        real(8), parameter :: SW_renters_spend_over_X_on_hous_2=0.497
        real(8), parameter :: SCF_mortgage_to_gross_housing_wealth=0.345
        real(8), parameter :: fraction_itemizing_MIDs_data=0.07467241172     
