    contains

        ! THE INDEX MAP. Employment, mental illness and the SUD are folded into
        ! one index, and these four functions are the only place that folding is
        ! known. Every fine grained test that used to compare the index against a
        ! threshold goes through them, so growing the grid does not mean auditing
        ! a hundred and fifty hand written comparisons.
        integer function emp_of(i_1)
            implicit none
            integer, intent(in) :: i_1
            emp_of=mod(i_1-1,3)+1
        end function

        integer function smi_of(i_1)
            implicit none
            integer, intent(in) :: i_1
            smi_of=mod((i_1-1)/3,number_of_smi_states)
        end function

        ! SNAP IN ONE PLACE, BECAUSE IT WAS WRITTEN OUT EIGHT TIMES.
        !
        ! Eight call sites carried this formula and they did not agree: the one
        ! in the labour supply block omitted food_stamp_taper altogether and so
        ! withdrew the benefit at a hundred cents on the dollar instead of
        ! thirty. That is the same fault as three others found today, a formula
        ! duplicated until one copy drifts, and a function is the only fix that
        ! stays fixed.
        !
        ! THE PROGRAMME, FY2023. The maximum allotment scales with household
        ! size on SNAP's own concave schedule; a household is eligible only if
        ! GROSS income is at or below 130 per cent of the poverty line for its
        ! size; and the benefit is the allotment less thirty cents per dollar of
        ! NET income, where net is gross after the twenty per cent earned income
        ! deduction and the standard deduction. Charging the taper on gross, as
        ! the old code did, overstates the withdrawal for every working
        ! household.
        real(8) function snap_benefit(hh_size_1,gross_income_1,avg_labour_1)

            implicit none

            real(8), intent(in) :: hh_size_1,gross_income_1,avg_labour_1
            real(8) :: scale_1,limit_1,net_1,weight_1
            integer :: n_lo_1,n_hi_1

            ! Household size is a real in this model and the schedule is defined
            ! on integers, so interpolate rather than truncate: truncating would
            ! pay a household of 2.9 the two person allotment.
            ! REVERTED TO THE CALIBRATED FLOOR, ON THE AUTHOR'S INSTRUCTION.
            ! The statutory schedule was correct per household and wrong in
            ! aggregate: it spent 20.4 per cent of labour income against 0.42
            ! in the data, a factor of 48, because far more households in this
            ! model fall under a realistic eligibility limit than in the world.
            ! An aggregate that far out is not a detail of the transfer, it is
            ! a different economy. So the programme is a single allotment
            ! max_food_cost less the statutory taper on income, and
            ! max_food_cost is calibrated on aggregate spending over labour
            ! income again.
            !
            ! hh_size_1 and avg_labour_1 are unused now and kept only so the
            ! nine call sites do not change.
            scale_1=hh_size_1
            limit_1=avg_labour_1
            net_1=max(0.d0,gross_income_1)
            weight_1=0

            snap_benefit=max(0.d0,max_food_cost-food_stamp_taper*net_1)

        end function

        integer function sud_of(i_1)
            implicit none
            integer, intent(in) :: i_1
            sud_of=(i_1-1)/(3*number_of_smi_states)
        end function

        ! WHAT A WORKING AGE HOUSEHOLD OUT OF WORK RECEIVES, IN ONE PLACE.
        !
        ! eq:fincome gives UI in the first period of a spell and DI thereafter
        ! to a household carrying SMI, and nothing otherwise. This was written
        ! out at four sites: the household's own income and three statistics
        ! that have to agree with it. They did not -- the statistics kept the
        ! old UI base after the income was corrected would have been the next
        ! drift, and one of them multiplied the mass with a plus sign. A single
        ! function is the only way the four cannot disagree again.
        !
        ! The note's e=2, the insured period, is emp_of 3 here; the note's e=3,
        ! non-employment after it, is emp_of 2.
        real(8) function out_of_work_income(unemployment_index_1,employment_index_1,avg_income_1)

            implicit none

            integer, intent(in) :: unemployment_index_1,employment_index_1
            real(8), intent(in) :: avg_income_1
            real(8) :: base_1

            out_of_work_income=0

            base_1=employment_grid(age_index,employment_index_1)*&
                labour_deterministic_efficiency(age_index)

            if (emp_of(unemployment_index_1)==3) then

                ! psi * min{y eps(j), ybar}: the rate multiplies the capped base.
                out_of_work_income=replacement_rate_ui*&
                    min(base_1,max_ui_as_perc_of_avg_inc*avg_income_1)

            elseif ((emp_of(unemployment_index_1)==2) .AND. &
                (smi_of(unemployment_index_1)>=1)) then

                out_of_work_income=zeta_DI*base_1

            end if

        end function


        subroutine check_one(name_1,value_1,want_1,tol_1,fail_count_1)

            ! One invariant: a quantity that must equal want_1.

            implicit none

            character(len=*), intent(in) :: name_1
            real(8), intent(in) :: value_1,want_1,tol_1
            integer, intent(inout) :: fail_count_1

            if (abs(value_1-want_1)<=tol_1) then

                write(*,'(A,A48,A,F16.10)') " INVARIANT PASS  ",name_1,"  = ",value_1

            else

                write(*,'(A,A48,A,F16.10,A,F8.4)') " INVARIANT FAIL  ",name_1,&
                    "  = ",value_1,"   want ",want_1
                fail_count_1=fail_count_1+1

            end if

        end subroutine

        subroutine check_range(name_1,value_1,fail_count_1)

            ! One invariant: a share, which must lie in the unit interval.

            implicit none

            character(len=*), intent(in) :: name_1
            real(8), intent(in) :: value_1
            integer, intent(inout) :: fail_count_1

            if ((value_1>=0.d0) .AND. (value_1<=1.d0)) then

                write(*,'(A,A48,A,F16.10)') " INVARIANT PASS  ",name_1,"  = ",value_1

            else

                write(*,'(A,A48,A,F16.10,A)') " INVARIANT FAIL  ",name_1,&
                    "  = ",value_1,"   outside [0,1]"
                fail_count_1=fail_count_1+1

            end if

        end subroutine

        subroutine print_all_moments()

            ! EVERY TARGETED MOMENT, ON EVERY PASS, BESIDE ITS TARGET.
            !
            ! A sweep point writes its row and STOPS, above almost all of the
            ! moment prints, and several moments are computed only inside the
            ! parameter update block, which a sweep skips entirely. Between them
            ! that left a sweep reporting six numbers out of twenty two, and the
            ! missing ones were fixed one at a time as the author asked for each:
            ! the drug spending share, then the value of life, then wealth over
            ! output. That is the wrong way round. This prints the lot.
            !
            ! The two child ratios and the drug share are recomputed here rather
            ! than read, because the variables that hold them are only assigned
            ! in the update block. They are functions of aggregates the
            ! distribution pass has already built, so they cost nothing.

            implicit none

            integer :: diag_age_1,diag_fail_1

            real(8) :: w2o_1,vsl_1,csud_n_1,csud_d_1,chom_n_1,chom_d_1
            ! The counterfactual overwrites model_total_drug_users, so the
            ! denominator of the gap has to be held before it runs.
            real(8) :: baseline_users_for_gap
            integer :: k_1
            ! THE VALIDATION BLOCK'S OWN SCRATCH. HUD's five band rates and
            ! five band shares are written here rather than as parameters
            ! because they belong to the one block that reads them.
            real(8) :: val_all_homeless_1,val_all_mass_1,val_cum_1
            real(8) :: val_earn_total_1,val_earn_bottom_1,val_earn_top_1
            real(8), dimension(5) :: val_hud_rate_1=(/0.003161d0,0.003378d0,&
                0.002912d0,0.002496d0,0.000770d0/)
            real(8), dimension(5) :: val_hud_share_1=(/0.260d0,0.272d0,&
                0.210d0,0.184d0,0.075d0/)

            w2o_1=model_total_net_wealth(1)/max(model_GDP_incl_imput_rent(1),10.d0**(-12))
            vsl_1=model_value_of_life(1)/max(model_average_labour_income(1),10.d0**(-12))

            ! ALEPH'S TWO INGREDIENTS, PRINTED, BECAUSE THE MOMENT HAS SWUNG BY A
            ! FACTOR OF FORTY-FIVE ACROSS BUILDS AND NOBODY CAN SEE WHY.
            !
            ! It has read 58 at one discount-factor type, 119 and 121 at two, 5.06
            ! after a normalisation was reverted, and 2.61 now, against a target of
            ! 80. A parameter that needs moving does not do that; a construction
            ! that keeps changing does.
            !
            ! The denominator is the one to watch. model_average_labour_income is
            ! a SUM over workers divided by model_total_workers, and the treatment
            ! price line implies it should be near 0.6 while the food-stamp lines
            ! in the same point imply 10.2 -- a factor of seventeen, which is
            ! about the number of workers. That is either the division not
            ! happening or the two lines meaning different things, and one
            ! printed pair settles it.
            !
            ! model_value_of_life is a mass-weighted SUM of V over the marginal
            ! utility of consumption, already divided by the ratio of pooled mass
            ! to the first type's, so it is on a one-type footing. Its own mass is
            ! printed beside it so the reader can form the per-household figure
            ! and see whether the target of 80 was set against the aggregate or
            ! the mean.
            write(*,*) "DIAG aleph numerator, model_value_of_life        =",&
                model_value_of_life(1)
            write(*,*) "DIAG aleph denominator, avg labour income        =",&
                model_average_labour_income(1)
            write(*,*) "DIAG   workers behind that average               =",&
                model_total_workers(1)
            write(*,*) "DIAG   implied TOTAL labour income               =",&
                model_average_labour_income(1)*model_total_workers(1)
            write(*,*) "DIAG   value of life per household               =",&
                model_value_of_life(1)/max(pooled_mass_all,10.d0**(-12))

            csud_n_1=0
            csud_d_1=0
            chom_n_1=0
            chom_d_1=0
            ! THE CHILD'S DRAW IS CONDITIONAL ON THE PARENT'S NODE NOW, so
            ! these two ratios need the marginal over parent nodes WITHIN each
            ! parent state rather than a single row. Weighting by
            ! newborn_parent_share renormalised inside the cell is what makes
            ! the numerator and denominator comparable: the disordered and the
            ! clean sit at different nodes, and it is precisely that difference
            ! -- income persistence -- that used to be missing and that these
            ! ratios are now meant to split from the direct penalty.
            !
            ! The literature says the split is roughly even: adjusting for
            ! parental education, income, social class and family type removes
            ! about half the effect of parental substance abuse on offspring
            ! outcomes. So delta_d should fall to something like half the work
            ! it was doing once rho carries the other half, and if it collapses
            ! to nothing then rho is doing too much.
            do cd_index_1=0,1
                do ch_index_1=1,2
                    csud_w_1(cd_index_1,ch_index_1)=&
                        sum(newborn_parent_share(:,cd_index_1,ch_index_1))
                end do
            end do
            do k_1=1,employment_grid_size
                do cp_index_1=1,employment_grid_size
                    csud_n_1=csud_n_1+newborn_parent_share(cp_index_1,1,1)*&
                        newborn_employment_probability(k_1,cp_index_1,1,1)*&
                        percent_addicted_by_employment(1,k_1)/max(csud_w_1(1,1),10.d0**(-14))
                    csud_d_1=csud_d_1+newborn_parent_share(cp_index_1,0,1)*&
                        newborn_employment_probability(k_1,cp_index_1,0,1)*&
                        percent_addicted_by_employment(1,k_1)/max(csud_w_1(0,1),10.d0**(-14))
                    chom_n_1=chom_n_1+newborn_parent_share(cp_index_1,0,2)*&
                        newborn_employment_probability(k_1,cp_index_1,0,2)*&
                        percent_homeless_by_employment(1,k_1)/max(csud_w_1(0,2),10.d0**(-14))
                    chom_d_1=chom_d_1+newborn_parent_share(cp_index_1,0,1)*&
                        newborn_employment_probability(k_1,cp_index_1,0,1)*&
                        percent_homeless_by_employment(1,k_1)/max(csud_w_1(0,1),10.d0**(-14))
                end do
            end do

            write(*,*) "===== ALL TARGETED MOMENTS ====="
            ! SIGMA_Y IS SCORED ON INCOME, NOT ON PRODUCTIVITY, from 3
            ! September. The author: *"yes please target the bottom share of
            ! income (not share of productivity but share of income after you
            ! account for the labor supply....)"*.
            !
            ! The old number came from employment_grid and its masses -- a
            ! statistic about the GRID, with no labour supply in it, no age
            ! efficiency profile and no distribution. Two households on the same
            ! productivity node with different hours counted identically. This
            ! one is the same walk the bottom 1, 5 and 10 per cent already use,
            ! taken at the median, over the model's own income histogram.
            !
            ! The productivity version is kept as a DIAG rather than deleted: it
            ! is what the whole archive before today was scored on, and the two
            ! side by side say how much of the dispersion is hours rather than
            ! wages.
            write(*,*) "MOMENT sigma_y   bottom half labour income share model=",&
                model_bottom_half_labour_income_share, " target=", bottom_half_earnings_share_data
            write(*,*) "DIAG bottom half PRODUCTIVITY share (the old sigma_y) =",&
                model_bottom_half_earnings_share
            write(*,*) "DIAG bottom half share of TOTAL income, all ages      =",&
                model_bottom_half_income_share(1)
            write(*,*) "MOMENT tau_l     average labour income tax   model=",&
                model_average_labour_income_tax(1), " target=", average_labor_income_tax_data
            write(*,*) "MOMENT omega_l   labour supply / total hours model=",&
                model_labor_supply(1)/max(model_total_hours(1),10.d0**(-12)),&
                " target=", avg_labor_supply_data
            write(*,*) "MOMENT beta      wealth over output          model=",&
                w2o_1, " target=", wealth_to_output_data
            ! h_2 IS ON TOTAL SPENDING, NOT ON INCOME, AND SO IS gamma BELOW.
            !
            ! The two housing moments were on different denominators. gamma's
            ! 26.8 per cent is CEX shelter and utilities over TOTAL EXPENDITURE
            ! and the 10.1 per cent beside it is the share of households paying
            ! more than half of TOTAL EXPENDITURE on housing, from the same
            ! survey. Both were being compared with income based objects, and
            ! the income and expenditure versions are not close: a household at
            ! the bottom spends more than it earns, so its housing over income
            ! is large exactly where its housing over expenditure is not, and
            ! that household is the one the headcount is made of.
            !
            ! Both objects now use the CEX denominator. The income versions are
            ! kept below as UNTARGETED rows, because the 40.6 and 17.5 per cent
            ! in the appendix are on income and are worth carrying.
            write(*,*) "MOMENT h_2       above half of spending      model=",&
                val_burden50_expend_all(1)/max(val_mass_expend_all(1),10.d0**(-14)),&
                " target=", severe_cost_burden_data
            write(*,*) "MOMENT h_3       share in the largest unit   model=",&
                model_housing_size_dist(1,housing_status_grid_size-1),&
                " target=", housing_size_dist_data(2)
            ! The smallest unit's share is kept as a DIAGNOSTIC rather than a
            ! target, because the grid it describes is still the object the
            ! instrument moves and a reader needs it alongside.
            ! WHICH ASSET GRID THIS POINT WAS SOLVED ON. Changing the grid
            ! changes every moment, so a point measured on one grid cannot be
            ! bracketed against a point measured on another -- and nothing in the
            ! vector, the tag or the file said which. It does now.
            do k_1=second_lowest_housing_grid_point,housing_status_grid_size-1
                write(*,*) "DIAG unit", k_1, " share of renters=",&
                    val_mass_by_unit(1,k_1)/max(mass_of_renters_at_housing_spending(1,1)*0+&
                    sum(val_mass_by_unit(1,second_lowest_housing_grid_point:)),10.d0**(-14)),&
                    " of whom over half of income=",&
                    val_burden50_by_unit(1,k_1)/max(val_mass_by_unit(1,k_1),10.d0**(-14))
            end do
            ! AGGREGATE RENT OVER AGGREGATE INCOME, which is NOT what gamma
            ! measures. gamma is model_avg_housing_spending_renters, a mass
            ! weighted mean of household RATIOS, and a mean of ratios is not the
            ! ratio of the means whenever the two are correlated -- which here
            ! they are, since the burden is concentrated in the low income tail.
            ! A data figure built as total rent over total income has to be
            ! compared with this line and not with gamma.
            !
            ! aggregate_rent_spending is GROSS rent, before housing vouchers, and
            ! covers housed renters only, so the homeless contribute nothing to
            ! the numerator and their income is still in the denominator.
            write(*,*) "DIAG aggregate rent / aggregate income           =",&
                aggregate_rent_spending(1)/max(model_total_income(1),10.d0**(-14))

            ! THE CEX DENOMINATOR. 26.8 per cent is shelter and utilities over
            ! TOTAL EXPENDITURE, so this line, not gamma's, is its analogue; and
            ! the two headcounts beside it are the share of households paying
            ! more than half of expenditure on housing, which is the object the
            ! smallest rung is to be calibrated on. CEX's own income based
            ! figure for the same numerator is 20.2 per cent, against the 26.8
            ! on expenditure, so a gap between this line and gamma's is expected
            ! and its size is the thing to read.
            write(*,*) "DIAG aggregate housing / aggregate expenditure   =",&
                val_hous_expend_num(1)/max(val_hous_expend_den(1),10.d0**(-14))
            write(*,*) "DIAG over half of EXPENDITURE, all households    =",&
                val_burden50_expend_all(1)/max(val_mass_expend_all(1),10.d0**(-14))
            write(*,*) "DIAG over half of EXPENDITURE, housed only       =",&
                val_burden50_expend_housed(1)/max(val_mass_expend_housed(1),10.d0**(-14))

            ! WHERE THE DRUG USERS ARE IN THE LIFE CYCLE, and the line that
            ! decides whether the income of users is a selection problem or a
            ! composition one. Data shares among users aged 26 and over, from
            ! data/drug_use_age_distribution.xlsx, are given beside each band.
            write(*,*) "UNTARGETED mean age of drug users            model=",&
                val_user_age_num(1)/max(val_user_mass_age(1),10.d0**(-14)),&
                " observed=", 45.48d0
            write(*,*) "UNTARGETED users aged 26-34, share           model=",&
                val_user_band(1,1)/max(val_user_mass_age(1),10.d0**(-14)), " observed=", 0.28404d0
            write(*,*) "UNTARGETED users aged 35-44, share           model=",&
                val_user_band(1,2)/max(val_user_mass_age(1),10.d0**(-14)), " observed=", 0.25054d0
            write(*,*) "UNTARGETED users aged 45-54, share           model=",&
                val_user_band(1,3)/max(val_user_mass_age(1),10.d0**(-14)), " observed=", 0.17768d0
            write(*,*) "UNTARGETED users aged 55-64, share           model=",&
                val_user_band(1,4)/max(val_user_mass_age(1),10.d0**(-14)), " observed=", 0.16327d0
            write(*,*) "UNTARGETED users aged 65 plus, share         model=",&
                val_user_band(1,5)/max(val_user_mass_age(1),10.d0**(-14)), " observed=", 0.12445d0
            write(*,*) "DIAG income of WORKING AGE drug users / average   =",&
                (val_user_income_working(1)/max(val_user_mass_working(1),10.d0**(-14)))/&
                max(model_average_income(1),10.d0**(-14))
            write(*,*) "DIAG working age share of drug users             =",&
                val_user_mass_working(1)/max(val_user_mass_age(1),10.d0**(-14))

            ! WHO THE OLD USERS ARE. Two in five users are 65 or over, and the
            ! three columns here say whether that is a lot of retirees using a
            ! little or a few using heavily, whether they carry the disorder or
            ! merely buy, and what they live on. val_mass_band is the population
            ! in the same five bands, built for the homelessness profile, so the
            ! rate is a ratio of two masses over identical age cuts.
            do k_1=1,5
                write(*,*) "DIAG users band", k_1, " use rate=",&
                    val_user_band(1,k_1)/max(val_mass_band(1,k_1),10.d0**(-14)),&
                    " share with the disorder=",&
                    val_user_sud_band(1,k_1)/max(val_user_band(1,k_1),10.d0**(-14)),&
                    " income/average=",&
                    (val_user_inc_band(1,k_1)/max(val_user_band(1,k_1),10.d0**(-14)))/&
                    max(model_average_income(1),10.d0**(-14))
            end do

            ! DOES THE STONE GEARY THRESHOLD HOLD IN THE SOLVED MODEL?
            ! The split buys nothing unless C > (phi/theta) p b, so a buyer must
            ! have MORE total consumption resources than a non buyer, by
            ! construction. If these two come out the other way round the
            ! closed form and the distribution disagree and one of them is wrong.
            write(*,*) "DIAG drug threshold, (phi/theta)*p*b            =",&
                (relative_share_of_consumption_1/max(relative_share_of_addiction_1,10.d0**(-14)))*&
                price_of_addictive_good*addiction_scalar_1
            write(*,*) "DIAG buyers: mean C                             =",&
                val_buy_C(1)/max(val_buy_mass(1),10.d0**(-14))
            write(*,*) "DIAG non-buyers: mean C                         =",&
                val_nobuy_C(1)/max(val_nobuy_mass(1),10.d0**(-14))
            write(*,*) "DIAG buyers: mean income                        =",&
                val_buy_income(1)/max(val_buy_mass(1),10.d0**(-14))
            write(*,*) "DIAG non-buyers: mean income                    =",&
                val_nobuy_income(1)/max(val_nobuy_mass(1),10.d0**(-14))
            write(*,*) "DIAG buyers as a share of clean households      =",&
                val_buy_mass(1)/max(val_buy_mass(1)+val_nobuy_mass(1),10.d0**(-14))

            ! IS THERE A BUFFER BEHIND THE LOW INCOME? The author's reading is
            ! that a household willing to risk the disorder is one with
            ! something to fall back on -- rich parents in the data, wealth in
            ! this model, since the model has no ongoing transfer from a parent
            ! to an adult child and the endowment at age 26 is the whole of it.
            ! The Stone Geary threshold is on total resources for consumption,
            ! which include drawing wealth down, so a household with low income
            ! and real assets is exactly the one the algebra says should buy.
            ! These three were computed and never printed, so nobody could see
            ! whether it does.
            write(*,*) "DIAG assets of drug users / average net worth    =",&
                model_average_assets_drug_users(1)/max(model_average_net_wealth(1),10.d0**(-14))
            write(*,*) "DIAG assets of experimenters / average net worth =",&
                model_avg_assets_experimenters(1)/max(model_average_net_wealth(1),10.d0**(-14))
            write(*,*) "DIAG assets with a SUD / average net worth       =",&
                model_average_assets_addicted(1)/max(model_average_net_wealth(1),10.d0**(-14))

            ! IS A PERIOD OF LIFE WORTH ANYTHING TO THE POOREST? aleph is added
            ! to a CRRA goods term that is negative and unbounded below, so the
            ! value of being alive falls with consumption. If any mass sits
            ! below zero, those households prefer not to be alive and an
            ! eightfold mortality multiplier is a benefit to them rather than a
            ! cost -- which would make the selection into drug use a defect and
            ! not a mechanism.
            ! AS A SHARE, WHICH IS WHAT THE NOTE ABOVE ASKS. val_neg_life_mass
            ! accumulates distribution_mass_used, so it is a mass on a pooled
            ! population near 95, and printed raw it reads 0.303 where the
            ! question is whether that is thirty per cent or a third of one per
            ! cent. It is the latter. The raw mass is kept beside it so the
            ! divisor is auditable, exactly as the food stamp line below does.
            write(*,*) "DIAG share with a NEGATIVE value of life         =",&
                val_neg_life_mass(1)/max(pooled_mass_all,10.d0**(-12)),&
                " raw mass=", val_neg_life_mass(1), " of ", pooled_mass_all
            write(*,*) "DIAG lowest value of a period of life            =",&
                val_life_min(1)
            write(*,*) "DIAG value of life, drug users                   =",&
                val_ugoods_users(1)/max(val_umass_users(1),10.d0**(-14))
            write(*,*) "DIAG value of life, everyone else                =",&
                val_ugoods_others(1)/max(val_umass_others(1),10.d0**(-14))
            write(*,*) "DIAG aleph itself, for scale                     =", value_of_life

            ! THE PRICE OF TREATMENT AGAINST WHAT IT COSTS IN REALITY.
            ! Outpatient runs 3,000 to 5,700 dollars a year and residential
            ! 16,000 to 21,900, against mean household wage income of 88,212,
            ! so 3.4 to 6.5 per cent of average labour income ambulatory and 18
            ! to 25 residential. TEDS-A admissions are overwhelmingly
            ! ambulatory, so the first range is the one to read this against.
            write(*,*) "DIAG treatment price / average labour income     =",&
                money_cost_of_treatment/max(model_average_labour_income(1),10.d0**(-14)),&
                " data outpatient=", 0.034d0, " to", 0.065d0

            ! WHO ACTUALLY GETS FOOD STAMPS, which the cbar moment cannot say.
            ! cbar targets AGGREGATE spending over labour income, and an
            ! aggregate can be hit with a tiny benefit paid to a great many
            ! households or a proper one paid to few. The floor the poorest
            ! household consumes against is the SECOND of those, and it is what
            ! bounds the CRRA goods term from below.
            !
            ! In the data 12.5 per cent of households received SNAP in 2023, the
            ! maximum allotment for one person was 291 dollars a month against
            ! mean household wage income of 88,212, so 3.96 per cent of it, and
            ! eligibility ran to 130 per cent of the poverty line, about 20 per
            ! cent of average labour income. The model's maximum is
            ! max_food_cost itself, since the consumption tax is zero, and its
            ! cutoff is max_food_cost/0.30.
            ! A SHARE, NOT A MASS. model_fraction_recieving_food_stamps is
            ! accumulated as a mass and is divided by the distribution only at
            ! the two file-writing sites, so this line printed 1.55 against a
            ! data figure of 0.125 and read as a moment missing by a factor of
            ! twelve. It is the mass on a population of about 51, not a share.
            write(*,*) "DIAG households receiving food stamps            =",&
                model_fraction_recieving_food_stamps(1)/max(pooled_mass_all,10.d0**(-12)),&
                " data=", 0.125d0
            ! BOTH OF THESE COMPARED A LEVEL AGAINST A RATIO. max_food_cost is
            ! in the model's consumption units and the figures beside it are
            ! fractions of mean wage income -- 291 dollars a month over 88,212,
            ! and the 130 per cent of poverty cutoff over the same. The
            ! comparison is only valid if average labour income is one, and it is
            ! about 0.6, so the allotment read five times too small when the
            ! ratio says about three. Divide, and they measure what they say.
            write(*,*) "DIAG max allotment / avg labour income           =",&
                max_food_cost/max(model_average_labour_income(1),10.d0**(-12)),&
                " data=", 0.039586d0
            write(*,*) "DIAG gross eligibility cutoff                     =",&
                (max_food_cost/food_stamp_taper)/&
                max(model_average_labour_income(1),10.d0**(-12)), " data=", 0.214872d0
            write(*,*) "DIAG aggregate rent / output                     =",&
                aggregate_rent_spending(1)/max(model_output(1),10.d0**(-14))
            write(*,*) "DIAG asset grid, reachable points                =",&
                real(positive_financial_grid_size+1,8)
            write(*,*) "DIAG share in the smallest unit                  =",&
                model_housing_size_dist(1,0)
            ! gamma ON THE DENOMINATOR ITS TARGET IS MEASURED ON. 26.8 per cent
            ! is a ratio of MEANS over total expenditure; the old object was a
            ! mass weighted mean of household rent over INCOME ratios, which is
            ! neither the same denominator nor the same kind of average. CEX's
            ! income based figure for the same numerator is 20.2 per cent, so
            ! the old pairing aimed the target about a third high.
            ! BACK TO THE EXPENDITURE DENOMINATOR, on the author's instruction of
            ! 1 September: "maybe we should still have gamma targeted to the
            ! portion households spend on housing out of their expenditures,
            ! which is 26.8%".
            !
            ! TWO REASONS, and the second only became visible tonight.
            !
            ! The theory one was recorded when the denominator was changed and
            ! set aside rather than answered: a Cobb-Douglas weight equals the
            ! EXPENDITURE share exactly, and income and expenditure differ by
            ! saving, so an income denominator asks gamma to equal something it
            ! is not.
            !
            ! The arithmetic one is new. The author wants the cheapest rung near
            ! 0.165, which is 25.9 per cent of average labour income, so every
            ! HOUSED household spends at least that share of income on rent. An
            ! income-denominated target of 0.202 is then below the floor the
            ! ladder itself imposes and is unreachable by construction. 0.268 is
            ! not.
            !
            ! CHANGING THE CONSTANT ALONE WOULD REINTRODUCE THE FAULT THIS
            ! REPLACED. 26.8 is a ratio over EXPENDITURE and
            ! model_avg_housing_spending_renters is housing over INCOME, so the
            ! object moves with the target. The income ratio stays below as an
            ! UNTARGETED row against its own 0.202 so nothing is lost.
            write(*,*) "MOMENT gamma     housing over expenditure    model=",&
                val_hous_expend_num(1)/max(val_hous_expend_den(1),10.d0**(-14)),&
                " target=", avg_rent_to_income_data
            write(*,*) "UNTARGETED housing over income, renters      model=",&
                model_avg_housing_spending_renters(1), " observed=", 0.202d0
            write(*,*) "MOMENT h_1       homelessness rate           model=",&
                model_fraction_homeless(1), " target=", fraction_homeless_data
            write(*,*) "MOMENT b         total drug users            model=",&
                model_total_drug_users(1), " target=", participation_rate_data
            write(*,*) "MOMENT lambda_d  disorder rate               model=",&
                model_fraction_addicted(1), " target=", sud_rate_data
            write(*,*) "MOMENT theta     drug spending share         model=",&
                weighted_drug_share_now(), " target=", drug_spending_share_data
            write(*,*) "MOMENT aleph     value of life / income      model=",&
                vsl_1, " target=", vsl_data
            write(*,*) "MOMENT pi_eu     unemployment rate           model=",&
                model_fraction_unemployed(1), " target=", unemployment_rate_data
            write(*,*) "MOMENT kappa_ued unemployment given SUD      model=",&
                model_fraction_addicted_and_unemployed(1), " target=", unemployment_rate_sud_data
            write(*,*) "MOMENT kappa_uem employment given SMI        model=",&
                model_employment_rate_given_smi(1), " target=", employment_rate_given_smi_data
            write(*,*) "MOMENT p_m       SMI population share        model=",&
                model_smi_prevalence(1), " target=", model_smi_prevalence_target(1)
            write(*,*) "MOMENT lambda_m  SMI share of the homeless   model=",&
                model_smi_share_of_homeless(1), " target=", smi_share_of_homeless_data
            write(*,*) "MOMENT pi_V      eligibles with a voucher    model=",&
                model_eligibles_getting_voucher(1), " target=", voucher_coverage_data
            ! AGGREGATE FOOD STAMP SPENDING IS A CHECK NOW, NOT A TARGET.
            ! SNAP is implemented as the programme runs -- allotment by
            ! household size, gross income eligibility at 130 per cent of the
            ! poverty line, thirty cents per dollar of net income -- and every
            ! one of those is assigned from the statute rather than fitted. The
            ! author's instruction was to implement it and not worry about the
            ! total cost, and a parameter cannot be both assigned and
            ! calibrated. So this row reports what the programme costs rather
            ! than driving anything.
            ! AN AGGREGATE OVER AN AGGREGATE, WHICH IS WHAT THE TARGET IS.
            !
            ! The target is 0.42 per cent of INCOME spent on food stamps -- the
            ! author's own words, "food stamps calibrated to 0.42% of income".
            ! That is total spending over total income, and the model was
            ! dividing total spending by model_average_labour_income, which is a
            ! MEAN. The ratio therefore scaled with the size of the population
            ! rather than measuring a share of anything, and it printed 0.0532
            ! against 0.0042: a miss of 1166 per cent that was an artefact of the
            ! denominator, not a statement about the programme.
            !
            ! THE MAGNITUDE CHECK, which is what the aleph episode says to do
            ! before believing a normalisation. Three diagnostics disagree while
            ! the denominator is a mean and agree once it is a total. The maximum
            ! allotment is about three times too small against SNAP's 291 dollars
            ! over mean wage income; recipients are 3.8 per cent of households
            ! against 12.5 in the data; and on the aggregate form spending comes
            ! out BELOW target rather than twelve times above it. All three then
            ! say the same thing -- the programme is too small -- where the old
            ! form said spending was far too large while its own allotment and
            ! coverage were far too small, which cannot all be true.
            !
            ! THE DENOMINATOR IS GDP, WHICH IN THIS MODEL IS INCOME.
            !
            ! It was written as model_total_income for one commit and that was
            ! wrong twice over. model_total_income is output PLUS investment
            ! income PLUS bequests: the return on capital is already inside
            ! output, so adding it counts it a second time, and a bequest is a
            ! transfer of existing wealth rather than income at all. GDP is the
            ! income concept in a closed economy with no foreign sector, and
            ! model_GDP is set equal to model_output a few hundred lines above.
            !
            ! It also matches the target's construction: SNAP outlays near 113
            ! billion against a GDP near 27.7 trillion is 0.0041, and the target
            ! is 0.0042.
            !
            ! model_output is reset on the first pass and accumulated on every
            ! one, exactly as the numerator is, so both sides are pooled and the
            ! ratio does not move with the number of discount-factor types.
            write(*,*) "MOMENT cbar      food stamps / income        model=",&
                govt_spending_on_food_stamps(1)/max(model_output(1),10.d0**(-12)),&
                " target=", food_stamps_share_data

            ! THE COMPONENTS AND THE OLD FORM, so the change above is auditable
            ! from the point file rather than from this comment, and so the
            ! alternative denominators can be read off without another run.
            write(*,*) "DIAG food stamps, aggregate spending             =",&
                govt_spending_on_food_stamps(1)
            write(*,*) "DIAG output, the denominator above               =",&
                model_output(1), " total income, which is NOT used=",&
                model_total_income(1)
            write(*,*) "DIAG food stamps / average labour income (OLD)   =",&
                govt_spending_on_food_stamps(1)/max(model_average_labour_income(1),10.d0**(-12))
            write(*,*) "MOMENT tau_u     treatment take up           model=",&
                model_treatment_take_up(1), " target=", treatment_take_up_data
            write(*,*) "MOMENT mu_H      recovery housed / homeless  model=",&
                model_recovery_housed(1)/max(model_recovery_homeless(1),10.d0**(-12)),&
                " target=", milby_recovery_ratio_data
            ! UNTARGETED, NOT MOMENT. Both penalties are set from the earnings
            ! literature now rather than calibrated to these ratios, because the
            ! ratios are not reachable through an income channel at any earnings
            ! penalty the evidence supports. They are reported so the paper can
            ! say how much of the intergenerational correlation income carries,
            ! and the prefix keeps them out of the loss: score_points reads
            ! MOMENT lines.
            write(*,*) "UNTARGETED delta_d child SUD ratio           model=",&
                csud_n_1/max(csud_d_1,10.d0**(-12)), " observed=", child_sud_ratio_data
            ! THE BOTTOM OF BOTH DISTRIBUTIONS, UNTARGETED. SCF 2022, households
            ! aged 26 to 65, the universe the paper already uses for wealth.
            ! The observed net worth shares are NEGATIVE at all three, which is
            ! the thing the bottom half share could not show: it is the only
            ! percentile where the data is still positive, so reporting it alone
            ! made a sign error look like a level error.
            write(*,*) "UNTARGETED wealth share bottom  1 pct        model=",&
                model_wealth_share_below(1,1), " observed=", -0.00225d0
            write(*,*) "UNTARGETED wealth share bottom  5 pct        model=",&
                model_wealth_share_below(2,1), " observed=", -0.00422d0
            write(*,*) "UNTARGETED wealth share bottom 10 pct        model=",&
                model_wealth_share_below(3,1), " observed=", -0.00446d0
            write(*,*) "UNTARGETED income share bottom  1 pct        model=",&
                model_income_share_below(1,1), " observed=", 0.00009d0
            write(*,*) "UNTARGETED income share bottom  5 pct        model=",&
                model_income_share_below(2,1), " observed=", 0.00288d0
            write(*,*) "UNTARGETED income share bottom 10 pct        model=",&
                model_income_share_below(3,1), " observed=", 0.00924d0
            write(*,*) "DIAG income histogram mass / distribution (want 1.0) =",&
                income_hist_mass_check

            ! THE INCOME TILT OF THE DISORDER, band for band against NSDUH.
            !
            ! The bands are NSDUH's own, matched on POPULATION SHARE rather than
            ! on dollars: 13.7 per cent of adults 26 and over are in its lowest
            ! income band, then 14.4, 11.0, 10.5, 9.5, 14.9 and 25.9. Walking
            ! the model's income histogram to the same cumulative shares gives
            ! seven groups that are comparable without needing the two surveys'
            ! income denominators to agree.
            !
            ! The observed rates are 0.1365, 0.1308, 0.0911, 0.1020, 0.0786,
            ! 0.0717 and 0.0482, a ratio of 2.83 from bottom to top. That is the
            ! shape to reproduce. A model that concentrates its disorder in one
            ! narrow band will show a spike here however well it matches the
            ! overall rate, and no parameter that moves where the spike sits
            ! will lift the income of users.
            val_cum_1=0
            k_1=1
            val_earn_bottom_1=0
            val_earn_total_1=0
            do i=1,income_bins
                val_cum_1=val_cum_1+income_hist_mass(i)/max(sum(income_hist_mass),10.d0**(-14))
                val_earn_bottom_1=val_earn_bottom_1+income_hist_sud(i)
                val_earn_total_1=val_earn_total_1+income_hist_mass(i)
                if ((val_cum_1>=nsduh_band_cum(k_1)) .OR. (i==income_bins)) then
                    write(*,*) "DIAG SUD rate, income band", k_1, " model=",&
                        val_earn_bottom_1/max(val_earn_total_1,10.d0**(-14)),&
                        " data=", nsduh_band_rate(k_1)
                    val_earn_bottom_1=0
                    val_earn_total_1=0

                    ! EXIT ONCE THE TOP BAND HAS BEEN REPORTED. k_1 was clamped
                    ! at 7, so once the cumulative mass passed the last NSDUH
                    ! cut the condition fired on EVERY remaining bin: band 7 was
                    ! printed 372 times in a real point, and every print after
                    ! the first is one bin's rate rather than the band's,
                    ! because the accumulators are reset just above. A reader
                    ! taking the last value got a single bin, not the band.
                    if (k_1==7) exit

                    k_1=k_1+1
                end if
            end do
            write(*,*) "UNTARGETED delta_h child homelessness ratio  model=",&
                chom_n_1/max(chom_d_1,10.d0**(-12)), " observed=", child_homeless_ratio_data

            ! ============================================================
            ! THE VALIDATION SECTION, tab:untargeted, WITH THE MODEL BESIDE
            ! THE DATA. Every row of that table has carried a data value and
            ! a source and no model number, which makes it a table of things
            ! the model is not asked to match and also is not checked on.
            ! The rows below are every one the benchmark can produce without
            ! a second solve; the two price elasticities need the drug price
            ! perturbed and re-solved, and returns to homelessness needs the
            ! distribution pushed forward two periods, so neither is here.
            ! ------------------------------------------------------------

            ! THE HOMELESSNESS PROFILE BY AGE. HUD publishes the age
            ! distribution for PEOPLE and h_1 is calibrated to a HOUSEHOLD
            ! rate, so the level differs by construction and the PROFILE is
            ! the check: each band's rate over the all band rate, against
            ! HUD's own 1.281, 1.369, 1.180, 1.011 and 0.312.
            val_all_homeless_1=sum(val_homeless_band(1,:))
            val_all_mass_1=sum(val_mass_band(1,:))
            write(*,*) "DIAG homelessness rate rebuilt from the bands    =",&
                val_all_homeless_1/max(val_all_mass_1,10.d0**(-14))
            do k_1=1,5
                write(*,*) "UNTARGETED homelessness rate, band", k_1, " model=",&
                    val_homeless_band(1,k_1)/max(val_mass_band(1,k_1),10.d0**(-14)),&
                    " observed=", val_hud_rate_1(k_1)
            end do
            do k_1=1,5
                write(*,*) "UNTARGETED homelessness profile, band", k_1, " model=",&
                    (val_homeless_band(1,k_1)/max(val_mass_band(1,k_1),10.d0**(-14)))/&
                    max(val_all_homeless_1/max(val_all_mass_1,10.d0**(-14)),10.d0**(-14)),&
                    " observed=", val_hud_rate_1(k_1)/0.002468d0
            end do
            ! THE OVERLAP, BAND BY BAND. If the disorder rate is near zero in
            ! the bands where the homeless are, the reversed association is
            ! composition and not a defect in the housing choice.
            do k_1=1,5
                write(*,*) "DIAG disorder rate, band", k_1, "                    =",&
                    val_sud_band(1,k_1)/max(val_mass_band(1,k_1),10.d0**(-14))
            end do
            do k_1=1,5
                write(*,*) "DIAG SUD share of the homeless, band", k_1, "        =",&
                    val_homeless_sud_band(1,k_1)/max(val_homeless_band(1,k_1),10.d0**(-14))
            end do

            do k_1=1,5
                write(*,*) "UNTARGETED share of the homeless, band", k_1, " model=",&
                    val_homeless_band(1,k_1)/max(val_all_homeless_1,10.d0**(-14)),&
                    " observed=", val_hud_share_1(k_1)
            end do

            ! THE TWO EARNINGS TENTHS, off the same productivity grid and the
            ! same ergodic weights sigma_y's bottom half share is read from,
            ! so the three are one computation and only the middle one is
            ! targeted. The node the cut falls inside is split at the cut,
            ! for the reason that computation gives.
            val_earn_total_1=0
            do k_1=1,employment_grid_size
                val_earn_total_1=val_earn_total_1+&
                    employment_grid(1,k_1)*unconditional_employment_probability(k_1)
            end do
            val_earn_bottom_1=0
            val_cum_1=0
            do k_1=1,employment_grid_size
                if ((val_cum_1+unconditional_employment_probability(k_1))<=0.1d0) then
                    val_earn_bottom_1=val_earn_bottom_1+&
                        employment_grid(1,k_1)*unconditional_employment_probability(k_1)
                    val_cum_1=val_cum_1+unconditional_employment_probability(k_1)
                else
                    val_earn_bottom_1=val_earn_bottom_1+employment_grid(1,k_1)*(0.1d0-val_cum_1)
                    exit
                end if
            end do
            val_earn_top_1=0
            val_cum_1=0
            do k_1=1,employment_grid_size
                if ((val_cum_1+unconditional_employment_probability(k_1))<=0.9d0) then
                    val_earn_top_1=val_earn_top_1+&
                        employment_grid(1,k_1)*unconditional_employment_probability(k_1)
                    val_cum_1=val_cum_1+unconditional_employment_probability(k_1)
                else
                    val_earn_top_1=val_earn_top_1+employment_grid(1,k_1)*(0.9d0-val_cum_1)
                    exit
                end if
            end do
            write(*,*) "UNTARGETED earnings share, bottom tenth      model=",&
                val_earn_bottom_1/max(val_earn_total_1,10.d0**(-14)), " observed=", 0.0099d0
            write(*,*) "UNTARGETED earnings share, top tenth         model=",&
                1.d0-val_earn_top_1/max(val_earn_total_1,10.d0**(-14)), " observed=", 0.411d0

            ! THE IMPATIENT TYPE'S BRACKET, set by the author. This was
            ! untargeted while there was one discount factor and nothing could
            ! move it; the impatient beta owns it now.
            write(*,*) "MOMENT w_bot     net worth share, bottom half model=",&
                model_bottom_half_wealth_share(1), " target=", bottom_half_wealth_share_data

            ! COST BURDEN AMONG RENTERS, at the same two cuts the model has
            ! been carrying all along and never read: 0.30 and 0.50 of
            ! income. The universe is renters, which is the SCF universe the
            ! appendix derives 40.6 and 17.5 on.
            write(*,*) "UNTARGETED renters above 30 pct of income    model=",&
                mass_of_renters_at_housing_spending(1,1), " observed=", 0.406d0
            ! SCORED FROM 5 September, on the author's instruction: *"is there a
            ! way to set h2 so that the share of spending over 50% of their income
            ! on housing is like in the data?"*. It was printed and never read.
            !
            ! NAMED burden50, NOT h_2. ENGINE.md records that conflating the h_2
            ! MOMENT (over half of EXPENDITURE, 0.101 in the CEX) with the h_2
            ! PARAMETER already cost a wrong concession once, and this is a third
            ! object on a third denominator. It gets its own name.
            !
            ! ITS INSTRUMENT IS THE BOTTOM RUNG. h2 sets what the cheapest unit
            ! costs, so it decides who is priced into paying over half their
            ! income for it; the top rung sets how much housing the bulk buy and
            ! owns gamma instead.
            ! COUNTED IN THE SMALLEST RENTAL ONLY, from 5 September. The author:
            ! *"h2 has to be a function of the fraction spending over 50% in the
            ! smallest rental, not overall"*, and *"those spending over 50% have
            ! to live in the smallest rental, not the largest"*.
            !
            ! WHY THE OVERALL COUNT MADE THE RULE INCOHERENT. Measured across
            ! fourteen ladder configurations, the overall figure sat at about 0.38
            ! and was generated almost entirely by h3 renters -- 40 per cent of
            ! them against 0.02 per cent of h2's. So the moment read ABOVE target
            ! and the rule said lower h2, while lowering h2 makes it cheaper and
            ! puts even fewer of its occupants over the line. The level said down
            ! and the placement said up.
            !
            ! Counted in h2 alone it reads about 0.0012 against 0.175, far BELOW
            ! target, and the author's own direction applies as they stated it:
            ! *"raise h2 if the share spending over 50% on housing is lower than
            ! the data (making sure they are the ones in h2)"*.
            !
            ! THE DENOMINATOR IS ALL RENTERS, not h2's occupants. The SCF's 0.175
            ! is a share of all renters, so hitting it requires BOTH that h2 holds
            ! enough households AND that they are genuinely stretched. A
            ! conditional share would need a target the data does not give.
            !
            ! The overall figure stays as an untargeted row directly below, so the
            ! burden can be watched migrating between the rungs.
            write(*,*) "MOMENT burden50  over half of income, in h2 model=",&
                val_burden50_by_unit(1,second_lowest_housing_grid_point)/&
                max(sum(val_mass_by_unit(1,second_lowest_housing_grid_point:)),10.d0**(-14)),&
                " target=", 0.175d0
            write(*,*) "UNTARGETED over half of income, all renters  model=",&
                mass_of_renters_at_housing_spending(1,2), " observed=", 0.175d0

            ! THE TWO PICTURE OF SUBSIDIZED HOUSEHOLDS ROWS. The tenant
            ! contribution rate is the check on kappa_r, which is set to
            ! 0.30 against HUD's 31.2 per cent, and it can come in UNDER
            ! 0.30 because a household whose rent is below kappa_r times its
            ! income draws no voucher and pays the rent.
            write(*,*) "UNTARGETED tenant contribution rate          model=",&
                val_voucher_rent(1)/max(val_voucher_income(1),10.d0**(-14)),&
                " observed=", 0.312d0
            write(*,*) "UNTARGETED voucher holders, wages main       model=",&
                val_voucher_wage_led(1)/max(val_voucher_mass(1),10.d0**(-14)),&
                " observed=", 0.28d0

            ! LABOUR FORCE PARTICIPATION. The pair is the row, not either
            ! half: NSDUH has participation HIGHER with a disorder, so a
            ! model that produces the penalty by pushing people out of the
            ! labour force fails this even with both levels close.
            write(*,*) "UNTARGETED participation, with a SUD         model=",&
                val_lfp_sud_num(1)/max(val_lfp_sud_den(1),10.d0**(-14)),&
                " observed=", 0.658d0
            write(*,*) "UNTARGETED participation, without a SUD      model=",&
                val_lfp_clean_num(1)/max(val_lfp_clean_den(1),10.d0**(-14)),&
                " observed=", 0.615d0
            ! THE SAME PAIR OVER WORKING AGE HOUSEHOLDS ONLY, which is not the
            ! data's universe and is kept because it measures something else
            ! worth knowing: if these are 1, the model has no extensive labour
            ! supply margin at all and the participation row above is carried
            ! entirely by the age composition of the two groups.
            write(*,*) "DIAG participation, with a SUD, working age      =",&
                val_lfp_sud_num(1)/max(val_lfp_sud_work_den(1),10.d0**(-14))
            ! HOUSEHOLDS WITH NO WAGE INCOME, which is the household level
            ! counterpart of non-participation and the unit this model is on.
            ! The participation rows above are scored against PERSON level
            ! rates, 0.615 and 0.658, while the model's income is calibrated to
            ! household wage income -- so they are not comparable and this row
            ! is. SCF 2022 puts it at 13.9 per cent of households aged 26 to 64
            ! and 29.5 per cent over 26 to 85.
            write(*,*) "DIAG households with no wage income, working age =",&
                val_nowage_working(1)/max(val_mass_working(1),10.d0**(-14)),&
                " data=", 0.1393d0
            write(*,*) "DIAG participation, without a SUD, working age   =",&
                val_lfp_clean_num(1)/max(val_lfp_clean_work_den(1),10.d0**(-14))

            ! THE THREE TEDS-A ROWS, all on the flow into treatment.
            write(*,*) "UNTARGETED homeless at treatment admission   model=",&
                val_treat_homeless(1)/max(val_treat_mass(1),10.d0**(-14)),&
                " observed=", 0.145d0
            write(*,*) "UNTARGETED SMI alongside SUD at admission    model=",&
                val_treat_smi(1)/max(val_treat_mass(1),10.d0**(-14)),&
                " observed=", 0.431d0
            write(*,*) "UNTARGETED working, homeless in treatment    model=",&
                val_treat_homeless_working(1)/max(val_treat_homeless(1),10.d0**(-14)),&
                " observed=", 0.066d0

            ! EMPLOYMENT AMONG THE HOMELESS. Computed as the complement of
            ! model_fraction_of_homeless_unemployed, working age on both sides,
            ! and written only to baseline_benchmark.txt -- so the only value
            ! anyone could read was from a file six months old, which said every
            ! working age homeless household was unemployed. Either that is a
            ! real property of the benchmark or the ratio is degenerate, and a
            ! number nobody can see from a point file cannot be told apart.
            ! The validation table already carries the TEDS-A row for working at
            ! all among the homeless IN TREATMENT, at 6.6 per cent, so this is
            ! the population that row is a subset of.
            write(*,*) "DIAG employed share of the homeless, working age =",&
                model_employed_share_of_homeless(1)
            write(*,*) "DIAG working age homeless mass                   =",&
                model_mass_homeless_working_age(1)

            ! THE OTHER DIRECTION OF THE SAME CONDITIONAL, which the model has
            ! always computed and never printed.
            !
            ! "employed share of the homeless" just above is P(employed |
            ! homeless) and answers what the homeless look like. This is
            ! P(homeless | unemployed) and answers whether unemployment is a
            ! route INTO homelessness, which is the question the policy is
            ! about. They are not interchangeable and the second cannot be
            ! recovered from the first without the working-age mass.
            !
            ! The ratio to the working-age homelessness rate is printed beside
            ! it because that is the unit-free version: how much more likely an
            ! unemployed household is to be on the street than a household
            ! drawn at random from the working-age population. One means
            ! unemployment carries no extra risk at all.
            write(*,*) "DIAG homelessness rate among the UNEMPLOYED      =",&
                model_fraction_of_unemployed_homeless(1)
            ! THE BASE HERE IS THE WORKING AGE HOMELESSNESS RATE, BUILT FROM
            ! THE TWO RAW MASSES, and NOT model_fraction_homeless. That moment
            ! is normalised on model_sum_of_lowest_productivities rather than on
            ! a population, so dividing by it would put two different
            ! denominators either side of the line and the ratio would not be a
            ! ratio of rates. model_mass_total_raw is the working age base --
            ! it is what model_fraction_unemployed is formed over -- and
            ! model_mass_homeless_working_age is the homeless part of it, so
            ! these two are the same population.
            write(*,*) "DIAG   ... over the working age homelessness rate=",&
                model_fraction_of_unemployed_homeless(1)/&
                max(model_mass_homeless_working_age(1)/&
                max(model_mass_total_raw(1),10.d0**(-14)),10.d0**(-14))

            ! THE SUD SHARE OF THE HOMELESS, the untargeted half of the same
            ! Gutwinski meta regression lambda_m is calibrated to.
            write(*,*) "UNTARGETED SUD share of the homeless         model=",&
                model_fraction_homeless_and_addicted(1), " observed=", 0.217d0

            ! DRUG POISONINGS AS A SHARE OF DEATHS AT 25 TO 44. The model
            ! has no cause of death; what it has is a survival probability
            ! that takes the disorder as an argument, so the deaths the
            ! disorder is responsible for are the ones that would not have
            ! happened at the clean hazard with age, homelessness and SMI
            ! held. Ages 26 to 44, because model age one is data age 26.
            ! THE PARAMETER THE ROW ABOVE AND THE TWO INCOME ROWS ALL TURN ON,
            ! printed beside them because it is now searchable and a point that
            ! does not record it cannot be read.
            write(*,*) "DIAG kappa_phi_d_level, SUD mortality level      =",&
                kappa_phi_d_level
            write(*,*) "UNTARGETED drug deaths, share of deaths      model=",&
                (val_deaths_all_young(1)-val_deaths_clean_young(1))/&
                max(val_deaths_all_young(1),10.d0**(-14)),&
                " observed=", 0.20d0

            write(*,*) "VALIDATION NOT COMPUTED: returns to homelessness within 24 months,",&
                " and the two drug price elasticities; each needs a second solve."
            ! ============================================================

            ! OMEGA_C'S MOMENT, AND WHY IT IS LAST.
            !
            ! It is the only targeted moment that is not a statistic of the
            ! solved equilibrium: it is the rise in use when the child term is
            ! switched off, so measuring it costs a SECOND value function solve
            ! and distribution convergence. Because a point run never entered
            ! the parameter update block, where the counterfactual used to live,
            ! omega_c was the one parameter in the search whose moment was never
            ! measured -- twenty three moments printed, twenty four parameters
            ! moved, and omega_c drifted with nothing pushing back. It sat at
            ! 0.5 for that reason alone.
            !
            ! THE COUNTERFACTUAL LEAVES ITS DISTRIBUTION BEHIND, which is why the
            ! old placement -- before the baseline -- contaminated every baseline
            ! statistic that followed it, a fault the code already recorded
            ! against this moment. Here it runs after the last of them, so the
            ! baseline is read clean and only the counterfactual carries the
            ! counterfactual's path. Nothing may be added below it.
            ! A DELIBERATE SKIP HAS TO BE DISTINGUISHABLE FROM A FAILED ONE.
            ! The counterfactual is a whole extra solve, converge and statistics
            ! pass -- about a third of a point's running time -- and while
            ! weight_on_child is pinned rather than searched, omega is not in the
            ! loss and paying for it every point buys nothing. But a point that
            ! simply LACKS the moment cannot be told from one measured before the
            ! counterfactual was fixed, which reported an exact zero, and those
            ! must stay out of the search. So the skip announces itself, inside
            ! the block run_one_point.sh keeps, and simplex.py reads that line.
            if (measure_child_gap==0) then

                write(*,*) "OMEGA SKIPPED    child counterfactual off by measure_child_gap"

            elseif ((include_child_in_continuation==1)&
                .AND. (model_total_drug_users(1)>&
                10.d0**(-1)*participation_rate_data)) then

                baseline_users_for_gap=model_total_drug_users(1)

                ! THE EVIDENCE HAS TO LAND INSIDE THIS BLOCK. run_one_point.sh
                ! keeps only the lines between ALL TARGETED MOMENTS and END OF
                ! MOMENTS, so anything printed elsewhere is discarded and a
                ! reader of the point file cannot tell a live counterfactual from
                ! a dead one. omega came back as exactly zero while b moved by a
                ! factor of 3.7 with omega_c, which cannot both be true, and
                ! there was no way to see which half was wrong.
                write(*,*) "OMEGA_DIAG baseline users=", baseline_users_for_gap,&
                    " child value=", expected_child_value

                child_penalty_off=1

                call solve_value_function_and_policy_functions(1)
                call converge_to_stationary_equilibrium(1)
                call stationary_equilibrium_statistics(1)

                ! model_total_drug_users IS BUILT IN govt_revenues_calc, NOT IN
                ! stationary_equilibrium_statistics. Both counterfactual blocks
                ! called only the latter, so the variable still held the BASELINE
                ! count when it was read back: the ratio was exactly one and
                ! omega came out as exactly 0.0000000000000000, at every value of
                ! omega_c, which is what a variable that was never updated looks
                ! like. The main path calls the two in this order, and so must
                ! anything that wants a fresh count.
                call govt_revenues_calc(1)

                drug_users_without_child=model_total_drug_users(1)

                write(*,*) "OMEGA_DIAG counterfactual users=", drug_users_without_child,&
                    " child value=", expected_child_value

                child_penalty_off=0

                write(*,*) "MOMENT omega     use rise, child term off    model=",&
                    drug_users_without_child/baseline_users_for_gap-1.d0,&
                    " target=", child_use_gap_data

            else

                ! NO BASELINE, NO GAP. A ratio taken against a using population
                ! a tenth of its target is a statement about the denominator,
                ! and printing it would enter the loss as if it were a
                ! measurement. Say why instead.
                write(*,*) "omega HELD: using population is", model_total_drug_users(1),&
                    "against a target of", participation_rate_data,&
                    "so the child use gap is not measurable"

            end if

            ! THE TWO DRUG PRICE ELASTICITIES, and they go below omega because
            ! a counterfactual leaves its distribution behind and this is one.
            ! When omega has run, the base this would perturb is omega's world
            ! and not the benchmark, so the two cannot both be measured in one
            ! point and this one says so rather than printing a number off the
            ! wrong base.
            if (measure_price_elasticity==0) then

                write(*,*) "ELASTICITY SKIPPED  drug price elasticities off by measure_price_elasticity"

            elseif (measure_child_gap==1) then

                write(*,*) "ELASTICITY SKIPPED  omega ran first and left its distribution behind"

            elseif (model_total_drug_users(1)<=10.d0**(-8)) then

                write(*,*) "ELASTICITY HELD     nobody uses, so a demand elasticity is not defined"

            else

                val_price_base_1=price_of_addictive_good
                val_users_base_1=model_total_drug_users(1)
                val_qty_base_1=model_drugs_used_by_users_on_average(1)
                val_qty_addict_base_1=model_drugs_used_by_addicts_on_average(1)
                val_qty_exper_base_1=model_drugs_used_by_experimenters_on_average(1)
                val_addict_share_base_1=model_mass_addicts(1)/&
                    max(model_mass_addicts(1)+model_mass_experimenters(1),10.d0**(-14))

                write(*,*) "ELASTICITY_DIAG base price=", val_price_base_1,&
                    " users=", val_users_base_1, " quantity per user=", val_qty_base_1
                write(*,*) "ELASTICITY_DIAG base per addict=", val_qty_addict_base_1,&
                    " per experimenter=", val_qty_exper_base_1,&
                    " addict share of users=", val_addict_share_base_1

                ! The market clears in the OUTER loop, so the price stays where
                ! it is put across a direct solve and converge. That is the
                ! whole reason this measures a demand curve.
                price_of_addictive_good=val_price_base_1*(1+elasticity_price_step)

                call solve_value_function_and_policy_functions(1)
                call converge_to_stationary_equilibrium(1)
                call stationary_equilibrium_statistics(1)
                ! model_total_drug_users is built in govt_revenues_calc and not
                ! in stationary_equilibrium_statistics, which is the mistake
                ! omega made and paid for.
                call govt_revenues_calc(1)

                write(*,*) "ELASTICITY_DIAG new price=", price_of_addictive_good,&
                    " users=", model_total_drug_users(1),&
                    " quantity per user=", model_drugs_used_by_users_on_average(1)

                if ((model_total_drug_users(1)>10.d0**(-12)) .AND. &
                    (val_users_base_1>10.d0**(-12))) then
                    write(*,*) "UNTARGETED price elasticity, participation   model=",&
                        log(model_total_drug_users(1)/val_users_base_1)/&
                        log(1+elasticity_price_step), " observed=", -0.63d0
                else
                    write(*,*) "ELASTICITY HELD     participation went to zero at the higher price"
                end if

                ! THE INTENSIVE MARGIN IS THE PER-ADDICT NUMBER, NOT THE PER-USER
                ! ONE. Olmstead et al. measure a conditional elasticity among
                ! continuing regular users. Quantity per USER moves whenever the
                ! addict/experimenter mix shifts, and a price rise shrinks the
                ! disorder stock, so that statistic mixes each household's own
                ! response with a change in who is being averaged over. It read
                ! -5.06 where the first order condition bounds an individual at
                ! about -1.3, which is how the mismatch was caught.
                if ((model_drugs_used_by_addicts_on_average(1)>10.d0**(-12)) .AND. &
                    (val_qty_addict_base_1>10.d0**(-12))) then
                    write(*,*) "UNTARGETED price elasticity, intensive       model=",&
                        log(model_drugs_used_by_addicts_on_average(1)/val_qty_addict_base_1)/&
                        log(1+elasticity_price_step), " observed=", -0.55d0
                else
                    write(*,*) "ELASTICITY HELD     quantity per addict went to zero at the higher price"
                end if

                ! The per-user figure is kept as a diagnostic, since the gap
                ! between it and the row above IS the composition effect.
                if ((model_drugs_used_by_users_on_average(1)>10.d0**(-12)) .AND. &
                    (val_qty_base_1>10.d0**(-12))) then
                    write(*,*) "DIAG elasticity, quantity per USER (mixed)      =",&
                        log(model_drugs_used_by_users_on_average(1)/val_qty_base_1)/&
                        log(1+elasticity_price_step)
                end if

                write(*,*) "ELASTICITY_DIAG new per addict=", model_drugs_used_by_addicts_on_average(1),&
                    " per experimenter=", model_drugs_used_by_experimenters_on_average(1),&
                    " addict share of users=", model_mass_addicts(1)/&
                    max(model_mass_addicts(1)+model_mass_experimenters(1),10.d0**(-14))

                ! THE THREE PIECES THE PER-USER NUMBER IS MADE OF. The first is
                ! the one the literature measures.
                if ((model_drugs_used_by_addicts_on_average(1)>10.d0**(-12)) .AND. &
                    (val_qty_addict_base_1>10.d0**(-12))) then
                    write(*,*) "DIAG elasticity, quantity per ADDICT            =",&
                        log(model_drugs_used_by_addicts_on_average(1)/val_qty_addict_base_1)/&
                        log(1+elasticity_price_step)
                end if
                if ((model_drugs_used_by_experimenters_on_average(1)>10.d0**(-12)) .AND. &
                    (val_qty_exper_base_1>10.d0**(-12))) then
                    write(*,*) "DIAG elasticity, quantity per EXPERIMENTER      =",&
                        log(model_drugs_used_by_experimenters_on_average(1)/val_qty_exper_base_1)/&
                        log(1+elasticity_price_step)
                end if
                if ((val_addict_share_base_1>10.d0**(-12)) .AND. &
                    (model_mass_addicts(1)+model_mass_experimenters(1)>10.d0**(-14))) then
                    write(*,*) "DIAG elasticity, ADDICT SHARE of users          =",&
                        log((model_mass_addicts(1)/(model_mass_addicts(1)+&
                        model_mass_experimenters(1)))/val_addict_share_base_1)/&
                        log(1+elasticity_price_step)
                end if

                price_of_addictive_good=val_price_base_1

            end if

            ! WHO IS HOMELESS, AND WHETHER THEY HAD A CHOICE. These are
            ! diagnostics, not moments: the prefix is DIAG so nothing parses them
            ! as targets and the moment count does not move. They are here rather
            ! than in the wider log because run_one_point.sh keeps only this
            ! block, and the question they answer -- why so few of the homeless
            ! carry serious mental illness when most such households have no
            ! income at all -- cannot be settled from the targeted moments.
            !
            ! homeless_by_choice counts a homeless household whose income PLUS
            ! ASSETS exceed the rent on the smallest dwelling, so it could have
            ! been housed and was not. Its complement is the households actually
            ! shut out. If the first number is close to one, homelessness in this
            ! model is a preference and not a constraint, and no parameter that
            ! moves incomes will move the mental illness share of the street.
            ! TWO DOCUMENTED MOMENTS FOR THE HOMELESS THAT NOTHING SCORED.
            ! Both are in section 5 of DATA_APPENDIX.md and neither was ever
            ! compared with the model. Meyer, Wyse, Meyer, Grunwaldt and Wu
            ! (2024), NBER 32323, from the 2010 Census linked to tax and
            ! administrative records: income of the homeless at 19.1 per cent of
            ! average, and formal employment at 52 per cent of the sheltered and
            ! 40 per cent of the unsheltered, so 0.46 at the midpoint.
            !
            ! The pair matters more than either alone. It says the homeless in
            ! the world are POOR AND HALF OF THEM WORK, where the model's are
            ! comfortable and nearly all of them work.
            write(*,*) "UNTARGETED income of the homeless            model=",&
                model_avg_homeless_income(1)/max(model_average_income(1),10.d0**(-14)),&
                " observed=", 0.191d0
            ! SCORED FROM 3 SEPTEMBER, on the author's instruction: *"I think you
            ! can choose the bottom productivity level to march the share of the
            ! employed homeless."*
            !
            ! bottom_productivity_level has been registered against emp_homeless
            ! in next_batch.py's OWN table for a day, and the gate has been
            ! reporting "response turns and nothing straddles the target" the
            ! whole time -- because the moment was emitted as UNTARGETED and
            ! score_points only reads MOMENT lines. The instrument had a target
            ! it could not see. It is a MOMENT now.
            write(*,*) "MOMENT emp_homeless employed share of homeless model=",&
                model_employed_share_of_homeless(1), " target=", 0.460d0
            write(*,*) "DIAG homeless who could afford it on INCOME ALONE=",&
                val_homeless_afford_on_income(1)
            write(*,*) "DIAG homeless by choice, share of the homeless   =",&
                model_fraction_homeless_by_choice(1)
            write(*,*) "DIAG homeless receiving food stamps              =",&
                model_fraction_homeless_recieving_food_stamps(1)
            ! THE LOWER TAIL OF WEALTH IS WHAT DECIDES WHO CAN BE SHUT OUT, and
            ! nothing in the loss pins it. beta is bracketed on wealth over
            ! output, an AGGREGATE, and it currently sits nineteen per cent above
            ! its target; the bottom half's share of net worth, 2.52 per cent in
            ! the Fed distributional accounts, is reported with the untargeted
            ! moments and never matched. A model can carry the right total wealth
            ! with far too little of it concentrated, and then no household is
            ! ever short of the smallest rent. These two say whether that is what
            ! is happening.
            ! MEDIAN ASSETS TO INCOME IS NOT PRINTED HERE, AND MUST NOT BE
            ! ADDED BACK. model_median_assets_to_income is declared, zeroed
            ! once, and never assigned anywhere in this file, so it reads
            ! exactly 0.000 in every run. It was printed here for four runs
            ! and read as evidence that the median household holds nothing,
            ! which would have contradicted the bottom half share below and
            ! sent the search after a bug that does not exist. It is not a
            ! measurement of anything. The live check on the shares below is
            ! the histogram pair at the end of this block.
            write(*,*) "DIAG average assets of the homeless              =",&
                model_avg_homeless_assets(1)
            write(*,*) "DIAG wealth share of the bottom 25 pct           =",&
                model_wealth_share_below(4,1)
            ! THE ONSET IS A PRODUCT AND ONLY THE PRODUCT MATTERS. lambda is
            ! searched, but what the disorder stock responds to is
            ! 1-exp(-lambda*quantity) at the mean quantity, and the quantity is
            ! a CHOICE. Over the whole archive of 29 August lambda spans 4.51 to
            ! 6.93 while the onset implied by the flow balance stays inside
            ! 0.0016 to 0.0031, which says the quantity is absorbing the hazard.
            ! That was INFERRED from the flow balance, never seen; these two
            ! lines make it visible in every point instead.
            write(*,*) "DIAG mean drug quantity, users                   =",&
                model_drugs_used_by_users_on_average(1)
            write(*,*) "DIAG onset at the mean quantity                  =",&
                addiction_onset_hazard(model_drugs_used_by_users_on_average(1))
            ! THE VALIDATION SECTION'S INCOME ROWS. The model has carried these
            ! three averages all along and never printed one of them, so the
            ! table in the note lists a data value and a source for each with no
            ! model counterpart beside it. They are ratios to average income
            ! because that is how NSDUH reports them: 74.0 per cent of average
            ! for drug users and 71.1 for a moderate or severe disorder.
            ! A TARGET NOW, ON THE AUTHOR'S INSTRUCTION, with kappa_phi_d_level
            ! as its instrument. It was the model's largest untargeted failure --
            ! users at 0.17 to 0.34 of average income against 0.74 -- and the
            ! reason is that the mortality penalty is the price of using, so a
            ! high one leaves only the most desperate willing to pay it. Making
            ! it a moment puts that parameter under the loss instead of leaving
            ! the failure to be reported.
            !
            ! READ IT ONLY WHERE b IS NEAR TARGET. If nearly everyone uses, the
            ! users ARE the population and this reads close to one for reasons
            ! that have nothing to do with the mechanism.
            write(*,*) "MOMENT y_u       income of drug users        model=",&
                model_avg_income_drug_users(1)/&
                max(model_average_income(1),10.d0**(-14)),&
                " target=", drug_user_income_data
            write(*,*) "UNTARGETED income with a SUD                 model=",&
                model_average_income_addicted(1)/&
                max(model_average_income(1),10.d0**(-14)),&
                " observed=", 0.711d0
            ! HOW BIG THE CORRECTION ABOVE WAS. This is the share of households
            ! carrying the disorder that consume nothing, and it is exactly the
            ! group whose income the three statistics above used to drop while
            ! counting its mass. It was computed, written to a file and never
            ! printed, so the bias was invisible from a point file.
            write(*,*) "DIAG carriers of the disorder consuming no drugs =",&
                model_addicts_consuming_no_drugs(1)
            write(*,*) "DIAG income of experimenters / average           =",&
                model_avg_income_experimenters(1)/&
                max(model_average_income(1),10.d0**(-14))
            ! THE SAME TWO OVER AVERAGE LABOUR INCOME, WHICH IS NOT THE SAME
            ! NUMBER AND IS THE ONE THE NOTE ALREADY QUOTES. The old benchmark's
            ! 0.41 for drug users is a ratio to average LABOUR income, and the
            ! rows above are ratios to average TOTAL income because that is what
            ! NSDUH's income concept is. Printing only one of them guarantees
            ! that someone eventually reads the new figure against the old and
            ! calls a change of denominator a change in the model.
            write(*,*) "DIAG income of drug users / labour income        =",&
                model_avg_income_drug_users(1)/&
                max(model_average_labour_income(1),10.d0**(-14))
            write(*,*) "DIAG income with a SUD / labour income           =",&
                model_average_income_addicted(1)/&
                max(model_average_labour_income(1),10.d0**(-14))
            ! POOLED MASS, NOT sum_of_distribution. That variable is module
            ! scope and calculate_cdf_of_incomes_earned -- eighth in the chain,
            ! so it runs after the mass is built -- reuses it as a scratch
            ! scalar holding ONE grid cell. Whatever it holds by the time this
            ! prints is not a population. pooled_mass_all is owned by one
            ! routine and nothing else writes it.
            write(*,*) "DIAG mass ON the top savings grid point          =",&
                diag_mass_top_financial/max(pooled_mass_all,10.d0**(-12))
            write(*,*) "DIAG mass in the top THREE savings grid points   =",&
                diag_mass_top3_financial/max(pooled_mass_all,10.d0**(-12))
            ! IS THE HISTOGRAM THE WHOLE DISTRIBUTION? Both should read 1.0. If
            ! they do not, the shares above are read off the wrong denominator
            ! and none of them mean anything.
            write(*,*) "DIAG histogram mass / distribution  (want 1.0)   =",&
                wealth_hist_mass_check
            write(*,*) "DIAG histogram wealth / total wealth (want 1.0)  =",&
                wealth_hist_wealth_check

            ! WHY THE MODEL'S HOMELESS ARE ALL YOUNG. The band shares say 98
            ! per cent of them are 25 to 34 against 26 in the HUD count, and the
            ! mortality gradient does not explain it: weighted by discounted
            ! remaining life the deterrent runs 1.00, 1.37, 1.57 and 1.79 across
            ! 26, 34, 50 and 58, which is nearly flat, and it COLLAPSES after 70
            ! where the model has no homeless at all. So the answer has to be on
            ! the other side of the trade -- what the household gains by not
            ! paying rent -- and that is not currently reported by age.
            !
            ! These four columns are the trade, age by age: how many are on the
            ! street, how many own (an owner cannot be homeless), and what a
            ! renter of that age holds and earns. If homelessness tracks renter
            ! wealth it is a buffer story; if it tracks the ownership rate it is
            ! a tenure story; if it tracks neither it is preferences.
            write(*,*) "DIAG --- the age profile of the housing margin ---"
            ! EVERY AGE, NOT EVERY THIRD. The stride of 3 printed 26, 29, 32 and
            ! hid 27 and 28 -- which is exactly where the age profile is decided:
            ! homelessness falls sixty-eight fold between 26 and 29 and nobody has
            ! seen the two steps in between. The author asked for the 26-to-27
            ! comparison and the diagnostic could not answer it.
            do diag_age_1=1,life_span,1

                ! SUD AND MASS ARE HERE SO THE PROFILE CAN BE READ AND BANDED.
                ! addiction_rate_by_age is the disorder rate at that age, over
                ! the same mass_by_age the homelessness rate above uses, and it
                ! was written to a csv and nowhere a point file could see it.
                ! mass= is what any banding of these columns has to weight by.
                write(*,'(A,I3,A,F10.6,A,F9.5,A,F11.5,A,F11.5,A,F10.6,A,F12.6)') &
                    "DIAG age ", 25+diag_age_1, &
                    "  homeless=", homelessness_by_age(1,diag_age_1), &
                    "  own=", homeownership_by_age(1,diag_age_1), &
                    "  renter wealth=", wealth_by_age_renter(1,diag_age_1), &
                    "  renter income=", income_by_age_renter(1,diag_age_1), &
                    "  sud=", addiction_rate_by_age(1,diag_age_1), &
                    "  mass=", mass_by_age(1,diag_age_1)

            end do

            ! ================= INVARIANTS =================
            ! IDENTITIES THAT MUST HOLD BY CONSTRUCTION, CHECKED ON EVERY POINT.
            !
            ! The model already carried three of these -- the histogram mass
            ! checks -- and they are what caught the first pooling bug: they had
            ! been printing 2.0000 for hours while the code was read and the
            ! diagnosis guessed at, wrongly, three times. Reading 38,000 lines
            ! does not find this class. A number that must be 1.0 and is not
            ! finds it on the first run.
            !
            ! Each line prints PASS or FAIL, and the last line is the count, so
            ! a run can be triaged from one grep instead of an eye over a
            ! hundred numbers.
            ! THE MASS EACH DISCOUNT-FACTOR TYPE ACTUALLY CARRIES, and the
            ! ratio between them. This is here because the two histogram
            ! invariants below read 1.19 rather than 1.0 for three points, and
            ! the diagnosis -- that the types do not weigh the same, so a
            ! denominator built from one type's mass times a pass count is
            ! wrong -- is a claim about these two numbers. If they come out
            ! equal, the diagnosis is wrong and the 1.19 has another cause.
            ! At one type the second entry is zero and the ratio is one.
            write(*,'(A,F14.6,A,F14.6,A,F10.6)') &
                " DIAG mass by beta type:  patient=", mass_by_beta_type(1), &
                "  impatient=", mass_by_beta_type(2), &
                "  patient/impatient=", &
                mass_by_beta_type(1)/max(mass_by_beta_type(2),10.d0**(-12))
            write(*,*) "DIAG pooled mass=", pooled_mass_all, &
                " one-type equivalent=", mass_by_beta_type(1)

            ! HOW OFTEN THE LABOUR SECANT ACTUALLY FAILED TO CONVERGE, once,
            ! rather than eleven lines every time it did. Zero is the expected
            ! reading. A large number here is a real solver problem and the
            ! twenty printed occurrences above are the evidence for it.
            write(*,*) "DIAG labour secant hit its iteration cap        =",&
                secant_warn_count

            write(*,*) "===== INVARIANTS ====="
            diag_fail_1=0

            call check_one("income histogram holds the whole distribution",&
                income_hist_mass_check,1.d0,10.d0**(-6),diag_fail_1)
            call check_one("wealth histogram holds the whole distribution",&
                wealth_hist_mass_check,1.d0,10.d0**(-6),diag_fail_1)
            call check_one("wealth histogram holds the whole of net worth",&
                wealth_hist_wealth_check,1.d0,10.d0**(-6),diag_fail_1)

            ! THE RENTAL MARKET CLEARS. Demand and supply are both accumulated
            ! over both discount-factor types, and the rent that solves the
            ! outer loop is the one that equates them. If this fails the price
            ! every household faces is wrong, and with it every housing choice.
            call check_one("rental market clears, demand over supply",&
                sum(total_rental_demand(1,:))/&
                max(sum(total_rental_supply(1,:)),10.d0**(-12)),&
                1.d0,10.d0**(-3),diag_fail_1)

            ! SHARES ARE SHARES. Every one of these is a fraction of a
            ! population and cannot leave the unit interval. A share above one
            ! is a pooling error or a denominator that lost its mass; a
            ! negative one is an accumulator that went backwards.
            call check_range("homelessness rate",model_fraction_homeless(1),diag_fail_1)
            call check_range("drug users",model_total_drug_users(1),diag_fail_1)
            call check_range("disorder rate",model_fraction_addicted(1),diag_fail_1)
            call check_range("SMI population share",model_smi_prevalence(1),diag_fail_1)
            call check_range("unemployment rate",model_fraction_unemployed(1),diag_fail_1)
            call check_range("homeownership rate",model_homeownership_rate(1),diag_fail_1)

            ! SHARES OF THE HOMELESS. Each of these is a subset of the homeless
            ! divided by the homeless, so each is bounded by one by construction
            ! and a value above one means the divisor is not the homeless mass.
            ! This is not hypothetical: total_homeless_1 is a LOCAL of the
            ! routine that forms these, its reset was disabled on the mistaken
            ! belief that an earlier routine owned it, and "homeless by choice"
            ! duly printed 1.6552. Nothing flagged it.
            call check_range("homeless by choice, share of the homeless",&
                model_fraction_homeless_by_choice(1),diag_fail_1)
            call check_range("homeless who could afford it on income",&
                val_homeless_afford_on_income(1),diag_fail_1)
            call check_range("employed share of the homeless",&
                model_employed_share_of_homeless(1),diag_fail_1)
            call check_range("SMI share of the homeless",&
                model_smi_share_of_homeless(1),diag_fail_1)
            call check_range("households receiving food stamps",&
                model_fraction_recieving_food_stamps(1)/max(pooled_mass_all,10.d0**(-12)),&
                diag_fail_1)

            ! THE AGE BANDS PARTITION THE HOMELESS. homelessness_by_age_group is
            ! normalised to sum to one by construction, so a failure here means
            ! the normalisation ran against a different population from the one
            ! the bands were filled from -- which is exactly what a routine
            ! called twice, once inside the two-pass loop and once outside it,
            ! produces.
            call check_one("the five age bands hold all of the homeless",&
                sum(homelessness_by_age_group(1,:)),1.d0,10.d0**(-6),diag_fail_1)

            if (diag_fail_1==0) then
                write(*,*) "INVARIANTS: all PASS"
            else
                write(*,*) "INVARIANTS: ", diag_fail_1, " FAILED -- see the lines above"
            end if

            write(*,*) "===== END OF MOMENTS ====="

        end subroutine

        function weighted_drug_share_now() result(share_1)

            ! THE DRUG SPENDING SHARE, COMPUTED WHERE A SWEEP CAN SEE IT.
            !
            ! The moment was computed inside the parameter update block, which a
            ! sweep skips entirely, so it never printed once in a sweep: the log
            ! carried zero occurrences of it across eleven points. That is the
            ! moment theta owns, and theta is one of the parameters the staged
            ! search pins at a declared value, so a sweep that cannot see the
            ! share cannot say whether the pin is the right one.
            !
            ! Everything it needs is an aggregate the distribution pass has
            ! already built, so it can be evaluated any time after aggregation.
            ! The update block now takes its value from here too, so there is one
            ! definition rather than two that can drift.

            implicit none

            real(8) :: share_1,floor_1,share_e_1,share_a_1
            logical :: ok_e_1,ok_a_1

            floor_1=10.d0**(-1)*model_average_labour_income(1)
            share_e_1=model_experimenters_total_drug_spending_to_total_income(1)
            share_a_1=model_addicted_total_addiction_spending_to_total_income(1)

            ok_e_1=(model_mass_experimenters(1)>0) .AND. (share_e_1>=0) .AND. &
                (model_experimenters_total_income(1)>&
                floor_1*model_mass_experimenters(1))
            ok_a_1=(model_mass_addicts(1)>0) .AND. (share_a_1>=0) .AND. &
                (model_addicted_total_income(1)>floor_1*model_mass_addicts(1))

            if (ok_e_1 .AND. ok_a_1) then

                share_1=(model_mass_experimenters(1)*share_e_1+&
                    model_mass_addicts(1)*share_a_1)/&
                    (model_mass_experimenters(1)+model_mass_addicts(1))

            elseif (ok_e_1) then

                share_1=share_e_1

            elseif (ok_a_1) then

                share_1=share_a_1

            else

                share_1=-1

            end if

        end function

        subroutine apply_gamma_tie()

            ! gamma = 0.28*(1-theta) while the tie is on, and nothing otherwise.
            ! Called after every place theta can change, so the two cannot fall
            ! out of step between one and the next.

            implicit none

            if (tie_gamma_to_theta==1) then

                relative_share_of_housing=gamma_share_of_non_drug*&
                    (1.d0-relative_share_of_addiction_1)

            end if

        end subroutine

        function move_factor(model_1,target_1,escape_1) result(factor_1)

            ! HOW FAR THIS PARAMETER MAY MOVE THIS LOOP, from the state of the
            ! moment it owns rather than from a fixed schedule. In range, the
            ! author's one per cent. In a corner, escape_1, until the moment is
            ! back in range and the slow rule takes over by itself. The test is
            ! relative to the target so it needs no bespoke bound per moment,
            ! and it reads the same for a rate, a ratio and a share.

            implicit none

            real(8), intent(in) :: model_1,target_1,escape_1
            real(8) :: factor_1

            if ((abs(target_1)>10.d0**(-12)) .AND. &
                ((model_1<corner_low*target_1) .OR. (model_1>corner_high*target_1))) then

                factor_1=escape_1

            else

                factor_1=trust_factor

            end if

        end function

        subroutine trust_step(step_1,current_1,factor_1,allowance_1)

            ! A NEWTON OR SECANT STEP NEEDS A TRUST REGION, and three of them did
            ! not have one. Measured over a single loop, with the report finally
            ! pairing each parameter with the moment it produced:
            !
            !   utility_cost_of_treatment  2.12423   -> 0          -100%, its floor
            !   separation_rate            0.005881  -> 1e-6       -100%, its floor
            !   lambda's onset             0.917909  -> 0.225139    -75%
            !
            ! against every other instrument moving under eight per cent. A
            ! secant is exactly right when the response is locally linear and
            ! unbounded when it is not, and at a corner it is never linear: the
            ! treatment secant divided by a take up that had barely moved, and
            ! the separation step was 0.0102 on a parameter of 0.0059, 173 per
            ! cent of it, so the clamp at the floor was the only thing that
            ! stopped it going negative. A parameter that lands on its bound
            ! every loop is not being calibrated, and the moments measured next
            ! to it are measured at the bound rather than at an answer.
            !
            ! So bound the step multiplicatively around where the parameter is,
            ! with an absolute allowance so one sitting at or near zero can still
            ! leave it. This is aleph's trust region, which already works, made
            ! available to the others rather than written out a fourth time.

            implicit none

            real(8), intent(inout) :: step_1
            real(8), intent(in) :: current_1,factor_1,allowance_1
            real(8) :: hi_1,lo_1

            hi_1=max(current_1*factor_1,current_1+allowance_1)
            lo_1=min(current_1/factor_1,current_1-allowance_1)
            step_1=max(min(step_1,hi_1),lo_1)

        end subroutine

        subroutine damp_on_flip(adj_1,gap_1,prev_gap_1,have_gap_1,start_1,floor_1)

            ! THE PATTERN, ONCE. A fixed adjuster on an elastic moment overshoots,
            ! the gap changes sign, and the parameter rings for ever without
            ! getting closer. Halving the step on a sign flip turns the rule into
            ! a bisection, which converges on any monotone response however steep;
            ! growing it back when the sign holds stops it creeping afterwards.
            !
            ! Written out inline four times before this — for delta_d, for b, for
            ! aleph's trust radius and for size_homelessness — and the fifth
            ! through ninth are these. The instruments that had it converged; the
            ! ones that did not oscillated: voucher coverage went 9.7, 26.7, 12.7,
            ! 47.3 per cent off across four loops, and the employment multiplier
            ! reached its target and left again, 7.5, 0.3, 15.8.
            !
            ! The caller owns the state, because each instrument needs its own and
            ! the checkpoint has to save it.

            implicit none

            real(8), intent(inout) :: adj_1,prev_gap_1
            integer, intent(inout) :: have_gap_1
            real(8), intent(in) :: gap_1,start_1,floor_1

            ! AN ADJUSTER AT ZERO IS PINNED AND MUST STAY PINNED.
            !
            ! The damping branch below is max(adj*0.5, floor). At adj=0 that is
            ! max(0, floor) = FLOOR, so the first time the gap changes sign an
            ! adjuster sitting at exactly zero jumps to the floor and then grows
            ! by 1.2 a loop up to its start value -- 1e-4 reaches 5e-2 in about
            ! thirty four loops. The growth branch, min(0*1.2, start)=0, is
            ! harmless. Only the damping branch resurrects.
            !
            ! Four adjusters reach this, every one documented as fixed:
            ! relative_share_of_housing ("ZERO, AND DELIBERATELY ... next_batch
            ! owns it across points"), relative_share_of_leisure (frozen by
            ! freeze_fitted_internals), housing_status_grid_expander, and
            ! penalty_child_homeless ("EXTERNALLY SET"). The in-model loop would
            ! move delta_h, gamma and omega_l away from the values handed in
            ! while the archive still recorded them as pinned -- a parameter
            ! drifting with no record that it moved.
            if (adj_1<=0.d0) return

            if (have_gap_1==1) then

                if ((gap_1*prev_gap_1)<0) then

                    adj_1=max(adj_1*0.5d0,floor_1)

                else

                    adj_1=min(adj_1*1.2d0,start_1)

                end if

            end if

            prev_gap_1=gap_1
            have_gap_1=1

        end subroutine

        integer function idx_of(e_1,m_1,d_1)
            implicit none
            integer, intent(in) :: e_1,m_1,d_1
            idx_of=3*number_of_smi_states*d_1+3*m_1+e_1
        end function

        ! WHICH SUD INDEX THE MORTALITY MULTIPLIER IS READ AT.
        !
        ! The excess mortality of the disorder is overwhelmingly a mortality of
        ! USE, poisoning above all, and treatment forbids use in the period it is
        ! taken. A household in treatment therefore does not carry kappa_phi_d
        ! that period, and this is the one place that exception is known.
        !
        ! It matters for whether anybody takes treatment at all. Before this, the
        ! offer was to give up a full period of the drug in exchange for raising
        ! the annual recovery hazard from 0.0250 to 0.0338, a gain of 0.88
        ! percentage points, and take up was zero at every cost including a cost
        ! of zero. Surviving the period at the clean hazard rather than at a
        ! multiple of it is a first order gain by comparison, and it is a gain the
        ! household is actually buying with the abstention it is already paying
        ! for.
        !
        ! The strong form of the assumption is deliberate and worth naming: the
        ! standardised mortality ratios kappa_phi_d is calibrated to are measured
        ! on people who CARRY the disorder, not on people using in a given year,
        ! so treating a household as fully clean for the period overstates what
        ! one period of abstention buys. The weaker form would scale the
        ! multiplier down rather than remove it.
        ! THE MEAN OF A MEAN-ONE LOGNORMAL BELOW ITS q-TH QUANTILE, which is
        ! Phi(Phi^{-1}(q) - sigma). Differencing it across two quantiles and
        ! dividing by the mass between them gives the conditional mean of that
        ! interval, which is where a node belongs: it makes the discretisation
        ! integrate to the distribution rather than to a truncation of it.
        real(8) function lognormal_tail_mean(q_1,sigma_1)
            implicit none
            real(8), intent(in) :: q_1,sigma_1
            if (q_1<=0) then
                lognormal_tail_mean=0
            else if (q_1>=1) then
                lognormal_tail_mean=1
            else
                lognormal_tail_mean=&
                    (1+erf((normal_quantile(q_1)-sigma_1)/sqrt(2.d0)))/2
            end if
        end function

        ! THE STANDARD NORMAL CDF, in one place. Fortran has erf, and
        ! Phi(x) = (1 + erf(x/sqrt(2)))/2.
        real(8) function normal_cdf(x_1)
            implicit none
            real(8), intent(in) :: x_1
            normal_cdf=(1.d0+erf(x_1/sqrt(2.d0)))/2.d0
        end function

        ! THE NORMAL QUANTILE BY BISECTION, because Fortran has erf and no
        ! inverse of it. Eighty halvings of [-12,12] is machine precision here
        ! and it is called once per node per loop, so the cost is nothing.
        real(8) function normal_quantile(p_1)
            implicit none
            real(8), intent(in) :: p_1
            real(8) :: lo_1,hi_1,mid_1
            integer :: iter_1
            lo_1=-12
            hi_1=12
            do iter_1=1,80
                mid_1=0.5d0*(lo_1+hi_1)
                if (((1+erf(mid_1/sqrt(2.d0)))/2)<p_1) then
                    lo_1=mid_1
                else
                    hi_1=mid_1
                end if
            end do
            normal_quantile=0.5d0*(lo_1+hi_1)
        end function

        integer function survival_sud_of(d_1,treatment_1)
            implicit none
            integer, intent(in) :: d_1,treatment_1
            ! THE DISORDER STILL KILLS WHILE IT IS BEING TREATED. This used to
            ! return d_1*(1-treatment_1), so a household in treatment was priced
            ! as though it did not carry the disorder at all for one period: the
            ! mortality penalty was suspended for the length of the course. That
            ! made treatment a second benefit on top of the recovery multiplier
            ! and is not what a course of treatment does. Treatment now buys the
            ! multiplier and nothing else.
            survival_sud_of=d_1
        end function

        ! THE STONE GEARY SHIFTER, in one place. It depends on whether the
        ! household carries a SUD and on whether it is homeless, and on nothing
        ! else. Homelessness is identified by the housing SIZE rather than the
        ! index because the chain from the solver down to
        ! optimize_frac_spent_on_addiciton carries the size; the homeless flow is
        ! size_homelessness times the smallest rental, about a fifth of it, so
        ! the test has an enormous margin and no floating point risk.
        !
        ! Every place that evaluates the drug term goes through this, so the flow
        ! utility, its marginal utility and the closed form split cannot drift
        ! apart. That was the reason not to patch them one at a time.
        real(8) function b_shifter(is_sud_1,housing_size_1)

            implicit none

            integer, intent(in) :: is_sud_1
            real(8), intent(in) :: housing_size_1

            ! b IS CONSTANT ACROSS EVERY STATE AND EVERY CHOICE. The arguments
            ! are kept so the 24 call sites read as they did, and so that a
            ! robustness run can restore a dependence in one place, but the
            ! baseline returns the same number everywhere. Three reasons, and the
            ! second is decisive.
            !
            ! HOUSING IS A CHOICE, NOT A STATE. b used to be multiplied by
            ! rho_b_homeless whenever the dwelling CHOSEN for next period was
            ! below the smallest rental. That makes preferences a function of a
            ! choice: the household picks its housing partly to move its own
            ! taste for drugs, which is not a preference in the usual sense and
            ! invites exactly the perverse selection the paper is about, a user
            ! choosing the street because the drug is worth more there.
            !
            ! THE SIGN OF THE UTILITY EFFECT IS WRONG ANYWAY. Flow utility is
            ! Cobb-Douglas in (b + v), so the marginal value of the drug is
            ! proportional to 1/(b+v): a SMALLER b raises the marginal value of
            ! using and raises desired intake. Whatever the level effect, the
            ! channel works by making the drug better on the street, which is a
            ! strange thing to assert and stranger to calibrate.
            !
            ! IT IS NOT NEEDED. Housing already changes drug use through a
            ! HAZARD rather than a taste: recovery from the disorder is harder
            ! harder on the street, probability_of_stopping_addiction_if_homeless
            ! against probability_of_stopping_addiction. That is a transition
            ! probability, it is what Milby et al.\ (2005) actually measure,
            ! abstinence rates by arm, and it carries the elasticity of drug use
            ! with respect to housing access on its own.
            b_shifter=addiction_scalar_1

        end function

        ! THE ADDICTION HAZARD, pi_d(v) = 1 - exp(-lambda v), in one place.
        !
        ! v is the QUANTITY of the drug, not the spending on it. Everywhere in
        ! the code the quantity is spending over the price,
        ! frac_spent_on_addiction*total_consumption_choice/price_of_addictive_good,
        ! and it has to be the quantity here or a supply side counterfactual
        ! would move the price, move spending, and leave onset untouched, which
        ! is the whole point of putting the hazard in quantity.
        real(8) function addiction_onset_hazard(drug_quantity_1)

            implicit none

            real(8), intent(in) :: drug_quantity_1

            ! BASE ONLY IF YOU USE. A household with v=0 is not a user and its
            ! onset stays exactly zero, which is the row the old lookup had and
            ! what keeps abstainers clean. Any positive quantity carries the
            ! baseline, then the exponential term on top of it.
            if (drug_quantity_1>0.d0) then

                addiction_onset_hazard=min(addiction_onset_base+&
                    (1-exp(-lambda_addiction*drug_quantity_1)),1.d0)

            else

                addiction_onset_hazard=0.d0

            end if

        end function

        ! d pi_d / d v = lambda exp(-lambda v). This is the marginal risk the
        ! household weighs against the marginal flow value of the drug, so it
        ! belongs next to the hazard and not inlined at the one place that
        ! differentiates it.
        real(8) function addiction_onset_hazard_slope(drug_quantity_1)

            implicit none

            real(8), intent(in) :: drug_quantity_1

            ! The additive base does not change d pi_d / d v, so the slope is
            ! unchanged EXCEPT where the hazard is clamped at one, and there it
            ! is zero. A slope that kept rising past the clamp would give the
            ! household a marginal risk the hazard does not actually deliver.
            if (addiction_onset_base+&
                (1-exp(-lambda_addiction*max(drug_quantity_1,0.d0)))>=1.d0) then

                addiction_onset_hazard_slope=0.d0

            else

                addiction_onset_hazard_slope=&
                    lambda_addiction*exp(-lambda_addiction*max(drug_quantity_1,0.d0))

            end if

        end function

        ! THE TRANSITION, replacing every read of addiction_probabilities.
        !
        ! Arguments are the four the array carried, in the same order, plus the
        ! drug quantity chosen at this state and a flag for whether the caller
        ! wants the perceived probability, which is what the household optimises
        ! against, or the objective one, which is what the distribution and the
        ! transition iterate on.
        !
        ! Only the ONSET row is a function of v. Recovery from the disorder runs
        ! on housing, harder on the street, and not on how much is
        ! used, so an already addicted household reads the array. A household
        ! that does not use has v=0 and 1-exp(0)=0, so the abstain row is
        ! reproduced exactly rather than special cased for its own sake, but the
        ! branch is kept anyway so that a zero lambda cannot make abstaining and
        ! using look identical to a reader of the code.
        real(8) function addiction_transition&
            (current_1,future_1,choice_1,homeless_1,drug_quantity_1,perceived_1,treatment_1,smi_1)

            implicit none

            integer, intent(in) :: current_1,future_1,choice_1,homeless_1,perceived_1,treatment_1
            ! OPTIONAL so that the twelve existing call sites stay valid while
            ! they are wired one at a time. Absent means no SMI, which is what
            ! the model was before, so leaving a site unwired is a silent
            ! omission rather than a compile error. Every site that has the
            ! unemployment index in scope should pass smi_of(it).
            integer, intent(in), optional :: smi_1
            real(8), intent(in) :: drug_quantity_1
            real(8) :: onset_1,recovery_1
            integer :: smi_used_1

            smi_used_1=0

            if (present(smi_1)) smi_used_1=smi_1

            ! ALREADY CARRYING THE DISORDER: the transition is recovery, it does
            ! not depend on how much is used, and treatment is the one choice
            ! that moves it. g multiplies the hazard and the complement follows,
            ! so a household in treatment recovers with probability
            ! min(1, g * pi_r) and stays with the rest.
            if ((current_1>=1) .AND. (include_addiction==1)) then

                recovery_1=addiction_probabilities(current_1,0,choice_1,homeless_1)

                if ((include_treatment==1) .AND. (treatment_1==1)) then

                    recovery_1=min(recovery_1*treatment_effect_on_recovery,1.d0)

                end if

                ! mu_m: SMI lowers the recovery hazard.
                recovery_1=recovery_with_smi(recovery_1,smi_used_1)

                if (future_1==0) then

                    addiction_transition=recovery_1

                else

                    addiction_transition=1-recovery_1

                end if

                return

            end if

            if ((smooth_addiction_hazard==0) .OR. (include_addiction==0) .OR. &
                (include_probability_of_becoming_addicted==0) .OR. (current_1>=1) .OR. &
                (choice_1==0)) then

                if (perceived_1==1) then

                    addiction_transition=&
                        addiction_probabilities_percieved(current_1,future_1,choice_1,homeless_1)

                else

                    addiction_transition=&
                        addiction_probabilities(current_1,future_1,choice_1,homeless_1)

                end if

                return

            end if

            onset_1=addiction_onset_hazard(drug_quantity_1)

            if (perceived_1==1) then

                onset_1=min(onset_1*difference_in_perceived_of_becoming_addicted_if_experiment,1.d0)

            end if

            if (future_1>=1) then

                addiction_transition=onset_1

            else

                addiction_transition=1-onset_1

            end if

        end function

        subroutine compute_asset_lottery(opt_1,lo_1,hi_1,recorded_value_1)

        ! A' OFF THE GRID, BY A TWO POINT LOTTERY.
        !
        ! The discrete search returns the best GRID point. The true optimum
        ! generally sits between two of them, and with a coarse grid that gap is
        ! the dominant approximation error in the savings policy. The
        ! distribution already knows how to split a household across two asset
        ! points: it loops m=1,2 sending (1-frac) to the policy index and frac to
        ! fin_index_frac_mov_to_optimal. That machinery was fully wired and then
        ! fed a hardcoded frac of zero, so both branches landed on the same point
        ! and the lottery collapsed. This fills it.
        !
        ! The optimum is located by fitting a parabola through the objective at
        ! the argmax and its two neighbours. The grid is UNEVENLY spaced, which
        ! rules out the textbook equal spacing formula, so the general three
        ! point vertex is used. The weight is then set so the lottery's MEAN
        ! asset holding equals the vertex, which is what makes the aggregate
        ! right even though no household sits at the optimum.
        !
        ! It refuses in three cases rather than extrapolating: at either end of
        ! the search range, where there is no bracket; when the parabola is not
        ! concave, so the vertex is a minimum or a straight line and the fit says
        ! nothing; and when the vertex falls outside the bracket, which means the
        ! quadratic is a bad local model. Refusing costs nothing, since frac zero
        ! is exactly the old behaviour.
        !
        ! MEASURED, AND IT IS INERT. Over one backward induction: 177,120 calls,
        ! 12 fired, 160,995 refused on the branch match and 16,113 on the
        ! geometry. So this subroutine currently does nothing, and the asset grid
        ! must NOT be cut on the strength of it. PERFORMANCE_NOTES.md section 11
        ! has the numbers and the fix, which is to keep or recompute the three
        ! objective values for the WINNING housing branch rather than trusting
        ! the vectors, since the search refills them per branch and leaves the
        ! last one behind.

        !$ use omp_lib

        implicit none

        integer, intent(in) :: opt_1,lo_1,hi_1
        real(8), intent(in) :: recorded_value_1
        real(8) :: x0_1,x1_1,x2_1,y0_1,y1_1,y2_1,d1_1,d2_1,denom_1,vertex_1

        interp_frac_1=0
        interp_neighbour_1=opt_1

        if (interpolate_a_prime==0) return

        if (interp_slot_1<=0) then

            interp_slot_1=1
            !$ interp_slot_1=min(max_CPUs,omp_get_thread_num()+1)

        end if

        interp_counters(1,interp_slot_1)=interp_counters(1,interp_slot_1)+1

        if ((opt_1<=lo_1) .OR. (opt_1>=hi_1)) then

            interp_counters(3,interp_slot_1)=interp_counters(3,interp_slot_1)+1
            return

        end if

        ! THE WINNING BRANCH'S OWN THREE POINTS, not whatever the vectors hold.
        !
        ! This used to read flow_utility_vector and future_utility_vector
        ! directly, and they hold the LAST housing branch searched rather than
        ! the one that won, so the exact-value test below refused nine times in
        ! ten and the lottery fired twelve times in 177,120 calls. The three
        ! points are now captured at the moment a branch becomes the global
        ! best, which is where the winner is known.
        !
        ! THE EXACT TEST IS KEPT, as a check rather than a filter: if what was
        ! captured does not reproduce the value actually recorded, something has
        ! gone out of step and refusing is still right.
        if ((.not.interp_won_ok_1) .OR. (interp_won_index_1/=opt_1)) then

            interp_counters(2,interp_slot_1)=interp_counters(2,interp_slot_1)+1
            return

        end if

        if (abs(interp_won_y1_1-recorded_value_1)>&
            10.d0**(-8)*max(abs(recorded_value_1),1.d0)) then

            interp_counters(2,interp_slot_1)=interp_counters(2,interp_slot_1)+1
            return

        end if

        x0_1=financial_grid(opt_1-1)
        x1_1=financial_grid(opt_1)
        x2_1=financial_grid(opt_1+1)

        if ((x1_1-x0_1<=0.d0) .OR. (x2_1-x1_1<=0.d0)) then

            interp_counters(3,interp_slot_1)=interp_counters(3,interp_slot_1)+1
            return

        end if

        y0_1=interp_won_y0_1
        y1_1=interp_won_y1_1
        y2_1=interp_won_y2_1

        ! An unreachable neighbour carries a sentinel rather than a value, and a
        ! parabola through a sentinel is meaningless.
        if ((y0_1<=large_negative_num/2) .OR. (y2_1<=large_negative_num/2)) then

            interp_counters(3,interp_slot_1)=interp_counters(3,interp_slot_1)+1
            return

        end if

        d1_1=(y1_1-y0_1)/(x1_1-x0_1)
        d2_1=(y2_1-y1_1)/(x2_1-x1_1)

        denom_1=d2_1-d1_1

        ! Concavity. A non negative second difference means the argmax is not an
        ! interior maximum of the fit.
        if (denom_1>=-10.d0**(-14)) then

            interp_counters(3,interp_slot_1)=interp_counters(3,interp_slot_1)+1
            return

        end if

        vertex_1=0.5d0*(x0_1+x1_1)-0.5d0*d1_1*(x2_1-x0_1)/denom_1

        if ((vertex_1<x0_1) .OR. (vertex_1>x2_1)) then

            interp_counters(3,interp_slot_1)=interp_counters(3,interp_slot_1)+1
            return

        end if

        if (vertex_1>=x1_1) then

            interp_neighbour_1=opt_1+1
            interp_frac_1=(vertex_1-x1_1)/(x2_1-x1_1)

        else

            interp_neighbour_1=opt_1-1
            interp_frac_1=(x1_1-vertex_1)/(x1_1-x0_1)

        end if

        interp_frac_1=max(min(interp_frac_1,1.d0),0.d0)

        if (interp_frac_1>0.d0) then

            interp_counters(4,interp_slot_1)=interp_counters(4,interp_slot_1)+1

        end if

    end subroutine

    subroutine report_asset_lottery()

    ! WHETHER THE LOTTERY IS DOING ANYTHING, which decides whether the asset
    ! grid can be cut.
    !
    ! The case for a coarse grid is that the lottery puts a' where the grid
    ! cannot, so coarseness stops costing accuracy. That case is worth nothing
    ! unless the lottery FIRES, and it can fail to fire for reasons that leave
    ! no other trace: the branch guard refusing on most calls, or the objective
    ! not being locally concave at the argmax. So the shares are read before
    ! the grid is touched, not after.
    !
    ! Read it as: a fire share near one means the grid is now the wrong place
    ! to spend points and can be cut. A large branch mismatch share means the
    ! guard is refusing rather than the geometry, and the fix is to fill the
    ! vectors from the winning branch, not to cut the grid. A large "other"
    ! share is the geometry itself and no amount of guard work will help.

    implicit none

    integer(8) :: calls_1,mism_1,other_1,fire_1
    integer :: slot_index_1

    calls_1=0
    mism_1=0
    other_1=0
    fire_1=0

    do slot_index_1=1,max_CPUs

        calls_1=calls_1+interp_counters(1,slot_index_1)
        mism_1=mism_1+interp_counters(2,slot_index_1)
        other_1=other_1+interp_counters(3,slot_index_1)
        fire_1=fire_1+interp_counters(4,slot_index_1)

    end do

    write(*,*) "-------- asset lottery --------"
    write(*,*) "calls                 = ", calls_1

    if (calls_1<=0) then

        write(*,*) "the lottery was never called"
        write(*,*) "------------------------------"
        return

    end if

    write(*,*) "fired                 = ", fire_1, dble(fire_1)/dble(calls_1)
    write(*,*) "refused branch match  = ", mism_1, dble(mism_1)/dble(calls_1)
    write(*,*) "refused geometry      = ", other_1, dble(other_1)/dble(calls_1)
    write(*,*) "------------------------------"

    end subroutine

    subroutine reset_asset_lottery_counters()

    ! Called before a value function solve so the shares describe THAT solve
    ! and not the accumulation of every solve since the program started.

    implicit none

    interp_counters=0

    end subroutine

    real(8) function survival_with_smi(base_survival_1,smi_1)

        ! eq:fsurv. survival_probability already carries age, homelessness and
        ! the SUD; SMI multiplies the death HAZARD on top of that:
        !
        !     s' = s ** kappa_phi_m
        !
        ! Hazards multiply, so exponents on survival multiply, and the result is
        ! bounded in [0,1] without a guard.

        implicit none

        real(8), intent(in) :: base_survival_1
        integer, intent(in) :: smi_1

        if ((number_of_smi_states==1) .OR. (smi_1<=0)) then

            survival_with_smi=base_survival_1
            return

        end if

        ! ON THE HAZARD, like the other two. The comment above described taking
        ! the hazard out, multiplying and putting it back, but 1-(1-s)*kappa
        ! multiplies the death PROBABILITY, which is a different object once the
        ! baseline stops being small.
        ! ON THE DEATH PROBABILITY TOO, for the same reason and capped the same
        ! way. Leaving this one as an exponent while the other three multiply
        ! would give a mentally ill household a different kind of penalty from
        ! the one the disorder and homelessness carry, which is the fault this
        ! block already records one level up.
        survival_with_smi=1.d0-min(1.d0,kappa_phi_m*(1.d0-base_survival_1))

    end function

    real(8) function recovery_with_smi(base_recovery_1,smi_1)

        ! mu_m in eq:frecover. SMI lowers the SUD recovery hazard: dual diagnosis
        ! relapse runs 39.8 against 26.4 percent, so mu_m is below one.

        implicit none

        real(8), intent(in) :: base_recovery_1
        integer, intent(in) :: smi_1

        if ((number_of_smi_states==1) .OR. (smi_1<=0)) then

            recovery_with_smi=base_recovery_1
            return

        end if

        recovery_with_smi=max(min(base_recovery_1*mu_m,1.d0),0.d0)

    end function

    real(8) function smi_transition(current_m_1,future_m_1,sud_1,age_1)

            ! eq:fonset. Onset is multiplied by iota when the household carries the
            ! SUD, which is the channel that makes a SUD raise the hazard of SMI.
            ! Leaving the state is lambda_m and does not depend on the SUD, on
            ! housing, or on anything chosen.
            !
            ! The chain does NOT depend on housing, and that is a finding rather than
            ! an omission: At Home / Chez Soi randomised 1,198 homeless adults with
            ! SMI and found no detectable effect of housing on symptom severity at
            ! any wave. Do not add a housing argument to this function.

            implicit none

            integer, intent(in) :: current_m_1,future_m_1,sud_1,age_1
            real(8) :: onset_1

            if (number_of_smi_states==1) then

                smi_transition=1
                return

            end if

            if (current_m_1==1) then

                if (future_m_1==0) then

                    smi_transition=lambda_m

                else

                    smi_transition=1-lambda_m

                end if

                return

            end if

            onset_1=smi_onset_by_age(min(max(age_1,1),life_span))

            if (sud_1>=1) then

                onset_1=min(onset_1*iota_smi,1.d0)

            end if

            if (future_m_1==1) then

                smi_transition=onset_1

            else

                smi_transition=1-onset_1

            end if

        end function

        real(8) function employment_transition(e_c_1,e_f_1,d_f_1,m_f_1,h_1,p_1,iph_1)

            ! The employment leg of the joint transition, keyed on the FUTURE
            ! disorder state, which is the existing convention: a household that
            ! acquires the SUD this period faces the addicted margins on the way in,
            ! and one that recovers faces the clean margins. h_1 is 1 housed, 2
            ! homeless.

            implicit none

            integer, intent(in) :: e_c_1,e_f_1,d_f_1,m_f_1,h_1,p_1
            real(8), intent(in) :: iph_1
            real(8) :: sep_1,find_1

            if (d_f_1>=1) then

                sep_1=probability_becoming_unemployed_if_addicted
                find_1=probability_becoming_employed_if_addicted

            else

                sep_1=probability_becoming_unemployed
                find_1=probability_becoming_employed

            end if

            ! SMI worsens both margins, in the same direction and by the same
            ! convention as the SUD multiplier: it multiplies separation and divides
            ! job finding, so kappa_uem greater than one is unambiguously worse.
            if (m_f_1>=1) then

                sep_1=sep_1*kappa_uem
                find_1=find_1/kappa_find_smi

            end if

            if (h_1==2) then

                ! THE STREET'S LABOUR-MARKET PENALTY. THIS IS THE LIVE SITE.
                !
                ! number_of_smi_states is 2, so build_unemployment_process_smi and
                ! this function are what the model actually uses; the hand-written
                ! block in create_unemployment_process is the one that gets
                ! VERIFIED against, not the one that runs. homeless_job_penalty_pp
                ! was added there and nowhere else, so delta 0.05, 0.30 and 0.55
                ! produced identical output -- the live path never saw it.
                !
                ! In POINTS, which is the author's form: *"if the chance went up 10
                ! p.p., you reduce the chance of regaining by 10 p.p. too (capped
                ! below at 0%)"*. It applies exactly here, because sep_1 and find_1
                ! are already node-level rates -- no productivity tilt to correct
                ! for, and the caps are the real probability bounds.
                ! DELTA ACTS ON SEPARATION ONLY, on the author's instruction of
                ! 5 September: *"apply delta only to the separation rate when
                ! homeless but not to the reattachment when homeless... That should
                ! deter the employed but not the unemployed"*.
                !
                ! WHY THE TWO SIDES ARE NOT SYMMETRIC IN WHO THEY HIT. Measured:
                ! removing the job-finding penalty entirely, iph 0.2 -> 0, raises
                ! homelessness among the UNEMPLOYED five-fold, 0.00092 to 0.00468,
                ! and takes it from 0.147 of the working-age rate to 0.724. The
                ! finding side costs an unemployed household eleven points of the
                ! ONLY asset it has -- its re-employment prospect is essentially
                ! its whole expected future income -- while the separation side
                ! costs an employed household 0.3 points of a small probability.
                ! So a symmetric penalty prices the poor OFF the street and leaves
                ! the comfortable on it, which is why every bracket that raised one
                ! moved the income of the homeless the WRONG way.
                !
                ! Adding delta to the separation side rather than replacing the
                ! multiplicative form also makes the parameter CONTINUOUS at zero.
                ! It was not: delta = 0 took the multiplicative branch with
                ! iph = 0.2 and imposed a STRONGER job-finding penalty than
                ! delta = 0.001 took with the pp branch, so the function ran
                ! backwards across the origin and the delta = 0 comparison was a
                ! branch switch rather than economics.
                sep_1=min(sep_1*(1+iph_1+extra_job_loss_if_homeless)+&
                    homeless_job_penalty_pp,1.d0)
                    
                find_1=find_1*(1-iph_1)

            end if

            sep_1=sep_1*adjusted_probability(p_1)

            sep_1=max(min(sep_1,1.d0),0.d0)
            find_1=max(min(find_1,1.d0),0.d0)

            employment_transition=0

            if (e_c_1==1) then

                if (e_f_1==2) employment_transition=sep_1*(1-probability_of_ui)
                if (e_f_1==3) employment_transition=sep_1*probability_of_ui
                if (e_f_1==1) employment_transition=1-sep_1

            else

                ! Out of work, with or without UI. Finding a job returns to 1.
                !
                ! UI IS A FIRST PERIOD BENEFIT, AND THE SPELL HAS TO LEAVE STATE
                ! 3 FOR THAT TO BE TRUE. State 3 is insured unemployment and
                ! state 2 pays nothing, so continuing the spell in the SAME
                ! state, which is what this branch used to do for both, paid the
                ! benefit again in every period of an unbroken spell. The
                ! comment here asserted the opposite -- that staying put "keeps
                ! UI a first period only benefit" -- which is exactly backwards:
                ! with probability_of_ui at one every job loser enters state 3
                ! and never left it, so state 2 carried no mass and unemployment
                ! was insured for life. That is not the programme, and it is not
                ! what Section 4.10 of the paper says the model does.
                !
                ! An unbroken spell therefore steps 1 -> 3 -> 2 -> 2 -> ...:
                ! insured in the first period out of work, nothing after it.
                if (e_f_1==1) then

                    employment_transition=find_1

                elseif ((ui_first_period_only==1) .AND. (e_c_1==3)) then

                    if (e_f_1==2) employment_transition=1-find_1

                elseif (e_f_1==e_c_1) then

                    employment_transition=1-find_1

                end if

            end if

        end function

        ! The slope the household actually responds to, which is the perceived
        ! one. Kept beside the transition so the two cannot drift apart if the
        ! perception wedge is ever reopened.
        real(8) function addiction_transition_slope(current_1,choice_1,drug_quantity_1)

            implicit none

            integer, intent(in) :: current_1,choice_1
            real(8), intent(in) :: drug_quantity_1

            if ((smooth_addiction_hazard==0) .OR. (include_addiction==0) .OR. &
                (include_probability_of_becoming_addicted==0) .OR. (current_1>=1) .OR. &
                (choice_1==0)) then

                addiction_transition_slope=0

                return

            end if

            addiction_transition_slope=&
                difference_in_perceived_of_becoming_addicted_if_experiment*&
                addiction_onset_hazard_slope(drug_quantity_1)

        end function

	end module Global_Vars
    
    program main_program

        use Global_Vars
        
        use omp_lib
        
        implicit none
        
        fraction_to_repay=0
        
        do i=1,mortgage_amortization
        
            fraction_to_repay=fraction_to_repay+(1/(1+risk_free_rate_data+mortgage_interest_gap)**(i))
        
        end do
        
        fraction_to_repay=(1/fraction_to_repay)-(risk_free_rate_data+mortgage_interest_gap)
        
        prepayment_penalty_starts_from=0.15*(1+fraction_to_repay+risk_free_rate_data+mortgage_interest_gap)+fraction_to_repay
                                                
        if (is_counterfactual==1) then
            
            large_negative_num=-1.7976931348623157E+10 !-HUGE(a_real_number)
            
        else
        
            large_negative_num=-1.7976931348623157E+10
            
        end if
                        
        write(*,*) "large_negative_num=", large_negative_num
        
        simulation_ended=1
        already_uploaded_benchmark=0
        
        call set_files_names()
                                     
        if (is_counterfactual==0) then
                                    
            call calibrating_model()
                
            call write_outputs(1)
                
        elseif ((is_counterfactual==1) .AND. (solve_transition_dynamics==0)) then
        
            call long_run_counter_factual()
            
            call write_outputs(transition_length)
                        
        elseif ((is_counterfactual==1) .AND. (solve_transition_dynamics==1)) then
        
            call transition_simulation()
            
            call write_outputs(1)
                        
        end if
        
        call cleanup_matrix()
                                
    end program main_program
    
    subroutine set_files_names()
    
        use Global_Vars
        
        implicit none
                                                                    
        if (is_counterfactual==0) then
                
            file_number='baseline_benchmark'
            old_results=file_number
            benchmark_simulation=file_number
            long_run_simulation=file_number
            old_transition_resuls=file_number
            
        else
        
            old_results='baseline_benchmark'  
            
            if (relative_price_change==0.02) then
            
                file_number='counter_price_change_002'
            
            elseif (relative_price_change==0.05) then
            
                file_number='counter_price_change_005'
                
            elseif (relative_price_change==0.1) then
            
                file_number='counter_price_change_010'
                
            elseif (relative_price_change==0.2) then
            
                file_number='counter_price_change_020'
                
            elseif (relative_price_change==0.5) then
            
                file_number='counter_price_change_050'
                
            elseif (relative_price_change==-0.02) then
            
                file_number='counter_price_change_-002'
                
            elseif (relative_price_change==-0.05) then
            
                file_number='counter_price_change_-005'
                
            elseif (relative_price_change==-0.1) then
            
                file_number='counter_price_change_-010'
                
            elseif (relative_price_change==-0.2) then
            
                file_number='counter_price_change_-020'
                
            elseif (relative_price_change==-0.5) then
            
                file_number='counter_price_change_-050'
                
            end if
                                    
            ! universal plus treatment first
            if ((probability_of_voucher_benchmark_used==1) .AND. &
               (increased_prob_of_voucher_if_homeless_and_addicted==0)) then
               
                file_number='counter_VTE_TF'
               
                if (compare_to_original_benchmark==1) then
                
                    old_results='baseline_benchmark'
               
                else
               
                    old_results='baseline_benchmark'
                    file_number='counter_VTE_TF_relative_to_VTE_HF'
                    
                end if
                                               
            ! universal plus HF
            elseif ((probability_of_voucher_benchmark_used==1) .AND. &
                    (increased_prob_of_voucher_if_homeless_and_addicted==1)) then
                    
                file_number='counter_VTE_HF'
                old_results='baseline_benchmark'  
                
            elseif ((probability_of_voucher_benchmark_used<1) .AND. &
                    (increased_prob_of_voucher_if_homeless_and_addicted==0)) then
                    
                file_number='counter_TF'
                old_results='baseline_benchmark'  
            
            end if
            
            if (partial_equilibrium==1) then
                        
                file_number=trim(file_number)//'_PE'
                
                if (how_many_iterations_to_do_on_distribution==1) then
                
                    file_number=trim(file_number)//'_1_period'
                
                elseif (how_many_iterations_to_do_on_distribution==5) then
                
                    file_number=trim(file_number)//'_5_periods'
                
                elseif (how_many_iterations_to_do_on_distribution==100) then
                
                    file_number=trim(file_number)//'_100_periods'
                
                end if
            
            end if
                
            benchmark_simulation=old_results
            long_run_simulation=old_results
            old_transition_resuls=old_results
                        
        end if
            
    end subroutine
    
    subroutine calculate_income(unemployment_index_1,employment_index_1,&
        income_1,avg_income_to_use_1,avg_income_to_use_2,labor_supply_1,in_retirement_1)
    
        use global_vars
        
        implicit none
        
        real(8), intent(inout) :: income_1
        real(8), intent(in) :: avg_income_to_use_1,avg_income_to_use_2,labor_supply_1
        integer, intent(in) :: employment_index_1,in_retirement_1,unemployment_index_1
        
        income_1=0
        
        if (in_retirement_1==1) then
        
            if (unemployment_index_1<=threshold_addiction_index) then
            
                income_1=model_ss_benefits(employment_index_1)
        
            elseif ((sud_of(unemployment_index_1)==1 .AND. emp_of(unemployment_index_1)==1)) then
                            
                income_1=model_ss_benefits(employment_index_1)
                
            elseif ((sud_of(unemployment_index_1)==1 .AND. emp_of(unemployment_index_1)==2)) then
            
                income_1=(1-ss_decrease_for_retired_addicted)*model_ss_benefits(employment_index_1)+&
                    ss_decrease_for_retired_addicted*model_ss_benefits(employment_index_1)*(1-ss_decrease_addicted(1))
                
            elseif (((sud_of(unemployment_index_1)==1 .AND. emp_of(unemployment_index_1)==3)) .AND. (include_addiction==1)) then
            
                income_1=(1-ss_decrease_for_retired_addicted)*model_ss_benefits(employment_index_1)+&
                    ss_decrease_for_retired_addicted*model_ss_benefits(employment_index_1)*(1-ss_decrease_addicted(2))
                
            end if
            
        else
        
            ! THE THREE WORKING AGE CASES OF eq:fincome, IN THE NOTE'S ORDER.
            ! The note numbers the states e=1 work, e=2 the first period of a
            ! spell, e=3 non-employment after it; the code's emp_of numbers the
            ! insured state 3 and the uninsured state 2, so the note's e=2 is
            ! emp_of 3 here and the note's e=3 is emp_of 2. Only the labels
            ! differ.
            if ((emp_of(unemployment_index_1)==1)) then
                        
                income_1=labor_supply_1*&
                    employment_grid(age_index,employment_index_1)*&
                    labour_deterministic_efficiency(age_index)
                    
            else
            
                ! UI in the insured period, DI after it for a household with
                ! SMI, nothing otherwise. See out_of_work_income.
                income_1=out_of_work_income(unemployment_index_1,&
                    employment_index_1,avg_income_to_use_1)
            
            end if                             
                                    
        end if
        
    end subroutine
    
    subroutine calculate_cdf_of_incomes_earned(time_period,age_index_1)
    
        use Global_Vars
        
        implicit none
        
        integer, intent(in) :: time_period,age_index_1
        integer :: time_period_used,financial_index,location,previous_index,has_house
        integer, dimension(1) :: min_income_earned_index,quintile
        real(8) :: total_income,sum_of_distribution_1,sum_of_distribution_2,size_of_quintile=real(1)/real(number_of_quintiles)
        real(8) :: labor_supply_used,avg_income_to_use_1,avg_income_to_use_2,bequest_2,income_taxes_paid_1,&
            financial_income_1,home_equity_1

        ! STATIC STORAGE, BECAUSE THESE ACCUMULATE ACROSS THE TWO PASSES.
        !
        ! Each of these is reset only when accumulating_beta_types is zero,
        ! which is the first pass, and added to on every pass. That is the
        ! right shape for a counter that has to hold both discount-factor
        ! types -- but it is only correct if the value survives from one
        ! call to the next, and a local without save does not. On the
        ! second pass the routine is entered fresh, the reset is skipped,
        ! and the accumulation lands on whatever the stack holds.
        !
        ! It has been working by accident: the calls come from the same
        ! site in the same order, so the frame is usually reused and the
        ! slot usually still holds the first pass's value. That is not a
        ! guarantee, it is a property of this build. save makes it one.
        !
        ! These stay LOCAL rather than moving to module scope on purpose.
        ! total_homeless_1 is the name of two different locals in two
        ! different routines; merging them would pool two counts of the
        ! same population into one divisor.
        save :: sum_of_distribution_1, sum_of_distribution_2
        
        avg_income_to_use_1=is_counterfactual*average_labor_income_calibrated+&
            (1-is_counterfactual)*model_average_labour_income(time_period)
                   
        if (accumulating_beta_types==0) sum_of_distribution_2=0
        
        do i=1,2
        
            sum_of_distribution_2=sum_of_distribution_2+&
                sum(distribution_stationary(i)%vector_transition_real(time_period,1:age_index_1,:,:,:,:,:))
                
        end do
        
        if (accumulating_beta_types==0) sum_of_distribution_1=0
        
        time_period_used=time_period-solve_transition_dynamics
        
        if (accumulating_beta_types==0) model_mass_of_households_by_income_earned(time_period,:)=0
        if (accumulating_beta_types==0) model_incomes_earned(time_period,:)=-1
        
        ! THE LIST OF DISTINCT INCOME LEVELS IS POOLED ACROSS THE DISCOUNT-FACTOR
        ! TYPES, so the running count of levels has to survive the pass boundary.
        ! It cannot simply be left in i: i is the mortgage index of the loop just
        ! above, which clobbers it. Carry it in its own variable.
        if (accumulating_beta_types==0) then
            i=1
        else
            i=income_cdf_levels_used
        end if
        
!        write(*,*) "size_of_quintile=", size_of_quintile
        write(*,*) "computing incomes for cdf"
                              
        ages_loop_1: do age_index=1,(1-include_retirees_in_income_cdf)*&
            (life_span-retirement_span)+include_retirees_in_income_cdf*age_index_1
        
            if (age_index>(life_span-retirement_span)) then
            
                in_retirement=1
                
            else
            
                in_retirement=0
                
            end if
                        
            do years_left_on_mortgage_index=1,max_amortization_years
            
                if (years_left_on_mortgage_index>1) then
                    
                    has_house=1
                    
                else
                
                    has_house=0
                    
                end if
                                                                
                do financial_index=has_house*1+(1-has_house)*renter_floor_by_age(min(max(age_index,1),life_span)),financial_grid_size
                
                    do unemployment_index=1,unemployment_grid_size
                                                                       
                        do employment_index=1,employment_grid_size
                        
                            if (inheritance_function_of_productivity==1) then
                        
                                bequest_2=employment_grid(age_index,employment_index)*inheritance_amount(age_index)+&
                            newborn_age_transfer(age_index)
                                
                            else
                        
                                call calculate_bequest_amount(age_index,bequest_2,employment_index)
                                
                            end if
                        
                            avg_income_to_use_2=&
                                is_counterfactual*average_labor_income_by_employment_calibrated(employment_index)+&
                                (1-is_counterfactual)*model_average_labour_income_by_employment(time_period,employment_index)
                                
                            do voucher_index=0,(1-has_house)*include_vouchers
                            
                                do housing_status_index=(1-has_house)*lowest_housing_grid_point+&
                                    has_house*index_of_smallest_house_hhld_can_buy,housing_status_index-1
                            
                                    labor_supply_used=policy_function_labor_supply(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    income_taxes_paid_1=policy_function_wage_income_tax_paid(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    home_equity_1=max(years_left_on_mortgage_index-1,0)*housing_price(time_period)*&
                                        housing_size(housing_status_index)*(1+min(financial_grid(financial_index),0.d0))
                                    
                                    call calculate_income(unemployment_index,employment_index,total_income,&
                                        avg_income_to_use_1,avg_income_to_use_2,labor_supply_used,in_retirement)
                                                                                        
                                    financial_income_1=risk_free_rate(time_period)*&
                                        max(financial_grid(financial_index),0.d0)
                                                                                        
                                    total_income=total_income+bequest_2
                                                                            
                                    if (use_income_or_income_plus_assets==2) then
                                    
                                        total_income=total_income+financial_income_1+max(financial_grid(financial_index),0.d0)
                                        
                                    elseif (use_income_or_income_plus_assets<=4) then
                                    
                                        total_income=total_income+financial_income_1
!                                            +&
!                                            max(financial_grid(financial_index),0.d0)
!                                            -income_taxes_paid_1-financial_income_1*investment_income_tax
                                                                                
                                    end if
                                    
                                    if (use_income_or_income_plus_assets==4) then
                                    
                                        total_income=total_income+home_equity_1
                                        
                                    end if
                                                                             
                                    if (i==1) then
                                        
                                        location=i
                                        
                                    else
                                    
                                        location=-1    
                                            
                                    end if
                                                
                                    do j=1,i
                                        
                                        if (abs(model_incomes_earned(time_period,j)-total_income)<10.d0**(-6)) then
                                                
                                            location=j
                                                
                                        end if
                                            
                                    end do
                                    
                                    sum_of_distribution_1=sum_of_distribution_1+&
                                        distribution_stationary(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period_used,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                                            
                                    sum_of_distribution=distribution_stationary(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period_used,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                    
                                    if (sum_of_distribution>0) then
                                                                            
                                        if (i==1) then
                                                                                                                        
                                            model_mass_of_households_by_income_earned(time_period,location)=&
                                                model_mass_of_households_by_income_earned(time_period,location)+&
                                                sum_of_distribution
                                                    
                                            model_incomes_earned(time_period,location)=total_income
                                                
                                            i=i+1
                                            
                                        elseif ((i>1) .AND. (location==-1)) then
                                                
                                            model_mass_of_households_by_income_earned(time_period,i+1)=&
                                                model_mass_of_households_by_income_earned(time_period,i+1)+&
                                                sum_of_distribution
                                                    
                                            model_incomes_earned(time_period,i+1)=total_income
                                                
                                            i=i+1
                                            
                                        elseif ((i>1) .AND. (location>-1)) then
                                        
                                            model_mass_of_households_by_income_earned(time_period,location)=&
                                                model_mass_of_households_by_income_earned(time_period,location)+&
                                                sum_of_distribution
                                            
                                        end if
                                        
                                        if (sum_of_distribution_1==sum_of_distribution_2) then
                                        
                                            exit ages_loop_1
                                            
                                        end if
                                        
                                    end if
                                    
                                end do
                                    
                            end do
                            
                        end do
                                                                                         
                    end do
                    
                end do
                
            end do
            
        end do ages_loop_1

        income_cdf_levels_used=i
        
        model_incomes_earned_saved(time_period,:)=model_incomes_earned(time_period,:)
        
        model_cdf_of_income_earned(time_period,:)=0
        
        i=1
        previous_index=1
        
        quintile=1
        mass_of_quintile(:)=0
        
        sum_of_distribution_1=0
                        
        do k=1,2
        
            sum_of_distribution_1=sum_of_distribution_1+&
                sum(distribution_stationary(k)%vector_transition_real(time_period_used,1:&
                (include_retirees_in_income_cdf*age_index_1+&
                (1-include_retirees_in_income_cdf)*(life_span-retirement_span)),:,:,:,:,:))
                
        end do
        
        write(*,*) "computing incomes at each quintile"
        
        do while (i<=(age_index_1*financial_grid_size*unemployment_grid_size*employment_grid_size*years_left_on_mortgage_index))
                        
            min_income_earned_index=minloc(model_incomes_earned(time_period,:),mask=model_incomes_earned(time_period,:)>=0)
                
            if (min_income_earned_index(1)>0) then
            
                if (model_mass_of_households_by_income_earned(time_period,min_income_earned_index(1))>0)  then
                                                                                                    
                    model_cdf_of_income_earned(time_period,min_income_earned_index(1))=&
                        model_cdf_of_income_earned(time_period,previous_index)+&
                        model_mass_of_households_by_income_earned(time_period,min_income_earned_index(1))/sum_of_distribution_1
                                                            
                    if (sum(model_cdf_of_income_earned(time_period,:))>0) then
                    
                        mass_of_quintile(quintile)=mass_of_quintile(quintile)+&
                            model_mass_of_households_by_income_earned(time_period,min_income_earned_index(1))
                    
                        if (floor(model_cdf_of_income_earned(time_period,min_income_earned_index(1))/size_of_quintile)>&
                            floor(model_cdf_of_income_earned(time_period,previous_index)/size_of_quintile) .AND. &
                            (model_cdf_of_income_earned(time_period,previous_index)<0.999)) then
                                            
                            income_cutoffs_of_quintiles(quintile)=model_incomes_earned(time_period,min_income_earned_index(1))
                            
                            quintile=quintile+1
                                                    
                        end if
                                                
                    end if
                                    
                    previous_index=min_income_earned_index(1)
                    
                end if
                
                if (model_cdf_of_income_earned(time_period,min_income_earned_index(1))>=0.9999) then
            
                    i=age_index_1*financial_grid_size*unemployment_grid_size*&
                        employment_grid_size*years_left_on_mortgage_index+1
                
                end if
                
                model_incomes_earned(time_period,min_income_earned_index(1))=-1
                                    
            end if
                    
            i=i+1
                                                        
        end do
                 
        model_incomes_earned(time_period,:)=model_incomes_earned_saved(time_period,:)
                
!        write(*,*) "sum(model_mass_of_households_by_income_earned(time_period,:)=", &
!            sum(model_mass_of_households_by_income_earned(time_period,:))
                
        do i=1,number_of_quintiles
            
            write(*,*) "mass_of_quintile(i)=", mass_of_quintile(i)
            
        end do
        
!        write(*,*) "sum(mass_of_quintile)=", sum(mass_of_quintile(:))
                    
    end subroutine
               
    subroutine stationary_equilibrium_statistics(time_period)
    
        use Global_Vars
        
        implicit none
        
        integer :: financial_index,time_period,pay_mortgage_insurance_1,has_house,low_quality_market,is_homeless_1,&
            is_addicted_1,time_period_used,housing_status_index_used,financial_index_used,amortization_used,fin_frac_used,&
            is_using_drugs,smi_age_1,earnings_bin_index
        real(8) :: total_income,lived_in_size_used,labor_supply_used,value_function_used,&
            distribution_mass_used,frac_used,rent_to_income,income_to_avg_income,total_renters_to_consider,&
            bequest_1,bequest_2,housing_to_income_owners,housing_to_income_all,mortgage_to_income_owners,&
            housing_to_income_renters,total_owners_to_consider,LTV_1,avg_income_to_use_1,avg_income_to_use_2,&
            total_homeless_1,assets_1,food_stamps_1,avg_net_wealth_to_use_1,MU_1,consumption_used,addiction_consumption_1,&
            total_consumption_used,net_wealth_1,model_average_income_previous,model_average_income_plus_assets_previous,&
            model_average_income_plus_all_assets_previous,earnings_1
            
        integer, dimension(1) :: rent_to_income_index,LTV_index,median_index,income_to_avg_income_wide_index

        ! STATIC STORAGE, BECAUSE THESE ACCUMULATE ACROSS THE TWO PASSES.
        !
        ! Each of these is reset only when accumulating_beta_types is zero,
        ! which is the first pass, and added to on every pass. That is the
        ! right shape for a counter that has to hold both discount-factor
        ! types -- but it is only correct if the value survives from one
        ! call to the next, and a local without save does not. On the
        ! second pass the routine is entered fresh, the reset is skipped,
        ! and the accumulation lands on whatever the stack holds.
        !
        ! It has been working by accident: the calls come from the same
        ! site in the same order, so the frame is usually reused and the
        ! slot usually still holds the first pass's value. That is not a
        ! guarantee, it is a property of this build. save makes it one.
        !
        ! These stay LOCAL rather than moving to module scope on purpose.
        ! total_homeless_1 is the name of two different locals in two
        ! different routines; merging them would pool two counts of the
        ! same population into one divisor.
        save :: total_homeless_1, total_renters_to_consider, total_owners_to_consider
                
        avg_income_to_use_1=is_counterfactual*average_labor_income_calibrated+&
            (1-is_counterfactual)*model_average_labour_income(time_period)
            
        avg_net_wealth_to_use_1=is_counterfactual*average_net_wealth_calibrated+&
            (1-is_counterfactual)*model_average_net_wealth(time_period)
                                    
        time_period_used=time_period-solve_transition_dynamics
        
        if (accumulating_beta_types==0) rent_to_income_cdf(time_period,:)=0
                        
        if (accumulating_beta_types==0) income_to_avg_income_wide_pdf_1(time_period,:)=0
        
        if (accumulating_beta_types==0) median_income_cdf(time_period,:)=0
        if (accumulating_beta_types==0) rent_to_income_homeless_cdf(time_period,:)=0
        if (accumulating_beta_types==0) total_homeless_1=0
        if (accumulating_beta_types==0) LTV_cdf(time_period,:)=0
        if (accumulating_beta_types==0) total_renters_to_consider=0
        if (accumulating_beta_types==0) total_owners_to_consider=0
        
        if (accumulating_beta_types==0) model_total_net_wealth(time_period)=0
        if (accumulating_beta_types==0) wealth_hist_mass=0
        if (accumulating_beta_types==0) wealth_hist_wealth=0
        if (accumulating_beta_types==0) income_hist_mass=0
        if (accumulating_beta_types==0) income_hist_sud=0
        if (accumulating_beta_types==0) income_hist_income=0
        if (accumulating_beta_types==0) earnings_hist_mass=0
        if (accumulating_beta_types==0) earnings_hist_earnings=0
        if (accumulating_beta_types==0) diag_mass_top_financial=0
        if (accumulating_beta_types==0) diag_mass_top3_financial=0
        if (accumulating_beta_types==0) model_youngest_net_wealth_share(time_period)=0
        if (accumulating_beta_types==0) model_net_wealth_owners(time_period)=0
        if (accumulating_beta_types==0) model_net_wealth_renters(time_period)=0
        if (accumulating_beta_types==0) model_total_owners(time_period)=0
        if (accumulating_beta_types==0) model_total_renters(time_period)=0
        if (accumulating_beta_types==0) model_financial(time_period)=0
        if (accumulating_beta_types==0) model_mass_with_positive_financial(time_period)=0
        if (accumulating_beta_types==0) model_average_financial(time_period)=0
        if (accumulating_beta_types==0) model_financial_renters(time_period)=0
        if (accumulating_beta_types==0) model_output(time_period)=0
        if (accumulating_beta_types==0) model_total_income(time_period)=0
        if (accumulating_beta_types==0) model_total_efficiency_units(time_period)=0
        if (accumulating_beta_types==0) model_labor_supply(time_period)=0
        if (accumulating_beta_types==0) model_fraction_choose_zero_work(time_period)=0
        if (accumulating_beta_types==0) model_fraction_choose_little_work(time_period)=0
        if (accumulating_beta_types==0) model_mass_can_work(time_period)=0
        if (accumulating_beta_types==0) model_total_hours(time_period)=0
        if (accumulating_beta_types==0) model_net_housing_wealth(time_period)=0
        if (accumulating_beta_types==0) model_gross_housing_wealth(time_period)=0
        if (accumulating_beta_types==0) model_mortgages(time_period)=0
        if (accumulating_beta_types==0) model_bequests(time_period)=0
        if (accumulating_beta_types==0) model_total_inheritance(time_period)=0
        if (accumulating_beta_types==0) value_of_bequests_by_age(:)=0
        if (accumulating_beta_types==0) bequests_mass_by_age(:)=0
        if (accumulating_beta_types==0) model_youngest_assets(time_period)=0
        if (accumulating_beta_types==0) model_financial_bequests(time_period)=0
        if (accumulating_beta_types==0) model_fraction_leaving_bequests(time_period)=0
        if (accumulating_beta_types==0) model_fraction_leaving_housing_bequests(time_period)=0
        if (accumulating_beta_types==0) mass_dying(time_period)=0
        if (accumulating_beta_types==0) total_renters_income(time_period)=0
        if (accumulating_beta_types==0) mass_of_owners(time_period)=0
        if (accumulating_beta_types==0) mass_of_legit_renters(time_period)=0
        if (accumulating_beta_types==0) model_avg_rent_to_income_ratio(time_period)=0
        if (accumulating_beta_types==0) model_avg_mortgage_spending(time_period)=0
        if (accumulating_beta_types==0) model_avg_housing_spending_owners(time_period)=0
        if (accumulating_beta_types==0) model_avg_housing_spending_all(time_period)=0
        if (accumulating_beta_types==0) model_avg_housing_spending_renters(time_period)=0
        if (accumulating_beta_types==0) model_mass_renters_to_consider(time_period)=0
        if (accumulating_beta_types==0) model_fraction_homeless(time_period)=0
        if (accumulating_beta_types==0) model_homeless_2_years_or_more(time_period)=0
        if (accumulating_beta_types==0) profile_of_chronic_homeless(time_period,:)=0
        if (accumulating_beta_types==0) mass_profile_of_chornic_homeless(time_period,:)=0
        if (accumulating_beta_types==0) model_homelessness_old(time_period)=0
        if (accumulating_beta_types==0) model_profile_of_homeless_old(:)=0
        if (accumulating_beta_types==0) model_addiction_by_employment(:)=0
        if (accumulating_beta_types==0) model_fraction_homeless_owners(time_period)=0
        if (accumulating_beta_types==0) model_fraction_of_homeless_unemployed(time_period)=0
        if (accumulating_beta_types==0) model_fraction_addicted_who_are_homeless(time_period)=0
        if (accumulating_beta_types==0) model_fraction_of_unemployed_homeless(time_period)=0
        if (accumulating_beta_types==0) model_fraction_of_homeless_and_addicted_unemployed(time_period)=0
        if (accumulating_beta_types==0) model_mass_homeless_raw(time_period)=0
        if (accumulating_beta_types==0) model_mass_homeless_working_age(time_period)=0
        if (accumulating_beta_types==0) model_mass_total_raw(time_period)=0
        if (accumulating_beta_types==0) model_mass_smi(time_period)=0
        if (accumulating_beta_types==0) model_smi_mass_by_age(:)=0
        if (accumulating_beta_types==0) model_mass_by_age(:)=0
        if (accumulating_beta_types==0) model_users_by_age(:)=0
        if (accumulating_beta_types==0) model_alive_by_age(:)=0
        if (accumulating_beta_types==0) newborn_parent_share_acc(:,:,:)=0
        if (accumulating_beta_types==0) model_smi_and_homeless(time_period)=0
        if (accumulating_beta_types==0) model_smi_and_employed(time_period)=0
        if (accumulating_beta_types==0) model_homeless_labour_income(time_period)=0
        if (accumulating_beta_types==0) model_all_labour_income(time_period)=0
        if (accumulating_beta_types==0) model_smi_share_of_homeless(time_period)=0
        if (accumulating_beta_types==0) model_employment_rate_given_smi(time_period)=0
        if (accumulating_beta_types==0) model_homeless_income_share(time_period)=0
        if (accumulating_beta_types==0) model_employed_share_of_homeless(time_period)=0

        if (accumulating_beta_types==0) model_fraction_unemployed(time_period)=0
        if (accumulating_beta_types==0) model_fraction_unemployed_on_ui(time_period)=0
        if (accumulating_beta_types==0) model_sum_of_lowest_productivities(time_period)=0
        if (accumulating_beta_types==0) model_median_assets_to_income(:)=0
        
        if (accumulating_beta_types==0) model_fraction_addicted(time_period)=0
        if (accumulating_beta_types==0) model_fraction_addicted_and_unemployed(time_period)=0
        if (accumulating_beta_types==0) model_fraction_homeless_and_addicted(time_period)=0
        
        if (accumulating_beta_types==0) model_value_of_life(time_period)=0
        if (accumulating_beta_types==0) model_fraction_with_negative_value_of_life(time_period)=0
        if (accumulating_beta_types==0) model_fraction_homeless_with_negative_value_of_life(time_period)=0
        if (accumulating_beta_types==0) model_fraction_addicted_with_negative_value_of_life(time_period)=0
        ! A MINIMUM TRACKER. Resetting on the second pass discards the patient type's
        ! minimum entirely, so the printed lowest value of a period of life was the
        ! impatient type's alone. Its maximum-tracker twin one line away IS guarded,
        ! which is what makes this an oversight rather than a decision.
        if (accumulating_beta_types==0) model_largest_negative_value_of_life(time_period)=10000000
        
        if (accumulating_beta_types==0) profile_by_income_to_avg_income_wide_1(time_period,:,:,:)=0
        if (accumulating_beta_types==0) mass_at_profile_income_to_avg_income_wide_1(time_period,:,:)=0
                
        do i=1,number_of_grids_rent_to_income_cdf
        
            rent_to_income_ratios(time_period,i)=(real(i)-real(1))/real(100)
                    
        end do
                
        do i=1,number_of_wide_grids_income_to_avg_income_cdf
        
            income_to_avg_income_wide_ratios(time_period,i)=(real(i)*40)/real(100)
                    
        end do
        
        do i=1,101
        
            LTV_ratios(time_period,i)=(real(i)-real(1))/real(100)
            
        end do
        
        if (accumulating_beta_types==0) model_total_workers(time_period)=0
        
        model_average_income_previous=model_average_income(time_period)
        model_average_income_plus_assets_previous=model_average_income_plus_assets(time_period)
        model_average_income_plus_all_assets_previous=model_average_income_plus_all_assets(time_period)
                
        if (accumulating_beta_types==0) model_average_labour_income(time_period)=0
        if (accumulating_beta_types==0) model_average_income(time_period)=0
        if (accumulating_beta_types==0) model_average_income_plus_assets(time_period)=0
        if (accumulating_beta_types==0) model_average_income_plus_all_assets(time_period)=0
        if (accumulating_beta_types==0) model_average_ss_benefits(time_period)=0
        
        if (accumulating_beta_types==0) model_average_labour_income_by_employment(time_period,:)=0
        if (accumulating_beta_types==0) mass_by_employment(time_period,:)=0
        
        if (accumulating_beta_types==0) total_rent_paid(time_period)=0
        if (accumulating_beta_types==0) total_imputed_rents(time_period)=0
          
        ! BOTH HALVES OF A RATIO, unguarded together. The ratio was internally consistent
        ! but described only the LAST TYPE SOLVED, which matters because the age
        ! profile of housing is what is being read.
        if (accumulating_beta_types==0) average_rent_by_age=0
        ! The denominator of the pair above.
        if (accumulating_beta_types==0) mass_of_renters_by_age=0
        
        if (accumulating_beta_types==0) sum_of_distribution_not_be_homeless=0
                             
        do age_index=1,life_span
        
            if (age_index>(life_span-retirement_span)) then
            
                in_retirement=1
                
            else
            
                in_retirement=0
                
            end if
                                    
            if (age_index==1) then
            
                newborn_household=1
                
            else
            
                newborn_household=0
            
            end if
                    
            do years_left_on_mortgage_index=1,max_amortization_years
                            
                if (years_left_on_mortgage_index>1) then
                    
                    has_house=1
                    
                else
                
                    has_house=0
                    
                end if
                                                
                do unemployment_index=1,unemployment_grid_size
                
                    do employment_index=1,employment_grid_size
                    
                        if (inheritance_function_of_productivity==1) then
                        
                            bequest_2=employment_grid(age_index,employment_index)*inheritance_amount(age_index)+&
                            newborn_age_transfer(age_index)
                            
                        else
                    
                            call calculate_bequest_amount(age_index,bequest_2,employment_index)
                            
                        end if
                    
                        avg_income_to_use_2=is_counterfactual*average_labor_income_by_employment_calibrated(employment_index)+&
                            (1-is_counterfactual)*model_average_labour_income_by_employment(time_period,employment_index)
                        
                        do voucher_index=0,(1-has_house)*include_vouchers
                            
                            do financial_index=has_house*1+(1-has_house)*renter_floor_by_age(min(max(age_index,1),life_span)),financial_grid_size
                                               
                                do housing_status_index=(1-has_house)*lowest_housing_grid_point+&
                                    has_house*index_of_smallest_house_hhld_can_buy,housing_status_grid_size-1
                                                                                            
                                    lived_in_size_used=policy_function_space_lived_in_size(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                                                    
                                    housing_status_index_used=policy_function_housing_status_index(years_left_on_mortgage_index)%&
                                        vector_transition_integer(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                                                            
                                    financial_index_used=policy_function_financial_index(years_left_on_mortgage_index)%&
                                        vector_transition_integer(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                            
                                    amortization_used=policy_function_years_of_amortization_index(years_left_on_mortgage_index)%&
                                        vector_transition_integer(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                                                            
                                    frac_used=frac_mov_optimal_1(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    fin_frac_used=fin_index_frac_mov_to_optimal(years_left_on_mortgage_index)%&
                                        vector_transition_integer(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    labor_supply_used=policy_function_labor_supply(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    if ((labor_supply_used>1) .OR. (labor_supply_used<0)) then
                                    
                                        write(*,*) "weird"
                                        
                                    end if
                                        
                                    consumption_used=policy_function_consumption(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    total_consumption_used=policy_function_total_consumption(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                                                            
                                    addiction_used=policy_function_addiction(years_left_on_mortgage_index)%&
                                        vector_transition_integer(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                                                            
                                    addiction_consumption_1=0
                                        
                                    if (addiction_used>0) then
                                        
                                        addiction_consumption_1=&
                                            max(total_consumption_used-consumption_used,0.d0)
                                            
                                    end if
                                        
                                    value_function_used=value_function(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    distribution_mass_used=distribution_stationary(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period_used,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    assets_1=2*threshold_for_food_stamps_as_perc_of_average_net_wealth*&
                                        avg_net_wealth_to_use_1
                                        
                                    if (unemployment_index>threshold_addiction_index) then
                                        
                                        model_addiction_by_employment(employment_index)=&
                                            model_addiction_by_employment(employment_index)+distribution_mass_used
                                            
                                    end if
                                    
                                    ! This one is a homeowner who chooses to rent
                                    if ((years_left_on_mortgage_index>1) .AND. (amortization_used==1)) then

                                        assets_1=max(housing_price(time_period)*housing_size(housing_status_index)*&
                                            (1-cost_of_selling-property_tax(time_period)-&
                                            housing_depreciation_rate+min(financial_grid(financial_index),0.d0)*&
                                            (1+mortgage_interest_rate(time_period)))+&
                                            max(financial_grid(financial_index),0.d0),0.d0)
                                
                                    ! This one is a renter who stays renting
                                    elseif ((years_left_on_mortgage_index==1) .AND. (amortization_used==1)) then
                                    
                                        assets_1=max(financial_grid(financial_index),0.d0)

                                    end if
                                    
                                    food_stamps_1=0
                                    
                                    ! If they have no assets, they get can qualift for food stamps
                                    if (assets_1<threshold_for_food_stamps_as_perc_of_average_net_wealth*&
                                        avg_net_wealth_to_use_1) then
                                        
                                        call calculate_income(unemployment_index,employment_index,total_income,&
                                            avg_income_to_use_1,avg_income_to_use_2,labor_supply_used,in_retirement)
                                        
                                        food_stamps_1=snap_benefit(actual_household_size(age_index),&
                                            total_income+max(financial_grid(financial_index),0.d0)*&
                                            risk_free_rate(time_period),avg_income_to_use_1)
                                                                    
                                    end if
                                    
                                    if (in_retirement==1) then
                                    
                                        model_average_ss_benefits(time_period)=&
                                            model_average_ss_benefits(time_period)+&
                                            total_income*distribution_mass_used
                                    
                                    end if
                                    
                                    if (age_index==1) then
                                    
                                        ! THE CALL SITS INSIDE THE MASS GUARD IT USED TO SIT
                                        ! OUTSIDE OF. Evaluated at every age-one cell, it raised
                                        ! 0**(-risk_aversion) at zero-mass corners where the cell
                                        ! is infeasible and consumption or the dwelling is zero --
                                        ! the Inf was then discarded by the guard below, so no
                                        ! number ever moved, but the flags it raised are noise and
                                        ! they stopped the -ffpe-trap sweep here. MU_1 feeds only
                                        ! the massed accumulation, so calling only on mass is the
                                        ! same number with a clean FPU.
                                        if (distribution_mass_used>0) then
                                                                    
                                            call calculate_marginal_non_housing_utility&
                                                (consumption_used,lived_in_size_used,addiction_used,&
                                                addiction_consumption_1,MU_1)
                                            
                                            model_value_of_life(time_period)=model_value_of_life(time_period)+&
                                                (value_function_used/MU_1)*distribution_mass_used
                                                
                                        end if
                                    
                                    end if
                                    
                                    if ((value_function_used<model_largest_negative_value_of_life(time_period)) .AND. &
                                        (distribution_mass_used>0)) then
                                            
                                        model_largest_negative_value_of_life(time_period)=value_function_used
                                        
                                    end if
                                    
                                    if (value_function_used<0) then
                                                                    
                                        model_fraction_with_negative_value_of_life(time_period)=&
                                            model_fraction_with_negative_value_of_life(time_period)+distribution_mass_used
                                            
                                        if (housing_status_index_used==lowest_housing_grid_point) then
                                        
                                            model_fraction_homeless_with_negative_value_of_life(time_period)=&
                                                model_fraction_homeless_with_negative_value_of_life(time_period)+&
                                                distribution_mass_used
                                                
                                        end if
                                        
                                        if (unemployment_index>threshold_addiction_index) then
                                        
                                            model_fraction_addicted_with_negative_value_of_life(time_period)=&
                                                model_fraction_addicted_with_negative_value_of_life(time_period)+&
                                                distribution_mass_used
                                        
                                        end if
                                            
                                    end if
                                                                                                   
                                    if ((in_retirement==0) .AND.&
                                        ((emp_of(unemployment_index)==1))) then
                                                            
                                        model_output(time_period)=model_output(time_period)+&
                                            (labor_supply_used*employment_grid(age_index,employment_index)*&
                                            labour_deterministic_efficiency(age_index))*distribution_mass_used
                                            
                                        model_total_efficiency_units(time_period)=model_total_efficiency_units(time_period)+&
                                            (labor_supply_used*employment_grid(age_index,employment_index)*&
                                            labour_deterministic_efficiency(age_index))*distribution_mass_used
                                                                                        
                                        model_labor_supply(time_period)=model_labor_supply(time_period)+&
                                            labor_supply_used*distribution_mass_used
                                            
                                        model_total_hours(time_period)=model_total_hours(time_period)+&
                                            max_labor_supply*distribution_mass_used
                                            
                                        model_mass_can_work(time_period)=model_mass_can_work(time_period)+distribution_mass_used
                                        
                                        if (labor_supply_used<=10.d0**(-7)) then
                                        
                                            model_fraction_choose_zero_work(time_period)=&
                                                model_fraction_choose_zero_work(time_period)+distribution_mass_used
                                                
                                        elseif (labor_supply_used<=0.5*0.4) then
                                        
                                            model_fraction_choose_little_work(time_period)=&
                                                model_fraction_choose_little_work(time_period)+distribution_mass_used
                                                
                                        end if
                                                                                                                    
                                    end if
                                    
                                    ! UNEMPLOYMENT IS A WORKING AGE STATE. Retirees keep
                                    ! whatever employment index they carried in, and the
                                    ! retirement transition is absorbing, so without this
                                    ! guard they were counted in every employment moment
                                    ! below. Most of them carry emp_of 1, so they entered
                                    ! the EMPLOYED share of the homeless as employed, and
                                    ! about thirty per cent of the model's homeless are
                                    ! retired.
                                    if ((emp_of(unemployment_index)>1) .AND. (in_retirement==0)) then
                                    
                                        model_fraction_unemployed(time_period)=&
                                            model_fraction_unemployed(time_period)+distribution_mass_used
                                            
                                        if (((sud_of(unemployment_index)==0 .AND. emp_of(unemployment_index)==3)) .OR. &
                                            ((sud_of(unemployment_index)==1 .AND. emp_of(unemployment_index)==3))) then
                                        
                                            model_fraction_unemployed_on_ui(time_period)=&
                                                model_fraction_unemployed_on_ui(time_period)+distribution_mass_used
                                                
                                        end if
                                        
                                        if (housing_status_index_used==lowest_housing_grid_point) then
                                        
                                            model_fraction_of_homeless_unemployed(time_period)=&
                                                model_fraction_of_homeless_unemployed(time_period)+&
                                                distribution_mass_used
                                                                                            
                                            model_fraction_of_unemployed_homeless(time_period)=&
                                                model_fraction_of_unemployed_homeless(time_period)+&
                                                distribution_mass_used
                                                
                                        end if
                                    
                                    end if
                                    
                                    ! THE SMI MOMENTS. smi_of is the only correct test
                                    ! once there are two SMI states; the coarse
                                    ! index > threshold form means "has a SUD" and
                                    ! nothing about mental illness.
                                    ! THE BASE FOR THE HOMELESS INCOME SHARE, AND WHY IT IS
                                    ! WORKING AGE ONLY.
                                    !
                                    ! Counting every household here put retirees, who earn no
                                    ! labour income, in the denominator but hardly any in the
                                    ! numerator, because the homeless are working age. That
                                    ! alone made the homeless look RICHER than average: mean
                                    ! homeless labour income 0.321 against a population mean of
                                    ! 0.278, a ratio of 1.15 against a target of 0.191. The sign
                                    ! was wrong, and rho_d and rho_m are calibrated on it, so
                                    ! both would have been driven to their bounds undoing a base
                                    ! mismatch rather than matching the data.
                                    if (in_retirement==0) then

                                        model_mass_total_raw(time_period)=&
                                            model_mass_total_raw(time_period)+distribution_mass_used

                                    end if

                                    model_mass_by_age(age_index)=&
                                        model_mass_by_age(age_index)+distribution_mass_used

                                    if (smi_of(unemployment_index)>=1) then

                                        model_mass_smi(time_period)=&
                                            model_mass_smi(time_period)+distribution_mass_used

                                        model_smi_mass_by_age(age_index)=&
                                            model_smi_mass_by_age(age_index)+distribution_mass_used

                                        if (emp_of(unemployment_index)==1) then

                                            model_smi_and_employed(time_period)=&
                                                model_smi_and_employed(time_period)+distribution_mass_used

                                        end if

                                        if (housing_status_index_used==lowest_housing_grid_point) then

                                            model_smi_and_homeless(time_period)=&
                                                model_smi_and_homeless(time_period)+distribution_mass_used

                                        end if

                                    end if

                                    if (unemployment_index>threshold_addiction_index) then
                                    
                                        model_fraction_addicted(time_period)=&
                                            model_fraction_addicted(time_period)+distribution_mass_used
                                                                                        
                                        if ((sud_of(unemployment_index)==1 .AND. emp_of(unemployment_index)>1)) then
                                        
                                            model_fraction_addicted_and_unemployed(time_period)=&
                                                model_fraction_addicted_and_unemployed(time_period)+distribution_mass_used
                                                
                                        end if
                                            
                                        if (housing_status_index_used==lowest_housing_grid_point) then
                                        
                                            model_fraction_addicted_who_are_homeless(time_period)=&
                                                model_fraction_addicted_who_are_homeless(time_period)+distribution_mass_used
                                        
                                            model_fraction_homeless_and_addicted(time_period)=&
                                                model_fraction_homeless_and_addicted(time_period)+distribution_mass_used
                                        
                                            if ((sud_of(unemployment_index)==1 .AND. emp_of(unemployment_index)>1)) then
                                        
                                                model_fraction_of_homeless_and_addicted_unemployed(time_period)=&
                                                    model_fraction_of_homeless_and_addicted_unemployed(time_period)+&
                                                    distribution_mass_used
                                                    
                                            end if
                                        
                                        end if
                                            
                                    end if
                                    
                                    if ((housing_status_index==lowest_housing_grid_point) .AND. &
                                        (housing_status_index_used==lowest_housing_grid_point)) then
                                        
                                        model_homeless_2_years_or_more(time_period)=&
                                            model_homeless_2_years_or_more(time_period)+distribution_mass_used
                                            
                                        profile_of_chronic_homeless(time_period,1)=&
                                            profile_of_chronic_homeless(time_period,1)+&
                                            age_index*distribution_mass_used
                                            
                                        if ((emp_of(unemployment_index)==1)) then
                                            
                                        else
                                            
                                            profile_of_chronic_homeless(time_period,2)=&
                                                profile_of_chronic_homeless(time_period,2)+&
                                                distribution_mass_used
                                                
                                        end if
                                        
                                        if (((emp_of(unemployment_index)==1) .OR. (emp_of(unemployment_index)==3))) then
                                            
                                        else
                                            
                                            profile_of_chronic_homeless(time_period,3)=&
                                                profile_of_chronic_homeless(time_period,3)+&
                                                distribution_mass_used
                                                
                                        end if
                                            
                                        if (unemployment_index>threshold_addiction_index) then
                                            
                                            profile_of_chronic_homeless(time_period,4)=&
                                                profile_of_chronic_homeless(time_period,4)+&
                                                distribution_mass_used
                                            
                                        end if
                                                                                
                                        mass_profile_of_chornic_homeless(time_period,:)=&
                                            mass_profile_of_chornic_homeless(time_period,:)+distribution_mass_used
                                        
                                    end if
                                    
                                    if (housing_status_index_used==lowest_housing_grid_point) then
                                    
                                        model_fraction_homeless(time_period)=&
                                            model_fraction_homeless(time_period)+distribution_mass_used

                                        ! A RAW HOMELESS MASS, KEPT SEPARATELY ON PURPOSE.
                                        ! model_fraction_homeless is divided by
                                        ! model_sum_of_lowest_productivities later, not by the
                                        ! total mass, so anything that reconstructs a mass from it
                                        ! is wrong by that ratio. That is exactly the error that
                                        ! made the SMI share of the homeless read 0.0012 percent.
                                        ! This counter depends on no later normalisation.
                                        model_mass_homeless_raw(time_period)=&
                                            model_mass_homeless_raw(time_period)+distribution_mass_used

                                        ! THE BASE FOR THE HOMELESS INCOME SHARE, AND IT HAS TO
                                        ! MATCH ITS NUMERATOR.
                                        !
                                        ! model_homeless_labour_income is accumulated inside
                                        ! "in_retirement==0 .AND. emp_of==1", so it is working age
                                        ! labour income. The raw mass above counts EVERY homeless
                                        ! household including retirees, and about thirty per cent
                                        ! of the model's homeless are retired. Dividing working age
                                        ! earnings by an all ages head count understated the
                                        ! homeless mean by that thirty per cent, against a
                                        ! population mean whose base, model_mass_total_raw, already
                                        ! excludes retirees. The two sides were not the same
                                        ! population, which is the same error that was found and
                                        ! fixed in model_mass_total_raw itself.
                                        if (in_retirement==0) then

                                            model_mass_homeless_working_age(time_period)=&
                                                model_mass_homeless_working_age(time_period)+&
                                                distribution_mass_used

                                        end if
                                            
                                        if (age_index>life_span-retirement_span) then
                                        
                                            call calculate_income(unemployment_index,employment_index,total_income,&
                                                avg_income_to_use_1,avg_income_to_use_2,labor_supply_used,in_retirement)
                                                
                                            total_income=total_income+risk_free_rate(time_period)*&
                                               max(financial_grid(financial_index),0.d0)
                                        
                                            model_homelessness_old(time_period)=&
                                                model_homelessness_old(time_period)+distribution_mass_used
                                                
                                            model_profile_of_homeless_old(1)=model_profile_of_homeless_old(1)+&
                                                age_index*distribution_mass_used
                                                
                                            if (total_income<0.1) then
                                            
!                                                write(*,*) "total_income=", total_income
                                                
                                            end if
                                                
                                            model_profile_of_homeless_old(2)=model_profile_of_homeless_old(2)+&
                                                total_income*distribution_mass_used
                                                
                                            model_profile_of_homeless_old(3)=model_profile_of_homeless_old(3)+&
                                                max(financial_grid(financial_index),0.d0)*distribution_mass_used
                                        
                                        end if
                                            
                                    end if
                                    
                                    sum_of_distribution_not_be_homeless=sum_of_distribution_not_be_homeless+&
                                        distribution_mass_used
                                                                        
                                    model_sum_of_lowest_productivities(time_period)=&
                                        model_sum_of_lowest_productivities(time_period)+distribution_mass_used
                                                                    
                                    mortgage_to_income_owners=0
                                    housing_to_income_owners=0
                                    housing_to_income_all=0
                                    housing_to_income_renters=0
                                    pay_mortgage_insurance_1=0
                                    
                                    call calculate_income(unemployment_index,employment_index,total_income,&
                                        avg_income_to_use_1,avg_income_to_use_2,labor_supply_used,in_retirement)
                                        
                                    total_income=total_income+risk_free_rate(time_period)*&
                                        max(financial_grid(financial_index),0.d0) !+food_stamps_1
                                        ! max(...,1e-14), HERE AND AT THE FIVE RATIOS BELOW LIKE IT: a
                                        ! massed cell CAN have exactly zero income -- unemployed, no
                                        ! UI, zero assets, food stamps excluded from this measure --
                                        ! and the ratio was then Inf. Every consumer already handles
                                        ! that correctly (Inf fails the <=cap test and lands in the
                                        ! top burden bin, which is the right economics for a
                                        ! zero-income renter), so the floor changes NOTHING downstream:
                                        ! the ratio is merely astronomically large instead of Inf,
                                        ! takes the same branch, and stops raising the divide flag
                                        ! that blocked the -ffpe-trap sweep.
                                                                            
                                    rent_to_income=(model_average_rent(time_period)*&
                                        model_average_rental_unit_size(time_period))/max(total_income,10.d0**(-14))
                                    
                                     if (rent_to_income<=max_rent_to_income) then
                                        
                                        rent_to_income_index=minloc(rent_to_income_ratios(time_period,:),1,&
                                            mask=rent_to_income_ratios(time_period,:)-rent_to_income>=0)
                                                                                                                                                               
                                    else
                                    
                                        rent_to_income_index(1)=number_of_grids_rent_to_income_cdf
                                                                                
                                    end if
                                    
                                    if (use_income_or_income_plus_assets==1) then
                                    
                                        income_to_avg_income=(total_income+bequest_2)/model_average_income_previous
                                        
                                    elseif (use_income_or_income_plus_assets==2) then
                                    
                                        income_to_avg_income=(total_income+bequest_2+&
                                            max(financial_grid(financial_index),0.d0))/&
                                            model_average_income_plus_assets_previous
                                            
                                    ! ==3 .OR. ==4, NOT ==3 ALONE. The live flag is 4, and this
                                    ! ladder ended at 3, so income_to_avg_income was read
                                    ! UNINITIALISED at every state below -- caught by
                                    ! -Wuninitialized, invisible in the output because the
                                    ! poisoned bin index only feeds the income-profile files.
                                    ! At the flag's other two sites (the income CDF and the
                                    ! quintile cut) 4 means income plus financial income plus
                                    ! home equity, which is what this branch computes; the
                                    ! ladder was evidently not extended when 4 was added.
                                    elseif ((use_income_or_income_plus_assets==3) .OR. &
                                        (use_income_or_income_plus_assets==4)) then
                                    
                                        if ((amortization_used==1) .AND. (years_left_on_mortgage_index==2)) then
                                        
                                            income_to_avg_income=(total_income+bequest_2+&
                                                max(financial_grid(financial_index),0.d0)+&
                                                housing_price(time_period)*housing_size(housing_status_index)*&
                                                (1+min(financial_grid(financial_index),0.d0)))/&
                                                model_average_income_plus_all_assets_previous
                                    
                                        else
                                    
                                            income_to_avg_income=(total_income+max(financial_grid(financial_index),0.d0))/&
                                                model_average_income_plus_all_assets_previous
                                                
                                        end if
                                    
                                    end if
                                    
                                    if (income_to_avg_income<=number_of_wide_grids_income_to_avg_income_cdf) then
                                                                                    
                                        income_to_avg_income_wide_index(1)=&
                                            max(minloc(income_to_avg_income_wide_ratios(time_period,:),1,&
                                            mask=income_to_avg_income_wide_ratios(time_period,:)-income_to_avg_income>=0),1)
                                                                                                                                                               
                                    else
                                    
                                        income_to_avg_income_wide_index(1)=number_of_wide_grids_income_to_avg_income_cdf
                                                                                
                                    end if
                                    
                                    if  (unemployment_index<=threshold_addiction_index) then
                                                                                                                   
                                        mass_at_profile_income_to_avg_income_wide_1&
                                            (time_period,2,income_to_avg_income_wide_index(1))=&
                                            mass_at_profile_income_to_avg_income_wide_1&
                                            (time_period,2,income_to_avg_income_wide_index(1))+&
                                            distribution_mass_used 

                                        is_using_drugs=0
                                    
                                        if (addiction_consumption_1>0) then
                                                                                                                         
                                            income_to_avg_income_wide_pdf_1(time_period,income_to_avg_income_wide_index(1))=&
                                                income_to_avg_income_wide_pdf_1(time_period,income_to_avg_income_wide_index(1))+&
                                                distribution_mass_used

                                            is_using_drugs=1
                                                
                                        end if

                                        mass_at_profile_income_to_avg_income_wide_1&
                                            (time_period,is_using_drugs,income_to_avg_income_wide_index(1))=&
                                            mass_at_profile_income_to_avg_income_wide_1&
                                            (time_period,is_using_drugs,income_to_avg_income_wide_index(1))+&
                                            distribution_mass_used                                        
                                        
                                        profile_by_income_to_avg_income_wide_1&
                                            (time_period,is_using_drugs,income_to_avg_income_wide_index(1),1)=&
                                            profile_by_income_to_avg_income_wide_1&
                                            (time_period,is_using_drugs,income_to_avg_income_wide_index(1),1)+&
                                            age_index*distribution_mass_used

                                        profile_by_income_to_avg_income_wide_1&
                                            (time_period,is_using_drugs,income_to_avg_income_wide_index(1),2)=&
                                            profile_by_income_to_avg_income_wide_1&
                                            (time_period,is_using_drugs,income_to_avg_income_wide_index(1),2)+&
                                            consumption_used*distribution_mass_used

                                        profile_by_income_to_avg_income_wide_1&
                                            (time_period,is_using_drugs,income_to_avg_income_wide_index(1),3)=&
                                            profile_by_income_to_avg_income_wide_1&
                                            (time_period,is_using_drugs,income_to_avg_income_wide_index(1),3)+&
                                            labor_supply_used*distribution_mass_used
                                            
                                        profile_by_income_to_avg_income_wide_1&
                                            (time_period,is_using_drugs,income_to_avg_income_wide_index(1),4)=&
                                            profile_by_income_to_avg_income_wide_1&
                                            (time_period,is_using_drugs,income_to_avg_income_wide_index(1),4)+&
                                            (total_income+bequest_2)*distribution_mass_used

                                        profile_by_income_to_avg_income_wide_1&
                                            (time_period,is_using_drugs,income_to_avg_income_wide_index(1),5)=&
                                            profile_by_income_to_avg_income_wide_1&
                                            (time_period,is_using_drugs,income_to_avg_income_wide_index(1),5)+&
                                            max(years_left_on_mortgage_index-1,0)*distribution_mass_used

                                        profile_by_income_to_avg_income_wide_1&
                                            (time_period,is_using_drugs,income_to_avg_income_wide_index(1),6)=&
                                            profile_by_income_to_avg_income_wide_1&
                                            (time_period,is_using_drugs,income_to_avg_income_wide_index(1),6)+&
                                            (max(financial_grid(financial_index),0.d0)+&
                                            max(years_left_on_mortgage_index-1,0)*housing_price(time_period)*&
                                            housing_size(housing_status_index)*&
                                            (1+min(financial_grid(financial_index),0.d0)))*&
                                            distribution_mass_used
                                            
                                        profile_by_income_to_avg_income_wide_1&
                                            (time_period,is_using_drugs,income_to_avg_income_wide_index(1),7)=&
                                            profile_by_income_to_avg_income_wide_1&
                                            (time_period,is_using_drugs,income_to_avg_income_wide_index(1),7)+&
                                            housing_size(housing_status_index)*&
                                            distribution_mass_used
                                            
                                        profile_by_income_to_avg_income_wide_1&
                                            (time_period,is_using_drugs,income_to_avg_income_wide_index(1),8)=&
                                            profile_by_income_to_avg_income_wide_1&
                                            (time_period,is_using_drugs,income_to_avg_income_wide_index(1),8)+&
                                            max(amortization_used-1,0)*distribution_mass_used
                                            
                                        profile_by_income_to_avg_income_wide_1&
                                            (time_period,is_using_drugs,income_to_avg_income_wide_index(1),9)=&
                                            profile_by_income_to_avg_income_wide_1&
                                            (time_period,is_using_drugs,income_to_avg_income_wide_index(1),9)+&
                                            employment_index*distribution_mass_used
                                                                                               
                                    end if                                   
                                        
                                    median_income_cdf(time_period,rent_to_income_index(1))=&
                                        median_income_cdf(time_period,rent_to_income_index(1))+distribution_mass_used
                                        
                                    if ((housing_status_index_used>second_lowest_housing_grid_point) .OR. &
                                       (have_two_rental_markets==0)) then
                                    
                                        low_quality_market=0
                                        
                                    else
                                    
                                        low_quality_market=1
                                    
                                    end if
                                                                                                                                            
                                    if ((amortization_used==1) .AND. &
                                        (housing_status_index_used>=second_lowest_housing_grid_point)) then 
                                                                                                            
                                        rent_to_income=(rent(time_period,low_quality_market)*lived_in_size_used)/max(total_income,10.d0**(-14))
                                        housing_to_income_all=rent_to_income

                                        ! GAMMA'S MOMENT IS AN EXPENDITURE SHARE, NOT A
                                        ! RENT TO INCOME RATIO. gamma is the Cobb-Douglas
                                        ! weight on housing, so its exact counterpart is
                                        ! housing over expenditure, not housing over
                                        ! income: the two differ by saving, and only the
                                        ! first is what a Cobb-Douglas share equals. It is
                                        ! also the moment the stylized model of Section 2
                                        ! matches gamma to, shelter plus utilities over
                                        ! expenditure net of drugs in the CEX, so the two
                                        ! models are now disciplined by one definition
                                        ! rather than by two that both mention housing.
                                        ! Net of drugs is what consumption_used already
                                        ! is, since the drug is carried separately in
                                        ! addiction_consumption_1.
                                        housing_to_income_renters=&
                                            (rent(time_period,low_quality_market)*lived_in_size_used)/&
                                            max(rent(time_period,low_quality_market)*lived_in_size_used+&
                                            consumption_used,10.d0**(-10))
                                                                              
                                        if (rent_to_income<1) then
                                            
                                            mass_of_legit_renters(time_period)=&
                                                mass_of_legit_renters(time_period)+distribution_mass_used
                                                
                                            model_avg_rent_to_income_ratio(time_period)=&
                                                model_avg_rent_to_income_ratio(time_period)+rent_to_income*distribution_mass_used

                                        end if
                                        
                                        if (rent_to_income<=max_rent_to_income) then
                                        
                                            rent_to_income_index=minloc(rent_to_income_ratios(time_period,:),&
                                                mask=rent_to_income_ratios(time_period,:)-rent_to_income>=0)
                                                                                                                                                                   
                                        else
                                        
                                            rent_to_income_index(1)=number_of_grids_rent_to_income_cdf
                                                                                    
                                        end if
                                                                            
                                        if ((in_retirement==1) .AND. (include_retirees_in_income_cdf==1)) then
                                            
                                            rent_to_income_cdf(time_period,rent_to_income_index(1))=&
                                                rent_to_income_cdf(time_period,rent_to_income_index(1))+&
                                                distribution_mass_used
                                                
                                            total_renters_to_consider=total_renters_to_consider+distribution_mass_used
                                                                                    
                                        end if
                                        
                                        if (in_retirement==0) then
                                            
                                            rent_to_income_cdf(time_period,rent_to_income_index(1))=&
                                                rent_to_income_cdf(time_period,rent_to_income_index(1))+&
                                                distribution_mass_used
                                                
                                            total_renters_to_consider=total_renters_to_consider+distribution_mass_used
                                                
                                        end if
                                            
                                        total_renters_income(time_period)=&
                                            total_renters_income(time_period)+&
                                            total_income*distribution_mass_used
                                            
                                    elseif (housing_status_index_used==lowest_housing_grid_point) then
                                                                                                            
                                        rent_to_income=(model_average_rent(time_period)*&
                                            model_average_rental_unit_size(time_period))/max(total_income,10.d0**(-14))
                                                                    
                                        if (rent_to_income<=max_rent_to_income) then
                                        
                                            rent_to_income_index=minloc(rent_to_income_ratios(time_period,:),&
                                                mask=rent_to_income_ratios(time_period,:)-rent_to_income>=0)
                                                
                                        else
                                        
                                            rent_to_income_index(1)=number_of_grids_rent_to_income_cdf
                                                                                    
                                        end if
                                                                            
                                        total_homeless_1=total_homeless_1+distribution_mass_used
                                            
                                        rent_to_income_homeless_cdf(time_period,rent_to_income_index(1))=&
                                            rent_to_income_homeless_cdf(time_period,rent_to_income_index(1))+&
                                            distribution_mass_used
                                              
                                    end if
                                    
                                    is_homeless_1=1
                                    
                                    if (housing_status_index_used==lowest_housing_grid_point) then
                                    
                                        is_homeless_1=2
                                    
                                    end if
                                    
                                    is_addicted_1=0
                                    
                                    if (unemployment_index>threshold_addiction_index) then
                                    
                                        is_addicted_1=1
                                        
                                    end if

                                    ! Weighted by the probability of dying, because a newborn
                                    ! replaces a household that dies and the death hazard is
                                    ! itself a function of the disorder and of homelessness.
                                    newborn_parent_share_acc(employment_index,is_addicted_1,is_homeless_1)=&
                                        newborn_parent_share_acc(employment_index,is_addicted_1,is_homeless_1)+&
                                        distribution_mass_used*(1-survival_probability(age_index,is_homeless_1,&
                                        is_addicted_1,smi_of(unemployment_index)))
                                    
                                    if (amortization_used>1) then
                                    
                                        LTV_1=-min(financial_grid(financial_index),0.d0)
                                    
                                        if (LTV_1<=1) then
                                        
                                            LTV_index=minloc(LTV_ratios(time_period,:),mask=LTV_ratios(time_period,:)-LTV_1>=0)
                                                
                                        else
                                        
                                            LTV_index(1)=101
                                            
                                        end if
                                    
                                        LTV_cdf(time_period,LTV_Index(1))=LTV_cdf(time_period,LTV_Index(1))+distribution_mass_used
                                        total_owners_to_consider=total_owners_to_consider+distribution_mass_used
                                    
                                    end if
                                                                    
                                    if (housing_status_index_used>=second_lowest_housing_grid_point) then
                                    
                                        call calculate_income(unemployment_index,employment_index,total_income,&
                                            avg_income_to_use_1,avg_income_to_use_2,labor_supply_used,in_retirement)
                                                                                          
                                        total_income=total_income+risk_free_rate(time_period)*&
                                            max(financial_grid(financial_index),0.d0)

                                        if (amortization_used>1) then
                                        
                                            housing_to_income_all=&
                                                housing_price(time_period)*housing_size(housing_status_index_used)*&
                                                ((-min(financial_grid(financial_index_used),0.d0))*&
                                                (pay_mortgage_insurance_1*mortgage_insurance_premium+&
                                                mortgage_interest_rate(time_period)+average_fraction_of_mortgage_repaid)+&
                                                (property_tax(time_period)+housing_depreciation_rate*&
                                                include_housing_depreciation_in_housing_costs))/max(total_income,10.d0**(-14))
                                                
                                            housing_to_income_owners=&
                                                housing_price(time_period)*housing_size(housing_status_index_used)*&
                                                (-financial_grid(min(financial_index_used,negative_financial_grid_size))*&
                                                (pay_mortgage_insurance_1*mortgage_insurance_premium+&
                                                mortgage_interest_rate(time_period)+average_fraction_of_mortgage_repaid)+&
                                                (property_tax(time_period)+housing_depreciation_rate*&
                                                include_housing_depreciation_in_housing_costs))/max(total_income,10.d0**(-14))
                                                
                                            mortgage_to_income_owners=&
                                                (-financial_grid(min(financial_index_used,negative_financial_grid_size))*&
                                                housing_price(time_period)*housing_size(housing_status_index_used)*&
                                                (pay_mortgage_insurance_1*mortgage_insurance_premium+&
                                                mortgage_interest_rate(time_period)+average_fraction_of_mortgage_repaid))/&
                                                total_income
                                        
                                        end if
                                                                        
                                    else
                                    
                                        call calculate_income(unemployment_index,employment_index,total_income,&
                                            avg_income_to_use_1,avg_income_to_use_2,labor_supply_used,in_retirement)
                                                                               
                                        total_income=total_income+&
                                            (risk_free_rate(time_period)*max(financial_grid(financial_index),0.d0)+unsecured_borrowing_rate*min(financial_grid(financial_index),0.d0))
                                                                                                                                    
                                        if (-min(financial_grid(financial_index_used),0.d0)>(1-minimum_downpayment)) then
                                                                                    
                                            pay_mortgage_insurance_1=1
                                            max_mortgage_payments_as_fraction_of_income=max_debt_to_income_ratio
                                    
                                        else
                                
                                            pay_mortgage_insurance_1=0
                                            max_mortgage_payments_as_fraction_of_income=max_debt_to_income_ratio_below_80
                                    
                                        end if
                                            
                                        spending_on_housing=&
                                            (-financial_grid(min(financial_index_used,negative_financial_grid_size))*&
                                            housing_price(time_period)*housing_size(housing_status_index_used)*&
                                            (pay_mortgage_insurance_1*mortgage_insurance_premium+&
                                            mortgage_interest_rate(time_period)+average_fraction_of_mortgage_repaid))+&
                                            housing_price(time_period-solve_transition_dynamics)*&
                                            housing_size(housing_status_index_used)*&
                                            (property_tax(time_period)+housing_depreciation_rate*&
                                            include_housing_depreciation_in_housing_costs)
                                                         
                                    end if
                                    
                                    model_financial(time_period)=model_financial(time_period)+&
                                        max(financial_grid(financial_index),0.d0)*distribution_mass_used
                                        
                                    if (financial_grid(financial_index)>=0) then
                                    
                                        model_mass_with_positive_financial(time_period)=&
                                            model_mass_with_positive_financial(time_period)+distribution_mass_used
                                    
                                    end if
                                    
                                    ! NET WORTH. The first two terms are the OWNER's
                                    ! house and the mortgage against it, the mortgage
                                    ! being a negative financial position expressed as
                                    ! a fraction of the dwelling's value. The third is
                                    ! the financial position itself.
                                    !
                                    ! Both are gated on has_house, and they have to be.
                                    ! Before unsecured borrowing a renter could not hold
                                    ! a negative position at all -- the choice loop
                                    ! started at the zero index -- so the mortgage term
                                    ! was identically zero for renters and truncating
                                    ! the third term at zero cost nothing. Borrowing
                                    ! made both live and both wrong: a renter's debt was
                                    ! multiplied by the value of the dwelling they rent,
                                    ! and their actual debt was then truncated away by
                                    ! the max(). w_bot is the bottom half's share of NET
                                    ! worth and the whole purpose of the borrowing was to
                                    ! give that half a negative tail, so the measure was
                                    ! broken in exactly the place it was meant to move.
                                    net_wealth_1=(max(min(amortization_used-1,1),0)*&
                                        (housing_price(time_period)*housing_size(housing_status_index_used))+&
                                        has_house*min(financial_grid(financial_index_used),0.d0)*&
                                        housing_price(time_period)*housing_size(housing_status_index_used)+&
                                        has_house*max(financial_grid(financial_index),0.d0)+&
                                        (1-has_house)*financial_grid(financial_index))
                                                                         
                                    model_total_net_wealth(time_period)=model_total_net_wealth(time_period)+&
                                        net_wealth_1*distribution_mass_used

                                    ! and into the wealth histogram, in multiples
                                    ! of average labour income. Everything at or
                                    ! below zero lands in the first bucket and
                                    ! everything above the top in the last, so no
                                    ! mass is lost at either end.
                                    ! SCALE BY THE CALIBRATED AVERAGE, NOT THE
                                    ! MEASURED ONE. model_average_labour_income
                                    ! is zeroed at the top of this sweep and is
                                    ! not accumulated until further down the same
                                    ! household loop, so at THIS line it is still
                                    ! zero. Dividing by it sent the max() guard to
                                    ! 1e-8, every household with positive wealth
                                    ! was clamped into the top bin and everything
                                    ! at or below zero into the first, and the
                                    ! percentile walk then split one occupied
                                    ! bucket proportionally by mass. That returned
                                    ! a share of exactly p times a constant at
                                    ! every percentile -- 0.95 per cent of wealth
                                    ! for the bottom 1 per cent, 47.5 for the
                                    ! bottom half -- which reads as a perfectly
                                    ! uniform distribution and is a measurement of
                                    ! nothing. The histogram consistency pair could
                                    ! not catch it: total mass and total wealth
                                    ! were both right, because the error is in how
                                    ! wealth is spread ACROSS bins.
                                    !
                                    ! average_labor_income_calibrated is a fixed
                                    ! constant, in scope here and independent of
                                    ! loop order, and it keeps the bin edges the
                                    ! same across points, which is what makes the
                                    ! shares comparable between vertices at all.
                                    ! Measured from wealth_bin_bottom, not from
                                    ! zero, so a household in debt lands in its
                                    ! own bucket instead of being clamped into
                                    ! the first one with everybody near zero.
                                    wealth_bin_index=min(max(1+floor(wealth_bins*&
                                        ((net_wealth_1/max(average_labor_income_calibrated,&
                                        10.d0**(-8)))-wealth_bin_bottom)/&
                                        (wealth_bin_top-wealth_bin_bottom)),1),wealth_bins)
                                    wealth_hist_mass(wealth_bin_index)=&
                                        wealth_hist_mass(wealth_bin_index)+distribution_mass_used
                                    wealth_hist_wealth(wealth_bin_index)=&
                                        wealth_hist_wealth(wealth_bin_index)+net_wealth_1*distribution_mass_used

                                    ! total_income is this household's own income,
                                    ! set by the call to calculate_income further up
                                    ! this same iteration, so it is the household
                                    ! level counterpart of net_wealth_1 and not an
                                    ! aggregate.
                                    income_bin_index=min(max(1+floor(income_bins*&
                                        (total_income/max(average_labor_income_calibrated,&
                                        10.d0**(-8)))/income_bin_top),1),income_bins)
                                    income_hist_mass(income_bin_index)=&
                                        income_hist_mass(income_bin_index)+distribution_mass_used
                                    if (sud_of(unemployment_index)>=1) then
                                        income_hist_sud(income_bin_index)=&
                                            income_hist_sud(income_bin_index)+distribution_mass_used
                                    end if
                                    income_hist_income(income_bin_index)=&
                                        income_hist_income(income_bin_index)+total_income*distribution_mass_used

                                    ! EARNINGS OF THE WORKING AGE IN WORK, on
                                    ! the same bins. Built here rather than from
                                    ! total_income because total_income has
                                    ! interest added to it by the time it
                                    ! reaches this line, and the target is a
                                    ! wage and salary statistic.
                                    !
                                    ! emp_of==1 is the in-work state; the two
                                    ! others are the insured and uninsured
                                    ! non-employment states, whose income is
                                    ! unemployment insurance or disability and
                                    ! is not earnings. in_retirement excludes
                                    ! the social security recipients. Together
                                    ! they are the SCF's own population.
                                    if ((in_retirement==0) .AND. &
                                        (emp_of(unemployment_index)==1)) then

                                        earnings_1=labor_supply_used*&
                                            employment_grid(age_index,employment_index)*&
                                            labour_deterministic_efficiency(age_index)

                                        earnings_bin_index=min(max(1+floor(income_bins*&
                                            (earnings_1/max(average_labor_income_calibrated,&
                                            10.d0**(-8)))/income_bin_top),1),income_bins)
                                        earnings_hist_mass(earnings_bin_index)=&
                                            earnings_hist_mass(earnings_bin_index)+distribution_mass_used
                                        earnings_hist_earnings(earnings_bin_index)=&
                                            earnings_hist_earnings(earnings_bin_index)+&
                                            earnings_1*distribution_mass_used

                                    end if

                                    if (financial_index==financial_grid_size) then
                                        diag_mass_top_financial=diag_mass_top_financial+distribution_mass_used
                                    end if
                                    if (financial_index>=financial_grid_size-2) then
                                        diag_mass_top3_financial=diag_mass_top3_financial+distribution_mass_used
                                    end if
                                        
                                    if (age_index<=youngest_ages_for_wealth_computation) then
                                    
                                        model_youngest_net_wealth_share(time_period)=&
                                            model_youngest_net_wealth_share(time_period)+&
                                            net_wealth_1*distribution_mass_used
                                            
                                    end if
                                        
                                    if (amortization_used>1) then
                                    
                                        model_net_wealth_owners(time_period)=model_net_wealth_owners(time_period)+&
                                            net_wealth_1*distribution_mass_used
                                        
                                        model_total_owners(time_period)=&
                                            model_total_owners(time_period)+distribution_mass_used
                                    
                                    else
                                    
                                        if (housing_status_index_used>lowest_housing_grid_point) then
                                    
                                            ! RAW, not truncated: this branch is
                                            ! renters only, so a negative position is
                                            ! unsecured debt and belongs in their net
                                            ! worth. The max() predates borrowing,
                                            ! when a renter could not be negative.
                                            model_net_wealth_renters(time_period)=&
                                                model_net_wealth_renters(time_period)+&
                                                financial_grid(financial_index)*distribution_mass_used
                                                
                                            model_total_renters(time_period)=&
                                                model_total_renters(time_period)+distribution_mass_used
                                                
                                        end if
                                    
                                    end if
                                                                        
                                    if (amortization_used>1) then
                                                                                                                                                                                                
                                        model_gross_housing_wealth(time_period)=model_gross_housing_wealth(time_period)+&
                                            (housing_price(time_period)*housing_size(housing_status_index_used))*&
                                            distribution_mass_used
                                            
                                        model_net_housing_wealth(time_period)=model_net_housing_wealth(time_period)+&
                                            (housing_price(time_period)*housing_size(housing_status_index_used)+&
                                            min(financial_grid(financial_index_used),0.d0)*&
                                            housing_price(time_period)*housing_size(housing_status_index_used))*&
                                            distribution_mass_used
                                                                                                        
                                        model_mortgages(time_period)=model_mortgages(time_period)-&
                                            min(financial_grid(financial_index_used),0.d0)*&
                                            housing_price(time_period)*housing_size(housing_status_index_used)*&
                                            distribution_mass_used
                                        
                                    end if
                                    
                                    if (total_income>0) then
                                    
                                        model_avg_mortgage_spending(time_period)=model_avg_mortgage_spending(time_period)+&
                                            mortgage_to_income_owners*distribution_mass_used

                                        model_avg_housing_spending_owners(time_period)=&
                                            model_avg_housing_spending_owners(time_period)+&
                                            housing_to_income_owners*distribution_mass_used

                                        model_avg_housing_spending_all(time_period)=model_avg_housing_spending_all(time_period)+&
                                            housing_to_income_all*distribution_mass_used

                                        model_avg_housing_spending_renters(time_period)=&
                                            model_avg_housing_spending_renters(time_period)+&
                                            housing_to_income_renters*distribution_mass_used
                                            
                                        model_mass_renters_to_consider(time_period)=&
                                            model_mass_renters_to_consider(time_period)+distribution_mass_used
                                                                    
                                    end if
                                                                    
                                    if (age_index==1) then
                                    
                                        if (years_left_on_mortgage_index==1) then
                                    
                                            model_youngest_assets(time_period)=model_youngest_assets(time_period)+&
                                                financial_grid(financial_index)*distribution_mass_used
                                                
                                        else
                                                                                
                                            model_youngest_assets(time_period)=model_youngest_assets(time_period)+&
                                                (housing_price(time_period)*housing_size(housing_status_index)+&
                                                min(financial_grid(financial_index),0.d0)*&
                                                housing_price(time_period)*housing_size(housing_status_index)+&
                                                max(financial_grid(financial_index),0.d0))*distribution_mass_used
                                        
                                        end if
                                            
                                    end if
                                    
                                    mass_dying(time_period)=mass_dying(time_period)+distribution_mass_used*&
                                        (1-survival_probability(age_index,is_homeless_1,is_addicted_1,smi_of(unemployment_index)))
                                                                
                                    if (amortization_used>1) then

                                        bequest_1=housing_price(time_period)*&
                                            housing_size(housing_status_index_used)*(1-remove_tax_and_depreciation*&
                                            (property_tax(time_period)+housing_depreciation_rate))
                                                                                
                                        bequest_1=bequest_1+&
                                            (1-frac_used)*(min(financial_grid(financial_index_used),0.d0)*&
                                            housing_price(time_period)*housing_size(housing_status_index_used)+&
                                            max(financial_grid(financial_index_used),0.d0))
                                                                                    
                                        bequest_1=bequest_1+frac_used*(min(financial_grid(fin_frac_used),0.d0)*&
                                            housing_price(time_period)*housing_size(housing_status_index_used)+&
                                            max(financial_grid(fin_frac_used),0.d0))
                                                                                        
                                    else
                                
                                        ! A DEBT IS PART OF THE ESTATE. The author
                                        ! asked on 2 September whether negative
                                        ! assets are subtracted from bequests. They
                                        ! were not: this branch is the renter's
                                        ! estate and it took max(grid,0), so a
                                        ! household dying in debt left nothing and
                                        ! the loan was forgiven.
                                        !
                                        ! Harmless while nobody could hold a
                                        ! negative position -- the whole negative
                                        ! grid was unreachable for renters. The
                                        ! moment unsecured borrowing opened it, it
                                        ! became a free option at EVERY age, not
                                        ! only the last: mortality is stochastic,
                                        ! so borrow, consume, and there is a chance
                                        ! the debt is never repaid. Barring
                                        ! borrowing in the terminal period does not
                                        ! touch that, because the default happens
                                        ! wherever death does.
                                        !
                                        ! The raw grid value carries the debt at
                                        ! face value, so a negative estate reduces
                                        ! aggregate bequests exactly as a positive
                                        ! one raises them. The homeowner branch
                                        ! above already did the right thing for a
                                        ! mortgage, scaling it by the house.
                                        bequest_1=(1-frac_used)*financial_grid(financial_index_used)+&
                                            frac_used*financial_grid(fin_frac_used)
                                
                                    end if
                                                                        
                                    value_of_bequests_by_age(age_index)=value_of_bequests_by_age(age_index)+&
                                        bequest_2*distribution_mass_used
                                                                            
                                    bequests_mass_by_age(age_index)=bequests_mass_by_age(age_index)+distribution_mass_used
                                    
                                    model_bequests(time_period)=model_bequests(time_period)+bequest_1*distribution_mass_used*&
                                        (1-survival_probability(age_index,is_homeless_1,is_addicted_1,smi_of(unemployment_index)))
                                        
                                    ! THE NEWBORN ENDOWMENT IS A TRANSFER AND IS
                                    ! COUNTED AS ONE. Without this the government
                                    ! would collect the bequests that fund it and
                                    ! never be charged for paying it out, which
                                    ! would show up as a free lunch in the budget
                                    ! rather than as a tax rate that has to clear.
                                    model_total_inheritance(time_period)=model_total_inheritance(time_period)+&
                                        newborn_age_transfer(age_index)*distribution_mass_used+&
                                        ((1-inheritance_function_of_productivity)+&
                                        inheritance_function_of_productivity*&
                                        employment_grid(age_index,employment_index))*&
                                        inheritance_amount(age_index)*distribution_mass_used
                                        
                                    ! THE SAME DEBT, IN THE AGGREGATE. This is
                                    ! the reported total of financial bequests and
                                    ! it must net out estates that are negative,
                                    ! or the accounting says more was inherited
                                    ! than was left.
                                    model_financial_bequests(time_period)=model_financial_bequests(time_period)+&
                                        ((1-frac_used)*financial_grid(financial_index_used)+&
                                        frac_used*financial_grid(fin_frac_used))*distribution_mass_used*&
                                        (1-survival_probability(age_index,is_homeless_1,is_addicted_1,smi_of(unemployment_index)))
                                    
                                    if (years_left_on_mortgage_index>1) then
                                    
                                        model_fraction_leaving_housing_bequests(time_period)=&
                                            model_fraction_leaving_housing_bequests(time_period)+distribution_mass_used*&
                                            (1-survival_probability(age_index,is_homeless_1,is_addicted_1,smi_of(unemployment_index)))
                                            
                                    end if

                                    if (bequest_1>0) then
                                    
                                        model_fraction_leaving_bequests(time_period)=&
                                            model_fraction_leaving_bequests(time_period)+distribution_mass_used*&
                                            (1-survival_probability(age_index,is_homeless_1,is_addicted_1,smi_of(unemployment_index)))
                                            
                                    end if
                                              
                                    if (amortization_used>=2) then
                                    
                                        mass_of_owners(time_period)=mass_of_owners(time_period)+distribution_mass_used
                                        
                                        model_wealth_of_owners(time_period)=model_wealth_of_owners(time_period)+&
                                            (max(years_left_on_mortgage_index-1,0)*&
                                            housing_price(time_period)*housing_size(housing_status_index)+&
                                            min(financial_grid(financial_index),0.d0)*&
                                            housing_price(time_period)*housing_size(housing_status_index)+&
                                            max(financial_grid(financial_index),0.d0))*distribution_mass_used
                                    
                                    end if
                                    
                                    if ((in_retirement==0) .AND. ((emp_of(unemployment_index)==1))) then
                                    
                                        model_total_workers(time_period)=model_total_workers(time_period)+distribution_mass_used
                                        
                                        model_average_labour_income(time_period)=model_average_labour_income(time_period)+&
                                            labor_supply_used*employment_grid(age_index,employment_index)*&
                                            labour_deterministic_efficiency(age_index)*&
                                            (rho_d**(min(sud_of(unemployment_index),1)*include_rho_d))*&
                                            (rho_m**(min(smi_of(unemployment_index),1)*include_rho_m))*&
                                            distribution_mass_used

                                        ! THE PENALTIES BELONG IN THE MOMENT TOO. The budget
                                        ! constraint applies rho_d and rho_m to earnings, so a
                                        ! moment that omitted them would be measuring a different
                                        ! wage than the household faces, and the homeless income
                                        ! share is exactly the moment they are calibrated on.
                                        model_all_labour_income(time_period)=model_all_labour_income(time_period)+&
                                            labor_supply_used*employment_grid(age_index,employment_index)*&
                                            labour_deterministic_efficiency(age_index)*&
                                            (rho_d**(min(sud_of(unemployment_index),1)*include_rho_d))*&
                                            (rho_m**(min(smi_of(unemployment_index),1)*include_rho_m))*&
                                            distribution_mass_used

                                        if (housing_status_index_used==lowest_housing_grid_point) then

                                            model_homeless_labour_income(time_period)=&
                                                model_homeless_labour_income(time_period)+&
                                                labor_supply_used*employment_grid(age_index,employment_index)*&
                                                labour_deterministic_efficiency(age_index)*&
                                                (rho_d**(min(sud_of(unemployment_index),1)*include_rho_d))*&
                                                (rho_m**(min(smi_of(unemployment_index),1)*include_rho_m))*&
                                                distribution_mass_used

                                        end if
                                            
                                        model_average_labour_income_by_employment(time_period,employment_index)=&
                                            model_average_labour_income_by_employment(time_period,employment_index)+&
                                            labor_supply_used*employment_grid(age_index,employment_index)*&
                                            labour_deterministic_efficiency(age_index)*distribution_mass_used
                                            
                                        mass_by_employment(time_period,employment_index)=&
                                            mass_by_employment(time_period,employment_index)+&
                                            distribution_mass_used
                                                                                 
                                    end if
                                                                    
                                    if (in_retirement==1) then
                                    
                                        model_average_income(time_period)=model_average_income(time_period)+&
                                            model_ss_benefits(employment_index)*distribution_mass_used
                                    
                                    else
                                    
                                        if ((emp_of(unemployment_index)==1)) then
                                        
                                            model_average_income(time_period)=model_average_income(time_period)+&
                                                labor_supply_used*employment_grid(age_index,employment_index)*&
                                                labour_deterministic_efficiency(age_index)*distribution_mass_used
                                                
                                        else
                                    
                                            model_average_income(time_period)=model_average_income(time_period)+&
                                                out_of_work_income(unemployment_index,employment_index,&
                                                avg_income_to_use_1)*distribution_mass_used
                                        
                                        end if
                                        
                                    end if
                                    
                                    model_average_income(time_period)=model_average_income(time_period)+&
                                        (risk_free_rate(time_period)*max(financial_grid(financial_index),0.d0)+unsecured_borrowing_rate*min(financial_grid(financial_index),0.d0))*&
                                        distribution_mass_used
                                        
                                    model_average_income_plus_assets(time_period)=model_average_income(time_period)+&
                                        (bequest_2+max(financial_grid(financial_index),0.d0))*distribution_mass_used
                                        
                                    if ((amortization_used==1) .AND. (years_left_on_mortgage_index==2)) then
                                        
                                        model_average_income_plus_all_assets(time_period)=&
                                            model_average_income_plus_assets(time_period)+&
                                            (bequest_2+housing_price(time_period)*housing_size(housing_status_index)*&
                                            (1+min(financial_grid(financial_index),0.d0)))*distribution_mass_used
                                            
                                    else
                                    
                                        model_average_income_plus_all_assets(time_period)=&
                                            model_average_income_plus_assets(time_period)
                                            
                                    end if
                                    
                                    if ((amortization_used==1) .AND. &
                                        (housing_status_index_used>=second_lowest_housing_grid_point)) then
                                        
                                        if (amortization_used==0) then

                                            total_rent_paid(time_period)=total_rent_paid(time_period)+&
                                                rent(time_period,low_quality_market)*lived_in_size_used*distribution_mass_used

                                            average_rent_by_age(age_index)=average_rent_by_age(age_index)+&
                                                rent(time_period,low_quality_market)*distribution_mass_used

                                        else

                                            total_rent_paid(time_period)=total_rent_paid(time_period)+&
                                                rent(time_period,low_quality_market)*lived_in_size_used*distribution_mass_used
        
                                            average_rent_by_age(age_index)=average_rent_by_age(age_index)+&
                                                rent(time_period,low_quality_market)*distribution_mass_used

                                        end if
                                                                                        
                                        mass_of_renters_by_age(age_index)=mass_of_renters_by_age(age_index)+&
                                            distribution_mass_used
                                                                                        
                                    elseif (amortization_used>1) then
                                    
                                        total_imputed_rents(time_period)=&
                                            total_imputed_rents(time_period)+rent(time_period,0)*&
                                            lived_in_size_used*distribution_mass_used
                                    
                                    end if
                                    
                                end do
                                    
                            end do
                            
                        end do
                        
                    end do
                                                                        
                end do
                
            end do
            
        end do
        
        sum_of_distribution=0
        
        do i=1,2
                
            sum_of_distribution=sum_of_distribution+&
                sum(distribution_stationary(i)%vector_transition_real(time_period,:,:,:,:,:,:))
            
        end do

        ! POOLED MASS, NOT ONE TYPE'S, AND ACCUMULATED RATHER THAN SCALED.
        !
        ! The histograms and every other accumulator above hold both
        ! discount-factor types once the benchmark chain has run twice, while
        ! distribution_stationary holds only the type just solved. The old code
        ! closed that gap by multiplying by the pass count, which is right only
        ! if the types weigh the same. They do not -- see pooled_mass_all's
        ! declaration for the measurement that says so -- so the passes are
        ! added up instead.
        !
        ! This routine is FIRST of the nine in the chain, so it owns the reset
        ! and every later routine in the same pass reads a total that already
        ! includes the current type.
        if (accumulating_beta_types==0) pooled_mass_all=0.d0
        pooled_mass_all=pooled_mass_all+sum_of_distribution
        if ((current_beta_type>=1) .AND. (current_beta_type<=size(mass_by_beta_type))) then
            mass_by_beta_type(current_beta_type)=sum_of_distribution
        end if
        sum_of_distribution=pooled_mass_all
        
        sum_of_retirees=0
        
        do i=1,2
        
            sum_of_retirees=sum_of_retirees+&
                sum(distribution_stationary(i)%&
                vector_transition_real(time_period,life_span-retirement_span+1:life_span,:,:,:,:,:))
        
        end do

        ! POOLED MASS OF RETIREES, accumulated for the same reason and in the
        ! same place as pooled_mass_all just above.
        if (accumulating_beta_types==0) pooled_mass_retirees=0.d0
        pooled_mass_retirees=pooled_mass_retirees+sum_of_retirees
        sum_of_retirees=pooled_mass_retirees
        
        do i=1,number_of_wide_grids_income_to_avg_income_cdf
        
            ! NORMALISE ONLY ON THE LAST PASS. These divisions put the
            ! result back into the accumulator they read, and the reset
            ! above is guarded to the FIRST pass, so on the second pass
            ! the accumulation lands on top of an already-divided value:
            !     pass 1   X = u          then  X = u/T
            !     pass 2   X = u/T + u    then  X = (u/T + u)/(2T)
            ! against a correct pooled 2u/2T = u/T. The ratio is
            ! (1+T)/(2T), which is only 1 when T is exactly one.
            !
            ! The driver comment asserts "each type's distribution carries
            ! unit mass". IT DOES NOT: the run log prints
            ! sum(distribution_guess) = 51.718, the life-cycle sum of
            ! cohort masses. So the factor is just above one half for a
            ! large denominator and blows up as 1/(2m) for a small
            ! subpopulation. 187 statements across the nine-routine
            ! chain were affected.

            if (current_beta_type==number_of_beta_types) then
                income_to_avg_income_wide_pdf_1(time_period,i)=&
                    income_to_avg_income_wide_pdf_1(time_period,i)/&
                    max(mass_at_profile_income_to_avg_income_wide_1(time_period,2,i),10.d0**(-14))
            end if
        
        end do
        
        if (current_beta_type==number_of_beta_types) then
            profile_of_chronic_homeless(time_period,:)=profile_of_chronic_homeless(time_period,:)/&
                mass_profile_of_chornic_homeless(time_period,:)
        end if

        do j=1,number_of_wide_grids_income_to_avg_income_cdf

            do i=1,number_of_profiles_for_income

                profile_by_income_to_avg_income_wide_1(time_period,2,j,i)=&
                    sum(profile_by_income_to_avg_income_wide_1(time_period,0:1,j,i))/&
                    max(mass_at_profile_income_to_avg_income_wide_1(time_period,2,j),10.d0**(-14))

            end do

        end do 

        do k=0,1

            do j=1,number_of_wide_grids_income_to_avg_income_cdf

                do i=1,number_of_profiles_for_income

                    if (current_beta_type==number_of_beta_types) then
                        profile_by_income_to_avg_income_wide_1(time_period,k,j,i)=&
                            profile_by_income_to_avg_income_wide_1(time_period,k,j,i)/&
                            max(mass_at_profile_income_to_avg_income_wide_1(time_period,k,j),10.d0**(-14))
                    end if

                end do

            end do

        end do        
        ! max(...,1e-14) ON EVERY SUBPOPULATION DENOMINATOR BELOW: an empty
        ! subpopulation -- no owners, no retirees yet, nobody with a negative
        ! value of life -- divided 0 by 0 and the statistic went NaN, which
        ! is the same class the aggregates section already guards ('every
        ! conditional statistic divides by max(denominator,1e-12)'). A
        ! floored empty subpopulation reports 0 instead of NaN and stops
        ! raising the invalid flag that halted the -ffpe-trap sweep here.
                
        if (current_beta_type==number_of_beta_types) model_average_ss_benefits(time_period)=model_average_ss_benefits(time_period)/max(sum_of_retirees,10.d0**(-14))
        
        if (current_beta_type==number_of_beta_types) model_net_wealth_owners(time_period)=model_net_wealth_owners(time_period)/max(model_total_owners(time_period),10.d0**(-14))

        if (current_beta_type==number_of_beta_types) model_net_wealth_renters(time_period)=model_net_wealth_renters(time_period)/max(model_total_renters(time_period),10.d0**(-14))
        
        if (current_beta_type==number_of_beta_types) then
            model_fraction_homeless_with_negative_value_of_life(time_period)=&
                model_fraction_homeless_with_negative_value_of_life(time_period)/max(model_fraction_with_negative_value_of_life(time_period),10.d0**(-14))
        end if
        
        if (current_beta_type==number_of_beta_types) then
            model_fraction_addicted_with_negative_value_of_life(time_period)=&
                model_fraction_addicted_with_negative_value_of_life(time_period)/max(model_fraction_with_negative_value_of_life(time_period),10.d0**(-14))
        end if
        
        if (current_beta_type==number_of_beta_types) then
            model_fraction_with_negative_value_of_life(time_period)=&
                model_fraction_with_negative_value_of_life(time_period)/sum_of_distribution
        end if
        
        if (current_beta_type==number_of_beta_types) median_income_cdf(time_period,:)=median_income_cdf(time_period,:)/sum_of_distribution
        
        do i=2,number_of_grids_rent_to_income_cdf
        
            median_income_cdf(time_period,i)=median_income_cdf(time_period,i-1)+median_income_cdf(time_period,i)
            
        end do
        
        if (current_beta_type==number_of_beta_types) then
            model_fraction_addicted_who_are_homeless(time_period)=&
                model_fraction_addicted_who_are_homeless(time_period)/max(model_fraction_addicted(time_period),10.d0**(-14))
        end if
        
        if (current_beta_type==number_of_beta_types) model_addiction_by_employment(:)=model_addiction_by_employment(:)/max(model_fraction_addicted(time_period),10.d0**(-14))
          
        if (current_beta_type==number_of_beta_types) then
            model_fraction_choose_zero_work(time_period)=&
                model_fraction_choose_zero_work(time_period)/max(model_mass_can_work(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_fraction_choose_little_work(time_period)=&
                model_fraction_choose_little_work(time_period)/max(model_mass_can_work(time_period),10.d0**(-14))
        end if
          
        median_index=minloc(median_income_cdf(time_period,:),1,&
            mask=median_income_cdf(time_period,:)-0.5>=0)
                        
        median_income(time_period)=(model_average_rent(time_period)*model_average_rental_unit_size(time_period))/&
            rent_to_income_ratios(time_period,max(median_index(1),1))
        
        if (current_beta_type==number_of_beta_types) then
            model_fraction_of_homeless_and_addicted_unemployed(time_period)=&
                model_fraction_of_homeless_and_addicted_unemployed(time_period)/max(model_fraction_homeless_and_addicted(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) model_profile_of_homeless_old(:)=model_profile_of_homeless_old(:)/max(model_homelessness_old(time_period),10.d0**(-14))
            
        if (current_beta_type==number_of_beta_types) model_homelessness_old(time_period)=model_homelessness_old(time_period)/max(model_fraction_homeless(time_period),10.d0**(-14))
    
        if (current_beta_type==number_of_beta_types) model_fraction_leaving_bequests(time_period)=model_fraction_leaving_bequests(time_period)/max(mass_dying(time_period),10.d0**(-14))
        
        if (current_beta_type==number_of_beta_types) then
            model_fraction_leaving_housing_bequests(time_period)=&
                model_fraction_leaving_housing_bequests(time_period)/max(mass_dying(time_period),10.d0**(-14))
        end if
                
        model_total_investment_income(time_period)=model_financial(time_period)*risk_free_rate(time_period)
        
        model_average_financial(time_period)=model_financial(time_period)/max(model_mass_with_positive_financial(time_period),10.d0**(-14))
        
        ! aleph IS LEFT AS AN AGGREGATE OVER A MEAN, ON THE EVIDENCE.
        !
        ! Audit B F4 argued that model_value_of_life is a mass-weighted SUM over
        ! households while its denominator is a MEAN, so the ratio scales with
        ! total mass and should be normalised. The structure of that argument is
        ! right. THE ARITHMETIC SAYS THE CONCLUSION IS NOT.
        !
        ! sum_of_distribution is 51.1 in this model, not one -- it is the
        ! life-cycle sum of cohort masses. aleph measures 57.95 against a target
        ! of 80, which is 28 per cent off. Dividing by 51.1 would put it at 1.13,
        ! which is 98.6 per cent off. A quantity sitting 28 per cent from its
        ! target is not one that is wrong by a factor of fifty; the target was
        ! evidently set against the aggregate form.
        !
        ! The normalisation was applied here and reverted the same hour, before
        ! any point was measured with it. The audit itself flagged its own
        ! evidence as "supporting but not decisive" and its magnitude check as
        ! "consistent with a doubling rather than a measurement of one".
        !
        ! What remains true and unresolved: at TWO types this ratio does scale
        ! with the number of types, so aleph doubles for a reason that has
        ! nothing to do with the value of life. That needs fixing at the two-type
        ! level -- probably by dividing by mass_passes, not by the whole mass --
        ! and it needs the equal-beta test to confirm the factor first.

        ! aleph's AGGREGATE MUST NOT GROW WITH THE NUMBER OF TYPES.
        !
        ! model_value_of_life is a mass-weighted SUM and its denominator at the
        ! print site is a MEAN, so the ratio is proportional to total mass. The
        ! target was set against that aggregate form -- dividing by the whole
        ! mass of 51.1 puts a moment that is 28 per cent off at 98.6 per cent
        ! off, which is how the first attempt at this was caught and reverted.
        !
        ! But at TWO types the sum runs over two passes while the mean does not,
        ! so aleph grows for a reason that has nothing to do with the value of
        ! life. What must be divided out is how much bigger the pooled
        ! population is than the one-type population the target was set
        ! against, and that is pooled_mass_all over the FIRST type's mass -- the
        ! patient type, which is the one the one-beta model is.
        !
        ! This was written as a division by mass_passes, the pass count. That is
        ! the same number only if the types weigh the same, and they do not: the
        ! histogram invariants put the gap at about nineteen per cent of the
        ! pooled total. The ratio below is exactly one at a single type, so
        ! nothing measured at one beta moves, which is the property the pass
        ! count was chosen for in the first place.
        if (current_beta_type==number_of_beta_types) then
            model_value_of_life(time_period)=model_value_of_life(time_period)/&
                max(pooled_mass_all/max(mass_by_beta_type(1),10.d0**(-12)),10.d0**(-12))
        end if

        model_GDP(time_period)=model_output(time_period)
        
        model_total_income(time_period)=model_output(time_period)+&
            model_total_investment_income(time_period)+include_bequests*model_bequests(time_period)
            
        if (current_beta_type==number_of_beta_types) then
            model_youngest_net_wealth_share(time_period)=&
                model_youngest_net_wealth_share(time_period)/model_total_net_wealth(time_period)
        end if
                            
        model_average_net_wealth(time_period)=model_total_net_wealth(time_period)/sum_of_distribution

        ! THE BOTTOM HALF'S SHARE OF NET WORTH. Walk the histogram up until half
        ! the mass is behind, splitting the bucket that straddles the median in
        ! proportion to the mass taken from it, and divide the wealth so
        ! collected by the total. The Fed distributional accounts put it at 2.52
        ! per cent. A share far above that is a lower tail with too much in it,
        ! which is the same thing as saying nobody can be shut out of the
        ! smallest rent.
        do percentile_index_1=1,5

            percentile_1=wealth_percentiles(percentile_index_1)
            cumulative_mass_1=0
            cumulative_wealth_1=0

            do wealth_bin_index=1,wealth_bins

                if (cumulative_mass_1+wealth_hist_mass(wealth_bin_index)>=&
                    percentile_1*sum_of_distribution) then

                    share_of_bin_1=(percentile_1*sum_of_distribution-cumulative_mass_1)/&
                        max(wealth_hist_mass(wealth_bin_index),10.d0**(-12))
                    cumulative_wealth_1=cumulative_wealth_1+&
                        share_of_bin_1*wealth_hist_wealth(wealth_bin_index)
                    exit

                end if

                cumulative_mass_1=cumulative_mass_1+wealth_hist_mass(wealth_bin_index)
                cumulative_wealth_1=cumulative_wealth_1+wealth_hist_wealth(wealth_bin_index)

            end do

            model_wealth_share_below(percentile_index_1,time_period)=cumulative_wealth_1/&
                max(model_total_net_wealth(time_period),10.d0**(-12))

        end do

        model_bottom_half_wealth_share(time_period)=model_wealth_share_below(5,time_period)

        ! THE SAME WALK ON INCOME, at the bottom 1, 5, 10 and 50 per cent. The
        ! bucket that straddles each cut is split in proportion to the mass
        ! taken from it, exactly as above.
        do percentile_index_1=1,4

            percentile_1=bottom_percentiles(percentile_index_1)
            cumulative_mass_1=0
            cumulative_income_1=0

            do income_bin_index=1,income_bins

                if (cumulative_mass_1+income_hist_mass(income_bin_index)>=&
                    percentile_1*sum_of_distribution) then

                    share_of_bin_1=(percentile_1*sum_of_distribution-cumulative_mass_1)/&
                        max(income_hist_mass(income_bin_index),10.d0**(-12))
                    cumulative_income_1=cumulative_income_1+&
                        share_of_bin_1*income_hist_income(income_bin_index)
                    exit

                end if

                cumulative_mass_1=cumulative_mass_1+income_hist_mass(income_bin_index)
                cumulative_income_1=cumulative_income_1+income_hist_income(income_bin_index)

            end do

            ! THE DENOMINATOR IS THE HISTOGRAM'S OWN TOTAL, AND THAT IS WEAKER
            ! THAN WHAT THE WEALTH SHARES DO. The wealth version divides by
            ! model_total_net_wealth, an aggregate accumulated independently, so
            ! comparing the two catches a histogram that has missed households.
            ! There is no household-level income aggregate to check against here
            ! -- model_total_income is output plus investment income plus
            ! bequests, which is not the sum of total_income over households --
            ! so dividing by the histogram's own sum is the honest choice: it
            ! makes these genuine shares that sum to one, at the cost of that
            ! second check. The mass check below is what remains, and it still
            ! catches the failure that matters, a histogram covering less than
            ! the distribution does.
            model_income_share_below(percentile_index_1,time_period)=cumulative_income_1/&
                max(sum(income_hist_income),10.d0**(-12))

        end do

        model_bottom_half_income_share(time_period)=model_income_share_below(4,time_period)

        ! AND THE SAME WALK AT THE MEDIAN ON EARNINGS, which is what sigma_y is
        ! scored on. The denominator is the earnings histogram's own mass, not
        ! sum_of_distribution: this histogram deliberately covers only the
        ! working age in work, so the median it walks to is the median of that
        ! population and not of the economy. Using sum_of_distribution here
        ! would ask for the earnings of the bottom half of EVERYONE, which the
        ! retired and the non-employed would put at zero.
        cumulative_mass_1=0
        cumulative_income_1=0

        do income_bin_index=1,income_bins

            if (cumulative_mass_1+earnings_hist_mass(income_bin_index)>=&
                0.50d0*sum(earnings_hist_mass)) then

                share_of_bin_1=(0.50d0*sum(earnings_hist_mass)-cumulative_mass_1)/&
                    max(earnings_hist_mass(income_bin_index),10.d0**(-12))
                cumulative_income_1=cumulative_income_1+&
                    share_of_bin_1*earnings_hist_earnings(income_bin_index)
                exit

            end if

            cumulative_mass_1=cumulative_mass_1+earnings_hist_mass(income_bin_index)
            cumulative_income_1=cumulative_income_1+earnings_hist_earnings(income_bin_index)

        end do

        model_bottom_half_labour_income_share=cumulative_income_1/&
            max(sum(earnings_hist_earnings),10.d0**(-12))

        income_hist_mass_check=sum(income_hist_mass)/max(sum_of_distribution,10.d0**(-12))

        ! DOES THE HISTOGRAM ACTUALLY HOLD THE WHOLE DISTRIBUTION? If its mass
        ! does not equal sum_of_distribution, or its wealth does not equal the
        ! total, then the loop it is accumulated in covers less than the model
        ! does and every share above is read off the wrong denominator. This is
        ! the check that would catch that, and it is reported rather than
        ! assumed, because a share of 27 per cent against a data figure of 2.5
        ! is exactly the kind of number that ought to be doubted first.
        wealth_hist_mass_check=sum(wealth_hist_mass)/max(sum_of_distribution,10.d0**(-12))
        wealth_hist_wealth_check=sum(wealth_hist_wealth)/&
            max(model_total_net_wealth(time_period),10.d0**(-12))
            
        if (current_beta_type==number_of_beta_types) model_avg_mortgage_spending(time_period)=model_avg_mortgage_spending(time_period)/max(mass_of_owners(time_period),10.d0**(-14))

        if (current_beta_type==number_of_beta_types) model_avg_housing_spending_owners(time_period)=model_avg_housing_spending_owners(time_period)/max(mass_of_owners(time_period),10.d0**(-14))

        if (current_beta_type==number_of_beta_types) model_avg_housing_spending_all(time_period)=model_avg_housing_spending_all(time_period)/max(sum_of_distribution_not_be_homeless,10.d0**(-14))

        if (current_beta_type==number_of_beta_types) then
            model_avg_housing_spending_renters(time_period)=model_avg_housing_spending_renters(time_period)/&
                max(model_mass_renters_to_consider(time_period),10.d0**(-14))
        end if
            
        model_wealth_of_owners(time_period)=model_wealth_of_owners(time_period)/max(mass_of_owners(time_period),10.d0**(-14))
                    
        if (current_beta_type==number_of_beta_types) then
            model_fraction_unemployed_on_ui(time_period)=model_fraction_unemployed_on_ui(time_period)/&
                max(model_fraction_unemployed(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_fraction_of_unemployed_homeless(time_period)=model_fraction_of_unemployed_homeless(time_period)/&
                max(model_fraction_unemployed(time_period),10.d0**(-14))
        end if
            
        ! The unemployment RATE is unemployed over the working age population,
        ! not over everyone: sum_of_distribution includes retirees, who are now
        ! excluded from the numerator, so the rate would read low by the retired
        ! share. model_mass_total_raw is the working age base.
        if (model_mass_total_raw(time_period)>10.d0**(-12)) then

            if (current_beta_type==number_of_beta_types) then
                model_fraction_unemployed(time_period)=model_fraction_unemployed(time_period)/&
                    max(model_mass_total_raw(time_period),10.d0**(-14))
            end if

        else

            if (accumulating_beta_types==0) model_fraction_unemployed(time_period)=0

        end if
        
        if (current_beta_type==number_of_beta_types) then
            model_fraction_addicted_and_unemployed(time_period)=model_fraction_addicted_and_unemployed(time_period)/&
                max(model_fraction_addicted(time_period),10.d0**(-14))
        end if
        
        if (current_beta_type==number_of_beta_types) model_fraction_addicted(time_period)=model_fraction_addicted(time_period)/max(sum_of_distribution,10.d0**(-14))
        if (current_beta_type==number_of_beta_types) then
            model_fraction_homeless_and_addicted(time_period)=model_fraction_homeless_and_addicted(time_period)/&
                max(model_fraction_homeless(time_period),10.d0**(-14))
        end if
        
        ! Working age on both sides now: the numerator excludes retirees, so the
        ! base must too.
        if (model_mass_homeless_working_age(time_period)>10.d0**(-12)) then

            if (current_beta_type==number_of_beta_types) then
                model_fraction_of_homeless_unemployed(time_period)=&
                    model_fraction_of_homeless_unemployed(time_period)/&
                    max(model_mass_homeless_working_age(time_period),10.d0**(-14))
            end if

        else

            if (accumulating_beta_types==0) model_fraction_of_homeless_unemployed(time_period)=0

        end if

        ! The employed share of the homeless is the complement of the moment
        ! immediately above, so it is not accumulated separately.
        model_employed_share_of_homeless(time_period)=&
            1-model_fraction_of_homeless_unemployed(time_period)

        ! ALL THREE RATIOS USE THE RAW MASSES. Reconstructing a mass from
        ! model_fraction_homeless is wrong, because that share is normalised by
        ! model_sum_of_lowest_productivities rather than by the total.
        if (model_mass_homeless_raw(time_period)>10.d0**(-12)) then

            model_smi_share_of_homeless(time_period)=model_smi_and_homeless(time_period)/&
                max(model_mass_homeless_raw(time_period),10.d0**(-14))

        else

            if (accumulating_beta_types==0) model_smi_share_of_homeless(time_period)=0

        end if

        if ((model_mass_homeless_working_age(time_period)>10.d0**(-12)) .AND. &
            (model_all_labour_income(time_period)>10.d0**(-12)) .AND. &
            (model_mass_total_raw(time_period)>10.d0**(-12))) then

            model_homeless_income_share(time_period)=&
                (model_homeless_labour_income(time_period)/&
                model_mass_homeless_working_age(time_period))/&
                (model_all_labour_income(time_period)/model_mass_total_raw(time_period))

        else

            if (accumulating_beta_types==0) model_homeless_income_share(time_period)=0

        end if

        if (model_mass_smi(time_period)>10.d0**(-12)) then

            model_employment_rate_given_smi(time_period)=model_smi_and_employed(time_period)/&
                max(model_mass_smi(time_period),10.d0**(-14))

        end if

        ! THE SMI POPULATION SHARE, which smi_onset_level answers to, and what
        ! the assigned profile says it should be at the model's own age weights.
        ! Both over the same base, every age, so the ratio is a prevalence.
        if (sum(model_mass_by_age(:))>10.d0**(-12)) then

            model_smi_prevalence(time_period)=&
                sum(model_smi_mass_by_age(:))/sum(model_mass_by_age(:))

            if (allocated(smi_prevalence_by_age)) then

                model_smi_prevalence_target(time_period)=&
                    sum(smi_prevalence_by_age(:)*model_mass_by_age(:))/sum(model_mass_by_age(:))

            end if

        end if

        ! THE FOUR RAW PIECES OF THE HOMELESS INCOME SHARE. It came out at 1.15,
        ! meaning the homeless earn MORE than average, which is wrong signed and
        ! is the moment rho_m and rho_d calibrate against. Printing the parts
        ! says which one is wrong in a single run instead of by argument: if the
        ! two masses are inconsistent the ratio is a base problem, and if the two
        ! incomes are, it is an accumulation problem.
        write(*,*) "homeless income parts: inc_homeless=", model_homeless_labour_income(time_period), &
            " mass_homeless=", model_mass_homeless_raw(time_period), &
            " inc_all=", model_all_labour_income(time_period), &
            " mass_all=", model_mass_total_raw(time_period)

        ! THE DENOMINATOR MUST BE THE SAME POPULATION AS THE NUMERATOR.
        ! model_mass_total_raw counts working age households only, because the
        ! homeless income share needs that base, while model_mass_smi counts every
        ! age, so their ratio is not a prevalence of anything. The by age masses
        ! give the right total and also say WHERE a shortfall is.
        if ((number_of_smi_states>1) .AND. (allocated(smi_prevalence_by_age))) then

            write(*,*) "SMI prevalence by age, model against profile:"

            do smi_age_1=1,life_span,10

                write(*,'(A,I3,A,F9.5,A,F9.5)') "   age ", smi_age_1, &
                    "  model=", model_smi_mass_by_age(smi_age_1)/&
                    max(model_mass_by_age(smi_age_1),10.d0**(-12)), &
                    "  profile=", smi_prevalence_by_age(smi_age_1)

            end do

            write(*,*) "SMI prevalence all ages, model=", &
                sum(model_smi_mass_by_age(:))/max(sum(model_mass_by_age(:)),10.d0**(-12)), &
                " profile at the model's age weights=", &
                sum(smi_prevalence_by_age(:)*model_mass_by_age(:))/&
                max(sum(model_mass_by_age(:)),10.d0**(-12))

        end if

        write(*,*) "SMI mass over the working age base (not a prevalence)=", &
            model_mass_smi(time_period)/max(model_mass_total_raw(time_period),10.d0**(-12)), &
            " onset(1)=", smi_onset_by_age(1), " onset(30)=", smi_onset_by_age(30), " lambda_m=", lambda_m
        write(*,*) "SMI share of homeless=", model_smi_share_of_homeless(time_period), &
            " employment rate given SMI=", model_employment_rate_given_smi(time_period)
        write(*,*) "homeless income share=", model_homeless_income_share(time_period), &
            " employed share of homeless=", model_employed_share_of_homeless(time_period)

        ! The shares only replace the standing ones when there is mass to divide
        ! by, so the first sweep of a cold start keeps the clean housed default
        ! rather than dividing by zero.
        if (sum(newborn_parent_share_acc(:,:,:))>10.d0**(-12)) then

            newborn_parent_share(:,:,:)=newborn_parent_share_acc(:,:,:)/&
                sum(newborn_parent_share_acc(:,:,:))

        end if

        write(*,*) "parents replaced by newborns: clean housed=", sum(newborn_parent_share(:,0,1)), &
            " clean homeless=", sum(newborn_parent_share(:,0,2)), &
            " disordered housed=", sum(newborn_parent_share(:,1,1)), &
            " disordered homeless=", sum(newborn_parent_share(:,1,2))
            
        if (current_beta_type==number_of_beta_types) then
            model_fraction_homeless_owners(time_period)=model_fraction_homeless_owners(time_period)/&
                max(model_fraction_homeless(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_homeless_2_years_or_more(time_period)=&
                model_homeless_2_years_or_more(time_period)/max(model_fraction_homeless(time_period),10.d0**(-14))
        end if
                    
        if (current_beta_type==number_of_beta_types) then
            model_fraction_homeless(time_period)=model_fraction_homeless(time_period)/&
                model_sum_of_lowest_productivities(time_period)
        end if
        
        if (current_beta_type==number_of_beta_types) model_avg_rent_to_income_ratio(time_period)=model_avg_rent_to_income_ratio(time_period)/max(mass_of_legit_renters(time_period),10.d0**(-14))
        
        do i=2,number_of_grids_rent_to_income_cdf
        
            rent_to_income_cdf(time_period,i)=rent_to_income_cdf(time_period,i-1)+rent_to_income_cdf(time_period,i)
            
            rent_to_income_homeless_cdf(time_period,i)=rent_to_income_homeless_cdf(time_period,i-1)+&
                rent_to_income_homeless_cdf(time_period,i)
                    
        end do
                
        if (current_beta_type==number_of_beta_types) rent_to_income_cdf(time_period,:)=rent_to_income_cdf(time_period,:)/max(total_renters_to_consider,10.d0**(-14))
        if (current_beta_type==number_of_beta_types) rent_to_income_homeless_cdf(time_period,:)=rent_to_income_homeless_cdf(time_period,:)/max(total_homeless_1,10.d0**(-14))
        
        median_index=minloc(rent_to_income_homeless_cdf(time_period,:),1,&
            mask=rent_to_income_homeless_cdf(time_period,:)-0.5>=0)
                        
        percentiles_homeless_income(time_period,1)=&
            (model_average_rent(time_period)*model_average_rental_unit_size(time_period))/&
            rent_to_income_ratios(time_period,max(median_index(1),1))
            
        median_index=minloc(rent_to_income_homeless_cdf(time_period,:),1,&
            mask=rent_to_income_homeless_cdf(time_period,:)-0.25>=0)
                        
        percentiles_homeless_income(time_period,2)=&
            (model_average_rent(time_period)*model_average_rental_unit_size(time_period))/&
            rent_to_income_ratios(time_period,max(median_index(1),1))
        
        do i=2,101
        
            LTV_cdf(time_period,i)=LTV_cdf(time_period,i-1)+LTV_cdf(time_period,i)
            
        end do
                
        LTV_cdf(time_period,:)=LTV_cdf(time_period,:)/max(total_owners_to_consider,10.d0**(-14))
        
        write(*,*) "rent_to_income_cdf(time_period,101)=", rent_to_income_cdf(time_period,101)
        write(*,*) "total_renters_to_consider=", total_renters_to_consider
                                             
        if (solve_transition_dynamics==0) then
                              
            write(*,*) "model_financial(",time_period,")=", model_financial(time_period)
            write(*,*) "model_mortgages(",time_period,")=", model_mortgages(time_period)
            write(*,*) "model_net_housing_wealth(",time_period,")=", model_net_housing_wealth(time_period)
            write(*,*) "model_gross_housing_wealth(",time_period,")=", model_gross_housing_wealth(time_period)
            write(*,*) "model_total_net_wealth(",time_period,")=", model_total_net_wealth(time_period)
            write(*,*) "model_bequests(",time_period,")=", model_bequests(time_period)
            write(*,*) "model_average_net_wealth(time_period)=", model_average_net_wealth(time_period)
            
        end if
        
        mortgage_interest_rate(time_period)=risk_free_rate(time_period)+mortgage_interest_gap
                                                        
        if (current_beta_type==number_of_beta_types) model_average_labour_income(time_period)=model_average_labour_income(time_period)/max(model_total_workers(time_period),10.d0**(-14))
        if (current_beta_type==number_of_beta_types) call set_newborn_age_transfer(time_period)
        if (current_beta_type==number_of_beta_types) call set_renter_floor(time_period)
        if (current_beta_type==number_of_beta_types) model_average_income(time_period)=model_average_income(time_period)/max(sum_of_distribution,10.d0**(-14))
        if (current_beta_type==number_of_beta_types) model_average_income_plus_assets(time_period)=model_average_income_plus_assets(time_period)/max(sum_of_distribution,10.d0**(-14))
        if (current_beta_type==number_of_beta_types) then
            model_average_income_plus_all_assets(time_period)=&
                model_average_income_plus_all_assets(time_period)/max(sum_of_distribution,10.d0**(-14))
        end if
                
        do age_index=1,life_span
        
        ! NORMALISE ONLY ON THE LAST PASS. This division puts its result back
        ! into the accumulator it reads, and the reset above is guarded to the
        ! FIRST pass, so without this guard the second pass divides an already
        ! divided value again and adds the second type on top of a finished
        ! average. Nothing at one type moves: the condition is 1==1 there.
        if (current_beta_type==number_of_beta_types) then
                average_rent_by_age(age_index)=average_rent_by_age(age_index)/max(mass_of_renters_by_age(age_index),10.d0**(-14))
        end if
            if (current_beta_type==number_of_beta_types) value_of_bequests_by_age(age_index)=value_of_bequests_by_age(age_index)/bequests_mass_by_age(age_index)
        
        end do
                
        do employment_index=1,employment_grid_size
        
            if (current_beta_type==number_of_beta_types) then
                model_average_labour_income_by_employment(time_period,employment_index)=&
                    model_average_labour_income_by_employment(time_period,employment_index)/&
                    max(mass_by_employment(time_period,employment_index),10.d0**(-14))
            end if
        
        end do
        
        model_GDP_incl_imput_rent(time_period)=model_GDP(time_period)+total_imputed_rents(time_period)
                                                                    
    end subroutine
        
    subroutine stationary_equilibirum_homeownership_rate(time_period)
    
        use Global_Vars
        
        implicit none
        
        integer, intent(in) :: time_period
        integer :: time_period_used,financial_index_used,financial_index,has_house,&
            housing_status_index_used,amortization_used,low_quality_market
        real(8) :: lived_in_size_used,labor_supply_used,distribution_mass_used,income_1,LTV_1,&
            avg_income_to_use_1,avg_income_to_use_2
            
        avg_income_to_use_1=is_counterfactual*average_labor_income_calibrated+&
            (1-is_counterfactual)*model_average_labour_income(time_period)
                            
        time_period_used=time_period-solve_transition_dynamics
                        
        if (accumulating_beta_types==0) model_fraction_of_homeowners_with_mortgage(time_period)=0
        if (accumulating_beta_types==0) model_fraction_of_homeowners_with_mortgage_over_20_perc(time_period)=0
        if (accumulating_beta_types==0) model_fraction_of_homeowners_with_mortgage_over_80_perc(time_period)=0
        if (accumulating_beta_types==0) model_fraction_of_homeowners_with_mortgage_over_90_perc(time_period)=0
        
        if (accumulating_beta_types==0) model_average_owner_occupied_unit_size(time_period)=0
        if (accumulating_beta_types==0) model_average_owner_occupied_unit_size_to_income(time_period)=0
        if (accumulating_beta_types==0) model_average_owner_occupied_unit_size_to_income_work_age(time_period)=0
        if (accumulating_beta_types==0) working_age_mass(time_period)=0
        if (accumulating_beta_types==0) model_average_owners_income(time_period)=0
        if (accumulating_beta_types==0) model_average_rental_unit_size(time_period)=0
        if (accumulating_beta_types==0) model_average_rent(time_period)=0
        if (accumulating_beta_types==0) mass_of_renters(time_period)=0
        if (accumulating_beta_types==0) model_wealth_of_renters(time_period)=0
        ! ONE OWNER PER VARIABLE. Reset and accumulation disabled here.
        !
        ! Every reset in the chain is guarded to the FIRST pass, which is safe only
        ! if exactly one routine owns the variable. Where two or more each reset and
        ! each accumulate, the guard that stops pass two resetting also lets each
        ! routine start from whatever the previous one left, so the second pass adds
        ! another copy of the second type on top of a finished total. Four owners of
        ! mass_by_employment made it 5*M where the pooled mass is 2*M, so every
        ! welfare-by-employment average was halved and homeownership_by_employment
        ! came out at 0.4 times truth.
        !
        ! It is the same quantity in every owner, so the FIRST in call order keeps
        ! it and the rest read it. The order is the same in the driver and in
        ! long_run_counter_factual, so the value is always built before it is read.
        ! if (accumulating_beta_types==0) mass_of_owners(time_period)=0
        if (accumulating_beta_types==0) mass_of_owners_with_mortgage(time_period)=0
                
        if (accumulating_beta_types==0) largest_housing_size_consumed_in_equilibrium=0
        if (accumulating_beta_types==0) fraction_with_largest_housing_size_consumed_in_eqilibrium=0
        if (accumulating_beta_types==0) fraction_with_smallest_financial_in_eqilibrium=0
        if (accumulating_beta_types==0) largest_financial_chosen_in_equilibrium=0
        ! SAME CLASS as the minimum tracker above, and its own guarded twin sits on the
        ! line above it.
        if (accumulating_beta_types==0) smallest_financial_chosen_in_equilibrium=financial_grid_size
        
        if (accumulating_beta_types==0) total_housing_demand(time_period)=0
        if (accumulating_beta_types==0) total_rental_demand(time_period,:)=0
        if (accumulating_beta_types==0) total_rental_demand_segmented(time_period,:)=0
        if (accumulating_beta_types==0) renters_by_rental(time_period,:)=0
        if (accumulating_beta_types==0) total_renters(time_period)=0
                
        if (accumulating_beta_types==0) average_age_of_homeowner_by_employment(time_period,:)=0
        if (accumulating_beta_types==0) mass_homeowners_by_employment(time_period,:)=0
        if (accumulating_beta_types==0) mass_renters_by_age(time_period,:)=0
            
        if (accumulating_beta_types==0) model_mass_switchers(time_period)=0
        if (accumulating_beta_types==0) model_age_switchers_to_renting(time_period)=0
        if (accumulating_beta_types==0) model_prod_switchers_to_renting(time_period)=0
        if (accumulating_beta_types==0) model_financial_switchers_to_renting(time_period)=0
        if (accumulating_beta_types==0) model_house_size_switchers_to_renting(time_period)=0
        
        if (accumulating_beta_types==0) model_mass_non_switcher_renters(time_period)=0
        if (accumulating_beta_types==0) model_age_non_switcher_renters(time_period)=0
        if (accumulating_beta_types==0) model_prod_non_switcher_renters(time_period)=0
        if (accumulating_beta_types==0) model_financial_non_switcher_renters(time_period)=0
        if (accumulating_beta_types==0) model_house_size_non_switcher_renters(time_period)=0
        
        if (accumulating_beta_types==0) model_mass_switchers_mortgages(time_period)=0
        if (accumulating_beta_types==0) model_age_switchers_mortgages_to_renting(time_period)=0
        if (accumulating_beta_types==0) model_prod_switchers_mortgages_to_renting(time_period)=0
        if (accumulating_beta_types==0) model_financial_switchers_mortgages_to_renting(time_period)=0
        if (accumulating_beta_types==0) model_house_size_switchers_mortgages_to_renting(time_period)=0
        
        if (accumulating_beta_types==0) mass_by_age_and_employment(time_period,:,:)=0
        
        do age_index=1,life_span
                    
            if (age_index>life_span-retirement_span) then
            
                in_retirement=1
                
            else
            
                in_retirement=0
            
            end if
                            
            do years_left_on_mortgage_index=1,max_amortization_years
                            
                if (years_left_on_mortgage_index>1) then
                    
                    has_house=1
                    
                else
                
                    has_house=0
                    
                end if
                
                do unemployment_index=1,unemployment_grid_size
                
                    do employment_index=1,employment_grid_size

                        avg_income_to_use_2=is_counterfactual*average_labor_income_by_employment_calibrated(employment_index)+&
                            (1-is_counterfactual)*model_average_labour_income_by_employment(time_period,employment_index)
                                                    
                        do voucher_index=0,(1-has_house)*include_vouchers
                        
                            do financial_index=has_house*1+(1-has_house)*renter_floor_by_age(min(max(age_index,1),life_span)),financial_grid_size
                                               
                                do housing_status_index=(1-has_house)*lowest_housing_grid_point+&
                                    has_house*index_of_smallest_house_hhld_can_buy,housing_status_grid_size-1
                                              
                                    lived_in_size_used=policy_function_space_lived_in_size(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                                                    
                                    housing_status_index_used=policy_function_housing_status_index(years_left_on_mortgage_index)%&
                                        vector_transition_integer(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    financial_index_used=policy_function_financial_index(years_left_on_mortgage_index)%&
                                        vector_transition_integer(time_period,age_index,financial_index,&
                                       unemployment_index,employment_index,housing_status_index,voucher_index)
                                            
                                    amortization_used=policy_function_years_of_amortization_index(years_left_on_mortgage_index)%&
                                        vector_transition_integer(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    labor_supply_used=policy_function_labor_supply(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                                                            
                                    distribution_mass_used=distribution_stationary(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period_used,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    if ((housing_status_index_used>second_lowest_housing_grid_point) .OR. &
                                       (have_two_rental_markets==0)) then
                                    
                                        low_quality_market=0
                                    
                                    else
                                    
                                        low_quality_market=1
                                    
                                    end if

                                    call calculate_income(unemployment_index,employment_index,income_1,&
                                        avg_income_to_use_1,avg_income_to_use_2,labor_supply_used,in_retirement)

                                    income_1=income_1+max(financial_grid(financial_index),0.d0)*risk_free_rate(time_period)            
                                                                
                                    if ((housing_status_index_used>largest_housing_size_consumed_in_equilibrium) .AND. &
                                        (distribution_mass_used>0)) then
                                       
                                        largest_housing_size_consumed_in_equilibrium=housing_status_index_used
                                       
                                    end if
                                    
                                    if ((financial_index_used>largest_financial_chosen_in_equilibrium) .AND. &
                                        (distribution_mass_used>0)) then
                                    
                                        largest_financial_chosen_in_equilibrium=financial_index_used
                                       
                                    end if
                                    
                                    if ((financial_index_used<smallest_financial_chosen_in_equilibrium) .AND. &
                                        (distribution_mass_used>0)) then
                                    
                                        smallest_financial_chosen_in_equilibrium=financial_index_used
                                       
                                    end if
                                                                    
                                    if (years_left_on_mortgage_index>1) then
                                    
                                        if (amortization_used<=1) then
                                        
                                            model_mass_switchers(time_period)=model_mass_switchers(time_period)+&
                                                distribution_mass_used
                                        
                                            model_age_switchers_to_renting(time_period)=&
                                                model_age_switchers_to_renting(time_period)+age_index*distribution_mass_used
                                                
                                            model_prod_switchers_to_renting(time_period)=&
                                                model_prod_switchers_to_renting(time_period)+distribution_mass_used
                                                
                                            model_financial_switchers_to_renting(time_period)=&
                                                model_financial_switchers_to_renting(time_period)+&
                                                max(financial_grid(financial_index),0.d0)*distribution_mass_used
                                                
                                            model_house_size_switchers_to_renting(time_period)=&
                                                model_house_size_switchers_to_renting(time_period)+&
                                                housing_status_index*distribution_mass_used
                                                
                                            if (financial_index<negative_financial_grid_size) then
                                            
                                                model_mass_switchers_mortgages(time_period)=&
                                                    model_mass_switchers_mortgages(time_period)+distribution_mass_used
                                        
                                                model_age_switchers_mortgages_to_renting(time_period)=&
                                                    model_age_switchers_mortgages_to_renting(time_period)+&
                                                    age_index*distribution_mass_used
                                                    
                                                model_prod_switchers_mortgages_to_renting(time_period)=&
                                                    model_prod_switchers_mortgages_to_renting(time_period)+&
                                                    distribution_mass_used
                                                    
                                                model_financial_switchers_mortgages_to_renting(time_period)=&
                                                    model_financial_switchers_mortgages_to_renting(time_period)+&
                                                    max(financial_grid(financial_index),0.d0)*distribution_mass_used
                                                    
                                                model_house_size_switchers_mortgages_to_renting(time_period)=&
                                                    model_house_size_switchers_mortgages_to_renting(time_period)+&
                                                    housing_status_index*distribution_mass_used
                                            
                                            end if                                            
                                                                                    
                                        end if
                                    
                                    end if
                                    
                                    if (years_left_on_mortgage_index<=1) then
                                    
                                        if (amortization_used<=1) then
                                        
                                            model_mass_non_switcher_renters(time_period)=&
                                                model_mass_non_switcher_renters(time_period)+distribution_mass_used
                                        
                                            model_age_non_switcher_renters(time_period)=&
                                                model_age_non_switcher_renters(time_period)+age_index*distribution_mass_used
                                                
                                            model_prod_non_switcher_renters(time_period)=&
                                                model_prod_non_switcher_renters(time_period)+distribution_mass_used
                                                
                                            model_financial_non_switcher_renters(time_period)=&
                                                model_financial_non_switcher_renters(time_period)+&
                                                max(financial_grid(financial_index),0.d0)*distribution_mass_used
                                                
                                            model_house_size_non_switcher_renters(time_period)=&
                                                model_house_size_non_switcher_renters(time_period)+&
                                                housing_status_index*distribution_mass_used
                                        
                                        end if    
                                    
                                    end if
                            
                                    if ((amortization_used==1) .AND. &
                                        (housing_status_index_used>=second_lowest_housing_grid_point)) then
                        
                                        model_average_rental_unit_size(time_period)=model_average_rental_unit_size(time_period)+&
                                            lived_in_size_used*distribution_mass_used
                                            
                                        model_average_rent(time_period)=model_average_rent(time_period)+&
                                            rent(time_period,low_quality_market)*lived_in_size_used*distribution_mass_used
                                                                    
                                        mass_of_renters(time_period)=mass_of_renters(time_period)+distribution_mass_used
                                        
                                        model_wealth_of_renters(time_period)=model_wealth_of_renters(time_period)+&
                                            (max(amortization_used-1,0)*&
                                            housing_price(time_period)*housing_size(housing_status_index)+&
                                            min(financial_grid(financial_index),0.d0)*&
                                            housing_price(time_period)*housing_size(housing_status_index)+&
                                            max(financial_grid(financial_index),0.d0))*distribution_mass_used
                                                                                                                            
                                    elseif (amortization_used>1) then
                        
                                        model_average_owner_occupied_unit_size(time_period)=&
                                            model_average_owner_occupied_unit_size(time_period)+&
                                            lived_in_size_used*distribution_mass_used
                                            
                                        if (income_1>0) then
                                            
                                            model_average_owner_occupied_unit_size_to_income(time_period)=&
                                                model_average_owner_occupied_unit_size_to_income(time_period)+&
                                                ((lived_in_size_used*housing_price(time_period))/(income_1))*&
                                                distribution_mass_used
                                                
                                            if (in_retirement==0) then
                                            
                                                model_average_owner_occupied_unit_size_to_income_work_age(time_period)=&
                                                    model_average_owner_occupied_unit_size_to_income_work_age(time_period)+&
                                                    ((lived_in_size_used*housing_price(time_period))/(income_1))*&
                                                    distribution_mass_used
                                                    
                                                working_age_mass(time_period)=working_age_mass(time_period)+distribution_mass_used
                                                    
                                            end if
                                            
                                        end if
                                            
                                        model_average_owners_income(time_period)=model_average_owners_income(time_period)+&
                                            income_1*distribution_mass_used
                                            
                                        ! ONE OWNER PER VARIABLE. Reset and accumulation disabled here.
                                        !
                                        ! Every reset in the chain is guarded to the FIRST pass, which is safe only
                                        ! if exactly one routine owns the variable. Where two or more each reset and
                                        ! each accumulate, the guard that stops pass two resetting also lets each
                                        ! routine start from whatever the previous one left, so the second pass adds
                                        ! another copy of the second type on top of a finished total. Four owners of
                                        ! mass_by_employment made it 5*M where the pooled mass is 2*M, so every
                                        ! welfare-by-employment average was halved and homeownership_by_employment
                                        ! came out at 0.4 times truth.
                                        !
                                        ! It is the same quantity in every owner, so the FIRST in call order keeps
                                        ! it and the rest read it. The order is the same in the driver and in
                                        ! long_run_counter_factual, so the value is always built before it is read.
                                        ! mass_of_owners(time_period)=mass_of_owners(time_period)+distribution_mass_used
                                        
                                        if (min(financial_grid(financial_index_used),0.d0)<0) then
                                        
                                            mass_of_owners_with_mortgage(time_period)=&
                                                mass_of_owners_with_mortgage(time_period)+distribution_mass_used
                                    
                                            model_fraction_of_homeowners_with_mortgage(time_period)=&
                                                model_fraction_of_homeowners_with_mortgage(time_period)+distribution_mass_used
                                                
                                            LTV_1=-min(financial_grid(financial_index_used),0.d0)
                                                
                                            if (LTV_1>minimum_downpayment) then
                                                
                                                model_fraction_of_homeowners_with_mortgage_over_20_perc(time_period)=&
                                                    model_fraction_of_homeowners_with_mortgage_over_20_perc(time_period)+&
                                                    distribution_mass_used

                                            end if
                                                
                                            if (LTV_1>(1-minimum_downpayment)) then
                                                
                                                model_fraction_of_homeowners_with_mortgage_over_80_perc(time_period)=&
                                                    model_fraction_of_homeowners_with_mortgage_over_80_perc(time_period)+&
                                                    distribution_mass_used

                                            end if
                                            
                                            if (LTV_1>(1-minimum_downpayment+min_down_of_second_smallest)) then
                                                
                                                model_fraction_of_homeowners_with_mortgage_over_90_perc(time_period)=&
                                                    model_fraction_of_homeowners_with_mortgage_over_90_perc(time_period)+&
                                                    distribution_mass_used

                                            end if
                                                                        
                                        end if
                                                            
                                    end if
                                    
                                    if ((housing_status_index_used==(housing_status_grid_size-1)) .AND. &
                                        (distribution_mass_used>0)) then
                                        
                                        fraction_with_largest_housing_size_consumed_in_eqilibrium=&
                                            fraction_with_largest_housing_size_consumed_in_eqilibrium+&
                                            distribution_mass_used
                                        
                                    end if
                                                                
                                    if ((financial_index_used==smallest_financial_chosen_in_equilibrium) .AND. &
                                        (distribution_mass_used>0)) then
                                        
                                        fraction_with_smallest_financial_in_eqilibrium=&
                                            fraction_with_smallest_financial_in_eqilibrium+&
                                            distribution_mass_used
                                        
                                    end if
                                    
                                    if (housing_status_index_used>=second_lowest_housing_grid_point) then
                                    
                                        total_housing_demand(time_period)=total_housing_demand(time_period)+&
                                            lived_in_size_used*distribution_mass_used
                                            
                                    end if
                                                                                                                
                                    mass_by_age_and_employment(time_period,age_index,employment_index)=&
                                        mass_by_age_and_employment(time_period,age_index,employment_index)+&
                                        distribution_mass_used
                                                                                                  
                                    if (amortization_used<=1) then
                                    
                                        if (housing_status_index_used>=second_lowest_housing_grid_point) then
                                                                                
                                            total_rental_demand(time_period,low_quality_market)=&
                                                total_rental_demand(time_period,low_quality_market)+&
                                                lived_in_size_used*distribution_mass_used
                                                
                                            if (housing_status_index_used>second_lowest_housing_grid_point) then
                                            
                                                low_quality_market=0
                                            
                                            else
                                            
                                                low_quality_market=1
                                            
                                            end if
                                            
                                            total_rental_demand_segmented(time_period,low_quality_market)=&
                                                total_rental_demand_segmented(time_period,low_quality_market)+&
                                                lived_in_size_used*distribution_mass_used
                                                
                                            renters_by_rental(time_period,housing_status_index_used)=&
                                                renters_by_rental(time_period,housing_status_index_used)+&
                                                distribution_mass_used
                                                
                                            total_renters(time_period)=total_renters(time_period)+distribution_mass_used
                                                
                                        end if
                                                                                                                                 
                                        mass_renters_by_age(time_period,age_index)=mass_renters_by_age(time_period,age_index)+&
                                            distribution_mass_used
                                                                                                                                                           
                                    else
                                    
                                        average_age_of_homeowner_by_employment(time_period,employment_index)=&
                                            average_age_of_homeowner_by_employment(time_period,employment_index)+&
                                            age_index*distribution_mass_used
                                            
                                        mass_homeowners_by_employment(time_period,employment_index)=&
                                            mass_homeowners_by_employment(time_period,employment_index)+&
                                            distribution_mass_used
                                                                        
                                    end if 
                                    
                                end do
                                    
                            end do
                            
                        end do
                        
                    end do
                    
                end do
                                            
            end do
            
        end do
        
        if (current_beta_type==number_of_beta_types) then
            renters_by_rental(time_period,:)=&
                renters_by_rental(time_period,:)/max(total_renters(time_period),10.d0**(-14))
        end if

        if (sum(renters_by_rental(time_period,0:housing_status_grid_size-1))>0) then

            model_housing_size_dist(time_period,:)=&
                renters_by_rental(time_period,0:housing_status_grid_size-1)/&
                sum(renters_by_rental(time_period,0:housing_status_grid_size-1))

        else

            if (accumulating_beta_types==0) model_housing_size_dist(time_period,:)=0

        end if
        
        if (current_beta_type==number_of_beta_types) then
            total_rental_demand_segmented(time_period,:)=total_rental_demand_segmented(time_period,:)/&
                sum(total_rental_demand_segmented(time_period,:))
        end if
        
        if (current_beta_type==number_of_beta_types) then
            model_age_switchers_to_renting(time_period)=&
                model_age_switchers_to_renting(time_period)/max(model_mass_switchers(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_prod_switchers_to_renting(time_period)=&
                model_prod_switchers_to_renting(time_period)/max(model_mass_switchers(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_financial_switchers_to_renting(time_period)=&
                model_financial_switchers_to_renting(time_period)/max(model_mass_switchers(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_house_size_switchers_to_renting(time_period)=&
                model_house_size_switchers_to_renting(time_period)/max(model_mass_switchers(time_period),10.d0**(-14))
        end if
                
        if (current_beta_type==number_of_beta_types) model_age_non_switcher_renters(time_period)=model_age_non_switcher_renters(time_period)/max(model_mass_non_switcher_renters(time_period),10.d0**(-14))
            
        if (current_beta_type==number_of_beta_types) model_prod_non_switcher_renters(time_period)=model_prod_non_switcher_renters(time_period)/max(model_mass_non_switcher_renters(time_period),10.d0**(-14))
            
        if (current_beta_type==number_of_beta_types) then
            model_financial_non_switcher_renters(time_period)=&
                model_financial_non_switcher_renters(time_period)/max(model_mass_non_switcher_renters(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_house_size_non_switcher_renters(time_period)=&
                model_house_size_non_switcher_renters(time_period)/max(model_mass_non_switcher_renters(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_age_switchers_mortgages_to_renting(time_period)=&
                model_age_switchers_mortgages_to_renting(time_period)/max(model_mass_switchers_mortgages(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_prod_switchers_mortgages_to_renting(time_period)=&
                model_prod_switchers_mortgages_to_renting(time_period)/max(model_mass_switchers_mortgages(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_financial_switchers_mortgages_to_renting(time_period)=&
                model_financial_switchers_mortgages_to_renting(time_period)/max(model_mass_switchers_mortgages(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_house_size_switchers_mortgages_to_renting(time_period)=&
                model_house_size_switchers_mortgages_to_renting(time_period)/max(model_mass_switchers_mortgages(time_period),10.d0**(-14))
        end if
        
        sum_of_distribution=0
        
        do i=1,2
                
            sum_of_distribution=sum_of_distribution+&
                sum(distribution_stationary(i)%vector_transition_real(time_period,:,:,:,:,:,:))
            
        end do

        ! POOLED MASS, NOT ONE TYPE'S. The histograms and every other
        ! accumulator above hold both discount-factor types once the
        ! benchmark chain has run twice, so a denominator recomputed from
        ! distribution_stationary -- which holds only the type just solved --
        ! is short by exactly the number of passes. Scale it up.
        ! POOLED MASS, READ NOT REBUILT. stationary_equilibrium_statistics runs
        ! FIRST in every pass and has already added this type's mass, so the
        ! total here is the real pooled mass rather than one type's scaled by a
        ! pass count. The types do not weigh the same; see pooled_mass_all.
        sum_of_distribution=pooled_mass_all
        
        if (solve_transition_dynamics==0) then
        
            write(*,*) "sum_of_distribution=", sum_of_distribution
            
        end if
                          
        if (current_beta_type==number_of_beta_types) then
            model_average_rental_unit_size(time_period)=&
                model_average_rental_unit_size(time_period)/max(mass_of_renters(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) model_average_rent(time_period)=model_average_rent(time_period)/sum(total_rental_demand(time_period,:))
                        
        if (current_beta_type==number_of_beta_types) then
            model_average_owner_occupied_unit_size(time_period)=&
                model_average_owner_occupied_unit_size(time_period)/max(mass_of_owners(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_average_owner_occupied_unit_size_to_income(time_period)=&
                model_average_owner_occupied_unit_size_to_income(time_period)/max(mass_of_owners(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_average_owner_occupied_unit_size_to_income_work_age(time_period)=&
                model_average_owner_occupied_unit_size_to_income_work_age(time_period)/max(working_age_mass(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) model_average_owners_income(time_period)=model_average_owners_income(time_period)/max(mass_of_owners(time_period),10.d0**(-14))
             
        model_homeownership_rate(time_period)=mass_of_owners(time_period)/sum_of_distribution_not_be_homeless
            
        if (current_beta_type==number_of_beta_types) then
            model_fraction_of_homeowners_with_mortgage(time_period)=&
                model_fraction_of_homeowners_with_mortgage(time_period)/max(mass_of_owners(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_fraction_of_homeowners_with_mortgage_over_80_perc(time_period)=&
                model_fraction_of_homeowners_with_mortgage_over_80_perc(time_period)/&
                max(model_fraction_of_homeowners_with_mortgage(time_period)*mass_of_owners(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_fraction_of_homeowners_with_mortgage_over_90_perc(time_period)=&
                model_fraction_of_homeowners_with_mortgage_over_90_perc(time_period)/&
                max(model_fraction_of_homeowners_with_mortgage(time_period)*mass_of_owners(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_fraction_of_homeowners_with_mortgage_over_20_perc(time_period)=&
                model_fraction_of_homeowners_with_mortgage_over_20_perc(time_period)/&
                max(model_fraction_of_homeowners_with_mortgage(time_period)*mass_of_owners(time_period),10.d0**(-14))
        end if
                        
        if (current_beta_type==number_of_beta_types) model_wealth_of_renters(time_period)=model_wealth_of_renters(time_period)/max(mass_of_renters(time_period),10.d0**(-14))
            
        if (solve_transition_dynamics==0) then
            
            write(*,*) "model_homeownership_rate(time_period)", model_homeownership_rate(time_period)
        
            write(*,*) "model_average_rental_unit_size(time_period)=", model_average_rental_unit_size(time_period)
            
            write(*,*) "model_average_rent(time_period)=", model_average_rent(time_period)
            
            write(*,*) "model_average_owner_occupied_unit_size(time_period)=", model_average_owner_occupied_unit_size(time_period)
            
            write(*,*) "model_average_rental_unit_size(time_period)/model_average_owner_occupied_unit_size(time_period)=", &
                model_average_rental_unit_size(time_period)/max(model_average_owner_occupied_unit_size(time_period),10.d0**(-14))
            
            write(*,*) "model_fraction_of_homeowners_with_mortgage(time_period)=", &
                model_fraction_of_homeowners_with_mortgage(time_period)
                                
        end if
                
        ! NORMALISE ONLY ON THE LAST PASS. This division puts its result back
        ! into the accumulator it reads, and the reset above is guarded to the
        ! FIRST pass, so without this guard the second pass divides an already
        ! divided value again and adds the second type on top of a finished
        ! average. Nothing at one type moves: the condition is 1==1 there.
        if (current_beta_type==number_of_beta_types) then
            fraction_with_largest_housing_size_consumed_in_eqilibrium=&
                fraction_with_largest_housing_size_consumed_in_eqilibrium/sum_of_distribution
        end if
            
        ! NORMALISE ONLY ON THE LAST PASS. This division puts its result back
        ! into the accumulator it reads, and the reset above is guarded to the
        ! FIRST pass, so without this guard the second pass divides an already
        ! divided value again and adds the second type on top of a finished
        ! average. Nothing at one type moves: the condition is 1==1 there.
        if (current_beta_type==number_of_beta_types) then
            fraction_with_smallest_financial_in_eqilibrium=fraction_with_smallest_financial_in_eqilibrium/sum_of_distribution
        end if
                      
        do employment_index=1,employment_grid_size
                        
            if (current_beta_type==number_of_beta_types) then
                average_age_of_homeowner_by_employment(time_period,employment_index)=&
                    average_age_of_homeowner_by_employment(time_period,employment_index)/&
                    max(mass_homeowners_by_employment(time_period,employment_index),10.d0**(-14))
            end if
                    
        end do
                  
        if (accumulating_beta_types==0) total_rental_supply(time_period,:)=0
    
        if (is_counterfactual==1) then
        
            if (infinite_elasticity_of_rental_supply==1) then
            
                total_rental_supply(time_period,:)=total_rental_demand(time_period,:)
                    
            else
            
                if (zero_elasticity==0) then
                
                    do i=0,have_two_rental_markets
                                                    
                        total_rental_supply(time_period,i)=max(((rent(time_period,i)-&
                            housing_price(time_period)+(1/(1+risk_free_rate(time_period)))*&
                            (housing_price(time_period-solve_transition_dynamics)*&
                            (1-housing_depreciation_rate-property_tax(time_period-solve_transition_dynamics)-&
                            property_tax_on_rental_housing)))/(rental_management_costs_calibrated(i)*&
                            convexity_of_rental_company(i))),0.d0)**(1/(convexity_of_rental_company(i)-1))
                            
                    end do
                                            
                end if
                    
            end if
                         
        else

             if (infinite_elasticity_of_rental_supply==1) then
            
                total_rental_supply(time_period,:)=total_rental_demand(time_period,:)
                    
            else
            
                if (zero_elasticity==0) then
                
                    do j=0,have_two_rental_markets

                        total_rental_supply(time_period,j)=max(((rent(time_period,j)-&
                            housing_price(time_period)+(1/(1+risk_free_rate(time_period)))*&
                            (housing_price(time_period-solve_transition_dynamics)*(1-housing_depreciation_rate-&
                            property_tax(time_period-solve_transition_dynamics)-property_tax_on_rental_housing)))/&
                            (rental_management_costs(j)*convexity_of_rental_company(j))),0.d0)**&
                            (1/(convexity_of_rental_company(j)-1))
                            
                    end do
                        
                else
                
                    total_rental_supply(time_period,:)=total_rental_demand(time_period,:)
                
                end if

            end if
            
        end if
                                      
    end subroutine
    
    subroutine stationary_equilibrium_wealth_distribution(time_period)
    
        use Global_Vars
        
        implicit none
        
        integer :: financial_index,loop_over_complete_distribution,wealth_counter_2,time_period,wealth_of_top_x_perc_index,has_house
        real(8) :: frac_of_household_mas_to_add,sum_distribution_used,net_wealth_used
                
        sum_of_distribution=0
        
        do i=1,2
                
            sum_of_distribution=sum_of_distribution+&
                sum(distribution_stationary(i)%vector_transition_real(time_period,:,:,:,:,:,:))
            
        end do

        ! NOT SCALED HERE, AND THAT IS DELIBERATE. This routine has NO
        ! guarded resets: it rebuilds wealth_counter, wealth_matrix and
        ! model_total_net_wealth_1 from distribution_stationary every time
        ! it runs, so its numerators are ONE type. Scaling the denominator
        ! to pooled mass would take the top-one-per-cent cut at two per
        ! cent of the mass actually being walked and divide a one-type
        ! head count by a two-type mass.
        !
        ! The mass_passes replacement made this morning was right for the
        ! routines whose accumulators survive the loop and wrong here, and
        ! the audit caught it the same day. A denominator must match the
        ! population of its own numerator, not the population of the model.
        
        wealth_counter=0
        
        wealth_matrix(time_period,:,:,:)=-housing_price(time_period)*housing_size(housing_status_grid_size-1)
        
        model_total_net_wealth_1(time_period)=0
        
        do years_left_on_mortgage_index=1,max_amortization_years
        
            if (years_left_on_mortgage_index==2) then
            
                has_house=1
                
            else
            
                has_house=0
                
            end if
        
            ! renter_array_floor, not renter_floor_by_age: age_index is not set
            ! in this routine either, and this is the same wealth_matrix walk
            ! that aborted at 11791 with minloc over an all-false mask, when the
            ! debt points were left out of the numerator while their mass stayed
            ! in the divisor.
            do financial_index=has_house*1+(1-has_house)*renter_array_floor,financial_grid_size
            
                do housing_status_index=(1-has_house)*lowest_housing_grid_point+&
                    has_house*index_of_smallest_house_hhld_can_buy,(housing_status_grid_size-1)
                    
                    sum_distribution_used=&
                        sum(distribution_stationary(years_left_on_mortgage_index)%&
                        vector_transition_real(time_period,:,financial_index,:,:,housing_status_index,:))
                                                    
                    if (sum_distribution_used>0) then
                    
                        ! Gated on has_house for the same reason as net_wealth_1
                        ! above: the middle term is an OWNER's mortgage, a negative
                        ! position read as a fraction of the dwelling's value, and
                        ! applying it to a renter multiplies unsecured debt by the
                        ! value of the flat they rent. The last term is truncated
                        ! for owners only, whose negative position is already the
                        ! mortgage; for a renter it is the position itself.
                        net_wealth_used=has_house*&
                            housing_price(time_period)*housing_size(housing_status_index)+&
                            has_house*min(financial_grid(financial_index),0.d0)*&
                            housing_price(time_period)*housing_size(housing_status_index)+&
                            has_house*max(financial_grid(financial_index),0.d0)+&
                            (1-has_house)*financial_grid(financial_index)
                        
                        wealth_matrix(time_period,financial_index,housing_status_index,years_left_on_mortgage_index)=&
                            net_wealth_used
                            
                        model_total_net_wealth_1(time_period)=model_total_net_wealth_1(time_period)+&
                            net_wealth_used*sum_distribution_used
                        
                        wealth_counter=wealth_counter+1    
                                                               
                    end if
                                            
                end do
                                                                
            end do
                            
        end do
                                    
        wealth_matrix_saved(time_period,:,:,:)=wealth_matrix(time_period,:,:,:)
        
        write(*,*) "begining wealth distribution" 
        
        do wealth_of_top_x_perc_index=1,(wealth_brackets)
        
            write(*,*) "compute for top ", 100*stopping_rule_wealth_dist(wealth_of_top_x_perc_index)
                
            wealth_matrix(time_period,:,:,:)=wealth_matrix_saved(time_period,:,:,:)
        
            pop_of_top_wealth_x_perc(wealth_of_top_x_perc_index)=0
            
            model_wealth_of_top_x_perc(wealth_of_top_x_perc_index)=0
                            
            distance_pop_of_top_wealth_x_perc(wealth_of_top_x_perc_index)=0
            
            if (wealth_of_top_x_perc_index==wealth_brackets) then
            
                loop_over_complete_distribution=1
            
            else
            
                loop_over_complete_distribution=0
            
            end if
            
            wealth_counter_2=1
                        
            do while (((loop_over_complete_distribution*wealth_counter_2)+(1-loop_over_complete_distribution)*&
                     (distance_pop_of_top_wealth_x_perc(wealth_of_top_x_perc_index)+10.d0**(-6)))&
                     <=(loop_over_complete_distribution*wealth_counter+&
                     (1-loop_over_complete_distribution)*stopping_rule_wealth_dist(wealth_of_top_x_perc_index)))
                                          
                wealth_counter_2=wealth_counter_2+1
                                
                max_wealth=maxval(wealth_matrix(time_period,:,:,:),mask=wealth_matrix(time_period,:,:,:)>&
                    -housing_price(time_period)*housing_size(housing_status_grid_size-1))
                                    
                max_wealth_index=maxloc(wealth_matrix(time_period,:,:,:),mask=wealth_matrix(time_period,:,:,:)>&
                    -housing_price(time_period)*housing_size(housing_status_grid_size-1))
                    
                sum_distribution_used=sum(distribution_stationary(max_wealth_index(3))%&
                    vector_transition_real(time_period,:,max_wealth_index(1),:,:,&
                    max_wealth_index(2)-2,:))
                                               
                if (((pop_of_top_wealth_x_perc(wealth_of_top_x_perc_index)+sum_distribution_used)/&
                    sum_of_distribution)>stopping_rule_wealth_dist(wealth_of_top_x_perc_index)) then
                                                                        
                    frac_of_household_mas_to_add=(sum_of_distribution*stopping_rule_wealth_dist(wealth_of_top_x_perc_index)-&
                        pop_of_top_wealth_x_perc(wealth_of_top_x_perc_index))/sum_distribution_used
                        
                    distance_pop_of_top_wealth_x_perc(wealth_of_top_x_perc_index)=&
                        stopping_rule_wealth_dist(wealth_of_top_x_perc_index)+0.000001
                        
                else
                
                    frac_of_household_mas_to_add=1
                    
                    distance_pop_of_top_wealth_x_perc(wealth_of_top_x_perc_index)=&
                        pop_of_top_wealth_x_perc(wealth_of_top_x_perc_index)/sum_of_distribution
                
                end if
                
                pop_of_top_wealth_x_perc(wealth_of_top_x_perc_index)=pop_of_top_wealth_x_perc(wealth_of_top_x_perc_index)+&
                    frac_of_household_mas_to_add*sum_distribution_used
                     
                model_wealth_of_top_x_perc(wealth_of_top_x_perc_index)=model_wealth_of_top_x_perc(wealth_of_top_x_perc_index)+&
                    frac_of_household_mas_to_add*max_wealth*sum_distribution_used
                    
                wealth_matrix(time_period,max_wealth_index(1),&
                    max_wealth_index(2)-2,max_wealth_index(3))=&
                    -housing_price(time_period)*housing_size(housing_status_grid_size-1)
                    
            end do
                                        
            if (solve_transition_dynamics==0) then
                
                write(*,*) "model_wealth_of_top_x_perc(",wealth_of_top_x_perc_index,")/model_net_wealth=",&
                    model_wealth_of_top_x_perc(wealth_of_top_x_perc_index)/max(model_total_net_wealth_1(time_period),10.d0**(-14))
                write(*,*) "stopping_rule_wealth_dist(",wealth_of_top_x_perc_index,")=",&
                    stopping_rule_wealth_dist(wealth_of_top_x_perc_index)
                                                        
            end if
                                      
        end do
        
        if (solve_transition_dynamics==0) then
        
            write(*,*) "file number=", file_number
            
        end if
        
    end subroutine
    
    subroutine stationary_equilibrium_income_distribution(time_period)
    
        use Global_Vars
        
        implicit none
        
        integer :: financial_index,loop_over_complete_distribution,income_counter_2,&
            time_period,income_of_top_x_perc_index,has_house,years_2
        real(8) :: frac_of_household_mas_to_add,avg_income_to_use_1,sum_distribution_used,&
            avg_income_to_use_2,labor_supply_used,distribution_mass_used,income_1,max_value,bequest_1
                
        sum_of_distribution=0
        
        do i=1,2
                
            sum_of_distribution=sum_of_distribution+&
                sum(distribution_stationary(i)%vector_transition_real(time_period,:,:,:,:,:,:))
            
        end do

        ! NOT SCALED HERE, AND THAT IS DELIBERATE. This routine has NO
        ! guarded resets: it rebuilds wealth_counter, wealth_matrix and
        ! model_total_net_wealth_1 from distribution_stationary every time
        ! it runs, so its numerators are ONE type. Scaling the denominator
        ! to pooled mass would take the top-one-per-cent cut at two per
        ! cent of the mass actually being walked and divide a one-type
        ! head count by a two-type mass.
        !
        ! The mass_passes replacement made this morning was right for the
        ! routines whose accumulators survive the loop and wrong here, and
        ! the audit caught it the same day. A denominator must match the
        ! population of its own numerator, not the population of the model.
        
        avg_income_to_use_1=is_counterfactual*average_labor_income_calibrated+&
            (1-is_counterfactual)*model_average_labour_income(time_period)
        
        income_counter=0
        
        do i=1,2
        
            income_matrix(i)%vector_real_income(:,:,:,:,:,:)=&
                -housing_price(time_period)*housing_size(housing_status_grid_size-1)
            
        end do
        
        do age_index=1,life_span
        
            if (age_index>life_span-retirement_span) then
            
                in_retirement=1
                
            else
            
                in_retirement=0
                
            end if
                            
            do years_left_on_mortgage_index=1,max_amortization_years
            
                if (years_left_on_mortgage_index==2) then
                
                    has_house=1
                    
                else
                
                    has_house=0
                    
                end if
                
                do unemployment_index=1,unemployment_grid_size
                
                    do employment_index=1,employment_grid_size
                    
                        if (inheritance_function_of_productivity==1) then
                        
                            bequest_1=employment_grid(age_index,employment_index)*inheritance_amount(age_index)+&
                            newborn_age_transfer(age_index)
                    
                        else
                        
                            call calculate_bequest_amount(age_index,bequest_1,employment_index)
                            
                        end if
                    
                        avg_income_to_use_2=is_counterfactual*average_labor_income_by_employment_calibrated(employment_index)+&
                            (1-is_counterfactual)*model_average_labour_income_by_employment(time_period,employment_index)
                                           
                        do voucher_index=0,(1-has_house)*include_vouchers
                
                            do financial_index=has_house*1+(1-has_house)*renter_floor_by_age(min(max(age_index,1),life_span)),financial_grid_size
                            
                                do housing_status_index=(1-has_house)*lowest_housing_grid_point+&
                                    has_house*index_of_smallest_house_hhld_can_buy,(housing_status_grid_size-1)
                                    
                                    distribution_mass_used=distribution_stationary(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    labor_supply_used=policy_function_labor_supply(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                                                    
                                    if (distribution_mass_used>0) then
                                    
                                        call calculate_income(unemployment_index,employment_index,income_1,&
                                            avg_income_to_use_1,avg_income_to_use_2,labor_supply_used,in_retirement)
                                                                                                                                                                   
                                        income_matrix(years_left_on_mortgage_index)%vector_real_income&
                                            (age_index,financial_index,unemployment_index,&
                                            employment_index,housing_status_index,voucher_index)=&
                                            income_1+max(financial_grid(financial_index),0.d0)*&
                                            risk_free_rate(time_period)+bequest_1
                                        
                                        income_counter=income_counter+1    
                                                                               
                                    end if
                                                            
                                end do
                                
                            end do
                            
                        end do
                        
                    end do
                                                                            
                end do
                
            end do
                            
        end do
        
        do i=1,2
                                    
            income_matrix_saved(i)%vector_real_income(:,:,:,:,:,:)=income_matrix(i)%vector_real_income(:,:,:,:,:,:)
            
        end do
        
        write(*,*) "begining income distribution" 
        
        do income_of_top_x_perc_index=1,3 ! (1-simulation_ended)*1+simulation_ended*(income_brackets)
        
            write(*,*) "compute for top ", 100*stopping_rule_income_dist(income_of_top_x_perc_index)
                
            do i=1,2
                
                income_matrix(i)%vector_real_income(:,:,:,:,:,:)=income_matrix_saved(i)%vector_real_income(:,:,:,:,:,:)
                
            end do
        
            pop_of_top_income_x_perc(income_of_top_x_perc_index)=0
            
            model_income_of_top_x_perc(income_of_top_x_perc_index)=0
                            
            distance_pop_of_top_income_x_perc(income_of_top_x_perc_index)=0
            
            if (income_of_top_x_perc_index==income_brackets) then
            
                loop_over_complete_distribution=1
            
            else
            
                loop_over_complete_distribution=0
            
            end if
            
            income_counter_2=1
                        
            do while (((loop_over_complete_distribution*income_counter_2)+(1-loop_over_complete_distribution)*&
                (distance_pop_of_top_income_x_perc(income_of_top_x_perc_index)+10.d0**(-6)))&
                <=(loop_over_complete_distribution*income_counter+&
                (1-loop_over_complete_distribution)*stopping_rule_income_dist(income_of_top_x_perc_index)))
                                          
                income_counter_2=income_counter_2+1
                
                max_value=-housing_price(time_period)*housing_size(housing_status_grid_size-1)
                years_2=1
                
                do i=1,2
                                
                    max_income=maxval(income_matrix(i)%vector_real_income(:,:,:,:,:,:),&
                        mask=income_matrix(i)%vector_real_income(:,:,:,:,:,:)>&
                        -housing_price(time_period)*housing_size(housing_status_grid_size-1))
                        
                    if (max_income>max_value) then
                    
                        max_value=max_income
                        years_2=i
                        
                    end if
                        
                end do
                                    
                max_income_index=maxloc(income_matrix(years_2)%vector_real_income(:,:,:,:,:,:),&
                    mask=income_matrix(years_2)%vector_real_income(:,:,:,:,:,:)>&
                    -housing_price(time_period)*housing_size(housing_status_grid_size-1))
                                                            
                sum_distribution_used=distribution_stationary(years_2)%&
                    vector_transition_real(time_period,max_income_index(1),max_income_index(2),&
                    max_income_index(3),max_income_index(4),max_income_index(5)-2,max_income_index(6)-1)
                                               
                if (((pop_of_top_income_x_perc(income_of_top_x_perc_index)+sum_distribution_used)/&
                    sum_of_distribution)>stopping_rule_income_dist(income_of_top_x_perc_index)) then
                                                                        
                    frac_of_household_mas_to_add=(sum_of_distribution*stopping_rule_income_dist(income_of_top_x_perc_index)-&
                        pop_of_top_income_x_perc(income_of_top_x_perc_index))/sum_distribution_used
                        
                    distance_pop_of_top_income_x_perc(income_of_top_x_perc_index)=&
                        stopping_rule_income_dist(income_of_top_x_perc_index)+0.000001
                        
                else
                
                    frac_of_household_mas_to_add=1
                    
                    distance_pop_of_top_income_x_perc(income_of_top_x_perc_index)=&
                        pop_of_top_income_x_perc(income_of_top_x_perc_index)/sum_of_distribution
                
                end if
                
                pop_of_top_income_x_perc(income_of_top_x_perc_index)=pop_of_top_income_x_perc(income_of_top_x_perc_index)+&
                    frac_of_household_mas_to_add*sum_distribution_used
                     
                model_income_of_top_x_perc(income_of_top_x_perc_index)=model_income_of_top_x_perc(income_of_top_x_perc_index)+&
                    frac_of_household_mas_to_add*max_income*sum_distribution_used
                    
                income_matrix(years_2)%vector_real_income(max_income_index(1),&
                    max_income_index(2),max_income_index(3),max_income_index(4),max_income_index(5)-2,max_income_index(6)-1)=&
                    -housing_price(time_period)*housing_size(housing_status_grid_size-1)
                    
            end do
                                        
            if (solve_transition_dynamics==0) then
                
                write(*,*) "model_income_of_top_x_perc(",income_of_top_x_perc_index,")/model_net_income=",&
                    model_income_of_top_x_perc(income_of_top_x_perc_index)/model_total_income(time_period)
                write(*,*) "stopping_rule_income_dist(",income_of_top_x_perc_index,")=",&
                    stopping_rule_income_dist(income_of_top_x_perc_index)
                                                        
            end if
                                      
        end do
        
        if (solve_transition_dynamics==0) then
        
            write(*,*) "file number=", file_number
            
        end if
        
    end subroutine
    
    ! THE LEVEL OF THE NEWBORN ENDOWMENT, refreshed wherever average labour
    ! income is. It is a share of average labour income rather than a number in
    ! model units so that it does not have to be re-set when anything else in
    ! the calibration moves the scale of the economy; newborn_endowment_scale=1
    ! hands a newborn one year of average earnings.
    !
    ! Only element 1 is ever nonzero. The rest of the array exists because every
    ! site that adds a transfer to resources is indexed by age, so keeping the
    ! shape costs nothing and means the endowment cannot leak into another age
    ! by an indexing slip.
    ! THE LOWEST GRID INDEX A RENTER MAY CHOOSE, by age. Called wherever the
    ! newborn transfer is set, so it is refreshed whenever average labour income
    ! is. Borrowing is barred in the final period of life: the household has no
    ! future income to repay from and would simply consume the loan.
    subroutine set_renter_floor(time_period)

        use global_vars

        implicit none

        integer, intent(in) :: time_period
        integer :: a_1, i_1

        renter_floor_by_age=negative_financial_grid_size

        ! The negative grid IS the borrowing range now, so every point of it is
        ! reachable and no search is needed -- except in the final period of
        ! life, where the household has no future income to repay from and
        ! borrowing is barred.
        !
        ! AND EXCEPT FOR THE PATIENT TYPE, when restrict_borrowing_to_impatient
        ! is on. The floor is a module array read by every state loop, every
        ! choice loop and every distribution loop, and the two types are solved
        ! in SEPARATE SEQUENTIAL PASSES with current_beta_type naming the pass,
        ! so setting it here at the top of a pass is all it takes to shrink both
        ! the states and the choices for that type alone. It is called from the
        ! pass loop for that reason; before this it was called once at the end
        ! of the last type's accumulation, which was enough when the floor did
        ! not depend on the type and is not now.
        !
        ! The guard is number_of_beta_types>1, not current_beta_type<
        ! number_of_beta_types: with a single type that type IS the whole
        ! economy, and barring it would silently turn borrowing off altogether.
        if (include_unsecured_borrowing==1) then

            if ((restrict_borrowing_to_impatient==1) .AND. &
                (number_of_beta_types>1) .AND. (current_beta_type==1)) then

                ! patient pass: the floor stays at the zero index

            else

                renter_floor_by_age(1:life_span-1)=1

            end if

        end if

    end subroutine

    subroutine set_newborn_age_transfer(time_period)

        use global_vars

        implicit none

        integer, intent(in) :: time_period

        newborn_age_transfer=0.d0

        if (uniform_newborn_endowment==1) then

            newborn_age_transfer(1)=newborn_endowment_scale*&
                (is_counterfactual*average_labor_income_calibrated+&
                (1-is_counterfactual)*model_average_labour_income(time_period))

        end if

    end subroutine

    subroutine calculate_bequest_amount(age_index_1,bequest_1,employment_index_1)
    
        use global_vars
        
        implicit none
        
        real(8), intent(out) :: bequest_1
        integer, intent(in) :: age_index_1,employment_index_1
        
        bequest_1=0
                                    
        do i=1,number_of_inheritance_ages
        
            if (age_index_1==inheritance_age_grid(i)) then
                                                                        
                ! THE NEWBORN ENDOWMENT IS FLAT, so it is added outside the
                ! productivity scaling rather than inside it: every newborn gets
                ! the same amount, which is the whole point of the instrument.
                bequest_1=newborn_age_transfer(age_index_1)+&
                    ((1-inheritance_function_of_productivity)+&
                    inheritance_function_of_productivity*&
                    employment_grid(age_index_1,employment_index_1))*&
                    inheritance_amount(i)
                                                            
            end if
            
        end do

    end subroutine
    
    subroutine stationary_equilibrium_income_bottom_distribution(time_period)
    
        use Global_Vars
        
        implicit none
        
        integer :: financial_index,loop_over_complete_distribution,income_counter_2,&
            time_period,income_of_top_x_perc_index,has_house,years_2
        real(8) :: frac_of_household_mas_to_add,avg_income_to_use_1,sum_distribution_used,&
            avg_income_to_use_2,labor_supply_used,distribution_mass_used,income_1,max_value,bequest_1
            
        write(*,*) "enter bottom income subroutine"
                
        sum_of_distribution=0
        
        do i=1,2
                
            sum_of_distribution=sum_of_distribution+&
                sum(distribution_stationary(i)%vector_transition_real(time_period,:,:,:,:,:,:))
            
        end do

        ! NOT SCALED HERE, AND THAT IS DELIBERATE. This routine has NO
        ! guarded resets: it rebuilds wealth_counter, wealth_matrix and
        ! model_total_net_wealth_1 from distribution_stationary every time
        ! it runs, so its numerators are ONE type. Scaling the denominator
        ! to pooled mass would take the top-one-per-cent cut at two per
        ! cent of the mass actually being walked and divide a one-type
        ! head count by a two-type mass.
        !
        ! The mass_passes replacement made this morning was right for the
        ! routines whose accumulators survive the loop and wrong here, and
        ! the audit caught it the same day. A denominator must match the
        ! population of its own numerator, not the population of the model.
        
        avg_income_to_use_1=is_counterfactual*average_labor_income_calibrated+&
            (1-is_counterfactual)*model_average_labour_income(time_period)
        
        income_counter=0
        
        do i=1,2
        
            income_matrix(i)%vector_real_income(:,:,:,:,:,:)=&
                -housing_price(time_period)*housing_size(housing_status_grid_size-1)
            
        end do

        write(*,*) "create income matrix"
        
        do age_index=1,life_span
        
            if (age_index>life_span-retirement_span) then
            
                in_retirement=1
                
            else
            
                in_retirement=0
                
            end if
                                
            do years_left_on_mortgage_index=1,max_amortization_years
            
                if (years_left_on_mortgage_index==2) then
                
                    has_house=1
                    
                else
                
                    has_house=0
                    
                end if
                
                do unemployment_index=1,unemployment_grid_size
                
                    do employment_index=1,employment_grid_size
                    
                        if (inheritance_function_of_productivity==1) then
                        
                            bequest_1=employment_grid(age_index,employment_index)*inheritance_amount(age_index)+&
                            newborn_age_transfer(age_index)
                            
                        else
                    
                            call calculate_bequest_amount(age_index,bequest_1,employment_index)
                    
                        end if
                    
                        avg_income_to_use_2=is_counterfactual*average_labor_income_by_employment_calibrated(employment_index)+&
                            (1-is_counterfactual)*model_average_labour_income_by_employment(time_period,employment_index)
                    
                        do voucher_index=0,(1-has_house)*include_vouchers
                                           
                            do financial_index=has_house*1+(1-has_house)*renter_floor_by_age(min(max(age_index,1),life_span)),financial_grid_size
                            
                                do housing_status_index=(1-has_house)*lowest_housing_grid_point+&
                                    has_house*index_of_smallest_house_hhld_can_buy,(housing_status_grid_size-1)
                                    
                                    distribution_mass_used=distribution_stationary(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    labor_supply_used=policy_function_labor_supply(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                                                    
                                    if (distribution_mass_used>0) then
                                    
                                        call calculate_income(unemployment_index,employment_index,income_1,&
                                            avg_income_to_use_1,avg_income_to_use_2,labor_supply_used,in_retirement)
                                                                                                                                                       
                                        income_matrix(years_left_on_mortgage_index)%vector_real_income&
                                            (age_index,financial_index,unemployment_index,&
                                            employment_index,housing_status_index,voucher_index)=&
                                            income_1+max(financial_grid(financial_index),0.d0)*&
                                            risk_free_rate(time_period)+bequest_1
                                        
                                        income_counter=income_counter+1    
                                                                               
                                    end if
                                    
                                end do
                                                            
                            end do
                            
                        end do
                        
                    end do
                                                                            
                end do
                
            end do
                            
        end do
        
        do i=1,2
                                    
            income_matrix_saved(i)%vector_real_income(:,:,:,:,:,:)=income_matrix(i)%vector_real_income(:,:,:,:,:,:)
            
        end do
        
        write(*,*) "begining bottom income distribution" 
        
        do income_of_top_x_perc_index=4,income_brackets ! (1-simulation_ended)*1+simulation_ended*(income_brackets)
        
            write(*,*) "compute for bottom ", 100*stopping_rule_income_dist(income_of_top_x_perc_index)
            
            do i=1,2
                
                income_matrix(i)%vector_real_income(:,:,:,:,:,:)=income_matrix_saved(i)%vector_real_income(:,:,:,:,:,:)
            
            end do
        
            pop_of_top_income_x_perc(income_of_top_x_perc_index)=0
            
            model_income_of_top_x_perc(income_of_top_x_perc_index)=0
                            
            distance_pop_of_top_income_x_perc(income_of_top_x_perc_index)=0
            
            if (income_of_top_x_perc_index==income_brackets) then
            
                loop_over_complete_distribution=0
            
            else
            
                loop_over_complete_distribution=0
            
            end if
            
            income_counter_2=1
                        
            do while (((loop_over_complete_distribution*income_counter_2)+(1-loop_over_complete_distribution)*&
                (distance_pop_of_top_income_x_perc(income_of_top_x_perc_index)+10.d0**(-6)))&
                <=(loop_over_complete_distribution*income_counter+&
                (1-loop_over_complete_distribution)*stopping_rule_income_dist(income_of_top_x_perc_index)))
                                          
                income_counter_2=income_counter_2+1
                
                max_value=1000000
                years_2=1
                
                do i=1,2
                                
                    max_income=minval(income_matrix(i)%vector_real_income(:,:,:,:,:,:),&
                        mask=income_matrix(i)%vector_real_income(:,:,:,:,:,:)>&
                        -housing_price(time_period)*housing_size(housing_status_grid_size-1))
                        
                    if (max_income<max_value) then
                    
                        max_value=max_income
                        years_2=i
                   
                    end if
                        
                end do
                                    
                max_income_index=minloc(income_matrix(years_2)%vector_real_income(:,:,:,:,:,:),&
                    mask=income_matrix(years_2)%vector_real_income(:,:,:,:,:,:)>&
                    -housing_price(time_period)*housing_size(housing_status_grid_size-1))
                                                                        
                sum_distribution_used=distribution_stationary(years_2)%&
                    vector_transition_real(time_period,max_income_index(1),max_income_index(2),&
                    max_income_index(3),max_income_index(4),max_income_index(5)-2,max_income_index(6)-1)
                                               
                if (((pop_of_top_income_x_perc(income_of_top_x_perc_index)+sum_distribution_used)/&
                    sum_of_distribution)>stopping_rule_income_dist(income_of_top_x_perc_index)) then
                                                                        
                    frac_of_household_mas_to_add=(sum_of_distribution*stopping_rule_income_dist(income_of_top_x_perc_index)-&
                        pop_of_top_income_x_perc(income_of_top_x_perc_index))/sum_distribution_used
                        
                    distance_pop_of_top_income_x_perc(income_of_top_x_perc_index)=&
                        stopping_rule_income_dist(income_of_top_x_perc_index)+0.000001
                        
                else
                
                    frac_of_household_mas_to_add=1
                    
                    distance_pop_of_top_income_x_perc(income_of_top_x_perc_index)=&
                        pop_of_top_income_x_perc(income_of_top_x_perc_index)/sum_of_distribution
                
                end if
                
                pop_of_top_income_x_perc(income_of_top_x_perc_index)=pop_of_top_income_x_perc(income_of_top_x_perc_index)+&
                    frac_of_household_mas_to_add*sum_distribution_used
                     
                model_income_of_top_x_perc(income_of_top_x_perc_index)=model_income_of_top_x_perc(income_of_top_x_perc_index)+&
                    frac_of_household_mas_to_add*max_income*sum_distribution_used
                    
                income_matrix(years_2)%vector_real_income(max_income_index(1),&
                    max_income_index(2),max_income_index(3),max_income_index(4),max_income_index(5)-2,max_income_index(6)-1)=&
                    -housing_price(time_period)*housing_size(housing_status_grid_size-1)
                    
            end do
                                        
            if (solve_transition_dynamics==0) then
                
                write(*,*) "model_income_of_top_x_perc(",income_of_top_x_perc_index,")/model_net_income=",&
                    model_income_of_top_x_perc(income_of_top_x_perc_index)/model_total_income(time_period)
                write(*,*) "stopping_rule_income_dist(",income_of_top_x_perc_index,")=",&
                    stopping_rule_income_dist(income_of_top_x_perc_index)
                                                        
            end if
                                      
        end do
        
        if (solve_transition_dynamics==0) then
        
            write(*,*) "file number=", file_number
            
        end if
        
    end subroutine
    
    subroutine stationary_equilibrium_wealth_distribution_of_old(time_period)
    
        use Global_Vars
        
        implicit none
        
        integer :: financial_index,wealth_counter_2,time_period,wealth_of_top_x_perc_index,has_house
        real(8) :: frac_of_household_mas_to_add,sum_distribution_used,sum_of_distribution_of_old

        ! STATIC STORAGE, BECAUSE THESE ACCUMULATE ACROSS THE TWO PASSES.
        !
        ! Each of these is reset only when accumulating_beta_types is zero,
        ! which is the first pass, and added to on every pass. That is the
        ! right shape for a counter that has to hold both discount-factor
        ! types -- but it is only correct if the value survives from one
        ! call to the next, and a local without save does not. On the
        ! second pass the routine is entered fresh, the reset is skipped,
        ! and the accumulation lands on whatever the stack holds.
        !
        ! It has been working by accident: the calls come from the same
        ! site in the same order, so the frame is usually reused and the
        ! slot usually still holds the first pass's value. That is not a
        ! guarantee, it is a property of this build. save makes it one.
        !
        ! These stay LOCAL rather than moving to module scope on purpose.
        ! total_homeless_1 is the name of two different locals in two
        ! different routines; merging them would pool two counts of the
        ! same population into one divisor.
        ! ONE TYPE, BECAUSE wealth_matrix IS ONE TYPE. THIS IS A PAIRING RULE.
        !
        ! The reset here was guarded to the first pass, so the divisor
        ! accumulated BOTH discount-factor types, while wealth_matrix twelve
        ! lines below is reset UNGUARDED and so is rebuilt from the one type just
        ! solved. The loop at 11186 walks wealth_matrix upward accumulating mass
        ! and divides by this, so on the second pass the share it can reach tops
        ! out at ONE HALF.
        !
        ! stopping_rule_wealth_dist_of_old is (0.25, 0.5, 0.75). The third target
        ! is therefore UNREACHABLE on the second pass: the loop consumes every
        ! cell in the array, `minloc` over an all-false mask returns zero, and
        ! `min_wealth_index(2)-2` indexes at MINUS TWO. A hang followed by an
        ! out-of-bounds write.
        !
        ! Caught on a live process, not by reading. gdb put the stack in
        ! _gfortran_mminloc0_4_r8 inside this routine, and the locals read
        ! sum_of_distribution_of_old=15.412 with the accumulated share at 0.186
        ! and still climbing toward 0.25 after fifty minutes -- twice the walk it
        ! should have been, on the first of three targets.
        !
        ! It is mine. The `save` added earlier tonight is what made the
        ! cross-pass accumulation actually happen; before it the local was
        ! undefined on entry to the second pass, which is undefined behaviour
        ! that happened to work when the slot came up zero. The `save` is dropped
        ! with the guard because there is now nothing to carry between calls.
        !
        ! THE RULE, which is the third time tonight the same mistake has been
        ! made: a divisor must cover the same population as the object it
        ! normalises. Check what it is paired with, not whether the accumulation
        ! pattern looks like its neighbours'.
        sum_of_distribution_of_old=0
        
        do i=1,2
                
            sum_of_distribution_of_old=sum_of_distribution_of_old+&
                sum(distribution_stationary(i)%vector_transition_real&
                (time_period,life_span-retirement_span+1:life_span,:,:,:,:,:))
            
        end do
        
        wealth_counter=0
        
        wealth_matrix(time_period,:,:,:)=-housing_price(time_period)*housing_size(housing_status_grid_size-1)
                
        do years_left_on_mortgage_index=1,max_amortization_years
        
            if (years_left_on_mortgage_index==2) then
            
                has_house=1
                
            else
            
                has_house=0
                
            end if
        
            ! renter_array_floor, NOT renter_floor_by_age. age_index is not set
            ! in this routine, so keying the bound on it read whatever the last
            ! routine to touch it happened to leave behind. With borrowing on
            ! that resolves to the zero index about as often as not, and then the
            ! three debt points never enter wealth_matrix while their mass stays
            ! in sum_of_distribution_of_old below. The walk can never reach its
            ! stopping rule, consumes every cell instead, and minloc over the
            ! all-false mask returns (0,0,0) -- which a bounds-checked run
            ! aborted on at 11791, reading distribution_stationary(0). The array
            ! floor is exactly the set of indices a renter can occupy and it does
            ! not depend on ambient state.
            do financial_index=has_house*1+(1-has_house)*renter_array_floor,financial_grid_size
            
                do housing_status_index=(1-has_house)*lowest_housing_grid_point+&
                    has_house*index_of_smallest_house_hhld_can_buy,(housing_status_grid_size-1)
                                                    
                    if (sum(distribution_stationary(years_left_on_mortgage_index)%&
                        vector_transition_real(time_period,life_span-retirement_span+1:life_span,&
                        financial_index,:,:,housing_status_index,:))>0) then
                        
                        ! Gated on has_house, the fourth site of the same defect:
                        ! the middle term is an OWNER's mortgage read as a
                        ! fraction of the dwelling's value, and the last is
                        ! truncated only because an owner's negative position is
                        ! already that mortgage. A renter's net worth is their
                        ! financial position, raw.
                        wealth_matrix(time_period,financial_index,housing_status_index,years_left_on_mortgage_index)=&
                            max(min(years_left_on_mortgage_index-1,1),0)*&
                            housing_price(time_period)*housing_size(housing_status_index)+&
                            has_house*min(financial_grid(financial_index),0.d0)*&
                            housing_price(time_period)*housing_size(housing_status_index)+&
                            has_house*max(financial_grid(financial_index),0.d0)+&
                            (1-has_house)*financial_grid(financial_index)
                                                    
                        wealth_counter=wealth_counter+1    
                                                               
                    end if
                                            
                end do
                                                                
            end do
                            
        end do
                                                
        wealth_matrix_saved(time_period,:,:,:)=wealth_matrix(time_period,:,:,:)
        
        write(*,*) "begining wealth distribution for old" 
        
        do wealth_of_top_x_perc_index=1,3
                
            wealth_matrix(time_period,:,:,:)=wealth_matrix_saved(time_period,:,:,:)
        
            pop_of_top_wealth_x_perc(wealth_of_top_x_perc_index)=0
            
            model_wealth_of_x_perc_of_old(wealth_of_top_x_perc_index)=0
                            
            distance_pop_of_top_wealth_x_perc(wealth_of_top_x_perc_index)=0
            
            wealth_counter_2=1
                        
            do while ((distance_pop_of_top_wealth_x_perc(wealth_of_top_x_perc_index)+10.d0**(-6))<=&
                stopping_rule_wealth_dist_of_old(wealth_of_top_x_perc_index))
                                          
                wealth_counter_2=wealth_counter_2+1
                                
                min_wealth=minval(wealth_matrix(time_period,:,:,:),mask=wealth_matrix(time_period,:,:,:)>&
                    -housing_price(time_period)*housing_size(housing_status_grid_size-1))
                                    
                min_wealth_index=minloc(wealth_matrix(time_period,:,:,:),mask=wealth_matrix(time_period,:,:,:)>&
                    -housing_price(time_period)*housing_size(housing_status_grid_size-1))
                                                                                
                sum_distribution_used=sum(distribution_stationary(min_wealth_index(3))%&
                    vector_transition_real(time_period,life_span-retirement_span+1:life_span,min_wealth_index(1),:,:,&
                    min_wealth_index(2)-2,:))
                                               
                if (((pop_of_top_wealth_x_perc(wealth_of_top_x_perc_index)+sum_distribution_used)/&
                    sum_of_distribution_of_old)>stopping_rule_wealth_dist_of_old(wealth_of_top_x_perc_index)) then
                                                                        
                    frac_of_household_mas_to_add=(sum_of_distribution_of_old*&
                        stopping_rule_wealth_dist_of_old(wealth_of_top_x_perc_index)-&
                        pop_of_top_wealth_x_perc(wealth_of_top_x_perc_index))/sum_distribution_used
                        
                    distance_pop_of_top_wealth_x_perc(wealth_of_top_x_perc_index)=&
                        stopping_rule_wealth_dist_of_old(wealth_of_top_x_perc_index)+0.000001
                        
                else
                
                    frac_of_household_mas_to_add=1
                    
                    distance_pop_of_top_wealth_x_perc(wealth_of_top_x_perc_index)=&
                        pop_of_top_wealth_x_perc(wealth_of_top_x_perc_index)/sum_of_distribution_of_old
                
                end if
                
                pop_of_top_wealth_x_perc(wealth_of_top_x_perc_index)=&
                    pop_of_top_wealth_x_perc(wealth_of_top_x_perc_index)+&
                    frac_of_household_mas_to_add*sum_distribution_used
                     
                model_wealth_of_x_perc_of_old(wealth_of_top_x_perc_index)=min_wealth
                    
                wealth_matrix(time_period,min_wealth_index(1),&
                    min_wealth_index(2)-2,min_wealth_index(3))=&
                    -housing_price(time_period)*housing_size(housing_status_grid_size-1)
                    
            end do
                                        
            if (solve_transition_dynamics==0) then
                
!                write(*,*) "model_wealth_of_x_perc_of_old(",wealth_of_top_x_perc_index,")=",&
!                    model_wealth_of_x_perc_of_old(wealth_of_top_x_perc_index)
!                write(*,*) "stopping_rule_wealth_dist_of_old(",wealth_of_top_x_perc_index,")=",&
!                    stopping_rule_wealth_dist_of_old(wealth_of_top_x_perc_index)
                                                        
            end if
                                      
        end do
        
        if (solve_transition_dynamics==0) then
        
            write(*,*) "file number=", file_number
            
        end if
        
    end subroutine
        
    subroutine calculate_gini_coefficient(time_period)
    
        use Global_Vars
        
        implicit none
        
        integer :: financial_index,time_period,has_house
        real(8) :: scalar_1=10,sum_distribution_used
        
        loop_count_gini=0
        
        wealth_matrix_gini(time_period,:,:,:)=-scalar_1*housing_price(time_period)*housing_size(housing_status_grid_size-1)
        
        do years_left_on_mortgage_index=1,max_amortization_years
        
            if (years_left_on_mortgage_index==2) then
            
                has_house=1
                
            else
            
                has_house=0
                
            end if
        
            ! renter_array_floor, not renter_floor_by_age: age_index is not set
            ! in this routine either, and this is the same wealth_matrix walk
            ! that aborted at 11791 with minloc over an all-false mask, when the
            ! debt points were left out of the numerator while their mass stayed
            ! in the divisor.
            do financial_index=has_house*1+(1-has_house)*renter_array_floor,financial_grid_size
            
                do housing_status_index=(1-has_house)*lowest_housing_grid_point+&
                    has_house*index_of_smallest_house_hhld_can_buy,(housing_status_grid_size-1)
                                        
                    if (sum(distribution_stationary(years_left_on_mortgage_index)%&
                        vector_transition_real(time_period,:,financial_index,:,:,housing_status_index,:))>0) then
                        
                        wealth_matrix_gini(time_period,financial_index,housing_status_index,years_left_on_mortgage_index)=&
                            housing_price(time_period)*housing_size(housing_status_index)*&
                            (max(min(years_left_on_mortgage_index-1,1),0)+min(financial_grid(financial_index),0.d0))+&
                            max(financial_grid(financial_index),0.d0)                            
                           
                        loop_count_gini=loop_count_gini+1
                                                               
                    end if
                                            
                end do
                                                                
            end do
                            
        end do
                                            
        gini_coefficient_numerator(time_period)=0
        gini_coefficient_cumulative_wealth(time_period,:)=0
            
        counter=1
                        
        do while (counter<=loop_count_gini)
            
            min_wealth_gini=minval(wealth_matrix_gini(time_period,:,:,:),mask=wealth_matrix_gini(time_period,:,:,:)>&
                -scalar_1*housing_price(time_period)*housing_size(housing_status_grid_size-1))
                
            min_wealth_index_gini=minloc(wealth_matrix_gini(time_period,:,:,:),mask=wealth_matrix_gini(time_period,:,:,:)>&
                -scalar_1*housing_price(time_period)*housing_size(housing_status_grid_size-1))
                
            sum_distribution_used=sum(distribution_stationary(min_wealth_index_gini(3))%&
                vector_transition_real(time_period,:,min_wealth_index_gini(1),:,:,min_wealth_index_gini(2)-2,:))
                                           
            gini_coefficient_cumulative_wealth(time_period,2)=gini_coefficient_cumulative_wealth(time_period,1)+&
                sum_distribution_used*min_wealth_gini
                                                
            wealth_matrix_gini(time_period,min_wealth_index_gini(1),min_wealth_index_gini(2)-2,&
                min_wealth_index_gini(3))=-2*scalar_1*housing_price(time_period)*housing_size(housing_status_grid_size-1)
                                        
            gini_coefficient_numerator(time_period)=gini_coefficient_numerator(time_period)+&
                (sum_distribution_used/sum_of_distribution)*(gini_coefficient_cumulative_wealth(time_period,2)+&
                gini_coefficient_cumulative_wealth(time_period,1))
                
            gini_coefficient_cumulative_wealth(time_period,1)=gini_coefficient_cumulative_wealth(time_period,2)
            
            counter=counter+1
                             
        end do
        
        gini_coefficient(time_period)=1-(gini_coefficient_numerator(time_period)/&
            gini_coefficient_cumulative_wealth(time_period,2))
        
        write(*,*) "gini_coefficient(", time_period,")=", gini_coefficient(time_period)
        
    end subroutine
    
    subroutine calculate_housing_voucher(housing_voucher_1,income_1,rent_spending_1,&
        homeowner_spending_1,is_current_homeowner_1,is_choosing_to_rent_1,time_period)
    
        use Global_Vars
     
        implicit none
        
        real(8), intent(in) :: income_1,rent_spending_1,homeowner_spending_1
        real(8), intent(inout) :: housing_voucher_1
        real(8) :: voucher_required
        integer, intent(in) :: time_period,is_current_homeowner_1,is_choosing_to_rent_1
                
        ! THE NOTE'S RULE, NOT A PAYMENT STANDARD.
        !
        ! This used to compute the subsidy against a standard fixed at the
        ! AVERAGE rental unit, max_rent_relative_to_ave times the average rent
        ! times the average size, which is how HUD actually works and is not what
        ! the written model says. Equation (17) is
        !
        !     Vch = 1{eta=1} 1{h' /= h_1} max(0, p_r h' - kappa_r y^g)
        !
        ! so the subsidy is computed on the household's OWN chosen dwelling. The
        ! difference is behavioural rather than cosmetic: under this rule a
        ! household can raise its voucher by renting a bigger unit, and under the
        ! payment standard it cannot.
        !
        ! Homelessness needs no indicator here. It pays no rent, so
        ! rent_spending_1 is zero and the subsidy is zero.
        voucher_required=max(is_choosing_to_rent_1*rent_spending_1+&
            is_current_homeowner_1*homeowner_spending_1-&
            max_fraction_of_income_spent_on_housing*income_1,0.d0)
                                    
        housing_voucher_1=max(min(voucher_required,&
            is_choosing_to_rent_1*rent_spending_1+&
            is_current_homeowner_1*homeowner_spending_1),0.d0)
                    
    end subroutine
    
    subroutine calculate_housing_voucher_2(housing_voucher_1,future_addiction_index_1,income_1,rent_spending_1,time_period)
    
        use Global_Vars
     
        implicit none
        
        real(8), intent(in) :: income_1,rent_spending_1
        real(8), intent(inout) :: housing_voucher_1
        integer, intent(in) :: time_period,future_addiction_index_1
        
        housing_voucher_1=0
        
        if (((unemployment_index>threshold_addiction_index) .OR. &
            ((future_addiction_index_1>=1) .AND. (unemployment_index<=threshold_addiction_index))) .AND. &
            (voucher_conditional_on_clean==1)) then
            
            if (voucher_conditional_on_clean_just_addicts==1) then
            
                write(*,*) "wrong"
                
            end if
            
            housing_voucher_1=0
            
        elseif ((unemployment_index>threshold_addiction_index) .AND. &
            (voucher_conditional_on_clean_just_addicts==1)) then
            
            if (voucher_conditional_on_clean==1) then
            
                write(*,*) "wrong"
                
            end if
                        
            housing_voucher_1=0
            
        else
                        
            housing_voucher_1=min(max(model_average_rent(time_period)*model_average_rental_unit_size(time_period)-&
                rent_to_income_ratio_vouchers*income_1,0.d0),max(rent_spending_1-rent_to_income_ratio_vouchers*income_1,0.d0))
                
        end if
                                         
    end subroutine
        
    subroutine govt_revenues_calc(time_period)
    
        use Global_Vars
        
        implicit none
        
        integer :: financial_index,time_period,has_house,amortization_used,time_period_used,housing_status_index_used,&
            is_current_owner,choose_to_rent,low_quality_market,is_addicted,addiction_choice_2,choose_addiction_1,age_group_1
        real(8) :: is_renter_to_owner,lived_in_size_used,distribution_mass_used,MID_used,income_tax_used,&
            consumption_used,labor_supply_used,avg_income_to_use_1,avg_income_to_use_2,&
            income_1,food_stamps_1,assets_1,assets_2,total_consumption_used,avg_net_wealth_to_use_1,housing_voucher_1,&
            total_homeless_1,after_tax_income_1,after_tax_income_2,frac_spent_on_addiction_used,housing_voucher_2,&
            total_addited_1,income_2,frac_getting_vouchers,homeowner_spending,total_addicted_and_homeless_1,bequest_1,&
            addiction_consumption_1

        ! STATIC STORAGE, BECAUSE THESE ACCUMULATE ACROSS THE TWO PASSES.
        !
        ! Each of these is reset only when accumulating_beta_types is zero,
        ! which is the first pass, and added to on every pass. That is the
        ! right shape for a counter that has to hold both discount-factor
        ! types -- but it is only correct if the value survives from one
        ! call to the next, and a local without save does not. On the
        ! second pass the routine is entered fresh, the reset is skipped,
        ! and the accumulation lands on whatever the stack holds.
        !
        ! It has been working by accident: the calls come from the same
        ! site in the same order, so the frame is usually reused and the
        ! slot usually still holds the first pass's value. That is not a
        ! guarantee, it is a property of this build. save makes it one.
        !
        ! These stay LOCAL rather than moving to module scope on purpose.
        ! total_homeless_1 is the name of two different locals in two
        ! different routines; merging them would pool two counts of the
        ! same population into one divisor.
        save :: total_addited_1, frac_getting_vouchers, total_homeless_1, total_addicted_and_homeless_1
            
        avg_income_to_use_1=is_counterfactual*average_labor_income_calibrated+&
            (1-is_counterfactual)*model_average_labour_income(time_period)
            
        avg_net_wealth_to_use_1=is_counterfactual*average_net_wealth_calibrated+&
            (1-is_counterfactual)*model_average_net_wealth(time_period)
                                    
        time_period_used=time_period-solve_transition_dynamics
        
        if (accumulating_beta_types==0) govt_revenues_from_labour_income(time_period)=0
        if (accumulating_beta_types==0) govt_spending_on_mortgage_interest_deductions(time_period)=0
        if (accumulating_beta_types==0) fraction_using_MID(time_period)=0
        if (accumulating_beta_types==0) govt_revenues_from_consumption(time_period)=0
        if (accumulating_beta_types==0) govt_revenues_from_investment_income(time_period)=0
        if (accumulating_beta_types==0) govt_revenues_from_property_tax(time_period)=0
        if (accumulating_beta_types==0) govt_lump_sum_transfers(time_period)=0
        if (accumulating_beta_types==0) govt_spending_on_ss(time_period)=0
        if (accumulating_beta_types==0) govt_ss_wasted(time_period)=0
        if (accumulating_beta_types==0) govt_spending_on_ui(time_period)=0
        if (accumulating_beta_types==0) govt_spending_on_di(time_period)=0
        if (accumulating_beta_types==0) govt_spending_on_homeless(time_period)=0
        if (accumulating_beta_types==0) govt_spending_on_addicts(time_period)=0
        if (accumulating_beta_types==0) govt_spending_on_food_stamps(time_period)=0
        if (accumulating_beta_types==0) model_fraction_spent_on_addiction(time_period)=0
        if (accumulating_beta_types==0) model_fraction_spent_on_addiction_experimenters(time_period)=0
        if (accumulating_beta_types==0) model_addicted_total_addiction_spending_to_total_income(time_period)=0
