        if (accumulating_beta_types==0) model_drugs_used_by_experimenters_on_average(time_period)=0
        if (accumulating_beta_types==0) model_mass_addicts(time_period)=0
        if (accumulating_beta_types==0) model_drugs_used_by_addicts_on_average(time_period)=0
        if (accumulating_beta_types==0) model_mass_experimenters(time_period)=0
        if (accumulating_beta_types==0) model_mass_total_users(time_period)=0
        if (accumulating_beta_types==0) employment_mass(time_period,:)=0
        if (accumulating_beta_types==0) govt_spending_on_housing_vouchers(time_period)=0
        if (accumulating_beta_types==0) govt_spending_on_housing_vouchers_2(time_period)=0
        if (accumulating_beta_types==0) model_eligibles_getting_voucher(time_period)=0
        if (accumulating_beta_types==0) model_eligibles_getting_voucher_relative_to_pop(time_period)=0
        if (accumulating_beta_types==0) model_addicts_getting_voucher(time_period)=0
        if (accumulating_beta_types==0) model_homeowners_experimenting(time_period)=0
        if (accumulating_beta_types==0) model_experimenters_getting_voucher(time_period)=0
        if (accumulating_beta_types==0) model_drug_users_getting_voucher(time_period)=0
        if (accumulating_beta_types==0) model_avg_income_experimenters(time_period)=0
        if (accumulating_beta_types==0) model_avg_income_drug_users(time_period)=0
        if (accumulating_beta_types==0) val_user_band(time_period,:)=0
        if (accumulating_beta_types==0) val_user_sud_band(time_period,:)=0
        if (accumulating_beta_types==0) val_user_inc_band(time_period,:)=0
        if (accumulating_beta_types==0) val_user_age_num(time_period)=0
        if (accumulating_beta_types==0) val_user_mass_age(time_period)=0
        if (accumulating_beta_types==0) val_user_income_working(time_period)=0
        if (accumulating_beta_types==0) val_user_mass_working(time_period)=0
        if (accumulating_beta_types==0) val_buy_mass(time_period)=0
        if (accumulating_beta_types==0) val_buy_C(time_period)=0
        if (accumulating_beta_types==0) val_buy_income(time_period)=0
        if (accumulating_beta_types==0) val_nobuy_mass(time_period)=0
        if (accumulating_beta_types==0) val_nobuy_C(time_period)=0
        if (accumulating_beta_types==0) val_nobuy_income(time_period)=0
        if (accumulating_beta_types==0) model_avg_assets_experimenters(time_period)=0
        if (accumulating_beta_types==0) model_eligibles(time_period)=0
        if (accumulating_beta_types==0) model_fraction_recieving_food_stamps(time_period)=0
        if (accumulating_beta_types==0) model_fraction_homeless_recieving_food_stamps(time_period)=0
        if (accumulating_beta_types==0) model_food_stamps_share_to_homeless(time_period)=0
        ! OWNED BY stationary_equilibrium_statistics, WHICH RUNS FIRST. Reset,
        ! accumulation and division disabled here.
        !
        ! model_fraction_homeless was reset, accumulated AND divided in two chain
        ! routines. Both resets are guarded to the first pass, so on the second
        ! pass this routine accumulated a MASS on top of the RATE the earlier one
        ! had already produced, then divided again: the value the h_1 bisection
        ! read was a 1:3 mixture over-weighting the impatient type, not the 1:1
        ! mixture the design intends. h_1 is a TARGETED moment and
        ! size_homelessness is driven by it.
        !
        ! The two routines divide by different denominators -- lowest
        ! productivities against sum_of_distribution -- but the first is
        ! accumulated for every household with no condition, so despite its name
        ! it is the same total mass. Keeping one owner is enough.
        ! if (accumulating_beta_types==0) model_fraction_homeless(time_period)=0
        if (accumulating_beta_types==0) model_fraction_recieving_housing_vouchers(time_period)=0
        if (accumulating_beta_types==0) net_govt_revenues(time_period)=0
        
        if (accumulating_beta_types==0) model_fraction_addicted_homeless_no_vouchers(time_period)=0
        if (accumulating_beta_types==0) frac_getting_vouchers=0
        
        ! ONE OWNER PER VARIABLE. Reset and accumulation disabled here.
        !
        ! Every reset in the chain is guarded to the FIRST pass, which is safe only
        ! if exactly one routine owns the variable. Where two or more each reset and
        ! each accumulate, the guard that stops pass two resetting also lets each
        ! routine start from whatever the previous one left, so the second pass adds
        ! another copy of the second type on top of a finished total. Four owners of
        ! mass_by_employment made it 5*M where the pooled mass is 2*M, so every
        ! welfare-by-employment average was halved and homeownership_by_employment
        ! came out at 0.4 times truth.
        !
        ! It is the same quantity in every owner, so the FIRST in call order keeps
        ! it and the rest read it. The order is the same in the driver and in
        ! long_run_counter_factual, so the value is always built before it is read.
        !
        ! THAT RULE APPLIES TO MODULE VARIABLES ONLY, AND total_homeless_1 IS NOT
        ! ONE. It is declared a local of this routine and, separately, a local of
        ! stationary_equilibrium_statistics: two variables that happen to share a
        ! name. So there is no earlier owner for this one to read. Disabling the
        ! reset here did not hand ownership to another routine, it left this
        ! routine's own local undefined on entry, and the eight homeless averages
        ! normalised by it below were divided by whatever the stack held.
        !
        ! It printed plainly and was missed for a day: "homeless by choice, share
        ! of the homeless" came out at 1.6552 in point_03ac59f09e, and a share of
        ! the homeless cannot exceed one. Both by-choice diagnostics now have an
        ! invariant so the next one is caught on the run that produces it.
        !
        ! The other nine disabled resets were checked against the declaration
        ! block at the same time. mass_of_owners, mass_by_employment,
        ! model_fraction_homeless, mass_renters_by_age, mass_by_age and
        ! mass_by_employment_and_age are all module scope, so the one-owner rule
        ! is sound for them and they are left alone.
        if (accumulating_beta_types==0) total_homeless_1=0
        if (accumulating_beta_types==0) total_addicted_and_homeless_1=0
        if (accumulating_beta_types==0) model_fraction_homeless_by_choice(time_period)=0
        if (accumulating_beta_types==0) val_homeless_afford_on_income(time_period)=0
        if (accumulating_beta_types==0) model_addicted_and_homeless_by_choice(time_period)=0
        
        if (accumulating_beta_types==0) model_avg_homeless_income(time_period)=0
        if (accumulating_beta_types==0) model_avg_homeless_after_tax_income(time_period)=0
        if (accumulating_beta_types==0) model_avg_homeless_tax_to_income(time_period)=0
        if (accumulating_beta_types==0) model_avg_homeless_assets(time_period)=0
        if (accumulating_beta_types==0) model_average_income_of_homeless_addicted(time_period)=0
        if (accumulating_beta_types==0) model_average_assets_addicted_and_homeless(time_period)=0
        
        if (accumulating_beta_types==0) model_average_assets_homeless_by_addiction(time_period,:)=0
        if (accumulating_beta_types==0) model_average_income_homeless_by_addiction(time_period,:)=0
        if (accumulating_beta_types==0) model_average_income_addicted(time_period)=0
        if (accumulating_beta_types==0) model_average_assets_addicted(time_period)=0
        if (accumulating_beta_types==0) model_average_assets_drug_users(time_period)=0
        if (accumulating_beta_types==0) model_mass_by_homeless_and_addiction(time_period,:)=0
        
        if (accumulating_beta_types==0) model_age_by_addiction(time_period,:)=0
        if (accumulating_beta_types==0) model_mass_age_by_addiction(time_period,:)=0
        
        if (accumulating_beta_types==0) model_addiction_rate_by_age(time_period,:)=0
        if (accumulating_beta_types==0) model_experimentation_choice_by_age(time_period,:)=0
        if (accumulating_beta_types==0) model_drug_use_by_age_group(time_period,:)=0
        if (accumulating_beta_types==0) model_drug_use_percent_by_age_group(time_period,:)=0
        
        if (accumulating_beta_types==0) addiction_rate_by_age(time_period,:)=0
        if (accumulating_beta_types==0) homeless_and_addiction_rate_by_age(time_period,:)=0
        if (accumulating_beta_types==0) mass_by_age(time_period,:)=0
        
        if (accumulating_beta_types==0) model_fraction_choose_addiction_when_unemployed(time_period)=0
        if (accumulating_beta_types==0) model_choose_addiction_when_income_is_low(time_period)=0
        if (accumulating_beta_types==0) model_fraction_choose_addiction_when_homeless(time_period)=0
        if (accumulating_beta_types==0) model_choose_addiction_when_retired(time_period)=0
        if (accumulating_beta_types==0) model_fraction_choose_addiction(time_period)=0
        if (accumulating_beta_types==0) model_mass_choose_addiction(time_period)=0
        
        if (accumulating_beta_types==0) model_unemployment_by_employment(time_period,:)=0
        if (accumulating_beta_types==0) mass_by_employment_1(time_period,:)=0
                
        do age_index=1,life_span
        
            if (age_index>(life_span-retirement_span)) then
            
                in_retirement=1
                
            else
            
                in_retirement=0
                
            end if
                                                
            do years_left_on_mortgage_index=1,max_amortization_years
                            
                if (years_left_on_mortgage_index>1) then
                                
                    has_house=1
                    
                else
                
                    has_house=0
                    
                end if
                                
                do unemployment_index=1,unemployment_grid_size
                                    
                    do employment_index=1,employment_grid_size
                    
                        if (inheritance_function_of_productivity==1) then
                        
                            bequest_1=employment_grid(age_index,employment_index)*inheritance_amount(age_index)+&
                            newborn_age_transfer(age_index)
                    
                        else
                            
                            call calculate_bequest_amount(age_index,bequest_1,employment_index)
                            
                        end if
                    
                        do voucher_index=0,(1-has_house)*include_vouchers

                            avg_income_to_use_2=is_counterfactual*average_labor_income_by_employment_calibrated(employment_index)+&
                                (1-is_counterfactual)*model_average_labour_income_by_employment(time_period,employment_index)
                                                                
                            do financial_index=has_house*1+(1-has_house)*renter_floor_by_age(min(max(age_index,1),life_span)),financial_grid_size
                                               
                                do housing_status_index=(1-has_house)*lowest_housing_grid_point+&
                                    has_house*index_of_smallest_house_hhld_can_buy,housing_status_grid_size-1
                                                                                                    
                                    lived_in_size_used=policy_function_space_lived_in_size(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    labor_supply_used=policy_function_labor_supply(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    housing_status_index_used=policy_function_housing_status_index(years_left_on_mortgage_index)%&
                                        vector_transition_integer(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                    
                                    amortization_used=&
                                        policy_function_years_of_amortization_index(years_left_on_mortgage_index)%&
                                        vector_transition_integer(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                                                    
                                    MID_used=policy_function_mortgage_interest_deductions(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    income_tax_used=policy_function_wage_income_tax_paid(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                                                            
                                    consumption_used=&
                                        policy_function_consumption(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    total_consumption_used=&
                                        policy_function_total_consumption(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    frac_spent_on_addiction_used=&
                                        policy_function_frac_spent_on_addiction(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    addiction_choice_2=&
                                        policy_function_addiction(years_left_on_mortgage_index)%&
                                        vector_transition_integer(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    addiction_consumption_1=0
                                        
                                    if (addiction_choice_2>0) then
                                        
                                        addiction_consumption_1=&
                                            max(total_consumption_used-consumption_used,0.d0)
                                            
                                    end if
                                                                                                    
                                    distribution_mass_used=distribution_stationary(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period_used,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)

                                    ! THE DENOMINATOR OF THE DISORDER RATE BY PRODUCTIVITY, and it has
                                    ! to be counted here, where every household passes, rather than
                                    ! inside the block that only households with the disorder reach.
                                    total_mass_by_employment(time_period,employment_index)=&
                                        total_mass_by_employment(time_period,employment_index)+distribution_mass_used

                                    ! THE HOMELESSNESS RATE BY PRODUCTIVITY, and it is counted HERE,
                                    ! in the same pass as the denominator above and after
                                    ! housing_status_index_used is set, rather than beside the other
                                    ! homelessness statistics further up. A numerator and a
                                    ! denominator accumulated in different loop nests is how the use
                                    ! rate by age came to read exactly 200 per cent.
                                    !
                                    ! This is delta_h's moment. Table 11 gives delta_h as internally
                                    ! calibrated against a child homelessness ratio of 2.10, the
                                    ! midpoint of Bassuk et al.'s odds ratios of 1.80 and 2.41, and
                                    ! child_homeless_ratio_data has been declared for it all along;
                                    ! there was simply nothing in the model to compare it with.
                                    if (housing_status_index_used==lowest_housing_grid_point) then

                                        percent_homeless_by_employment(time_period,employment_index)=&
                                            percent_homeless_by_employment(time_period,employment_index)+&
                                            distribution_mass_used

                                    end if

                                    ! Every household passes here, which is what
                                    ! the use rate by age needs under it.
                                    model_alive_by_age(age_index)=&
                                        model_alive_by_age(age_index)+distribution_mass_used

                                    ! THE VALIDATION ROWS THIS PASS CAN SEE, put
                                    ! where every household passes and where the
                                    ! numerator and the denominator of each are
                                    ! therefore in the same loop nest, for the
                                    ! reason the comment above gives.
                                    val_is_homeless_1=0
                                    if (housing_status_index_used==lowest_housing_grid_point) then
                                        val_is_homeless_1=1
                                    end if
                                    val_is_sud_1=0
                                    if (unemployment_index>threshold_addiction_index) then
                                        val_is_sud_1=1
                                    end if
                                    ! WORKING AT ALL. A household works if it is
                                    ! in the employed state and chose positive
                                    ! hours; the same test model_fraction_choose
                                    ! _zero_work uses, so the two agree.
                                    val_in_labour_force_1=0
                                    if (in_retirement==0) then
                                        if (emp_of(unemployment_index)>1) then
                                            ! In a spell: unemployed, which is IN
                                            ! the labour force and is how pi_eu
                                            ! is measured a few blocks above.
                                            val_in_labour_force_1=1
                                        elseif (labor_supply_used>10.d0**(-7)) then
                                            val_in_labour_force_1=2
                                        end if
                                    end if

                                    ! LABOUR FORCE PARTICIPATION BY DISORDER
                                    ! STATUS. NSDUH puts participation HIGHER
                                    ! with a disorder, 65.8 against 61.5, which
                                    ! is the informative half of this row: the
                                    ! earnings penalty has to run through
                                    ! unemployment conditional on participating
                                    ! rather than through leaving the labour
                                    ! force, and a model that reproduces the
                                    ! level by pushing people out of it fails
                                    ! the check it looks like it passes.
                                    ! THE DENOMINATOR IS EVERY ADULT, NOT EVERY
                                    ! WORKING AGE ADULT. NSDUH's 65.8 and 61.5
                                    ! are participation among adults twenty six
                                    ! and over, which includes the retired, and
                                    ! the retired are most of what separates a
                                    ! participation rate of 0.62 from one of 1.
                                    ! Measured over working age households only
                                    ! this row came back as exactly 1.0000 on
                                    ! both arms, which is not the model failing
                                    ! the check: it is the wrong universe, and
                                    ! the exact 1 is worth keeping in its own
                                    ! right because it says the model has NO
                                    ! extensive margin -- every household in the
                                    ! employed state chooses positive hours, so
                                    ! nobody leaves the labour force except by
                                    ! retiring.
                                    if (val_is_sud_1==1) then
                                        val_lfp_sud_den(time_period)=&
                                            val_lfp_sud_den(time_period)+distribution_mass_used
                                        if (val_in_labour_force_1>0) then
                                            val_lfp_sud_num(time_period)=&
                                                val_lfp_sud_num(time_period)+distribution_mass_used
                                        end if
                                        if (in_retirement==0) then
                                            val_lfp_sud_work_den(time_period)=&
                                                val_lfp_sud_work_den(time_period)+distribution_mass_used
                                        end if
                                    else
                                        val_lfp_clean_den(time_period)=&
                                            val_lfp_clean_den(time_period)+distribution_mass_used
                                        if (val_in_labour_force_1>0) then
                                            val_lfp_clean_num(time_period)=&
                                                val_lfp_clean_num(time_period)+distribution_mass_used
                                        end if
                                        if (in_retirement==0) then
                                            val_lfp_clean_work_den(time_period)=&
                                                val_lfp_clean_work_den(time_period)+distribution_mass_used
                                        end if
                                    end if

                                    ! THE THREE TEDS-A ROWS. The admissions file
                                    ! is selected on entering publicly funded
                                    ! treatment, so it is useful for ratios and
                                    ! not levels, and the flow into treatment is
                                    ! the right denominator for all three. All
                                    ! ages enter, as they do in TEDS-A, which
                                    ! means a retiree counts as not working.
                                    if (val_is_sud_1==1) then

                                        val_treat_1=real(policy_function_treatment(years_left_on_mortgage_index)%&
                                            vector_transition_integer(time_period,age_index,financial_index,&
                                            unemployment_index,employment_index,housing_status_index,&
                                            voucher_index),8)*distribution_mass_used

                                        val_treat_mass(time_period)=val_treat_mass(time_period)+val_treat_1

                                        if (smi_of(unemployment_index)>=1) then
                                            val_treat_smi(time_period)=val_treat_smi(time_period)+val_treat_1
                                        end if

                                        if (val_is_homeless_1==1) then
                                            val_treat_homeless(time_period)=&
                                                val_treat_homeless(time_period)+val_treat_1
                                            if (val_in_labour_force_1==2) then
                                                val_treat_homeless_working(time_period)=&
                                                    val_treat_homeless_working(time_period)+val_treat_1
                                            end if
                                        end if

                                    end if

                                    ! DRUG POISONINGS AS A SHARE OF DEATHS AT
                                    ! 25 TO 44. The model has no cause of death,
                                    ! but survival_probability carries the
                                    ! disorder as an argument, so the deaths the
                                    ! disorder is responsible for are the deaths
                                    ! that would not have happened at the clean
                                    ! hazard, holding age, homelessness and SMI.
                                    ! Model age one is data age 26, so ages 26 to
                                    ! 44 are age_index 1 to 19; the data band
                                    ! starts a year earlier and the model has no
                                    ! twenty five year olds to give it.
                                    if (age_index<=19) then

                                        val_deaths_all_young(time_period)=val_deaths_all_young(time_period)+&
                                            distribution_mass_used*(1-survival_probability(age_index,&
                                            1+val_is_homeless_1,val_is_sud_1,smi_of(unemployment_index)))

                                        val_deaths_clean_young(time_period)=val_deaths_clean_young(time_period)+&
                                            distribution_mass_used*(1-survival_probability(age_index,&
                                            1+val_is_homeless_1,0,smi_of(unemployment_index)))

                                    end if

                                    ! THE FLOW, restricted to households who can still acquire the
                                    ! disorder. A household that already has it is not at risk, so
                                    ! including it would average the onset rate over people for whom
                                    ! the hazard is not defined.
                                    if (sud_of(unemployment_index)==0) then

                                        clean_mass_by_employment(time_period,employment_index)=&
                                            clean_mass_by_employment(time_period,employment_index)+&
                                            distribution_mass_used

                                        drug_quantity_by_employment(time_period,employment_index)=&
                                            drug_quantity_by_employment(time_period,employment_index)+&
                                            (frac_spent_on_addiction_used*total_consumption_used/&
                                            price_of_addictive_good)*distribution_mass_used

                                        clean_consumption_by_employment(time_period,employment_index)=&
                                            clean_consumption_by_employment(time_period,employment_index)+&
                                            total_consumption_used*distribution_mass_used

                                        ! The hazard is averaged, not evaluated at the average
                                        ! quantity: 1-exp(-lambda v) is concave, so the two differ
                                        ! and it is the average hazard that generates the flow.
                                        onset_hazard_by_employment(time_period,employment_index)=&
                                            onset_hazard_by_employment(time_period,employment_index)+&
                                            addiction_onset_hazard(frac_spent_on_addiction_used*&
                                            total_consumption_used/price_of_addictive_good)*&
                                            distribution_mass_used

                                    end if
                                                                                                                     
                                    if (years_left_on_mortgage_index>1) then
                                        
                                        is_current_owner=1
                                        homeowner_spending=&
                                            housing_price(time_period)*housing_size(housing_status_index)*&
                                            (property_tax(time_period)+housing_depreciation_rate-&
                                            mortgage_interest_rate(time_period)*min(financial_grid(financial_index),0.d0))
                                            
                                    else
                                    
                                        is_current_owner=0
                                        homeowner_spending=0
                                        
                                    end if
                                    
                                    if (amortization_used>1) then
                                        
                                        choose_to_rent=0
                                        
                                    else
                                    
                                        choose_to_rent=1
                                        
                                    end if
                                    
                                    if ((housing_status_index_used>second_lowest_housing_grid_point) .OR. &
                                       (have_two_rental_markets==0)) then
                                    
                                        low_quality_market=0
                                    
                                    else
                                    
                                        low_quality_market=1
                                    
                                    end if
                                                                       
                                    call calculate_income(unemployment_index,employment_index,income_1,&
                                        avg_income_to_use_1,avg_income_to_use_2,labor_supply_used,in_retirement)

                                    income_2=income_1+(risk_free_rate(time_period)*max(financial_grid(financial_index),0.d0)+unsecured_borrowing_rate*min(financial_grid(financial_index),0.d0))  
                                                                        
                                    if ((addiction_consumption_1>0) .AND. &
                                        (unemployment_index<=threshold_addiction_index) .AND. &
                                        (is_current_owner==1)) then
                                    
                                        model_homeowners_experimenting(time_period)=&
                                            model_homeowners_experimenting(time_period)+distribution_mass_used
                                            
                                    end if
                                    
                                    if ((income_2<threshold_income_vouchers*((1-is_counterfactual)*median_income(time_period)+&
                                        is_counterfactual*median_income_calibrated)) .AND. (include_vouchers==1)) then

                                        if ((amortization_used==1) .AND. (years_left_on_mortgage_index==1)) then

                                            model_eligibles(time_period)=model_eligibles(time_period)+distribution_mass_used

                                        end if

                                        if ((years_left_on_mortgage_index==1) .AND. (amortization_used==1) .AND. &
                                            (voucher_index==1)) then
                                                                                                            
                                            call calculate_housing_voucher_2(housing_voucher_2,addiction_choice_2,income_2,&
                                                rent(time_period,low_quality_market)*housing_size(housing_status_index_used),&
                                                time_period)
                                                                                        
                                            govt_spending_on_housing_vouchers_2(time_period)=&
                                                govt_spending_on_housing_vouchers_2(time_period)+&
                                                housing_voucher_2*distribution_mass_used
                                                
                                            if (housing_voucher_2>0) then
                                            
                                                model_fraction_recieving_housing_vouchers(time_period)=&   
                                                    model_fraction_recieving_housing_vouchers(time_period)+&
                                                    distribution_mass_used

                                                model_eligibles_getting_voucher(time_period)=&  
                                                    model_eligibles_getting_voucher(time_period)+distribution_mass_used
                                                    
                                                if (unemployment_index>threshold_addiction_index) then
                                                    
                                                    model_addicts_getting_voucher(time_period)=&
                                                        model_addicts_getting_voucher(time_period)+distribution_mass_used
                                                    
                                                end if
                                                
                                                if (addiction_consumption_1>0) then
                                                
                                                    model_drug_users_getting_voucher(time_period)=&
                                                        model_drug_users_getting_voucher(time_period)+distribution_mass_used

                                                end if
                                                
                                                if ((addiction_consumption_1>0) .AND. &
                                                    (unemployment_index<=threshold_addiction_index)) then
                                                    
                                                    model_experimenters_getting_voucher(time_period)=&
                                                        model_experimenters_getting_voucher(time_period)+distribution_mass_used
                                                    
                                                end if
                                                
                                            end if
                                        
                                        end if
                                        
                                    end if
                                    
                                    assets_1=2*threshold_for_food_stamps_as_perc_of_average_net_wealth*&
                                        avg_net_wealth_to_use_1
                                    
                                    ! This one is a homeowner who chooses to rent
                                    if ((years_left_on_mortgage_index>1) .AND. (amortization_used==1)) then

                                        assets_1=max(housing_price(time_period)*housing_size(housing_status_index)*&
                                            ((1-cost_of_selling-property_tax(time_period)-housing_depreciation_rate)+&
                                            min(financial_grid(financial_index),0.d0)*(1+mortgage_interest_rate(time_period)))+&
                                            max(financial_grid(financial_index),0.d0),0.d0)
                                
                                    ! This one is a renter who stays renting
                                    elseif ((years_left_on_mortgage_index==1) .AND. (amortization_used==1)) then
                                    
                                        assets_1=max(financial_grid(financial_index),0.d0)

                                    end if
                                    
                                    ! THE NUMERATOR HAS TO BE SUMMED OVER THE SET THE DENOMINATOR
                                    ! COUNTS, and it was not. This guard used to be
                                    ! addiction_consumption_1>0 alone -- households that BUY drugs --
                                    ! while model_mass_total_users, which divides it, counts buyers
                                    ! PLUS every household carrying the disorder whether it buys or
                                    ! not. So a household with the disorder that consumes nothing
                                    ! contributed its mass to the denominator and none of its income
                                    ! to the numerator, and the average income of drug users came out
                                    ! low by exactly that group's share of the user mass.
                                    !
                                    ! model_addicts_consuming_no_drugs exists precisely because the
                                    ! group is not empty, so this was never a harmless mismatch. The
                                    ! guard below is now character for character the one on
                                    ! model_mass_total_users.
                                    if (((addiction_consumption_1>0) .AND. (unemployment_index<=threshold_addiction_index)) .OR. &
                                        (unemployment_index>threshold_addiction_index)) then
                                    
                                        ! INCOME INCLUDING INTEREST, TO MATCH THE DENOMINATOR. These ratios divide by
                                        ! model_average_income, which adds r*max(a,0) unconditionally, while the
                                        ! numerators were accumulated with income_1, which is social security,
                                        ! earnings or UI/DI and NO interest. NSDUH's income variable is total
                                        ! personal income, so the 0.740 target is the interest-inclusive ratio --
                                        ! and the model's users are not asset-poor, holding about half of average
                                        ! net worth against a wealth-to-output ratio near four, so the omitted
                                        ! term is large. The mismatch biases y_u DOWN, which is the direction of
                                        ! the failure it has been showing all day: 0.33 to 0.47 against 0.740.
                                        model_avg_income_drug_users(time_period)=&
                                            model_avg_income_drug_users(time_period)+income_2*distribution_mass_used

                                        ! SAME GUARD, character for character, as the line
                                        ! above. That is the whole point: three statistics have
                                        ! been found today whose numerator and denominator ran
                                        ! over different sets, so an age decomposition of this
                                        ! average has to be summed over exactly the households
                                        ! the average is summed over.
                                        val_user_mass_age(time_period)=val_user_mass_age(time_period)+&
                                            distribution_mass_used
                                        val_user_age_num(time_period)=val_user_age_num(time_period)+&
                                            (25.d0+real(age_index,8))*distribution_mass_used

                                        if (age_index<=9) then
                                            val_band_2=1
                                        elseif (age_index<=19) then
                                            val_band_2=2
                                        elseif (age_index<=29) then
                                            val_band_2=3
                                        elseif (age_index<=39) then
                                            val_band_2=4
                                        else
                                            val_band_2=5
                                        end if

                                        val_user_band(time_period,val_band_2)=&
                                            val_user_band(time_period,val_band_2)+distribution_mass_used
                                        val_user_inc_band(time_period,val_band_2)=&
                                            val_user_inc_band(time_period,val_band_2)+income_2*distribution_mass_used
                                        if (unemployment_index>threshold_addiction_index) then
                                            val_user_sud_band(time_period,val_band_2)=&
                                                val_user_sud_band(time_period,val_band_2)+distribution_mass_used
                                        end if

                                        if (age_index<=(life_span-retirement_span)) then
                                            val_user_mass_working(time_period)=&
                                                val_user_mass_working(time_period)+distribution_mass_used
                                            val_user_income_working(time_period)=&
                                                val_user_income_working(time_period)+income_2*distribution_mass_used
                                        end if

                                    end if
                                    
                                    ! THE STONE GEARY THRESHOLD, TESTED RATHER THAN ASSUMED.
                                    ! Over CLEAN households only, because the question is who
                                    ! CHOOSES to buy; a household that already carries the
                                    ! disorder is not making that choice for the first time.
                                    ! C is total_consumption_used, the resources the split in
                                    ! optimize_frac_spent_on_addiciton divides, which is the
                                    ! object the threshold is on -- income is not.
                                    if (unemployment_index<=threshold_addiction_index) then
                                        if (addiction_consumption_1>0) then
                                            val_buy_mass(time_period)=val_buy_mass(time_period)+&
                                                distribution_mass_used
                                            val_buy_C(time_period)=val_buy_C(time_period)+&
                                                total_consumption_used*distribution_mass_used
                                            val_buy_income(time_period)=val_buy_income(time_period)+&
                                                income_1*distribution_mass_used
                                        else
                                            val_nobuy_mass(time_period)=val_nobuy_mass(time_period)+&
                                                distribution_mass_used
                                            val_nobuy_C(time_period)=val_nobuy_C(time_period)+&
                                                total_consumption_used*distribution_mass_used
                                            val_nobuy_income(time_period)=val_nobuy_income(time_period)+&
                                                income_1*distribution_mass_used
                                        end if
                                    end if

                                    if ((addiction_consumption_1>0) .AND. &
                                        (unemployment_index<=threshold_addiction_index) .AND. &
                                        (include_probability_of_becoming_addicted==1)) then
                                        
                                        model_avg_income_experimenters(time_period)=&
                                            model_avg_income_experimenters(time_period)+income_1*distribution_mass_used
                                            
                                        ! This one is a homeowner who chooses to rent
                                        if (years_left_on_mortgage_index>1) then

                                            assets_2=max(housing_price(time_period)*housing_size(housing_status_index)*&
                                                ((1-cost_of_selling-property_tax(time_period)-housing_depreciation_rate)+&
                                                min(financial_grid(financial_index),0.d0)*(1+mortgage_interest_rate(time_period)))+&
                                                max(financial_grid(financial_index),0.d0),0.d0)
                                    
                                        ! This one is a renter who stays renting
                                        elseif (years_left_on_mortgage_index==1) then
                                        
                                            assets_2=max(financial_grid(financial_index),0.d0)

                                        end if 
                                            
                                        model_avg_assets_experimenters(time_period)=&
                                            model_avg_assets_experimenters(time_period)+assets_2*distribution_mass_used
                                            
                                        model_exprimenters(time_period)=model_exprimenters(time_period)+&
                                            distribution_mass_used
                                            
                                        model_average_drug_spending_experimenters(time_period)=&
                                            model_average_drug_spending_experimenters(time_period)+&
                                            addiction_consumption_1*distribution_mass_used
                                            
                                        if (addiction_consumption_1<=((1-is_counterfactual)*model_drug_threshold(time_period)+&
                                            is_counterfactual*drug_threshold_calibrated)*(1+0.000000001d0)) then
                                            
                                            model_fraction_light_users(time_period)=model_fraction_light_users(time_period)+&
                                                distribution_mass_used
                                            
                                        end if
                                                                                    
                                    end if
                                    
                                    food_stamps_1=0
                                    
                                    ! If they have no assets, they get can qualift for food stamps
                                    if (assets_1<threshold_for_food_stamps_as_perc_of_average_net_wealth*&
                                        avg_net_wealth_to_use_1) then
                                                            
                                        food_stamps_1=snap_benefit(actual_household_size(age_index),&
                                            income_1+max(financial_grid(financial_index),0.d0)*&
                                            risk_free_rate(time_period),avg_income_to_use_1)
                                                                    
                                    end if
                                    
                                    if ((addiction_consumption_1>0) .AND. &
                                        (unemployment_index<=threshold_addiction_index)) then
                                                                                
                                        income_2=income_1+risk_free_rate(time_period)*&
                                            max(financial_grid(financial_index),0.d0)+bequest_1
                                            
                                        model_experimenters_total_drug_spending_to_total_income(time_period)=&
                                            model_experimenters_total_drug_spending_to_total_income(time_period)+&
                                            (frac_spent_on_addiction_used*total_consumption_used)*distribution_mass_used
                                            
                                        model_experimenters_total_income(time_period)=&
                                            model_experimenters_total_income(time_period)+income_2*distribution_mass_used
                                                                                        
                                        if (income_2>0) then
                                    
                                            model_fraction_spent_on_addiction_experimenters(time_period)=&
                                                model_fraction_spent_on_addiction_experimenters(time_period)+&
                                                (frac_spent_on_addiction_used*total_consumption_used/income_2)*&
                                                distribution_mass_used
                                              
                                        else
                                        
                                            model_fraction_spent_on_addiction_experimenters(time_period)=&
                                                model_fraction_spent_on_addiction_experimenters(time_period)+&
                                                1*distribution_mass_used
                                            
                                        end if
                                        
                                    end if
                                    
                                    ! TREATMENT TAKE UP, over households that
                                    ! carry the disorder, which is the
                                    ! denominator NSDUH reports it on.
                                    if (unemployment_index>threshold_addiction_index) then

                                        model_mass_with_sud(time_period)=&
                                            model_mass_with_sud(time_period)+distribution_mass_used

                                        model_treatment_take_up(time_period)=&
                                            model_treatment_take_up(time_period)+&
                                            real(policy_function_treatment(years_left_on_mortgage_index)%&
                                            vector_transition_integer(time_period,age_index,financial_index,&
                                            unemployment_index,employment_index,housing_status_index,&
                                            voucher_index),8)*distribution_mass_used

                                        ! MU_H's MOMENT. The recovery hazard each
                                        ! household actually faces, averaged over
                                        ! the housed and the homeless separately,
                                        ! so their ratio is the increase in
                                        ! recovery that housing produces IN THE
                                        ! MODEL rather than the raw ratio mu_H is
                                        ! built from. The two differ through
                                        ! composition: who is on the street is not
                                        ! a random draw of who carries the
                                        ! disorder, and the SMI multiplier and
                                        ! treatment take up both enter the hazard.
                                        if (housing_status_index_used>=second_lowest_housing_grid_point) then

                                            model_sud_mass_housed(time_period)=&
                                                model_sud_mass_housed(time_period)+distribution_mass_used

                                            model_recovery_housed(time_period)=&
                                                model_recovery_housed(time_period)+distribution_mass_used*&
                                                addiction_transition(1,0,&
                                                policy_function_addiction(years_left_on_mortgage_index)%&
                                                vector_transition_integer(time_period,age_index,financial_index,&
                                                unemployment_index,employment_index,housing_status_index,&
                                                voucher_index),1,0.d0,1,&
                                                policy_function_treatment(years_left_on_mortgage_index)%&
                                                vector_transition_integer(time_period,age_index,financial_index,&
                                                unemployment_index,employment_index,housing_status_index,&
                                                voucher_index),smi_of(unemployment_index))

                                        else

                                            model_sud_mass_homeless(time_period)=&
                                                model_sud_mass_homeless(time_period)+distribution_mass_used

                                            model_recovery_homeless(time_period)=&
                                                model_recovery_homeless(time_period)+distribution_mass_used*&
                                                addiction_transition(1,0,&
                                                policy_function_addiction(years_left_on_mortgage_index)%&
                                                vector_transition_integer(time_period,age_index,financial_index,&
                                                unemployment_index,employment_index,housing_status_index,&
                                                voucher_index),2,0.d0,1,&
                                                policy_function_treatment(years_left_on_mortgage_index)%&
                                                vector_transition_integer(time_period,age_index,financial_index,&
                                                unemployment_index,employment_index,housing_status_index,&
                                                voucher_index),smi_of(unemployment_index))

                                        end if

                                    end if

                                    if (((addiction_consumption_1>0) .AND. (unemployment_index<=threshold_addiction_index)) .OR. &
                                        (unemployment_index>threshold_addiction_index)) then
                                        
                                        model_drugs_used_by_users_on_average(time_period)=&
                                            model_drugs_used_by_users_on_average(time_period)+&
                                            (frac_spent_on_addiction_used*total_consumption_used/price_of_addictive_good)*&
                                            distribution_mass_used
                                            
                                        model_drugs_consumed_by_users(time_period)=&
                                            model_drugs_consumed_by_users(time_period)+&
                                            (frac_spent_on_addiction_used*total_consumption_used/price_of_addictive_good)*&
                                            distribution_mass_used
                                            
                                        model_mass_total_users(time_period)=&
                                            model_mass_total_users(time_period)+distribution_mass_used
                                            
                                        if (age_index<=4) then
                                        
                                            age_group_1=1
                                            
                                        elseif (age_index<=9) then
                                            
                                            age_group_1=2
                                                
                                        elseif (age_index<=14) then
                                            
                                            age_group_1=3
                                            
                                        elseif (age_index<=19) then
                                            
                                            age_group_1=4
                                            
                                        elseif (age_index<=24) then
                                            
                                            age_group_1=5
                                            
                                        elseif (age_index<=29) then
                                            
                                            age_group_1=6
                                            
                                        elseif (age_index<=34) then
                                            
                                            age_group_1=7
                                            
                                        elseif (age_index<=39) then
                                            
                                            age_group_1=8
                                            
                                        else
                                        
                                            age_group_1=9
                                            
                                        end if
                                                
                                        model_drug_use_by_age_group(time_period,age_group_1)=&
                                            model_drug_use_by_age_group(time_period,age_group_1)+distribution_mass_used

                                        model_users_by_age(age_index)=&
                                            model_users_by_age(age_index)+distribution_mass_used
                                            
                                        model_drug_use_percent_by_age_group(time_period,age_group_1)=&
                                            model_drug_use_percent_by_age_group(time_period,age_group_1)+&
                                            distribution_mass_used
                                            
                                        if (unemployment_index>threshold_addiction_index) then
                                        
                                            model_drugs_used_by_addicts_on_average(time_period)=&
                                                model_drugs_used_by_addicts_on_average(time_period)+&
                                                (frac_spent_on_addiction_used*total_consumption_used/price_of_addictive_good)*&
                                                distribution_mass_used
                                        
                                            model_mass_addicts(time_period)=&
                                                model_mass_addicts(time_period)+distribution_mass_used
                                                
                                            model_addiction_rate_by_age(time_period,age_index)=&
                                                model_addiction_rate_by_age(time_period,age_index)+&
                                                distribution_mass_used
                                                                                            
                                        end if
                                            
                                        if ((addiction_consumption_1>0) .AND. (unemployment_index<=threshold_addiction_index)) then
                                        
                                            model_drugs_used_by_experimenters_on_average(time_period)=&
                                                model_drugs_used_by_experimenters_on_average(time_period)+&
                                                (frac_spent_on_addiction_used*total_consumption_used/price_of_addictive_good)*&
                                                distribution_mass_used
                                            
                                            model_mass_experimenters(time_period)=&
                                                model_mass_experimenters(time_period)+distribution_mass_used
                                                
                                            model_experimentation_choice_by_age(time_period,age_index)=&
                                                model_experimentation_choice_by_age(time_period,age_index)+&
                                                distribution_mass_used
                                        
                                        end if
                                            
                                    end if
                                                                        
                                    if (unemployment_index>threshold_addiction_index) then
                                    
                                        model_average_spent_on_addiction_by_addicted(time_period)=&
                                            model_average_spent_on_addiction_by_addicted(time_period)+&
                                            frac_spent_on_addiction_used*distribution_mass_used
                                            
                                        model_addicted(time_period)=model_addicted(time_period)+&
                                            distribution_mass_used
                                    
                                        total_addited_1=total_addited_1+distribution_mass_used
                                                                            
                                        income_2=income_1+(risk_free_rate(time_period)*max(financial_grid(financial_index),0.d0)+unsecured_borrowing_rate*min(financial_grid(financial_index),0.d0))+&
                                            bequest_1
                                            
                                        model_addicted_total_income(time_period)=&
                                            model_addicted_total_income(time_period)+&
                                            income_2*distribution_mass_used
                                            
                                        model_addicted_total_addiction_spending_to_total_income(time_period)=&
                                            model_addicted_total_addiction_spending_to_total_income(time_period)+&
                                            (frac_spent_on_addiction_used*total_consumption_used)*distribution_mass_used
                                        
                                        if (income_2>0) then
                                    
                                            model_fraction_spent_on_addiction(time_period)=&
                                                model_fraction_spent_on_addiction(time_period)+&
                                                (frac_spent_on_addiction_used*total_consumption_used/income_2)*&
                                                distribution_mass_used
                                              
                                        else
                                        
                                            model_fraction_spent_on_addiction(time_period)=&
                                                model_fraction_spent_on_addiction(time_period)+1*distribution_mass_used
                                            
                                        end if
                                        
                                        ! ONE OWNER PER VARIABLE. Reset and accumulation disabled here.
                                        !
                                        ! Every reset in the chain is guarded to the FIRST pass, which is safe only
                                        ! if exactly one routine owns the variable. Where two or more each reset and
                                        ! each accumulate, the guard that stops pass two resetting also lets each
                                        ! routine start from whatever the previous one left, so the second pass adds
                                        ! another copy of the second type on top of a finished total. Four owners of
                                        ! mass_by_employment made it 5*M where the pooled mass is 2*M, so every
                                        ! welfare-by-employment average was halved and homeownership_by_employment
                                        ! came out at 0.4 times truth.
                                        !
                                        ! It is the same quantity in every owner, so the FIRST in call order keeps
                                        ! it and the rest read it. The order is the same in the driver and in
                                        ! long_run_counter_factual, so the value is always built before it is read.
                                        ! mass_by_employment(time_period,employment_index)=&
                                        ! mass_by_employment(time_period,employment_index)+distribution_mass_used

                                        ! EVERY HOUSEHOLD WITH THE DISORDER COUNTS HERE. This block is
                                        ! already reached only when sud_of is one, so the mass added is
                                        ! the disorder's, and the sub-block below narrows to the employed
                                        ! for a different statistic. Counting the numerator inside that
                                        ! narrower test made this the employment rate among households
                                        ! with the disorder rather than the disorder rate by productivity,
                                        ! which is what delta_d is calibrated against.
                                        percent_addicted_by_employment(time_period,employment_index)=&
                                            percent_addicted_by_employment(time_period,employment_index)+&
                                            distribution_mass_used

                                        if ((sud_of(unemployment_index)==1 .AND. emp_of(unemployment_index)==1)) then
                                            
                                            addiction_share_of_income_by_employment(time_period,employment_index)=&
                                                addiction_share_of_income_by_employment(time_period,employment_index)+&
                                                (frac_spent_on_addiction_used*total_consumption_used/&
                                                (income_1+risk_free_rate(time_period)*&
                                                max(financial_grid(financial_index),0.d0)))*distribution_mass_used
                                                                                
                                            employment_mass(time_period,employment_index)=&
                                                employment_mass(time_period,employment_index)+distribution_mass_used
                                                
                                        end if
                                                                                
                                    end if
                                    
                                    if ((has_house==1) .AND. (in_retirement==0)) then
                                                                           
                                        if ((property_tax_deductibility>0) .OR. (mortgage_deductibility>0)) then 
                                                                                                             
                                            govt_spending_on_mortgage_interest_deductions(time_period)=&
                                                govt_spending_on_mortgage_interest_deductions(time_period)+&
                                                MID_used*distribution_mass_used
                                                                                        
                                            is_renter_to_owner=0
                                                                                        
                                        end if
                                                                                    
                                        if (MID_used>0) then
                                            
                                            fraction_using_MID(time_period)=fraction_using_MID(time_period)+distribution_mass_used
                                            
                                        end if
                                        
                                        if ((in_retirement==1) .AND. (MID_used>0)) then
                                        
                                            write(*,*) "error mortgage deduction"
                                            write(*,*) "MID_used=", MID_used
                                            
                                        end if
                                        
                                        if ((MID_used>0) .AND. (years_left_on_mortgage_index<=1)) then
                                        
                                            write(*,*) "renter with mortgage deductions"
                                            write(*,*) "MID_used=", MID_used
                                        
                                        end if
                                        
                                    end if
                                                                                                                      
                                    govt_revenues_from_labour_income(time_period)=&
                                        govt_revenues_from_labour_income(time_period)+income_tax_used*distribution_mass_used
                                                                                                                        
                                    if (in_retirement==1) then

                                        govt_spending_on_ss(time_period)=govt_spending_on_ss(time_period)+&
                                            model_ss_benefits(employment_index)*distribution_mass_used

                                        govt_ss_wasted(time_period)=govt_ss_wasted(time_period)+&
                                            (model_ss_benefits(employment_index)-income_1)*distribution_mass_used
                                                                                 
                                    else
                                    
                                        ! UI and DI are separate outlays in eq:fgovt and are
                                        ! separated here, so the budget carries both and the run
                                        ! can report what each costs.
                                        if (emp_of(unemployment_index)==3) then
                                        
                                            govt_spending_on_ui(time_period)=govt_spending_on_ui(time_period)+&
                                                income_1*distribution_mass_used
                                                      
                                        elseif ((emp_of(unemployment_index)==2) .AND. &
                                            (smi_of(unemployment_index)>=1)) then
                                        
                                            govt_spending_on_di(time_period)=govt_spending_on_di(time_period)+&
                                                income_1*distribution_mass_used
                                        
                                        end if
                                             
                                    end if
                                    
                                    if (housing_status_index_used==lowest_housing_grid_point) then
                                    
                                        ! OWNED BY stationary_equilibrium_statistics, WHICH RUNS FIRST. Reset,
                                        ! accumulation and division disabled here.
                                        !
                                        ! model_fraction_homeless was reset, accumulated AND divided in two chain
                                        ! routines. Both resets are guarded to the first pass, so on the second
                                        ! pass this routine accumulated a MASS on top of the RATE the earlier one
                                        ! had already produced, then divided again: the value the h_1 bisection
                                        ! read was a 1:3 mixture over-weighting the impatient type, not the 1:1
                                        ! mixture the design intends. h_1 is a TARGETED moment and
                                        ! size_homelessness is driven by it.
                                        !
                                        ! The two routines divide by different denominators -- lowest
                                        ! productivities against sum_of_distribution -- but the first is
                                        ! accumulated for every household with no condition, so despite its name
                                        ! it is the same total mass. Keeping one owner is enough.
                                        ! model_fraction_homeless(time_period)=model_fraction_homeless(time_period)+&
                                        ! distribution_mass_used
                                    
                                        govt_spending_on_homeless(time_period)=govt_spending_on_homeless(time_period)+&
                                            homeless_cost_govt_as_perc_of_avg_inc*avg_income_to_use_1*distribution_mass_used
                                    
                                    end if
                                                                        
                                    if (food_stamps_1>0) then
                                    
                                        model_fraction_recieving_food_stamps(time_period)=&
                                            model_fraction_recieving_food_stamps(time_period)+&
                                            distribution_mass_used
                                    
                                    end if
                                    
                                    if ((food_stamps_1>0) .AND. &
                                        (housing_status_index_used==lowest_housing_grid_point)) then
                                    
                                        model_fraction_homeless_recieving_food_stamps(time_period)=&
                                            model_fraction_homeless_recieving_food_stamps(time_period)+&
                                            distribution_mass_used
                                            
                                        model_food_stamps_share_to_homeless(time_period)=&
                                            model_food_stamps_share_to_homeless(time_period)+&
                                            food_stamps_1*distribution_mass_used
                                            
                                    end if

                                    govt_spending_on_food_stamps(time_period)=govt_spending_on_food_stamps(time_period)+&
                                        food_stamps_1*distribution_mass_used
                                        
                                    is_addicted=0
                                    
                                    if (addiction_consumption_1>0) then
                                    
                                        is_addicted=1
                                    
                                    end if
                                    
                                    if (in_retirement>=0) then
                                    
                                        if (unemployment_index<=threshold_addiction_index) then
                                        
                                            if (addiction_consumption_1>0) then
                                        
                                                model_fraction_choose_addiction(time_period)=&
                                                    model_fraction_choose_addiction(time_period)+distribution_mass_used
                                                    
                                            end if
                                        
                                        end if     
                                        
                                    end if
                                    
                                    if ((unemployment_index<=threshold_addiction_index) .AND. (addiction_consumption_1>0)) then
                                    
                                        model_mass_choose_addiction(time_period)=model_mass_choose_addiction(time_period)+&
                                            distribution_mass_used
                                    
                                    end if
                                    
                                    if ((in_retirement==1) .AND. (unemployment_index<=threshold_addiction_index) .AND. &
                                        (addiction_consumption_1>0)) then
                                    
                                        model_choose_addiction_when_retired(time_period)=&
                                            model_choose_addiction_when_retired(time_period)+distribution_mass_used
                                    
                                    end if
                                    
                                    if ((housing_status_index_used==lowest_housing_grid_point) .AND. &
                                        (unemployment_index<=threshold_addiction_index) .AND. (addiction_consumption_1>0)) then
                                        
                                        model_fraction_choose_addiction_when_homeless(time_period)=&
                                            model_fraction_choose_addiction_when_homeless(time_period)+distribution_mass_used
                                        
                                    end if  
                                                                                        
                                    if (in_retirement==0) then
                                    
                                        mass_by_employment_1(time_period,employment_index)=&
                                            mass_by_employment_1(time_period,employment_index)+distribution_mass_used
                                                                                                        
                                        if (((sud_of(unemployment_index)==0 .AND. emp_of(unemployment_index)==2)) .OR. &
                                            ((sud_of(unemployment_index)==0 .AND. emp_of(unemployment_index)==3)) .OR. &
                                            ((sud_of(unemployment_index)==1 .AND. emp_of(unemployment_index)==2)) .OR. &
                                            ((sud_of(unemployment_index)==1 .AND. emp_of(unemployment_index)==3))) then
                                            
                                            model_unemployment_by_employment(time_period,employment_index)=&
                                                model_unemployment_by_employment(time_period,employment_index)+&
                                                distribution_mass_used  
                                                                                        
                                            choose_addiction_1=0
                                        
                                            if (addiction_consumption_1>0) then
                                            
                                                choose_addiction_1=1
                                            
                                            end if
                                            
                                            if ((sud_of(unemployment_index)==0 .AND. emp_of(unemployment_index)==2)) then
                                            
                                                model_fraction_choose_addiction_when_unemployed(time_period)=&
                                                    model_fraction_choose_addiction_when_unemployed(time_period)+&
                                                    choose_addiction_1*distribution_mass_used
                                                    
                                            end if
                                        
                                        end if
                                        
                                    end if
                                    
                                    if ((addiction_consumption_1>0) .AND. &
                                        (unemployment_index<=threshold_addiction_index)) then  
                                                                            
                                        if (income_1<threshold_income_vouchers*&
                                            ((1-is_counterfactual)*median_income(time_period)+&
                                            is_counterfactual*median_income_calibrated)) then
                                    
                                            model_choose_addiction_when_income_is_low(time_period)=&
                                                model_choose_addiction_when_income_is_low(time_period)+&
                                                distribution_mass_used
                                                
                                        end if
                                                                            
                                    end if
                                    
                                    ! THE SAME DENOMINATOR, SO THE SAME SET. is_addicted is 1 when
                                    ! addiction_consumption_1>0, which means CONSUMES and not HAS THE
                                    ! DISORDER whatever the name suggests, and this is divided by
                                    ! model_mass_total_users like the income above.
                                    if (((addiction_consumption_1>0) .AND. (unemployment_index<=threshold_addiction_index)) .OR. &
                                        (unemployment_index>threshold_addiction_index)) then
                                                                        
                                        model_average_assets_drug_users(time_period)=&
                                            model_average_assets_drug_users(time_period)+&
                                            (has_house*housing_price(time_period)*housing_size(housing_status_index)+&
                                            max(financial_grid(financial_index),0.d0))*distribution_mass_used
                                            
                                    end if
                                    
                                    ! EVERY HOUSEHOLD CARRYING THE DISORDER, WHICH IS WHAT DIVIDES
                                    ! THESE TWO. total_addited_1 is guarded by
                                    ! unemployment_index>threshold_addiction_index and nothing else,
                                    ! so requiring is_addicted==1 here -- which means CONSUMES, not
                                    ! HAS THE DISORDER -- dropped the income and assets of every
                                    ! carrier consuming nothing while keeping their mass below the
                                    ! line. NSDUH's 71.1 per cent is over everyone with a moderate or
                                    ! severe disorder, consuming this year or not, so there is no
                                    ! reading on which the old pair was the right one.
                                    if (unemployment_index>threshold_addiction_index) then
                                    
                                        model_average_income_addicted(time_period)=&
                                            model_average_income_addicted(time_period)+&
                                            income_2*distribution_mass_used
                                            
                                        model_average_assets_addicted(time_period)=&
                                            model_average_assets_addicted(time_period)+&
                                            (has_house*housing_price(time_period)*housing_size(housing_status_index)+&
                                            max(financial_grid(financial_index),0.d0))*distribution_mass_used
                                        
                                    end if
                                    
                                    if ((unemployment_index>threshold_addiction_index) .OR. (is_addicted==1)) then
                                                                                                        
                                        model_age_by_addiction(time_period,1)=&
                                            model_age_by_addiction(time_period,1)+&
                                            age_index*distribution_mass_used
                                            
                                    else
                                    
                                        model_age_by_addiction(time_period,0)=&
                                            model_age_by_addiction(time_period,0)+&
                                            age_index*distribution_mass_used
                                            
                                    end if
                                        
                                    addiction_rate_by_age(time_period,age_index)=&
                                        addiction_rate_by_age(time_period,age_index)+&
                                        is_addicted*distribution_mass_used
                                        
                                    if (housing_status_index_used==lowest_housing_grid_point) then
                                    
                                        homeless_and_addiction_rate_by_age(time_period,age_index)=&
                                            homeless_and_addiction_rate_by_age(time_period,age_index)+&
                                            is_addicted*distribution_mass_used
                                    
                                    end if
                                        
                                    mass_by_age(time_period,age_index)=mass_by_age(time_period,age_index)+distribution_mass_used
                                    
                                    model_mass_age_by_addiction(time_period,is_addicted)=&
                                        model_mass_age_by_addiction(time_period,is_addicted)+distribution_mass_used
                                        
                                    if (housing_status_index_used==lowest_housing_grid_point) then
                                    
                                        total_homeless_1=total_homeless_1+distribution_mass_used
                                        
                                        model_avg_homeless_income(time_period)=&
                                            model_avg_homeless_income(time_period)+&
                                            income_2*distribution_mass_used
                                            
                                        after_tax_income_1=&
                                            (income_1-income_tax_used+(1-investment_income_tax)*&
                                            (risk_free_rate(time_period)*max(financial_grid(financial_index),0.d0)+unsecured_borrowing_rate*min(financial_grid(financial_index),0.d0))+&
                                            food_stamps_1)
                                            
                                        after_tax_income_2=after_tax_income_1-food_stamps_1
                                            
                                        model_average_assets_homeless_by_addiction(time_period,is_addicted)=&
                                            model_average_assets_homeless_by_addiction(time_period,is_addicted)+&
                                            (has_house*housing_price(time_period)*housing_size(housing_status_index)+&
                                            max(financial_grid(financial_index),0.d0))*distribution_mass_used
                                            
                                        model_average_income_homeless_by_addiction(time_period,is_addicted)=&
                                            model_average_income_homeless_by_addiction(time_period,is_addicted)+&
                                            income_1*distribution_mass_used
                                            
                                        model_mass_by_homeless_and_addiction(time_period,is_addicted)=&
                                            model_mass_by_homeless_and_addiction(time_period,is_addicted)+&
                                            distribution_mass_used
                                                                                
                                        model_avg_homeless_after_tax_income(time_period)=&
                                            model_avg_homeless_after_tax_income(time_period)+&
                                            after_tax_income_1*distribution_mass_used
                                            
                                        if (income_1>0) then
                                        
                                            model_avg_homeless_tax_to_income(time_period)=&
                                                model_avg_homeless_tax_to_income(time_period)+&
                                                (income_tax_used/income_1)*distribution_mass_used
                                                                                    
                                        end if
                                            
                                        if (years_left_on_mortgage_index==1) then
                                        
                                            model_avg_homeless_assets(time_period)=&
                                                model_avg_homeless_assets(time_period)+&
                                                max(financial_grid(financial_index),0.d0)*distribution_mass_used
                                                
                                            if (unemployment_index>threshold_addiction_index) then
                                            
                                                model_average_assets_addicted_and_homeless(time_period)=&
                                                    model_average_assets_addicted_and_homeless(time_period)+&
                                                    max(financial_grid(financial_index),0.d0)*distribution_mass_used
                                                    
                                            end if
                                        
                                        else
                                            
                                            model_avg_homeless_assets(time_period)=&
                                                model_avg_homeless_assets(time_period)+&
                                                (housing_price(time_period)*housing_size(housing_status_index)+&
                                                (1+min(financial_grid(financial_index),0.d0))+&
                                                max(financial_grid(financial_index),0.d0))*distribution_mass_used
                                                
                                            if (unemployment_index>threshold_addiction_index) then
                                            
                                                model_average_assets_addicted_and_homeless(time_period)=&
                                                    model_average_assets_addicted_and_homeless(time_period)+&
                                                    (housing_price(time_period)*housing_size(housing_status_index)+&
                                                    (1+min(financial_grid(financial_index),0.d0))+&
                                                    max(financial_grid(financial_index),0.d0))*distribution_mass_used
                                                    
                                            end if
                                                
                                        end if
                                        
                                        if (unemployment_index>threshold_addiction_index) then
                                        
                                            total_addicted_and_homeless_1=total_addicted_and_homeless_1+distribution_mass_used
                                            
                                            model_average_income_of_homeless_addicted(time_period)=&
                                                model_average_income_of_homeless_addicted(time_period)+&
                                                after_tax_income_1*distribution_mass_used
                                            
                                        end if
                                        
                                        ! THE SAME TEST WITHOUT THE ASSETS, which is the
                                        ! one that says whether stripping wealth could ever
                                        ! price a household out of the smallest unit.
                                        if (after_tax_income_2>&
                                            rent(time_period,0)*housing_size(second_lowest_housing_grid_point)) then

                                            val_homeless_afford_on_income(time_period)=&
                                                val_homeless_afford_on_income(time_period)+&
                                                distribution_mass_used

                                        end if

                                        if ((after_tax_income_2+financial_grid(financial_index))>&
                                            rent(time_period,0)*housing_size(second_lowest_housing_grid_point)) then
                                            
                                            model_fraction_homeless_by_choice(time_period)=&
                                                model_fraction_homeless_by_choice(time_period)+&
                                                distribution_mass_used
                                                
                                            if (unemployment_index>threshold_addiction_index) then
                                            
                                                model_addicted_and_homeless_by_choice(time_period)=&
                                                    model_addicted_and_homeless_by_choice(time_period)+distribution_mass_used
                                                    
                                            end if                                        
                                                                                        
                                        end if
                                        
                                    end if
                                    
                                    if (unemployment_index>threshold_addiction_index) then
                                    
                                        govt_spending_on_addicts(time_period)=govt_spending_on_addicts(time_period)+&
                                            addict_cost_govt_as_perc_of_avg_inc*avg_income_to_use_1*distribution_mass_used
                                    
                                    end if
                                    
!                                    if ((unemployment_index<=threshold_addiction_index) .AND. (addiction_choice_2==1)) then
!                                    
!                                        govt_spending_on_addicts(time_period)=govt_spending_on_addicts(time_period)+&
!                                            addict_cost_govt_as_perc_of_avg_inc*avg_income_to_use_1*distribution_mass_used
!                                            
!                                    end if
                                                                        
                                    housing_voucher_1=0
                                    
                                    if (provide_vouchers==1) then
                                                                                                            
                                        call calculate_housing_voucher(housing_voucher_1,income_1,rent(time_period,low_quality_market)*housing_size(housing_status_index_used),&
                                            homeowner_spending,is_current_owner,choose_to_rent,time_period)
                                              
                                    end if
                                                                    
                                    if (housing_voucher_1>0) then
                                    
                                        frac_getting_vouchers=frac_getting_vouchers+distribution_mass_used
                                        
                                    end if
                                        
                                    govt_spending_on_housing_vouchers(time_period)=govt_spending_on_housing_vouchers(time_period)+&
                                        housing_voucher_1*distribution_mass_used
                                    
                                    if (consumption_tax>0) then
                                                    
                                        govt_revenues_from_consumption(time_period)=&
                                            govt_revenues_from_consumption(time_period)+&
                                            consumption_tax*total_consumption_used*distribution_mass_used
                                            
                                    end if
                                        
                                    govt_revenues_from_investment_income(time_period)=&
                                        govt_revenues_from_investment_income(time_period)+investment_income_tax*&
                                        ((risk_free_rate(time_period)*max(financial_grid(financial_index),0.d0)+unsecured_borrowing_rate*min(financial_grid(financial_index),0.d0)))*&
                                        distribution_mass_used
                                                                         
                                    if (housing_status_index_used>=second_lowest_housing_grid_point) then
                                        
                                        if ((time_period>1) .OR. (solve_transition_dynamics==0)) then
                                                                                                                       
                                            govt_revenues_from_property_tax(time_period)=&
                                                govt_revenues_from_property_tax(time_period)+&
                                                property_tax(time_period)*housing_price(time_period)*&
                                                lived_in_size_used*distribution_mass_used
                                                                                      
                                        end if
                                        
                                    end if
                                    
                                end do
                                                                       
                            end do
                            
                        end do
                        
                    end do
                                                                   
                end do
        
            end do
            
        end do
        
        if (current_beta_type==number_of_beta_types) then
            model_fraction_light_users(time_period)=model_fraction_light_users(time_period)/&
                max(model_exprimenters(time_period),10.d0**(-14))
        end if
        
        if (model_mass_with_sud(time_period)>0) then

            if (current_beta_type==number_of_beta_types) then
                model_treatment_take_up(time_period)=&
                    model_treatment_take_up(time_period)/max(model_mass_with_sud(time_period),10.d0**(-14))
            end if

        end if

        ! Turn the two recovery sums into average hazards. Left at zero when a side
        ! is empty, which the update below tests for rather than dividing by it:
        ! with homelessness at a few tenths of a per cent the homeless SUD mass is
        ! small, and it is exactly zero whenever the housing margin has collapsed.
        if (model_sud_mass_housed(time_period)>0) then

            if (current_beta_type==number_of_beta_types) then
                model_recovery_housed(time_period)=&
                    model_recovery_housed(time_period)/max(model_sud_mass_housed(time_period),10.d0**(-14))
            end if

        end if

        if (model_sud_mass_homeless(time_period)>0) then

            if (current_beta_type==number_of_beta_types) then
                model_recovery_homeless(time_period)=&
                    model_recovery_homeless(time_period)/max(model_sud_mass_homeless(time_period),10.d0**(-14))
            end if

        end if

        if (current_beta_type==number_of_beta_types) then
            model_drugs_used_by_users_on_average(time_period)=&
                model_drugs_used_by_users_on_average(time_period)/max(model_mass_total_users(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_drugs_used_by_experimenters_on_average(time_period)=&
                model_drugs_used_by_experimenters_on_average(time_period)/max(model_mass_experimenters(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_drugs_used_by_addicts_on_average(time_period)=&
                model_drugs_used_by_addicts_on_average(time_period)/max(model_mass_addicts(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_addiction_rate_by_age(time_period,:)=&
                model_addiction_rate_by_age(time_period,:)/max(model_mass_addicts(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_drug_use_by_age_group(time_period,:)=&
                model_drug_use_by_age_group(time_period,:)/max(model_mass_total_users(time_period),10.d0**(-14))
        end if
                                                                                       
        if (current_beta_type==number_of_beta_types) then
            model_experimentation_choice_by_age(time_period,:)=&
                model_experimentation_choice_by_age(time_period,:)/max(model_mass_experimenters(time_period),10.d0**(-14))
        end if
        
        ! AFTER THIS BLOCK THESE TWO ARE RATIOS, spending over income, each
        ! summed over its group with the distribution's mass. Anything reading
        ! them downstream takes them as they are. The calibration used to divide
        ! them by the group's total income a SECOND time, and since that total is
        ! a mass weighted number of order 1e-4 for a group that barely exists,
        ! a share of 0.002 came back as 1,204,097 and a share of 0.007 as 62.
        ! That is what threw theta to its floor and back every other iteration.
        !
        ! A group with no income has no ratio. Dividing by zero here put a NaN
        ! into the drug block that survived into the next iteration, so the
        ! sentinel is negative and the caller tests for it.
        if (model_addicted_total_income(time_period)>0) then

            if (current_beta_type==number_of_beta_types) then
                model_addicted_total_addiction_spending_to_total_income(time_period)=&
                    model_addicted_total_addiction_spending_to_total_income(time_period)/&
                    max(model_addicted_total_income(time_period),10.d0**(-14))
            end if

        else

            model_addicted_total_addiction_spending_to_total_income(time_period)=-1

        end if

        if (model_experimenters_total_income(time_period)>0) then

            if (current_beta_type==number_of_beta_types) then
                model_experimenters_total_drug_spending_to_total_income(time_period)=&
                    model_experimenters_total_drug_spending_to_total_income(time_period)/&
                    max(model_experimenters_total_income(time_period),10.d0**(-14))
            end if

        else

            model_experimenters_total_drug_spending_to_total_income(time_period)=-1

        end if
        
        model_total_drug_users(time_period)=model_addicted(time_period)+model_exprimenters(time_period)
        
        if (current_beta_type==number_of_beta_types) then
            model_average_drug_spending_experimenters(time_period)=&
                model_average_drug_spending_experimenters(time_period)/max(model_exprimenters(time_period),10.d0**(-14))
        end if
        
        if (current_beta_type==number_of_beta_types) then
            model_addicts_getting_voucher(time_period)=&
                model_addicts_getting_voucher(time_period)/max(model_eligibles_getting_voucher(time_period),10.d0**(-14))
        end if
            
        sum_of_distribution=0
        
        do i=1,2
                
            sum_of_distribution=sum_of_distribution+&
                sum(distribution_stationary(i)%vector_transition_real(time_period,:,:,:,:,:,:))
            
        end do

        ! POOLED MASS, NOT ONE TYPE'S. The histograms and every other
        ! accumulator above hold both discount-factor types once the
        ! benchmark chain has run twice, so a denominator recomputed from
        ! distribution_stationary -- which holds only the type just solved --
        ! is short by exactly the number of passes. Scale it up.
        ! POOLED MASS, READ NOT REBUILT. stationary_equilibrium_statistics runs
        ! FIRST in every pass and has already added this type's mass, so the
        ! total here is the real pooled mass rather than one type's scaled by a
        ! pass count. The types do not weigh the same; see pooled_mass_all.
        sum_of_distribution=pooled_mass_all
            
        model_eligibles_getting_voucher_relative_to_pop(time_period)=&
            model_eligibles_getting_voucher(time_period)/sum_of_distribution
            
        if (current_beta_type==number_of_beta_types) then
            model_homeowners_experimenting(time_period)=&
                model_homeowners_experimenting(time_period)/max(model_homeownership_rate(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_experimenters_getting_voucher(time_period)=&
                model_experimenters_getting_voucher(time_period)/max(model_eligibles_getting_voucher(time_period),10.d0**(-14))
        end if

        if (current_beta_type==number_of_beta_types) then
            model_drug_users_getting_voucher(time_period)=&
                model_drug_users_getting_voucher(time_period)/max(model_eligibles_getting_voucher(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_avg_income_experimenters(time_period)=&
                model_avg_income_experimenters(time_period)/max(model_exprimenters(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_avg_income_drug_users(time_period)=&
                model_avg_income_drug_users(time_period)/max(model_mass_total_users(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_avg_assets_experimenters(time_period)=&
                model_avg_assets_experimenters(time_period)/max(model_exprimenters(time_period),10.d0**(-14))
        end if
                
        if (current_beta_type==number_of_beta_types) then
            model_eligibles_getting_voucher(time_period)=&  
                model_eligibles_getting_voucher(time_period)/max(model_eligibles(time_period),10.d0**(-14))
        end if
        
        if (current_beta_type==number_of_beta_types) then
            model_unemployment_by_employment(time_period,:)=&
                model_unemployment_by_employment(time_period,:)/max(mass_by_employment_1(time_period,:),10.d0**(-14))
        end if
        
        if (current_beta_type==number_of_beta_types) then
            addiction_rate_by_age(time_period,:)=&
                addiction_rate_by_age(time_period,:)/max(mass_by_age(time_period,:),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            homeless_and_addiction_rate_by_age(time_period,:)=&
                homeless_and_addiction_rate_by_age(time_period,:)/max(mass_by_age(time_period,:),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_fraction_choose_addiction_when_unemployed(time_period)=&
                model_fraction_choose_addiction_when_unemployed(time_period)/max(model_mass_choose_addiction(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_choose_addiction_when_income_is_low(time_period)=&
                model_choose_addiction_when_income_is_low(time_period)/max(model_mass_choose_addiction(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_fraction_choose_addiction_when_homeless(time_period)=&
                model_fraction_choose_addiction_when_homeless(time_period)/max(model_mass_choose_addiction(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_choose_addiction_when_retired(time_period)=&
                model_choose_addiction_when_retired(time_period)/max(model_mass_choose_addiction(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_fraction_choose_addiction(time_period)=&
                model_fraction_choose_addiction(time_period)/max(model_mass_choose_addiction(time_period),10.d0**(-14))
        end if
        
        if (current_beta_type==number_of_beta_types) then
            model_average_spent_on_addiction_by_addicted(time_period)=&
                model_average_spent_on_addiction_by_addicted(time_period)/total_addited_1
        end if
        
        do employment_index=1,employment_grid_size
        
            ! GUARDED for the same reason as the profile below it.
            if (employment_mass(time_period,employment_index)>10.d0**(-12)) then

                if (current_beta_type==number_of_beta_types) then
                    addiction_share_of_income_by_employment(time_period,employment_index)=&
                        addiction_share_of_income_by_employment(time_period,employment_index)/&
                        max(employment_mass(time_period,employment_index),10.d0**(-14))
                end if

            else

                if (accumulating_beta_types==0) addiction_share_of_income_by_employment(time_period,employment_index)=0

            end if
                
            ! THE DISORDER RATE AT A PRODUCTIVITY NODE is the mass with the
            ! disorder there over the WHOLE population there, so the denominator
            ! is total_mass_by_employment. mass_by_employment is accumulated
            ! inside the block only households with the disorder reach, so
            ! dividing by it returned a share of the disordered rather than a
            ! rate, and the profile it produced was near one at every node with
            ! anyone on it and zero elsewhere. delta_d is calibrated on a ratio
            ! of two averages of this profile, so it was chasing a statistic
            ! that could not respond to the penalty.
            !
            ! The guard stays: a node with no population is 0/0, and zero is
            ! also right on its own terms, since no one there can carry the
            ! disorder.
            if (total_mass_by_employment(time_period,employment_index)>10.d0**(-12)) then

                if (current_beta_type==number_of_beta_types) then
                    percent_addicted_by_employment(time_period,employment_index)=&
                        percent_addicted_by_employment(time_period,employment_index)/&
                        max(total_mass_by_employment(time_period,employment_index),10.d0**(-14))
                end if

                if (current_beta_type==number_of_beta_types) then
                    percent_homeless_by_employment(time_period,employment_index)=&
                        percent_homeless_by_employment(time_period,employment_index)/&
                        max(total_mass_by_employment(time_period,employment_index),10.d0**(-14))
                end if

            else

                if (accumulating_beta_types==0) percent_addicted_by_employment(time_period,employment_index)=0
                if (accumulating_beta_types==0) percent_homeless_by_employment(time_period,employment_index)=0

            end if

            ! The flow onset rate at this node, and the drug quantity and total
            ! consumption behind it. Dividing quantity by consumption gives the
            ! DRUG BUDGET SHARE, which is the number that says whether the
            ! gradient is a preference or a deterrence result: with homothetic
            ! preferences and a cost of the disorder proportional to income the
            ! share is constant by construction, so a flat share means no force
            ! in the model is tilting use against income.
            if (clean_mass_by_employment(time_period,employment_index)>10.d0**(-12)) then

                if (current_beta_type==number_of_beta_types) then
                    drug_quantity_by_employment(time_period,employment_index)=&
                        drug_quantity_by_employment(time_period,employment_index)/&
                        max(clean_mass_by_employment(time_period,employment_index),10.d0**(-14))
                end if

                if (current_beta_type==number_of_beta_types) then
                    onset_hazard_by_employment(time_period,employment_index)=&
                        onset_hazard_by_employment(time_period,employment_index)/&
                        max(clean_mass_by_employment(time_period,employment_index),10.d0**(-14))
                end if

                if (current_beta_type==number_of_beta_types) then
                    clean_consumption_by_employment(time_period,employment_index)=&
                        clean_consumption_by_employment(time_period,employment_index)/&
                        max(clean_mass_by_employment(time_period,employment_index),10.d0**(-14))
                end if

            else

                if (accumulating_beta_types==0) drug_quantity_by_employment(time_period,employment_index)=0
                if (accumulating_beta_types==0) onset_hazard_by_employment(time_period,employment_index)=0
                if (accumulating_beta_types==0) clean_consumption_by_employment(time_period,employment_index)=0

            end if
            
        end do
        
        if (current_beta_type==number_of_beta_types) then
            model_average_assets_homeless_by_addiction(time_period,:)=model_average_assets_homeless_by_addiction(time_period,:)/&
                max(model_mass_by_homeless_and_addiction(time_period,:),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_average_income_homeless_by_addiction(time_period,:)=model_average_income_homeless_by_addiction(time_period,:)/&
                max(model_mass_by_homeless_and_addiction(time_period,:),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_average_income_addicted(time_period)=&
                model_average_income_addicted(time_period)/total_addited_1
        end if
                                        
        if (current_beta_type==number_of_beta_types) then
            model_average_assets_addicted(time_period)=&
                model_average_assets_addicted(time_period)/total_addited_1
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_average_assets_drug_users(time_period)=&
                model_average_assets_drug_users(time_period)/max(model_mass_total_users(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_age_by_addiction(time_period,:)=&
                model_age_by_addiction(time_period,:)/max(model_mass_age_by_addiction(time_period,:),10.d0**(-14))
        end if
                
        if (current_beta_type==number_of_beta_types) then
            model_fraction_addicted_homeless_no_vouchers(time_period)=&
                model_fraction_addicted_homeless_no_vouchers(time_period)/total_homeless_1
        end if
        
        if (current_beta_type==number_of_beta_types) then
            model_fraction_spent_on_addiction(time_period)=&
                model_fraction_spent_on_addiction(time_period)/total_addited_1
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_fraction_spent_on_addiction_experimenters(time_period)=&
                model_fraction_spent_on_addiction_experimenters(time_period)/max(model_exprimenters(time_period),10.d0**(-14))
        end if
                        
        if (current_beta_type==number_of_beta_types) then
            model_fraction_homeless_by_choice(time_period)=&
                model_fraction_homeless_by_choice(time_period)/total_homeless_1
        end if

        if (current_beta_type==number_of_beta_types) then
            val_homeless_afford_on_income(time_period)=&
                val_homeless_afford_on_income(time_period)/max(total_homeless_1,10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_addicted_and_homeless_by_choice(time_period)=&
                model_addicted_and_homeless_by_choice(time_period)/total_addicted_and_homeless_1
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_average_income_of_homeless_addicted(time_period)=&
                model_average_income_of_homeless_addicted(time_period)/total_addicted_and_homeless_1
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_avg_homeless_income(time_period)=&
                model_avg_homeless_income(time_period)/total_homeless_1
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_avg_homeless_after_tax_income(time_period)=&
                model_avg_homeless_after_tax_income(time_period)/total_homeless_1
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_avg_homeless_tax_to_income(time_period)=&
                model_avg_homeless_tax_to_income(time_period)/total_homeless_1
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_avg_homeless_assets(time_period)=&
                model_avg_homeless_assets(time_period)/total_homeless_1
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_average_assets_addicted_and_homeless(time_period)=&
                model_average_assets_addicted_and_homeless(time_period)/total_addicted_and_homeless_1
        end if
                    
        if ((time_period==1) .AND. (solve_transition_dynamics==1)) then
        
            do age_index=1,life_span
            
                if (age_index>(life_span-retirement_span)) then
                
                    in_retirement=1
                    
                else
                
                    in_retirement=0
                    
                end if
                                            
                do years_left_on_mortgage_index=1,max_amortization_years
                                
                    if (years_left_on_mortgage_index>1) then
                                    
                        has_house=1
                        
                    else
                    
                        has_house=0
                        
                    end if
                    
                    do unemployment_index=1,unemployment_grid_size
                    
                        do employment_index=1,employment_grid_size
                        
                            do voucher_index=0,(1-has_house)*include_vouchers
                           
                                do financial_index=has_house*1+(1-has_house)*renter_floor_by_age(min(max(age_index,1),life_span)),financial_grid_size
                                                   
                                    do housing_status_index=(1-has_house)*lowest_housing_grid_point+&
                                        has_house*index_of_smallest_house_hhld_can_buy,housing_status_grid_size-1
                                                                                                                                        
                                        lived_in_size_used=&
                                            policy_function_space_lived_in_size_to_fetch(years_left_on_mortgage_index)%&
                                            vector_real(age_index,financial_index,unemployment_index,&
                                            employment_index,housing_status_index,voucher_index)
                                                                              
                                        distribution_mass_used=distribution_to_fetch(years_left_on_mortgage_index)%&
                                            vector_real(age_index,financial_index,unemployment_index,&
                                            employment_index,housing_status_index,voucher_index)
                                            
                                        if (housing_status_index>=second_lowest_housing_grid_point) then
                                                                                                                                                                    
                                            govt_revenues_from_property_tax(time_period)=&
                                                govt_revenues_from_property_tax(time_period)+&
                                                property_tax(time_period)*housing_price(time_period)*&
                                                lived_in_size_used*distribution_mass_used
                                                                                              
                                        end if
                                                                               
                                    end do
                                    
                                end do
                                    
                            end do
                            
                        end do
                                                                       
                    end do
            
                end do
                
            end do

        end if
        
        sum_of_distribution=0
        
        do i=1,2
                
            sum_of_distribution=sum_of_distribution+&
                sum(distribution_stationary(i)%vector_transition_real(time_period,:,:,:,:,:,:))
            
        end do

        ! POOLED MASS, NOT ONE TYPE'S. The histograms and every other
        ! accumulator above hold both discount-factor types once the
        ! benchmark chain has run twice, so a denominator recomputed from
        ! distribution_stationary -- which holds only the type just solved --
        ! is short by exactly the number of passes. Scale it up.
        ! POOLED MASS, READ NOT REBUILT. stationary_equilibrium_statistics runs
        ! FIRST in every pass and has already added this type's mass, so the
        ! total here is the real pooled mass rather than one type's scaled by a
        ! pass count. The types do not weigh the same; see pooled_mass_all.
        sum_of_distribution=pooled_mass_all
        
        if (current_beta_type==number_of_beta_types) then
            model_drug_use_percent_by_age_group(time_period,:)=&
                model_drug_use_percent_by_age_group(time_period,:)/sum_of_distribution
        end if
        
        if (current_beta_type==number_of_beta_types) model_total_drug_users(time_period)=model_total_drug_users(time_period)/sum_of_distribution
        
        if (current_beta_type==number_of_beta_types) model_addicted(time_period)=model_addicted(time_period)/sum_of_distribution
        
        if (current_beta_type==number_of_beta_types) model_exprimenters(time_period)=model_exprimenters(time_period)/sum_of_distribution
        
        fraction_using_MID(time_period)=fraction_using_MID(time_period)/sum_of_distribution
                   
        model_average_labour_income_tax(time_period)=&
            govt_revenues_from_labour_income(time_period)/(model_total_efficiency_units(time_period)+&
            model_financial(time_period)*risk_free_rate(time_period))
                     
        if (current_beta_type==number_of_beta_types) then
            model_fraction_homeless_recieving_food_stamps(time_period)=&
                model_fraction_homeless_recieving_food_stamps(time_period)/max(model_fraction_homeless(time_period),10.d0**(-14))
        end if
            
        if (current_beta_type==number_of_beta_types) then
            model_food_stamps_share_to_homeless(time_period)=&
                model_food_stamps_share_to_homeless(time_period)/max(model_fraction_homeless(time_period),10.d0**(-14))
        end if
        
        ! OWNED BY stationary_equilibrium_statistics, WHICH RUNS FIRST. Reset,
        ! accumulation and division disabled here.
        !
        ! model_fraction_homeless was reset, accumulated AND divided in two chain
        ! routines. Both resets are guarded to the first pass, so on the second
        ! pass this routine accumulated a MASS on top of the RATE the earlier one
        ! had already produced, then divided again: the value the h_1 bisection
        ! read was a 1:3 mixture over-weighting the impatient type, not the 1:1
        ! mixture the design intends. h_1 is a TARGETED moment and
        ! size_homelessness is driven by it.
        !
        ! The two routines divide by different denominators -- lowest
        ! productivities against sum_of_distribution -- but the first is
        ! accumulated for every household with no condition, so despite its name
        ! it is the same total mass. Keeping one owner is enough.
        ! if (current_beta_type==number_of_beta_types) model_fraction_homeless(time_period)=model_fraction_homeless(time_period)/sum_of_distribution
                    
        total_govt_revenues(time_period)=&
            govt_revenues_from_labour_income(time_period)+&
            govt_revenues_from_consumption(time_period)+govt_revenues_from_investment_income(time_period)+&
            include_property_taxes_in_govt_constraint*govt_revenues_from_property_tax(time_period)-&
            govt_lump_sum_transfers(time_period)
            
        ! WHAT THE TESTING COSTS THE BUDGET. Under Treatment First every income
        ! eligible household has to be screened for the condition to mean
        ! anything, so the government pays cost_per_drug_test for each of them,
        ! once per period. Zero in the benchmark, where voucher_conditional_on_clean
        ! is zero, nothing is conditional and nobody is tested, so this term
        ! cannot move the calibration; it is what makes the counterfactual pay
        ! for its own enforcement rather than getting it free.
        govt_spending_on_drug_tests=voucher_conditional_on_clean*cost_per_drug_test*&
            model_eligibles_getting_voucher(time_period)/&
            max(probability_of_voucher_benchmark_used_1,10.d0**(-10))

        govt_revenues_to_use_in_tests(time_period)=&
            total_govt_revenues(time_period)-govt_spending_on_ss(time_period)-&
            govt_spending_on_ui(time_period)-govt_spending_on_di(time_period)-&
            govt_spending_on_homeless(time_period)-govt_spending_on_addicts(time_period)-&
            govt_spending_on_food_stamps(time_period)-govt_spending_on_housing_vouchers(time_period)-&
            govt_spending_on_housing_vouchers_2(time_period)-govt_spending_on_drug_tests+&
            (1-include_bequests*(1-residual_bequests_to_government))*&
            (model_bequests(time_period)-value_of_initial_assets-model_total_inheritance(time_period))
                    
        net_govt_revenues(time_period)=clear_only_vouchers_govt_budget*(-govt_spending_on_housing_vouchers_2(time_period))+&
            (1-clear_only_vouchers_govt_budget)*govt_revenues_to_use_in_tests(time_period)
        
        net_govt_revenues(time_period)=net_govt_revenues(time_period)+&
            include_bequests_in_govt_constraint*model_bequests(time_period)
                            
        if (solve_transition_dynamics==0) then
                
            write(*,*) "net_govt_revenues=", net_govt_revenues(time_period)
            
        end if
    
    end subroutine
            
    subroutine calculate_household_housing_spending(time_period)
    
        use Global_Vars
        
        implicit none
        
        integer :: financial_index,pay_mortgage_insurance_1,low_quality_market
        integer, intent(in) :: time_period
        integer :: has_house,time_period_used,amortization_used,financial_index_used,&
            housing_status_index_used,addiction_used_1
        real(8) :: total_income,mass_of_renters_1,labor_supply_used,distribution_mass_used,lived_in_size_used,&
            avg_income_to_use_1,avg_income_to_use_2,housing_voucher_2
        real(8) :: val_hous_outlay_1,val_total_expend_1,val_total_consumption_1

        ! STATIC STORAGE, BECAUSE THESE ACCUMULATE ACROSS THE TWO PASSES.
        !
        ! Each of these is reset only when accumulating_beta_types is zero,
        ! which is the first pass, and added to on every pass. That is the
        ! right shape for a counter that has to hold both discount-factor
        ! types -- but it is only correct if the value survives from one
        ! call to the next, and a local without save does not. On the
        ! second pass the routine is entered fresh, the reset is skipped,
        ! and the accumulation lands on whatever the stack holds.
        !
        ! It has been working by accident: the calls come from the same
        ! site in the same order, so the frame is usually reused and the
        ! slot usually still holds the first pass's value. That is not a
        ! guarantee, it is a property of this build. save makes it one.
        !
        ! These stay LOCAL rather than moving to module scope on purpose.
        ! total_homeless_1 is the name of two different locals in two
        ! different routines; merging them would pool two counts of the
        ! same population into one divisor.
        save :: mass_of_renters_1
                
        avg_income_to_use_1=is_counterfactual*average_labor_income_calibrated+&
            (1-is_counterfactual)*model_average_labour_income(time_period)

        time_period_used=time_period-solve_transition_dynamics
                
        if (accumulating_beta_types==0) mass_of_renters_at_housing_spending(time_period,:)=0
        if (accumulating_beta_types==0) mass_of_homeowners_at_housing_spending(time_period,:)=0
        
        if (accumulating_beta_types==0) model_rent_burden_by_age(time_period,:,:)=0
        ! ONE OWNER PER VARIABLE. Reset and accumulation disabled here.
        !
        ! Every reset in the chain is guarded to the FIRST pass, which is safe only
        ! if exactly one routine owns the variable. Where two or more each reset and
        ! each accumulate, the guard that stops pass two resetting also lets each
        ! routine start from whatever the previous one left, so the second pass adds
        ! another copy of the second type on top of a finished total. Four owners of
        ! mass_by_employment made it 5*M where the pooled mass is 2*M, so every
        ! welfare-by-employment average was halved and homeownership_by_employment
        ! came out at 0.4 times truth.
        !
        ! It is the same quantity in every owner, so the FIRST in call order keeps
        ! it and the rest read it. The order is the same in the driver and in
        ! long_run_counter_factual, so the value is always built before it is read.
        ! if (accumulating_beta_types==0) mass_renters_by_age(time_period,:)=0
        
        if (accumulating_beta_types==0) mass_of_renters_1=0
        if (accumulating_beta_types==0) val_burden50_by_unit(time_period,:)=0
        if (accumulating_beta_types==0) val_mass_by_unit(time_period,:)=0

        if (accumulating_beta_types==0) val_burden50_expend_all(time_period)=0
        if (accumulating_beta_types==0) val_mass_expend_all(time_period)=0
        if (accumulating_beta_types==0) val_burden50_expend_housed(time_period)=0
        if (accumulating_beta_types==0) val_mass_expend_housed(time_period)=0
        if (accumulating_beta_types==0) val_hous_expend_num(time_period)=0
        if (accumulating_beta_types==0) val_hous_expend_den(time_period)=0

        if (accumulating_beta_types==0) val_voucher_mass(time_period)=0
        if (accumulating_beta_types==0) val_voucher_rent(time_period)=0
        if (accumulating_beta_types==0) val_voucher_income(time_period)=0
        if (accumulating_beta_types==0) val_voucher_wage_led(time_period)=0
        
        do age_index=1,life_span
        
            if (age_index>(life_span-retirement_span)) then
            
                in_retirement=1
                
            else
            
                in_retirement=0
                
            end if
                
            if (age_index==1) then
            
                newborn_household=1
                
            else
            
                newborn_household=0
            
            end if
        
            do years_left_on_mortgage_index=1,max_amortization_years
                            
                if (years_left_on_mortgage_index>1) then
                    
                    has_house=1
                    
                else
                
                    has_house=0
                    
                end if
                                                                                
                do unemployment_index=1,unemployment_grid_size
                
                    do employment_index=1,employment_grid_size
                    
                        do voucher_index=0,(1-has_house)*include_vouchers

                            avg_income_to_use_2=is_counterfactual*average_labor_income_by_employment_calibrated(employment_index)+&
                                (1-is_counterfactual)*model_average_labour_income_by_employment(time_period,employment_index)
                                                            
                            do financial_index=has_house*1+(1-has_house)*renter_floor_by_age(min(max(age_index,1),life_span)),financial_grid_size
                    
                                do housing_status_index=(1-has_house)*lowest_housing_grid_point+&
                                    has_house*index_of_smallest_house_hhld_can_buy,housing_status_grid_size-1
                                                            
                                    lived_in_size_used=policy_function_space_lived_in_size(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                    
                                    amortization_used=policy_function_years_of_amortization_index(years_left_on_mortgage_index)%&
                                        vector_transition_integer(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                
                                    financial_index_used=policy_function_financial_index(years_left_on_mortgage_index)%&
                                        vector_transition_integer(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    housing_status_index_used=policy_function_housing_status_index(years_left_on_mortgage_index)%&
                                        vector_transition_integer(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    labor_supply_used=policy_function_labor_supply(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    addiction_used_1=policy_function_addiction(years_left_on_mortgage_index)%&
                                        vector_transition_integer(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                                                            
                                    distribution_mass_used=distribution_stationary(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period_used,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)  
                                        
                                    if ((housing_status_index_used>second_lowest_housing_grid_point) .OR. &
                                       (have_two_rental_markets==0)) then
                                    
                                        low_quality_market=0
                                    
                                    else
                                    
                                        low_quality_market=1
                                    
                                    end if
                                                                                                        
                                    ! THE HOMELESS WERE IN THIS DENOMINATOR AND COULD NEVER
                                    ! BE IN THE NUMERATOR, which is the third instance of that
                                    ! fault found today. The burdened count above requires
                                    ! housing_status_index_used >= second_lowest, so a homeless
                                    ! household adds mass below the line and nothing above it.
                                    !
                                    ! At a homelessness rate of 0.27 per cent the bias was 0.3
                                    ! per cent and harmless. It stops being harmless now that
                                    ! h_2 is a TARGET and the mechanism proposed for hitting it
                                    ! is to push households onto the street: every one that
                                    ! goes would inflate this denominator and drop h_2 with no
                                    ! household's burden changing, so the target would appear to
                                    ! be met by the very move that was supposed to earn it.
                                    !
                                    ! SCF's universe is renters paying rent, and the homeless
                                    ! are not in SCF at all, so excluding them is also what
                                    ! matches the 10.1 per cent this is calibrated to.
                                    if ((amortization_used<=1) .AND. &
                                        (housing_status_index_used>=second_lowest_housing_grid_point)) then
                                    
                                        mass_of_renters_1=mass_of_renters_1+distribution_mass_used

                                        val_mass_by_unit(time_period,housing_status_index_used)=&
                                            val_mass_by_unit(time_period,housing_status_index_used)+&
                                            distribution_mass_used
                                    
                                    end if
                                    
                                    call calculate_income(unemployment_index,employment_index,total_income,&
                                        avg_income_to_use_1,avg_income_to_use_2,labor_supply_used,in_retirement)
                                             
                                    total_income=total_income+(risk_free_rate(time_period)*max(financial_grid(financial_index),0.d0)+unsecured_borrowing_rate*min(financial_grid(financial_index),0.d0))
                                    
                                    housing_voucher_2=0
                                    
                                    if ((total_income<threshold_income_vouchers*((1-is_counterfactual)*median_income(time_period)+&
                                        is_counterfactual*median_income_calibrated)) .AND. (include_vouchers==1)) then

                                        if ((years_left_on_mortgage_index==1) .AND. (amortization_used==1) .AND. &
                                            (voucher_index==1)) then
                                                                                                            
                                            call calculate_housing_voucher_2(housing_voucher_2,addiction_used_1,total_income,&
                                                rent(time_period,low_quality_market)*lived_in_size_used,time_period)
                                        
                                        end if
                                        
                                    end if

                                    ! THE TWO PICTURE OF SUBSIDIZED HOUSEHOLDS
                                    ! ROWS, and the universe is households that
                                    ! actually draw a voucher rather than ones
                                    ! that hold the eligibility index, since a
                                    ! household above the income threshold or in
                                    ! a unit the voucher does not cover receives
                                    ! nothing and is not in HUD's file either.
                                    if (housing_voucher_2>0) then

                                        val_gross_rent_1=rent(time_period,low_quality_market)*lived_in_size_used

                                        val_labour_income_1=0
                                        if ((in_retirement==0) .AND. (emp_of(unemployment_index)==1)) then
                                            val_labour_income_1=labor_supply_used*&
                                                employment_grid(age_index,employment_index)*&
                                                labour_deterministic_efficiency(age_index)
                                        end if

                                        val_voucher_mass(time_period)=val_voucher_mass(time_period)+&
                                            distribution_mass_used

                                        ! THE TENANT CONTRIBUTION RATE, as an
                                        ! aggregate of rent over an aggregate of
                                        ! income, because HUD's 31.2 per cent is
                                        ! a mean monthly tenant rent over a mean
                                        ! annual income and not a mean of ratios.
                                        val_voucher_rent(time_period)=val_voucher_rent(time_period)+&
                                            max(val_gross_rent_1-housing_voucher_2,0.d0)*distribution_mass_used

                                        val_voucher_income(time_period)=val_voucher_income(time_period)+&
                                            total_income*distribution_mass_used

                                        ! WAGES AS THE MAIN INCOME. Income here
                                        ! is wages, or a transfer, plus interest
                                        ! on positive balances, so main means
                                        ! more than half and nothing subtler is
                                        ! available to mean.
                                        if (val_labour_income_1>0.5d0*total_income) then
                                            val_voucher_wage_led(time_period)=val_voucher_wage_led(time_period)+&
                                                distribution_mass_used
                                        end if

                                    end if

                                    if ((amortization_used<=1) .AND. &
                                        (housing_status_index_used>=second_lowest_housing_grid_point)) then
                                        
                                        fraction_of_income_spent_on_housing=&
                                            (rent(time_period,low_quality_market)*lived_in_size_used-housing_voucher_2)
                                                                
                                    elseif (amortization_used>1) then
                                              
                                        if ((-min(financial_grid(financial_index_used),0.d0)>(1-minimum_downpayment)) .AND. &
                                            (financial_grid(financial_index_used)<0)) then
                                                                        
                                            pay_mortgage_insurance_1=1
                                        
                                        else
                                    
                                            pay_mortgage_insurance_1=0
                                        
                                        end if
                                                                         
                                        fraction_of_income_spent_on_housing=&
                                            housing_price(time_period)*lived_in_size_used*&
                                            ((-financial_grid(min(financial_index_used,negative_financial_grid_size))*&
                                            (pay_mortgage_insurance_1*mortgage_insurance_premium+&
                                            mortgage_interest_rate(time_period)+average_fraction_of_mortgage_repaid))+&
                                            (property_tax(time_period-solve_transition_dynamics)+&
                                            include_housing_depreciation_in_housing_costs*housing_depreciation_rate))
                                                                                                                                                                                                                                                                                    
                                    end if
                                    
                                    ! THE EXPENDITURE DENOMINATOR, TAKEN BEFORE THE INCOME ONE
                                    ! OVERWRITES THE OUTLAY.
                                    !
                                    ! fraction_of_income_spent_on_housing holds the housing OUTLAY
                                    ! at this point and is divided by income three lines below, so
                                    ! the expenditure version has to be formed here or not at all.
                                    ! The outlay is recomputed rather than read off that variable
                                    ! because a household that is homeless satisfies neither branch
                                    ! above and would inherit the previous state's number.
                                    !
                                    ! Expenditure is the model's own: total consumption, which
                                    ! already carries drug spending, plus the housing outlay. The
                                    ! outlay is NET of the voucher, which is what the household pays
                                    ! and what a consumer unit reports.
                                    !
                                    ! ALL households and HOUSED households are both accumulated.
                                    ! The universe asked for is all households; CEX consumer units
                                    ! are housed, so the two differ by the homelessness rate and the
                                    ! difference should be stated rather than chosen silently.
                                    val_total_consumption_1=&
                                        policy_function_total_consumption(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)

                                    val_hous_outlay_1=0
                                    if ((amortization_used<=1) .AND. &
                                        (housing_status_index_used>=second_lowest_housing_grid_point)) then
                                        val_hous_outlay_1=max(rent(time_period,low_quality_market)*&
                                            lived_in_size_used-housing_voucher_2,0.d0)
                                    elseif (amortization_used>1) then
                                        val_hous_outlay_1=fraction_of_income_spent_on_housing
                                    end if

                                    val_total_expend_1=val_total_consumption_1+val_hous_outlay_1

                                    val_mass_expend_all(time_period)=val_mass_expend_all(time_period)+&
                                        distribution_mass_used
                                    val_hous_expend_num(time_period)=val_hous_expend_num(time_period)+&
                                        val_hous_outlay_1*distribution_mass_used
                                    val_hous_expend_den(time_period)=val_hous_expend_den(time_period)+&
                                        val_total_expend_1*distribution_mass_used

                                    if (val_hous_outlay_1>0.5d0*max(val_total_expend_1,10.d0**(-14))) then
                                        val_burden50_expend_all(time_period)=&
                                            val_burden50_expend_all(time_period)+distribution_mass_used
                                    end if

                                    if (housing_status_index_used>=second_lowest_housing_grid_point) then
                                        val_mass_expend_housed(time_period)=&
                                            val_mass_expend_housed(time_period)+distribution_mass_used
                                        if (val_hous_outlay_1>0.5d0*max(val_total_expend_1,10.d0**(-14))) then
                                            val_burden50_expend_housed(time_period)=&
                                                val_burden50_expend_housed(time_period)+distribution_mass_used
                                        end if
                                    end if

                                    if (total_income==0) then
                                    
                                        fraction_of_income_spent_on_housing=1
                                    
                                    else
                                        
                                        fraction_of_income_spent_on_housing=fraction_of_income_spent_on_housing/max(total_income,10.d0**(-14))
                                        
                                    end if
                                                
                                    frac_of_inc_spent_on_hous_threshold(time_period,1)=0.3
                                    frac_of_inc_spent_on_hous_threshold(time_period,2)=0.5
                                    frac_of_inc_spent_on_hous_threshold(time_period,3)=0.75
                                    frac_of_inc_spent_on_hous_threshold(time_period,4)=1 
                                            
                                    if ((amortization_used<=1) .AND. &
                                       (housing_status_index_used>=second_lowest_housing_grid_point)) then
                                                                                    
                                        do i=1,number_of_thresholds
                                                
                                            if (fraction_of_income_spent_on_housing>&
                                                frac_of_inc_spent_on_hous_threshold(time_period,i)) then
                                                            
                                                mass_of_renters_at_housing_spending(time_period,i)=&
                                                    mass_of_renters_at_housing_spending(time_period,i)+distribution_mass_used

                                                if (i==2) then
                                                    val_burden50_by_unit(time_period,housing_status_index_used)=&
                                                        val_burden50_by_unit(time_period,housing_status_index_used)+&
                                                        distribution_mass_used
                                                end if
                                                    
                                                model_rent_burden_by_age(time_period,age_index,i)=&
                                                    model_rent_burden_by_age(time_period,age_index,i)+distribution_mass_used
                                                                                                    
                                            end if
                                                            
                                        end do
                                                                                                                
                                        ! ONE OWNER PER VARIABLE. Reset and accumulation disabled here.
                                        !
                                        ! Every reset in the chain is guarded to the FIRST pass, which is safe only
                                        ! if exactly one routine owns the variable. Where two or more each reset and
                                        ! each accumulate, the guard that stops pass two resetting also lets each
                                        ! routine start from whatever the previous one left, so the second pass adds
                                        ! another copy of the second type on top of a finished total. Four owners of
                                        ! mass_by_employment made it 5*M where the pooled mass is 2*M, so every
                                        ! welfare-by-employment average was halved and homeownership_by_employment
                                        ! came out at 0.4 times truth.
                                        !
                                        ! It is the same quantity in every owner, so the FIRST in call order keeps
                                        ! it and the rest read it. The order is the same in the driver and in
                                        ! long_run_counter_factual, so the value is always built before it is read.
                                        ! mass_renters_by_age(time_period,age_index)=mass_renters_by_age(time_period,age_index)+&
                                        ! distribution_mass_used
                                                 
                                    elseif (amortization_used>1) then
                                                                                                                                    
                                        do i=1,number_of_thresholds    
                                                    
                                            if (fraction_of_income_spent_on_housing>&
                                                frac_of_inc_spent_on_hous_threshold(time_period,i)) then
                                                            
                                                mass_of_homeowners_at_housing_spending(time_period,i)=&
                                                    mass_of_homeowners_at_housing_spending(time_period,i)+distribution_mass_used
                                                            
                                            end if
                                            
                                        end do
                                                                                          
                                    end if
                                    
                                end do
                            
                            end do
                            
                        end do
                        
                    end do
                                                            
                end do
        
            end do
            
        end do
        
        do age_index=1,life_span
        
            do i=1,number_of_thresholds
        
                if (current_beta_type==number_of_beta_types) then
                    model_rent_burden_by_age(time_period,age_index,i)=&
                        model_rent_burden_by_age(time_period,age_index,i)/mass_renters_by_age(time_period,age_index)
                end if
                    
            end do
        
        end do
        
        if (solve_transition_dynamics==1) then
        
            open(unit=1,file="percentage_spending_on_housing"//trim(file_number)//".txt",action="write",status="replace")
                
        else
        
            open(unit=1,file="percentage_spending_on_housing"//trim(file_number)//".txt",action="write",status="replace")
        
        end if
        
        do i=1,number_of_thresholds
        
            if (current_beta_type==number_of_beta_types) then
                mass_of_renters_at_housing_spending(time_period,i)=&
                    mass_of_renters_at_housing_spending(time_period,i)/mass_of_renters_1
            end if
                
            if (current_beta_type==number_of_beta_types) then
                mass_of_homeowners_at_housing_spending(time_period,i)=&
                    mass_of_homeowners_at_housing_spending(time_period,i)/mass_of_owners_with_mortgage(time_period)
            end if
                
            if (solve_transition_dynamics==0) then
            
                if (i<=number_of_thresholds) then
                
                    if (i<=2) then
                
                        write(*,*) "percentage of renters spending more than ", &
                            frac_of_inc_spent_on_hous_threshold(time_period,i)," on their income on housing=",&
                            mass_of_renters_at_housing_spending(time_period,i)
                            
                        write(*,*) "percentage of homeowners with a mortgage spending more than ", &
                            frac_of_inc_spent_on_hous_threshold(time_period,i)," on their income on housing=",&
                            mass_of_homeowners_at_housing_spending(time_period,i)
                            
                    end if
                        
                end if
                    
            end if
                                            
            write(1,*) "percentage of renters spending more than ", &
                frac_of_inc_spent_on_hous_threshold(time_period,i)," on their income on housing=",&
                mass_of_renters_at_housing_spending(time_period,i)
            write(1,*) "percentage of homeowners with a mortgage spending more than ", &
                frac_of_inc_spent_on_hous_threshold(time_period,i)," on their income on housing=",&
                mass_of_homeowners_at_housing_spending(time_period,i)
                                
        end do
        
        close(1)
                
    end subroutine
           
    subroutine calculate_welfare(time_period)
    
        use Global_Vars
    
        implicit none
        
        integer :: financial_index,age_index_1
        integer, intent(in) :: time_period
        integer :: has_house,time_period_used
        real(8) :: distribution_mass_used,value_function_used,labor_supply_used,income_1,&
            avg_income_to_use_1,avg_income_to_use_2
                
        avg_income_to_use_1=is_counterfactual*average_labor_income_calibrated+&
            (1-is_counterfactual)*model_average_labour_income(time_period)
        
        age_index_1=1
                
        time_period_used=time_period-solve_transition_dynamics
        
        if (accumulating_beta_types==0) average_welfare_of_all_cohorts(time_period)=0
        if (accumulating_beta_types==0) average_welfare_of_youngest_cohort(time_period)=0
        if (accumulating_beta_types==0) average_welfare_of_youngest_by_quintile(time_period,:)=0
        if (accumulating_beta_types==0) population_by_quintile(time_period,:)=0
        
        do age_index=1,life_span
        
            if (age_index>(life_span-retirement_span)) then
            
                in_retirement=1
                
            else
            
                in_retirement=0
                
            end if
                                    
            do years_left_on_mortgage_index=1,max_amortization_years
            
                if (years_left_on_mortgage_index>1) then
                    
                    has_house=1
                    
                else
                
                    has_house=0
                    
                end if
                
                do unemployment_index=1,unemployment_grid_size
                
                    do employment_index=1,employment_grid_size
                    
                        do voucher_index=0,(1-has_house)*include_vouchers
                    
                            avg_income_to_use_2=is_counterfactual*average_labor_income_by_employment_calibrated(employment_index)+&
                                (1-is_counterfactual)*model_average_labour_income_by_employment(time_period,employment_index)
                                                            
                            do financial_index=has_house*1+(1-has_house)*renter_floor_by_age(min(max(age_index,1),life_span)),financial_grid_size
                                               
                                do housing_status_index=(1-has_house)*lowest_housing_grid_point+&
                                    has_house*index_of_smallest_house_hhld_can_buy,housing_status_grid_size-1
                                                                    
                                    labor_supply_used=policy_function_labor_supply(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                                                    
                                    value_function_used=value_function(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                                                                                      
                                    distribution_mass_used=distribution_stationary(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period_used,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                    
                                    call calculate_income(unemployment_index,employment_index,income_1,&
                                        avg_income_to_use_1,avg_income_to_use_2,labor_supply_used,in_retirement)
                                    
                                    income_1=income_1+max(financial_grid(financial_index),0.d0)*risk_free_rate(time_period)
                                                                    
                                    average_welfare_of_all_cohorts(time_period)=average_welfare_of_all_cohorts(time_period)+&
                                        value_function_used*distribution_mass_used
                                                                                        
                                    if (age_index==1) then
                                    
                                        if ((time_period==2) .AND. (value_function_used==large_negative_num)) then
                                            
                                            if (distribution_mass_used>0) then
                                                
                                                write(*,*) "odd"
                                                
                                            end if
                                            
                                        end if
                                        
                                        if (distribution_mass_used>0) then
                                        
                                            if (value_function_used==large_negative_num) then
                                        
                                                write(*,*) "stuck"
                                                write(*,*) "years_left_on_mortgage_index=",years_left_on_mortgage_index
                                                write(*,*) "age_index=", age_index
                                                write(*,*) "financial_index=", financial_index
                                                write(*,*) "unemployment_index=", unemployment_index
                                                write(*,*) "employment_index=", employment_index
                                                write(*,*) "housing_status_index=", housing_status_index
                                                
                                            end if
                                    
                                            average_welfare_of_youngest_cohort(time_period)=&
                                                average_welfare_of_youngest_cohort(time_period)+&
                                                value_function_used*distribution_mass_used
                                                
                                            i=number_of_quintiles
                                            
                                            quintile_loop: do k=1,number_of_quintiles-1
                                            
                                                if (income_1<=income_cutoffs_of_quintiles(k)) then
                                            
                                                    i=k
                                                    
                                                    exit quintile_loop
                                                
                                                end if
                                            
                                            end do quintile_loop
                                                                                            
                                            population_by_quintile(time_period,i)=population_by_quintile(time_period,i)+&
                                                distribution_mass_used
                                            
                                            average_welfare_of_youngest_by_quintile(time_period,i)=&
                                                average_welfare_of_youngest_by_quintile(time_period,i)+&
                                                value_function_used*distribution_mass_used
                                                                                                                                          
                                        end if
                                                                                
                                    end if
                                    
                                end do
                                
                            end do
                            
                        end do
                        
                    end do
                        
                end do
            
            end do
            
        end do     
        
        do i=1,number_of_quintiles
        
            if (current_beta_type==number_of_beta_types) then
                average_welfare_of_youngest_by_quintile(time_period,i)=&
                    average_welfare_of_youngest_by_quintile(time_period,i)/population_by_quintile(time_period,i)
            end if
                
        end do
        
        sum_of_distribution=0
        
        do i=1,2
                
            sum_of_distribution=sum_of_distribution+&
                sum(distribution_stationary(i)%vector_transition_real(time_period,:,:,:,:,:,:))
            
        end do

        ! POOLED MASS, NOT ONE TYPE'S. The histograms and every other
        ! accumulator above hold both discount-factor types once the
        ! benchmark chain has run twice, so a denominator recomputed from
        ! distribution_stationary -- which holds only the type just solved --
        ! is short by exactly the number of passes. Scale it up.
        ! POOLED MASS, READ NOT REBUILT. stationary_equilibrium_statistics runs
        ! FIRST in every pass and has already added this type's mass, so the
        ! total here is the real pooled mass rather than one type's scaled by a
        ! pass count. The types do not weigh the same; see pooled_mass_all.
        sum_of_distribution=pooled_mass_all
        
        sum_of_distribution_youngest=0
                
        do i=1,2
                
            sum_of_distribution_youngest=sum_of_distribution_youngest+&
                sum(distribution_stationary(i)%vector_transition_real(time_period,1,:,:,:,:,:))
            
        end do

        ! POOLED MASS, NOT ONE TYPE'S. The histograms and every other
        ! accumulator above hold both discount-factor types once the
        ! benchmark chain has run twice, so a denominator recomputed from
        ! distribution_stationary -- which holds only the type just solved --
        ! is short by exactly the number of passes. Scale it up.
        ! POOLED NEWBORN MASS, accumulated rather than scaled. The newborn
        ! cohorts of the two types are the same size -- differential mortality
        ! has not acted at age one -- so this agrees with the old pass-count
        ! scaling here. It is accumulated anyway, so that one rule covers every
        ! mass in the chain and none of them depends on the types weighing the
        ! same. calculate_welfare runs once per pass and owns this one.
        if (accumulating_beta_types==0) pooled_mass_youngest=0.d0
        pooled_mass_youngest=pooled_mass_youngest+sum_of_distribution_youngest
        sum_of_distribution_youngest=pooled_mass_youngest
        
        if (current_beta_type==number_of_beta_types) average_welfare_of_all_cohorts(time_period)=average_welfare_of_all_cohorts(time_period)/sum_of_distribution
        
        if (current_beta_type==number_of_beta_types) average_welfare_of_youngest_cohort(time_period)=average_welfare_of_youngest_cohort(time_period)/sum_of_distribution_youngest
            
        if (solve_transition_dynamics==0) then
        
            write(*,*) "average_welfare_of_youngest_cohort=", average_welfare_of_youngest_cohort(time_period)
            write(*,*) "average_welfare_of_all_cohorts=", average_welfare_of_all_cohorts(time_period)
            
        end if
        
    end subroutine
    
    subroutine calculate_welfare_by_characteristics(time_period)
    
        use Global_Vars
    
        implicit none
        
        integer :: financial_index,l,time_period_used,employment_index_to_use,index_addiction_1,low_quality_market
        integer, intent(in) :: time_period
        integer :: has_house,amortization_used,financial_index_used,housing_status_index_used,is_homeless_1
        real(8) :: distribution_mass_used,value_function_used,MID_used,consumption_used,lived_in_size_used,labor_supply_used,&
            avg_income_to_use_1,avg_income_to_use_2,frac_spent_on_addiction_used
                
        avg_income_to_use_1=is_counterfactual*average_labor_income_calibrated+&
            (1-is_counterfactual)*model_average_labour_income(time_period)

        time_period_used=time_period-solve_transition_dynamics
                
        if (accumulating_beta_types==0) welfare_by_age(time_period,:)=0
        ! OWNED BY govt_revenues_calc, WHICH RUNS FIRST. Reset and accumulation disabled here.
        ! mass_by_age was reset AND accumulated in three routines that run in
        ! sequence inside the two-pass loop, every reset guarded to the first pass.
        ! So on pass two each routine added another copy of the second type on top
        ! of what the previous one left: govt_revenues_calc ended at M1+M2, which is
        ! correct, this routine at M1+2*M2, and calculate_homeownership_by_
        ! characteristics at M1+3*M2 -- and the last is where homelessness_by_age
        ! and homeownership_by_age are normalised, so the age profile the author is
        ! reading came out at half its true value.
        !
        ! It is the same quantity in all three, so the first owner's copy is the one
        ! to keep. The call order is govt_revenues_calc, then this, then
        ! calculate_homeownership_by_characteristics, in the driver AND in
        ! long_run_counter_factual, so the value is always built before it is read.
        ! if (accumulating_beta_types==0) mass_by_age(time_period,:)=0
        
        if (accumulating_beta_types==0) welfare_by_age_and_addiction(time_period,:,:)=0
        if (accumulating_beta_types==0) mass_by_age_and_addiciton(time_period,:,:)=0
        
        if (accumulating_beta_types==0) welfare_by_employment_and_age(time_period,:,:)=0
        if (accumulating_beta_types==0) mass_by_employment_and_age(time_period,:,:)=0
        
        if (accumulating_beta_types==0) welfare_by_employment(time_period,:)=0
        if (accumulating_beta_types==0) welfare_by_employment_youngest(time_period,:)=0
        if (accumulating_beta_types==0) welfare_by_employment_youngest_old_dist(time_period,:)=0
        ! ONE OWNER PER VARIABLE. Reset and accumulation disabled here.
        !
        ! Every reset in the chain is guarded to the FIRST pass, which is safe only
        ! if exactly one routine owns the variable. Where two or more each reset and
        ! each accumulate, the guard that stops pass two resetting also lets each
        ! routine start from whatever the previous one left, so the second pass adds
        ! another copy of the second type on top of a finished total. Four owners of
        ! mass_by_employment made it 5*M where the pooled mass is 2*M, so every
        ! welfare-by-employment average was halved and homeownership_by_employment
        ! came out at 0.4 times truth.
        !
        ! It is the same quantity in every owner, so the FIRST in call order keeps
        ! it and the rest read it. The order is the same in the driver and in
        ! long_run_counter_factual, so the value is always built before it is read.
        ! if (accumulating_beta_types==0) mass_by_employment(time_period,:)=0
        if (accumulating_beta_types==0) mass_by_employment_youngest(time_period,:)=0
        if (accumulating_beta_types==0) wealth_by_employment(time_period,:)=0
        
        if (accumulating_beta_types==0) welfare_by_addiction(time_period,:)=0
        if (accumulating_beta_types==0) welfare_by_addiction_youngest(time_period,:)=0
        if (accumulating_beta_types==0) lowest_welfare_of_addicted(time_period,:)=0
        if (accumulating_beta_types==0) mass_by_addiction(time_period,:)=0
        if (accumulating_beta_types==0) mass_by_addiction_youngest(time_period,:)=0
        
        if (accumulating_beta_types==0) welfare_by_homelessness(time_period,:)=0
        if (accumulating_beta_types==0) mass_by_homelessness(time_period,:)=0
        
        if (accumulating_beta_types==0) fraction_with_mortgage(time_period,:)=0
        if (accumulating_beta_types==0) fraction_renters_by_employment(time_period,:)=0
        if (accumulating_beta_types==0) average_age_of_homeowner(time_period,:)=0
        if (accumulating_beta_types==0) MID_share_by_employment(time_period,:)=0
        
        if (accumulating_beta_types==0) welfare_by_unemployment(time_period,:)=0
        if (accumulating_beta_types==0) mass_by_unemployment(time_period,:)=0
                
        if (accumulating_beta_types==0) mass_of_renters_by_employment(time_period,:)=0
                
        if (accumulating_beta_types==0) average_income(time_period,:)=0
        if (accumulating_beta_types==0) average_housing_costs(time_period,:)=0
        if (accumulating_beta_types==0) average_consumption(time_period,:)=0
        
        if (accumulating_beta_types==0) average_house_inheritance(time_period,:)=0
        if (accumulating_beta_types==0) average_house_non_inheritance(time_period,:)=0
        
        if (accumulating_beta_types==0) mass_inheritance(time_period,:)=0
        if (accumulating_beta_types==0) mass_non_inheritance(time_period,:)=0
        
        if (accumulating_beta_types==0) welfare_by_employment_and_tenure(time_period,:,:)=0
        if (accumulating_beta_types==0) wealth_by_employment_and_tenure(time_period,:,:)=0
        if (accumulating_beta_types==0) consumption_by_employment_and_tenure(time_period,:,:)=0
        if (accumulating_beta_types==0) housing_by_employment_and_tenure(time_period,:,:)=0
        if (accumulating_beta_types==0) mortgage_by_employment_and_tenure(time_period,:,:)=0
        if (accumulating_beta_types==0) mortgage_by_employment(time_period,:)=0
        if (accumulating_beta_types==0) mass_by_mortgage_and_employment(time_period,:)=0
        if (accumulating_beta_types==0) mass_by_employment_and_tenure(time_period,:,:)=0
        
        if (accumulating_beta_types==0) welfare_by_employment_tenure_and_age(time_period,:,:,:)=0
        if (accumulating_beta_types==0) mortgage_by_employment_tenure_and_age(time_period,:,:,:)=0
        if (accumulating_beta_types==0) mass_by_employment_tenure_and_age(time_period,:,:,:)=0
        
        if (accumulating_beta_types==0) welfare_by_ownership_status(time_period,:,:)=0
        if (accumulating_beta_types==0) mass_by_ownership_status(time_period,:,:)=0
        
        if (accumulating_beta_types==0) mortgage_to_house_value_ratio_of_owners_by_age(time_period,:)=0
        if (accumulating_beta_types==0) mass_mortgage_to_house_value_ratio_of_owners_by_age(time_period,:)=0
        
        if (accumulating_beta_types==0) model_LTV_by_age_group(time_period,:)=0
        if (accumulating_beta_types==0) mass_LTV_by_age_group(time_period,:)=0
        if (accumulating_beta_types==0) model_homeownership_by_age_group(time_period,:)=0
        if (accumulating_beta_types==0) mass_by_age_group(time_period,:)=0
        
        do age_index=1,life_span
                    
            if (age_index>(life_span-retirement_span)) then
            
                in_retirement=1
                
            else
            
                in_retirement=0
            
            end if
                            
            do years_left_on_mortgage_index=1,max_amortization_years
                            
                if (years_left_on_mortgage_index>1) then
                    
                    has_house=1
                    
                else
                
                    has_house=0
                    
                end if
                                                            
                do unemployment_index=1,unemployment_grid_size
                
                    do employment_index=1,employment_grid_size
                    
                        do voucher_index=0,(1-has_house)*include_vouchers
                    
                            avg_income_to_use_2=is_counterfactual*average_labor_income_by_employment_calibrated(employment_index)+&
                                (1-is_counterfactual)*model_average_labour_income_by_employment(time_period,employment_index)
                                                            
                            do financial_index=has_house*1+(1-has_house)*renter_floor_by_age(min(max(age_index,1),life_span)),financial_grid_size
                                               
                                do housing_status_index=(1-has_house)*lowest_housing_grid_point+&
                                    has_house*index_of_smallest_house_hhld_can_buy,housing_status_grid_size-1
                                                                
                                    lived_in_size_used=policy_function_space_lived_in_size(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                                                             
                                    amortization_used=policy_function_years_of_amortization_index(years_left_on_mortgage_index)%&
                                        vector_transition_integer(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                
                                    financial_index_used=policy_function_financial_index(years_left_on_mortgage_index)%&
                                        vector_transition_integer(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    labor_supply_used=policy_function_labor_supply(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    housing_status_index_used=policy_function_housing_status_index(years_left_on_mortgage_index)%&
                                        vector_transition_integer(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    MID_used=policy_function_mortgage_interest_deductions(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                                                                                                
                                    consumption_used=policy_function_consumption(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    frac_spent_on_addiction_used=policy_function_frac_spent_on_addiction&
                                        (years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    value_function_used=value_function(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    distribution_mass_used=distribution_stationary(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period_used,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)  
                                                                                    
                                    welfare_by_age(time_period,age_index)=&
                                        welfare_by_age(time_period,age_index)+value_function_used*distribution_mass_used
                                        
                                    welfare_by_employment_and_age(time_period,employment_index,age_index)=&
                                        welfare_by_employment_and_age(time_period,employment_index,age_index)+&
                                        value_function_used*distribution_mass_used
                                        
                                    if (unemployment_index<=threshold_addiction_index) then
                                    
                                        index_addiction_1=1
                                    
                                    else
                                    
                                        index_addiction_1=2
                                        
                                    end if
                                    
                                    welfare_by_age_and_addiction(time_period,age_index,index_addiction_1-1)=&
                                        welfare_by_age_and_addiction(time_period,age_index,index_addiction_1-1)+&
                                        value_function_used*distribution_mass_used
                                        
                                    mass_by_age_and_addiciton(time_period,age_index,index_addiction_1-1)=&
                                        mass_by_age_and_addiciton(time_period,age_index,index_addiction_1-1)+&
                                        distribution_mass_used
                                    
                                    welfare_by_addiction(time_period,index_addiction_1)=&
                                        welfare_by_addiction(time_period,index_addiction_1)+&
                                        value_function_used*distribution_mass_used
                                            
                                    mass_by_addiction(time_period,index_addiction_1)=&
                                        mass_by_addiction(time_period,index_addiction_1)+distribution_mass_used
                                        
                                    is_homeless_1=1
                                        
                                    if (housing_status_index==lowest_housing_grid_point) then
                                    
                                        is_homeless_1=2
                                        
                                    end if
                                    
                                    welfare_by_homelessness(time_period,is_homeless_1)=&
                                        welfare_by_homelessness(time_period,is_homeless_1)+&
                                        value_function_used*distribution_mass_used
                                    
                                    mass_by_homelessness(time_period,is_homeless_1)=&
                                        mass_by_homelessness(time_period,is_homeless_1)+distribution_mass_used
                                    
                                        
                                    if (age_index==1) then
                                    
                                        welfare_by_addiction_youngest(time_period,index_addiction_1)=&
                                            welfare_by_addiction_youngest(time_period,index_addiction_1)+&
                                            value_function_used*distribution_mass_used
                                            
                                        if ((value_function_used<lowest_welfare_of_addicted(time_period,1)) .AND. &
                                           (distribution_mass_used>0)) then
                                        
                                            lowest_welfare_of_addicted(time_period,1)=value_function_used
                                            lowest_welfare_of_addicted(time_period,2)=distribution_mass_used
                                            lowest_welfare_of_addicted(time_period,3)=unemployment_index
                                            lowest_welfare_of_addicted(time_period,4)=employment_index
                                            lowest_welfare_of_addicted(time_period,5)=financial_index
                                            lowest_welfare_of_addicted(time_period,6)=amortization_used
                                            lowest_welfare_of_addicted(time_period,7)=housing_status_index_used
                                            lowest_welfare_of_addicted(time_period,8)=financial_index_used
                                            lowest_welfare_of_addicted(time_period,9)=labor_supply_used
                                            lowest_welfare_of_addicted(time_period,10)=frac_spent_on_addiction_used
                                            lowest_welfare_of_addicted(time_period,11)=consumption_used                                        
                                            
                                        end if
                                            
                                        mass_by_addiction_youngest(time_period,index_addiction_1)=&
                                            mass_by_addiction_youngest(time_period,index_addiction_1)+distribution_mass_used
                                            
                                    end if
                                                                                
                                    ! OWNED BY govt_revenues_calc, WHICH RUNS FIRST. Reset and accumulation disabled here.
                                    ! mass_by_age was reset AND accumulated in three routines that run in
                                    ! sequence inside the two-pass loop, every reset guarded to the first pass.
                                    ! So on pass two each routine added another copy of the second type on top
                                    ! of what the previous one left: govt_revenues_calc ended at M1+M2, which is
                                    ! correct, this routine at M1+2*M2, and calculate_homeownership_by_
                                    ! characteristics at M1+3*M2 -- and the last is where homelessness_by_age
                                    ! and homeownership_by_age are normalised, so the age profile the author is
                                    ! reading came out at half its true value.
                                    !
                                    ! It is the same quantity in all three, so the first owner's copy is the one
                                    ! to keep. The call order is govt_revenues_calc, then this, then
                                    ! calculate_homeownership_by_characteristics, in the driver AND in
                                    ! long_run_counter_factual, so the value is always built before it is read.
                                    ! mass_by_age(time_period,age_index)=mass_by_age(time_period,age_index)+&
                                    ! distribution_mass_used
                                                                            
                                    mass_by_employment_and_age(time_period,employment_index,age_index)=&
                                        mass_by_employment_and_age(time_period,employment_index,age_index)+&
                                        distribution_mass_used
                                                                        
                                    employment_index_to_use=employment_index

                                    if (age_index<=9) then
                                        
                                        l=1
                                        
                                    elseif (age_index<=19) then
                                    
                                        l=2
                                    
                                    elseif (age_index<=29) then
                                    
                                        l=3
                                    
                                    elseif (age_index<=39) then
                                    
                                        l=4
                                    
                                    elseif (age_index>39) then
                                    
                                        l=5
                                    
                                    end if

                                    mass_by_age_group(time_period,l)=mass_by_age_group(time_period,l)+&
                                        distribution_mass_used
                                                                                                                                                            
                                    if (amortization_used>=2) then
                                
                                        mortgage_to_house_value_ratio_of_owners_by_age(time_period,age_index)=&
                                            mortgage_to_house_value_ratio_of_owners_by_age(time_period,age_index)-&
                                            min(financial_grid(financial_index_used),0.d0)*&
                                            distribution_mass_used
                                                                                
                                        model_LTV_by_age_group(time_period,l)=model_LTV_by_age_group(time_period,l)-&
                                            min(financial_grid(financial_index_used),0.d0)*&
                                            distribution_mass_used
                                        
                                        mass_LTV_by_age_group(time_period,l)=mass_LTV_by_age_group(time_period,l)+&
                                            distribution_mass_used
                                                                                    
                                        mass_mortgage_to_house_value_ratio_of_owners_by_age(time_period,age_index)=&
                                            mass_mortgage_to_house_value_ratio_of_owners_by_age(time_period,age_index)+&
                                            distribution_mass_used
                                            
                                        model_homeownership_by_age_group(time_period,l)=&
                                            model_homeownership_by_age_group(time_period,l)+&
                                            distribution_mass_used
                                                                                    
                                    end if                                      
                                        
                                    welfare_by_employment(time_period,employment_index_to_use)=&
                                        welfare_by_employment(time_period,employment_index_to_use)+&
                                        value_function_used*distribution_mass_used
                                        
                                    welfare_by_unemployment(time_period,unemployment_index)=&
                                        welfare_by_unemployment(time_period,unemployment_index)+&
                                        value_function_used*distribution_mass_used
                                        
                                    mass_by_unemployment(time_period,unemployment_index)=&
                                        mass_by_unemployment(time_period,unemployment_index)+distribution_mass_used
                                        
                                    if (years_left_on_mortgage_index<=1) then
                                    
                                        mass_of_renters_by_employment(time_period,employment_index_to_use)=&
                                            mass_of_renters_by_employment(time_period,employment_index_to_use)+&
                                            distribution_mass_used
                                                                            
                                    end if
                                        
                                    if (age_index==1) then
                                    
                                        welfare_by_employment_youngest(time_period,employment_index_to_use)=&
                                            welfare_by_employment_youngest(time_period,employment_index_to_use)+&
                                            value_function_used*distribution_mass_used
                                            
                                        mass_by_employment_youngest(time_period,employment_index_to_use)=&
                                            mass_by_employment_youngest(time_period,employment_index_to_use)+&
                                            distribution_mass_used
                                    
                                    end if
                                        
                                    MID_share_by_employment(time_period,employment_index_to_use)=&
                                        MID_share_by_employment(time_period,employment_index_to_use)+&
                                        MID_used*distribution_mass_used
                                        
                                    wealth_by_employment(time_period,employment_index_to_use)=&
                                        wealth_by_employment(time_period,employment_index_to_use)+&
                                        (housing_price(time_period)*housing_size(housing_status_index)*&
                                        (max(min(years_left_on_mortgage_index-1,1),0)+&
                                        min(financial_grid(financial_index),0.d0))+&
                                        max(financial_grid(financial_index),0.d0))*distribution_mass_used
                                        
                                    if (in_retirement==1) then
                                    
                                        average_income(time_period,employment_index_to_use)=&
                                            average_income(time_period,employment_index_to_use)+&
                                            model_ss_benefits(employment_index)*distribution_mass_used
                                    
                                    else
                                    
                                        if ((emp_of(unemployment_index)==1)) then
                                        
                                            average_income(time_period,employment_index_to_use)=&
                                                average_income(time_period,employment_index_to_use)+&
                                                (labor_supply_used*employment_grid(age_index,employment_index)*&
                                                labour_deterministic_efficiency(age_index))*distribution_mass_used
                                                
                                        else
                                                                                
                                            average_income(time_period,employment_index_to_use)=&
                                                average_income(time_period,employment_index_to_use)+&
                                                out_of_work_income(unemployment_index,employment_index,&
                                                avg_income_to_use_1)*distribution_mass_used
                                                                  
                                        end if
                                    
                                    end if
                                    
                                    average_income(time_period,employment_index_to_use)=&
                                        average_income(time_period,employment_index_to_use)+&
                                        (max(financial_grid(financial_index),0.d0)*&
                                        risk_free_rate(time_period)+lump_sum_transfer(time_period))*&
                                        distribution_mass_used
                                        
                                    if (age_index==1) then
                                    
                                        if (years_left_on_mortgage_index>1) then
                                        
                                            average_house_inheritance(time_period,employment_index_to_use)=&
                                                average_house_inheritance(time_period,employment_index_to_use)+&
                                                housing_size(housing_status_index)*distribution_mass_used
                                                
                                            mass_inheritance(time_period,employment_index_to_use)=&
                                                mass_inheritance(time_period,employment_index_to_use)+distribution_mass_used
                                        
                                        end if
                                        
                                        average_house_non_inheritance(time_period,employment_index_to_use)=&
                                            average_house_non_inheritance(time_period,employment_index_to_use)+&
                                            max(financial_grid(financial_index),0.d0)*distribution_mass_used
                                            
                                        mass_non_inheritance(time_period,employment_index_to_use)=&
                                            mass_non_inheritance(time_period,employment_index_to_use)+distribution_mass_used
                                                                        
                                    end if
                                        
                                    if (financial_grid(financial_index)<0) then
                                        
                                        fraction_with_mortgage(time_period,employment_index_to_use)=&
                                            fraction_with_mortgage(time_period,employment_index_to_use)+distribution_mass_used
                                            
                                    end if
                                    
                                    average_consumption(time_period,employment_index_to_use)=&
                                        average_consumption(time_period,employment_index_to_use)+&
                                        consumption_used*distribution_mass_used
                                        
                                    if ((housing_status_index_used>second_lowest_housing_grid_point) .OR. &
                                       (have_two_rental_markets==0)) then
                                    
                                        low_quality_market=0
                                    
                                    else
                                    
                                        low_quality_market=1
                                    
                                    end if
                                    
                                    if (amortization_used<=1) then
                                    
                                        fraction_renters_by_employment(time_period,employment_index_to_use)=&
                                            fraction_renters_by_employment(time_period,employment_index_to_use)+&
                                            distribution_mass_used

                                        average_housing_costs(time_period,employment_index_to_use)=&
                                            average_housing_costs(time_period,employment_index_to_use)+&
                                            rent(time_period,low_quality_market)*lived_in_size_used*&
                                            distribution_mass_used
                                                                                
                                    else
                                    
                                        average_age_of_homeowner(time_period,employment_index_to_use)=&
                                            average_age_of_homeowner(time_period,employment_index_to_use)+age_index*&
                                            distribution_mass_used
                                            
                                        average_housing_costs(time_period,employment_index_to_use)=&
                                            average_housing_costs(time_period,employment_index_to_use)+&
                                            (housing_price(time_period)*housing_size(housing_status_index)*&
                                            (property_tax(time_period)+housing_depreciation_rate)-&
                                            min(financial_grid(financial_index),0.d0)*&
                                            housing_price(time_period)*housing_size(housing_status_index)*&
                                            mortgage_interest_rate(time_period)-MID_used)*distribution_mass_used
                                            
                                    end if
                                    
                                    ! ONE OWNER PER VARIABLE. Reset and accumulation disabled here.
                                    !
                                    ! Every reset in the chain is guarded to the FIRST pass, which is safe only
                                    ! if exactly one routine owns the variable. Where two or more each reset and
                                    ! each accumulate, the guard that stops pass two resetting also lets each
                                    ! routine start from whatever the previous one left, so the second pass adds
                                    ! another copy of the second type on top of a finished total. Four owners of
                                    ! mass_by_employment made it 5*M where the pooled mass is 2*M, so every
                                    ! welfare-by-employment average was halved and homeownership_by_employment
                                    ! came out at 0.4 times truth.
                                    !
                                    ! It is the same quantity in every owner, so the FIRST in call order keeps
                                    ! it and the rest read it. The order is the same in the driver and in
                                    ! long_run_counter_factual, so the value is always built before it is read.
                                    ! mass_by_employment(time_period,employment_index_to_use)=&
                                    ! mass_by_employment(time_period,employment_index_to_use)+distribution_mass_used
                                                                         
                                    if (years_left_on_mortgage_index<=1) then
                                    
                                        i=1
                                        
                                    elseif (years_left_on_mortgage_index==3) then
                                    
                                        i=2
                                        
                                    else
                                    
                                        i=3
                                    
                                    end if
                                    
                                    if (age_index==1) then
                                    
                                        welfare_by_employment_youngest_old_dist(time_period,employment_index_to_use)=&
                                            welfare_by_employment_youngest_old_dist(time_period,employment_index_to_use)+&
                                            value_function_used*distribution_mass_used
                                            
                                    end if
                                                                                
                                    mass_by_employment_and_tenure(time_period,employment_index_to_use,i)=&
                                        mass_by_employment_and_tenure(time_period,employment_index_to_use,i)+distribution_mass_used
                                    
                                    if (value_function_used>-200000) then
                                    
                                        welfare_by_employment_and_tenure(time_period,employment_index_to_use,i)=&
                                            welfare_by_employment_and_tenure(time_period,employment_index_to_use,i)+&
                                            value_function_used*distribution_mass_used
                                            
                                        wealth_by_employment_and_tenure(time_period,employment_index_to_use,i)=&
                                            wealth_by_employment_and_tenure(time_period,employment_index_to_use,i)+&
                                            housing_price(time_period)*housing_size(housing_status_index)*&
                                            (max(min(years_left_on_mortgage_index-1,1),0)+&
                                            min(financial_grid(financial_index),0.d0)+&
                                            max(financial_grid(financial_index),0.d0))*distribution_mass_used
                                            
                                        consumption_by_employment_and_tenure(time_period,employment_index_to_use,i)=&
                                            consumption_by_employment_and_tenure(time_period,employment_index_to_use,i)+&
                                            consumption_used*distribution_mass_used
                                            
                                        housing_by_employment_and_tenure(time_period,employment_index_to_use,i)=&
                                            housing_by_employment_and_tenure(time_period,employment_index_to_use,i)+&
                                            lived_in_size_used*distribution_mass_used
                                            
                                        mortgage_by_employment_and_tenure(time_period,employment_index_to_use,i)=&
                                            mortgage_by_employment_and_tenure(time_period,employment_index_to_use,i)-&
                                            min(financial_grid(financial_index),0.d0)*&
                                            housing_price(time_period)*housing_size(housing_status_index)*&
                                            distribution_mass_used
                                            
                                        if (financial_grid(financial_index)<0) then
                                        
                                            mortgage_by_employment(time_period,employment_index_to_use)=&
                                                mortgage_by_employment(time_period,employment_index_to_use)-&
                                                min(financial_grid(financial_index),0.d0)*&
                                                housing_price(time_period)*housing_size(housing_status_index)*&
                                                distribution_mass_used
                                                
                                            mass_by_mortgage_and_employment(time_period,employment_index_to_use)=&
                                                mass_by_mortgage_and_employment(time_period,employment_index_to_use)+&
                                                distribution_mass_used
                                        
                                        end if
                                                                                    
                                        age_group=int(floor(real(age_index)/real(10))+1)
                                            
                                        welfare_by_employment_tenure_and_age(time_period,employment_index_to_use,i,age_group)=&
                                            welfare_by_employment_tenure_and_age(time_period,employment_index_to_use,i,age_group)+&
                                            value_function_used*distribution_mass_used
                                                                                
                                        mortgage_by_employment_tenure_and_age(time_period,employment_index_to_use,i,age_group)=&
                                            mortgage_by_employment_tenure_and_age(time_period,employment_index_to_use,i,age_group)-&
                                            min(financial_grid(financial_index),0.d0)*distribution_mass_used
                                                
                                        mass_by_employment_tenure_and_age(time_period,employment_index_to_use,i,age_group)=&
                                            mass_by_employment_tenure_and_age(time_period,employment_index_to_use,i,age_group)+&
                                            distribution_mass_used
                                            
                                    end if
                                    
                                    if (age_index==1) then
                                                                                                                                                                            
                                        welfare_by_ownership_status(time_period,max(min(amortization_used-1,1),0),&
                                            employment_index_to_use)=welfare_by_ownership_status(time_period,max(min(&
                                            amortization_used-1,1),0),employment_index_to_use)+value_function_used*&
                                            distribution_mass_used
                                                                            
                                        mass_by_ownership_status(time_period,max(min(amortization_used-1,1),0),&
                                            employment_index_to_use)=mass_by_ownership_status(time_period,max(min(&
                                            amortization_used-1,1),0),employment_index_to_use)+distribution_mass_used
                                                                                     
                                    end if
                                
                                end do
                                
                            end do
                            
                        end do
                        
                    end do
                                                    
                end do
                                    
            end do
            
        end do
        
        if (current_beta_type==number_of_beta_types) then
            welfare_by_homelessness(time_period,:)=&
                welfare_by_homelessness(time_period,:)/mass_by_homelessness(time_period,:)
        end if
        
        do age_index=1,life_span
                
            if (current_beta_type==number_of_beta_types) then
                welfare_by_age(time_period,age_index)=welfare_by_age(time_period,age_index)/&
                    mass_by_age(time_period,age_index)
            end if
                
            if (current_beta_type==number_of_beta_types) then
                welfare_by_age_and_addiction(time_period,age_index,:)=&
                    welfare_by_age_and_addiction(time_period,age_index,:)/mass_by_age_and_addiciton(time_period,age_index,:)
            end if
                                    
        end do
        
        do age_index=1,life_span
        
            do employment_index=1,employment_grid_size
                
                if (current_beta_type==number_of_beta_types) then
                    welfare_by_employment_and_age(time_period,employment_index,age_index)=&
                        welfare_by_employment_and_age(time_period,employment_index,age_index)/&
                        mass_by_employment_and_age(time_period,employment_index,age_index)
                end if
                    
            end do
                                    
        end do    
        
        do i=1,2
        
            if (current_beta_type==number_of_beta_types) welfare_by_addiction(time_period,i)=welfare_by_addiction(time_period,i)/mass_by_addiction(time_period,i)
            if (current_beta_type==number_of_beta_types) then
                welfare_by_addiction_youngest(time_period,i)=welfare_by_addiction_youngest(time_period,i)/&
                    mass_by_addiction_youngest(time_period,i)
            end if
            
        end do
                            
        sum_of_distribution=0
        
        do i=1,2
                
            sum_of_distribution=sum_of_distribution+&
                sum(distribution_stationary(i)%vector_transition_real(time_period,:,:,:,:,:,:))
            
        end do

        ! POOLED MASS. This routine is SEVENTH of nine in the two-pass
        ! loop and sum_of_distribution is MODULE scope, so the one-type
        ! value it leaves here is what every later reader sees --
        ! including print_all_moments, which runs after the loop has
        ! ended and accumulating_beta_types is back to zero. That is why
        ! the mass diagnostics came out at exactly 2.0: pooled
        ! numerators over a denominator holding one type.
        !
        ! The scaling was reverted here once, on the reasoning that this
        ! routine is per-type. It is not: it does not OWN this variable.
        ! POOLED MASS, READ NOT REBUILT. stationary_equilibrium_statistics runs
        ! FIRST in every pass and has already added this type's mass, so the
        ! total here is the real pooled mass rather than one type's scaled by a
        ! pass count. The types do not weigh the same; see pooled_mass_all.
        sum_of_distribution=pooled_mass_all
        
        do age_index=1,life_span
        
            if (current_beta_type==number_of_beta_types) then
                mortgage_to_house_value_ratio_of_owners_by_age(time_period,age_index)=&
                    mortgage_to_house_value_ratio_of_owners_by_age(time_period,age_index)/&
                    mass_mortgage_to_house_value_ratio_of_owners_by_age(time_period,age_index)
            end if
        
        end do
        
        do age_index=1,life_span
        
            if (current_beta_type==number_of_beta_types) then
                mass_mortgage_to_house_value_ratio_of_owners_by_age(time_period,age_index)=&
                    mass_mortgage_to_house_value_ratio_of_owners_by_age(time_period,age_index)/&
                    sum_of_distribution
            end if
        
        end do
        
        do i=1,5 
        
        ! NORMALISE ONLY ON THE LAST PASS. This division puts its result back
        ! into the accumulator it reads, and the reset above is guarded to the
        ! FIRST pass, so without this guard the second pass divides an already
        ! divided value again and adds the second type on top of a finished
        ! average. Nothing at one type moves: the condition is 1==1 there.
        if (current_beta_type==number_of_beta_types) then
                model_LTV_by_age_group(time_period,i)=model_LTV_by_age_group(time_period,i)/&
                    mass_LTV_by_age_group(time_period,i)
        end if
                
            if (current_beta_type==number_of_beta_types) then
                model_homeownership_by_age_group(time_period,i)=&
                    model_homeownership_by_age_group(time_period,i)/mass_by_age_group(time_period,i)
            end if
        
        end do
                
        do employment_index=1,employment_grid_size
                
            if (current_beta_type==number_of_beta_types) then
                welfare_by_employment(time_period,employment_index)=welfare_by_employment(time_period,employment_index)/&
                    mass_by_employment(time_period,employment_index)
            end if
                
            if (current_beta_type==number_of_beta_types) then
                welfare_by_employment_youngest_old_dist(time_period,employment_index)=&
                    welfare_by_employment_youngest_old_dist(time_period,employment_index)/&
                    mass_by_employment_and_age(time_period,employment_index,1)
            end if
                                
            if (current_beta_type==number_of_beta_types) then
                welfare_by_employment_youngest(time_period,employment_index)=&
                    welfare_by_employment_youngest(time_period,employment_index)/&
                    mass_by_employment_youngest(time_period,employment_index)
            end if
                
        ! NORMALISE ONLY ON THE LAST PASS. This division puts its result back
        ! into the accumulator it reads, and the reset above is guarded to the
        ! FIRST pass, so without this guard the second pass divides an already
        ! divided value again and adds the second type on top of a finished
        ! average. Nothing at one type moves: the condition is 1==1 there.
        if (current_beta_type==number_of_beta_types) then
                MID_share_by_employment(time_period,employment_index)=MID_share_by_employment(time_period,employment_index)/&
                    govt_spending_on_mortgage_interest_deductions(time_period)
        end if
                
            if (current_beta_type==number_of_beta_types) then
                wealth_by_employment(time_period,employment_index)=wealth_by_employment(time_period,employment_index)/&
                    mass_by_employment(time_period,employment_index)
            end if
                
            if (current_beta_type==number_of_beta_types) then
                fraction_with_mortgage(time_period,employment_index)=fraction_with_mortgage(time_period,employment_index)/&
                    mass_by_employment(time_period,employment_index)
            end if
                
            if (current_beta_type==number_of_beta_types) then
                fraction_renters_by_employment(time_period,employment_index)=&
                    fraction_renters_by_employment(time_period,employment_index)/&
                    mass_by_employment(time_period,employment_index)
            end if
                
            if (current_beta_type==number_of_beta_types) then
                average_age_of_homeowner(time_period,employment_index)=average_age_of_homeowner(time_period,employment_index)/&
                    mass_by_employment(time_period,employment_index)
            end if
                
            if (current_beta_type==number_of_beta_types) then
                average_income(time_period,employment_index)=average_income(time_period,employment_index)/&
                    mass_by_employment(time_period,employment_index)
            end if
                
            if (current_beta_type==number_of_beta_types) then
                average_housing_costs(time_period,employment_index)=average_housing_costs(time_period,employment_index)/&
                    mass_by_employment(time_period,employment_index)
            end if
                
            if (current_beta_type==number_of_beta_types) then
                average_consumption(time_period,employment_index)=average_consumption(time_period,employment_index)/&
                    mass_by_employment(time_period,employment_index)
            end if
                
            if (current_beta_type==number_of_beta_types) then
                average_house_inheritance(time_period,employment_index)=average_house_inheritance(time_period,employment_index)/&
                    mass_inheritance(time_period,employment_index)
            end if
                
            if (current_beta_type==number_of_beta_types) then
                average_house_non_inheritance(time_period,employment_index)=&
                    average_house_non_inheritance(time_period,employment_index)/&
                    mass_non_inheritance(time_period,employment_index)
            end if
                                                
        end do
                   
        do employment_index=1,employment_grid_size
        
            if (current_beta_type==number_of_beta_types) then
                mortgage_by_employment(time_period,employment_index)=mortgage_by_employment(time_period,employment_index)/&
                    mass_by_mortgage_and_employment(time_period,employment_index)
            end if
        
            do years_left_on_mortgage_index=1,3
            
                if (current_beta_type==number_of_beta_types) then
                    welfare_by_employment_and_tenure(time_period,employment_index,years_left_on_mortgage_index)=&
                        welfare_by_employment_and_tenure(time_period,employment_index,years_left_on_mortgage_index)/&
                        mass_by_employment_and_tenure(time_period,employment_index,years_left_on_mortgage_index)
                end if
                    
                if (current_beta_type==number_of_beta_types) then
                    wealth_by_employment_and_tenure(time_period,employment_index,years_left_on_mortgage_index)=&
                        wealth_by_employment_and_tenure(time_period,employment_index,years_left_on_mortgage_index)/&
                        mass_by_employment_and_tenure(time_period,employment_index,years_left_on_mortgage_index)
                end if
                    
                if (current_beta_type==number_of_beta_types) then
                    consumption_by_employment_and_tenure(time_period,employment_index,years_left_on_mortgage_index)=&
                        consumption_by_employment_and_tenure(time_period,employment_index,years_left_on_mortgage_index)/&
                        mass_by_employment_and_tenure(time_period,employment_index,years_left_on_mortgage_index)
                end if
                    
                if (current_beta_type==number_of_beta_types) then
                    housing_by_employment_and_tenure(time_period,employment_index,years_left_on_mortgage_index)=&
                        housing_by_employment_and_tenure(time_period,employment_index,years_left_on_mortgage_index)/&
                        mass_by_employment_and_tenure(time_period,employment_index,years_left_on_mortgage_index)
                end if
                    
                if (current_beta_type==number_of_beta_types) then
                    mortgage_by_employment_and_tenure(time_period,employment_index,years_left_on_mortgage_index)=&
                        mortgage_by_employment_and_tenure(time_period,employment_index,years_left_on_mortgage_index)/&
                        mass_by_employment_and_tenure(time_period,employment_index,years_left_on_mortgage_index)
                end if
            
            end do
            
        end do
        
        do age_index=1,int((real(life_span)/real(10)))
        
            do employment_index=1,employment_grid_size
            
                do years_left_on_mortgage_index=1,3
                                
                    if (current_beta_type==number_of_beta_types) then
                        welfare_by_employment_tenure_and_age(time_period,employment_index,years_left_on_mortgage_index,age_index)=&
                            welfare_by_employment_tenure_and_age(time_period,employment_index,years_left_on_mortgage_index,age_index)/&
                            mass_by_employment_tenure_and_age(time_period,employment_index,years_left_on_mortgage_index,age_index)
                    end if
                        
                    if (current_beta_type==number_of_beta_types) then
                        mortgage_by_employment_tenure_and_age(time_period,employment_index,years_left_on_mortgage_index,age_index)=&
                            mortgage_by_employment_tenure_and_age(time_period,employment_index,years_left_on_mortgage_index,age_index)/&
                            mass_by_employment_tenure_and_age(time_period,employment_index,years_left_on_mortgage_index,age_index)
                    end if
                                        
                end do
                
            end do
            
        end do
        
        do k=0,1
        
            do employment_index=1,employment_grid_size
                    
                if (current_beta_type==number_of_beta_types) then
                    welfare_by_ownership_status(time_period,k,employment_index)=&
                        welfare_by_ownership_status(time_period,k,employment_index)/&
                        mass_by_ownership_status(time_period,k,employment_index)
                end if
                                                                        
            end do
        
        end do
        
        do unemployment_index=1,unemployment_grid_size
        
            if (current_beta_type==number_of_beta_types) then
                welfare_by_unemployment(time_period,unemployment_index)=&
                    welfare_by_unemployment(time_period,unemployment_index)/&
                    mass_by_unemployment(time_period,unemployment_index)    
            end if
        
        end do
        
    end subroutine
    
    subroutine calculate_welfare_gains(time_period,welfare_to_compare_1,type_1,x_1)

        use Global_Vars
        use, intrinsic :: ieee_arithmetic
        implicit none

        integer, intent(in) :: time_period
        integer, intent(in) :: type_1
        real(8), intent(in) :: welfare_to_compare_1
        real(8), intent(inout) :: x_1

        real(8) :: stopping_rule_1, x_0, x_2, distance_1
        real(8) :: welfare_adjusted_1, w0, w2
        character*1 :: string_used
               
        vf_simulation='baseline_benchmark'
                   
        write(*,*) "vf_simulation=", vf_simulation

        stopping_rule_1 = 10.d0**(-4)

        if (already_uploaded_benchmark==0) then
            do i=1,2
                write(string_used,'(i1)') i

                open(unit=10,file="distribution_stationary"//trim(string_used)//trim(vf_simulation)//".dat", &
                     action='read')
                    read(10,'(F30.28)') distribution_stationary_benchmark(i)%vector_real(:,:,:,:,:,:)
                close(10)

                open(unit=10,file="value_function"//trim(string_used)//trim(vf_simulation)//".dat", &
                     action='read')
                    read(10,'(F35.13)') value_function_benchmark(i)%vector_real(:,:,:,:,:,:)
                close(10)

                open(unit=10,file="policy_function_frac_spent_on_addiction"//&
                    trim(string_used)//trim(vf_simulation)//".dat", &
                     action='read')
                    read(10,'(F25.20)') policy_function_frac_spent_on_addiction_benchmark(i)%vector_real(:,:,:,:,:,:)
                close(10)

                open(unit=10,file="policy_function_total_consumption"//trim(string_used)//trim(vf_simulation)//".dat", &
                     action='read')
                    read(10,'(F26.20)') policy_function_total_consumption_benchmark(i)%vector_real(:,:,:,:,:,:)
                close(10)

                open(unit=10,file="policy_function_labor_supply"//trim(string_used)//trim(vf_simulation)//".dat", &
                     action='read')
                    read(10,'(F22.20)') policy_function_labor_supply_benchmark(i)%vector_real(:,:,:,:,:,:)
                close(10)

                open(unit=10,file="policy_function_housing_status_index"//trim(string_used)//trim(vf_simulation)//".dat", &
                     action='read')
                    read(10,'(I2)') policy_function_housing_status_index_benchmark(i)%vector_integer(:,:,:,:,:,:)
                close(10)

                open(unit=10,file="policy_function_years_of_amortization_index"//&
                    trim(string_used)//trim(vf_simulation)//".dat", action='read')
                    read(10,'(I2)') policy_function_years_of_amortization_index_benchmark(i)%vector_integer(:,:,:,:,:,:)
                close(10)

                open(unit=10,file="policy_function_addiction"//trim(string_used)//trim(vf_simulation)//".dat", &
                     action='read')
                    read(10,'(I1)') policy_function_addiction_benchmark(i)%vector_integer(:,:,:,:,:,:)
                close(10)

                open(unit=10,file="policy_function_financial_index"//trim(string_used)//trim(vf_simulation)//".dat", &
                     action='read')
                    read(10,'(I3)') policy_function_financial_index_benchmark(i)%vector_integer(:,:,:,:,:,:)
                close(10)

                open(unit=10,file="fin_index_frac_mov_to_optimal"//trim(string_used)//trim(vf_simulation)//".dat", &
                     action='read')
                    read(10,'(I3)') fin_index_frac_mov_to_optimal_benchmark(i)%vector_integer(:,:,:,:,:,:)
                close(10)

                open(unit=10,file="frac_mov_optimal_1"//trim(string_used)//trim(vf_simulation)//".dat", &
                     action='read')
                    read(10,'(F22.20)') frac_mov_optimal_1_benchmark(i)%vector_real(:,:,:,:,:,:)
                close(10)

            end do
            already_uploaded_benchmark=1
        end if

        x_0 = -0.5d0
        x_2 =  0.5d0

        call compute_value_function_comparison(time_period, x_0)
        call compute_value_of_comparison(w0, type_1)

        call compute_value_function_comparison(time_period, x_2)
        call compute_value_of_comparison(w2, type_1)

        if (ieee_is_nan(w0) .or. ieee_is_nan(w2)) then
            write(*,*) "NaN welfare at bracket endpoints."
            stop
        end if

        if ( (welfare_to_compare_1 < min(w0,w2)) .or. (welfare_to_compare_1 > max(w0,w2)) ) then
            write(*,*) "target welfare not bracketed by x in [-1,1]."
            write(*,*) "w0=", w0, " w2=", w2, " target=", welfare_to_compare_1
            stop
        end if

        x_1 = 0.5d0*(x_0 + x_2)
        distance_1 = abs(x_2 - x_0)
        
        do while (distance_1 > stopping_rule_1)

            call compute_value_function_comparison(time_period, x_1)
            call compute_value_of_comparison(welfare_adjusted_1, type_1)

            if (ieee_is_nan(welfare_adjusted_1)) then
                write(*,*) "NaN welfare at x=", x_1
                stop
            end if

            if (welfare_adjusted_1 < welfare_to_compare_1) then
                x_0 = x_1
            else
                x_2 = x_1
            end if

            x_1 = 0.5d0*(x_0 + x_2)
            distance_1 = abs(x_2 - x_0)

            write(*,*) "x_1=", x_1, " distance_1=", distance_1, " welfare_adjusted_1=", welfare_adjusted_1

        end do

    end subroutine

    subroutine compute_value_function_comparison(time_period,x_1)

        use global_vars
        use, intrinsic :: ieee_arithmetic

        implicit none

        integer, intent(in) :: time_period
        integer :: financial_index,has_house,track_housing_1,is_homeless_1,&
            addiction_index_1,financial_index_1,years_1,housing_1,financial_index_2,loop_over_addiction_1,&
            addiction_used_1,check_1,is_addicted_1,first_voucher_index,second_voucher_index,&
            has_opportunity_1,voucher_index_1

        real(8) :: total_consumption_1,consumption_1,fraction_spent_on_addiction_1,distribution_1,income_1,&
            flow_utility_1,labor_supply_1,frac_move_1,avg_income_to_use_1,avg_income_to_use_2
        real(8), intent(in) :: x_1

        avg_income_to_use_1=is_counterfactual*average_labor_income_calibrated+&
            (1-is_counterfactual)*model_average_labour_income(time_period)

        do i=1,2
            value_function_comparison(i)%vector_real(:,:,:,:,:,:)=0.d0
        end do

        do age_index=life_span,1,-1

            if (age_index>life_span-retirement_span) then
                in_retirement=1
            else
                in_retirement=0
            end if

            if (age_index>=(life_span-retirement_span)) then
                at_least_one_period_before_retirement=1
            else
                at_least_one_period_before_retirement=0
            end if

            if (age_index==1) then
                newborn_household=1
            else
                newborn_household=0
            end if

            do years_left_on_mortgage_index=1,newborn_household*1+(1-newborn_household)*max_amortization_years

                if (years_left_on_mortgage_index>1) then
                    has_house=1
                else
                    has_house=0
                end if

                track_housing_1=1
                if (has_house==0) then
                    if (track_renters_housing==0) then
                        track_housing_1=0
                    end if
                end if

                do unemployment_index=1,unemployment_grid_size
                    do employment_index=1,employment_grid_size

                        avg_income_to_use_2=is_counterfactual*average_labor_income_by_employment_calibrated(employment_index)+&
                            (1-is_counterfactual)*model_average_labour_income_by_employment(time_period,employment_index)

                        do voucher_index=0,(1-has_house)*include_vouchers

                            do financial_index=newborn_household*negative_financial_grid_size+&
                                 (1-newborn_household)*(has_house*1+(1-has_house)*renter_floor_by_age(min(max(age_index,1),life_span))),&
                                 include_exogenous_endowment*financial_grid_size+(1-include_exogenous_endowment)*&
                                 (newborn_household*negative_financial_grid_size+(1-newborn_household)*financial_grid_size)

                                do housing_status_index=(1-has_house)*lowest_housing_grid_point+&
                                    has_house*index_of_smallest_house_hhld_can_buy,&
                                    track_housing_1*(1-newborn_household)*(housing_status_grid_size-1)

                                    years_1=policy_function_years_of_amortization_index_benchmark&
                                        (years_left_on_mortgage_index)%vector_integer(age_index,&
                                        financial_index,unemployment_index,employment_index,&
                                        housing_status_index,voucher_index)

                                    if (years_1>1) then
                                        choose_to_own=1
                                    else
                                        choose_to_own=0
                                    end if

                                    track_housing_2=1
                                    if (choose_to_own==0) then
                                        if (track_renters_housing==0) then
                                            track_housing_2=0
                                        end if
                                    end if

                                    labor_supply_1=policy_function_labor_supply_benchmark&
                                        (years_left_on_mortgage_index)%vector_real&
                                        (age_index,financial_index,unemployment_index,&
                                        employment_index,housing_status_index,voucher_index)

                                    total_consumption_1=policy_function_total_consumption_benchmark&
                                        (years_left_on_mortgage_index)%vector_real&
                                        (age_index,financial_index,unemployment_index,&
                                        employment_index,housing_status_index,voucher_index)

                                    housing_1=policy_function_housing_status_index_benchmark&
                                        (years_left_on_mortgage_index)%&
                                        vector_integer(age_index,financial_index,unemployment_index,&
                                        employment_index,housing_status_index,voucher_index)

                                    addiction_used_1=policy_function_addiction_benchmark&
                                        (years_left_on_mortgage_index)%&
                                        vector_integer(age_index,financial_index,unemployment_index,&
                                        employment_index,housing_status_index,voucher_index)

                                    addiction_index_1=0
                                    loop_over_addiction_1=0

                                    if (unemployment_index>threshold_addiction_index) then
                                    
                                        addiction_index_1=1
                                        loop_over_addiction_1=1
                                        
                                    elseif ((addiction_used_1>=1) .AND. &
                                        (unemployment_index<=threshold_addiction_index) .AND. &
                                        (include_probability_of_becoming_addicted==1)) then
                                        
                                        loop_over_addiction_1=1
                                        
                                    end if

                                    call calculate_income(unemployment_index,employment_index,income_1,&
                                        avg_income_to_use_1,avg_income_to_use_2,labor_supply_1,in_retirement)

                                    income_1=income_1+(risk_free_rate(time_period)*max(financial_grid(financial_index),0.d0)+unsecured_borrowing_rate*min(financial_grid(financial_index),0.d0))

                                    future_housing_status_index_to_use_2=housing_1

                                    if (track_housing_2==0) then
                                        if (future_housing_status_index_to_use_2>second_lowest_housing_grid_point) then
                                            future_housing_status_index_to_use_2=0
                                        end if
                                    end if

                                    is_homeless_1=1
                                    if (future_housing_status_index_to_use_2==lowest_housing_grid_point) then
                                        is_homeless_1=2
                                    end if

                                    is_addicted_1=0
                                    if (unemployment_index>threshold_addiction_index) then
                                        is_addicted_1=1
                                    end if

                                    call compute_voucher_index_1(is_homeless_1,voucher_index_1)
                                    call calculate_future_voucher_index_and_opportunity&
                                        (has_opportunity_1,first_voucher_index,second_voucher_index,&
                                        time_period,has_house,choose_to_own,voucher_index_1,income_1)

                                    treatment_used_1=&
                                        policy_function_treatment(years_left_on_mortgage_index)%&
                                        vector_transition_integer(1,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)

                                    fraction_spent_on_addiction_1=&
                                        policy_function_frac_spent_on_addiction_benchmark&
                                        (years_left_on_mortgage_index)%&
                                        vector_real(age_index,financial_index,unemployment_index,&
                                        employment_index,housing_status_index,voucher_index)

                                    financial_index_1=policy_function_financial_index_benchmark&
                                        (years_left_on_mortgage_index)%&
                                        vector_integer(age_index,financial_index,unemployment_index,&
                                        employment_index,housing_status_index,voucher_index)

                                    financial_index_2=fin_index_frac_mov_to_optimal_benchmark&
                                        (years_left_on_mortgage_index)%&
                                        vector_integer(age_index,financial_index,unemployment_index,&
                                        employment_index,housing_status_index,voucher_index)

                                    frac_move_1=frac_mov_optimal_1_benchmark(years_left_on_mortgage_index)%&
                                        vector_real(age_index,financial_index,unemployment_index,&
                                        employment_index,housing_status_index,voucher_index)

                                    distribution_1=distribution_stationary_benchmark(years_left_on_mortgage_index)%&
                                        vector_real(age_index,financial_index,unemployment_index,&
                                        employment_index,housing_status_index,voucher_index)

                                    consumption_1=(1-fraction_spent_on_addiction_1)*total_consumption_1*(1+x_1)

                                    if (consumption_1>0.d0) then

                                        call calculate_flow_utility(0,housing_1,housing_size(housing_1),&
                                            fraction_spent_on_addiction_1,total_consumption_1,consumption_1,&
                                            choose_to_own,addiction_used_1,flow_utility_1,1)

                                        flow_utility_1=flow_utility_1+relative_share_of_leisure*&
                                            ((max_labor_supply-labor_supply_1)**&
                                            (1-leisure_curvature))/(1-leisure_curvature)&
                                            -kappa_x*model_fraction_homeless(1)

                                        value_function_comparison(years_left_on_mortgage_index)%&
                                            vector_real(age_index,financial_index,unemployment_index,&
                                            employment_index,housing_status_index,voucher_index)=flow_utility_1

                                        if (age_index<life_span) then

                                            do future_addiction_index_2=&
                                                (1-loop_over_addiction_1)*addiction_used_1+loop_over_addiction_1*0,&
                                                (1-loop_over_addiction_1)*addiction_used_1+loop_over_addiction_1*include_addiction

                                                check_1=0
                                                if (future_addiction_index_2==1) then
                                                    check_1=1
                                                end if

                                                do future_unemployment_index=include_addiction*&
                                                    ((1-check_1)*1+check_1*(threshold_addiction_index+1))+&
                                                    (1-include_addiction)*&
                                                    (at_least_one_period_before_retirement*unemployment_index+&
                                                    (1-at_least_one_period_before_retirement)*1),include_addiction*&
                                                    ((1-check_1)*threshold_addiction_index+check_1*unemployment_grid_size)+&
                                                    (1-include_addiction)*&
                                                    (at_least_one_period_before_retirement*unemployment_index+&
                                                    (1-at_least_one_period_before_retirement)*unemployment_grid_size)

                                                    do future_employment_index=&
                                                        at_least_one_period_before_retirement*employment_index+&
                                                        (1-at_least_one_period_before_retirement)*1,&
                                                        at_least_one_period_before_retirement*employment_index+&
                                                        (1-at_least_one_period_before_retirement)*employment_grid_size

                                                        do future_voucher_index=first_voucher_index,second_voucher_index

                                                            value_function_comparison(years_left_on_mortgage_index)%&
                                                                vector_real(age_index,financial_index,unemployment_index,&
                                                                employment_index,housing_status_index,voucher_index)=&
                                                                value_function_comparison(years_left_on_mortgage_index)%&
                                                                vector_real(age_index,financial_index,unemployment_index,&
                                                                employment_index,housing_status_index,voucher_index)+&
                                                                discount_factor*&
                                                                survival_probability(age_index,is_homeless_1,is_addicted_1,smi_of(unemployment_index))*&
                                                                voucher_probabilities_benchmark(voucher_index,future_voucher_index,&
                                                                has_opportunity_1,voucher_index_1)*employment_process&
                                                                (age_index,employment_index,future_employment_index)*&
                                                                unemployment_process(age_index,unemployment_index,&
                                                                future_unemployment_index,is_homeless_1,&
                                                                future_addiction_index_2,employment_index)*&
                                                                addiction_transition&
                                                                (addiction_index_1,future_addiction_index_2,addiction_used_1,&
                                                                is_homeless_1,fraction_spent_on_addiction_1*&
                                                                total_consumption_1/price_of_addictive_good_benchmark,1,&
                                                                treatment_used_1)*&
                                                                ((1-frac_move_1)*&
                                                                value_function_comparison(years_1)%&
                                                                vector_real(age_index+1,financial_index_1,&
                                                                future_unemployment_index,future_employment_index,&
                                                                future_housing_status_index_to_use_2,future_voucher_index)+&
                                                                frac_move_1*value_function_comparison(years_1)%&
                                                                vector_real(age_index+1,financial_index_2,&
                                                                future_unemployment_index,future_employment_index,&
                                                                future_housing_status_index_to_use_2,future_voucher_index))

                                                        end do
                                                    end do
                                                end do
                                            end do

                                        end if

                                    else
                                    
                                        value_function_comparison(years_left_on_mortgage_index)%&
                                            vector_real(age_index,financial_index,unemployment_index,&
                                            employment_index,housing_status_index,voucher_index) = -1.d300
                                    end if

                                end do
                            end do
                        end do
                    end do
                end do

            end do
        end do

    end subroutine

    subroutine compute_value_of_comparison(welfare_adjusted_1,type_1)

        use global_vars
        use, intrinsic :: ieee_arithmetic

        implicit none

        integer :: financial_index,has_house,track_housing_1
        integer, intent(in) :: type_1
        real(8) :: distribution_1,value_function_1,mass_1
        real(8), intent(inout) :: welfare_adjusted_1

        write(*,*) "type_1 loop=", type_1

        welfare_adjusted_1=0.d0
        mass_1=0.d0

        do age_index=1,1

            if (age_index==1) then
                newborn_household=1
            else
                newborn_household=0
            end if

            do years_left_on_mortgage_index=1,newborn_household*1+(1-newborn_household)*max_amortization_years

                if (years_left_on_mortgage_index>1) then
                    has_house=1
                else
                    has_house=0
                end if

                track_housing_1=1
                if (has_house==0) then
                    if (track_renters_housing==0) then
                        track_housing_1=0
                    end if
                end if

                do unemployment_index=1,unemployment_grid_size
                    do employment_index=1,employment_grid_size
                        do voucher_index=0,(1-has_house)*include_vouchers

                            do financial_index=newborn_household*negative_financial_grid_size+&
                                (1-newborn_household)*(has_house*1+(1-has_house)*renter_floor_by_age(min(max(age_index,1),life_span))),&
                                include_exogenous_endowment*financial_grid_size+(1-include_exogenous_endowment)*&
                                (newborn_household*negative_financial_grid_size+(1-newborn_household)*financial_grid_size)

                                do housing_status_index=(1-has_house)*lowest_housing_grid_point+&
                                    has_house*index_of_smallest_house_hhld_can_buy,&
                                    track_housing_1*(1-newborn_household)*(housing_status_grid_size-1)

                                    value_function_1=value_function_comparison(years_left_on_mortgage_index)%&
                                        vector_real(age_index,financial_index,unemployment_index,&
                                        employment_index,housing_status_index,voucher_index)

                                    distribution_1=distribution_stationary_benchmark&
                                        (years_left_on_mortgage_index)%vector_real&
                                        (age_index,financial_index,unemployment_index,&
                                        employment_index,housing_status_index,voucher_index)

                                    if (distribution_1>0.d0) then
                                        select case (type_1)
                                        case (1)
                                            welfare_adjusted_1=welfare_adjusted_1+value_function_1*distribution_1
                                            mass_1=mass_1+distribution_1
                                        case (2)
                                            if (unemployment_index>threshold_addiction_index) then
                                                welfare_adjusted_1=welfare_adjusted_1+value_function_1*distribution_1
                                                mass_1=mass_1+distribution_1
                                            end if
                                        case (3)
                                            if (unemployment_index<=threshold_addiction_index) then
                                                welfare_adjusted_1=welfare_adjusted_1+value_function_1*distribution_1
                                                mass_1=mass_1+distribution_1
                                            end if
                                        end select
                                    end if

                                end do
                            end do
                        end do
                    end do
                end do

            end do
        end do

        if (mass_1 > 0.d0) then
            welfare_adjusted_1 = welfare_adjusted_1 / mass_1
        else
            welfare_adjusted_1 = ieee_value(welfare_adjusted_1, ieee_quiet_nan)
        end if

        write(*,*) "welfare_adjusted_1=", welfare_adjusted_1
        write(*,*) "mass_1=", mass_1

    end subroutine

    subroutine calculate_homeownership_by_characteristics(time_period)
    
        use Global_Vars
        
        implicit none
        
        integer, intent(in) :: time_period
        integer :: has_house,financial_index,time_period_used,amortization_used,housing_status_index_used,&
            employment_index_to_use,low_quality_market,age_group_1,addiction_choice_2,is_using_drugs,financial_index_used_1,&
            fin_financial_index_move_to_used_1
        real(8) :: distribution_mass_used,lived_in_size_used,consumption_used,total_income,MID_used,&
            total_MID_value,labor_supply_used,avg_income_to_use_1,avg_income_to_use_2,rent_to_income_to_use,&
            addiction_consumption_1,total_consumption_used,bequest_2,income_taxes_paid_used,food_stamps_1,assets_1,&
            avg_net_wealth_to_use_1,frac_next_1,savings_1,total_income_1,mass_of_addicts,financial_income_1,home_equity_1

        ! STATIC STORAGE, BECAUSE THESE ACCUMULATE ACROSS THE TWO PASSES.
        !
        ! Each of these is reset only when accumulating_beta_types is zero,
        ! which is the first pass, and added to on every pass. That is the
        ! right shape for a counter that has to hold both discount-factor
        ! types -- but it is only correct if the value survives from one
        ! call to the next, and a local without save does not. On the
        ! second pass the routine is entered fresh, the reset is skipped,
        ! and the accumulation lands on whatever the stack holds.
        !
        ! It has been working by accident: the calls come from the same
        ! site in the same order, so the frame is usually reused and the
        ! slot usually still holds the first pass's value. That is not a
        ! guarantee, it is a property of this build. save makes it one.
        !
        ! These stay LOCAL rather than moving to module scope on purpose.
        ! total_homeless_1 is the name of two different locals in two
        ! different routines; merging them would pool two counts of the
        ! same population into one divisor.
        save :: mass_of_addicts, total_MID_value

        ! Scratch for the renter income diagnostic below, which has to mirror
        ! the household's own tax function rather than approximate it.
        real(8) :: diag_gross_1,diag_taxable_1

        avg_income_to_use_1=is_counterfactual*average_labor_income_calibrated+&
            (1-is_counterfactual)*model_average_labour_income(time_period)
                        
        time_period_used=time_period-solve_transition_dynamics
        
        if (accumulating_beta_types==0) homeownership_by_employment(time_period,:)=0
        if (accumulating_beta_types==0) tenure_by_employment(time_period,:,:)=0
        if (accumulating_beta_types==0) tenure_by_income_quintile(time_period,:,:)=0
        if (accumulating_beta_types==0) rent_burden_by_income_quintile(time_period,:)=0
        if (accumulating_beta_types==0) MID_share_by_income_quintile(time_period,:)=0
        if (accumulating_beta_types==0) mass_by_income_quintile(time_period,:)=0
        if (accumulating_beta_types==0) MID_itemizers_by_income_quintile(time_period,:)=0
        if (accumulating_beta_types==0) housing_size_by_employment(time_period,:)=0
        if (accumulating_beta_types==0) housing_size_by_employment_and_tenure(time_period,:,:)=0
        if (accumulating_beta_types==0) mass_by_tenure_and_employment(time_period,:,:)=0
        if (accumulating_beta_types==0) housing_size_by_employment_and_age(time_period,:,:)=0
        if (accumulating_beta_types==0) consumption_by_employment_and_age(time_period,:,:)=0
        if (accumulating_beta_types==0) wealth_by_employment_and_age(time_period,:,:)=0
        ! ONE OWNER PER VARIABLE. Reset and accumulation disabled here.
        !
        ! Every reset in the chain is guarded to the FIRST pass, which is safe only
        ! if exactly one routine owns the variable. Where two or more each reset and
        ! each accumulate, the guard that stops pass two resetting also lets each
        ! routine start from whatever the previous one left, so the second pass adds
        ! another copy of the second type on top of a finished total. Four owners of
        ! mass_by_employment made it 5*M where the pooled mass is 2*M, so every
        ! welfare-by-employment average was halved and homeownership_by_employment
        ! came out at 0.4 times truth.
        !
        ! It is the same quantity in every owner, so the FIRST in call order keeps
        ! it and the rest read it. The order is the same in the driver and in
        ! long_run_counter_factual, so the value is always built before it is read.
        ! if (accumulating_beta_types==0) mass_by_employment(time_period,:)=0
        ! ONE OWNER PER VARIABLE. Reset and accumulation disabled here.
        !
        ! Every reset in the chain is guarded to the FIRST pass, which is safe only
        ! if exactly one routine owns the variable. Where two or more each reset and
        ! each accumulate, the guard that stops pass two resetting also lets each
        ! routine start from whatever the previous one left, so the second pass adds
        ! another copy of the second type on top of a finished total. Four owners of
        ! mass_by_employment made it 5*M where the pooled mass is 2*M, so every
        ! welfare-by-employment average was halved and homeownership_by_employment
        ! came out at 0.4 times truth.
        !
        ! It is the same quantity in every owner, so the FIRST in call order keeps
        ! it and the rest read it. The order is the same in the driver and in
        ! long_run_counter_factual, so the value is always built before it is read.
        ! if (accumulating_beta_types==0) mass_by_employment_and_age(time_period,:,:)=0
        if (accumulating_beta_types==0) homeownership_by_age(time_period,:)=0
        if (accumulating_beta_types==0) model_assets_by_age(time_period,:)=0
        if (accumulating_beta_types==0) housing_size_by_age(time_period,:)=0
        ! OWNED BY govt_revenues_calc, WHICH RUNS FIRST. Reset and accumulation disabled here.
        ! mass_by_age was reset AND accumulated in three routines that run in
        ! sequence inside the two-pass loop, every reset guarded to the first pass.
        ! So on pass two each routine added another copy of the second type on top
        ! of what the previous one left: govt_revenues_calc ended at M1+M2, which is
        ! correct, this routine at M1+2*M2, and calculate_homeownership_by_
        ! characteristics at M1+3*M2 -- and the last is where homelessness_by_age
        ! and homeownership_by_age are normalised, so the age profile the author is
        ! reading came out at half its true value.
        !
        ! It is the same quantity in all three, so the first owner's copy is the one
        ! to keep. The call order is govt_revenues_calc, then this, then
        ! calculate_homeownership_by_characteristics, in the driver AND in
        ! long_run_counter_factual, so the value is always built before it is read.
        ! if (accumulating_beta_types==0) mass_by_age(time_period,:)=0
        if (accumulating_beta_types==0) homelessness_by_age(time_period,:)=0
        if (accumulating_beta_types==0) homelessness_by_age_group(time_period,:)=0
        if (accumulating_beta_types==0) val_homeless_band(time_period,:)=0
        if (accumulating_beta_types==0) val_mass_band(time_period,:)=0
        if (accumulating_beta_types==0) val_sud_band(time_period,:)=0
        if (accumulating_beta_types==0) val_homeless_sud_band(time_period,:)=0
        
        if (accumulating_beta_types==0) wealth_by_age_renter(time_period,:)=0
        if (accumulating_beta_types==0) income_by_age_renter(time_period,:)=0
        if (accumulating_beta_types==0) consumption_by_age_renter(time_period,:)=0
        if (accumulating_beta_types==0) consumption_by_age(time_period,:)=0
        if (accumulating_beta_types==0) housing_consumption_by_age_renter(time_period,:)=0
        if (accumulating_beta_types==0) mass_by_age_and_renter(time_period,:)=0
        
        if (accumulating_beta_types==0) model_drug_use_by_income_quintile(time_period,:)=0
        if (accumulating_beta_types==0) mass_by_income_quintile_1(time_period,:)=0

        if (accumulating_beta_types==0) profile_by_income_quintile(time_period,:,:,:)=0
        if (accumulating_beta_types==0) mass_by_income_quintile_2(time_period,:,:)=0
        
        if (accumulating_beta_types==0) model_addicts_consuming_no_drugs(time_period)=0
        if (accumulating_beta_types==0) mass_of_addicts=0
        
        if (accumulating_beta_types==0) total_MID_value=0
        
        if (simulation_ended==(compute_income_cdf+(1-compute_income_cdf)*1)) then
        
            if (is_counterfactual==0) then
        
                call calculate_cdf_of_incomes_earned(time_period,life_span)
                
            end if
        
        end if
        
        do age_index=1,life_span
                    
            if (age_index>(life_span-retirement_span)) then
            
                in_retirement=1
                
            else
            
                in_retirement=0
                
            end if
                                
            do years_left_on_mortgage_index=1,max_amortization_years
                            
                if (years_left_on_mortgage_index>1) then
                    
                    has_house=1
                    
                else
                
                    has_house=0
                    
                end if
                
                do unemployment_index=1,unemployment_grid_size
                
                    do employment_index=1,employment_grid_size
                    
                        avg_income_to_use_2=is_counterfactual*average_labor_income_by_employment_calibrated(employment_index)+&
                                (1-is_counterfactual)*model_average_labour_income_by_employment(time_period,employment_index)
                                                    
                        if (inheritance_function_of_productivity==1) then
                        
                            bequest_2=employment_grid(age_index,employment_index)*inheritance_amount(age_index)+&
                            newborn_age_transfer(age_index)
                        
                        else
                                                    
                            call calculate_bequest_amount(age_index,bequest_2,employment_index)
                            
                        end if

                        do voucher_index=0,(1-has_house)*include_vouchers
                                                    
                            do financial_index=has_house*1+(1-has_house)*renter_floor_by_age(min(max(age_index,1),life_span)),financial_grid_size
                                               
                                do housing_status_index=(1-has_house)*lowest_housing_grid_point+&
                                    has_house*index_of_smallest_house_hhld_can_buy,housing_status_grid_size-1
                                    
                                    financial_index_used_1=policy_function_financial_index(years_left_on_mortgage_index)%&
                                        vector_transition_integer(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)  
                                        
                                    fin_financial_index_move_to_used_1=&
                                        fin_index_frac_mov_to_optimal(years_left_on_mortgage_index)%&
                                        vector_transition_integer(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)  
                                        
                                    frac_next_1=frac_mov_optimal_1(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                        
                                    lived_in_size_used=policy_function_space_lived_in_size(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                                            
                                    amortization_used=policy_function_years_of_amortization_index(years_left_on_mortgage_index)%&
                                        vector_transition_integer(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                
                                    housing_status_index_used=policy_function_housing_status_index(years_left_on_mortgage_index)%&
                                        vector_transition_integer(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    labor_supply_used=policy_function_labor_supply(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    total_consumption_used=policy_function_total_consumption(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                                                            
                                    consumption_used=policy_function_consumption(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                                                                
                                    income_taxes_paid_used=policy_function_wage_income_tax_paid(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    MID_used=policy_function_mortgage_interest_deductions(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                                                                
                                    addiction_choice_2=&
                                        policy_function_addiction(years_left_on_mortgage_index)%&
                                        vector_transition_integer(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    addiction_consumption_1=0
                                        
                                    if (addiction_choice_2>0) then
                                    
                                        addiction_consumption_1=max(total_consumption_used-consumption_used,0.d0)
                                        
                                    end if
                                                                            
                                    distribution_mass_used=distribution_stationary(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period_used,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index) 
                                        
                                    employment_index_to_use=employment_index
                                
                                    if (years_left_on_mortgage_index==1) then
                                    
                                        i=1
                                        
                                    elseif (years_left_on_mortgage_index==2) then
                                    
                                        if (financial_grid(financial_index)<0) then
                                    
                                            i=2
                                            
                                        else
                                        
                                            i=3
                                            
                                        end if
                                        
                                    end if
                                    
                                    if (unemployment_index>threshold_addiction_index) then
                                    
                                        mass_of_addicts=mass_of_addicts+distribution_mass_used
                                            
                                        if (addiction_consumption_1==0) then
                                        
                                            model_addicts_consuming_no_drugs(time_period)=&
                                                model_addicts_consuming_no_drugs(time_period)+&
                                                distribution_mass_used
                                        
                                        end if
                                    
                                    end if
                                    
                                    if (simulation_ended==(compute_income_cdf+(1-compute_income_cdf)*1)) then
                                                    
                                        call calculate_income(unemployment_index,employment_index,total_income,&
                                            avg_income_to_use_1,avg_income_to_use_2,labor_supply_used,in_retirement)
                                            
                                        total_income_1=total_income
                                            
                                        food_stamps_1=0
                                        assets_1=0
                                        avg_net_wealth_to_use_1=1
                                    
                                        ! If they have no assets, they get can qualift for food stamps
                                        if (assets_1<threshold_for_food_stamps_as_perc_of_average_net_wealth*&
                                            avg_net_wealth_to_use_1) then
                                                                                        
                                            food_stamps_1=snap_benefit(actual_household_size(age_index),&
                                                total_income+max(financial_grid(financial_index),0.d0)*&
                                                risk_free_rate(time_period),avg_income_to_use_1)
                                                                        
                                        end if
                                        
                                        home_equity_1=max(years_left_on_mortgage_index-1,0)*housing_price(time_period)*&
                                            housing_size(housing_status_index)*(1+min(financial_grid(financial_index),0.d0))
                                        
                                        financial_income_1=risk_free_rate(time_period)*&
                                            max(financial_grid(financial_index),0.d0)
                                                          
                                        total_income=total_income+bequest_2
                                            
                                        if (use_income_or_income_plus_assets==2) then
                                        
                                            total_income=total_income+financial_income_1+max(financial_grid(financial_index),0.d0)
                                            
                                        elseif (use_income_or_income_plus_assets<=4) then
                                        
                                            total_income=total_income+financial_income_1
!                                                +&
!                                                max(financial_grid(financial_index),0.d0)-&
!                                                income_taxes_paid_used-financial_income_1*investment_income_tax
                                            
                                        end if
                                        
                                        if (use_income_or_income_plus_assets==4) then
                                        
                                            total_income=total_income+home_equity_1
                                        
                                        end if
                                        
                                        if (((in_retirement==1) .AND. (include_retirees_in_income_cdf==1)) .OR. &
                                            (in_retirement==0)) then
                                            
                                            j=number_of_quintiles
                                            
                                            quintile_loop: do k=1,number_of_quintiles-1
                                            
                                                if (total_income<=income_cutoffs_of_quintiles(k)) then
                                            
                                                    j=k
                                                    
                                                    exit quintile_loop
                                                
                                                end if
                                            
                                            end do quintile_loop
                                                                                                                                
                                            if (unemployment_index<=threshold_addiction_index) then
                                            
!                                                x=after_tax_wealth_net_of_expenses_1-&
!                                                    ((frac_used*min(financial_grid(fin_index_frac_used),0.d0)+&
!                                                    (1-frac_used)*min(financial_grid(financial_index_used),0.d0))*&
!                                                    max(amortization_used-1,0)*housing_price(time_period)*housing_size(housing_status_index_used)+&
!                                                    frac_used*max(financial_grid(fin_index_frac_used),0.d0)+&
!                                                    (1-frac_used)*max(financial_grid(financial_index_used),0.d0)+&            
!                                                    (1+consumption_tax)*(consumption_used+frac_spent_on_addiction_used*total_consumption_used))
                                            
                                                mass_by_income_quintile_1(time_period,j)=&
                                                    mass_by_income_quintile_1(time_period,j)+distribution_mass_used
                                                
                                                is_using_drugs=0

                                                if (addiction_consumption_1>0) then
                                                
                                                    is_using_drugs=1

                                                    model_drug_use_by_income_quintile(time_period,j)=&
                                                        model_drug_use_by_income_quintile(time_period,j)+&
                                                        distribution_mass_used
                                                        
                                                end if

                                                mass_by_income_quintile_2(time_period,is_using_drugs,j)=&
                                                    mass_by_income_quintile_2(time_period,is_using_drugs,j)+&
                                                    distribution_mass_used                                        
                                                
                                                profile_by_income_quintile(time_period,is_using_drugs,j,1)=&
                                                    profile_by_income_quintile(time_period,is_using_drugs,j,1)+&
                                                    age_index*distribution_mass_used

                                                profile_by_income_quintile(time_period,is_using_drugs,j,2)=&
                                                    profile_by_income_quintile(time_period,is_using_drugs,j,2)+&
                                                    (consumption_used-food_stamps_1)*distribution_mass_used

                                                profile_by_income_quintile(time_period,is_using_drugs,j,3)=&
                                                    profile_by_income_quintile(time_period,is_using_drugs,j,3)+&
                                                    labor_supply_used*distribution_mass_used

                                                profile_by_income_quintile(time_period,is_using_drugs,j,4)=&
                                                    profile_by_income_quintile(time_period,is_using_drugs,j,4)+&
                                                    total_income*distribution_mass_used

                                                profile_by_income_quintile(time_period,is_using_drugs,j,5)=&
                                                    profile_by_income_quintile(time_period,is_using_drugs,j,5)+&
                                                    max(years_left_on_mortgage_index-1,0)*distribution_mass_used

                                                profile_by_income_quintile(time_period,is_using_drugs,j,6)=&
                                                    profile_by_income_quintile(time_period,is_using_drugs,j,6)+&
                                                    (max(financial_grid(financial_index),0.d0)+&
                                                    max(years_left_on_mortgage_index-1,0)*housing_price(time_period)*&
                                                    housing_size(housing_status_index)*&
                                                    (1+min(financial_grid(financial_index),0.d0)))*distribution_mass_used
                                                    
                                                profile_by_income_quintile(time_period,is_using_drugs,j,7)=&
                                                    profile_by_income_quintile(time_period,is_using_drugs,j,7)+&
                                                    housing_size(housing_status_index)*distribution_mass_used
                                                    
                                                profile_by_income_quintile(time_period,is_using_drugs,j,8)=&
                                                    profile_by_income_quintile(time_period,is_using_drugs,j,8)+&
                                                    max(amortization_used-1,0)*distribution_mass_used
                                                    
                                                profile_by_income_quintile(time_period,is_using_drugs,j,9)=&
                                                    profile_by_income_quintile(time_period,is_using_drugs,j,9)+&
                                                    employment_index*distribution_mass_used
                                                    
                                                savings_1=(1-frac_next_1)*max(financial_grid(financial_index_used_1),0.d0)+&
                                                    frac_next_1*max(financial_grid(fin_financial_index_move_to_used_1),0.d0)+&
                                                    max(amortization_used-1,0)*((1-frac_next_1)*&
                                                    housing_price(time_period)*housing_size(housing_status_index_used)*&
                                                    min(financial_grid(financial_index_used_1),0.d0)+&
                                                    frac_next_1*housing_price(time_period)*housing_size(housing_status_index_used)*&
                                                    min(financial_grid(fin_financial_index_move_to_used_1),0.d0))
                                                                                                        
                                                profile_by_income_quintile(time_period,is_using_drugs,j,10)=&
                                                    profile_by_income_quintile(time_period,is_using_drugs,j,10)+&
                                                    (savings_1-(max(financial_grid(financial_index),0.d0)+&
                                                    max(years_left_on_mortgage_index-1,0)*&
                                                    housing_price(time_period)*housing_size(housing_status_index)*&
                                                    min(financial_grid(financial_index),0.d0)))*distribution_mass_used
                                                    
                                                profile_by_income_quintile(time_period,is_using_drugs,j,11)=&
                                                    profile_by_income_quintile(time_period,is_using_drugs,j,11)+&
                                                    (addiction_consumption_1/price_of_addictive_good)*distribution_mass_used
                                                    
                                                profile_by_income_quintile(time_period,is_using_drugs,j,12)=&
                                                    profile_by_income_quintile(time_period,is_using_drugs,j,12)+&
                                                    min(financial_grid(financial_index),0.d0)*distribution_mass_used
                                                    
                                                profile_by_income_quintile(time_period,is_using_drugs,j,13)=&
                                                    profile_by_income_quintile(time_period,is_using_drugs,j,13)+&
                                                    max(financial_grid(financial_index),0.d0)*distribution_mass_used
                                                    
                                                if ((housing_status_index_used>second_lowest_housing_grid_point) .OR. &
                                                   (have_two_rental_markets==0)) then
                                                
                                                    low_quality_market=0
                                                
                                                else
                                                
                                                    low_quality_market=1
                                                
                                                end if                                    
                                                    
                                                profile_by_income_quintile(time_period,is_using_drugs,j,14)=&
                                                    profile_by_income_quintile(time_period,is_using_drugs,j,14)+&
                                                    (max(years_left_on_mortgage_index-1,0)*&
                                                    housing_price(time_period)*housing_size(housing_status_index)*&
                                                    (-min(financial_grid(financial_index),0.d0)*&
                                                    risk_free_rate(time_period)+housing_depreciation_rate+&
                                                    property_tax(time_period))+rent(time_period,low_quality_market)*&
                                                    (1-max(years_left_on_mortgage_index-1,0))*&
                                                    housing_size(housing_status_index))*distribution_mass_used
                                                    
                                                profile_by_income_quintile(time_period,is_using_drugs,j,15)=&
                                                    profile_by_income_quintile(time_period,is_using_drugs,j,15)+&
                                                    income_taxes_paid_used*distribution_mass_used
                                                    
                                                profile_by_income_quintile(time_period,is_using_drugs,j,16)=&
                                                    profile_by_income_quintile(time_period,is_using_drugs,j,16)+&
                                                    total_income_1*distribution_mass_used
                                                                                                      
                                            end if
                                                                                                                                                                                                                            
                                            tenure_by_income_quintile(time_period,j,i)=&
                                                tenure_by_income_quintile(time_period,j,i)+distribution_mass_used
                                                
                                            if ((amortization_used<=1) .AND. &
                                                (housing_status_index_used>lowest_housing_grid_point)) then
                                                
                                                if ((housing_status_index_used>second_lowest_housing_grid_point) .OR. &
                                                    (have_two_rental_markets==0))  then
                                                
                                                    low_quality_market=0
                                                
                                                else
                                                
                                                    low_quality_market=1
                                                
                                                end if
                                                
                                                rent_to_income_to_use=&
                                                    rent(time_period,low_quality_market)*housing_size(housing_status_index_used)/&
                                                    total_income
                                                    
                                                mass_renters_by_income_quintile(time_period,j)=&
                                                    mass_renters_by_income_quintile(time_period,j)+distribution_mass_used
                                                    
                                                if ((rent_to_income_to_use>=0.3) .OR. (total_income==0)) then
                                                
                                                    rent_burden_by_income_quintile(time_period,j)=&
                                                        rent_burden_by_income_quintile(time_period,j)+distribution_mass_used
                                                        
                                                end if
                                                
                                            end if                                     
                                                
                                            MID_share_by_income_quintile(time_period,j)=&
                                                MID_share_by_income_quintile(time_period,j)+&
                                                MID_used*distribution_mass_used
                                                
                                            mass_by_income_quintile(time_period,j)=&
                                                mass_by_income_quintile(time_period,j)+distribution_mass_used
                                                
                                            if (MID_used>0) then
                                            
                                                MID_itemizers_by_income_quintile(time_period,j)=&
                                                    MID_itemizers_by_income_quintile(time_period,j)+&
                                                    distribution_mass_used
                                                    
                                            end if
                                                
                                        end if
                                        
                                    end if
                                    
                                    total_MID_value=total_MID_value+MID_used*distribution_mass_used
                                                                    
                                    tenure_by_employment(time_period,employment_index_to_use,i)=&
                                        tenure_by_employment(time_period,employment_index_to_use,i)+distribution_mass_used
                                        
                                    housing_size_by_employment_and_tenure(time_period,employment_index_to_use,i)=&
                                        housing_size_by_employment_and_tenure(time_period,employment_index_to_use,i)+&
                                        lived_in_size_used*distribution_mass_used
                                        
                                    mass_by_tenure_and_employment(time_period,employment_index_to_use,i)=&
                                        mass_by_tenure_and_employment(time_period,employment_index_to_use,i)+&
                                        distribution_mass_used
                        
                                    homeownership_by_employment(time_period,employment_index_to_use)=&
                                        homeownership_by_employment(time_period,employment_index_to_use)+&
                                        max(min(amortization_used-1,1),0)*distribution_mass_used
                                        
                                    housing_size_by_employment(time_period,employment_index_to_use)=& 
                                        housing_size_by_employment(time_period,employment_index_to_use)+&
                                        lived_in_size_used*distribution_mass_used
                                        
                                    housing_size_by_employment_and_age(time_period,employment_index_to_use,age_index)=& 
                                        housing_size_by_employment_and_age(time_period,employment_index_to_use,age_index)+&
                                        lived_in_size_used*distribution_mass_used
                                        
                                    consumption_by_employment_and_age(time_period,employment_index_to_use,age_index)=& 
                                        consumption_by_employment_and_age(time_period,employment_index_to_use,age_index)+&
                                        consumption_used*distribution_mass_used
                                        
                                    wealth_by_employment_and_age(time_period,employment_index_to_use,age_index)=&
                                        wealth_by_employment_and_age(time_period,employment_index_to_use,age_index)+&
                                        (housing_price(time_period)*housing_size(housing_status_index)*&
                                        (max(min(years_left_on_mortgage_index-1,1),0)+&
                                        min(financial_grid(financial_index),0.d0))+&
                                        max(financial_grid(financial_index),0.d0))*distribution_mass_used
                                                                
                                    ! ONE OWNER PER VARIABLE. Reset and accumulation disabled here.
                                    !
                                    ! Every reset in the chain is guarded to the FIRST pass, which is safe only
                                    ! if exactly one routine owns the variable. Where two or more each reset and
                                    ! each accumulate, the guard that stops pass two resetting also lets each
                                    ! routine start from whatever the previous one left, so the second pass adds
                                    ! another copy of the second type on top of a finished total. Four owners of
                                    ! mass_by_employment made it 5*M where the pooled mass is 2*M, so every
                                    ! welfare-by-employment average was halved and homeownership_by_employment
                                    ! came out at 0.4 times truth.
                                    !
                                    ! It is the same quantity in every owner, so the FIRST in call order keeps
                                    ! it and the rest read it. The order is the same in the driver and in
                                    ! long_run_counter_factual, so the value is always built before it is read.
                                    ! mass_by_employment(time_period,employment_index_to_use)=&
                                    ! mass_by_employment(time_period,employment_index_to_use)+distribution_mass_used
                                        
                                    ! ONE OWNER PER VARIABLE. Reset and accumulation disabled here.
                                    !
                                    ! Every reset in the chain is guarded to the FIRST pass, which is safe only
                                    ! if exactly one routine owns the variable. Where two or more each reset and
                                    ! each accumulate, the guard that stops pass two resetting also lets each
                                    ! routine start from whatever the previous one left, so the second pass adds
                                    ! another copy of the second type on top of a finished total. Four owners of
                                    ! mass_by_employment made it 5*M where the pooled mass is 2*M, so every
                                    ! welfare-by-employment average was halved and homeownership_by_employment
                                    ! came out at 0.4 times truth.
                                    !
                                    ! It is the same quantity in every owner, so the FIRST in call order keeps
                                    ! it and the rest read it. The order is the same in the driver and in
                                    ! long_run_counter_factual, so the value is always built before it is read.
                                    ! mass_by_employment_and_age(time_period,employment_index_to_use,age_index)=&
                                    ! mass_by_employment_and_age(time_period,employment_index_to_use,age_index)+&
                                    ! distribution_mass_used
                                        
                                    consumption_by_age(time_period,age_index)=consumption_by_age(time_period,age_index)+&
                                        consumption_used*distribution_mass_used
                                                                
                                    homeownership_by_age(time_period,age_index)=homeownership_by_age(time_period,age_index)+&
                                        max(min(amortization_used-1,1),0)*distribution_mass_used
                                        
                                    model_assets_by_age(time_period,age_index)=model_assets_by_age(time_period,age_index)+&
                                        (housing_price(time_period)*housing_size(housing_status_index)*&
                                        (max(min(years_left_on_mortgage_index-1,1),0)+&
                                        min(financial_grid(financial_index),0.d0))+&
                                        max(financial_grid(financial_index),0.d0))*distribution_mass_used
                                    
                                    housing_size_by_age(time_period,age_index)=housing_size_by_age(time_period,age_index)+&
                                        lived_in_size_used*distribution_mass_used
                                    
                                    ! OWNED BY govt_revenues_calc, WHICH RUNS FIRST. Reset and accumulation disabled here.
                                    ! mass_by_age was reset AND accumulated in three routines that run in
                                    ! sequence inside the two-pass loop, every reset guarded to the first pass.
                                    ! So on pass two each routine added another copy of the second type on top
                                    ! of what the previous one left: govt_revenues_calc ended at M1+M2, which is
                                    ! correct, this routine at M1+2*M2, and calculate_homeownership_by_
                                    ! characteristics at M1+3*M2 -- and the last is where homelessness_by_age
                                    ! and homeownership_by_age are normalised, so the age profile the author is
                                    ! reading came out at half its true value.
                                    !
                                    ! It is the same quantity in all three, so the first owner's copy is the one
                                    ! to keep. The call order is govt_revenues_calc, then this, then
                                    ! calculate_homeownership_by_characteristics, in the driver AND in
                                    ! long_run_counter_factual, so the value is always built before it is read.
                                    ! mass_by_age(time_period,age_index)=mass_by_age(time_period,age_index)+&
                                    ! distribution_mass_used

                                    ! THE HOMELESSNESS RATE BY BAND NEEDS ITS OWN
                                    ! DENOMINATOR. homelessness_by_age_group is
                                    ! normalised to shares of the homeless, which
                                    ! is the table's second row and not its
                                    ! first, and homelessness_by_age is divided
                                    ! through by mass_by_age further down, so
                                    ! neither can be recombined into a rate after
                                    ! the fact. This carries the band's total
                                    ! mass beside the band's homeless mass.
                                    if (age_index<=9) then
                                        val_band_1=1
                                    elseif (age_index<=19) then
                                        val_band_1=2
                                    elseif (age_index<=29) then
                                        val_band_1=3
                                    elseif (age_index<=39) then
                                        val_band_1=4
                                    else
                                        val_band_1=5
                                    end if

                                    val_mass_band(time_period,val_band_1)=&
                                        val_mass_band(time_period,val_band_1)+distribution_mass_used

                                    if (housing_status_index_used==lowest_housing_grid_point) then
                                        val_homeless_band(time_period,val_band_1)=&
                                            val_homeless_band(time_period,val_band_1)+distribution_mass_used
                                    end if

                                    ! CARRYING THE DISORDER, which is the test on
                                    ! the unemployment index and NOT is_addicted,
                                    ! since that one means consumes drugs.
                                    if (unemployment_index>threshold_addiction_index) then

                                        val_sud_band(time_period,val_band_1)=&
                                            val_sud_band(time_period,val_band_1)+distribution_mass_used

                                        if (housing_status_index_used==lowest_housing_grid_point) then
                                            val_homeless_sud_band(time_period,val_band_1)=&
                                                val_homeless_sud_band(time_period,val_band_1)+distribution_mass_used
                                        end if

                                    end if

                                    if (housing_status_index_used==lowest_housing_grid_point) then
                                    
                                        homelessness_by_age(time_period,age_index)=homelessness_by_age(time_period,age_index)+&
                                            distribution_mass_used                                            
                                            
                                        if (age_index<=9) then
                                        
                                            age_group_1=1
                                            
                                        elseif (age_index<=19) then
                                        
                                            age_group_1=2
                                            
                                        elseif (age_index<=29) then
                                        
                                            age_group_1=3
                                            
                                        elseif (age_index<=39) then
                                        
                                            age_group_1=4
                                            
                                        else
                                        
                                            age_group_1=5
                                            
                                        end if
                                        
                                        homelessness_by_age_group(time_period,age_group_1)=&
                                            homelessness_by_age_group(time_period,age_group_1)+distribution_mass_used
                                            
                                    end if
                                        
                                    if (amortization_used<=1) then
                                        
                                        wealth_by_age_renter(time_period,age_index)=wealth_by_age_renter(time_period,age_index)+&
                                            (housing_price(time_period)*housing_size(housing_status_index)*&
                                            (max(min(years_left_on_mortgage_index-1,1),0)+&
                                            min(financial_grid(financial_index),0.d0))+&
                                            max(financial_grid(financial_index),0.d0))*distribution_mass_used
                                                                                    
                                        if (in_retirement==1) then

                                            ! A RETIREE'S OWN PENSION, NOT THE ECONOMY'S AVERAGE WAGE.
                                            !
                                            ! This added model_average_labour_income -- an AGGREGATE --
                                            ! to a per-household accumulator, so every retired renter
                                            ! was recorded with the same income regardless of the type
                                            ! they retired as, and that income was not a pension at
                                            ! all. In the point file the column jumped from 0.4872 at
                                            ! age 65 to 12.2973 at 66 and then sat flat to 85, varying
                                            ! only in the fourth decimal from the interest term below.
                                            !
                                            ! It read as a twenty-five-fold rise in income at
                                            ! retirement, which is what it was mistaken for while
                                            ! working out why the old are homeless. The model itself is
                                            ! unaffected -- income_by_age_renter is written to the DIAG
                                            ! line and read nowhere else -- but it is exactly the column
                                            ! anyone would use to answer that question.
                                            !
                                            ! calculate_income is what the MODEL uses for a retiree, so
                                            ! it is called here rather than the benefit being rebuilt:
                                            ! that keeps the social security formula, the SSI floor and
                                            ! the reductions for a retired household with a disorder in
                                            ! one place instead of two.
                                            call calculate_income(unemployment_index,employment_index,&
                                                diag_gross_1,avg_income_to_use_1,avg_income_to_use_1,&
                                                labor_supply_used,in_retirement)

                                            income_by_age_renter(time_period,age_index)=&
                                                income_by_age_renter(time_period,age_index)+&
                                                diag_gross_1*distribution_mass_used

                                        else
                                        
                                            if ((emp_of(unemployment_index)==1)) then

                                                ! THE HOUSEHOLD'S OWN TAX FUNCTION, NOT AN APPROXIMATION OF IT.
                                                !
                                                ! This subtracted taxable**curvature and left out
                                                ! labor_income_tax_rate altogether, where the budget
                                                ! constraint subtracts taxable - rate*taxable**curvature
                                                ! and floors the result at zero. With the rate at 0.75
                                                ! and the curvature at 0.85 the difference is not small:
                                                ! a taxable income of 0.04 pays NOTHING in the model,
                                                ! because 0.04 - 0.752*0.0655 is negative and the floor
                                                ! catches it, and paid 0.0655 here -- more than the whole
                                                ! income. So this line printed NEGATIVE income for every
                                                ! renter aged 26 to 38, which is the diagnostic and not
                                                ! the model, and it is the obvious wrong explanation for
                                                ! why the young are the ones who are homeless.
                                                !
                                                ! The deduction is still left out. It is per household
                                                ! and not available here, and it only ever reduces the
                                                ! tax, so what is printed is a lower bound on income
                                                ! rather than a number that can go through zero.
                                                diag_gross_1=labor_supply_used*&
                                                    employment_grid(age_index,employment_index)*&
                                                    labour_deterministic_efficiency(age_index)
                                                diag_taxable_1=max(diag_gross_1-personal_exemption,0.d0)

                                                income_by_age_renter(time_period,age_index)=&
                                                    income_by_age_renter(time_period,age_index)+&
                                                    (diag_gross_1-&
                                                    max(diag_taxable_1-&
                                                    (labor_income_tax_rate+increase_in_labour_income_tax)*&
                                                    diag_taxable_1**curvature_of_labor_income_taxes,0.d0))*&
                                                    distribution_mass_used
                                                    
                                            else
                                            
                                                ! The mass MULTIPLIES the income here. It was a plus
                                                ! sign, which added the population to the income and
                                                ! made this accumulator neither one thing nor the
                                                ! other; every sibling accumulator uses a product.
                                                income_by_age_renter(time_period,age_index)=&
                                                    income_by_age_renter(time_period,age_index)+&
                                                    out_of_work_income(unemployment_index,employment_index,&
                                                    avg_income_to_use_1)*distribution_mass_used
                                            
                                            end if
                                                
                                        end if
                                        
                                        income_by_age_renter(time_period,age_index)=&
                                            income_by_age_renter(time_period,age_index)+&
                                            (risk_free_rate(time_period)*max(financial_grid(financial_index),0.d0)+unsecured_borrowing_rate*min(financial_grid(financial_index),0.d0))*&
                                            distribution_mass_used
                                        
                                        consumption_by_age_renter(time_period,age_index)=&
                                            consumption_by_age_renter(time_period,age_index)+consumption_used*distribution_mass_used
                                            
                                        housing_consumption_by_age_renter(time_period,age_index)=&
                                            housing_consumption_by_age_renter(time_period,age_index)+&
                                            lived_in_size_used*distribution_mass_used
                                            
                                        mass_by_age_and_renter(time_period,age_index)=&
                                            mass_by_age_and_renter(time_period,age_index)+distribution_mass_used
                                                                    
                                    end if
                                    
                                end do
                                
                            end do
                                
                        end do
                        
                    end do
                        
                end do
                                                    
            end do
                
        end do

        do k=0,1

            do j=1,number_of_quintiles

                do i=1,number_of_profiles_for_income

                    if (current_beta_type==number_of_beta_types) then
                        profile_by_income_quintile(time_period,k,j,i)=&
                            profile_by_income_quintile(time_period,k,j,i)/&
                            mass_by_income_quintile_2(time_period,k,j)
                    end if

                end do

            end do

        end do
                                                
        if (current_beta_type==number_of_beta_types) then
            model_drug_use_by_income_quintile(time_period,:)=&
                model_drug_use_by_income_quintile(time_period,:)/&
                mass_by_income_quintile_1(time_period,:)
        end if
        
        if (current_beta_type==number_of_beta_types) then
            homelessness_by_age_group(time_period,:)=&
                homelessness_by_age_group(time_period,:)/sum(homelessness_by_age_group(time_period,:))
        end if
        
        do age_index=1,life_span
        
            if (current_beta_type==number_of_beta_types) then
                wealth_by_age_renter(time_period,age_index)=&
                    wealth_by_age_renter(time_period,age_index)/mass_by_age_and_renter(time_period,age_index)
            end if
                
            if (current_beta_type==number_of_beta_types) then
                income_by_age_renter(time_period,age_index)=&
                    income_by_age_renter(time_period,age_index)/mass_by_age_and_renter(time_period,age_index)
            end if
                
            if (current_beta_type==number_of_beta_types) then
                consumption_by_age_renter(time_period,age_index)=&
                    consumption_by_age_renter(time_period,age_index)/mass_by_age_and_renter(time_period,age_index)
            end if
            
            if (current_beta_type==number_of_beta_types) then
                housing_consumption_by_age_renter(time_period,age_index)=&
                    housing_consumption_by_age_renter(time_period,age_index)/mass_by_age_and_renter(time_period,age_index)
            end if
            
        end do
        
        do years_left_on_mortgage_index=1,3
        
            do employment_index=1,employment_grid_size
            
                if (current_beta_type==number_of_beta_types) then
                    housing_size_by_employment_and_tenure(time_period,employment_index,years_left_on_mortgage_index)=&
                        housing_size_by_employment_and_tenure(time_period,employment_index,years_left_on_mortgage_index)/&
                        mass_by_tenure_and_employment(time_period,employment_index,years_left_on_mortgage_index)
                end if
            
            end do
            
        end do
                         
        do employment_index=1,employment_grid_size
        
            if (current_beta_type==number_of_beta_types) then
                homeownership_by_employment(time_period,employment_index)=&
                    homeownership_by_employment(time_period,employment_index)/mass_by_employment(time_period,employment_index)
            end if
            
            if (current_beta_type==number_of_beta_types) then
                housing_size_by_employment(time_period,employment_index)=&
                    housing_size_by_employment(time_period,employment_index)/mass_by_employment(time_period,employment_index)
            end if
                                
        end do
        
        do age_index=1,life_span
        
            do employment_index=1,1,employment_grid_size
        
                if (current_beta_type==number_of_beta_types) then
                    housing_size_by_employment_and_age(time_period,employment_index,age_index)=&
                        housing_size_by_employment_and_age(time_period,employment_index,age_index)/&
                        mass_by_employment_and_age(time_period,employment_index,age_index)
                end if
            
                if (current_beta_type==number_of_beta_types) then
                    consumption_by_employment_and_age(time_period,employment_index,age_index)=&
                        consumption_by_employment_and_age(time_period,employment_index,age_index)/&
                        mass_by_employment_and_age(time_period,employment_index,age_index)
                end if
                    
                if (current_beta_type==number_of_beta_types) then
                    wealth_by_employment_and_age(time_period,employment_index,age_index)=&
                        wealth_by_employment_and_age(time_period,employment_index,age_index)/&
                        mass_by_employment_and_age(time_period,employment_index,age_index)
                end if
                    
                if (current_beta_type==number_of_beta_types) then
                    consumption_by_age(time_period,age_index)=consumption_by_age(time_period,age_index)/&
                        mass_by_age(time_period,age_index)
                end if
                                        
            end do
                                
        end do
        
        do age_index=1,life_span
                
            if (current_beta_type==number_of_beta_types) then
                homeownership_by_age(time_period,age_index)=homeownership_by_age(time_period,age_index)/&
                    mass_by_age(time_period,age_index)
            end if
                
            if (current_beta_type==number_of_beta_types) then
                model_assets_by_age(time_period,age_index)=model_assets_by_age(time_period,age_index)/&
                    mass_by_age(time_period,age_index)
            end if
          
            if (current_beta_type==number_of_beta_types) then
                housing_size_by_age(time_period,age_index)=housing_size_by_age(time_period,age_index)/&
                    mass_by_age(time_period,age_index)
            end if
                
            if (current_beta_type==number_of_beta_types) then
                homelessness_by_age(time_period,age_index)=homelessness_by_age(time_period,age_index)/&
                    mass_by_age(time_period,age_index)
            end if
                                        
        end do
        
        ! NORMALISE ONLY ON THE LAST PASS. This division puts its result back
        ! into the accumulator it reads, and the reset above is guarded to the
        ! FIRST pass, so without this guard the second pass divides an already
        ! divided value again and adds the second type on top of a finished
        ! average. Nothing at one type moves: the condition is 1==1 there.
        if (current_beta_type==number_of_beta_types) then
            MID_share_by_income_quintile(time_period,:)=&
                MID_share_by_income_quintile(time_period,:)/total_MID_value
        end if
            
        ! NORMALISE ONLY ON THE LAST PASS. This division puts its result back
        ! into the accumulator it reads, and the reset above is guarded to the
        ! FIRST pass, so without this guard the second pass divides an already
        ! divided value again and adds the second type on top of a finished
        ! average. Nothing at one type moves: the condition is 1==1 there.
        if (current_beta_type==number_of_beta_types) then
            MID_itemizers_by_income_quintile(time_period,:)=&
                MID_itemizers_by_income_quintile(time_period,:)/mass_by_income_quintile(time_period,:)
        end if
        
        if (simulation_ended==(compute_income_cdf+(1-compute_income_cdf)*1))  then
                
            do k=1,number_of_quintiles
            
!                write(*,*) "income_cutoffs_of_quintiles(k)", income_cutoffs_of_quintiles(min(k,number_of_quintiles-1))
!                write(*,*) "tenure_by_income_quintile=", sum(tenure_by_income_quintile(time_period,k,:))
!                write(*,*) "mass_of_quintile=", mass_of_quintile(k)
            
            end do
            
        end if
        
        if (current_beta_type==number_of_beta_types) then
            rent_burden_by_income_quintile(time_period,:)=&
                rent_burden_by_income_quintile(time_period,:)/mass_renters_by_income_quintile(time_period,:)
        end if
                                                    
        if (current_beta_type==number_of_beta_types) then
            model_addicts_consuming_no_drugs(time_period)=&
                model_addicts_consuming_no_drugs(time_period)/mass_of_addicts
        end if
            
    end subroutine
    
    subroutine frac_of_households_in_support_of_policy(time_period)
    
        use Global_Vars
        
        implicit none
        
        integer :: financial_index,time_period,has_house,employment_index_to_use
        character*1 :: string_used
        real(8) :: distribution_mass_used,value_function_used,value_function_benchamrk_used,&
            total_addicted_1,total_addicted_youngest_1
                        
        frac_in_support(time_period)=0
        frac_in_support_youngest(time_period)=0
        
        frac_in_support_addicted(time_period)=0
        frac_in_support_addicted_youngest(time_period)=0
        total_addicted_1=0
        total_addicted_youngest_1=0
        
        frac_in_support_by_tenure_and_employment(time_period,:,:)=0
        mass_by_tenure_and_employment(time_period,:,:)=0
        
        average_welfare_of_winners(time_period)=0
        average_welfare_of_winners_benchmark(time_period)=0
                
        do i=1,2
        
            write(string_used,'(i1)') i
    
            open(unit=9,file="value_function"//trim(string_used)//trim(benchmark_simulation)//".dat",action='read')
                read(9,'(F35.13)') value_function_benchmark(i)%vector_real(:,:,:,:,:,:)
            close(9)
            open(unit=10,file="distribution_stationary"//trim(string_used)//trim(benchmark_simulation)//".dat",action='read')
                read(10,'(F30.28)') distribution_stationary_benchmark(i)%vector_real(:,:,:,:,:,:)
            close(10)
            
        end do
                            
        do age_index=1,life_span
                            
            do years_left_on_mortgage_index=1,max_amortization_years
                            
                if (years_left_on_mortgage_index>1) then
                    
                    has_house=1
                    
                else
                
                    has_house=0
                    
                end if
                                    
                do unemployment_index=1,unemployment_grid_size
                
                    do employment_index=1,employment_grid_size
                    
                        do voucher_index=0,(1-has_house)*include_vouchers
                                    
                            do financial_index=has_house*1+(1-has_house)*renter_floor_by_age(min(max(age_index,1),life_span)),financial_grid_size
                                               
                                do housing_status_index=(1-has_house)*lowest_housing_grid_point+&
                                    has_house*index_of_smallest_house_hhld_can_buy,housing_status_grid_size-1
                                                
                                    if (years_left_on_mortgage_index==0) then
                                    
                                        i=0
                                    
                                    elseif (years_left_on_mortgage_index==1) then
                                    
                                        i=1
                                        
                                    elseif (years_left_on_mortgage_index==2) then
                                    
                                        if (financial_grid(financial_index)<0) then
                                    
                                            i=3
                                            
                                        else
                                        
                                            i=2
                                            
                                        end if
                                        
                                    end if
                                    
                                    distribution_mass_used=distribution_stationary_benchmark(years_left_on_mortgage_index)%&
                                        vector_real(age_index,financial_index,unemployment_index,&
                                        employment_index,housing_status_index,voucher_index)
                                                                        
                                    value_function_used=value_function(max(years_left_on_mortgage_index,1))%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                        
                                    value_function_benchamrk_used=value_function_benchmark(years_left_on_mortgage_index)%&
                                        vector_real(age_index,financial_index,unemployment_index,employment_index,&
                                        housing_status_index,voucher_index)
                                        
                                    employment_index_to_use=employment_index
                                
                                    mass_by_tenure_and_employment(time_period,employment_index_to_use,max(i,1))=&
                                        mass_by_tenure_and_employment(time_period,employment_index_to_use,max(i,1))+&
                                        distribution_mass_used
                                        
                                    if (unemployment_index>threshold_addiction_index) then
                                    
                                        total_addicted_1=total_addicted_1+distribution_mass_used
                                        
                                        if (age_index==1) then
                                        
                                            total_addicted_youngest_1=total_addicted_youngest_1+distribution_mass_used
                                            
                                        end if
                                        
                                    end if
                                                                           
                                    if (value_function_used>value_function_benchamrk_used) then
                                                
                                        if (age_index==1) then
                                                
                                            frac_in_support_youngest(time_period)=&
                                                frac_in_support_youngest(time_period)+distribution_mass_used
                                                
                                            if (unemployment_index>threshold_addiction_index) then
                                            
                                                frac_in_support_addicted_youngest(time_period)=&
                                                    frac_in_support_addicted_youngest(time_period)+distribution_mass_used
                                                                                            
                                            end if
                                                                                                
                                        end if
                                                        
                                        frac_in_support(time_period)=frac_in_support(time_period)+distribution_mass_used
                                        
                                        if (unemployment_index>threshold_addiction_index) then
                                            
                                            frac_in_support_addicted(time_period)=&
                                                frac_in_support_addicted(time_period)+distribution_mass_used
                                                                                        
                                        end if
                                                                                    
                                        frac_in_support_by_tenure_and_employment(time_period,employment_index_to_use,max(i,1))=&
                                            frac_in_support_by_tenure_and_employment(time_period,employment_index_to_use,max(i,1))+&
                                            distribution_mass_used
                                            
                                        average_welfare_of_winners(time_period)=average_welfare_of_winners(time_period)+&
                                            distribution_mass_used*value_function_used
                                            
                                        average_welfare_of_winners_benchmark(time_period)=&
                                            average_welfare_of_winners_benchmark(time_period)+&
                                            distribution_mass_used*value_function_benchamrk_used
                                            
                                    end if
                                                                    
                                end do
                                
                            end do
                         
                         end do
                         
                    end do
                    
                end do
                    
            end do
            
        end do
        
        frac_in_support_addicted_youngest(time_period)=&
            frac_in_support_addicted_youngest(time_period)/total_addicted_youngest_1
            
        frac_in_support_addicted(time_period)=&
            frac_in_support_addicted(time_period)/total_addicted_1
        
        average_welfare_of_winners(time_period)=average_welfare_of_winners(time_period)/frac_in_support(time_period)
            
        average_welfare_of_winners_benchmark(time_period)=&
            average_welfare_of_winners_benchmark(time_period)/frac_in_support(time_period)

        sum_of_distribution=0
        
        do i=1,2
                
            sum_of_distribution=sum_of_distribution+&
                sum(distribution_stationary(i)%vector_transition_real(time_period,:,:,:,:,:,:))
            
        end do
        
        sum_of_distribution_youngest=0
        
        do i=1,2
                
            sum_of_distribution_youngest=sum_of_distribution_youngest+&
                sum(distribution_stationary(i)%vector_transition_real(time_period,1,:,:,:,:,:))
            
        end do
                
        do i=1,3
        
            do j=1,employment_grid_size
                            
                frac_in_support_by_tenure_and_employment(time_period,j,i)=&
                    frac_in_support_by_tenure_and_employment(time_period,j,i)/&
                    mass_by_tenure_and_employment(time_period,j,i)
                                    
            end do
            
        end do
                                
        frac_in_support(time_period)=frac_in_support(time_period)/sum_of_distribution
        
        frac_in_support_youngest(time_period)=frac_in_support_youngest(time_period)/sum_of_distribution_youngest
                            
        if (solve_transition_dynamics==0) then
        
            write(*,*) "frac_in_support(",time_period,")=", frac_in_support(time_period)
            write(*,*) "frac_in_support_youngest(",time_period,")=", frac_in_support_youngest(time_period)
            
        end if
            
    end subroutine
        
    subroutine copy_housing_state_slice(time_period,from_1,to_1)

        ! Copy every policy and the value function from one previous dwelling
        ! index to another. Only called where the two are provably the same
        ! problem, which is checked by the caller rather than here.

        use Global_Vars

        implicit none

        integer, intent(in) :: time_period,from_1,to_1
        integer :: k_1

        do k_1=1,newborn_household*1+(1-newborn_household)*max_amortization_years

            value_function(k_1)%vector_transition_real(time_period,age_index,:,:,:,to_1,:)=&
                value_function(k_1)%vector_transition_real(time_period,age_index,:,:,:,from_1,:)

            policy_function_consumption(k_1)%vector_transition_real(time_period,age_index,:,:,:,to_1,:)=&
                policy_function_consumption(k_1)%vector_transition_real(time_period,age_index,:,:,:,from_1,:)

            policy_function_total_consumption(k_1)%vector_transition_real(time_period,age_index,:,:,:,to_1,:)=&
                policy_function_total_consumption(k_1)%vector_transition_real(time_period,age_index,:,:,:,from_1,:)

            policy_function_frac_spent_on_addiction(k_1)%vector_transition_real(time_period,age_index,:,:,:,to_1,:)=&
                policy_function_frac_spent_on_addiction(k_1)%vector_transition_real(time_period,age_index,:,:,:,from_1,:)

            policy_function_labor_supply(k_1)%vector_transition_real(time_period,age_index,:,:,:,to_1,:)=&
                policy_function_labor_supply(k_1)%vector_transition_real(time_period,age_index,:,:,:,from_1,:)

            policy_function_cutoff_taxable_income(k_1)%vector_transition_real(time_period,age_index,:,:,:,to_1,:)=&
                policy_function_cutoff_taxable_income(k_1)%vector_transition_real(time_period,age_index,:,:,:,from_1,:)

            policy_function_wage_income_tax_paid(k_1)%vector_transition_real(time_period,age_index,:,:,:,to_1,:)=&
                policy_function_wage_income_tax_paid(k_1)%vector_transition_real(time_period,age_index,:,:,:,from_1,:)

            policy_function_mortgage_interest_deductions(k_1)%vector_transition_real(time_period,age_index,:,:,:,to_1,:)=&
                policy_function_mortgage_interest_deductions(k_1)%vector_transition_real(time_period,age_index,:,:,:,from_1,:)

            policy_function_space_lived_in_size(k_1)%vector_transition_real(time_period,age_index,:,:,:,to_1,:)=&
                policy_function_space_lived_in_size(k_1)%vector_transition_real(time_period,age_index,:,:,:,from_1,:)

            frac_mov_optimal_1(k_1)%vector_transition_real(time_period,age_index,:,:,:,to_1,:)=&
                frac_mov_optimal_1(k_1)%vector_transition_real(time_period,age_index,:,:,:,from_1,:)

            policy_function_financial_index(k_1)%vector_transition_integer(time_period,age_index,:,:,:,to_1,:)=&
                policy_function_financial_index(k_1)%vector_transition_integer(time_period,age_index,:,:,:,from_1,:)

            policy_function_housing_status_index(k_1)%vector_transition_integer(time_period,age_index,:,:,:,to_1,:)=&
                policy_function_housing_status_index(k_1)%vector_transition_integer(time_period,age_index,:,:,:,from_1,:)

            policy_function_space_lived_in_index(k_1)%vector_transition_integer(time_period,age_index,:,:,:,to_1,:)=&
                policy_function_space_lived_in_index(k_1)%vector_transition_integer(time_period,age_index,:,:,:,from_1,:)

            policy_function_years_of_amortization_index(k_1)%vector_transition_integer(time_period,age_index,:,:,:,to_1,:)=&
                policy_function_years_of_amortization_index(k_1)%vector_transition_integer(time_period,age_index,:,:,:,from_1,:)

            policy_function_addiction(k_1)%vector_transition_integer(time_period,age_index,:,:,:,to_1,:)=&
                policy_function_addiction(k_1)%vector_transition_integer(time_period,age_index,:,:,:,from_1,:)

            policy_function_treatment(k_1)%vector_transition_integer(time_period,age_index,:,:,:,to_1,:)=&
                policy_function_treatment(k_1)%vector_transition_integer(time_period,age_index,:,:,:,from_1,:)

            fin_index_frac_mov_to_optimal(k_1)%vector_transition_integer(time_period,age_index,:,:,:,to_1,:)=&
                fin_index_frac_mov_to_optimal(k_1)%vector_transition_integer(time_period,age_index,:,:,:,from_1,:)

        end do

    end subroutine

    subroutine solve_value_function_and_policy_functions(time_period)
    
        use Global_Vars
        !$ use omp_lib
        
        implicit none
        
        integer :: financial_index,time_period,run_internal_grid,number_of_threads_used,has_house,track_housing_1
        integer :: collapse_housing_state_1,housing_copy_1
        real(8) :: age_cpu_time_1,age_cpu_prev_1
        integer :: age_wall_1,age_wall_prev_1,age_wall_rate_1
        real(8) :: labor_supply_2
        character*1 :: string_used

        ! Cleared here so the shares describe THIS backward induction.
        if (report_lottery_diagnostics==1) then

            call reset_asset_lottery_counters()

        end if

        ! THE CHILD'S VALUE MUST BE READ BEFORE THE SLICE IT LIVES IN IS WIPED.
        !
        ! This block used to sit below, after the loop that sets this
        ! time_period's value function to large_negative_num. It reads the age
        ! one value at that same time_period, so it was reading the sentinel it
        ! had just written, and the guard inside
        ! compute_expected_child_value then returned early with zeros. The
        ! consequence is not subtle: expected_child_value printed exactly
        ! 0.0000000000000000 in every pass of every calibration iteration, so
        ! weight_on_child*expected_child_value contributed nothing to any
        ! household's continuation, and the child externality the paper turns on
        ! was switched off in the solve while appearing to be present.
        !
        ! Moved here, above the wipe, so it reads the PREVIOUS pass's age one
        ! values, which is what the comment always said it did. Nothing between
        ! the two positions feeds it: the lines in between wipe policy
        ! functions, optionally read a labour supply file, and set the thread
        ! count, and newborn_employment_probability is built outside this
        ! routine, in GKKOC_intergenerational_employment_process.
        if (include_child_in_continuation==1) then

            call compute_expected_child_value(time_period)

            write(*,*) "expected_child_value=", expected_child_value

        end if

        max_future_mortgage_index_1=negative_financial_grid_size

        do i=1,2

            value_function(i)%vector_transition_real(time_period,:,:,:,:,:,:)=large_negative_num
            value_function(i)%vector_transition_real(time_period,life_span+1,:,:,:,:,:)=0

        end do
                
        do i=1,2
        
            policy_function_financial_index(i)%vector_transition_integer(time_period,:,:,:,:,:,:)=negative_financial_grid_size
            policy_function_housing_status_index(i)%vector_transition_integer(time_period,:,:,:,:,:,:)=0        
            policy_function_consumption(i)%vector_transition_real(time_period,:,:,:,:,:,:)=0
            policy_function_space_lived_in_index(i)%vector_transition_integer(time_period,:,:,:,:,:,:)=0
            policy_function_space_lived_in_size(i)%vector_transition_real(time_period,:,:,:,:,:,:)=0
            policy_function_wage_income_tax_paid(i)%vector_transition_real(time_period,:,:,:,:,:,:)=0
            policy_function_years_of_amortization_index(i)%vector_transition_integer(time_period,:,:,:,:,:,:)=1
            policy_function_mortgage_interest_deductions(i)%vector_transition_real(time_period,:,:,:,:,:,:)=0    
            policy_function_labor_supply(i)%vector_transition_real(time_period,:,:,:,:,:,:)=1
            frac_mov_optimal_1(i)%vector_transition_real(time_period,:,:,:,:,:,:)=0
            fin_index_frac_mov_to_optimal(i)%vector_transition_integer(time_period,:,:,:,:,:,:)=negative_financial_grid_size
            policy_function_total_consumption(i)%vector_transition_real(time_period,:,:,:,:,:,:)=0
            policy_function_frac_spent_on_addiction(i)%vector_transition_real(time_period,:,:,:,:,:,:)=0
            policy_function_addiction(i)%vector_transition_integer(time_period,:,:,:,:,:,:)=0
            policy_function_treatment(i)%vector_transition_integer(time_period,:,:,:,:,:,:)=0
                
        end do
        
        if ((loop_count<2) .AND. (partial_equilibrium==1)) then
        
            do i=1,2
            
                write(string_used,'(i1)') i
                            
                open(unit=10,file="policy_function_labor_supply"//&
                    trim(string_used)//trim(benchmark_simulation)//".dat",action='read')
                    read(10,'(F22.20)') policy_function_labor_supply(i)%vector_transition_real(time_period,:,:,:,:,:,:)
                close(10)
                
            end do
                
        end if
        
        negative_consumption=0
        
        call cpu_time(value_function_iteration_start_time)
        
        if (solve_transition_dynamics>=0) then
        
            number_of_threads_used=max_CPUs
            ! max_CPUs stays a compile-time parameter because it dimensions vector_cpu_real.
            ! Use it only as an upper bound; take the actual thread count from the runtime so
            ! the same binary is correct on a 4-core laptop and a 40-core server. Honours
            ! OMP_NUM_THREADS when set.
            !$ number_of_threads_used=max(1,min(max_CPUs,omp_get_max_threads()))

            CALL OMP_SET_NUM_THREADS(number_of_threads_used)
        
            !$omp parallel
            !$omp master
            !$ write(*,*) "number of threads = ", omp_get_num_threads()
            !$omp end master
            !$omp end parallel
            
        end if
                       
        ! The child's expected value is computed at the top of this routine,
        ! above the wipe of this time_period's value function, because the wipe
        ! destroys the age one values it has to read. It is a constant within
        ! the pass either way; see the block at include_child_in_continuation.

        do age_index=life_span,1,-1

            ! PER AGE TIMING. TIMING.md's numbers were measured with a print like
            ! this and then it was removed again, which is why every later
            ! estimate had to be arithmetic. It costs one call and one line per
            ! age, sixty lines a pass, and it is the difference between knowing
            ! what a change bought and guessing.
            call cpu_time(age_cpu_time_1)
            call system_clock(age_wall_1,age_wall_rate_1)

            if (age_index<life_span) then

                write(*,'(A,I4,A,F10.2,A,F10.2)') " AGE_TIME age=", age_index+1, &
                    "  wall_s=", real(age_wall_1-age_wall_prev_1,8)/real(max(age_wall_rate_1,1),8), &
                    "  cpu_s=", age_cpu_time_1-age_cpu_prev_1

            end if

            ! THE LOTTERY SHARES, REPORTED PART WAY THROUGH AND NOT ONLY AT THE
            ! END, because a report that only prints at the end of a backward
            ! induction is a report you do not get. Two attempts to measure this
            ! were lost when the run was cut off partway, at ages 13 and 38 of
            ! sixty, and each time the whole diagnostic went with it.
            !
            ! The counts are cumulative across ages, so an interrupted run still
            ! answers the question the diagnostic exists for, and printing them
            ! by age also shows whether the fire rate varies over the life cycle,
            ! which a single figure at the end would hide.
            if ((report_lottery_diagnostics==1) .AND. (mod(age_index,10)==0)) then

                call report_asset_lottery()

            end if

            age_cpu_prev_1=age_cpu_time_1
            age_wall_prev_1=age_wall_1
                
            if (age_index>(life_span-retirement_span)) then
                
                in_retirement=1
            
            else
            
                in_retirement=0 
            
            end if
                                    
            if (age_index==1) then
            
                newborn_household=1
                
            else
            
                newborn_household=0
                
            end if
            
            if (age_index==life_span) then
            
                can_get_mortgage=allow_retirees_borrow
                                
            else
                            
                if (age_index<=life_span-retirement_span) then
                
                    can_get_mortgage=1
                    
                else
                
                    can_get_mortgage=allow_retirees_borrow
                
                end if
                
            end if
            
            if (age_index>=(life_span-retirement_span)) then
                
                at_least_one_period_before_retirement=1
            
            else
                
                at_least_one_period_before_retirement=0
            
            end if
            
            one_period_before_death=0
            
            if (age_index==life_span) then
            
                one_period_before_death=1
            
            end if
            
            do years_left_on_mortgage_index=1,newborn_household*1+(1-newborn_household)*max_amortization_years

                has_house=0

                if (years_left_on_mortgage_index>1) then

                    has_house=1

                end if
                
                track_housing_1=1
                        
                if (has_house==0) then
                
                    if (track_renters_housing==0) then
                    
                        track_housing_1=0
                        
                    end if
                    
                end if
                
                do employment_index=1,employment_grid_size
                
                    do voucher_index=0,(1-has_house)*include_vouchers
                                                    
                        ! LAST PERIOD'S DWELLING IS NOT A STATE FOR A RENTER,
                        ! so it is solved once rather than twice.
                        !
                        ! With owning switched off, the previous dwelling reaches
                        ! nothing. fixed_cost_to_moving is zero; changing_homes
                        ! is assigned in three places and read in none, so the
                        ! moving cost machinery is dead; and inside
                        ! calculate_after_tax_wealth housing_status_index appears
                        ! only under is_current_owner, which needs
                        ! years_left_on_mortgage_index above one and never gets
                        ! it. The problem is therefore identical at every value
                        ! of the index, and the loop was solving it twice: at
                        ! homelessness and at the smallest rental, because
                        ! track_renters_housing collapses the rest onto zero.
                        !
                        ! The switches were flipped without the loop bounds
                        ! following them, which is what left this here. Solving
                        ! one and copying into the others is exact, not an
                        ! approximation, and it halves the backward pass.
                        collapse_housing_state_1=0

                        if ((include_homeownership==0) .AND. (track_renters_housing==0) .AND. &
                            (fixed_cost_to_moving==0) .AND. (has_house==0)) then

                            collapse_housing_state_1=1

                        end if

                        do housing_status_index=(1-has_house)*lowest_housing_grid_point+&
                            has_house*index_of_smallest_house_hhld_can_buy,&
                            (1-collapse_housing_state_1)*&
                            (track_housing_1*(1-newborn_household)*(housing_status_grid_size-1))+&
                            collapse_housing_state_1*((1-has_house)*lowest_housing_grid_point+&
                            has_house*index_of_smallest_house_hhld_can_buy)
                                                        
                            do unemployment_index=1,unemployment_grid_size
                                                                                                            
                                !$omp parallel do default(none) &
                                !$omp& shared(frac_mov_optimal_1,fin_index_frac_mov_to_optimal,&
                                !$omp& policy_function_consumption,policy_function_space_lived_in_size,&
                                !$omp& policy_function_space_lived_in_index,policy_function_addiction,&
                                !$omp& policy_function_financial_index,policy_function_wage_income_tax_paid,&
                                !$omp& policy_function_housing_status_index,policy_function_mortgage_interest_deductions,&
                                !$omp& policy_function_labor_supply,policy_function_cutoff_taxable_income,&
                                !$omp& policy_function_years_of_amortization_index,housing_status_index,&
                                !$omp& policy_function_frac_spent_on_addiction,policy_function_total_consumption,&
                                !$omp& model_average_rental_unit_size,rent,negative_consumption,has_mortgage,&
                                !$omp& model_average_labour_income,housing_status_utility_function,&
                                !$omp& net_govt_revenues,relative_share_of_housing,survival_probability,discount_factor,&
                                !$omp& value_function_guess,value_function,labor_supply_2,&
                                !$omp& employment_process,years_left_on_mortgage_index,unemployment_index,employment_index,&
                                !$omp& large_negative_num,labour_deterministic_efficiency,model_ss_benefits,housing_size,&
                                !$omp& housing_price,mortgage_insurance_premium,mortgage_interest_rate,property_tax,&
                                !$omp& curvature_of_labor_income_taxes,labor_income_tax_rate,voucher_index,&
                                !$omp& financial_grid,increase_in_labour_income_tax,&
                                !$omp& relative_share_of_housing_2,relative_share_of_consumption_2,relative_share_of_addiction,&
                                !$omp& age_index,discount_factor_on_child,unemployment_process,&
                                !$omp& risk_free_rate,time_period,rental_management_costs,can_get_mortgage,&
                                !$omp& unemployment_grid,employment_grid,run_internal_grid,at_least_one_period_before_retirement,&
                                !$omp& index_of_smallest_house_hhld_can_buy,convexity_of_rental_company,&
                                !$omp& size_of_smallest_house_hhld_can_buy,model_average_owner_occupied_unit_size,has_house,&
                                !$omp& in_retirement,newborn_household,lump_sum_transfer,&
                                !$omp& scaled_household_size,one_period_before_death,median_income,&
                                !$omp& warm_start_a_prime,warm_start_ready,renter_floor_by_age)
                        
                                do financial_index=newborn_household*negative_financial_grid_size+&
                                    (1-newborn_household)*(has_house*1+(1-has_house)*renter_floor_by_age(min(max(age_index,1),life_span))),&
                                    include_exogenous_endowment*financial_grid_size+(1-include_exogenous_endowment)*&
                                    (newborn_household*negative_financial_grid_size+&
                                    (1-newborn_household)*financial_grid_size)
                                                                                                                                                                 
                                    total_household_wealth=has_house*housing_price(time_period)*&
                                        housing_size(housing_status_index)+max(financial_grid(financial_index),0.d0)
                                                                 
                                    went_in_1=0
                                                                 
                                    if (years_left_on_mortgage_index<=1) then
                                    
                                        value_function_owner=large_negative_num
                                                                        
                                        call renters_problem(time_period,financial_index)
                                        
                                    else
                                    
                                        value_function_renter=large_negative_num
                                                    
                                        call owners_problem(time_period,financial_index)   
                                                                                                     
                                    end if
                                                                
                                    call which_is_better(time_period,financial_index)
                                                                                                                                                    
                                    if (do_internal_computations==1) then
                                    
                                        if (years_left_on_mortgage_index<=1) then
                                        
                                            if (optimal_household_can_consume_renter==1)  then
                                            
                                                run_internal_grid=1
                                                
                                            else
                                            
                                                run_internal_grid=0
                                                
                                            end if
                                            
                                        else
                                        
                                            if (optimal_household_can_consume_owner==1)  then
                                            
                                                run_internal_grid=1
                                                
                                            else
                                            
                                                run_internal_grid=0
                                                                                            
                                            end if
                                        
                                        end if
                                        
                                        if (run_internal_grid==1) then
                                        
                                            financial_index_used_3=&
                                                policy_function_financial_index(years_left_on_mortgage_index)%&
                                                vector_transition_integer(time_period,age_index,financial_index,&
                                                unemployment_index,employment_index,housing_status_index,voucher_index)
                                                
                                            space_lived_in_index_used_3=&
                                                policy_function_space_lived_in_index(years_left_on_mortgage_index)%&
                                                vector_transition_integer(time_period,age_index,financial_index,&
                                                unemployment_index,employment_index,housing_status_index,voucher_index)
                                                
                                            labor_supply_used_3=policy_function_labor_supply(years_left_on_mortgage_index)%&
                                                vector_transition_real(time_period,age_index,financial_index,&
                                                unemployment_index,employment_index,housing_status_index,voucher_index)
                                    
                                            amortization_used_dist=&
                                                policy_function_years_of_amortization_index(years_left_on_mortgage_index)%&
                                                vector_transition_integer(time_period,age_index,financial_index,&
                                                unemployment_index,employment_index,housing_status_index,voucher_index)
                                                
                                            frac_spent_on_addiction_3=&
                                                policy_function_frac_spent_on_addiction(years_left_on_mortgage_index)%&
                                                vector_transition_real(time_period,age_index,financial_index,&
                                                unemployment_index,employment_index,housing_status_index,voucher_index)
                                                
                                            addiction_used=policy_function_addiction&
                                                (years_left_on_mortgage_index)%vector_transition_integer&
                                                (time_period,age_index,financial_index,unemployment_index,&
                                                employment_index,housing_status_index,voucher_index)
                                                
                                            max_future_mortgage_index_1=negative_financial_grid_size
                                            
                                            if (amortization_used_dist>1) then
                                                                               
                                                max_mortgage_value_allowed_1=&
                                                    -min(financial_grid(financial_index_used_3),0.d0)
                                                                                                        
                                                max_future_mortgage_index_1=min(max(minloc(max_mortgage_value_allowed_1+&
                                                    financial_grid(1:negative_financial_grid_size),1,mask=&
                                                    (max_mortgage_value_allowed_1+financial_grid&
                                                    (1:negative_financial_grid_size))>=0),1),negative_financial_grid_size)
                                                                                                       
                                            end if
                                    
                                            call internal_computations&
                                                (value_function(years_left_on_mortgage_index)%&
                                                vector_transition_real(time_period,age_index,financial_index,&
                                                unemployment_index,employment_index,housing_status_index,voucher_index),&
                                                labor_supply_used_3,labor_supply_used_3*&
                                                employment_grid(age_index,employment_index)*&
                                                labour_deterministic_efficiency(age_index),&
                                                financial_index_used_3,max(min(amortization_used_dist-1,1),0),&
                                                space_lived_in_index_used_3,policy_function_housing_status_index&
                                                (years_left_on_mortgage_index)%vector_transition_integer&
                                                (time_period,age_index,financial_index,unemployment_index,&
                                                employment_index,housing_status_index,voucher_index),amortization_used_dist,&
                                                policy_function_wage_income_tax_paid(years_left_on_mortgage_index)%&
                                                vector_transition_real(time_period,age_index,financial_index,&
                                                unemployment_index,employment_index,housing_status_index,voucher_index),&
                                                policy_function_mortgage_interest_deductions(years_left_on_mortgage_index)%&
                                                vector_transition_real(time_period,age_index,financial_index,unemployment_index,&
                                                employment_index,housing_status_index,voucher_index),financial_index,time_period,&
                                                optimal_after_tax_wealth_net_of_expenses,max_future_mortgage_index_1,&
                                                frac_spent_on_addiction_3,addiction_used)
                                                                                                
                                            value_function(years_left_on_mortgage_index)%&
                                                vector_transition_real(time_period,age_index,financial_index,&
                                                unemployment_index,employment_index,housing_status_index,voucher_index)=&
                                                val_fun_internal
                                                
                                        end if
                                            
                                    end if
                                    
                                    if ((value_function(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)<0) .AND. &
                                        (optimal_after_tax_wealth_net_of_expenses>0)) then
                                    
    !                                    write(*,*) "age_index=", age_index
    !                                    write(*,*) "financial_index=", financial_index
    !                                    write(*,*) "financial_grid(financial_index)=", financial_grid(financial_index)
    !                                    write(*,*) "years_left_on_mortgage_index=", years_left_on_mortgage_index
    !                                    write(*,*) "unemployment_index=", unemployment_index
    !                                    write(*,*) "employment_index=", employment_index
    !                                    write(*,*) "housing_status_index=", housing_status_index
    !                                    write(*,*) "value=", value_function(years_left_on_mortgage_index)%&
    !                                        vector_transition_real(time_period,age_index,financial_index,&
    !                                        unemployment_index,employment_index,housing_status_index)
    !                                    write(*,*) "policy_function_addiction=", &
    !                                        policy_function_addiction(years_left_on_mortgage_index)%&
    !                                        vector_transition_integer(time_period,age_index,financial_index,&
    !                                        unemployment_index,employment_index,housing_status_index)
    !                                    write(*,*) "policy_function_housing_status_index=", &
    !                                        policy_function_housing_status_index(years_left_on_mortgage_index)%&
    !                                        vector_transition_integer(time_period,age_index,financial_index,&
    !                                        unemployment_index,employment_index,housing_status_index)
    !                                    write(*,*) "policy_function_financial_index=", &
    !                                        policy_function_financial_index(years_left_on_mortgage_index)%&
    !                                        vector_transition_integer(time_period,age_index,financial_index,&
    !                                        unemployment_index,employment_index,housing_status_index)
    !                                    write(*,*) "policy_function_consumption=", &
    !                                        policy_function_consumption(years_left_on_mortgage_index)%&
    !                                        vector_transition_real(time_period,age_index,financial_index,&
    !                                        unemployment_index,employment_index,housing_status_index)
    !                                    write(*,*) "policy_function_total_consumption=", &
    !                                        policy_function_total_consumption(years_left_on_mortgage_index)%&
    !                                        vector_transition_real(time_period,age_index,financial_index,&
    !                                        unemployment_index,employment_index,housing_status_index)
    !                                    write(*,*) "policy_function_labor_supply=", &
    !                                        policy_function_labor_supply(years_left_on_mortgage_index)%&
    !                                        vector_transition_real(time_period,age_index,financial_index,&
    !                                        unemployment_index,employment_index,housing_status_index)
    !                                    
                                    end if
                                    
                                    if ((policy_function_consumption(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)<=0) .AND. &
                                        (optimal_after_tax_wealth_net_of_expenses>0)) then
                                        
                                        write(*,*) "consumption negatuve"
                                                
                                    end if
                                    
                                    if ((policy_function_frac_spent_on_addiction(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)<0) .OR. &
                                        policy_function_frac_spent_on_addiction(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)>1) then
                                        
                                        write(*,*) "consumption negatuve 2"
                                        write(*,*) "policy_function_frac_spent_on_addiction(years_left_on_mortgage_index)%&
                                            vector_transition_real(time_period,age_index,financial_index,&
                                            unemployment_index,employment_index,housing_status_index)=", &
                                            policy_function_frac_spent_on_addiction(years_left_on_mortgage_index)%&
                                            vector_transition_real(time_period,age_index,financial_index,&
                                            unemployment_index,employment_index,housing_status_index,voucher_index)
                                                
                                    end if
                                    
                                    if (policy_function_total_consumption(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)<&
                                        policy_function_consumption(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)) then
                                        
                                        write(*,*) "werird"
                                        
                                    end if
                                    
                                    if ((addiction_used==0) .AND. (unemployment_index>threshold_addiction_index) .AND. &
                                       (optimal_after_tax_wealth_net_of_expenses>0) .AND. (run_internal_grid==1)) then
                                    
                                        write(*,*) "error wrong addiction option"
                                    
                                    end if
                                                                    
                                    if (optimal_after_tax_wealth_net_of_expenses>0) then
                                                                                                            
                                        call check_budget_constraint_clears&
                                            (time_period,optimal_after_tax_wealth_net_of_expenses,financial_index)
                                                                                    
                                    end if
                                    
                                    labor_supply_2=policy_function_labor_supply(years_left_on_mortgage_index)%&
                                        vector_transition_real(time_period,age_index,financial_index,&
                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                    
                                    if ((labor_supply_2>1) .OR. (labor_supply_2<0)) then
        
                                        write(*,*) "labor_supply_2=", labor_supply_2
                                    
                                    end if
                                    
                                end do
                                                             
                                !$omp end parallel do
                                
                            end do

                            ! The solved slice copied across the indices that
                            ! were not solved. The distribution and the moments
                            ! still read every one of them, so the arrays have to
                            ! be whole even though only one was computed.
                            if (collapse_housing_state_1==1) then

                                do housing_copy_1=housing_status_index+1,&
                                    track_housing_1*(1-newborn_household)*(housing_status_grid_size-1)

                                    call copy_housing_state_slice(time_period,housing_status_index,housing_copy_1)

                                end do

                            end if
                            
                        end do
                                                                    
                    end do
                    
                end do
            
            end do
            
            if (loop_count<1) then
            
                write(*,*) "age_index=", age_index
                
            end if
            
        end do
        
        if (solve_transition_dynamics==0) then
                
            loop_count=loop_count+1
            
        end if

        ! THE LOTTERY IS COUNTED WHERE IT RUNS. The a' search is in this
        ! subroutine, and the first version reset the counters at the head of
        ! converge_to_stationary_equilibrium, which the calibration loop calls
        ! AFTER this one. So the reset wiped the whole solve's counts and the
        ! report read zero and said the lottery had never been called, which was
        ! a statement about where the counters were cleared and not about the
        ! lottery.
        if (report_lottery_diagnostics==1) then

            call report_asset_lottery()

        end if
         
        call cpu_time(value_function_iteration_stop_time)
        
        write(*,*) "time=", value_function_iteration_stop_time-value_function_iteration_start_time
        
        if ((solve_transition_dynamics==1) .AND. (is_counterfactual==1)) then
        
            write(*,*) "time_period=", time_period
            
        end if
    
    end subroutine
    
    subroutine renters_problem(time_period,financial_index)

        use Global_Vars
        
        implicit none
    
        integer, intent(in) :: time_period,financial_index
                                                                                                                      
        call renter_to_renter_problem(time_period,financial_index)
                
        ! THE SECOND. Buying is not in the choice set. With include_homeownership
        ! at zero the renter to owner branch is never solved and its value is
        ! minus infinity, so the comparison below can only ever pick renting.
        if (include_homeownership==1) then
        
            call renter_to_owner_problem(time_period,financial_index)
            
        else
        
            value_function_renter_owner=large_negative_num
            
        end if
        
        if ((value_function_renter_renter>=value_function_renter_owner) .OR. (include_ownership==0)) then
                        
            value_function_renter=value_function_renter_renter
            
            optimal_renter_indeces(1)=optimal_renter_renter_indeces(1)
            optimal_renter_indeces(2)=optimal_renter_renter_indeces(2)
            optimal_renter_indeces(3)=optimal_renter_renter_indeces(3)
                
            optimal_gross_wage_income_renter=optimal_gross_wage_income_renter_renter
            optimal_cutoff_taxable_income_renter=optimal_cutoff_taxable_income_renter_renter
            optimal_wage_income_tax_paid_renter=optimal_wage_income_tax_paid_renter_renter
            optimal_after_tax_wealth_net_of_expenses_renter=optimal_after_tax_wealth_net_of_expenses_renter_renter
            optimal_consumption_renter=optimal_consumption_renter_renter
            optimal_space_lived_in_renter=optimal_space_lived_in_renter_renter
            optimal_mortgage_deductions_renter=optimal_mortgage_deductions_renter_renter
            optimal_household_can_consume_renter=optimal_household_can_consume_renter_renter
            optimal_labor_supply_renter=optimal_labor_supply_renter_renter
            optimal_frac_spent_on_addiction_renter=optimal_frac_spent_on_addiction_renter_renter
            optimal_total_consumption_renter=optimal_total_consumption_renter_renter
            optimal_addiction_status_renter=optimal_addiction_status_renter_renter
            optimal_treatment_renter=optimal_treatment_renter_renter
            
            if ((unemployment_index>threshold_addiction_index) .AND. &
                (optimal_addiction_status_renter_renter==0) .AND. (optimal_after_tax_wealth_net_of_expenses_renter>0)) then
            
                write(*,*) "wrong renter renter"
            
            end if
                    
        else
        
            value_function_renter=value_function_renter_owner
            
            optimal_renter_indeces(1)=optimal_renter_owner_indeces(1)
            optimal_renter_indeces(2)=optimal_renter_owner_indeces(2)
            optimal_renter_indeces(3)=optimal_renter_owner_indeces(3)
                
            optimal_gross_wage_income_renter=optimal_gross_wage_income_renter_owner
            optimal_cutoff_taxable_income_renter=optimal_cutoff_taxable_income_renter_owner
            optimal_wage_income_tax_paid_renter=optimal_wage_income_tax_paid_renter_owner
            optimal_after_tax_wealth_net_of_expenses_renter=optimal_after_tax_wealth_net_of_expenses_renter_owner
            optimal_consumption_renter=optimal_consumption_renter_owner
            optimal_space_lived_in_renter=optimal_space_lived_in_renter_owner
            optimal_mortgage_deductions_renter=optimal_mortgage_deductions_renter_owner
            optimal_household_can_consume_renter=optimal_household_can_consume_renter_owner
            optimal_labor_supply_renter=optimal_labor_supply_renter_owner
            optimal_frac_spent_on_addiction_renter=optimal_frac_spent_on_addiction_renter_owner
            optimal_total_consumption_renter=optimal_total_consumption_renter_owner
            optimal_addiction_status_renter=optimal_addiction_status_renter_owner
            optimal_treatment_renter=0
            
            if ((unemployment_index>threshold_addiction_index) .AND. &
                (optimal_addiction_status_renter_owner==0)) then
            
                write(*,*) "wrong renter owner"
            
            end if
        
        end if
        
        if ((age_index==3) .AND. (financial_index==101) .AND. (employment_index==1) .AND. &
            (housing_status_index==2)) then
            
!            write(*,*) "value_function_renter=", value_function_renter
            
        end if
                                
    end subroutine
    
    subroutine ensure_ev_table(time_period,evx_slot,evx_fai,&
        evx_fhsi,evx_fhsu,&
        evx_homeless,evx_opp,evx_vidx,&
        evx_fv,evx_sv,evx_loopadd,evx_addidx)

        ! Invalidate the table when the outer state moves and fill the column
        ! asked for if it is not there. Pulled out of the Bellman loop because
        ! the smooth hazard reads the table twice per node, once to price the
        ! drug risk before the choice is made and once to form the continuation
        ! after, and the two reads have to agree about what is cached.

        use Global_Vars
        !$ use omp_lib

        implicit none

        integer, intent(in) :: time_period,evx_slot,evx_fai,&
            evx_fhsi,evx_fhsu,&
            evx_homeless,evx_opp,evx_vidx,&
            evx_fv,evx_sv,evx_loopadd,evx_addidx

        if ((ev_table_key(1,evx_slot)/=age_index) .OR. &
            (ev_table_key(2,evx_slot)/=employment_index) .OR. &
            (ev_table_key(3,evx_slot)/=unemployment_index) .OR. &
            (ev_table_key(4,evx_slot)/=voucher_index) .OR. &
            (ev_table_key(5,evx_slot)/=housing_status_index) .OR. &
            (ev_table_key(6,evx_slot)/=years_left_on_mortgage_index)) then

            ev_table_valid(:,:,:,evx_slot)=.FALSE.
            ev_table_key(1,evx_slot)=age_index
            ev_table_key(2,evx_slot)=employment_index
            ev_table_key(3,evx_slot)=unemployment_index
            ev_table_key(4,evx_slot)=voucher_index
            ev_table_key(5,evx_slot)=housing_status_index
            ev_table_key(6,evx_slot)=years_left_on_mortgage_index

        end if

        if (.NOT. ev_table_valid(evx_fai,evx_fhsi,evx_opp,evx_slot)) then

            call fill_ev_table(time_period,evx_slot,evx_fai,&
                evx_fhsi,evx_fhsu,evx_homeless,evx_opp,evx_vidx,&
                evx_fv,evx_sv,evx_loopadd,evx_addidx)

        end if

    end subroutine

    subroutine fill_ev_table(time_period,evx_slot,evx_fai,&
        evx_fhsi,evx_fhsu,&
        evx_homeless,evx_opp,evx_vidx,&
        evx_fv,evx_sv,evx_loopadd,evx_addidx)

        ! Tabulate EV(a') for one (chosen housing, eligibility) pair. The body is
        ! the same four deep sum the Bellman loop used to run inside the a' loop,
        ! with a' moved to the outside, so every term and every loop bound is
        ! identical.
        !
        ! WHAT THE SECOND INDEX MEANS DEPENDS ON THE HAZARD, and it has to.
        !
        ! With smooth_addiction_hazard at 0 the addiction probability is a
        ! constant given the drug regime, so it can be folded into the sum and
        ! the table is indexed by the CHOICE, which is what it was.
        !
        ! With the hazard at 1 the probability depends on the quantity chosen at
        ! this node, and the quantity depends on a', so folding it in would
        ! tabulate a different function at every a' and destroy the hoist. The
        ! table therefore carries NO hazard and is indexed by the future disorder
        ! STATE, and the caller forms
        !
        !     (1-pi_d(v)) * EV(a',clean) + pi_d(v) * EV(a',disorder)
        !
        ! once v is known. That is exact, not an approximation: the hazard is the
        ! only factor in the old sum that depended on the choice, everything else
        ! is a function of the future state. It also hands the caller the two
        ! continuations separately, which is what the drug first order condition
        ! needs, so the restructure pays for itself twice.

        use Global_Vars

        implicit none

        integer, intent(in) :: time_period,evx_slot,evx_fai,&
            evx_fhsi,evx_fhsu,&
            evx_homeless,evx_opp,evx_vidx,&
            evx_fv,evx_sv,evx_loopadd,evx_addidx

        integer :: ffi_1,fei_1,fai_1,fui_1,fvi_1,evx_check,evx_lo,evx_hi,evx_col
        real(8) :: acc,haz_1

        ! In smooth mode both future states are tabulated on every call, because
        ! both are read: a household that uses needs the disorder continuation
        ! and a household that has the disorder needs the clean one for recovery.
        if (smooth_addiction_hazard==1) then

            evx_lo=0
            evx_hi=include_addiction

        else

            evx_lo=(1-evx_loopadd)*evx_fai+evx_loopadd*0
            evx_hi=(1-evx_loopadd)*evx_fai+evx_loopadd*include_addiction

        end if

        do fai_1=evx_lo,evx_hi

            ! The column written. In smooth mode it is the future state, so the
            ! sum is accumulated per state rather than across them; otherwise it
            ! is the choice and every state lands in the same column, which is
            ! what folding the hazard in means.
            evx_col=smooth_addiction_hazard*fai_1+(1-smooth_addiction_hazard)*evx_fai

            if (smooth_addiction_hazard==1) then

                ev_table(:,evx_col,evx_fhsi,evx_opp,evx_slot)=0

            elseif (fai_1==evx_lo) then

                ev_table(:,evx_col,evx_fhsi,evx_opp,evx_slot)=0

            end if

            evx_check=0

            if (fai_1==1) then

                evx_check=1

            end if

            ! THE FILL RANGE IS THE NEXT AGE'S STATE FLOOR, and it has to be
            ! exactly that, no wider and no narrower.
            !
            ! This table reads value_function at age_index+1, so it can only be
            ! filled where that function was SOLVED -- which is the state floor
            ! at age_index+1. Filling the whole grid instead, as the first
            ! version of this did, tabulates uncomputed entries at indices 1-3
            ! and the result is not confined to those indices: with borrowing
            ! OFF, where nothing can even reach them, it moved w_bot from 0.0295
            ! to 3.27, homelessness from 0.084 to 0.011 and drug use to exactly
            ! zero. Something downstream reads the table below the chosen index
            ! -- the internal-grid interpolation is the candidate -- so an
            ! unreachable entry is not an unread one.
            !
            ! renter_floor_by_age is negative_financial_grid_size when borrowing
            ! is off and in the final period of life, so this is the old bound in
            ! exactly those cases.
            do ffi_1=renter_floor_by_age(min(max(age_index+1,1),life_span)),financial_grid_size

                acc=0

                do fei_1=at_least_one_period_before_retirement*employment_index+&
                    (1-at_least_one_period_before_retirement)*1,&
                    at_least_one_period_before_retirement*employment_index+&
                    (1-at_least_one_period_before_retirement)*employment_grid_size

                    if (employment_process(age_index,employment_index,fei_1)<=0.d0) cycle

                    ! In smooth mode the hazard is applied by the caller, so the
                    ! factor here is one. Off, it is the old array read.
                    haz_1=smooth_addiction_hazard*1.d0+(1-smooth_addiction_hazard)*&
                        addiction_probabilities_percieved(evx_addidx,fai_1,&
                        evx_fai,evx_homeless)

                    do fui_1=include_addiction*&
                        ((1-evx_check)*1+evx_check*(threshold_addiction_index+1))+&
                        (1-include_addiction)*(at_least_one_period_before_retirement*&
                        (one_period_before_death*1+(1-one_period_before_death)*unemployment_index)+&
                        (1-at_least_one_period_before_retirement)*1),include_addiction*&
                        ((1-evx_check)*threshold_addiction_index+evx_check*unemployment_grid_size)+&
                        (1-include_addiction)*(at_least_one_period_before_retirement*&
                        (one_period_before_death*unemployment_grid_size+&
                        (1-one_period_before_death)*unemployment_index)+&
                        (1-at_least_one_period_before_retirement)*unemployment_grid_size)

                        do fvi_1=evx_fv,evx_sv

                            acc=acc+discount_factor*&
                                survival_probability(age_index,evx_homeless,evx_addidx,smi_of(unemployment_index))*&
                                voucher_probabilities(voucher_index,fvi_1,&
                                evx_opp,evx_vidx)*&
                                employment_process(age_index,employment_index,fei_1)*&
                                unemployment_process(age_index,unemployment_index,&
                                fui_1,evx_homeless,fai_1,employment_index)*&
                                haz_1*&
                                value_function(1)%vector_transition_real&
                                (min(time_period+solve_transition_dynamics,transition_length),age_index+1,&
                                ffi_1,fui_1,fei_1,evx_fhsu,fvi_1)

                        end do

                    end do

                end do

                ev_table(ffi_1,evx_col,evx_fhsi,&
                    evx_opp,evx_slot)=ev_table(ffi_1,evx_col,evx_fhsi,&
                    evx_opp,evx_slot)+acc

            end do

        end do

        ! In smooth mode the fill covers every column at this (housing,
        ! eligibility) pair, so every column is marked. Off, only the choice
        ! that was asked for is.
        if (smooth_addiction_hazard==1) then

            ev_table_valid(:,evx_fhsi,evx_opp,evx_slot)=.TRUE.

        else

            ev_table_valid(evx_fai,evx_fhsi,&
                evx_opp,evx_slot)=.TRUE.

        end if

    end subroutine

    subroutine renter_to_renter_problem(time_period,financial_index)
    
        use Global_Vars
        !$ use omp_lib
        
        implicit none
        
        integer, intent(in) :: time_period,financial_index
        integer :: changing_homes,tenure_1,tenure_2,proceed_2,&
            future_housing_status_index_to_use,is_working_1,is_homeless_1,x_1,addiction_index,&
            global_search_index,optimal_financial_1,loop_over_addiction_1,check_1,allow_to_choose_addiction,&
            first_voucher_index,second_voucher_index,has_opportunity_1,can_consume_drugs,voucher_index_1,&
            allow_to_choose_homelessness,ev_slot,drug_pass_1,drug_risk_top,&
            a_lo_1,a_hi_1,a_floor_1,a_attempt_1,branch_argmax_1,warm_used_1,warm_guess_1,&
            treatment_choice_1,treatment_top_1
        real(8) :: branch_best_1
        real(8) :: labor_supply_1,labor_supply_2
        
        allow_to_choose_homelessness=1
        
        if (age_index>max_age_to_choose_homelessness) then
        
            allow_to_choose_homelessness=0
            
        end if       
        
        allow_to_choose_addiction=1
            
        if (age_index>max_age_to_choose_addiction) then
        
            allow_to_choose_addiction=0
                         
        end if
                     
        addiction_index=0
        
        if (unemployment_index>threshold_addiction_index) then
        
            addiction_index=1
            
        end if
        
        is_working_1=1
        
        if ((in_retirement==1) .OR. &
            (emp_of(unemployment_index)>1)) then
        
            is_working_1=0
            
        end if
        
        proceed_2=1
        tenure_1=1
        tenure_2=0
        
        labor_supply_2=1
            
        largest_value=large_negative_num
        
        optimal_renter_renter_indeces(1)=negative_financial_grid_size
        optimal_financial_1=negative_financial_grid_size
        optimal_renter_renter_indeces(2)=1
        optimal_renter_renter_indeces(3)=0
                 
        optimal_consumption_renter_renter=0
        optimal_after_tax_wealth_net_of_expenses_renter_renter=0
        optimal_gross_wage_income_renter_renter=0
        optimal_cutoff_taxable_income_renter_renter=0
        optimal_wage_income_tax_paid_renter_renter=0
        optimal_space_lived_in_renter_renter=0
        optimal_mortgage_deductions_renter_renter=0
        optimal_household_can_consume_renter_renter=0
        optimal_labor_supply_renter_renter=((1-is_working_1)*0+is_working_1*1)
        labor_supply_1=optimal_labor_supply_renter_renter
        optimal_frac_spent_on_addiction_renter_renter=0
        optimal_total_consumption_renter_renter=0
        optimal_addiction_status_renter_renter=0
        optimal_treatment_renter_renter=0
        treatment_choice_now=0
        
        if (fixed_labor_supply_at_benchmark==1) then
                    
            labor_supply_2=&
                policy_function_labor_supply(years_left_on_mortgage_index)%&
                vector_transition_real(time_period,age_index,financial_index,unemployment_index,&
                employment_index,housing_status_index,voucher_index)
                
            labor_supply_1=labor_supply_2
                
        end if
                    
        do future_addiction_index=addiction_index,&
            (1-allow_to_choose_addiction)*addiction_index+allow_to_choose_addiction*&
            (include_addiction+(1-addiction_index)*include_heavy_vs_light_use_transitions)
        
            loop_over_addiction_1=0
                        
            if (addiction_index==1) then
            
                loop_over_addiction_1=1
                
            elseif ((future_addiction_index>=1) .AND. &
                (include_probability_of_becoming_addicted==1)) then
            
                loop_over_addiction_1=1
                
            end if
                        
            changing_homes=0

            ! TREATMENT. A binary choice, open only to a household that already
            ! carries the disorder, evaluated alongside housing and saving
            ! rather than after them, because it changes the budget through the
            ! forced abstention and so changes what every other choice is worth.
            treatment_top_1=0

            if ((include_treatment==1) .AND. (addiction_index==1)) then

                treatment_top_1=1

            end if

            do treatment_choice_1=0,treatment_top_1

            treatment_choice_now=treatment_choice_1
                            
            do future_housing_status_index=&
                allow_to_choose_homelessness*lowest_housing_grid_point,largest_house_size_hhld_can_rent
                
                if (track_renters_housing==0) then
                
                    if (future_housing_status_index<=second_lowest_housing_grid_point) then
            
                        future_housing_status_index_to_use=future_housing_status_index
                        
                    else
                        
                        future_housing_status_index_to_use=0
                        
                    end if
                    
                else
                
                    future_housing_status_index_to_use=future_housing_status_index
                
                end if   
                
                is_homeless_1=1
                
                if (future_housing_status_index_to_use==lowest_housing_grid_point) then
                
                    is_homeless_1=2
                
                end if
                
                call compute_voucher_index_1(is_homeless_1,voucher_index_1)

                ! The window for this branch's a' search, and the per branch
                ! argmax that both the window and coarse mode need.
                branch_best_1=large_negative_num

                ! THE FLOOR OF THE ASSET SEARCH. Opening the negative grid to the
                ! STATE loops was only half of unsecured borrowing: this is where
                ! a' is CHOSEN, and it was pinned at negative_financial_grid_size
                ! -- the index of zero -- so no renter could ever select a
                ! negative position, no renter ever arrived at one, and the whole
                ! extension was unreachable. The controlled twin showed it: with
                ! the limit at a full year of average income, w_bot moved from
                ! 0.029487 to 0.029610 and the bottom one per cent's share of
                ! wealth stayed strictly positive at +1.19e-04 against -2.25e-03
                ! in the data. Nobody was borrowing because nobody could.
                !
                ! renter_floor_by_age is the same object the state loops use. It
                ! is negative_financial_grid_size when borrowing is off and in the
                ! final period of life, so this line is a no-op in exactly the
                ! cases where borrowing is meant to be barred.
                ! THE NEXT AGE'S floor, not this one's. a' is where the
                ! household ARRIVES, so what bounds it is the state floor of the
                ! age it arrives at. Keyed on age_index instead, a household at
                ! life_span-1 could borrow into a final period whose value
                ! function is not solved at negative assets at all -- the
                ! "no borrowing in the last period" rule states the bound on the
                ! arriving age, and this is the loop that has to honour it.
                a_floor_1=renter_floor_by_age(min(max(age_index+1,1),life_span))
                branch_argmax_1=a_floor_1

                a_lo_1=a_floor_1
                a_hi_1=financial_grid_size
                warm_used_1=0

                if ((warm_start_asset_search==1) .AND. (warm_start_ready==1) .AND. &
                    (verify_asset_search==0)) then

                    warm_guess_1=warm_start_a_prime(age_index,financial_index,&
                        unemployment_index,employment_index,housing_status_index,&
                        voucher_index,future_addiction_index,future_housing_status_index)

                    if (warm_guess_1>=a_floor_1) then

                        a_lo_1=max(warm_guess_1-warm_start_half_width,a_floor_1)
                        a_hi_1=min(warm_guess_1+warm_start_half_width,financial_grid_size)
                        warm_used_1=1

                    end if

                end if

                do a_attempt_1=1,2

                ! The second attempt runs only when the first one's argmax sat on
                ! an edge the optimum could have crossed. Then the window is
                ! discarded and the full grid searched, which is what a cold
                ! start would have done.
                if (a_attempt_1==2) then

                    if (warm_used_1==0) exit

                    if (((branch_argmax_1>a_lo_1) .OR. (a_lo_1==a_floor_1)) .AND. &
                        ((branch_argmax_1<a_hi_1) .OR. (a_hi_1==financial_grid_size))) exit

                    a_lo_1=a_floor_1
                    a_hi_1=financial_grid_size
                    branch_best_1=large_negative_num

                end if

                do global_search_index=0,coarse_grid
            
                do future_financial_index=&
                    (1-global_search_index)*a_lo_1+&
                    global_search_index*max(branch_argmax_1-grid_gaps+1,a_lo_1),&
                    (1-global_search_index)*a_hi_1+&
                    global_search_index*min(branch_argmax_1+grid_gaps-1,a_hi_1),&
                    (1-global_search_index)*grid_gaps+global_search_index

                    if ((future_housing_status_index==housing_status_index) .AND. &
                       (years_left_on_mortgage_index==1)) then
                    
                        changing_homes=0
                        
                    else
                    
                        changing_homes=1
                        
                    end if
                    
                    ! THE NODE IS SOLVED TWICE WHEN THE HAZARD CAN BITE, and only
                    ! then. The drug first order condition needs EV(a',clean) -
                    ! EV(a',disorder), the table that holds it is keyed on voucher
                    ! eligibility, and eligibility is a threshold on income, which
                    ! is not known until hours and consumption have been solved.
                    ! So the first pass solves the node with the risk term off,
                    ! purely to locate income and eligibility; the second solves
                    ! it again with the risk term on, and hours, consumption and
                    ! the drug quantity come out mutually consistent because the
                    ! whole chain, secant included, re-runs underneath it.
                    !
                    ! It costs a second solve at exactly the nodes where the
                    ! choice exists: a household that already carries the
                    ! disorder faces a recovery hazard that does not depend on
                    ! how much it uses, and one that abstains has v=0, so neither
                    ! pays for the pass.
                    drug_risk_top=0

                    if ((smooth_addiction_hazard==1) .AND. (addiction_index==0) .AND. &
                        (future_addiction_index>=1) .AND. (include_addiction==1) .AND. &
                        (include_probability_of_becoming_addicted==1)) then

                        drug_risk_top=1

                    end if

                    drug_risk_housing_index=future_housing_status_index
                    drug_risk_ownership=0

                    do drug_pass_1=0,drug_risk_top

                    drug_risk_active=drug_pass_1

                    if ((in_retirement==0) .AND. (fixed_labor_supply_at_benchmark==0)) then

                        labor_supply_2=1

                    end if

                    call calculate_after_tax_wealth&
                        (financial_index,future_financial_index,years_left_on_mortgage_index,0,&
                        housing_status_index,future_housing_status_index,tenure_2,tenure_2,tenure_2,&
                        tenure_2,tenure_1,time_period,labor_supply_2,cutoff_taxable_income,future_addiction_index)
                        ! owner_to_owner_move_1,owner_to_renter_1,renter_to_owner_1,owner_to_owner_stay_1,renter_to_renter_1

                    if (labor_supply_2>0.4) then

                    if ((in_retirement==0) .AND. (fixed_labor_supply_at_benchmark==0) .AND. &
                        (emp_of(unemployment_index)==1)) then

                        x_1=1

                        call secant(time_period,financial_index,financial_grid(future_financial_index),&
                            housing_size(future_housing_status_index),future_housing_status_index,&
                            x_1,after_tax_wealth_net_of_expenses,labor_supply_1,gross_wage_income,&
                            wage_income_tax_paid,food_stamps_recieved,housing_voucher_recieved,&
                            housing_voucher_recieved_2,mortgage_deductions_tax_rebates,proceed_2,&
                            future_addiction_index)

                    end if

                    end if

                    call calculate_future_voucher_index_and_opportunity&
                        (has_opportunity_1,first_voucher_index,second_voucher_index,&
                        time_period,0,0,voucher_index_1,gross_wage_income+investment_income)

                    ! Between the passes, read the loss from acquiring the
                    ! disorder at this a'. Filling the table here rather than
                    ! below costs nothing: it is cached on the same key and the
                    ! read further down finds it already built.
                    if (drug_pass_1<drug_risk_top) then

                        ev_slot=1
                        !$ ev_slot=omp_get_thread_num()+1

                        call ensure_ev_table(time_period,ev_slot,future_addiction_index,&
                            future_housing_status_index,future_housing_status_index_to_use,&
                            is_homeless_1,has_opportunity_1,voucher_index_1,&
                            first_voucher_index,second_voucher_index,loop_over_addiction_1,&
                            addiction_index)

                        drug_risk_value=max(ev_table(future_financial_index,0,&
                            future_housing_status_index,has_opportunity_1,ev_slot)-&
                            ev_table(future_financial_index,include_addiction,&
                            future_housing_status_index,has_opportunity_1,ev_slot),0.d0)

                        ! Hand the second pass the hours the first one found.
                        secant_guess=labor_supply_1
                        have_secant_guess=1

                    end if

                    end do

                    have_secant_guess=0

                    can_consume_drugs=1
                                                                                                                                                                                                                                                                                       
                    if ((consumption_choice>=(food_stamps_recieved/(1+consumption_tax))) .AND. &
                        (consumption_choice>0) .AND. (frac_spent_on_addiction>=0) .AND. &
                        (total_consumption_choice>=consumption_choice) .AND. (proceed_2==1) .AND. &
                        (can_consume_drugs==1)) then
                        
                        if (abs(consumption_choice-total_consumption_choice*(1-frac_spent_on_addiction))>10.d0**(-8)) then
            
                            write(*,*) "wrong_2"
                            write(*,*) "consumption_choice=", consumption_choice
                            write(*,*) "total_consumption_choice=", total_consumption_choice
                            write(*,*) "frac_spent_on_addiction=", frac_spent_on_addiction
                        
                        end if
                                                        
                        future_leisure_vector(future_financial_index)=relative_share_of_leisure*&
                            ((max_labor_supply-labor_supply_1)**(1-leisure_curvature))/(1-leisure_curvature)
                           
                        call calculate_flow_utility(0,future_housing_status_index,&
                            housing_size(future_housing_status_index),frac_spent_on_addiction,&
                            total_consumption_choice,consumption_choice,0,future_addiction_index,&
                            flow_utility_vector(future_financial_index),0)
                            
                        flow_utility_vector(future_financial_index)=&
                            flow_utility_vector(future_financial_index)+&
                            future_leisure_vector(future_financial_index)
                                                                                                                           
                        future_utility_vector=0
                        future_bequest_vector=0
                        
                        if (include_bequest_motive==1) then
                             
                            if ((age_index==life_span) .OR. (have_probablistic_death==1)) then
                            
                                call calculate_bequest_utility(financial_grid(future_financial_index),&
                                    future_bequest_vector(future_financial_index),is_homeless_1,addiction_index)
                                                                                    
                                 future_utility_vector(future_financial_index)=&
                                    future_utility_vector(future_financial_index)+&
                                    future_bequest_vector(future_financial_index)
                                                                           
                            end if
                            
                        end if
                        
                        ! The child, weighted by the chance the household does not
                        ! survive this period and by omega. It does not depend on
                        ! a', since the estate goes to the government rather than
                        ! to the child, so it shifts the housing and drug choices
                        ! and leaves the saving decision alone.
                        !
                        ! THE FIRST INDEX IS THE CHOICE, NOT THE INHERITED STATE.
                        ! It read addiction_index, which is set once from
                        ! unemployment_index before this loop and is the SUD state
                        ! the household arrives with. The maximisation here is over
                        ! future_addiction_index, so the term was identical across
                        ! every drug choice and could not enter that decision at
                        ! all -- a household could not weigh "if I use, my child is
                        ! worse off", which is the whole content of omega's moment.
                        ! The second index was already the choice: is_homeless_1 is
                        ! set from future_housing_status_index_to_use above.
                        if (include_child_in_continuation==1) then
                        
                            future_utility_vector(future_financial_index)=&
                                future_utility_vector(future_financial_index)+&
                                discount_factor*&
                                (1-survival_probability(age_index,is_homeless_1,survival_sud_of(addiction_index,treatment_choice_now),smi_of(unemployment_index)))*&
                                weight_on_child*expected_child_value(employment_index,future_addiction_index,is_homeless_1)
                        
                        end if
                        
                        ! THE TABULATED PATH. The sum below depends on a' only
                        ! through the value function lookup, so it is computed
                        ! once per (drug regime, chosen housing, eligibility) and
                        ! read here. The table is invalidated whenever the outer
                        ! state moves, detected from the module level loop
                        ! indices, so the calling code is untouched. The original
                        ! nest is kept and runs when the switch is off, which is
                        ! what makes the two comparable.
                        if (hoist_expectation==1) then

                            ev_slot=1
                            !$ ev_slot=omp_get_thread_num()+1

                            call ensure_ev_table(time_period,ev_slot,future_addiction_index,&
                                future_housing_status_index,future_housing_status_index_to_use,&
                                is_homeless_1,has_opportunity_1,voucher_index_1,&
                                first_voucher_index,second_voucher_index,loop_over_addiction_1,&
                                addiction_index)

                            if (smooth_addiction_hazard==1) then

                                ! The table carries the two continuations and no
                                ! hazard, so the weighting happens here, at the
                                ! one place where the quantity chosen at this node
                                ! is known.
                                do future_addiction_index_2=0,include_addiction

                                    future_utility_vector(future_financial_index)=&
                                        future_utility_vector(future_financial_index)+&
                                        addiction_transition(addiction_index,future_addiction_index_2,&
                                        future_addiction_index,is_homeless_1,&
                                        frac_spent_on_addiction*total_consumption_choice/&
                                        price_of_addictive_good,1,treatment_choice_now)*&
                                        ev_table(future_financial_index,future_addiction_index_2,&
                                        future_housing_status_index,has_opportunity_1,ev_slot)

                                end do

                            else

                                future_utility_vector(future_financial_index)=&
                                    future_utility_vector(future_financial_index)+&
                                    ev_table(future_financial_index,future_addiction_index,&
                                    future_housing_status_index,has_opportunity_1,ev_slot)

                            end if

                        else

                        do future_employment_index=&
                            at_least_one_period_before_retirement*employment_index+&
                            (1-at_least_one_period_before_retirement)*1,&
                            at_least_one_period_before_retirement*employment_index+&
                            (1-at_least_one_period_before_retirement)*employment_grid_size

                            ! FIXED PRODUCTIVITY, and a free win even without it. When the productivity
                            ! transition is the identity, eight of the nine branches carry zero mass and
                            ! the innermost nest is nine times larger than it needs to be. Skipping them
                            ! is exact, not an approximation, and it also prunes the near zero tails of
                            ! the Tauchen matrix when productivity is stochastic.
                            if (employment_process(age_index,employment_index,future_employment_index)<=0.d0) cycle

                        
                            do future_addiction_index_2=&
                                (1-loop_over_addiction_1)*future_addiction_index+loop_over_addiction_1*0,&
                                (1-loop_over_addiction_1)*future_addiction_index+loop_over_addiction_1*include_addiction
                            
                                check_1=0
                                
                                if (future_addiction_index_2==1) then
                                
                                    check_1=1
                                    
                                end if
                            
                                do future_unemployment_index=include_addiction*&
                                    ((1-check_1)*1+check_1*(threshold_addiction_index+1))+&
                                    (1-include_addiction)*(at_least_one_period_before_retirement*&
                                    (one_period_before_death*1+(1-one_period_before_death)*unemployment_index)+&
                                    (1-at_least_one_period_before_retirement)*1),include_addiction*&
                                    ((1-check_1)*threshold_addiction_index+check_1*unemployment_grid_size)+&
                                    (1-include_addiction)*(at_least_one_period_before_retirement*&
                                    (one_period_before_death*unemployment_grid_size+&
                                    (1-one_period_before_death)*unemployment_index)+&
                                    (1-at_least_one_period_before_retirement)*unemployment_grid_size)
                                    
                                    do future_voucher_index=first_voucher_index,second_voucher_index
                                                                                                                      
                                        future_utility_vector(future_financial_index)=&
                                            future_utility_vector(future_financial_index)+discount_factor*&
                                            survival_probability(age_index,is_homeless_1,survival_sud_of(addiction_index,treatment_choice_now),smi_of(unemployment_index))*&
                                            voucher_probabilities(voucher_index,future_voucher_index,&
                                            has_opportunity_1,voucher_index_1)*&
                                            employment_process(age_index,employment_index,future_employment_index)*&
                                            unemployment_process(age_index,unemployment_index,&
                                            future_unemployment_index,is_homeless_1,future_addiction_index_2,employment_index)*&
                                            addiction_transition(addiction_index,future_addiction_index_2,&
                                            future_addiction_index,is_homeless_1,&
                                            frac_spent_on_addiction*total_consumption_choice/&
                                            price_of_addictive_good,1,treatment_choice_now)*&
                                            value_function(1)%vector_transition_real&
                                            (min(time_period+solve_transition_dynamics,transition_length),age_index+1,&
                                            future_financial_index,future_unemployment_index,future_employment_index,&
                                            future_housing_status_index_to_use,future_voucher_index)
                                            
                                    end do
                                            
                                end do
                                                                                                                                                           
                            end do
                            
                        end do
                        
                        end if
                                                                       
                        value_function_renter_renter=flow_utility_vector(future_financial_index)+&
                            future_utility_vector(future_financial_index)

                        ! THIS BRANCH's best, kept separately from the running
                        ! maximum across branches. That is the whole of the
                        ! coarse mode bug: a branch that does not beat the
                        ! incumbent still has to know where its own optimum sat,
                        ! or the refinement looks in another branch's basin.
                        if ((global_search_index==0) .AND. &
                            (value_function_renter_renter>branch_best_1)) then

                            branch_best_1=value_function_renter_renter
                            branch_argmax_1=future_financial_index

                        end if

                        if (value_function_renter_renter>largest_value) then
                                                                    
                            largest_value=value_function_renter_renter

                            ! THE THREE POINTS THE LOTTERY WILL NEED, taken here
                            ! because here is where the winning branch is known
                            ! and its vectors are still the ones in scope. An
                            ! interior argmax only: at either end there is no
                            ! parabola to fit and the lottery refuses anyway.
                            interp_won_ok_1=.false.
                            interp_won_index_1=future_financial_index

                            if ((future_financial_index>1) .AND. &
                                (future_financial_index<financial_grid_size)) then

                                interp_won_y0_1=flow_utility_vector(future_financial_index-1)+&
                                    future_utility_vector(future_financial_index-1)
                                interp_won_y1_1=flow_utility_vector(future_financial_index)+&
                                    future_utility_vector(future_financial_index)
                                interp_won_y2_1=flow_utility_vector(future_financial_index+1)+&
                                    future_utility_vector(future_financial_index+1)
                                interp_won_ok_1=.true.

                            end if
                                                        
                            optimal_renter_renter_indeces(1)=future_financial_index
                            
                            if (global_search_index==0) then
                            
                                optimal_financial_1=future_financial_index
                                
                            end if
                            
                            optimal_renter_renter_indeces(2)=1
                            optimal_renter_renter_indeces(3)=future_housing_status_index
                            
                            optimal_consumption_renter_renter=consumption_choice
                            
                            if (consumption_choice<=0) then
                            
                                write(*,*) "renter renter eror"
                                
                            end if
                                                                          
                            optimal_after_tax_wealth_net_of_expenses_renter_renter=after_tax_wealth_net_of_expenses
                            optimal_gross_wage_income_renter_renter=gross_wage_income
                            optimal_cutoff_taxable_income_renter_renter=cutoff_taxable_income
                            optimal_wage_income_tax_paid_renter_renter=wage_income_tax_paid
                            optimal_space_lived_in_renter_renter=future_housing_status_index
                            optimal_mortgage_deductions_renter_renter=mortgage_deductions_tax_rebates
                            optimal_household_can_consume_renter_renter=1
                            optimal_labor_supply_renter_renter=labor_supply_1
                            optimal_frac_spent_on_addiction_renter_renter=frac_spent_on_addiction
                            optimal_total_consumption_renter_renter=total_consumption_choice
                            optimal_addiction_status_renter_renter=future_addiction_index
                            optimal_treatment_renter_renter=treatment_choice_1
                                                                                                                                                                                                                             
                        end if
                                                                                                                                                                                                                                                           
                    end if
                    
                end do
                
                end do

                end do

                ! Where this branch's optimum sat, for the next loop to start
                ! from. Threads own disjoint financial_index slices, so this is
                ! written without a race.
                if (warm_start_asset_search==1) then

                    warm_start_a_prime(age_index,financial_index,&
                        unemployment_index,employment_index,housing_status_index,&
                        voucher_index,future_addiction_index,future_housing_status_index)=&
                        branch_argmax_1

                end if
                
            end do

            end do

            treatment_choice_now=0
        
        end do
            
        value_function_renter_renter=largest_value  
            
    end subroutine
    
    subroutine renter_to_owner_problem(time_period,financial_index)
    
        use Global_Vars
        
        implicit none
        
        integer, intent(in) :: time_period,financial_index
        integer :: smallest_house,second_smallest_house,is_working_1,x_1,global_search_index
        integer :: max_future_mortgage_index,chooses_positive_mortgage,tenure_1,tenure_2,proceed_2,addiction_index,&
            optimal_financial_1,loop_over_addiction_1,check_1,allow_to_choose_addiction,can_consume_drugs
        real(8) :: max_mortgage_value_allowed,labor_supply_1,labor_supply_2,wealth_1
                                
        allow_to_choose_addiction=1
            
        if (age_index>max_age_to_choose_addiction) then
        
            allow_to_choose_addiction=0
                         
        end if
        
        addiction_index=0
        
        if (unemployment_index>threshold_addiction_index) then
        
            addiction_index=1
            
        end if
        
        proceed_2=1
        tenure_1=1
        tenure_2=0
        
        labor_supply_2=1
                
        is_working_1=1
        
        if ((in_retirement==1) .OR. &
            (emp_of(unemployment_index)>1)) then
        
            is_working_1=0
            
        end if
            
        largest_value=large_negative_num
        
        optimal_renter_owner_indeces(1)=1
        optimal_financial_1=1
        optimal_renter_owner_indeces(2)=max_amortization_years
        optimal_renter_owner_indeces(3)=index_of_smallest_house_hhld_can_buy
                 
        optimal_consumption_renter_owner=0
        optimal_after_tax_wealth_net_of_expenses_renter_owner=0
        optimal_gross_wage_income_renter_owner=0
        optimal_cutoff_taxable_income_renter_owner=0
        optimal_wage_income_tax_paid_renter_owner=0
        optimal_space_lived_in_renter_owner=index_of_smallest_house_hhld_can_buy
        optimal_mortgage_deductions_renter_owner=0
        optimal_household_can_consume_renter_owner=0
        optimal_labor_supply_renter_owner=((1-is_working_1)*0+is_working_1*1)
        labor_supply_1=optimal_labor_supply_renter_owner
        optimal_frac_spent_on_addiction_renter_owner=0
        optimal_total_consumption_renter_owner=0
        optimal_addiction_status_renter_owner=0
        
        if (fixed_labor_supply_at_benchmark==1) then
                    
            labor_supply_2=&
                policy_function_labor_supply(years_left_on_mortgage_index)%&
                vector_transition_real(time_period,age_index,financial_index,unemployment_index,&
                employment_index,housing_status_index,voucher_index)
                
            labor_supply_1=labor_supply_2
                
        end if
                
        do future_addiction_index=addiction_index,&
            (1-allow_to_choose_addiction)*addiction_index+allow_to_choose_addiction*&
            (include_addiction+(1-addiction_index)*include_heavy_vs_light_use_transitions)
        
            loop_over_addiction_1=0
                    
            if (addiction_index==1) then
            
                loop_over_addiction_1=1
                
            elseif ((future_addiction_index>=1) .AND. &
                (include_probability_of_becoming_addicted==1)) then
            
                loop_over_addiction_1=1
                
            end if
                
            do future_housing_status_index=index_of_smallest_house_hhld_can_buy,housing_status_grid_size-1
            
                smallest_house=0
                second_smallest_house=0
                
                if (can_get_mortgage==1) then
                
                    if (housing_price(time_period)*housing_size(future_housing_status_index)<=&
                        fraction_of_average_house_price_data*((1-is_counterfactual)*&
                        model_average_owner_occupied_unit_size(time_period)*&
                        housing_price(time_period)+is_counterfactual*&
                        average_owner_occupied_house_size_calibrated*calibrated_stationary_housing_price)) then
                                    
                        smallest_house=1
                        
                    elseif (housing_price(time_period)*housing_size(future_housing_status_index)<=&
                        2*fraction_of_average_house_price_data*((1-is_counterfactual)*&
                        model_average_owner_occupied_unit_size(time_period)*&
                        housing_price(time_period)+is_counterfactual*&
                        average_owner_occupied_house_size_calibrated*calibrated_stationary_housing_price)) then 
                        
                        second_smallest_house=1
                        
                    end if
                                    
                    if (in_retirement==1) then
                                                    
                        max_future_mortgage_index=negative_financial_grid_size
                                                    
                    else
                    
                        max_mortgage_value_allowed=&
                            real(1)-real(minimum_downpayment)+smallest_house*min_down_of_smallest+&
                            second_smallest_house*min_down_of_second_smallest
                    
                        max_future_mortgage_index=min(max(minloc(max_mortgage_value_allowed+&
                            financial_grid(1:negative_financial_grid_size),1,mask=(max_mortgage_value_allowed+&
                            financial_grid(1:negative_financial_grid_size))>0),1),negative_financial_grid_size)
                        
                    end if
                        
                else
                
                    max_future_mortgage_index=negative_financial_grid_size
                
                end if
                
                do global_search_index=0,coarse_grid
                            
                do future_mortgage_index=& ! max_future_mortgage_index,financial_grid_size ! &
                    (1-global_search_index)*max_future_mortgage_index+&
                    global_search_index*max(optimal_financial_1-grid_gaps+1,max_future_mortgage_index),&
                    (1-global_search_index)*financial_grid_size+&
                    global_search_index*min(optimal_financial_1+grid_gaps-1,financial_grid_size),&
                    (1-global_search_index)*grid_gaps+global_search_index
                    
                    if (future_mortgage_index<negative_financial_grid_size) then
                    
                        chooses_positive_mortgage=1
                    
                    else
                    
                        chooses_positive_mortgage=0
                    
                    end if
                                    
                    do future_years_of_amortization_index=2,max_amortization_years
                                                                                                   
                        if (((total_household_wealth-housing_price(time_period)*&
                            housing_size(future_housing_status_index)*(1+cost_of_buying+&
                            min(financial_grid(future_mortgage_index),0.d0)))>0) .AND. &
                            (-financial_grid(future_mortgage_index)<=(1-minimum_downpayment+smallest_house*min_down_of_smallest+&
                            second_smallest_house*min_down_of_second_smallest))) then
                                
                            space_lived_in_index_feasible=future_housing_status_index
                                                              
                            if (-financial_grid(future_mortgage_index)>(1-minimum_downpayment)) then
                                                            
                                pay_mortgage_insurance=1
                                max_mortgage_payments_as_fraction_of_income=max_debt_to_income_ratio
                                    
                            else
                                            
                                pay_mortgage_insurance=0
                                max_mortgage_payments_as_fraction_of_income=max_debt_to_income_ratio_below_80
                                                
                            end if
                            
                            if ((in_retirement==0) .AND. (fixed_labor_supply_at_benchmark==0)) then
                                        
                                labor_supply_2=1
                                                                    
                            end if
                                
                            call calculate_after_tax_wealth&
                                (financial_index,future_mortgage_index,years_left_on_mortgage_index,&
                                pay_mortgage_insurance,housing_status_index,future_housing_status_index,&
                                tenure_2,tenure_2,tenure_1,tenure_2,tenure_2,time_period,labor_supply_2,&
                                cutoff_taxable_income,future_addiction_index)
                                ! owner_to_owner_move_1,owner_to_renter_1,renter_to_owner_1,owner_to_owner_stay_1,renter_to_renter_1
                            
                            if (labor_supply_2>0.4) then
                            if ((in_retirement==0) .AND. (fixed_labor_supply_at_benchmark==0) .AND. &
                                (emp_of(unemployment_index)==1)) then
            
                                x_1=2
                                                            
                                call secant(time_period,financial_index,max(financial_grid(future_mortgage_index),0.d0)+&
                                    min(financial_grid(future_mortgage_index),0.d0)*&
                                    housing_price(time_period)*housing_size(future_housing_status_index),&
                                    housing_size(space_lived_in_index_feasible),space_lived_in_index_feasible,&
                                    x_1,after_tax_wealth_net_of_expenses,labor_supply_1,gross_wage_income,&
                                    wage_income_tax_paid,food_stamps_recieved,housing_voucher_recieved,&
                                    housing_voucher_recieved_2,mortgage_deductions_tax_rebates,proceed_2,&
                                    future_addiction_index)
                                                                                 
                            end if
                            end if
                                
                            if (chooses_positive_mortgage==1) then
                                
                                spending_on_housing=housing_price(time_period)*housing_size(future_housing_status_index)*&
                                    ((-min(financial_grid(future_mortgage_index),0.d0)*&
                                    (pay_mortgage_insurance*mortgage_insurance_premium+&
                                    mortgage_interest_rate(time_period)+average_fraction_of_mortgage_repaid))+&
                                    (fraction_of_property_taxes_in_GDS*property_tax(time_period)+&
                                    include_housing_depreciation_in_housing_costs*housing_depreciation_rate))
                                
                            else
                            
                                spending_on_housing=0
                                
                            end if
                                                                           
                            if (((spending_on_housing/(gross_wage_income+investment_income))<=&
                                max_mortgage_payments_as_fraction_of_income) .OR. &
                                (future_mortgage_index>=negative_financial_grid_size)) then
                                                                                                
                                can_consume_drugs=1
                                                               
                                flow_utility_vector(future_mortgage_index)=0
                                                                                                                        
                                if ((consumption_choice>=(food_stamps_recieved/(1+consumption_tax))) .AND. &
                                    (consumption_choice>0) .AND. (frac_spent_on_addiction>=0) .AND. &
                                    (total_consumption_choice>=consumption_choice) .AND. (proceed_2==1) .AND.&
                                    (can_consume_drugs==1)) then
                                    
                                    if (abs(consumption_choice-total_consumption_choice*&
                                        (1-frac_spent_on_addiction))>10.d0**(-8)) then
        
                                        write(*,*) "wrong_2"
                                        write(*,*) "consumption_choice=", consumption_choice
                                        write(*,*) "total_consumption_choice=", total_consumption_choice
                                        write(*,*) "frac_spent_on_addiction=", frac_spent_on_addiction
                                    
                                    end if
                                                                                                                                
                                    future_leisure_vector(future_mortgage_index)=&
                                        relative_share_of_leisure*((max_labor_supply-labor_supply_1)**&
                                        (1-leisure_curvature))/(1-leisure_curvature)
                                                                            
                                    call calculate_flow_utility(0,space_lived_in_index_feasible,&
                                        housing_size(space_lived_in_index_feasible),frac_spent_on_addiction,&
                                        total_consumption_choice,consumption_choice,1,future_addiction_index,&
                                        flow_utility_vector(future_mortgage_index),0)
                                        
                                    flow_utility_vector(future_mortgage_index)=&
                                        flow_utility_vector(future_mortgage_index)+&
                                        future_leisure_vector(future_mortgage_index)
                                                                                                                                                                                                                       
                                    future_utility_vector=0
                                    future_bequest_vector=0
                                    
                                    if (include_bequest_motive==1) then
                                                                              
                                        if ((age_index==life_span) .OR. (have_probablistic_death==1)) then
                                                                                
                                            wealth_1=housing_price(time_period)*&
                                                housing_size(future_housing_status_index)*(1-remove_tax_and_depreciation*&
                                                (property_tax(time_period)+housing_depreciation_rate)+&
                                                (1+mortgage_interest_rate(time_period))*&
                                                min(financial_grid(future_mortgage_index),0.d0))+&
                                                max(financial_grid(future_mortgage_index),0.d0)
                                                
                                            call calculate_bequest_utility(wealth_1,&
                                                future_bequest_vector(future_mortgage_index),1,addiction_index)
                                                                        
                                            future_utility_vector(future_mortgage_index)=&
                                                future_utility_vector(future_mortgage_index)+&
                                                future_bequest_vector(future_mortgage_index)
                                                                                                                                      
                                        end if
                                        
                                    end if
                                        
                                    do future_addiction_index_2=&
                                        (1-loop_over_addiction_1)*future_addiction_index+loop_over_addiction_1*0,&
                                        (1-loop_over_addiction_1)*future_addiction_index+loop_over_addiction_1*include_addiction
                                    
                                        check_1=0
                                        
                                        if (future_addiction_index_2==1) then
                                        
                                            check_1=1
                                            
                                        end if
                                                                        
                                        do future_unemployment_index=include_addiction*&
                                            ((1-check_1)*1+check_1*(threshold_addiction_index+1))+&
                                            (1-include_addiction)*(at_least_one_period_before_retirement*&
                                            (one_period_before_death*1+(1-one_period_before_death)*unemployment_index)+&
                                            (1-at_least_one_period_before_retirement)*1),include_addiction*&
                                            ((1-check_1)*threshold_addiction_index+check_1*unemployment_grid_size)+&
                                            (1-include_addiction)*(at_least_one_period_before_retirement*&
                                            (one_period_before_death*unemployment_grid_size+&
                                            (1-one_period_before_death)*unemployment_index)+&
                                            (1-at_least_one_period_before_retirement)*unemployment_grid_size)
                                                                                        
                                            do future_employment_index=&
                                                at_least_one_period_before_retirement*employment_index+&
                                                (1-at_least_one_period_before_retirement)*1,&
                                                at_least_one_period_before_retirement*employment_index+&
                                                (1-at_least_one_period_before_retirement)*employment_grid_size

                                                ! FIXED PRODUCTIVITY, and a free win even without it. When the productivity
                                                ! transition is the identity, eight of the nine branches carry zero mass and
                                                ! the innermost nest is nine times larger than it needs to be. Skipping them
                                                ! is exact, not an approximation, and it also prunes the near zero tails of
                                                ! the Tauchen matrix when productivity is stochastic.
                                                if (employment_process(age_index,employment_index,future_employment_index)<=0.d0) cycle

                                                                     
                                                future_utility_vector(future_mortgage_index)=&
                                                    future_utility_vector(future_mortgage_index)+discount_factor*&
                                                    survival_probability(age_index,1,survival_sud_of(addiction_index,treatment_choice_now),smi_of(unemployment_index))*&
                                                    employment_process(age_index,employment_index,future_employment_index)*&
                                                    unemployment_process(age_index,unemployment_index,&
                                                    future_unemployment_index,1,future_addiction_index_2,employment_index)*&
                                                    addiction_transition(addiction_index,future_addiction_index_2,&
                                                    future_addiction_index,1,&
                                                    frac_spent_on_addiction*total_consumption_choice/&
                                                    price_of_addictive_good,1,treatment_choice_now)*&
                                                    value_function(future_years_of_amortization_index)%&
                                                    vector_transition_real&
                                                    (min(time_period+solve_transition_dynamics,transition_length),&
                                                    age_index+1,future_mortgage_index,future_unemployment_index,&
                                                    future_employment_index,future_housing_status_index,0)
                                                    
                                            end do
                                                                                                                                                                                                                                                                                               
                                        end do
                                        
                                    end do
                                                                     
                                    value_function_renter_owner=flow_utility_vector(future_mortgage_index)+&
                                        future_utility_vector(future_mortgage_index)
                                                                                   
                                    if (value_function_renter_owner>largest_value) then
                                
                                        largest_value=value_function_renter_owner                               
                                                                          
                                        optimal_renter_owner_indeces(1)=future_mortgage_index
                                        
                                        if (global_search_index==0) then
                                        
                                            optimal_financial_1=future_mortgage_index
                                            
                                        end if
                                        
                                        optimal_renter_owner_indeces(2)=future_years_of_amortization_index
                                        optimal_renter_owner_indeces(3)=future_housing_status_index
                        
                                        optimal_consumption_renter_owner=consumption_choice
                                        
                                        if (consumption_choice<=0) then
                            
                                            write(*,*) "renter owner eror"
                                        
                                        end if
                                        
                                        optimal_after_tax_wealth_net_of_expenses_renter_owner=after_tax_wealth_net_of_expenses
                                            
                                        optimal_gross_wage_income_renter_owner=gross_wage_income
                                        optimal_cutoff_taxable_income_renter_owner=cutoff_taxable_income
                                        optimal_wage_income_tax_paid_renter_owner=wage_income_tax_paid
                                        optimal_space_lived_in_renter_owner=space_lived_in_index_feasible
                                        optimal_mortgage_deductions_renter_owner=mortgage_deductions_tax_rebates
                                        optimal_household_can_consume_renter_owner=1
                                        optimal_labor_supply_renter_owner=labor_supply_1
                                        optimal_frac_spent_on_addiction_renter_owner=frac_spent_on_addiction
                                        optimal_total_consumption_renter_owner=total_consumption_choice
                                        optimal_addiction_status_renter_owner=future_addiction_index
                                                                                                                                                                                                
                                    end if
                                                                                    
                                end if
                                
                            end if
                        
                        end if
                        
                    end do
                                   
                end do
                
                end do
                    
            end do
            
        end do
        
        value_function_renter_owner=largest_value
                
    end subroutine
    
    subroutine owners_problem(time_period,financial_index)
    
        use Global_Vars
        
        implicit none
            
        integer, intent(in) :: time_period,financial_index
                                                                                
        call owner_owner_stay_problem(time_period,financial_index)
        
        if (smallest_index_for_purchase==(housing_status_grid_size-1)) then
        
            value_function_owner_owner_move=large_negative_num
            
        else
                
            call owner_owner_move_problem(time_period,financial_index)
            
        end if
                
        call owner_renter_problem(time_period,financial_index)
                                            
        if (value_function_owner_owner_stay>value_function_owner_owner_move) then
        
            if (value_function_owner_owner_stay>value_function_owner_renter) then
                    
                value_function_owner=value_function_owner_owner_stay
                                                                                     
                optimal_owner_indeces(1)=optimal_owner_owner_stay_indeces(1)
                optimal_owner_indeces(2)=optimal_owner_owner_stay_indeces(2)
                optimal_owner_indeces(3)=optimal_owner_owner_stay_indeces(3)

                optimal_consumption_owner=optimal_consumption_owner_owner_stay
                optimal_after_tax_wealth_net_of_expenses_owner=&
                    optimal_after_tax_wealth_net_of_expenses_owner_owner_stay
                optimal_gross_wage_income_owner=optimal_gross_wage_income_owner_owner_stay
                optimal_cutoff_taxable_income_owner=optimal_cutoff_taxable_income_owner_owner_stay
                optimal_wage_income_tax_paid_owner=optimal_wage_income_tax_paid_owner_owner_stay
                optimal_space_lived_in_owner=optimal_space_lived_in_owner_owner_stay
                optimal_mortgage_deductions_owner=optimal_mortgage_deductions_owner_owner_stay
                optimal_household_can_consume_owner=optimal_household_can_consume_owner_owner_stay
                optimal_labor_supply_owner=optimal_labor_supply_owner_owner_stay
                optimal_frac_spent_on_addiction_owner=optimal_frac_spent_on_addiction_owner_owner_stay
                optimal_total_consumption_owner=optimal_total_consumption_owner_owner_stay
                optimal_addiction_status_owner=optimal_addiction_status_owner_owner_stay
                
                if ((unemployment_index>threshold_addiction_index) .AND. &
                    (optimal_addiction_status_owner_owner_stay==0) .AND. &
                    (optimal_after_tax_wealth_net_of_expenses_owner>0)) then
                
                    write(*,*) "wrong stay"
                
                end if
                
            else
            
                value_function_owner=value_function_owner_renter
                                                                                     
                optimal_owner_indeces(1)=optimal_owner_renter_indeces(1)
                optimal_owner_indeces(2)=optimal_owner_renter_indeces(2)
                optimal_owner_indeces(3)=optimal_owner_renter_indeces(3)

                optimal_consumption_owner=optimal_consumption_owner_renter
                optimal_after_tax_wealth_net_of_expenses_owner=&
                    optimal_after_tax_wealth_net_of_expenses_owner_renter
                optimal_gross_wage_income_owner=optimal_gross_wage_income_owner_renter
                 optimal_cutoff_taxable_income_owner=optimal_cutoff_taxable_income_owner_renter
                optimal_wage_income_tax_paid_owner=optimal_wage_income_tax_paid_owner_renter
                optimal_space_lived_in_owner=optimal_space_lived_in_owner_renter
                optimal_mortgage_deductions_owner=optimal_mortgage_deductions_owner_renter
                optimal_household_can_consume_owner=optimal_household_can_consume_owner_renter
                optimal_labor_supply_owner=optimal_labor_supply_owner_renter
                optimal_frac_spent_on_addiction_owner=optimal_frac_spent_on_addiction_owner_renter
                optimal_total_consumption_owner=optimal_total_consumption_owner_renter
                optimal_addiction_status_owner=optimal_addiction_status_owner_renter
                
                if ((unemployment_index>threshold_addiction_index) .AND. &
                    (optimal_addiction_status_owner_renter==0) .AND. &
                    (optimal_after_tax_wealth_net_of_expenses_owner>0)) then
                
                    write(*,*) "wrong owner renter"
                
                end if
                
            end if
            
        else
        
            if (value_function_owner_owner_move>value_function_owner_renter) then
                    
                value_function_owner=value_function_owner_owner_move
                                                                                     
                optimal_owner_indeces(1)=optimal_owner_owner_move_indeces(1)
                optimal_owner_indeces(2)=optimal_owner_owner_move_indeces(2)
                optimal_owner_indeces(3)=optimal_owner_owner_move_indeces(3)

                optimal_consumption_owner=optimal_consumption_owner_owner_move
                optimal_after_tax_wealth_net_of_expenses_owner=&
                    optimal_after_tax_wealth_net_of_expenses_owner_owner_move
                optimal_gross_wage_income_owner=optimal_gross_wage_income_owner_owner_move
                optimal_cutoff_taxable_income_owner=optimal_cutoff_taxable_income_owner_owner_move
                optimal_wage_income_tax_paid_owner=optimal_wage_income_tax_paid_owner_owner_move
                optimal_space_lived_in_owner=optimal_space_lived_in_owner_owner_move
                optimal_mortgage_deductions_owner=optimal_mortgage_deductions_owner_owner_move
                optimal_household_can_consume_owner=optimal_household_can_consume_owner_owner_move
                optimal_labor_supply_owner=optimal_labor_supply_owner_owner_move
                optimal_frac_spent_on_addiction_owner=optimal_frac_spent_on_addiction_owner_owner_move
                optimal_total_consumption_owner=optimal_total_consumption_owner_owner_move
                optimal_addiction_status_owner=optimal_addiction_status_owner_owner_move
                
                if ((unemployment_index>threshold_addiction_index) .AND. &
                    (optimal_addiction_status_owner_owner_move==0) .AND. &
                    (optimal_after_tax_wealth_net_of_expenses_owner>0)) then
                
                    write(*,*) "wrong owner ower move"
                
                end if

            else
            
                value_function_owner=value_function_owner_renter
                                                                                     
                optimal_owner_indeces(1)=optimal_owner_renter_indeces(1)
                optimal_owner_indeces(2)=optimal_owner_renter_indeces(2)
                optimal_owner_indeces(3)=optimal_owner_renter_indeces(3)

                optimal_consumption_owner=optimal_consumption_owner_renter
                optimal_after_tax_wealth_net_of_expenses_owner=&
                    optimal_after_tax_wealth_net_of_expenses_owner_renter
                optimal_gross_wage_income_owner=optimal_gross_wage_income_owner_renter
                optimal_cutoff_taxable_income_owner=optimal_cutoff_taxable_income_owner_renter
                optimal_wage_income_tax_paid_owner=optimal_wage_income_tax_paid_owner_renter
                optimal_space_lived_in_owner=optimal_space_lived_in_owner_renter
                optimal_mortgage_deductions_owner=optimal_mortgage_deductions_owner_renter
                optimal_household_can_consume_owner=optimal_household_can_consume_owner_renter
                optimal_labor_supply_owner=optimal_labor_supply_owner_renter
                optimal_frac_spent_on_addiction_owner=optimal_frac_spent_on_addiction_owner_renter
                optimal_total_consumption_owner=optimal_total_consumption_owner_renter
                optimal_addiction_status_owner=optimal_addiction_status_owner_renter
                
                if ((unemployment_index>threshold_addiction_index) .AND. &
                    (optimal_addiction_status_owner_renter==0) .AND.&
                    (optimal_after_tax_wealth_net_of_expenses_owner>0)) then
                
                    write(*,*) "wrong owner renter"
                
                end if
                
            end if
            
        end if
                                
    end subroutine
    
    subroutine owner_owner_stay_problem(time_period,financial_index)
    
        use Global_Vars
        
        implicit none
        
        integer, intent(in) :: time_period,financial_index
        integer :: max_future_mortgage_index,smallest_house,second_smallest_house,&
            tenure_1,tenure_2,proceed_2,is_working_1,x_1,addiction_index,global_search_index,optimal_financial_1,&
            first_iteration_1,loop_over_addiction_1,check_1,allow_to_choose_addiction,can_consume_drugs
        real(8) :: max_mortgage_value_allowed,labor_supply_1,labor_supply_2,wealth_1

        allow_to_choose_addiction=1
            
        if (age_index>max_age_to_choose_addiction) then
        
            allow_to_choose_addiction=0
                         
        end if
        
        addiction_index=0
        
        if (unemployment_index>threshold_addiction_index) then
        
            addiction_index=1
            
        end if

        proceed_2=1
        tenure_1=1
        tenure_2=0

        labor_supply_2=1
                
        is_working_1=1
        
        if ((in_retirement==1) .OR. &
            (emp_of(unemployment_index)>1)) then
        
            is_working_1=0
            
        end if
                                
        largest_value=large_negative_num
                        
        optimal_owner_owner_stay_indeces(1)=1
        optimal_financial_1=1
        optimal_owner_owner_stay_indeces(2)=years_left_on_mortgage_index
        optimal_owner_owner_stay_indeces(3)=housing_status_index
                                    
        optimal_gross_wage_income_owner_owner_stay=0
        optimal_cutoff_taxable_income_owner_owner_stay=0
        optimal_wage_income_tax_paid_owner_owner_stay=0
        optimal_after_tax_wealth_net_of_expenses_owner_owner_stay=0
        optimal_consumption_owner_owner_stay=0
        optimal_space_lived_in_owner_owner_stay=index_of_smallest_house_hhld_can_buy
        optimal_mortgage_deductions_owner_owner_stay=0
        optimal_household_can_consume_owner_owner_stay=0
        optimal_labor_supply_owner_owner_stay=((1-is_working_1)*0+is_working_1*1)
        labor_supply_1=optimal_labor_supply_owner_owner_stay
        optimal_frac_spent_on_addiction_owner_owner_stay=0
        optimal_total_consumption_owner_owner_stay=0
        optimal_addiction_status_owner_owner_stay=0
        
        if (fixed_labor_supply_at_benchmark==1) then
                    
            labor_supply_2=&
                policy_function_labor_supply(years_left_on_mortgage_index)%&
                vector_transition_real(time_period,age_index,financial_index,unemployment_index,&
                employment_index,housing_status_index,voucher_index)
                
            labor_supply_1=labor_supply_2
                
        end if
                                
        space_lived_in_index_feasible=housing_status_index
                
        do future_addiction_index=addiction_index,&
            (1-allow_to_choose_addiction)*addiction_index+allow_to_choose_addiction*&
            (include_addiction+(1-addiction_index)*include_heavy_vs_light_use_transitions)
        
            loop_over_addiction_1=0
                    
            if (addiction_index==1) then
            
                loop_over_addiction_1=1
                
            elseif ((future_addiction_index>=1) .AND. &
                (include_probability_of_becoming_addicted==1)) then
            
                loop_over_addiction_1=1
                
            end if
                                 
            smallest_house=0
            second_smallest_house=0 
                        
            if (can_get_mortgage==1) then
                                  
                if (housing_price(time_period)*housing_size(housing_status_index)<=&
                    fraction_of_average_house_price_data*((1-is_counterfactual)*&
                    model_average_owner_occupied_unit_size(time_period)*&
                    housing_price(time_period)+is_counterfactual*&
                    average_owner_occupied_house_size_calibrated*calibrated_stationary_housing_price)) then
                                
                    smallest_house=1
                    
                elseif (housing_price(time_period)*housing_size(housing_status_index)<=&
                    2*fraction_of_average_house_price_data*((1-is_counterfactual)*&
                    model_average_owner_occupied_unit_size(time_period)*&
                    housing_price(time_period)+is_counterfactual*&
                    average_owner_occupied_house_size_calibrated*calibrated_stationary_housing_price)) then 
                    
                    second_smallest_house=1
                    
                end if
                
                if (in_retirement==1) then
                   
                    max_mortgage_value_allowed=-min(financial_grid(financial_index),0.d0)*(1-fraction_to_repay)
                        
                    max_future_mortgage_index=min(max(minloc(max_mortgage_value_allowed+&
                        financial_grid(1:negative_financial_grid_size),1,mask=(max_mortgage_value_allowed+&
                        financial_grid(1:negative_financial_grid_size))>=0),1),negative_financial_grid_size)
                                                            
                else
                    
                    max_mortgage_value_allowed=real(1)-real(minimum_downpayment)+&
                        smallest_house*min_down_of_smallest+second_smallest_house*min_down_of_second_smallest
                
                    max_future_mortgage_index=min(max(minloc(max_mortgage_value_allowed+&
                        financial_grid(1:negative_financial_grid_size),1,&
                        mask=(max_mortgage_value_allowed+financial_grid(1:negative_financial_grid_size))>=0),1),&
                        negative_financial_grid_size)
                    
                end if
                    
            else
            
                max_future_mortgage_index=negative_financial_grid_size
            
            end if
            
            do global_search_index=coarse_grid*(-1),coarse_grid
            
            first_iteration_1=0
                
            if (global_search_index==-1) then
            
                first_iteration_1=1
                
            end if
                                                        
            do future_mortgage_index=& !max_future_mortgage_index,financial_grid_size
                first_iteration_1*financial_index+&
                (1-first_iteration_1)*((1-global_search_index)*max_future_mortgage_index+&
                global_search_index*max(optimal_financial_1-grid_gaps+1,max_future_mortgage_index)),&
                first_iteration_1*min(financial_index+2,financial_grid_size)+&
                (1-first_iteration_1)*((1-global_search_index)*financial_grid_size+&
                global_search_index*min(optimal_financial_1+grid_gaps-1,financial_grid_size)),&
                first_iteration_1*1+(1-first_iteration_1)*((1-global_search_index)*grid_gaps+global_search_index)
                                                    
                do future_years_of_amortization_index=2,max_amortization_years
                                
                    if (-financial_grid(future_mortgage_index)>(1-minimum_downpayment)) then
                                                    
                        pay_mortgage_insurance=1
                        max_mortgage_payments_as_fraction_of_income=max_debt_to_income_ratio
                            
                    else
                                    
                        pay_mortgage_insurance=0
                        max_mortgage_payments_as_fraction_of_income=max_debt_to_income_ratio_below_80
                                        
                    end if
                    
                    if ((in_retirement==0) .AND. (fixed_labor_supply_at_benchmark==0)) then
                                             
                        labor_supply_2=1
                                               
                    end if
                                                     
                    call calculate_after_tax_wealth&
                        (financial_index,future_mortgage_index,years_left_on_mortgage_index,pay_mortgage_insurance,&
                        housing_status_index,housing_status_index,tenure_2,tenure_2,tenure_2,tenure_1,tenure_2,&
                        time_period,labor_supply_2,cutoff_taxable_income,future_addiction_index)
                        ! owner_to_owner_move_1,owner_to_renter_1,renter_to_owner_1,owner_to_owner_stay_1,renter_to_renter_1
                     
                    if (labor_supply_2>0.4) then 
                    if ((in_retirement==0) .AND. (fixed_labor_supply_at_benchmark==0) .AND. &
                        ((emp_of(unemployment_index)==1))) then
                                            
                        x_1=2
                                            
                        call secant(time_period,financial_index,max(financial_grid(future_mortgage_index),0.d0)+&
                            min(financial_grid(future_mortgage_index),0.d0)*&
                            housing_price(time_period)*housing_size(housing_status_index),&
                            housing_size(space_lived_in_index_feasible),space_lived_in_index_feasible,&
                            x_1,after_tax_wealth_net_of_expenses,labor_supply_1,gross_wage_income,&
                            wage_income_tax_paid,food_stamps_recieved,housing_voucher_recieved,&
                            housing_voucher_recieved_2,mortgage_deductions_tax_rebates,proceed_2,future_addiction_index)
                                                                   
                    end if
                    end if
                    
                    if (future_mortgage_index<negative_financial_grid_size) then
                                                                   
                        if (financial_grid(future_mortgage_index)<(1-fraction_to_repay)*financial_grid(financial_index)) then
                            
                            spending_on_housing=housing_price(time_period)*housing_size(housing_status_index)*&
                                ((-min(financial_grid(future_mortgage_index),0.d0)*&
                                (pay_mortgage_insurance*mortgage_insurance_premium+&
                                mortgage_interest_rate(time_period)+average_fraction_of_mortgage_repaid))+&
                                (fraction_of_property_taxes_in_GDS*property_tax(time_period)+&
                                include_housing_depreciation_in_housing_costs*housing_depreciation_rate))
                            
                        else
                        
                            spending_on_housing=0
                        
                        end if
                                                                      
                    else
                    
                        spending_on_housing=0
                    
                    end if
                        
                    if (((spending_on_housing/(gross_wage_income+investment_income))<=&
                        max_mortgage_payments_as_fraction_of_income) .OR. &
                        (future_mortgage_index>=negative_financial_grid_size)) then
                        
                        can_consume_drugs=1
                                                                                      
                        if ((consumption_choice>=(food_stamps_recieved/(1+consumption_tax))) .AND. &
                            (consumption_choice>0) .AND. (frac_spent_on_addiction>=0) .AND. &
                            (total_consumption_choice>=consumption_choice) .AND. (proceed_2==1) .AND. &
                            (can_consume_drugs==1)) then
                            
                            if (abs(consumption_choice-total_consumption_choice*(1-frac_spent_on_addiction))>10.d0**(-8)) then
        
                                write(*,*) "wrong_2"
                                write(*,*) "consumption_choice=", consumption_choice
                                write(*,*) "total_consumption_choice=", total_consumption_choice
                                write(*,*) "frac_spent_on_addiction=", frac_spent_on_addiction
                            
                            end if
                                                                            
                            future_leisure_vector(future_mortgage_index)=relative_share_of_leisure*&
                                ((max_labor_supply-labor_supply_1)**(1-leisure_curvature))/(1-leisure_curvature)
                                                            
                            call calculate_flow_utility(0,space_lived_in_index_feasible,&
                                housing_size(space_lived_in_index_feasible),frac_spent_on_addiction,&
                                total_consumption_choice,consumption_choice,1,future_addiction_index,&
                                flow_utility_vector(future_mortgage_index),0)
                                
                            flow_utility_vector(future_mortgage_index)=&
                                flow_utility_vector(future_mortgage_index)+&
                                future_leisure_vector(future_mortgage_index)
                                                                                                                                                                                                               
                            future_utility_vector=0
                            future_bequest_vector=0
                            
                            if (include_bequest_motive==1) then
                                                                      
                                if ((age_index==life_span) .OR. (have_probablistic_death==1)) then
                                
                                    wealth_1=housing_price(time_period)*housing_size(housing_status_index)*&
                                        (1-remove_tax_and_depreciation*&
                                        (property_tax(time_period)+housing_depreciation_rate)+&
                                        (1+mortgage_interest_rate(time_period))*&
                                        min(financial_grid(future_mortgage_index),0.d0))+&
                                        max(financial_grid(future_mortgage_index),0.d0)
                                        
                                    call calculate_bequest_utility(wealth_1,&
                                        future_bequest_vector(future_mortgage_index),1,addiction_index)
                                                                
                                    future_utility_vector(future_mortgage_index)=&
                                        future_utility_vector(future_mortgage_index)+&
                                        future_bequest_vector(future_mortgage_index)
                                                                                                                                                            
                                end if
                                
                            end if
                                
                            do future_addiction_index_2=&
                                (1-loop_over_addiction_1)*future_addiction_index+loop_over_addiction_1*0,&
                                (1-loop_over_addiction_1)*future_addiction_index+loop_over_addiction_1*include_addiction
                            
                                check_1=0
                                
                                if (future_addiction_index_2==1) then
                                
                                    check_1=1
                                    
                                end if
                                                        
                                do future_unemployment_index=include_addiction*&
                                    ((1-check_1)*1+check_1*(threshold_addiction_index+1))+&
                                    (1-include_addiction)*(at_least_one_period_before_retirement*&
                                    (one_period_before_death*1+(1-one_period_before_death)*unemployment_index)+&
                                    (1-at_least_one_period_before_retirement)*1),include_addiction*&
                                    ((1-check_1)*threshold_addiction_index+check_1*unemployment_grid_size)+&
                                    (1-include_addiction)*(at_least_one_period_before_retirement*&
                                    (one_period_before_death*unemployment_grid_size+&
                                    (1-one_period_before_death)*unemployment_index)+&
                                    (1-at_least_one_period_before_retirement)*unemployment_grid_size)
                                                                                
                                    do future_employment_index=&
                                        at_least_one_period_before_retirement*employment_index+&
                                        (1-at_least_one_period_before_retirement)*1,&
                                        at_least_one_period_before_retirement*employment_index+&
                                        (1-at_least_one_period_before_retirement)*employment_grid_size

                                        ! FIXED PRODUCTIVITY, and a free win even without it. When the productivity
                                        ! transition is the identity, eight of the nine branches carry zero mass and
                                        ! the innermost nest is nine times larger than it needs to be. Skipping them
                                        ! is exact, not an approximation, and it also prunes the near zero tails of
                                        ! the Tauchen matrix when productivity is stochastic.
                                        if (employment_process(age_index,employment_index,future_employment_index)<=0.d0) cycle

                                                                                                                                                                                                                                           
                                        future_utility_vector(future_mortgage_index)=&
                                            future_utility_vector(future_mortgage_index)+&
                                            discount_factor*survival_probability(age_index,1,survival_sud_of(addiction_index,treatment_choice_now),smi_of(unemployment_index))*&
                                            employment_process(age_index,employment_index,future_employment_index)*&
                                            unemployment_process(age_index,unemployment_index,&
                                            future_unemployment_index,1,future_addiction_index_2,employment_index)*&
                                            addiction_transition(addiction_index,future_addiction_index_2,&
                                            future_addiction_index,1,&
                                            frac_spent_on_addiction*total_consumption_choice/&
                                            price_of_addictive_good,1,treatment_choice_now)*&
                                            value_function(future_years_of_amortization_index)%&
                                            vector_transition_real(min(time_period+solve_transition_dynamics,transition_length),&
                                            age_index+1,future_mortgage_index,future_unemployment_index,&
                                            future_employment_index,housing_status_index,0)
                                                                                                                            
                                    end do
                                    
                                end do
                            
                            end do
                                                                                            
                            value_function_owner_owner_stay=&
                                flow_utility_vector(future_mortgage_index)+&
                                future_utility_vector(future_mortgage_index)
                                                                          
                            if (value_function_owner_owner_stay>largest_value) then
                        
                                largest_value=value_function_owner_owner_stay
                                                                                                  
                                optimal_owner_owner_stay_indeces(1)=future_mortgage_index
                                
                                if (global_search_index<=0) then
                                
                                    optimal_financial_1=optimal_owner_owner_stay_indeces(1)
                                    
                                end if
                                
                                optimal_owner_owner_stay_indeces(2)=future_years_of_amortization_index
                                optimal_owner_owner_stay_indeces(3)=housing_status_index
                                optimal_consumption_owner_owner_stay=consumption_choice
                                
                                if (consumption_choice<=0) then
                            
                                    write(*,*) "owner owner stay eror"
                                    
                                end if
                                
                                optimal_after_tax_wealth_net_of_expenses_owner_owner_stay=after_tax_wealth_net_of_expenses
                                optimal_gross_wage_income_owner_owner_stay=gross_wage_income
                                optimal_cutoff_taxable_income_owner_owner_stay=cutoff_taxable_income
                                optimal_wage_income_tax_paid_owner_owner_stay=wage_income_tax_paid
                                optimal_space_lived_in_owner_owner_stay=space_lived_in_index_feasible
                                optimal_mortgage_deductions_owner_owner_stay=mortgage_deductions_tax_rebates
                                optimal_household_can_consume_owner_owner_stay=1     
                                optimal_labor_supply_owner_owner_stay=labor_supply_1
                                optimal_frac_spent_on_addiction_owner_owner_stay=frac_spent_on_addiction
                                optimal_total_consumption_owner_owner_stay=total_consumption_choice
                                optimal_addiction_status_owner_owner_stay=future_addiction_index
                                
                                if ((unemployment_index>threshold_addiction_index) .AND. &
                                    (optimal_addiction_status_owner_owner_stay==0)) then
                                
                                    write(*,*) "wrong stay 1"
                                
                                end if
                                                                                                                                        
                            end if
                                                                            
                        end if
                        
                    end if
                                            
                end do
                
                end do
                                    
            end do
            
        end do
        
        value_function_owner_owner_stay=largest_value
        
    end subroutine
        
    subroutine owner_owner_move_problem(time_period,financial_index)
    
        use Global_Vars
        
        implicit none
            
        integer, intent(in) :: time_period,financial_index
        integer :: smallest_house,second_smallest_house,is_working_1,x_1,&
            global_search_index,optimal_financial_1,loop_over_addiction_1,check_1
        integer :: max_future_mortgage_index,chooses_positive_mortgage,tenure_1,tenure_2,proceed_2,addiction_index,&
            allow_to_choose_addiction,can_consume_drugs
        real(8) :: max_mortgage_value_allowed,labor_supply_1,labor_supply_2,wealth_1
                                
        allow_to_choose_addiction=1
            
        if (age_index>max_age_to_choose_addiction) then
        
            allow_to_choose_addiction=0
                         
        end if
        
        addiction_index=0
        
        if (unemployment_index>threshold_addiction_index) then
        
            addiction_index=1
            
        end if
        
        proceed_2=1
        tenure_1=1
        tenure_2=0
                
        labor_supply_2=1
                
        is_working_1=1
        
        if ((in_retirement==1) .OR. &
            (emp_of(unemployment_index)>1)) then
        
            is_working_1=0
            
        end if
        
        largest_value=large_negative_num
                        
        optimal_owner_owner_move_indeces(1)=1
        optimal_financial_1=1
        optimal_owner_owner_move_indeces(2)=max_amortization_years
        optimal_owner_owner_move_indeces(3)=index_of_smallest_house_hhld_can_buy
                                    
        optimal_consumption_owner_owner_move=0
        optimal_gross_wage_income_owner_owner_move=0
        optimal_cutoff_taxable_income_owner_owner_move=0
        optimal_wage_income_tax_paid_owner_owner_move=0
        optimal_after_tax_wealth_net_of_expenses_owner_owner_move=0
        optimal_space_lived_in_owner_owner_move=index_of_smallest_house_hhld_can_buy
        optimal_mortgage_deductions_owner_owner_move=0
        optimal_household_can_consume_owner_owner_move=0
        optimal_labor_supply_owner_owner_move=((1-is_working_1)*0+is_working_1*1)
        labor_supply_1=optimal_labor_supply_owner_owner_move
        optimal_frac_spent_on_addiction_owner_owner_move=0
        optimal_total_consumption_owner_owner_move=0
        optimal_addiction_status_owner_owner_move=0
        
        if (fixed_labor_supply_at_benchmark==1) then
                    
            labor_supply_2=&
                policy_function_labor_supply(years_left_on_mortgage_index)%&
                vector_transition_real(time_period,age_index,financial_index,unemployment_index,&
                employment_index,housing_status_index,voucher_index)
                
            labor_supply_1=labor_supply_2
                
        end if
                
        do future_addiction_index=addiction_index,&
            (1-allow_to_choose_addiction)*addiction_index+allow_to_choose_addiction*&
            (include_addiction+(1-addiction_index)*include_heavy_vs_light_use_transitions)
        
            loop_over_addiction_1=0
                
            if (addiction_index==1) then
            
                loop_over_addiction_1=1
                
            elseif ((future_addiction_index>=1) .AND. &
                (include_probability_of_becoming_addicted==1)) then
            
                loop_over_addiction_1=1
                
            end if
                                        
            do future_housing_status_index=index_of_smallest_house_hhld_can_buy,housing_status_grid_size-1
            
                smallest_house=0
                second_smallest_house=0
                
                if (future_housing_status_index==-1) then
                
                else
                
                    if (can_get_mortgage==1) then
                    
                        if (housing_price(time_period)*housing_size(future_housing_status_index)<=&
                            fraction_of_average_house_price_data*((1-is_counterfactual)*&
                            model_average_owner_occupied_unit_size(time_period)*&
                            housing_price(time_period)+is_counterfactual*&
                            average_owner_occupied_house_size_calibrated*calibrated_stationary_housing_price)) then
                                    
                            smallest_house=1
                            
                        elseif (housing_price(time_period)*housing_size(future_housing_status_index)<=&
                            2*fraction_of_average_house_price_data*((1-is_counterfactual)*&
                            model_average_owner_occupied_unit_size(time_period)*&
                            housing_price(time_period)+is_counterfactual*&
                            average_owner_occupied_house_size_calibrated*calibrated_stationary_housing_price)) then 
                            
                            second_smallest_house=1
                            
                        end if
                        
                        if (in_retirement==1) then
                                                            
                            max_future_mortgage_index=negative_financial_grid_size
                                                            
                        else
                                                        
                            max_mortgage_value_allowed=real(1)-real(minimum_downpayment)+&
                                smallest_house*min_down_of_smallest+second_smallest_house*min_down_of_second_smallest
                        
                            max_future_mortgage_index=min(max(minloc(max_mortgage_value_allowed+&
                                financial_grid(1:negative_financial_grid_size),1,&
                                mask=(max_mortgage_value_allowed+financial_grid(1:negative_financial_grid_size))>=0),1),&
                                negative_financial_grid_size)
                            
                        end if
                            
                    else
                    
                        max_future_mortgage_index=negative_financial_grid_size
                    
                    end if
                    
                    do global_search_index=0,coarse_grid
                                                        
                    do future_mortgage_index=& !max_future_mortgage_index,financial_grid_size !&
                        (1-global_search_index)*max_future_mortgage_index+&
                        global_search_index*max(optimal_financial_1-grid_gaps+1,max_future_mortgage_index),&
                        (1-global_search_index)*financial_grid_size+&
                        global_search_index*min(optimal_financial_1+grid_gaps-1,financial_grid_size),&
                        (1-global_search_index)*grid_gaps+global_search_index
                        
                        if (future_mortgage_index<negative_financial_grid_size) then
                        
                            chooses_positive_mortgage=1
                        
                        else
                        
                            chooses_positive_mortgage=0
                        
                        end if
                                            
                        do future_years_of_amortization_index=2,max_amortization_years
                                                                                                      
                            if (((total_household_wealth+min(financial_grid(financial_index),0.d0)*&
                                housing_price(time_period)*housing_size(housing_status_index)*&
                                (1+mortgage_interest_rate(time_period))-housing_price(time_period)*&
                                (housing_size(housing_status_index)*cost_of_selling+&
                                housing_size(future_housing_status_index)*cost_of_buying)-&
                                housing_price(time_period)*housing_size(future_housing_status_index)*&
                                (1+min(financial_grid(future_mortgage_index),0.d0)))>0) .AND. &
                                (-financial_grid(future_mortgage_index)<&
                                (1-minimum_downpayment+smallest_house*min_down_of_smallest+&
                                second_smallest_house*min_down_of_second_smallest))) then
                                                                        
                                space_lived_in_index_feasible=future_housing_status_index
                                    
                                if (-financial_grid(future_mortgage_index)>(1-minimum_downpayment)) then
                                                                
                                    pay_mortgage_insurance=1
                                    max_mortgage_payments_as_fraction_of_income=max_debt_to_income_ratio
                                        
                                else
                                                
                                    pay_mortgage_insurance=0
                                    max_mortgage_payments_as_fraction_of_income=max_debt_to_income_ratio_below_80
                                                    
                                end if
                                
                                if ((in_retirement==0) .AND. (fixed_labor_supply_at_benchmark==0)) then
                                            
                                    labor_supply_2=1
                                                                        
                                end if
                                    
                                call calculate_after_tax_wealth&
                                    (financial_index,future_mortgage_index,years_left_on_mortgage_index,&
                                    pay_mortgage_insurance,housing_status_index,future_housing_status_index,&
                                    tenure_1,tenure_2,tenure_2,tenure_2,tenure_2,time_period,labor_supply_2,&
                                    cutoff_taxable_income,future_addiction_index)
                                    ! owner_to_owner_move_1,owner_to_renter_1,renter_to_owner_1,owner_to_owner_stay_1,renter_to_renter_1
                                   
                                if (labor_supply_2>0.4) then
                                if ((in_retirement==0) .AND. (fixed_labor_supply_at_benchmark==0).AND. &
                                    ((emp_of(unemployment_index)==1))) then
                
                                    x_1=2
                                                                
                                    call secant(time_period,financial_index,max(financial_grid(future_mortgage_index),0.d0)+&
                                        min(financial_grid(future_mortgage_index),0.d0)*&
                                        housing_price(time_period)*housing_size(future_housing_status_index),&
                                        housing_size(space_lived_in_index_feasible),future_housing_status_index,&
                                        x_1,after_tax_wealth_net_of_expenses,labor_supply_1,gross_wage_income,&
                                        wage_income_tax_paid,food_stamps_recieved,housing_voucher_recieved,&
                                        housing_voucher_recieved_2,mortgage_deductions_tax_rebates,proceed_2,&
                                        future_addiction_index)
                                                                                        
                                end if
                                end if
                                                                
                                if (chooses_positive_mortgage==1) then
                                                                                                                                                                            
                                    spending_on_housing=&
                                        housing_price(time_period)*housing_size(future_housing_status_index)*&
                                        ((-min(financial_grid(future_mortgage_index),0.d0)*&
                                        (pay_mortgage_insurance*mortgage_insurance_premium+&
                                        mortgage_interest_rate(time_period)+average_fraction_of_mortgage_repaid))+&
                                        (fraction_of_property_taxes_in_GDS*property_tax(time_period)+&
                                        include_housing_depreciation_in_housing_costs*housing_depreciation_rate))
                                        
                                else
                                
                                    spending_on_housing=0
                                
                                end if
                                                                                
                                if (((spending_on_housing/(gross_wage_income+investment_income))<=&
                                    max_mortgage_payments_as_fraction_of_income) .OR. &
                                    (future_mortgage_index>=negative_financial_grid_size)) then
                                    
                                    can_consume_drugs=1
                                                                        
                                    if ((consumption_choice>=(food_stamps_recieved/(1+consumption_tax))) .AND. &
                                        (consumption_choice>0) .AND. (frac_spent_on_addiction>=0) .AND. &
                                        (total_consumption_choice>=consumption_choice) .AND. (proceed_2==1) .AND. &
                                        (can_consume_drugs==1)) then
                                        
                                        if (abs(consumption_choice-total_consumption_choice*&
                                            (1-frac_spent_on_addiction))>10.d0**(-8)) then
        
                                            write(*,*) "wrong_2"
                                            write(*,*) "consumption_choice=", consumption_choice
                                            write(*,*) "total_consumption_choice=", total_consumption_choice
                                            write(*,*) "frac_spent_on_addiction=", frac_spent_on_addiction
                                        
                                        end if
                                                                                                                
                                        future_leisure_vector(future_mortgage_index)=&
                                            relative_share_of_leisure*((max_labor_supply-labor_supply_1)**&
                                            (1-leisure_curvature))/(1-leisure_curvature)
                                                                                    
                                        call calculate_flow_utility(0,space_lived_in_index_feasible,&
                                            housing_size(space_lived_in_index_feasible),frac_spent_on_addiction,&
                                            total_consumption_choice,consumption_choice,1,future_addiction_index,&
                                            flow_utility_vector(future_mortgage_index),0)
                                            
                                        flow_utility_vector(future_mortgage_index)=&
                                            flow_utility_vector(future_mortgage_index)+&
                                            future_leisure_vector(future_mortgage_index)
                                                                                                                                                                                                                                                       
                                        future_utility_vector=0
                                        future_bequest_vector=0
                                        
                                        if (include_bequest_motive==1) then
                                        
                                            if ((age_index==life_span) .OR. (have_probablistic_death==1)) then
                                            
                                                wealth_1=housing_price(time_period)*&
                                                    housing_size(future_housing_status_index)*&
                                                    (1-remove_tax_and_depreciation*&
                                                    (property_tax(time_period)+housing_depreciation_rate)+&
                                                    (1+mortgage_interest_rate(time_period))*&
                                                    min(financial_grid(future_mortgage_index),0.d0))+&
                                                    max(financial_grid(future_mortgage_index),0.d0)
                                                    
                                                call calculate_bequest_utility(wealth_1,&
                                                    future_bequest_vector(future_mortgage_index),1,addiction_index)
                                                                            
                                                future_utility_vector(future_mortgage_index)=&
                                                    future_utility_vector(future_mortgage_index)+&
                                                    future_bequest_vector(future_mortgage_index)
                                                                                                                                                            
                                            end if
                                            
                                        end if
                                        
                                        do future_addiction_index_2=&
                                            (1-loop_over_addiction_1)*future_addiction_index+loop_over_addiction_1*0,&
                                            (1-loop_over_addiction_1)*future_addiction_index+loop_over_addiction_1*include_addiction
                                        
                                            check_1=0
                                            
                                            if (future_addiction_index_2==1) then
                                            
                                                check_1=1
                                                
                                            end if
                                        
                                            do future_unemployment_index=include_addiction*&
                                                ((1-check_1)*1+check_1*(threshold_addiction_index+1))+&
                                                (1-include_addiction)*(at_least_one_period_before_retirement*&
                                                (one_period_before_death*1+(1-one_period_before_death)*unemployment_index)+&
                                                (1-at_least_one_period_before_retirement)*1),include_addiction*&
                                                ((1-check_1)*threshold_addiction_index+check_1*unemployment_grid_size)+&
                                                (1-include_addiction)*(at_least_one_period_before_retirement*&
                                                (one_period_before_death*unemployment_grid_size+&
                                                (1-one_period_before_death)*unemployment_index)+&
                                                (1-at_least_one_period_before_retirement)*unemployment_grid_size)
                                                                                            
                                                do future_employment_index=&
                                                    at_least_one_period_before_retirement*employment_index+&
                                                    (1-at_least_one_period_before_retirement)*1,&
                                                    at_least_one_period_before_retirement*employment_index+&
                                                    (1-at_least_one_period_before_retirement)*employment_grid_size

                                                    ! FIXED PRODUCTIVITY, and a free win even without it. When the productivity
                                                    ! transition is the identity, eight of the nine branches carry zero mass and
                                                    ! the innermost nest is nine times larger than it needs to be. Skipping them
                                                    ! is exact, not an approximation, and it also prunes the near zero tails of
                                                    ! the Tauchen matrix when productivity is stochastic.
                                                    if (employment_process(age_index,employment_index,future_employment_index)<=0.d0) cycle

                                                                                                                                                                                                                                                                                                 
                                                    future_utility_vector(future_mortgage_index)=&
                                                        future_utility_vector(future_mortgage_index)+&
                                                        discount_factor*survival_probability(age_index,1,survival_sud_of(addiction_index,treatment_choice_now),smi_of(unemployment_index))*&
                                                        employment_process(age_index,employment_index,future_employment_index)*&
                                                        unemployment_process(age_index,unemployment_index,&
                                                        future_unemployment_index,1,future_addiction_index_2,employment_index)*&
                                                        addiction_transition(addiction_index,future_addiction_index_2,&
                                                        future_addiction_index,1,&
                                                        frac_spent_on_addiction*total_consumption_choice/&
                                                        price_of_addictive_good,1,treatment_choice_now)*&
                                                        value_function(future_years_of_amortization_index)%vector_transition_real&
                                                        (min(time_period+solve_transition_dynamics,transition_length),age_index+1,&
                                                        future_mortgage_index,future_unemployment_index,future_employment_index,&
                                                        future_housing_status_index,0)
                                                        
                                                end do
                                                
                                            end do
                                            
                                        end do
                                                                            
                                        value_function_owner_owner_move=flow_utility_vector(future_mortgage_index)+&
                                            future_utility_vector(future_mortgage_index)
                                                                                  
                                        if (value_function_owner_owner_move>largest_value) then
                                    
                                            largest_value=value_function_owner_owner_move
                                                                              
                                            optimal_owner_owner_move_indeces(1)=future_mortgage_index
                                            optimal_owner_owner_move_indeces(2)=future_years_of_amortization_index
                                            optimal_owner_owner_move_indeces(3)=future_housing_status_index
                                            
                                            if (global_search_index==0) then
                                            
                                                optimal_financial_1=future_mortgage_index
                                                
                                            end if
                            
                                            optimal_consumption_owner_owner_move=consumption_choice
                                            
                                            if (consumption_choice<=0) then
                            
                                                write(*,*) "owner owner move eror"
                                                
                                            end if
                                                                                        
                                            optimal_after_tax_wealth_net_of_expenses_owner_owner_move=&
                                                after_tax_wealth_net_of_expenses
                                                
                                            optimal_gross_wage_income_owner_owner_move=gross_wage_income
                                            optimal_cutoff_taxable_income_owner_owner_move=cutoff_taxable_income
                                            optimal_wage_income_tax_paid_owner_owner_move=wage_income_tax_paid
                                            optimal_space_lived_in_owner_owner_move=space_lived_in_index_feasible
                                            optimal_mortgage_deductions_owner_owner_move=mortgage_deductions_tax_rebates
                                            optimal_household_can_consume_owner_owner_move=1
                                            optimal_labor_supply_owner_owner_move=labor_supply_1
                                            optimal_frac_spent_on_addiction_owner_owner_move=frac_spent_on_addiction
                                            optimal_total_consumption_owner_owner_move=total_consumption_choice
                                            optimal_addiction_status_owner_owner_move=future_addiction_index
                                                                                                                                              
                                        end if
                                                                                    
                                    end if
                                    
                                end if
                                                                                                
                            end if
                            
                        end do
                               
                    end do
                    
                    end do
                    
                end if
                                            
            end do
            
        end do
            
        value_function_owner_owner_move=largest_value
                                                                
    end subroutine
    
    subroutine owner_renter_problem(time_period,financial_index)
    
        use Global_Vars
        
        implicit none
            
        integer, intent(in) :: time_period,financial_index
        integer :: tenure_1,tenure_2,proceed_2,future_housing_status_index_to_use,voucher_index_1,&
            is_working_1,is_homeless_1,x_1,addiction_index,global_search_index,optimal_financial_1,can_consume_drugs,&
            loop_over_addiction_1,check_1,allow_to_choose_addiction,first_voucher_index,second_voucher_index,has_opportunity_1,&
            allow_to_choose_homelessness
        real(8) :: labor_supply_1,labor_supply_2 
                
        allow_to_choose_homelessness=1
        
        if (age_index>max_age_to_choose_homelessness) then
        
            allow_to_choose_homelessness=0
            
        end if
                        
        allow_to_choose_addiction=1
            
        if (age_index>max_age_to_choose_addiction) then
        
            allow_to_choose_addiction=0
                         
        end if
        
        addiction_index=0
        
        if (unemployment_index>threshold_addiction_index) then
        
            addiction_index=1
            
        end if
                
        tenure_1=1
        tenure_2=0
        proceed_2=1
        
        labor_supply_2=1
                
        is_working_1=1
        
        if ((in_retirement==1) .OR. &
            (emp_of(unemployment_index)>1)) then
        
            is_working_1=0
            
        end if
        
        largest_value=large_negative_num
                        
        optimal_owner_renter_indeces(1)=negative_financial_grid_size
        optimal_financial_1=negative_financial_grid_size
        optimal_owner_renter_indeces(2)=1
        optimal_owner_renter_indeces(3)=0
                                    
        optimal_consumption_owner_renter=0
        optimal_gross_wage_income_owner_renter=0
        optimal_cutoff_taxable_income_owner_renter=0
        optimal_wage_income_tax_paid_owner_renter=0
        optimal_after_tax_wealth_net_of_expenses_owner_renter=0
        optimal_after_tax_wealth_owner_renter=0
        optimal_space_lived_in_owner_renter=0
        optimal_mortgage_deductions_owner_renter=0
        optimal_household_can_consume_owner_renter=0
        optimal_labor_supply_owner_renter=((1-is_working_1)*0+is_working_1*1)
        labor_supply_1=optimal_labor_supply_owner_renter
        optimal_frac_spent_on_addiction_owner_renter=0
        optimal_total_consumption_owner_renter=0
        optimal_addiction_status_owner_renter=0
        
        if (fixed_labor_supply_at_benchmark==1) then
                    
            labor_supply_2=&
                policy_function_labor_supply(years_left_on_mortgage_index)%&
                vector_transition_real(time_period,age_index,financial_index,unemployment_index,&
                employment_index,housing_status_index,voucher_index)
                
            labor_supply_1=labor_supply_2
                
        end if
                        
        do future_addiction_index=addiction_index,&
            (1-allow_to_choose_addiction)*addiction_index+allow_to_choose_addiction*&
            (include_addiction+(1-addiction_index)*include_heavy_vs_light_use_transitions)
        
            loop_over_addiction_1=0
            
            if (addiction_index==1) then
            
                loop_over_addiction_1=1
                
            elseif ((future_addiction_index>=1) .AND. &
                (include_probability_of_becoming_addicted==1)) then
            
                loop_over_addiction_1=1
        
            end if
                
            do future_housing_status_index=&
                allow_to_choose_homelessness*lowest_housing_grid_point,largest_house_size_hhld_can_rent
                
                if (track_renters_housing==0) then
                
                    if (future_housing_status_index<=second_lowest_housing_grid_point) then
            
                        future_housing_status_index_to_use=future_housing_status_index
                        
                    else
                        
                        future_housing_status_index_to_use=0
                        
                    end if
                    
                else
                
                    future_housing_status_index_to_use=future_housing_status_index
                
                end if
                
                is_homeless_1=1
                
                if (future_housing_status_index_to_use==lowest_housing_grid_point) then
                
                    is_homeless_1=2
            
                end if
                
                call compute_voucher_index_1(is_homeless_1,voucher_index_1)
                
                do global_search_index=0,coarse_grid
                            
                do future_financial_index=&
                    (1-global_search_index)*negative_financial_grid_size+&
                    global_search_index*max(optimal_financial_1-grid_gaps+1,negative_financial_grid_size),&
                    (1-global_search_index)*financial_grid_size+&
                    global_search_index*min(optimal_financial_1+grid_gaps-1,financial_grid_size),&
                    (1-global_search_index)*grid_gaps+global_search_index
                
                    ! Skip the asset points no state chose last time. Off by
                    ! default, and never applied on the first solve, when there is
                    ! no previous policy to learn the set from.
                    if ((restrict_a_prime==1) .AND. (a_prime_set_ready==1)) then
                    
                        if (.NOT. a_prime_allowed(future_financial_index)) cycle
                        
                    end if
                
                    if ((in_retirement==0) .AND. (fixed_labor_supply_at_benchmark==0)) then
                                    
                        labor_supply_2=1
                                          
                    end if
                            
                    call calculate_after_tax_wealth&
                        (financial_index,future_financial_index,years_left_on_mortgage_index,0,&
                        housing_status_index,future_housing_status_index,tenure_2,tenure_1,tenure_2,&
                        tenure_2,tenure_2,time_period,labor_supply_2,cutoff_taxable_income,future_addiction_index)
                        ! owner_to_owner_move_1,owner_to_renter_1,renter_to_owner_1,owner_to_owner_stay_1,renter_to_renter_1
                      
                    if (labor_supply_2>0.4) then
                    if ((in_retirement==0) .AND. (fixed_labor_supply_at_benchmark==0) .AND. &
                        ((emp_of(unemployment_index)==1))) then
                    
                        x_1=1
                
                        call secant(time_period,financial_index,financial_grid(future_financial_index),&
                            housing_size(future_housing_status_index),future_housing_status_index,&
                            x_1,after_tax_wealth_net_of_expenses,labor_supply_1,gross_wage_income,&
                            wage_income_tax_paid,food_stamps_recieved,housing_voucher_recieved,&
                            housing_voucher_recieved_2,mortgage_deductions_tax_rebates,proceed_2,&
                            future_addiction_index)
                                                                                    
                    end if
                    end if
                    
                    call calculate_future_voucher_index_and_opportunity&
                        (has_opportunity_1,first_voucher_index,second_voucher_index,&
                        time_period,1,0,voucher_index_1,gross_wage_income+investment_income)
                    
                    if (-financial_grid(financial_index)>(1-minimum_downpayment)) then
                                                    
                        pay_mortgage_insurance=1
                            
                    else
                                    
                        pay_mortgage_insurance=0
                                        
                    end if
                    
                    can_consume_drugs=1
                                                                                    
                    if ((consumption_choice>=(food_stamps_recieved/(1+consumption_tax))) .AND. &
                        (consumption_choice>0) .AND. (frac_spent_on_addiction>=0) .AND. &
                        (total_consumption_choice>=consumption_choice) .AND. (proceed_2==1) .AND. &
                        (can_consume_drugs==1)) then
                        
                        if (abs(consumption_choice-total_consumption_choice*(1-frac_spent_on_addiction))>10.d0**(-8)) then
            
                            write(*,*) "wrong_2"
                            write(*,*) "consumption_choice=", consumption_choice
                            write(*,*) "total_consumption_choice=", total_consumption_choice
                            write(*,*) "frac_spent_on_addiction=", frac_spent_on_addiction
                        
                        end if
                                                                            
                        future_leisure_vector(future_financial_index)=relative_share_of_leisure*&
                            ((max_labor_supply-labor_supply_1)**(1-leisure_curvature))/(1-leisure_curvature)
                                                
                        call calculate_flow_utility(0,future_housing_status_index,&
                            housing_size(future_housing_status_index),frac_spent_on_addiction,&
                            total_consumption_choice,consumption_choice,0,future_addiction_index,&
                            flow_utility_vector(future_financial_index),0)
                            
                        flow_utility_vector(future_financial_index)=&
                            flow_utility_vector(future_financial_index)+&
                            future_leisure_vector(future_financial_index)
                                                                                                                                                                 
                        future_utility_vector=0
                        future_bequest_vector=0
                        
                        if (include_bequest_motive==1) then
                               
                            if ((age_index==life_span) .OR. (have_probablistic_death==1)) then
                                                        
                                call calculate_bequest_utility(financial_grid(future_financial_index),&
                                    future_bequest_vector(future_financial_index),is_homeless_1,addiction_index)
                                                        
                                future_utility_vector(future_financial_index)=&
                                    future_utility_vector(future_financial_index)+&
                                    future_bequest_vector(future_financial_index)
                                                                                                                        
                            end if
                            
                        end if
                        
                        do future_addiction_index_2=&
                            (1-loop_over_addiction_1)*future_addiction_index+loop_over_addiction_1*0,&
                            (1-loop_over_addiction_1)*future_addiction_index+loop_over_addiction_1*include_addiction
                        
                            check_1=0
                            
                            if (future_addiction_index_2==1) then
                            
                                check_1=1
                                
                            end if
                                            
                            do future_unemployment_index=include_addiction*&
                                ((1-check_1)*1+check_1*(threshold_addiction_index+1))+&
                                (1-include_addiction)*(at_least_one_period_before_retirement*&
                                (one_period_before_death*1+(1-one_period_before_death)*unemployment_index)+&
                                (1-at_least_one_period_before_retirement)*1),include_addiction*&
                                ((1-check_1)*threshold_addiction_index+check_1*unemployment_grid_size)+&
                                (1-include_addiction)*(at_least_one_period_before_retirement*&
                                (one_period_before_death*unemployment_grid_size+(1-one_period_before_death)*unemployment_index)+&
                                (1-at_least_one_period_before_retirement)*unemployment_grid_size)
                                                                            
                                do future_employment_index=&
                                    at_least_one_period_before_retirement*employment_index+&
                                    (1-at_least_one_period_before_retirement)*1,&
                                    at_least_one_period_before_retirement*employment_index+&
                                    (1-at_least_one_period_before_retirement)*employment_grid_size

                                    ! FIXED PRODUCTIVITY, and a free win even without it. When the productivity
                                    ! transition is the identity, eight of the nine branches carry zero mass and
                                    ! the innermost nest is nine times larger than it needs to be. Skipping them
                                    ! is exact, not an approximation, and it also prunes the near zero tails of
                                    ! the Tauchen matrix when productivity is stochastic.
                                    if (employment_process(age_index,employment_index,future_employment_index)<=0.d0) cycle

                                    
                                    do future_voucher_index=first_voucher_index,second_voucher_index
                                                                                                                                                                                                   
                                        future_utility_vector(future_financial_index)=&
                                            future_utility_vector(future_financial_index)+&
                                            discount_factor*survival_probability(age_index,is_homeless_1,survival_sud_of(addiction_index,treatment_choice_now),smi_of(unemployment_index))*&
                                            voucher_probabilities(voucher_index,future_voucher_index,&
                                            has_opportunity_1,voucher_index_1)*&
                                            employment_process(age_index,employment_index,future_employment_index)*&
                                            unemployment_process(age_index,unemployment_index,&
                                            future_unemployment_index,is_homeless_1,future_addiction_index_2,employment_index)*&
                                            addiction_transition(addiction_index,future_addiction_index_2,&
                                            future_addiction_index,is_homeless_1,&
                                            frac_spent_on_addiction*total_consumption_choice/&
                                            price_of_addictive_good,1,treatment_choice_now)*&
                                            value_function(1)%vector_transition_real&
                                            (min(time_period+solve_transition_dynamics,transition_length),&
                                            age_index+1,future_financial_index,future_unemployment_index,&
                                            future_employment_index,future_housing_status_index_to_use,future_voucher_index)
                                            
                                    end do
                                                                                                                                                                                                                                                                                                                  
                                end do
                                
                            end do
                            
                        end do
                                                             
                        value_function_owner_renter=&
                            flow_utility_vector(future_financial_index)+&
                            future_utility_vector(future_financial_index)
                                                                                                                   
                        if (value_function_owner_renter>largest_value) then
                                                                
                            went_in_1=1
                            largest_value=value_function_owner_renter
                                                                 
                            optimal_owner_renter_indeces(1)=future_financial_index
                            optimal_owner_renter_indeces(2)=1
                            optimal_owner_renter_indeces(3)=future_housing_status_index
                            
                            if (global_search_index==0) then
                            
                                optimal_financial_1=future_financial_index
                                
                            end if
            
                            optimal_consumption_owner_renter=consumption_choice
                            
                            if (consumption_choice<food_stamps_recieved/(1+consumption_tax)) then
                            
                                write(*,*) "not good 7777"
                                write(*,*) "consumption_choice=", consumption_choice
                            
                            end if
                            
                            if (consumption_choice<=0) then
                            
                                write(*,*) "owner renter eror"
                                
                            end if
                            
                            optimal_after_tax_wealth_net_of_expenses_owner_renter=after_tax_wealth_net_of_expenses
                                
                            optimal_gross_wage_income_owner_renter=gross_wage_income
                            optimal_cutoff_taxable_income_owner_renter=cutoff_taxable_income
                            optimal_wage_income_tax_paid_owner_renter=wage_income_tax_paid
                            optimal_space_lived_in_owner_renter=future_housing_status_index
                            optimal_mortgage_deductions_owner_renter=mortgage_deductions_tax_rebates
                            optimal_household_can_consume_owner_renter=1
                            optimal_labor_supply_owner_renter=labor_supply_1
                            optimal_frac_spent_on_addiction_owner_renter=frac_spent_on_addiction
                            optimal_total_consumption_owner_renter=total_consumption_choice 
                            optimal_addiction_status_owner_renter=future_addiction_index
                            
                        end if
                                                                        
                    end if
                    
                end do
                                                                     
                end do
            
            end do 
            
        end do
                
        value_function_owner_renter=largest_value
                            
    end subroutine
    
    subroutine calculate_flow_utility(internal_computation_1,future_housing_status_index_1,&
        space_lived_in_internal_1,frac_spent_on_addiction_1,total_consumption_choice_1,&
        consumption_choice_1,ownership_status_index_1,addicted_status_1,flow_utility_1,is_benchmark)
    
        use Global_Vars
        
        implicit none
        
        integer, intent(in) :: internal_computation_1,future_housing_status_index_1,&
            ownership_status_index_1,addicted_status_1,is_benchmark
        
        real(8), intent(in) :: space_lived_in_internal_1,frac_spent_on_addiction_1,&
            total_consumption_choice_1,consumption_choice_1
            
        real(8) :: price_of_addictive_good_to_use

        ! CONSUMPTION AS THE UTILITY FUNCTION SEES IT, which is not what the
        ! household paid for when it is on the street. See the declaration of
        ! consumption_penalty_homeless. total_consumption_choice_1 is deliberately
        ! NOT scaled: the penalty is on non-housing consumption, and the addictive
        ! good is priced separately.
        real(8) :: c_util_1
            
        real(8), intent(inout) :: flow_utility_1
        
        if (is_benchmark==1) then
        
            price_of_addictive_good_to_use=price_of_addictive_good_benchmark
            
        else
        
            price_of_addictive_good_to_use=price_of_addictive_good
        
        end if
        
        c_util_1=consumption_choice_1
        
        if (future_housing_status_index_1==lowest_housing_grid_point) then
        
            c_util_1=consumption_choice_1*(1.d0-consumption_penalty_homeless)
            
        end if
        
        if (internal_computation_1==0) then
        
            if (use_cobb_douglas==1) then
        
                if (addicted_status_1==1) then
                
                    flow_utility_1=scaled_household_size(age_index)*&
                        ((1-relative_share_of_addiction)*&
                        (housing_status_utility_function(future_housing_status_index_1,&
                        age_index,ownership_status_index_1,addicted_status_1)*&
                        (c_util_1**((1-risk_aversion_consumption)*&
                        (1-relative_share_of_housing))))/(1-risk_aversion_consumption)+&
                        relative_share_of_addiction*((frac_spent_on_addiction_1*total_consumption_choice_1/&
                        price_of_addictive_good_to_use)**(1-risk_aversion_consumption))/(1-risk_aversion_consumption))
                
                else
                    
                    flow_utility_1=scaled_household_size(age_index)*&
                        ((housing_status_utility_function(future_housing_status_index_1,&
                        age_index,ownership_status_index_1,addicted_status_1)*&
                        (c_util_1**((1-risk_aversion_consumption)*&
                        (1-relative_share_of_housing))))/(1-risk_aversion_consumption))
                        
                end if
                
            elseif (use_cobb_douglas_2==1) then
            
                flow_utility_1=scaled_household_size(age_index)*&
                    ((housing_status_utility_function(future_housing_status_index_1,&
                    age_index,ownership_status_index_1,addicted_status_1)*&
                    c_util_1**((1-risk_aversion_consumption)*relative_share_of_consumption_2)*&
                    (b_shifter(0,housing_size(future_housing_status_index_1))+(frac_spent_on_addiction_1*total_consumption_choice_1)/price_of_addictive_good_to_use)**&
                    ((1-risk_aversion_consumption)*relative_share_of_addiction)))/(1-risk_aversion_consumption)
            
            elseif (include_probability_of_becoming_addicted==1) then
            
                if (unemployment_index>threshold_addiction_index) then
                        
                    flow_utility_1=scaled_household_size(age_index)*&
                        ((housing_status_utility_function(future_housing_status_index_1,age_index,ownership_status_index_1,1)*&
                        c_util_1**((1-risk_aversion_consumption)*relative_share_of_consumption_2)*&
                        ((b_shifter(1,housing_size(future_housing_status_index_1))+(frac_spent_on_addiction_1*total_consumption_choice_1)/&
                        price_of_addictive_good_to_use))**&
                        ((1-risk_aversion_consumption)*relative_share_of_addiction_2)))/(1-risk_aversion_consumption)
                        
                else
                
                    flow_utility_1=scaled_household_size(age_index)*&
                        ((housing_status_utility_function(future_housing_status_index_1,age_index,ownership_status_index_1,0)*&
                        c_util_1**((1-risk_aversion_consumption)*relative_share_of_consumption_1)*&
                        ((b_shifter(0,housing_size(future_housing_status_index_1))+(frac_spent_on_addiction_1*total_consumption_choice_1)/&
                        price_of_addictive_good_to_use))**&
                        ((1-risk_aversion_consumption)*relative_share_of_addiction_1)))/(1-risk_aversion_consumption)
                
                end if
                
            else
            
                if (addicted_status_1==1) then
                
                    flow_utility_1=(1-utility_improvement)*sqrt_household_size(age_index)*&
                        ((housing_status_utility_function(future_housing_status_index_1,&
                        age_index,ownership_status_index_1,addicted_status_1)+&
                        relative_share_of_consumption_2*(c_util_1/&
                        sqrt_household_size(age_index))**(power_1)+relative_share_of_addiction*&
                        (((frac_spent_on_addiction_1*total_consumption_choice_1)/price_of_addictive_good_to_use)/&
                        sqrt_household_size(age_index))**(power_3))**(power_2))/(1-risk_aversion_consumption)
                
                else
                    
                    flow_utility_1=sqrt_household_size(age_index)*&
                        ((housing_status_utility_function(future_housing_status_index_1,&
                        age_index,ownership_status_index_1,addicted_status_1)+(1-relative_share_of_housing)*&
                        (c_util_1/sqrt_household_size(age_index))**(power_1))**&
                        (power_2))/(1-risk_aversion_consumption)
                        
                end if
            
            end if
                    
        else
        
            if (use_cobb_douglas==1) then
            
                if (addicted_status_1==1) then
                
                    flow_utility_1=scaled_household_size(age_index)*&
                        ((1-relative_share_of_addiction)*&
                        ((space_lived_in_internal_1*(1+ownership_status_index_1*advantage_to_owning))**&
                        ((1-risk_aversion_consumption)*relative_share_of_housing)*&
                        (c_util_1)**((1-risk_aversion_consumption)*&
                        ((1-relative_share_of_housing))))/(1-risk_aversion_consumption)+&
                        relative_share_of_addiction*((frac_spent_on_addiction_1*total_consumption_choice_1)**&
                        (1-risk_aversion_consumption))/(1-risk_aversion_consumption))
                    
                else
                
                    flow_utility_1=scaled_household_size(age_index)*&
                        ((space_lived_in_internal_1*(1+ownership_status_index_1*advantage_to_owning))**&
                        ((1-risk_aversion_consumption)*relative_share_of_housing)*&
                        (total_consumption_choice_1)**((1-risk_aversion_consumption)*&
                        (1-relative_share_of_housing)))/(1-risk_aversion_consumption)
                        
                end if   
                
            elseif (use_cobb_douglas_2==1) then
                        
                flow_utility_1=scaled_household_size(age_index)*&
                    ((space_lived_in_internal_1*(1+ownership_status_index_1*advantage_to_owning))**&
                    ((1-risk_aversion_consumption)*relative_share_of_housing)*&
                    c_util_1**((1-risk_aversion_consumption)*relative_share_of_consumption_2)*&
                    (b_shifter(0,housing_size(future_housing_status_index_1))+(frac_spent_on_addiction_1*total_consumption_choice_1)/price_of_addictive_good_to_use)**&
                    ((1-risk_aversion_consumption)*relative_share_of_addiction))/(1-risk_aversion_consumption)
                    
            elseif (include_probability_of_becoming_addicted==1) then
            
                if (unemployment_index>threshold_addiction_index) then
                
                    flow_utility_1=scaled_household_size(age_index)*&
                        ((space_lived_in_internal_1*(1+ownership_status_index_1*advantage_to_owning))**&
                        ((1-risk_aversion_consumption)*relative_share_of_housing_2)*&
                        c_util_1**((1-risk_aversion_consumption)*relative_share_of_consumption_2)*&
                        ((b_shifter(1,housing_size(future_housing_status_index_1))+(frac_spent_on_addiction_1*total_consumption_choice_1)/&
                        price_of_addictive_good_to_use))**&
                        ((1-risk_aversion_consumption)*relative_share_of_addiction_2))/(1-risk_aversion_consumption)
                
                else
                
                    flow_utility_1=scaled_household_size(age_index)*&
                        ((space_lived_in_internal_1*(1+ownership_status_index_1*advantage_to_owning))**&
                        ((1-risk_aversion_consumption)*relative_share_of_housing_1)*&
                        c_util_1**((1-risk_aversion_consumption)*relative_share_of_consumption_1)*&
                        ((b_shifter(0,housing_size(future_housing_status_index_1))+(frac_spent_on_addiction_1*total_consumption_choice_1)/&
                        price_of_addictive_good_to_use))**&
                        ((1-risk_aversion_consumption)*relative_share_of_addiction_1))/(1-risk_aversion_consumption)
                
                end if
                    
            else
            
                if (addicted_status_1==1) then
                
                    flow_utility_1=(1-utility_improvement)*sqrt_household_size(age_index)*&
                        ((relative_share_of_housing_2*((space_lived_in_internal_1*&
                        (1+ownership_status_index_1*advantage_to_owning))/&
                        sqrt_household_size(age_index))**(power_1)+&
                        relative_share_of_consumption_2*(c_util_1/&
                        sqrt_household_size(age_index))**(power_1)+relative_share_of_addiction*&
                        (((frac_spent_on_addiction_1*total_consumption_choice_1)/price_of_addictive_good_to_use)/&
                        sqrt_household_size(age_index))**(power_3))**(power_2))/(1-risk_aversion_consumption)
                                        
                else
            
                    flow_utility_1=sqrt_household_size(age_index)*&
                        ((relative_share_of_housing*((space_lived_in_internal_1*&
                        (1+ownership_status_index_1*advantage_to_owning))/sqrt_household_size(age_index))**(power_1)+&
                        (1-relative_share_of_housing)*(total_consumption_choice_1/sqrt_household_size(age_index))**&
                        (power_1))**(power_2))/(1-risk_aversion_consumption)
                        
                end if
                    
            end if
            
        end if   
        
        ! Recorded before anything additive is appended, because the drug first
        ! order condition needs the aggregate and not the level. See the
        ! declaration of flow_utility_goods_only.
        flow_utility_goods_only=flow_utility_1

        ! The value of life is charged whether or not the household uses: the
        ! two arms of the test this replaces were character for character the
        ! same, which is what a condition means once it no longer conditions on
        ! anything.
        flow_utility_1=flow_utility_1+value_of_life
        
        ! bar_tau^u, charged wherever flow utility is evaluated so that the
        ! value function, the comparison routine and the welfare calculations
        ! cannot disagree about what treatment costs.
        ! Treatment's cost is monetary and is charged in
        ! calculate_addiction_spending, on resources. utility_cost_of_treatment
        ! is held at zero and this subtraction is kept so that a robustness run
        ! can put a utility cost back beside the price in one place.
        if ((include_treatment==1) .AND. (treatment_choice_now==1)) then

            flow_utility_1=flow_utility_1-utility_cost_of_treatment

        end if

    end subroutine
    
    subroutine calculate_bequest_utility(wealth_1,bequest_1,is_homeless_1,is_addicted_1)
    
        use Global_Vars
        
        implicit none
        
        real(8), intent(in) :: wealth_1
        real(8), intent(inout) :: bequest_1
        integer, intent(in) :: is_homeless_1,is_addicted_1
                        
        if (minimum_inheritance>0) then
                
            bequest_1=(1-survival_probability(age_index,is_homeless_1,survival_sud_of(is_addicted_1,treatment_choice_now),smi_of(unemployment_index)))*&
                discount_factor_on_child*((minimum_inheritance+wealth_1)**(1-risk_aversion_consumption))/&
                (1-risk_aversion_consumption)
                
        else
        
            if (wealth_1>0) then
            
                bequest_1=((1-survival_probability(age_index,is_homeless_1,survival_sud_of(is_addicted_1,treatment_choice_now),smi_of(unemployment_index)))*&
                    discount_factor_on_child*(wealth_1)**(1-risk_aversion_consumption))/(1-risk_aversion_consumption)
            
            else
        
                bequest_1=large_negative_num
                
            end if
            
        end if  
        
    end subroutine
    
    subroutine calculate_marginal_non_housing_utility(consumption_1,housing_1,addiction_choice_2,addiction_1,MU_1)
    
        use Global_Vars
        
        implicit none
    
        real(8), intent(in) :: consumption_1,housing_1,addiction_1
        real(8), intent(out) :: MU_1
        real(8) :: first_part,second_part
        integer, intent(in) :: addiction_choice_2
        
        if (use_cobb_douglas==1) then
                    
            first_part=(1-relative_share_of_addiction)*scaled_household_size(age_index)*&
                (((housing_1)**(relative_share_of_housing))*((consumption_1)**(1-relative_share_of_housing)))**&
                (-risk_aversion_consumption)
                
            second_part=(1-relative_share_of_housing)*(consumption_1)**(-relative_share_of_housing)*&
                ((housing_1)**(relative_share_of_housing))
                
        elseif (use_cobb_douglas_2==1) then
        
            first_part=scaled_household_size(age_index)*&
                ((housing_1**relative_share_of_housing)*&
                (consumption_1**relative_share_of_consumption_2)*&
                (b_shifter(0,housing_1)+(addiction_1/price_of_addictive_good))**relative_share_of_addiction)**&
                (-risk_aversion_consumption)
                
            second_part=relative_share_of_consumption_2*(consumption_1)**(relative_share_of_consumption_2-1)*&
                ((housing_1**relative_share_of_housing)*&
                (b_shifter(0,housing_1)+(addiction_1/price_of_addictive_good))**relative_share_of_addiction)   
                
        elseif (include_probability_of_becoming_addicted==1) then
        
            if (unemployment_index>threshold_addiction_index) then
        
                first_part=scaled_household_size(age_index)*&
                    ((housing_1**relative_share_of_housing_2)*&
                    (consumption_1**relative_share_of_consumption_2)*&
                    ((b_shifter(1,housing_1)+(addiction_1/price_of_addictive_good))**relative_share_of_addiction_2))**&
                    (-risk_aversion_consumption)
                    
                second_part=relative_share_of_consumption_2*(consumption_1)**(relative_share_of_consumption_2-1)*&
                    (housing_1**relative_share_of_housing_2)*&
                    ((b_shifter(1,housing_1)+(addiction_1/price_of_addictive_good))**relative_share_of_addiction_2)
                    
            else
            
                first_part=scaled_household_size(age_index)*&
                    ((housing_1**relative_share_of_housing_1)*&
                    (consumption_1**relative_share_of_consumption_1)*&
                    ((b_shifter(0,housing_1)+(addiction_1/price_of_addictive_good))**relative_share_of_addiction_1))**&
                    (-risk_aversion_consumption)
                    
                second_part=relative_share_of_consumption_1*(consumption_1)**(relative_share_of_consumption_1-1)*&
                    (housing_1**relative_share_of_housing_1)*&
                    ((b_shifter(0,housing_1)+(addiction_1/price_of_addictive_good))**relative_share_of_addiction_1)
            
            end if
                                                            
        else
        
            if (addiction_choice_2>0) then
            
                first_part=(1-utility_improvement)*&
                    ((relative_share_of_housing_2*(housing_1/sqrt_household_size(age_index))**(power_1)+&
                    relative_share_of_consumption_2*(consumption_1/sqrt_household_size(age_index))**(power_1)+&
                    relative_share_of_addiction*((addiction_1/price_of_addictive_good)/sqrt_household_size(age_index))**&
                    (power_3))**(power_2-1))
                    
                second_part=relative_share_of_consumption_2*(consumption_1/sqrt_household_size(age_index))**(power_1-1)
                    
            else
            
                first_part=(relative_share_of_housing*(housing_1/sqrt_household_size(age_index))**(power_1)+&
                    (1-relative_share_of_housing)*(consumption_1/sqrt_household_size(age_index))**(power_1))**&
                    (power_2-1)
                    
                second_part=(1-relative_share_of_housing)*(consumption_1/sqrt_household_size(age_index))**(power_1)
                        
            end if 
                                    
        end if
        
        MU_1=first_part*second_part
        
    end subroutine
    
    subroutine which_is_better(time_period,financial_index)
    
        use Global_Vars
        
        implicit none
        
        integer, intent(in) :: time_period,financial_index
        integer :: is_owner_better
        
        is_owner_better=0
        
        if ((value_function_owner>value_function_renter) .AND. (include_ownership==1)) then
        
            is_owner_better=1
            
        end if
                                                                                                
        value_function(years_left_on_mortgage_index)%&
            vector_transition_real(time_period,age_index,financial_index,&
            unemployment_index,employment_index,housing_status_index,voucher_index)=&
            is_owner_better*value_function_owner+(1-is_owner_better)*value_function_renter
                                                
        optimal_after_tax_wealth_net_of_expenses=&
            is_owner_better*optimal_after_tax_wealth_net_of_expenses_owner+&
            (1-is_owner_better)*optimal_after_tax_wealth_net_of_expenses_renter
                        
        policy_function_financial_index(years_left_on_mortgage_index)%&
            vector_transition_integer(time_period,age_index,financial_index,&
            unemployment_index,employment_index,housing_status_index,voucher_index)=&
            is_owner_better*optimal_owner_indeces(1)+(1-is_owner_better)*optimal_renter_indeces(1)
            
        policy_function_years_of_amortization_index(years_left_on_mortgage_index)%&
            vector_transition_integer(time_period,age_index,financial_index,&
            unemployment_index,employment_index,housing_status_index,voucher_index)=&
            is_owner_better*optimal_owner_indeces(2)+(1-is_owner_better)*optimal_renter_indeces(2)
                                        
        policy_function_housing_status_index(years_left_on_mortgage_index)%&
            vector_transition_integer(time_period,age_index,financial_index,&
            unemployment_index,employment_index,housing_status_index,voucher_index)=&
            is_owner_better*optimal_owner_indeces(3)+(1-is_owner_better)*optimal_renter_indeces(3)
                                
        policy_function_consumption(years_left_on_mortgage_index)%&
            vector_transition_real(time_period,age_index,financial_index,&
            unemployment_index,employment_index,housing_status_index,voucher_index)=&
            is_owner_better*optimal_consumption_owner+(1-is_owner_better)*optimal_consumption_renter
                    
        policy_function_space_lived_in_index(years_left_on_mortgage_index)%&
            vector_transition_integer(time_period,age_index,financial_index,&
            unemployment_index,employment_index,housing_status_index,voucher_index)=&
            is_owner_better*optimal_space_lived_in_owner+(1-is_owner_better)*optimal_space_lived_in_renter
                    
        policy_function_space_lived_in_size(years_left_on_mortgage_index)%&
            vector_transition_real(time_period,age_index,financial_index,&
            unemployment_index,employment_index,housing_status_index,voucher_index)=&
            is_owner_better*housing_size(optimal_space_lived_in_owner)+&
            (1-is_owner_better)*housing_size(optimal_space_lived_in_renter)
                                    
        policy_function_wage_income_tax_paid(years_left_on_mortgage_index)%&
            vector_transition_real(time_period,age_index,financial_index,&
            unemployment_index,employment_index,housing_status_index,voucher_index)=&
            is_owner_better*optimal_wage_income_tax_paid_owner+&
            (1-is_owner_better)*optimal_wage_income_tax_paid_renter
            
        policy_function_mortgage_interest_deductions(years_left_on_mortgage_index)%&
            vector_transition_real(time_period,age_index,financial_index,&
            unemployment_index,employment_index,housing_status_index,voucher_index)=&
            is_owner_better*optimal_mortgage_deductions_owner+&
            (1-is_owner_better)*optimal_mortgage_deductions_renter
            
        if ((adjust_labor_supply==0) .AND. (is_counterfactual==1)) then
        
        else
                                     
            policy_function_labor_supply(years_left_on_mortgage_index)%&
                vector_transition_real(time_period,age_index,financial_index,&
                unemployment_index,employment_index,housing_status_index,voucher_index)=&
                is_owner_better*optimal_labor_supply_owner+&
                (1-is_owner_better)*optimal_labor_supply_renter
                
        end if

        policy_function_cutoff_taxable_income(years_left_on_mortgage_index)%&
            vector_transition_real(time_period,age_index,financial_index,&
            unemployment_index,employment_index,housing_status_index,voucher_index)=&
            is_owner_better*optimal_cutoff_taxable_income_owner+&
            (1-is_owner_better)*optimal_cutoff_taxable_income_renter
            
        policy_function_frac_spent_on_addiction(years_left_on_mortgage_index)%&
            vector_transition_real(time_period,age_index,financial_index,&
            unemployment_index,employment_index,housing_status_index,voucher_index)=&
            (is_owner_better*optimal_frac_spent_on_addiction_owner+&
            (1-is_owner_better)*optimal_frac_spent_on_addiction_renter)
                    
        policy_function_total_consumption(years_left_on_mortgage_index)%&
            vector_transition_real(time_period,age_index,financial_index,&
            unemployment_index,employment_index,housing_status_index,voucher_index)=&
            is_owner_better*optimal_total_consumption_owner+&
            (1-is_owner_better)*optimal_total_consumption_renter
            
        if (unemployment_index<=threshold_addiction_index) then
        
            if (policy_function_total_consumption(years_left_on_mortgage_index)%&
                vector_transition_real(time_period,age_index,financial_index,&
                unemployment_index,employment_index,housing_status_index,voucher_index)>&
                policy_function_consumption(years_left_on_mortgage_index)%&
                vector_transition_real(time_period,age_index,financial_index,&
                unemployment_index,employment_index,housing_status_index,voucher_index)) then
                            
                policy_function_addiction(years_left_on_mortgage_index)%&
                    vector_transition_integer(time_period,age_index,financial_index,&
                    unemployment_index,employment_index,housing_status_index,voucher_index)=&
                    is_owner_better*optimal_addiction_status_owner+&
                    (1-is_owner_better)*optimal_addiction_status_renter

                policy_function_treatment(years_left_on_mortgage_index)%&
                    vector_transition_integer(time_period,age_index,financial_index,&
                    unemployment_index,employment_index,housing_status_index,voucher_index)=&
                    (1-is_owner_better)*optimal_treatment_renter
                    
                if ((unemployment_index>threshold_addiction_index) .AND. &
                    (policy_function_addiction(years_left_on_mortgage_index)%&
                    vector_transition_integer(time_period,age_index,financial_index,&
                    unemployment_index,employment_index,housing_status_index,voucher_index)==0)) then
                    
                    write(*,*) "error"
                    
                end if
                
            else
            
                policy_function_addiction(years_left_on_mortgage_index)%&
                    vector_transition_integer(time_period,age_index,financial_index,&
                    unemployment_index,employment_index,housing_status_index,voucher_index)=0

                policy_function_treatment(years_left_on_mortgage_index)%&
                    vector_transition_integer(time_period,age_index,financial_index,&
                    unemployment_index,employment_index,housing_status_index,voucher_index)=0
            
            end if
                
        else
        
            policy_function_addiction(years_left_on_mortgage_index)%&
                vector_transition_integer(time_period,age_index,financial_index,&
                unemployment_index,employment_index,housing_status_index,voucher_index)=1

            policy_function_treatment(years_left_on_mortgage_index)%&
                vector_transition_integer(time_period,age_index,financial_index,&
                unemployment_index,employment_index,housing_status_index,voucher_index)=&
                optimal_treatment_renter
        
        end if
                                                                                                         
    end subroutine
    
    subroutine secant(time_period,financial_index_1,future_financial_amount_1,space_lived_in_1,&
        future_housing_status_index_1,years_left_on_mortgage_1,after_tax_wealth_net_of_expenses_2,&
        labor_supply_1,gross_wage_income_2,wage_income_tax_paid_2,food_stamps_2,housing_voucher_2,&
        housing_voucher_4,mortgage_deductions_tax_rebates_2,proceed_2,addiction_index_1)
    
        use Global_Vars
    
        implicit none
        
        real(8) :: MU_1,MU_2,x_0,x_1,x_2
        real(8) :: stopping_rule_secant=10.d0**(-8)
        real(8) :: distance_secant
        real(8), intent(inout) :: labor_supply_1,after_tax_wealth_net_of_expenses_2,gross_wage_income_2,&
            wage_income_tax_paid_2,food_stamps_2,housing_voucher_2,mortgage_deductions_tax_rebates_2,housing_voucher_4
        real(8), intent(in) :: future_financial_amount_1,space_lived_in_1
        integer, intent(in) :: financial_index_1,future_housing_status_index_1,addiction_index_1
        integer, intent(inout) :: proceed_2,years_left_on_mortgage_1
        integer, intent(in) :: time_period
        integer :: loop_1,can_consume_1,max_loop_count
        real(8) :: after_tax_wealth_net_of_expenses_1,gross_wage_income_1,wage_income_tax_paid_1,&
            food_stamps_1,housing_voucher_1,housing_voucher_3,mortgage_deductions_tax_rebates_1,taxable_income_1
            
        max_loop_count=1000
                     
        proceed_2=1
        distance_secant=1
        
        x_0=0
        x_2=1

        if (have_secant_guess==1) then

            x_0=max(secant_guess-secant_guess_width,0.d0)
            x_2=min(secant_guess+secant_guess_width,1.d0)

        end if

        x_1=(x_0+x_2)/2
                    
        loop_1=1
            
        do while ((distance_secant>stopping_rule_secant) .AND. (loop_1<max_loop_count))
        
            after_tax_wealth_net_of_expenses_1=after_tax_wealth_net_of_expenses_2
            gross_wage_income_1=gross_wage_income_2
            wage_income_tax_paid_1=wage_income_tax_paid_2
            food_stamps_1=food_stamps_2
            housing_voucher_1=housing_voucher_2
            housing_voucher_3=housing_voucher_4
            mortgage_deductions_tax_rebates_1=mortgage_deductions_tax_rebates_2
            
            labor_supply_1=x_1
                        
            call objective(time_period,MU_1,MU_2,x_1,after_tax_wealth_net_of_expenses_1,&
                financial_index_1,future_financial_amount_1,space_lived_in_1,&
                future_housing_status_index_1,can_consume_1,gross_wage_income_1,&
                wage_income_tax_paid_1,food_stamps_1,housing_voucher_1,housing_voucher_3,&
                mortgage_deductions_tax_rebates_1,years_left_on_mortgage_1,addiction_index_1,taxable_income_1)
                
            if (abs(consumption_choice-total_consumption_choice*(1-frac_spent_on_addiction))>10.d0**(-8)) then
        
                write(*,*) "wrong_secant"
                write(*,*) "consumption_choice=", consumption_choice
                write(*,*) "total_consumption_choice=", total_consumption_choice
                write(*,*) "frac_spent_on_addiction=", frac_spent_on_addiction
            
            end if
                
            if (can_consume_1==1) then
            
                proceed_2=1
                
                ! need more work, make the lower bound higher (update up)
                if (MU_1<MU_2) then
                
                    x_0=x_1
                    x_1=(x_1+x_2)/2
                    
                ! need less lesiure, make the upper bound lower (update down)
                else
                
                    x_2=x_1
                    x_1=(x_1+x_0)/2
                
                end if
                                
                distance_secant=abs(x_0-x_2)
                
!                if (x_1<10.d0**(-8)) then
!                
!                    x_1=0
!                    call objective(time_period,MU_1,MU_2,x_1,after_tax_wealth_net_of_expenses_1,&
!                        financial_index_1,future_financial_amount_1,space_lived_in_1,&
!                        future_housing_status_index_1,can_consume_1,gross_wage_income_1,&
!                        wage_income_tax_paid_1,food_stamps_1,housing_voucher_1,housing_voucher_3,&
!                        mortgage_deductions_tax_rebates_1,years_left_on_mortgage_1,addiction_index_1,taxable_income_1)
!                    
!                end if
                                    
            ! Not enough to consume, must raise lower bound on work
            else
            
                x_0=x_1
                x_1=(x_1+x_2)/2
                
                proceed_2=0

                ! THE BRACKET WIDTH, NOT THE MARGINAL UTILITIES. This is the
                ! path where objective returned can_consume_1=0, and on that
                ! path it assigns NEITHER of its intent(out) arguments, so
                ! MU_1 and MU_2 are undefined here. Under gfortran the dummies
                ! alias the caller's variables so what was read was the previous
                ! iteration's pair rather than garbage, which is why it never
                ! showed -- but the do while termination test depended on it.
                !
                ! The sibling branch a few lines below already terminates on
                ! abs(x_0-x_2), which is the bisection's own bracket and is
                ! always defined. The other three call sites guard on
                ! can_consume_1==1 before reading MU; this one could not,
                ! because it IS the not-consuming path.
                distance_secant=abs(x_0-x_2)
                
            end if
                        
            loop_1=loop_1+1
                                            
        end do
        
        ! The warm bracket is only a guess. If the answer sits on one of its
        ! edges the root was outside it, so the bracket is discarded and the
        ! whole interval bisected.
        if ((have_secant_guess==1) .AND. (can_consume_1==1) .AND. &
            ((labor_supply_1<=x_0+10.d0**(-6)) .OR. (labor_supply_1>=x_2-10.d0**(-6))) .AND. &
            ((x_0>0) .OR. (x_2<1))) then

            x_0=0
            x_2=1
            x_1=0.5
            distance_secant=1
            loop_1=1

            do while ((distance_secant>stopping_rule_secant) .AND. (loop_1<max_loop_count))

                after_tax_wealth_net_of_expenses_1=after_tax_wealth_net_of_expenses_2
                gross_wage_income_1=gross_wage_income_2
                wage_income_tax_paid_1=wage_income_tax_paid_2
                food_stamps_1=food_stamps_2
                housing_voucher_1=housing_voucher_2
                housing_voucher_3=housing_voucher_4
                mortgage_deductions_tax_rebates_1=mortgage_deductions_tax_rebates_2

                labor_supply_1=x_1

                call objective(time_period,MU_1,MU_2,x_1,after_tax_wealth_net_of_expenses_1,&
                    financial_index_1,future_financial_amount_1,space_lived_in_1,&
                    future_housing_status_index_1,can_consume_1,gross_wage_income_1,&
                    wage_income_tax_paid_1,food_stamps_1,housing_voucher_1,housing_voucher_3,&
                    mortgage_deductions_tax_rebates_1,years_left_on_mortgage_1,addiction_index_1,taxable_income_1)

                if (can_consume_1==1) then

                    proceed_2=1

                    if (MU_1<MU_2) then

                        x_0=x_1
                        x_1=(x_1+x_2)/2

                    else

                        x_2=x_1
                        x_1=(x_1+x_0)/2

                    end if

                    distance_secant=abs(x_0-x_2)

                else

                    x_0=x_1
                    x_1=(x_1+x_2)/2
                    proceed_2=0
                    ! Same undefined read as above, same fix: the bracket width,
                    ! which is what the branch directly above this one uses.
                    distance_secant=abs(x_0-x_2)

                end if

                loop_1=loop_1+1

            end do

        end if

        if ((labor_supply_1>1) .OR. (labor_supply_1<0)) then
        
            write(*,*) "labor_supply_1=", labor_supply_1
        
        end if
        
        ! IT MUST TEST THE QUANTITY THE LOOP CONVERGED ON, AND IT DID NOT.
        !
        ! The loop above exits when distance_secant, which is abs(x_0-x_2), the
        ! width of the BRACKET, falls under stopping_rule_secant. This warning
        ! tested abs(MU_1-MU_2), the gap in MARGINAL UTILITY, against the same
        ! 1e-8. Those are different quantities in different units: a bisection on
        ! [0,1] reaches a bracket of 1e-8 in about twenty seven steps, while the
        ! marginal utility gap at that point is whatever the function's slope
        ! makes it and is essentially never under 1e-8. So the warning fired for
        ! a converged solve, at essentially every working-age household state.
        !
        ! IT COST THE WHOLE EVENING. Eleven unbuffered writes per occurrence,
        ! with GFORTRAN_UNBUFFERED_ALL=1 set by run_one_point.sh, serialise all
        ! four OpenMP threads on stdout. A worker measured 1.42 MB/s of it and a
        ! working age costing 191 seconds against 0.4 for a retired one -- a
        ! factor of about 500 -- and 6.3 GB emitted in 73 minutes with no moments
        ! block at the end of it. NO POINT HAS EVER BEEN MEASURED on a source at
        ! or after the commit that made this able to fire.
        !
        ! Both halves are mine, from 84c1ee5: that commit changed the loop test
        ! from the marginal utilities to the bracket, and in the same pass gave
        ! this warning a condition that was still on the marginal utilities. Each
        ! change was right on its own and together they are inconsistent.
        !
        ! LEAVING WITHOUT CONVERGING IS HITTING THE ITERATION CAP, which is what
        ! the warning is for and what it now tests. That cannot fire on a solve
        ! that converged, whatever the marginal utilities do. The gap is still
        ! printed, as information rather than as the trigger.
        !
        ! AND IT IS THROTTLED REGARDLESS. Eleven writes inside a parallel region
        ! is a hazard even when the condition is right, because a genuine
        ! non-convergence at many states would cost the same hours. After
        ! secant_warn_cap occurrences it stops printing and the count is reported
        ! once, at the end of the run.
        if ((can_consume_1==1) .AND. (loop_1>=max_loop_count) .AND. (x_1>0) .AND. (x_1<1)) then

            !$omp atomic
            secant_warn_count=secant_warn_count+1

            if (secant_warn_count<=secant_warn_cap) then

            write(*,*) "labor"
            write(*,*) "distance_secant=", distance_secant
            write(*,*) "loop_1=", loop_1
            write(*,*) "MU_1=", MU_1
            write(*,*) "MU_2=", MU_2
            write(*,*) "x_1=", x_1
            write(*,*) "x_0=", x_0 
            write(*,*) "x_2=", x_2
            write(*,*) "addiction_index_1=", addiction_index_1
            write(*,*) "consumption_choice=", consumption_choice
            write(*,*) "frac_spent_on_addiction=", frac_spent_on_addiction
            write(*,*) "taxable_income_1=", taxable_income_1

            end if

        end if
        
        call objective(time_period,MU_1,MU_2,labor_supply_1,after_tax_wealth_net_of_expenses_2,&
            financial_index_1,future_financial_amount_1,space_lived_in_1,future_housing_status_index_1,&
            can_consume_1,gross_wage_income_2,wage_income_tax_paid_2,food_stamps_2,housing_voucher_2,&
            housing_voucher_4,mortgage_deductions_tax_rebates_2,years_left_on_mortgage_1,addiction_index_1,taxable_income_1)
                                         
    end subroutine

    subroutine objective(time_period,MU_1,MU_2,labor_supply_1,after_tax_wealth_net_of_expenses_1,financial_index_1,&
        future_financial_amount_1,space_lived_in_1,future_housing_status_index_1,can_consume_1,gross_wage_income_1,&
        wage_income_tax_paid_1,food_stamps_1,housing_voucher_1,housing_voucher_2,mortgage_deductions_tax_rebates_1,&
        years_left_on_mortgage_1,addiction_index_1,taxable_income_1)
        
        use Global_Vars

        real(8), intent(out) :: MU_1,MU_2
        real(8), intent(inout) :: labor_supply_1,gross_wage_income_1,wage_income_tax_paid_1,food_stamps_1,&
            housing_voucher_1,after_tax_wealth_net_of_expenses_1,mortgage_deductions_tax_rebates_1,&
            housing_voucher_2
        integer, intent(inout) :: can_consume_1,years_left_on_mortgage_1
        real(8), intent(in) :: future_financial_amount_1,space_lived_in_1
        integer, intent(in) :: financial_index_1,future_housing_status_index_1,addiction_index_1
        real(8) :: consumption_1,income_2
        real(8), intent(out) :: taxable_income_1
        integer, intent(in) :: time_period
        integer :: mortgage_index_2,deduct_MID,is_current_owner,choose_to_rent,low_quality_market
        real(8) :: deductions_claimed_1,max_gross_wage_income_1,&
            tax_liability_with_mortgage_deductions_1,tax_liability_without_mortgage_deductions_1,assets_1,&
            avg_net_wealth_to_use_1,avg_income_to_use_1,homeowner_spending,bequest_1
            
        if (inheritance_function_of_productivity==1) then
                        
            bequest_1=employment_grid(age_index,employment_index)*inheritance_amount(age_index)+&
                            newborn_age_transfer(age_index)
         
        else
        
            call calculate_bequest_amount(age_index,bequest_1,employment_index)
            
        end if
            
        if ((future_housing_status_index_1>second_lowest_housing_grid_point) .OR. &
           (have_two_rental_markets==0)) then
        
            low_quality_market=0
        
        else
        
            low_quality_market=1
        
        end if
        
        if (years_left_on_mortgage_index>1) then
                                    
            is_current_owner=1
            homeowner_spending=&
                housing_price(time_period)*housing_size(housing_status_index)*&
                (property_tax(time_period)+housing_depreciation_rate-&
                mortgage_interest_rate(time_period)*min(financial_grid(financial_index_1),0.d0))
                           
        else
        
            is_current_owner=0
            homeowner_spending=0
            
        end if
        
        if (years_left_on_mortgage_1==2) then
            
            choose_to_rent=0
            
        else
        
            choose_to_rent=1
            
        end if
                            
        avg_income_to_use_1=is_counterfactual*average_labor_income_calibrated+&
            (1-is_counterfactual)*model_average_labour_income(time_period)
            
        avg_net_wealth_to_use_1=is_counterfactual*average_net_wealth_calibrated+&
            (1-is_counterfactual)*model_average_net_wealth(time_period)
          
        can_consume_1=1
          
        ! eq:fincome. The two productivity penalties, conditional on working.
        ! rho_d is what lets an EMPLOYED household be poor enough to be priced
        ! out of housing; rho_m is the same for SMI. Both multiply earnings
        ! down, so both are below one.
        !
        ! unemployment_index is safe to read here: the loop over it sits OUTSIDE
        ! the omp parallel do, which runs over the financial index.
        max_gross_wage_income_1=employment_grid(age_index,employment_index)*labour_deterministic_efficiency(age_index)*&
            (rho_d**(min(sud_of(unemployment_index),1)*include_rho_d))*&
            (rho_m**(min(smi_of(unemployment_index),1)*include_rho_m))
        
        after_tax_wealth_net_of_expenses_1=after_tax_wealth_net_of_expenses_1-&
            (gross_wage_income_1-wage_income_tax_paid_1+food_stamps_1+housing_voucher_1+housing_voucher_2)

        gross_wage_income_1=labor_supply_1*max_gross_wage_income_1
        
        food_stamps_1=0
        assets_1=2*threshold_for_food_stamps_as_perc_of_average_net_wealth*avg_net_wealth_to_use_1

        ! Checking if the household has assets

        ! This one is a homeowner
        if ((years_left_on_mortgage_index>1) .AND. (years_left_on_mortgage_1==1)) then

            assets_1=housing_price(time_period)*housing_size(housing_status_index)*&
                ((1-cost_of_selling-property_tax(time_period)-housing_depreciation_rate)+&
                min(financial_grid(financial_index_1),0.d0)*(1+mortgage_interest_rate(time_period)))+&
                max(financial_grid(financial_index_1),0.d0)
    
        ! This one is a renter
        elseif ((years_left_on_mortgage_index==1) .AND. (years_left_on_mortgage_1==1)) then
        
            assets_1=financial_grid(financial_index_1)

        end if
        
        ! If they have no assets, they get can qualift for food stamps
        if (assets_1<threshold_for_food_stamps_as_perc_of_average_net_wealth*avg_net_wealth_to_use_1) then
                                
            food_stamps_1=snap_benefit(actual_household_size(age_index),&
                gross_wage_income_1+risk_free_rate(time_period)*max(financial_grid(financial_index_1),0.d0),&
                avg_income_to_use_1)
                                        
        end if
        
        housing_voucher_1=0
        
        if (provide_vouchers==1) then
        
            if ((years_left_on_mortgage_1>=1) .AND. &
                ((space_lived_in_1-housing_size(lowest_housing_grid_point))>10.d0**(-2))) then
                
                call calculate_housing_voucher(housing_voucher_1,gross_wage_income_1,&
                    rent(time_period,low_quality_market)*space_lived_in_1,homeowner_spending,&
                    is_current_owner,choose_to_rent,time_period)
                                    
            end if
            
        end if
        
        housing_voucher_2=0
                
        if ((is_current_owner==0) .AND. (years_left_on_mortgage_1==1) .AND. (voucher_index==1) .AND. (include_vouchers==1)) then

            income_2=gross_wage_income_1+risk_free_rate(time_period)*max(financial_grid(financial_index_1),0.d0)
        
            if (income_2<threshold_income_vouchers*&
                ((1-is_counterfactual)*median_income(time_period)+is_counterfactual*median_income_calibrated)) then
            
                call calculate_housing_voucher_2(housing_voucher_2,future_addiction_index,income_2,&
                    rent(time_period,low_quality_market)*space_lived_in_1,time_period)

            end if
        
        end if
                                
        mortgage_index_2=min(financial_index_1,negative_financial_grid_size)
                     
        deduct_MID=0
        deductions_claimed_1=0
        tax_liability_with_mortgage_deductions_1=0
        tax_liability_without_mortgage_deductions_1=0
        mortgage_deductions_tax_rebates_1=0
                                    
        if ((years_left_on_mortgage_index>1) .AND. ((mortgage_deductibility>0) .OR. (property_tax_deductibility>0))) then
                            
            deductions_claimed_1=&
                (mortgage_deductibility*min(-min(financial_grid(mortgage_index_2),0.d0)*&
                housing_price(time_period)*housing_size(housing_status_index),&
                max_MID_debt*(is_counterfactual*average_labor_income_calibrated+&
                (1-is_counterfactual)*model_average_labour_income(time_period)))*mortgage_interest_rate(time_period)+&
                (property_tax_deductibility*property_tax(time_period)+include_housing_depreciation_in_housing_costs*&
                housing_depreciation_rate)*housing_price(time_period)*housing_size(housing_status_index))
                
            deductions_claimed_1=max(deductions_claimed_1,0.d0)
                
            if (deductions_claimed_1>standard_deduction) then
                
                deduct_MID=1
                                                                                    
                tax_liability_with_mortgage_deductions_1=&
                    max(max(gross_wage_income_1-personal_exemption-deductions_claimed_1,0.d0)-&
                    (labor_income_tax_rate+increase_in_labour_income_tax)*&
                    max(gross_wage_income_1-personal_exemption-deductions_claimed_1,0.d0)**&
                    curvature_of_labor_income_taxes,0.d0)
                                
                tax_liability_without_mortgage_deductions_1=&
                    max(max(gross_wage_income_1-personal_exemption-standard_deduction,0.d0)-&
                    (labor_income_tax_rate+increase_in_labour_income_tax)*&
                    max(gross_wage_income_1-personal_exemption-standard_deduction,0.d0)**&
                    curvature_of_labor_income_taxes,0.d0)
                    
                mortgage_deductions_tax_rebates_1=max(tax_liability_without_mortgage_deductions_1-&
                    tax_liability_with_mortgage_deductions_1,0.d0)
            
            end if
                     
        end if

        taxable_income_1=max(gross_wage_income_1-personal_exemption-&
            deduct_MID*deductions_claimed_1-(1-deduct_MID)*standard_deduction,0.d0)
                    
        wage_income_tax_paid_1=&
            max(max(taxable_income_1,0.d0)-(labor_income_tax_rate+increase_in_labour_income_tax)*&
            max(taxable_income_1,0.d0)**curvature_of_labor_income_taxes,0.d0)
            
        after_tax_wealth_net_of_expenses_1=after_tax_wealth_net_of_expenses_1+&
            (gross_wage_income_1-wage_income_tax_paid_1+food_stamps_1+housing_voucher_1+housing_voucher_2)
            
        consumption_1=(after_tax_wealth_net_of_expenses_1-future_financial_amount_1)/(1+consumption_tax)
        
        consumption_choice=consumption_1
        total_consumption_choice=consumption_1
        
        frac_spent_on_addiction=0
        
        call calculate_addiction_spending(consumption_1,food_stamps_1,addiction_index_1,space_lived_in_1)
        
        if (abs(consumption_choice-total_consumption_choice*(1-frac_spent_on_addiction))>10.d0**(-8)) then
        
            write(*,*) "wrong_objective"
            write(*,*) "consumption_choice=", consumption_choice
            write(*,*) "total_consumption_choice=", total_consumption_choice
            write(*,*) "frac_spent_on_addiction=", frac_spent_on_addiction
        
        end if
                
        if ((consumption_choice>=(food_stamps_1/(1+consumption_tax))) .AND. &
           (consumption_choice>0)) then 
                  
            MU_1=relative_share_of_leisure*(max_labor_supply-labor_supply_1)**(-leisure_curvature)
                
            if (use_cobb_douglas==1) then
        
                if (frac_spent_on_addiction>0) then
                
                    MU_2=(1-relative_share_of_addiction)*scaled_household_size(age_index)*&
                        ((consumption_choice**(1-relative_share_of_housing)*&
                        (space_lived_in_1)**(relative_share_of_housing))**&
                        (-risk_aversion_consumption))*(((1-relative_share_of_housing)*&
                        (consumption_choice)**(-relative_share_of_housing))*((space_lived_in_1)**&
                        (relative_share_of_housing)))
                
                    if (housing_voucher_2==0) then
                    
                        if (taxable_income_1>0) then
                                    
                            MU_2=MU_2*(curvature_of_labor_income_taxes*&
                                (labor_income_tax_rate+increase_in_labour_income_tax)*max_gross_wage_income_1*(taxable_income_1)**&
                                (curvature_of_labor_income_taxes-1))/(1+consumption_tax)
                                
                        else
                        
                            MU_2=MU_2*(max_gross_wage_income_1)/(1+consumption_tax)
                        
                        end if
                            
                    else
                    
                        if (taxable_income_1>0) then
                    
                            MU_2=MU_2*(curvature_of_labor_income_taxes*&
                                (labor_income_tax_rate+increase_in_labour_income_tax)*max_gross_wage_income_1*(taxable_income_1)**&
                                (curvature_of_labor_income_taxes-1)-&
                                rent_to_income_ratio_vouchers*max_gross_wage_income_1)/(1+consumption_tax)
                                
                        else
                        
                            MU_2=MU_2*(max_gross_wage_income_1-&
                                rent_to_income_ratio_vouchers*max_gross_wage_income_1)/(1+consumption_tax)
                        
                        end if
                    
                    end if
                
                else
                    
                    MU_2=scaled_household_size(age_index)*&
                        ((consumption_choice**(1-relative_share_of_housing)*&
                        (space_lived_in_1)**(relative_share_of_housing))**(-risk_aversion_consumption))*&
                        ((1-relative_share_of_housing)*(consumption_choice)**(-relative_share_of_housing)*&
                        (space_lived_in_1)**(relative_share_of_housing))
                
                    if (housing_voucher_2==0) then
                    
                        if (taxable_income_1>0) then
                                        
                            MU_2=MU_2*(curvature_of_labor_income_taxes*&
                                (labor_income_tax_rate+increase_in_labour_income_tax)*max_gross_wage_income_1*(taxable_income_1)**&
                                (curvature_of_labor_income_taxes-1))/(1+consumption_tax)
                                
                        else
                        
                            MU_2=MU_2*(max_gross_wage_income_1)/(1+consumption_tax)
                        
                        end if
                            
                    else
                    
                        if (taxable_income_1>0) then
                    
                            MU_2=MU_2*(curvature_of_labor_income_taxes*&
                                (labor_income_tax_rate+increase_in_labour_income_tax)*max_gross_wage_income_1*(taxable_income_1)**&
                                (curvature_of_labor_income_taxes-1)-&
                                rent_to_income_ratio_vouchers*max_gross_wage_income_1)/(1+consumption_tax)
                                
                        else
                        
                            MU_2=MU_2*(max_gross_wage_income_1-&
                                rent_to_income_ratio_vouchers*max_gross_wage_income_1)/(1+consumption_tax)
                        
                        end if
                    
                    end if
                        
                end if
                
            elseif (use_cobb_douglas_2==1) then 
            
                MU_2=scaled_household_size(age_index)*&
                    (((consumption_choice**relative_share_of_consumption_2)*&
                    (space_lived_in_1**relative_share_of_housing)*&
                    (b_shifter(0,housing_size(future_housing_status_index_1))+(frac_spent_on_addiction*total_consumption_choice)/&
                    price_of_addictive_good)**relative_share_of_addiction)**(-risk_aversion_consumption))*&
                    (relative_share_of_consumption_2*consumption_choice**(relative_share_of_consumption_2-1))*&
                    ((space_lived_in_1**relative_share_of_housing)*&
                    (b_shifter(0,housing_size(future_housing_status_index_1))+((frac_spent_on_addiction*total_consumption_choice)/&
                    price_of_addictive_good))**relative_share_of_addiction)
            
                if (housing_voucher_2==0) then
                
                    if (taxable_income_1>0) then
                                
                        MU_2=MU_2*(curvature_of_labor_income_taxes*&
                            (labor_income_tax_rate+increase_in_labour_income_tax)*max_gross_wage_income_1*(taxable_income_1)**&
                            (curvature_of_labor_income_taxes-1))/(1+consumption_tax)
                            
                    else
                    
                        MU_2=MU_2*(max_gross_wage_income_1)/(1+consumption_tax)
                    
                    end if
                        
                else
                
                    if (taxable_income_1>0) then
                
                        MU_2=MU_2*(curvature_of_labor_income_taxes*&
                            (labor_income_tax_rate+increase_in_labour_income_tax)*max_gross_wage_income_1*(taxable_income_1)**&
                            (curvature_of_labor_income_taxes-1)-&
                            rent_to_income_ratio_vouchers*max_gross_wage_income_1)/(1+consumption_tax)
                            
                    else
                    
                        MU_2=MU_2*(max_gross_wage_income_1-&
                            rent_to_income_ratio_vouchers*max_gross_wage_income_1)/(1+consumption_tax)
                    
                    end if
                
                end if
                
            elseif (include_probability_of_becoming_addicted==1) then
            
                if (unemployment_index>threshold_addiction_index) then
            
                    MU_2=scaled_household_size(age_index)*&
                        (((consumption_choice**relative_share_of_consumption_2)*&
                        (space_lived_in_1**relative_share_of_housing_2)*&
                        ((b_shifter(1,housing_size(future_housing_status_index_1))+(frac_spent_on_addiction*total_consumption_choice)/&
                        price_of_addictive_good))**relative_share_of_addiction_2)**(-risk_aversion_consumption))*&
                        (relative_share_of_consumption_2*consumption_choice**(relative_share_of_consumption_2-1))*&
                        ((space_lived_in_1**relative_share_of_housing_2)*&
                        ((b_shifter(1,housing_size(future_housing_status_index_1))+(frac_spent_on_addiction*total_consumption_choice)/&
                        price_of_addictive_good))**relative_share_of_addiction_2)
                        
                else
                
                    MU_2=scaled_household_size(age_index)*&
                        (((consumption_choice**relative_share_of_consumption_1)*&
                        (space_lived_in_1**relative_share_of_housing_1)*&
                        ((b_shifter(0,housing_size(future_housing_status_index_1))+(frac_spent_on_addiction*total_consumption_choice)/&
                        price_of_addictive_good))**relative_share_of_addiction_1)**(-risk_aversion_consumption))*&
                        (relative_share_of_consumption_1*consumption_choice**(relative_share_of_consumption_1-1))*&
                        ((space_lived_in_1**relative_share_of_housing_1)*&
                        ((b_shifter(0,housing_size(future_housing_status_index_1))+(frac_spent_on_addiction*total_consumption_choice)/&
                        price_of_addictive_good))**relative_share_of_addiction_1)
                
                end if
            
                if (housing_voucher_2==0) then
                
                    if (taxable_income_1>0) then
                                
                        MU_2=MU_2*(curvature_of_labor_income_taxes*&
                            (labor_income_tax_rate+increase_in_labour_income_tax)*max_gross_wage_income_1*(taxable_income_1)**&
                            (curvature_of_labor_income_taxes-1))/(1+consumption_tax)
                            
                    else
                    
                        MU_2=MU_2*(max_gross_wage_income_1)/(1+consumption_tax)
                    
                    end if
                        
                else
                
                    if (taxable_income_1>0) then
                
                        MU_2=MU_2*(curvature_of_labor_income_taxes*&
                            (labor_income_tax_rate+increase_in_labour_income_tax)*max_gross_wage_income_1*(taxable_income_1)**&
                            (curvature_of_labor_income_taxes-1)-&
                            rent_to_income_ratio_vouchers*max_gross_wage_income_1)/(1+consumption_tax)
                            
                    else
                    
                        MU_2=MU_2*(max_gross_wage_income_1-&
                            rent_to_income_ratio_vouchers*max_gross_wage_income_1)/(1+consumption_tax)
                    
                    end if
                
                end if
                
            else
            
                if (frac_spent_on_addiction>0) then
                
                    MU_2=(1-utility_improvement)*&
                        ((relative_share_of_housing_2*(space_lived_in_1/sqrt_household_size(age_index))**(power_1)+&
                        relative_share_of_consumption_2*(consumption_choice/sqrt_household_size(age_index))**(power_1)+&
                        relative_share_of_addiction*(((frac_spent_on_addiction*total_consumption_choice)/&
                        price_of_addictive_good)/sqrt_household_size(age_index))**&
                        (power_3))**(power_2-1))*(relative_share_of_consumption_2*&
                        (consumption_choice/sqrt_household_size(age_index))**(power_1-1))
                
                    if (housing_voucher_2==0) then
                    
                        if (taxable_income_1>0) then
                                    
                            MU_2=MU_2*(curvature_of_labor_income_taxes*(labor_income_tax_rate+increase_in_labour_income_tax)*&
                                max_gross_wage_income_1*(taxable_income_1)**(curvature_of_labor_income_taxes-1))/(1+consumption_tax)
                                
                        else
                        
                            MU_2=MU_2*(max_gross_wage_income_1)/(1+consumption_tax)
                        
                        end if
                            
                    else
                    
                        if (taxable_income_1>0) then
                    
                            MU_2=MU_2*(curvature_of_labor_income_taxes*(labor_income_tax_rate+increase_in_labour_income_tax)*&
                                max_gross_wage_income_1*(taxable_income_1)**(curvature_of_labor_income_taxes-1)-&
                                rent_to_income_ratio_vouchers*max_gross_wage_income_1)/(1+consumption_tax)
                    
                        else
                        
                            MU_2=MU_2*(max_gross_wage_income_1-&
                                rent_to_income_ratio_vouchers*max_gross_wage_income_1)/(1+consumption_tax)
                        
                        end if
                    
                    end if
                                    
                else
                
                    MU_2=((relative_share_of_housing*(space_lived_in_1/sqrt_household_size(age_index))**(power_1)+&
                        (1-relative_share_of_housing)*(consumption_choice/sqrt_household_size(age_index))**&
                        (power_1))**(power_2-1))*((1-relative_share_of_housing)*&
                        (consumption_choice/sqrt_household_size(age_index))**(power_1-1))
                
                    if (housing_voucher_2==0) then
                    
                        if (taxable_income_1>0) then
                                    
                            MU_2=MU_2*(curvature_of_labor_income_taxes*(labor_income_tax_rate+increase_in_labour_income_tax)*&
                                max_gross_wage_income_1*(taxable_income_1)**(curvature_of_labor_income_taxes-1))/(1+consumption_tax)
                                
                        else
                        
                            MU_2=MU_2*(max_gross_wage_income_1)/(1+consumption_tax)
                        
                        end if
                            
                    else
                    
                        if (taxable_income_1>0) then
                    
                            MU_2=MU_2*(curvature_of_labor_income_taxes*(labor_income_tax_rate+increase_in_labour_income_tax)*&
                                max_gross_wage_income_1*(taxable_income_1)**(curvature_of_labor_income_taxes-1)-&
                                rent_to_income_ratio_vouchers*max_gross_wage_income_1)/(1+consumption_tax)
                                
                        else
                        
                            MU_2=MU_2*(max_gross_wage_income_1-&
                                rent_to_income_ratio_vouchers*max_gross_wage_income_1)/(1+consumption_tax)
                        
                        end if
                    
                    end if
                        
                end if
            
            end if
                                    
        else
                
            can_consume_1=0                

        end if
        
    end subroutine
    
    subroutine calculate_after_tax_wealth(financial_index_1,future_financial_index_1,years_left_on_mortgage_1,&
        pay_mortgage_insurance_1,housing_status_index_1,future_housing_status_index_1,&
        owner_to_owner_move_1,owner_to_renter_1,renter_to_owner_1,owner_to_owner_stay_1,renter_to_renter_1,&
        time_period,labor_supply_1,cutoff_taxable_income_1,addiction_index_1)
    
        use Global_Vars
        
        implicit none
        
        integer :: financial_index_1,future_financial_index_1,years_left_on_mortgage_1,&
            housing_status_index_1,future_housing_status_index_1,pay_mortgage_insurance_1,owner_to_owner_move_1,&
            owner_to_renter_1,renter_to_owner_1,owner_to_owner_stay_1,renter_to_renter_1,time_period,&
            mortgage_index_2,deduct_MID,is_current_owner,choose_to_rent,low_quality_market,addiction_index_1
        real(8) :: newborn_transfer_1
                    
        real(8) :: tax_liability_with_mortgage_deductions_1,tax_liability_without_mortgage_deductions_1,&
            cost_of_mortgage,cost_of_housing,deductions_claimed_1,lump_sum_transfer_given,&
            prepayment_penalty_1,origination_cost_1,fixed_cost_to_moving_1,labor_supply_1,&
            cutoff_taxable_income_1,bequest_1,avg_income_to_use_1,avg_income_to_use_2,assets_1,avg_net_wealth_to_use_1,&
            homeowner_spending,taxable_income_1
            
        if ((future_housing_status_index_1>second_lowest_housing_grid_point) .OR. &
           (have_two_rental_markets==0)) then
        
            low_quality_market=0
        
        else
        
            low_quality_market=1
        
        end if
                    
        avg_income_to_use_1=is_counterfactual*average_labor_income_calibrated+&
            (1-is_counterfactual)*model_average_labour_income(time_period)
            
        avg_income_to_use_2=is_counterfactual*average_labor_income_by_employment_calibrated(employment_index)+&
            (1-is_counterfactual)*model_average_labour_income_by_employment(time_period,employment_index)
            
        avg_net_wealth_to_use_1=is_counterfactual*average_net_wealth_calibrated+&
            (1-is_counterfactual)*model_average_net_wealth(time_period)
                    
        if (years_left_on_mortgage_index>1) then
                                    
            is_current_owner=1
            homeowner_spending=&
                housing_price(time_period)*housing_size(housing_status_index_1)*&
                (property_tax(time_period)+housing_depreciation_rate-&
                mortgage_interest_rate(time_period)*min(financial_grid(financial_index_1),0.d0))                
                           
        else
        
            is_current_owner=0
            homeowner_spending=0
            
        end if
        
        if ((renter_to_renter_1==1) .OR. (owner_to_renter_1==1)) then
            
            choose_to_rent=1
            
        else
        
            choose_to_rent=0
            
        end if
        
        if (inheritance_function_of_productivity==1) then
                        
            bequest_1=employment_grid(age_index,employment_index)*inheritance_amount(age_index)+&
                            newborn_age_transfer(age_index)
            
        else
        
            call calculate_bequest_amount(age_index,bequest_1,employment_index)
            
        end if
                                    
        call calculate_income(unemployment_index,employment_index,gross_wage_income,&
            avg_income_to_use_1,avg_income_to_use_2,labor_supply_1,in_retirement)
                                                             
        total_household_working_wealth=max(financial_grid(financial_index_1),0.d0)
                                                           
        investment_income=total_household_working_wealth*risk_free_rate(time_period)
                                                                                                                          
        investment_income_tax_paid=investment_income_tax*max(investment_income,0.d0)
                                                
        mortgage_index_2=min(financial_index_1,negative_financial_grid_size)
                     
        deduct_MID=0
        deductions_claimed_1=0
        tax_liability_with_mortgage_deductions_1=0
        tax_liability_without_mortgage_deductions_1=0
        mortgage_deductions_tax_rebates=0
                                    
        if ((years_left_on_mortgage_1>1) .AND. ((mortgage_deductibility>0) .OR. (property_tax_deductibility>0))) then
                            
            deductions_claimed_1=&
                (mortgage_deductibility*min((-min(financial_grid(mortgage_index_2),0.d0))*&
                housing_price(time_period)*housing_size(housing_status_index_1),&
                max_MID_debt*avg_income_to_use_1)*(pay_mortgage_insurance_1*&
                mortgage_insurance_premium+mortgage_interest_rate(time_period))+&
                (property_tax_deductibility*property_tax(time_period)+include_housing_depreciation_in_housing_costs*&
                housing_depreciation_rate)*housing_price(time_period)*housing_size(housing_status_index_1))
                
            deductions_claimed_1=max(deductions_claimed_1,0.d0)
                
            if (deductions_claimed_1>standard_deduction) then
                
                deduct_MID=1
                                                                                    
                tax_liability_with_mortgage_deductions_1=&
                    max(max(gross_wage_income-personal_exemption-deductions_claimed_1,0.d0)-&
                    (labor_income_tax_rate+increase_in_labour_income_tax)*&
                    max(gross_wage_income-personal_exemption-deductions_claimed_1,0.d0)**&
                    curvature_of_labor_income_taxes,0.d0)
                                
                tax_liability_without_mortgage_deductions_1=&
                    max(max(gross_wage_income-personal_exemption-standard_deduction,0.d0)-&
                    (labor_income_tax_rate+increase_in_labour_income_tax)*&
                    max(gross_wage_income-personal_exemption-standard_deduction,0.d0)**&
                    curvature_of_labor_income_taxes,0.d0)
                    
                mortgage_deductions_tax_rebates=max(tax_liability_without_mortgage_deductions_1-&
                    tax_liability_with_mortgage_deductions_1,0.d0)
            
            end if
                     
        end if

        cutoff_taxable_income_1=personal_exemption+deduct_MID*deductions_claimed_1+(1-deduct_MID)*standard_deduction
                    
        taxable_income_1=max(gross_wage_income-personal_exemption-deduct_MID*deductions_claimed_1-&
            (1-deduct_MID)*standard_deduction,0.d0)
                
        wage_income_tax_paid=max(max(taxable_income_1,0.d0)-&
            (labor_income_tax_rate+increase_in_labour_income_tax)*&
            max(taxable_income_1,0.d0)**curvature_of_labor_income_taxes,0.d0)
                     
        food_stamps_recieved=0
        housing_voucher_recieved=0
        housing_voucher_recieved_2=0
        
        fixed_cost_to_moving_1=0
        lump_sum_transfer_given=0
        property_taxes_paid=0
        housing_depreciation_expenditures=0
        cost_of_mortgage=0  
        origination_cost_1=0
        prepayment_penalty_1=0
        cost_of_housing=0
        rent_spending=0
                              
        if (renter_to_renter_1==1) then
                                
            if (future_housing_status_index_1==lowest_housing_grid_point) then
            
                rent_spending=0
                
            else
                    
                rent_spending=rent(time_period,low_quality_market)*housing_size(future_housing_status_index_1)
                
            end if
                                       
            if (((future_housing_status_index_1 .NE. housing_status_index_1) .OR. &
                (years_left_on_mortgage_index .NE. 1)) .AND. (age_index>1)) then
                        
                fixed_cost_to_moving_1=fixed_cost_to_moving
                            
            end if
                                                           
            if (financial_grid(financial_index_1)<threshold_for_food_stamps_as_perc_of_average_net_wealth*&
                avg_net_wealth_to_use_1) then
                            
                food_stamps_recieved=snap_benefit(actual_household_size(age_index),&
                    gross_wage_income+risk_free_rate(time_period)*max(financial_grid(financial_index_1),0.d0),&
                    avg_income_to_use_1)
                    
            end if
            
            if (provide_vouchers==1) then
            
                if (future_housing_status_index_1>lowest_housing_grid_point) then
            
                    call calculate_housing_voucher(housing_voucher_recieved,gross_wage_income,rent_spending,&
                        homeowner_spending,is_current_owner,choose_to_rent,time_period)
                        
                end if
                                
            end if

            if ((include_vouchers==1) .AND. (voucher_index==1) .AND. &
                (gross_wage_income+investment_income<threshold_income_vouchers*&
                ((1-is_counterfactual)*median_income(time_period)+is_counterfactual*median_income_calibrated))) then

                call calculate_housing_voucher_2(housing_voucher_recieved_2,future_addiction_index,&
                    gross_wage_income+investment_income,rent_spending,time_period)

            end if
            
        elseif (renter_to_owner_1==1) then
                
            if (financial_grid(future_financial_index_1)<0) then
        
                origination_cost_1=mortgage_origination_cost*avg_income_to_use_1
                    
            end if
                                           
            cost_of_housing=(1+cost_of_buying)*housing_price(time_period)*housing_size(future_housing_status_index_1)
                    
            if (provide_vouchers==1) then
            
                call calculate_housing_voucher(housing_voucher_recieved,gross_wage_income,&
                    rent_spending,homeowner_spending,is_current_owner,choose_to_rent,time_period)
                                
            end if
                                                                                                         
        elseif (owner_to_owner_stay_1==1) then
                                        
            if (financial_grid(financial_index_1)<0) then
            
                if (financial_grid(future_financial_index_1)<&
                    (financial_grid(financial_index_1)*(1-prepayment_penalty_starts_from))) then
                    
                    origination_cost_1=mortgage_origination_cost*avg_income_to_use_1
                    
                    prepayment_penalty_1=penalty_months_of_interest*mortgage_interest_rate(time_period)*&
                        (-min(financial_grid(financial_index_1),0.d0))*&
                        housing_price(time_period)*housing_size(housing_status_index_1)*&
                        (1-prepayment_penalty_starts_from)
                                                
                else
                
                    prepayment_penalty_1=penalty_months_of_interest*mortgage_interest_rate(time_period)*&
                        max(min(financial_grid(future_financial_index_1),0.d0)-&
                        min(financial_grid(financial_index_1),0.d0)*(1-prepayment_penalty_starts_from),0.d0)*&
                        housing_price(time_period)*housing_size(housing_status_index_1)
                        
                end if
                
            else
            
                if (financial_grid(future_financial_index_1)<0) then
            
                    origination_cost_1=mortgage_origination_cost*avg_income_to_use_1
                        
                end if
                
            end if
                                            
            cost_of_housing=housing_price(time_period)*housing_size(housing_status_index_1)
                                                           
            property_taxes_paid=property_tax(time_period-solve_transition_dynamics)*&
                housing_price(time_period-solve_transition_dynamics)*housing_size(housing_status_index_1)
                                                                                              
            housing_depreciation_expenditures=&
                housing_depreciation_rate*housing_price(time_period-solve_transition_dynamics)*housing_size(housing_status_index_1)
                                   
            cost_of_mortgage=-min(financial_grid(financial_index_1),0.d0)*&
                housing_price(time_period)*housing_size(housing_status_index_1)*&
                (1+mortgage_interest_rate(time_period)+pay_mortgage_insurance_1*mortgage_insurance_premium)
                
            if (provide_vouchers==1) then
            
                call calculate_housing_voucher(housing_voucher_recieved,gross_wage_income,rent_spending,&
                    homeowner_spending,is_current_owner,choose_to_rent,time_period)
                                
            end if
                                              
        elseif (owner_to_owner_move_1==1) then
                                    
            if (financial_grid(future_financial_index_1)<0) then
                        
                origination_cost_1=mortgage_origination_cost*avg_income_to_use_1
                   
            end if
                
            prepayment_penalty_1=penalty_months_of_interest*mortgage_interest_rate(time_period)*&
                (-min(financial_grid(financial_index_1),0.d0))*&
                housing_price(time_period)*housing_size(housing_status_index_1)*(1-prepayment_penalty_starts_from)
                                                              
            property_taxes_paid=property_tax(time_period-solve_transition_dynamics)*&
                housing_price(time_period-solve_transition_dynamics)*housing_size(housing_status_index_1)
                   
            cost_of_housing=(1+cost_of_buying)*housing_price(time_period)*housing_size(future_housing_status_index_1)+&
                cost_of_selling*housing_price(time_period)*housing_size(housing_status_index_1)
                                                                               
            housing_depreciation_expenditures=&
                housing_depreciation_rate*housing_price(time_period-solve_transition_dynamics)*housing_size(housing_status_index_1)
                                            
            cost_of_mortgage=-min(financial_grid(financial_index_1),0.d0)*&
                housing_price(time_period)*housing_size(housing_status_index_1)*&
                (1+mortgage_interest_rate(time_period)+pay_mortgage_insurance_1*mortgage_insurance_premium)
                
            if (provide_vouchers==1) then
            
                call calculate_housing_voucher(housing_voucher_recieved,gross_wage_income,rent_spending,&
                    homeowner_spending,is_current_owner,choose_to_rent,time_period)
                                
            end if
                                                    
        elseif (owner_to_renter_1==1) then
                
            prepayment_penalty_1=penalty_months_of_interest*mortgage_interest_rate(time_period)*&
                (-min(financial_grid(financial_index_1),0.d0))*housing_price(time_period)*housing_size(housing_status_index_1)*&
                (1-prepayment_penalty_starts_from)
                            
            if (future_housing_status_index_1==lowest_housing_grid_point) then
            
                rent_spending=0
            
            else
            
                rent_spending=rent(time_period,low_quality_market)*housing_size(future_housing_status_index_1)
            
            end if
                                                                                
            property_taxes_paid=property_tax(time_period-solve_transition_dynamics)*&
                housing_price(time_period-solve_transition_dynamics)*housing_size(housing_status_index_1)
                                             
            cost_of_housing=cost_of_selling*housing_price(time_period)*housing_size(housing_status_index_1)
                                    
            housing_depreciation_expenditures=&
                housing_depreciation_rate*housing_price(time_period-solve_transition_dynamics)*housing_size(housing_status_index_1)
                        
            cost_of_mortgage=-min(financial_grid(financial_index_1),0.d0)*&
                housing_price(time_period)*housing_size(housing_status_index_1)*&
                (1+mortgage_interest_rate(time_period)+pay_mortgage_insurance_1*mortgage_insurance_premium)
            
            assets_1=max(housing_price(time_period)*housing_size(housing_status_index_1)*&
                (1-cost_of_selling-property_tax(time_period)-housing_depreciation_rate+&
                min(financial_grid(financial_index_1),0.d0)*(1+mortgage_interest_rate(time_period)))+&
                max(financial_grid(financial_index_1),0.d0),0.d0)
    
            if (assets_1<threshold_for_food_stamps_as_perc_of_average_net_wealth*avg_net_wealth_to_use_1) then
                                
                food_stamps_recieved=snap_benefit(actual_household_size(age_index),&
                    gross_wage_income+risk_free_rate(time_period)*max(financial_grid(financial_index_1),0.d0),&
                    avg_income_to_use_1)
                                            
            end if
            
            if (provide_vouchers==1) then
            
                if (future_housing_status_index_1>lowest_housing_grid_point) then
            
                    call calculate_housing_voucher(housing_voucher_recieved,gross_wage_income,rent_spending,&
                        homeowner_spending,is_current_owner,choose_to_rent,time_period)
                        
                end if
                                        
            end if
                                                                                                
        end if
                                                                                                               
        ! THE NEWBORN'S TRANSFER. Received once, at age 1, and only when the
        ! endowment is being delivered as a transfer rather than as a stock; see
        ! the block beside initial_endowment. employment_index and age_index are
        ! module globals fixed by the serial loops enclosing every OpenMP region
        ! that reaches here -- employment_index appears in the shared clause at
        ! 18047, not a private one -- so reading them is safe.
        newborn_transfer_1=0.d0

        if ((endowment_is_a_transfer==1) .AND. (age_index==1)) then

            newborn_transfer_1=fraction_with_positive_wealth(employment_index)*&
                relative_endowments(employment_index)*max_initial_endowment

        end if

        after_tax_wealth_net_of_expenses=gross_wage_income-wage_income_tax_paid+&
            investment_income-investment_income_tax_paid+total_household_wealth-& 
            property_taxes_paid-housing_depreciation_expenditures-rent_spending-cost_of_mortgage-&
            cost_of_housing+lump_sum_transfer_given-origination_cost_1-prepayment_penalty_1-&
            fixed_cost_to_moving_1+bequest_1+food_stamps_recieved+housing_voucher_recieved+&
            housing_voucher_recieved_2+newborn_transfer_1
            
        ! A NEGATIVE POSITION MEANS TWO DIFFERENT THINGS AND THIS LINE USED TO
        ! ASSUME ONLY ONE. For an OWNER, financial_grid<0 is mortgage debt
        ! denominated against the house, so it is right that it comes in scaled
        ! by housing_price*housing_size. For a RENTER with unsecured borrowing
        ! there is no house to denominate it against: the grid is built as
        ! -unsecured_borrowing_limit*<average labour income>, an absolute
        ! amount, and the fifteen sites that charge unsecured_borrowing_rate all
        ! read it that way. Scaled by a dwelling, a renter's borrowing was
        ! priced by the unit they chose -- almost free on the street, expensive
        ! in the largest rental -- instead of by the interest rate.
        !
        ! choose_to_rent is already the tenure of the period the position is
        ! carried INTO, which is the tenure that decides what the debt is.
        !
        ! WITH BORROWING OFF THIS IS A NO-OP, provably: renter_floor_by_age puts
        ! a renter's floor at the zero index, so min(financial_grid,0) is zero
        ! and both branches vanish. That is what keeps the archive valid across
        ! the change.
        consumption_choice=(after_tax_wealth_net_of_expenses-&
            max(financial_grid(future_financial_index_1),0.d0)-&
            (1-choose_to_rent)*min(financial_grid(future_financial_index_1),0.d0)*&
            housing_price(time_period)*housing_size(future_housing_status_index_1)-&
            choose_to_rent*min(financial_grid(future_financial_index_1),0.d0))/(1+consumption_tax)

        total_consumption_choice=consumption_choice
                        
        frac_spent_on_addiction=0
                    
        call calculate_addiction_spending(consumption_choice,food_stamps_recieved,&
            addiction_index_1,housing_size(future_housing_status_index_1))
                                
    end subroutine
    
    subroutine calculate_addiction_spending(consumption_1,food_stamps_1,addiction_index_1,housing_size_1)
    
        use Global_Vars
        
        implicit none
        
        real(8), intent(in) :: consumption_1,food_stamps_1,housing_size_1
        real(8) :: total_consumption_choice_1,total_consumption_choice_2
        integer, intent(in) :: addiction_index_1
        
        ! TREATMENT NO LONGER FORBIDS USE, and the reason is that forbidding it
        ! left bar_tau^u unidentified.
        !
        ! It used to set frac_spent_on_addiction to zero, so taking treatment
        ! meant giving up the drug for the period. The comment that stood here
        ! warned that without the abstention treatment is a free multiplier on
        ! recovery that every household takes and no utility cost can undo. The
        ! run says the opposite happened: at a utility cost of ZERO take up was
        ! 0.0128 against a target of 0.245, and bar_tau^u sat on its floor with
        ! nowhere to go. The abstention is worth more than the multiplier, so the
        ! cost could only bind from below, where it has no room.
        !
        ! With use allowed, treatment is the recovery multiplier and bar_tau^u is
        ! its only price. At zero cost every household carrying the disorder
        ! takes it, and the bracket raises the cost until take up falls to the
        ! target: the parameter is identified FROM ABOVE, which is the side it
        ! has room on.

        if ((addiction_index_1>=1) .AND. (consumption_choice>0) .AND. (relative_share_of_addiction>0)) then
                                
            total_consumption_choice_1=consumption_1

            ! THE COST OF TREATMENT, CHARGED HERE AND NOWHERE ELSE.
            !
            ! This routine is entered only when addiction_index_1 >= 1, and
            ! treatment is open only when addiction_index == 1, so the
            ! households that can be in treatment are exactly the households
            ! that reach this line, on both of its call paths. consumption_1 is
            ! intent(in) and is read exactly once, here, so one charge covers
            ! the budget completely -- which is the point, after a night in
            ! which four separate quantities were found written out in several
            ! places with one copy differing.
            !
            ! A household that cannot pay ends with consumption at the floor and
            ! flow utility at minus infinity, so it never chooses treatment.
            ! That is the mechanism and not a numerical guard: treatment it
            ! cannot afford is treatment it does not take.
            if ((include_treatment==1) .AND. (treatment_choice_now==1)) then

                total_consumption_choice_1=max(total_consumption_choice_1-&
                    money_cost_of_treatment,10.d0**(-10))

            end if

            total_consumption_choice_2=total_consumption_choice_1
                    
            call optimize_frac_spent_on_addiciton&
                (total_consumption_choice_2,consumption_choice,frac_spent_on_addiction,&
                price_of_addictive_good,food_stamps_1,housing_size_1,addiction_index_1)
                          
            if (consumption_choice<food_stamps_1/(1+consumption_tax))  then
            
                if ((unemployment_index<=threshold_addiction_index) .AND. &
                   (addiction_index_1==2)) then
                   
                    ! Checks if there is enough resources available for drug consumption at the high level
                    if ((total_consumption_choice_1-food_stamps_1/(1+consumption_tax))>=&
                        ((1-is_counterfactual)*model_drug_threshold(1)+&
                        is_counterfactual*drug_threshold_calibrated)*(1+0.00000001d0)) then
                        
                        consumption_choice=food_stamps_1/(1+consumption_tax)
                        total_consumption_choice=total_consumption_choice_1
                        frac_spent_on_addiction=min(max(1-consumption_choice/total_consumption_choice,0.d0),1.d0)
                        
                        if (total_consumption_choice<consumption_choice) then
                        
        !                    write(*,*) "mistake"
                            
                            consumption_choice=0
                            total_consumption_choice=0
                            frac_spent_on_addiction=0
                                                 
                        end if
                    
                    ! if there arent enough resources, then I make it impossible to be in this choice
                    else
                    
                        consumption_choice=0
                        total_consumption_choice=total_consumption_choice_1
                        frac_spent_on_addiction=min(max(1-consumption_choice/total_consumption_choice,0.d0),1.d0)
                        
                    end if
        
                else
                            
                    consumption_choice=food_stamps_1/(1+consumption_tax)
                    total_consumption_choice=total_consumption_choice_1
                    frac_spent_on_addiction=min(max(1-consumption_choice/total_consumption_choice,0.d0),1.d0)
                    
                    if (total_consumption_choice<consumption_choice) then
                        
    !                    write(*,*) "mistake"
                        
                        consumption_choice=0
                        total_consumption_choice=0
                        frac_spent_on_addiction=0
                                             
                    end if
                    
                end if
                
            else
        
                total_consumption_choice=total_consumption_choice_2
                
            end if
            
        else
        
            frac_spent_on_addiction=0
                
        end if
        
        if (abs(consumption_choice-total_consumption_choice*(1-frac_spent_on_addiction))>10.d0**(-8)) then
        
            write(*,*) "wrong"
            write(*,*) "consumption_choice=", consumption_choice
            write(*,*) "total_consumption_choice=", total_consumption_choice
            write(*,*) "frac_spent_on_addiction=", frac_spent_on_addiction
        
        end if
        
    end subroutine
    
    subroutine optimize_frac_spent_on_addiciton(total_consumption_choice_1,consumption_choice_1,&
        frac_spent_on_addiction_1,price_of_addictive_good_1,food_stamps_1,housing_size_1,addiction_index_1)
    
        use Global_Vars
        
        real(8), intent(inout) :: consumption_choice_1,frac_spent_on_addiction_1,total_consumption_choice_1
        real(8) :: x_0,x_1,x_2,MU_1,MU_2,distance_1,stopping_rule_1=10.d0**(-5),total_consumption_choice_3,&
            food_stamps_value,consumption_1,addiction_1,test_1,drug_consumption_1
        real(8), intent(in) :: price_of_addictive_good_1,food_stamps_1,housing_size_1
        integer, intent(in) :: addiction_index_1
        integer :: loop_count_1,max_loop_count
                
        test_1=total_consumption_choice_1
        total_consumption_choice_3=total_consumption_choice_1

        food_stamps_value=food_stamps_1/(1+consumption_tax)
        
        MU_1=0
        MU_2=0
        
        x_0=0
        x_2=1
        x_1=(x_0+x_2)/2
        
        distance_1=1
        loop_count_1=1
        max_loop_count=1000
        
        if (include_probability_of_becoming_addicted==1) then
        
            if ((change_utility_for_addicts==0) .AND. (size_of_penalty==0)) then
        
                ! Everything has to agree now, shifters included: b does not
                ! depend on the disorder, so addiction_scalar_2 equals
                ! addiction_scalar_1 by construction and the weights match too.
                if ((relative_share_of_consumption_2 .NE. relative_share_of_consumption_1) .OR. &
                   (relative_share_of_housing_1 .NE. relative_share_of_housing_2)) then
                
                    write(*,*) "strange"
                    write(*,*) "relative_share_of_consumption_2=", relative_share_of_consumption_2
                    write(*,*) "relative_share_of_consumption_1", relative_share_of_consumption_1
                    write(*,*) "addiction_scalar_2=", addiction_scalar_2
                    write(*,*) "addiction_scalar_1=", addiction_scalar_1
                    
                end if
                
            end if
        
            if (unemployment_index>threshold_addiction_index) then
            
                consumption_choice_1=(relative_share_of_consumption_2*&
                    (price_of_addictive_good_1*b_shifter(1,housing_size_1)+total_consumption_choice_3))/&
                    (relative_share_of_consumption_2+relative_share_of_addiction_2)
                    
            else
            
                consumption_choice_1=(relative_share_of_consumption_1*&
                    (price_of_addictive_good_1*b_shifter(0,housing_size_1)+total_consumption_choice_3))/&
                    (relative_share_of_consumption_1+relative_share_of_addiction_1)
                                
            end if
            
            consumption_choice_1=min(consumption_choice_1,total_consumption_choice_3)

            frac_spent_on_addiction_1=1-consumption_choice_1/total_consumption_choice_3
            total_consumption_choice_1=total_consumption_choice_3

            ! THE RISK TERM, and this is where the hazard stops being decoration.
            !
            ! The closed form above is the static Cobb-Douglas split: it sets the
            ! marginal utility of consumption equal to the marginal utility of
            ! the drug and knows nothing about next period. Leave it alone and
            ! pi_d(v) rises with v in the transition while the household picks v
            ! as though it did not, which is the flat hazard wearing a different
            ! hat.
            !
            ! With the disorder in play the household solves
            !
            !   max  u(c,h,b+v) + (1-pi_d(v)) EV_clean + pi_d(v) EV_disorder
            !   s.t. c + p v = C
            !
            ! whose first order condition adds one term to the static one:
            !
            !   G [ w_v/(b+v) - p w_c/c ] = lambda exp(-lambda v) (EV_clean - EV_disorder)
            !
            ! where G is flow utility times (1-sigma), the common factor the
            ! static condition was free to cancel and this one is not, since the
            ! right hand side is in utils and the left is a ratio.
            !
            ! THE BRACKET IS THE CLOSED FORM ITSELF, which is what makes this
            ! cheap and safe. Risk can only push the household towards LESS of
            ! the drug, so the solution lies between the static split and
            ! abstention. At the static split the left side is zero and the right
            ! is positive, so the household wants more consumption; at the corner
            ! where it buys nothing, b is of order 1e-8 and w_v/(b+v) swamps
            ! everything, so it wants less. One sign change, one bisection, and
            ! the objective rises then falls across it, so the root is the
            ! maximum rather than just a stationary point.
            if ((smooth_addiction_hazard==1) .AND. (drug_risk_active==1) .AND. &
                (drug_risk_value>0) .AND. (total_consumption_choice_3>0) .AND. &
                (frac_spent_on_addiction_1>0)) then

                call solve_drug_split_with_risk(total_consumption_choice_3,&
                    consumption_choice_1,frac_spent_on_addiction_1,&
                    price_of_addictive_good_1,housing_size_1,addiction_index_1)

                total_consumption_choice_1=total_consumption_choice_3

            end if

            drug_consumption_1=frac_spent_on_addiction_1*total_consumption_choice_3

            ! The cutoff only exists while the light and heavy regimes do. With
            ! the split collapsed there is one use decision and no v_bar to clip
            ! against, so clipping here would silently cap every experimenter's
            ! drug spending at the retired threshold.
            if ((unemployment_index<=threshold_addiction_index) .AND. &
                (include_heavy_vs_light_use_transitions==1)) then
            
                if (addiction_index_1==1) then               
                    
                    drug_consumption_1=min(drug_consumption_1,&
                        (1-is_counterfactual)*model_drug_threshold(1)+&
                        is_counterfactual*drug_threshold_calibrated)
                        
                    consumption_choice_1=total_consumption_choice_3-drug_consumption_1
                    
                    frac_spent_on_addiction_1=1-consumption_choice_1/total_consumption_choice_3
                
                elseif (addiction_index_1==2) then
                
                    drug_consumption_1=max(drug_consumption_1,&
                        ((1-is_counterfactual)*model_drug_threshold(1)+&
                        is_counterfactual*drug_threshold_calibrated)*(1+0.00000001d0))
                        
                    consumption_choice_1=total_consumption_choice_3-drug_consumption_1
                    
                    frac_spent_on_addiction_1=1-consumption_choice_1/total_consumption_choice_3
                
                end if
                
            end if
        
        else
        
            do while ((distance_1>stopping_rule_1) .AND. (loop_count_1<max_loop_count))
                        
                if (loop_count_1<max_loop_count) then

                    consumption_1=x_1*total_consumption_choice_3
                    addiction_1=(1-x_1)*total_consumption_choice_3
                                    
                    if (use_cobb_douglas==1) then
                    
                        MU_1=(1-relative_share_of_addiction)*(1/price_of_addictive_good_1)*&
                            (((housing_size_1)**(relative_share_of_housing))*&
                            ((consumption_1)**(1-relative_share_of_housing)))**(-risk_aversion_consumption)*&
                            (1-relative_share_of_housing)*(consumption_1)**(-relative_share_of_housing)*&
                            ((housing_size_1)**(relative_share_of_housing))
                            
                        MU_2=relative_share_of_addiction*(addiction_1/price_of_addictive_good_1)**(-risk_aversion_consumption)
                                                
                    elseif (use_cobb_douglas_2==1) then
                    
                        MU_1=(1/price_of_addictive_good_1)*&
                            (relative_share_of_consumption_2*consumption_1**(relative_share_of_consumption_2-1))*&
                            ((b_shifter(0,housing_size_1)+(addiction_1/price_of_addictive_good_1))**relative_share_of_addiction)
                            
                        MU_2=(relative_share_of_addiction*(b_shifter(0,housing_size_1)+(addiction_1/price_of_addictive_good_1))**&
                            (relative_share_of_addiction-1))*(consumption_1**relative_share_of_consumption_2)
                            
                    elseif (include_probability_of_becoming_addicted==1) then
                    
                        if (unemployment_index>threshold_addiction_index) then
                    
                            MU_1=price_of_addictive_good_1*(relative_share_of_consumption_2*consumption_1**(-1))
                                
                            MU_2=(relative_share_of_addiction_2*(b_shifter(1,housing_size_1)+addiction_1/price_of_addictive_good_1)**(-1))
                                
                        else
                        
                            MU_1=price_of_addictive_good_1*(relative_share_of_consumption_1*consumption_1**(-1))
                                
                            MU_2=(relative_share_of_addiction_1*(b_shifter(0,housing_size_1)+addiction_1/price_of_addictive_good_1)**(-1))
                        
                        end if
                                
                    else
                    
                        MU_1=(1/price_of_addictive_good_1)*&
                            (power_1*relative_share_of_consumption_2*(consumption_1/sqrt_household_size(age_index))**(power_1-1))
                            
                        MU_2=(power_3*relative_share_of_addiction*((addiction_1/price_of_addictive_good_1)/&
                            sqrt_household_size(age_index))**(power_3-1))
                            
                    end if
                    
                    if (total_consumption_choice_3>=0) then
                
                        ! need more consumption, make the lower bound higher (update up)
                        if (MU_1>MU_2) then
                        
                            x_0=x_1
                            x_1=(x_1+x_2)/2
                            
                        ! need more addiction, make the upper bound lower (update down)
                        else
                        
                            x_2=x_1
                            x_1=(x_1+x_0)/2
                        
                        end if
                                            
                    end if
                        
                    distance_1=abs(x_0-x_2)
                    
                    loop_count_1=loop_count_1+1
                    
                end if
                        
            end do
            
            frac_spent_on_addiction_1=(1-x_1)
            consumption_choice_1=x_1*total_consumption_choice_3
            total_consumption_choice_1=total_consumption_choice_3
            
            if ((distance_1>stopping_rule_1) .OR. ((abs(MU_1-MU_2)>10.d0**(-1)) .AND. (abs(x_1-1)>0.0001)) .OR. &
                ((abs(MU_1-MU_2)>10.d0**(-1)) .AND. (abs(x_1-0)<0.0001))) then
        
    !            write(*,*) "addiction"
    !            write(*,*) "distance_1=", distance_1
    !            write(*,*) "x_1=", x_1
    !            write(*,*) "MU_1=", MU_1
    !            write(*,*) "MU_2=", MU_2
    !            write(*,*) "total_consumption_choice_1=", total_consumption_choice_1
    !            write(*,*) "consumption_1=", consumption_choice_1
    !            write(*,*) "food_stamps_value=", food_stamps_value
    !            write(*,*) "frac_spent_on_addiction_1=", frac_spent_on_addiction_1
    !            write(*,*) "loop_count_1=", loop_count_1
            
            end if
                
        end if
                                            
        if (abs(consumption_choice_1-total_consumption_choice_1*(1-frac_spent_on_addiction_1))>10.d0**(-8)) then
        
            write(*,*) "wrong_1"
            write(*,*) "consumption_choice=", consumption_choice_1
            write(*,*) "total_consumption_choice=", total_consumption_choice_1
            write(*,*) "frac_spent_on_addiction=", frac_spent_on_addiction_1
        
        end if

    end subroutine

    subroutine solve_drug_split_with_risk(total_consumption_choice_1,consumption_choice_1,&
        frac_spent_on_addiction_1,price_of_addictive_good_1,housing_size_1,addiction_index_1)

        ! The drug quantity that internalises the hazard. Called only from
        ! optimize_frac_spent_on_addiciton, and only for a household that does
        ! not yet carry the disorder and has chosen to use; see the comment
        ! there for the first order condition and why the static split is the
        ! lower end of the bracket.
        !
        ! The level of flow utility comes from calculate_flow_utility rather than
        ! being written out again here. That is the same discipline b_shifter
        ! imposes on the shifter: the marginal condition and the utility it is
        ! the margin of cannot be allowed to drift apart, and writing the
        ! Cobb-Douglas out a second time is exactly how they would.

        use Global_Vars

        implicit none

        real(8), intent(in) :: total_consumption_choice_1,price_of_addictive_good_1,housing_size_1
        real(8), intent(inout) :: consumption_choice_1,frac_spent_on_addiction_1
        integer, intent(in) :: addiction_index_1

        real(8) :: x_lo,x_hi,x_mid,cons_x_1,v_1,b_1,utility_1,scale_1,marginal_1,share_c_1,share_v_1
        real(8) :: stopping_rule_1=10.d0**(-6)
        integer :: is_sud_1,loop_1,max_loop_1

        is_sud_1=0

        if (unemployment_index>threshold_addiction_index) then

            is_sud_1=1

        end if

        if (is_sud_1==1) then

            share_c_1=relative_share_of_consumption_2
            share_v_1=relative_share_of_addiction_2

        else

            share_c_1=relative_share_of_consumption_1
            share_v_1=relative_share_of_addiction_1

        end if

        b_1=b_shifter(is_sud_1,housing_size_1)

        x_lo=consumption_choice_1/total_consumption_choice_1
        x_hi=1

        if (x_lo>=1-stopping_rule_1) then

            return

        end if

        max_loop_1=200
        loop_1=1

        do while (((x_hi-x_lo)>stopping_rule_1) .AND. (loop_1<max_loop_1))

            x_mid=(x_lo+x_hi)/2

            cons_x_1=x_mid*total_consumption_choice_1
            v_1=((1-x_mid)*total_consumption_choice_1)/price_of_addictive_good_1

            call calculate_flow_utility(0,drug_risk_housing_index,housing_size_1,&
                1-x_mid,total_consumption_choice_1,cons_x_1,drug_risk_ownership,&
                addiction_index_1,utility_1,0)

            ! Flow utility is the Cobb-Douglas aggregate over (1-sigma), so the
            ! aggregate itself is that times (1-sigma), and the two marginal
            ! utilities are the aggregate times the share over its argument.
            !
            ! THE AGGREGATE, NOT THE LEVEL. utility_1 carries the value of life
            ! and bar_tau^u on top of the aggregate, and multiplying those by
            ! (1-sigma) does not recover a marginal utility of anything; with
            ! sigma above one it returns a large negative number and inverts the
            ! whole condition. flow_utility_goods_only is the same call's
            ! aggregate, recorded before either term is appended.
            scale_1=(1-risk_aversion_consumption)*flow_utility_goods_only

            marginal_1=scale_1*(share_v_1/(b_1+v_1))-&
                scale_1*(price_of_addictive_good_1*share_c_1/cons_x_1)-&
                addiction_transition_slope(is_sud_1,addiction_index_1,v_1)*drug_risk_value

            ! Positive means the drug is still worth more at the margin than the
            ! consumption it displaces and the risk it carries, so buy more of it
            ! by moving the upper bound on the consumption share down.
            if (marginal_1>0) then

                x_hi=x_mid

            else

                x_lo=x_mid

            end if

            loop_1=loop_1+1

        end do

        consumption_choice_1=min(((x_lo+x_hi)/2)*total_consumption_choice_1,total_consumption_choice_1)

        frac_spent_on_addiction_1=min(max(1-consumption_choice_1/total_consumption_choice_1,0.d0),1.d0)

        consumption_choice_1=total_consumption_choice_1*(1-frac_spent_on_addiction_1)

    end subroutine

    subroutine internal_computations&
        (value_function_1,labor_supply_1,gross_wage_income_1,&
        fin_index_1,ownership_status_index_1,space_lived_in_index_1,housing_status_index_1,&
        years_of_amortization_1,wage_income_tax_paid_2,mortgage_interest_deductions_2,&
        financial_index,time_period,after_tax_wealth_net_of_expenses_1,max_future_mortgage_index_2,&
        frac_spent_on_addiction_2,future_addiction_index_1)
    
        use Global_Vars
        
        implicit none
        
        
        integer :: financial_index,fin_index_1,ownership_status_index_1,can_purchase_new_house,years_of_amortization_1,&
            housing_status_index_1,space_lived_in_index_1,time_period,adjust_budget,can_consume_drugs,&
            become_renter,smallest_house,second_smallest_house,max_future_mortgage_index_2,owner_to_owner_stay_2,&
            owner_to_owner_move_2,renter_to_owner_2,check_GDS_2,proceed_2,track_housing_1,low_quality_market,&
            future_housing_status_index_to_use,is_homeless_1,x_1,is_current_owner_1,future_addiction_index_1,voucher_index_1,&
            current_addiction_index_1,loop_over_addiction_1,check_1,has_opportunity_1,first_voucher_index,second_voucher_index
            
        real(8) :: value_function_1,after_tax_wealth_net_of_expenses_1,spending_on_housing_1,&
            after_tax_wealth_net_of_expenses_1_copy,rent_spent_1,rent_spent_2,space_lived_in_optimal_1,&
            after_tax_wealth_net_of_expenses_1_optimal,max_mortgage_payments_as_fraction_of_income_1,&
            gross_wage_income_1,wage_income_tax_paid_2,wage_income_tax_paid_1,optimal_wage_income_tax_paid_1,&
            labor_supply_1,optimal_labor_supply_1,optimal_mortgage_interest_deductions_1,&
            mortgage_interest_deductions_2,mortgage_interest_deductions_1,investment_income_tax_paid_1_optimal,&
            investment_income_tax_paid_1,assets_1,optimal_gross_wage_income_1,labor_supply_2,wealth_1,&
            avg_income_to_use_1,avg_income_to_use_2,food_stamps_recieved_1,housing_voucher_recieved_1,avg_net_wealth_to_use_1,&
            frac_spent_on_addiction_2,homeowner_spending_1,renter_spending_1,consumption_choice_1,total_consumption_choice_1,&
            LTV_1,optimal_frac_spent_on_addiction,housing_voucher_recieved_3,income_to_use,bequest_1
            
        if (inheritance_function_of_productivity==1) then
                        
            bequest_1=employment_grid(age_index,employment_index)*inheritance_amount(age_index)+&
                            newborn_age_transfer(age_index)
            
        else
            
            call calculate_bequest_amount(age_index,bequest_1,employment_index)
            
        end if

        current_addiction_index_1=0
        loop_over_addiction_1=0
            
        if (unemployment_index>threshold_addiction_index) then
        
            future_addiction_index_1=1        
            current_addiction_index_1=1 
            loop_over_addiction_1=1
            
        elseif ((future_addiction_index_1>=1) .AND. &
            (include_probability_of_becoming_addicted==1)) then
            
            loop_over_addiction_1=1
        
        end if
        
        if ((housing_status_index_1>second_lowest_housing_grid_point) .OR. &
            (have_two_rental_markets==0)) then
            
            low_quality_market=0
            
        else
        
            low_quality_market=1
        
        end if         
                    
        avg_income_to_use_1=is_counterfactual*average_labor_income_calibrated+&
            (1-is_counterfactual)*model_average_labour_income(time_period)
                                            
        avg_income_to_use_2=is_counterfactual*average_labor_income_by_employment_calibrated(employment_index)+&
            (1-is_counterfactual)*model_average_labour_income_by_employment(time_period,employment_index)
            
        avg_net_wealth_to_use_1=is_counterfactual*average_net_wealth_calibrated+&
            (1-is_counterfactual)*model_average_net_wealth(time_period)
                                            
        track_housing_1=1
            
        if (ownership_status_index_1==0) then
        
            if (track_renters_housing==0) then
                    
                track_housing_1=0
            
            end if
            
        end if
        
        if (track_housing_1==0) then
            
            if (housing_status_index_1<=second_lowest_housing_grid_point) then
    
                future_housing_status_index_to_use=housing_status_index_1
                
            else
                
                future_housing_status_index_to_use=0
                
            end if
            
        else
        
            future_housing_status_index_to_use=housing_status_index_1
        
        end if
        
        is_homeless_1=1
        
        if (future_housing_status_index_to_use==lowest_housing_grid_point) then
        
            is_homeless_1=2
            
        end if
        
        call compute_voucher_index_1(is_homeless_1,voucher_index_1)              
         
        proceed_2=1
        
        optimal_gross_wage_income_1=gross_wage_income_1
                                
        owner_to_owner_stay_2=0
            
        if ((ownership_status_index_1==1) .AND. (years_left_on_mortgage_index==2) .AND. &
            (housing_status_index_1==housing_status_index)) then
        
            owner_to_owner_stay_2=1
                    
        end if
        
        owner_to_owner_move_2=0
        
        if ((ownership_status_index_1==1) .AND. (years_left_on_mortgage_index==2) .AND. &
            (housing_status_index_1 .NE. housing_status_index)) then
        
            owner_to_owner_move_2=1
                    
        end if
        
        renter_to_owner_2=0
        
        if ((ownership_status_index_1==1) .AND. (years_left_on_mortgage_index==1)) then
        
            renter_to_owner_2=1
                    
        end if
        
        if (years_left_on_mortgage_index>1) then
        
            is_current_owner_1=1
            
        else
        
            is_current_owner_1=0
            
        end if
                    
        become_renter=0
        
        if (years_of_amortization_1<=1) then
        
            become_renter=1
            
        end if
        
        optimal_frac_spent_on_addiction=frac_spent_on_addiction_2
                    
        consumption_choice_1=&
            (after_tax_wealth_net_of_expenses_1-max(financial_grid(fin_index_1),0.d0)-&
            min(financial_grid(fin_index_1),0.d0)*housing_price(time_period)*housing_size(housing_status_index_1))/&
            (1+consumption_tax)
                                                           
        space_lived_in_optimal_1=housing_size(space_lived_in_index_1)
        
        after_tax_wealth_net_of_expenses_1_optimal=after_tax_wealth_net_of_expenses_1
                                                
        investment_income_tax_paid_1_optimal=&
            investment_income_tax*max(financial_grid(financial_index),0.d0)*risk_free_rate(time_period)
                   
        rent_spent_2=(1-ownership_status_index_1)*&
            rent(time_period,low_quality_market)*housing_size(housing_status_index_1)
        
        if (housing_status_index_1==lowest_housing_grid_point) then
            
            rent_spent_2=0
                
        end if
                                                            
        optimal_labor_supply_1=labor_supply_1
        labor_supply_2=labor_supply_1
                                                    
        optimal_wage_income_tax_paid_1=wage_income_tax_paid_2
                    
        optimal_mortgage_interest_deductions_1=mortgage_interest_deductions_2
        mortgage_interest_deductions_1=mortgage_interest_deductions_2
                                                                                                                   
        ! Built here, on the index actually being recorded, so the lottery cannot
        ! drift out of step with the policy. The utility vectors still hold this
        ! state's values at this point, since this routine is called straight
        ! after that state's a' search. Both outputs default to the degenerate
        ! case, frac zero on the chosen point, which is what this used to be
        ! hardcoded to.
        call compute_asset_lottery(fin_index_1,negative_financial_grid_size,financial_grid_size,&
            value_function_1)


        frac_mov_optimal_1(years_left_on_mortgage_index)%&
            vector_transition_real(time_period,age_index,financial_index,&
            unemployment_index,employment_index,housing_status_index,voucher_index)=&
            interp_frac_1

        fin_index_frac_mov_to_optimal(years_left_on_mortgage_index)%&
            vector_transition_integer(time_period,age_index,financial_index,&
            unemployment_index,employment_index,housing_status_index,voucher_index)=&
            interp_neighbour_1
                    
        if (in_retirement==1) then
        
            if (age_index<=life_span) then
        
                if ((owner_to_owner_stay_2==1) .OR. (owner_to_owner_move_2==1) .OR. (renter_to_owner_2==1)) then
                
                    if (fin_index_1<negative_financial_grid_size) then
            
                        dis_prev_index_fin=financial_grid(fin_index_1)-&
                            financial_grid(max(fin_index_1-1,max_future_mortgage_index_2))
                            
                    else
                    
                        dis_prev_index_fin=financial_grid(fin_index_1)-&
                            financial_grid(max(fin_index_1-1,negative_financial_grid_size))
                    
                    end if
                        
                else
                
                    dis_prev_index_fin=financial_grid(fin_index_1)-&
                        financial_grid(max(fin_index_1-1,negative_financial_grid_size))
                
                end if
                
            else
            
                dis_prev_index_fin=financial_grid(fin_index_1)-financial_grid(max(fin_index_1-1,negative_financial_grid_size))
            
            end if
            
        else
        
            if (fin_index_1<negative_financial_grid_size) then
            
                dis_prev_index_fin=financial_grid(fin_index_1)-financial_grid(max(fin_index_1-1,max_future_mortgage_index_2))
            
            else
        
                dis_prev_index_fin=financial_grid(fin_index_1)-financial_grid(max(fin_index_1-1,&
                    can_get_mortgage*(ownership_status_index_1*1+(1-ownership_status_index_1)*negative_financial_grid_size)+&
                    (1-can_get_mortgage)*negative_financial_grid_size))
                    
            end if
        
        end if
        
        if ((owner_to_owner_stay_2==1) .OR. (owner_to_owner_move_2==1) .OR. (renter_to_owner_2==1)) then
        
            if (fin_index_1<negative_financial_grid_size) then
            
                dis_next_index_fin=financial_grid(min(fin_index_1+1,negative_financial_grid_size))-financial_grid(fin_index_1)
            
            else
                                                                         
                dis_next_index_fin=financial_grid(min(fin_index_1+1,financial_grid_size))-financial_grid(fin_index_1)
                
            end if
            
        else
        
            dis_next_index_fin=financial_grid(min(fin_index_1+1,financial_grid_size))-financial_grid(fin_index_1)
        
        end if
                                                        
        slope_of_financial_internal=(dis_prev_index_fin+dis_next_index_fin)/(fin_num_of_internal-1)
                                                    
        after_tax_wealth_net_of_expenses_1_copy=after_tax_wealth_net_of_expenses_1
                                                                
        internal_loop_1: do future_financial_index=1,fin_num_of_internal-2
                        
            if (in_retirement==1) then
    
                if (age_index<=life_span) then
            
                    if ((owner_to_owner_stay_2==1) .OR. (owner_to_owner_move_2==1) .OR. (renter_to_owner_2==1)) then
                    
                        if (fin_index_1<negative_financial_grid_size) then
                        
                            financial_internal=(financial_grid(max(fin_index_1-1,max_future_mortgage_index_2))+&
                                slope_of_financial_internal*future_financial_index)*&
                                housing_price(time_period)*housing_size(housing_status_index_1)
                                
                            LTV_1=financial_grid(max(fin_index_1-1,max_future_mortgage_index_2))+&
                                slope_of_financial_internal*future_financial_index
                        
                        else
                
                            financial_internal=financial_grid(max(fin_index_1-1,negative_financial_grid_size))+&
                                slope_of_financial_internal*future_financial_index
                                
                            LTV_1=financial_internal
                                
                        end if
                            
                    else
                    
                        financial_internal=financial_grid(max(fin_index_1-1,negative_financial_grid_size))+&
                            slope_of_financial_internal*future_financial_index
                            
                        LTV_1=financial_internal
                    
                    end if
                    
                else
                
                    financial_internal=financial_grid(max(fin_index_1-1,negative_financial_grid_size))+&
                        slope_of_financial_internal*future_financial_index
                        
                    LTV_1=financial_internal
                
                end if
            
            else
            
                if (fin_index_1<negative_financial_grid_size) then
                
                    financial_internal=(financial_grid(max(fin_index_1-1,&
                        can_get_mortgage*max_future_mortgage_index_2+(1-can_get_mortgage)*negative_financial_grid_size))+&
                        slope_of_financial_internal*future_financial_index)*&
                        housing_price(time_period)*housing_size(housing_status_index_1)
                        
                    LTV_1=(financial_grid(max(fin_index_1-1,&
                        can_get_mortgage*max_future_mortgage_index_2+(1-can_get_mortgage)*negative_financial_grid_size))+&
                        slope_of_financial_internal*future_financial_index)
                
                else
            
                    financial_internal=financial_grid(max(fin_index_1-1,negative_financial_grid_size))+&
                        slope_of_financial_internal*future_financial_index
                        
                    LTV_1=financial_internal
                                                
                end if
            
            end if        
                                    
            space_lived_in_internal=housing_size(space_lived_in_index_1)
                             
            adjust_budget=0
        
            rent_spent_1=rent_spent_2
            mortgage_interest_deductions_1=mortgage_interest_deductions_2
            wage_income_tax_paid_1=wage_income_tax_paid_2
            investment_income_tax_paid_1=&
                investment_income_tax*max(financial_grid(financial_index),0.d0)*risk_free_rate(time_period)
            optimal_gross_wage_income_1=gross_wage_income_1
            labor_supply_2=labor_supply_1
                     
            food_stamps_recieved_1=0
            
            assets_1=2*threshold_for_food_stamps_as_perc_of_average_net_wealth*avg_net_wealth_to_use_1
    
            ! This one is a homeowner turning to renting
            if ((years_left_on_mortgage_index>1) .AND. (ownership_status_index_1==0)) then

                assets_1=max(housing_price(time_period)*housing_size(housing_status_index)*&
                    (1-cost_of_selling-property_tax(time_period)-housing_depreciation_rate)+&
                    min(financial_grid(financial_index),0.d0)*(1+mortgage_interest_rate(time_period))*&
                    housing_price(time_period)*housing_size(housing_status_index)+&
                    max(financial_grid(financial_index),0.d0),0.d0)
        
            ! This one is a renter staying renting
            elseif ((years_left_on_mortgage_index==1) .AND. (ownership_status_index_1==0)) then
            
                assets_1=max(financial_grid(financial_index),0.d0)

            end if

            if (assets_1<threshold_for_food_stamps_as_perc_of_average_net_wealth*avg_net_wealth_to_use_1) then
            
                ! THIS SITE OMITTED food_stamp_taper, so it withdrew the benefit at a
                ! hundred cents on the dollar instead of thirty. The function charges
                ! the statutory rate here as everywhere else.
                food_stamps_recieved_1=snap_benefit(actual_household_size(age_index),&
                    optimal_gross_wage_income_1+risk_free_rate(time_period)*&
                    max(financial_grid(financial_index),0.d0),avg_income_to_use_1)
                                                    
            end if
            
            housing_voucher_recieved_1=0

            if (provide_vouchers==1) then
            
                homeowner_spending_1=0
                renter_spending_1=0
                                
                ! owner to rent not homeless
                if ((ownership_status_index_1==0) .AND. (is_current_owner_1==1) .AND. &
                    (housing_status_index_1 .NE. lowest_housing_grid_point)) then
                
                    homeowner_spending_1=&
                        housing_price(time_period)*housing_size(housing_status_index)*&
                        (property_tax(time_period)+housing_depreciation_rate-&
                        mortgage_interest_rate(time_period)*min(financial_grid(financial_index),0.d0))
                                                
                    renter_spending_1=rent_spent_1
                             
                ! renter to renter not homeless
                elseif ((ownership_status_index_1==0) .AND. (is_current_owner_1==0) .AND. &
                    (housing_status_index_1 .NE. lowest_housing_grid_point)) then
                
                    homeowner_spending_1=0
                    renter_spending_1=rent_spent_1
                               
                ! owner to owner not homless
                elseif ((ownership_status_index_1==1) .AND. (is_current_owner_1==1) .AND. & 
                    (housing_status_index_1 .NE. lowest_housing_grid_point)) then
                
                    homeowner_spending_1=&
                        housing_price(time_period)*housing_size(housing_status_index)*&
                        (property_tax(time_period)+housing_depreciation_rate-&
                        mortgage_interest_rate(time_period)*min(financial_grid(financial_index),0.d0))
                        
                    renter_spending_1=0
                                                        
                end if
                
                if (housing_status_index_1>lowest_housing_grid_point) then
                
                    call calculate_housing_voucher(housing_voucher_recieved_1,&
                        optimal_gross_wage_income_1,&
                        renter_spending_1,homeowner_spending_1,is_current_owner_1,&
                        ownership_status_index_1,time_period)
                        
                end if
                                    
            end if

            housing_voucher_recieved_3=0

            income_to_use=optimal_gross_wage_income_1+(risk_free_rate(time_period)*max(financial_grid(financial_index),0.d0)+unsecured_borrowing_rate*min(financial_grid(financial_index),0.d0))

            if ((income_to_use<threshold_income_vouchers*((1-is_counterfactual)*median_income(time_period)+&
                is_counterfactual*median_income_calibrated)) .AND. (include_vouchers==1)) then

                if ((is_current_owner_1==0) .AND. (ownership_status_index_1==0) .AND. (voucher_index==1)) then

                    call calculate_housing_voucher_2&
                        (housing_voucher_recieved_3,future_addiction_index_1,&
                        income_to_use,rent_spent_1,time_period)
                    
                end if

            end if
            
            after_tax_wealth_net_of_expenses_1=after_tax_wealth_net_of_expenses_1_copy
                             
            after_tax_wealth_net_of_expenses_1=after_tax_wealth_net_of_expenses_1-&
                adjust_budget*(rent_spent_1-rent_spent_2)
                                               
            total_consumption_choice_1=(after_tax_wealth_net_of_expenses_1-financial_internal)/(1+consumption_tax)                
            consumption_choice_1=(1-frac_spent_on_addiction_2)*total_consumption_choice_1
                            
            if ((in_retirement==0) .AND. (fixed_labor_supply_at_benchmark==0) .AND.&
                ((emp_of(unemployment_index)==1))) then
                                            
                x_1=ownership_status_index_1+1
        
                call secant(time_period,financial_index,financial_internal,&
                    space_lived_in_internal,housing_status_index_1,x_1,after_tax_wealth_net_of_expenses_1,&
                    labor_supply_2,optimal_gross_wage_income_1,wage_income_tax_paid_1,&
                    food_stamps_recieved_1,housing_voucher_recieved_1,housing_voucher_recieved_3,&
                    mortgage_interest_deductions_1,proceed_2,future_addiction_index_1)
                    
                consumption_choice_1=consumption_choice
                total_consumption_choice_1=total_consumption_choice
                frac_spent_on_addiction_2=frac_spent_on_addiction

            end if
            
            income_to_use=optimal_gross_wage_income_1+(risk_free_rate(time_period)*max(financial_grid(financial_index),0.d0)+unsecured_borrowing_rate*min(financial_grid(financial_index),0.d0))
            
            call calculate_future_voucher_index_and_opportunity&
                (has_opportunity_1,first_voucher_index,second_voucher_index,&
                time_period,is_current_owner_1,ownership_status_index_1,voucher_index_1,income_to_use)
                                                                                
            can_purchase_new_house=1
            
            if ((LTV_1<financial_grid(fin_index_1)) .AND. (ownership_status_index_1==1)) then
                        
                smallest_house=0
                second_smallest_house=0

                if (housing_price(time_period)*housing_size(housing_status_index_1)<=&
                    fraction_of_average_house_price_data*((1-is_counterfactual)*&
                    model_average_owner_occupied_unit_size(time_period)*housing_price(time_period)+is_counterfactual*&
                    average_owner_occupied_house_size_calibrated*calibrated_stationary_housing_price)) then
                            
                    smallest_house=1
                    
                elseif (housing_price(time_period)*housing_size(housing_status_index_1)<=&
                    2*fraction_of_average_house_price_data*((1-is_counterfactual)*&
                    model_average_owner_occupied_unit_size(time_period)*housing_price(time_period)+is_counterfactual*&
                    average_owner_occupied_house_size_calibrated*calibrated_stationary_housing_price)) then 
                    
                    second_smallest_house=1
                    
                end if
            
                if (-LTV_1<(1-minimum_downpayment+smallest_house*min_down_of_smallest+second_smallest_house+&
                    min_down_of_second_smallest)) then
                    
                    if (-LTV_1>(1-minimum_downpayment)) then
                                                    
                        pay_mortgage_insurance=1
                        max_mortgage_payments_as_fraction_of_income_1=max_debt_to_income_ratio
                            
                    else
                                    
                        pay_mortgage_insurance=0
                        max_mortgage_payments_as_fraction_of_income_1=max_debt_to_income_ratio_below_80
                                        
                    end if
                    
                    check_GDS_2=1
                    
                    if (owner_to_owner_stay_2==1) then
                    
                        if (LTV_1>financial_grid(financial_index)*(1-fraction_to_repay)) then
                        
                            check_GDS_2=0
                            
                        end if                               
                    
                    end if
                    
                    if (check_GDS_2==1) then
                                
                        spending_on_housing_1=&
                            (-min(financial_internal,0.d0)*(pay_mortgage_insurance*mortgage_insurance_premium+&
                            mortgage_interest_rate(time_period)+average_fraction_of_mortgage_repaid))+&
                            housing_size(housing_status_index)*housing_price(time_period)*&
                            (fraction_of_property_taxes_in_GDS*property_tax(time_period)+&
                            include_housing_depreciation_in_housing_costs*housing_depreciation_rate)
                            
                    else
                    
                        spending_on_housing_1=0
                    
                    end if
                                                                                                
                    if ((spending_on_housing_1/(optimal_gross_wage_income_1+&
                        (risk_free_rate(time_period)*max(financial_grid(financial_index),0.d0)+unsecured_borrowing_rate*min(financial_grid(financial_index),0.d0))))<=&
                        max_mortgage_payments_as_fraction_of_income_1) then
                        
                        can_purchase_new_house=1
                        
                    else
                    
                        can_purchase_new_house=0
                    
                    end if
                    
                else
                
                    can_purchase_new_house=0
                    
                end if
            
            end if
            
            can_consume_drugs=1
                        
            if (can_purchase_new_house==1) then
                                                                            
                if ((consumption_choice_1>=(food_stamps_recieved_1/(1+consumption_tax))) .AND. &
                    (consumption_choice_1>0) .AND. (frac_spent_on_addiction_2>=0) .AND. &
                    (total_consumption_choice_1>=consumption_choice_1) .AND. &
                    (can_consume_drugs==1) .AND. (proceed_2==1)) then
                                                                                
                    dis_internal_from_optimal_fin=LTV_1-financial_grid(fin_index_1)
                                                
                    if (dis_internal_from_optimal_fin<0) then
                    
                        if (in_retirement==1) then

                            if (age_index<=life_span) then
                        
                                if ((owner_to_owner_stay_2==1) .OR. (owner_to_owner_move_2==1) .OR. &
                                    (renter_to_owner_2==1)) then
                                                                
                                    fin_index_frac_mov_to=max(fin_index_1-1,max_future_mortgage_index_2)
                                                                                
                                else
                                
                                    fin_index_frac_mov_to=max(fin_index_1-1,negative_financial_grid_size)
                                
                                end if
                                
                            else
                            
                                fin_index_frac_mov_to=max(fin_index_1-1,negative_financial_grid_size)
                            
                            end if
                        
                        else
                        
                            fin_index_frac_mov_to=max(fin_index_1-1,can_get_mortgage*(ownership_status_index_1*1+&
                                (1-ownership_status_index_1)*negative_financial_grid_size)+&
                                (1-can_get_mortgage)*negative_financial_grid_size)
                        
                        end if
                                                                    
                        frac_mov_to_another_cell_1=abs(dis_internal_from_optimal_fin)/dis_prev_index_fin
                                                                                             
                    ! Considering a financial choice above the optimal one found
                    elseif (dis_internal_from_optimal_fin>0) then
                    
                        if ((owner_to_owner_stay_2==1) .OR. (owner_to_owner_move_2==1) .OR. (renter_to_owner_2==1)) then
                        
                            if (fin_index_1<negative_financial_grid_size) then
                            
                                fin_index_frac_mov_to=min(fin_index_1+1,negative_financial_grid_size)
                            
                            else
                    
                                fin_index_frac_mov_to=min(fin_index_1+1,financial_grid_size)
                                
                            end if
                            
                        else
                        
                            fin_index_frac_mov_to=min(fin_index_1+1,financial_grid_size)
                        
                        end if
                                                
                        frac_mov_to_another_cell_1=abs(dis_internal_from_optimal_fin)/dis_next_index_fin
                                                                                                                                                      
                    ! This means we are considering the same financial choice as the optimal choice found
                    else
                                                                        
                        frac_mov_to_another_cell_1=0
                                                            
                        fin_index_frac_mov_to=fin_index_1
                                                                                                            
                    end if
                    
                    financial_index_copy=fin_index_1
                                    
                    financial_index_copy_1=fin_index_frac_mov_to
                                                                    
                    future_leisure_internal=relative_share_of_leisure*&
                        ((max_labor_supply-labor_supply_2)**(1-leisure_curvature))/(1-leisure_curvature)
                                                   
                    call calculate_flow_utility(1,housing_status_index_1,&
                        space_lived_in_internal,frac_spent_on_addiction_2,total_consumption_choice_1,&
                        consumption_choice_1,ownership_status_index_1,future_addiction_index_1,&
                        flow_utility_internal,0)
                                                
                    flow_utility_internal=flow_utility_internal+future_leisure_internal
                                                                                                                    
                    future_utility_internal=0
                    future_bequest_internal=0
                    
                    if (include_bequest_motive==1) then
                                        
                        if ((age_index==life_span) .OR. (have_probablistic_death==1)) then
                            
                            if (ownership_status_index_1==1) then
                            
                                wealth_1=housing_price(time_period)*&
                                    housing_size(housing_status_index_1)*(1-remove_tax_and_depreciation*&
                                    (property_tax(time_period)+housing_depreciation_rate))+&
                                    financial_internal-mortgage_interest_rate(time_period)*&
                                    (-min(financial_internal,0.d0))
                                                  
                            else
                            
                                wealth_1=financial_internal
                                                            
                            end if
                            
                            call calculate_bequest_utility(wealth_1,future_bequest_internal,&
                                is_homeless_1,current_addiction_index_1)
                                                            
                            future_utility_internal=future_utility_internal+future_bequest_internal
                                                                                                                        
                        end if
                        
                    end if
                    
                    do future_addiction_index_2=&
                        (1-loop_over_addiction_1)*future_addiction_index_1+loop_over_addiction_1*0,&
                        (1-loop_over_addiction_1)*future_addiction_index_1+loop_over_addiction_1*include_addiction
                        
                        check_1=0
                            
                        if (future_addiction_index_2==1) then
                        
                            check_1=1
                            
                        end if
                                                                                        
                        do future_unemployment_index=include_addiction*&
                            ((1-check_1)*1+check_1*(threshold_addiction_index+1))+&
                            (1-include_addiction)*(at_least_one_period_before_retirement*&
                            (one_period_before_death*1+(1-one_period_before_death)*unemployment_index)+&
                            (1-at_least_one_period_before_retirement)*1),include_addiction*&
                            ((1-check_1)*threshold_addiction_index+check_1*unemployment_grid_size)+&
                            (1-include_addiction)*(at_least_one_period_before_retirement*&
                            (one_period_before_death*unemployment_grid_size+(1-one_period_before_death)*unemployment_index)+&
                            (1-at_least_one_period_before_retirement)*unemployment_grid_size)
                                                                           
                            do future_employment_index=&
                                at_least_one_period_before_retirement*employment_index+&
                                (1-at_least_one_period_before_retirement)*1,&
                                at_least_one_period_before_retirement*employment_index+&
                                (1-at_least_one_period_before_retirement)*employment_grid_size

                                do future_voucher_index=first_voucher_index,second_voucher_index
                                                                                                                                                                                                                                           
                                    future_utility_internal=future_utility_internal+discount_factor*&
                                        survival_probability(age_index,is_homeless_1,survival_sud_of(current_addiction_index_1,treatment_choice_now),smi_of(unemployment_index))*&
                                        voucher_probabilities(voucher_index,future_voucher_index,&
                                        has_opportunity_1,voucher_index_1)*&
                                        employment_process(age_index,employment_index,future_employment_index)*&
                                        unemployment_process(age_index,unemployment_index,&
                                        future_unemployment_index,is_homeless_1,future_addiction_index_2,employment_index)*&
                                        addiction_transition(current_addiction_index_1,future_addiction_index_2,&
                                        future_addiction_index_1,is_homeless_1,&
                                        frac_spent_on_addiction_2*total_consumption_choice_1/&
                                        price_of_addictive_good,1,treatment_choice_now)*&
                                        (frac_mov_to_another_cell_1*value_function(years_of_amortization_1)%&
                                        vector_transition_real(min(time_period+solve_transition_dynamics,transition_length),&
                                        age_index+1,financial_index_copy_1,future_unemployment_index,future_employment_index,&
                                        future_housing_status_index_to_use,future_voucher_index)+(1-frac_mov_to_another_cell_1)*&
                                        value_function(years_of_amortization_1)%vector_transition_real&
                                        (min(time_period+solve_transition_dynamics,transition_length),age_index+1,&
                                        financial_index_copy,future_unemployment_index,future_employment_index,&
                                        future_housing_status_index_to_use,future_voucher_index))
                                
                                end do
                                                                                                                                                                                                                                                        
                            end do
                            
                        end do
                        
                    end do
                                                                            
                    val_fun_internal=flow_utility_internal+future_utility_internal
                                                
                    if ((val_fun_internal>value_function_1) .AND. (frac_mov_to_another_cell_1>=0) .AND. &
                        (frac_mov_to_another_cell_1<=1)) then
            
                        value_function_1=val_fun_internal
                                                                                                    
                        frac_mov_optimal_1(years_left_on_mortgage_index)%&
                            vector_transition_real(time_period,age_index,financial_index,&
                            unemployment_index,employment_index,housing_status_index,voucher_index)=&
                            frac_mov_to_another_cell_1
                                                        
                        fin_index_frac_mov_to_optimal(years_left_on_mortgage_index)%&
                            vector_transition_integer(time_period,age_index,financial_index,&
                            unemployment_index,employment_index,housing_status_index,voucher_index)=&
                            fin_index_frac_mov_to
                    
                        policy_function_consumption(years_left_on_mortgage_index)%&
                            vector_transition_real(time_period,age_index,financial_index,&
                            unemployment_index,employment_index,housing_status_index,voucher_index)=&
                            consumption_choice_1
                            
                        if (consumption_choice_1<=0) then
                            
                            write(*,*) "internal eror"
                            
                        end if
                            
                        policy_function_total_consumption(years_left_on_mortgage_index)%&
                            vector_transition_real(time_period,age_index,financial_index,&
                            unemployment_index,employment_index,housing_status_index,voucher_index)=&
                            total_consumption_choice_1
                            
                        optimal_frac_spent_on_addiction=frac_spent_on_addiction_2
                                                            
                        optimal_labor_supply_1=labor_supply_2
                                                                                                     
                        space_lived_in_optimal_1=space_lived_in_internal
                                              
                        after_tax_wealth_net_of_expenses_1_optimal=&
                            after_tax_wealth_net_of_expenses_1
                                                                                    
                        optimal_wage_income_tax_paid_1=wage_income_tax_paid_1
                            
                        optimal_mortgage_interest_deductions_1=mortgage_interest_deductions_1
                                                                                                                                                        
                    end if
                                                
                end if
                                                                            
            end if
                                    
        end do internal_loop_1
            
        val_fun_internal=value_function_1
        
        policy_function_space_lived_in_size(years_left_on_mortgage_index)%&
            vector_transition_real(time_period,age_index,financial_index,&
            unemployment_index,employment_index,housing_status_index,voucher_index)=&
            space_lived_in_optimal_1
                    
        optimal_after_tax_wealth_net_of_expenses=after_tax_wealth_net_of_expenses_1_optimal
                        
        policy_function_wage_income_tax_paid(years_left_on_mortgage_index)%&
            vector_transition_real(time_period,age_index,financial_index,&
            unemployment_index,employment_index,housing_status_index,voucher_index)=&
            optimal_wage_income_tax_paid_1
            
        policy_function_mortgage_interest_deductions(years_left_on_mortgage_index)%&
            vector_transition_real(time_period,age_index,financial_index,&
            unemployment_index,employment_index,housing_status_index,voucher_index)=&
            optimal_mortgage_interest_deductions_1
            
        if ((adjust_labor_supply==0) .AND. (is_counterfactual==1)) then
        
        else
            
            policy_function_labor_supply(years_left_on_mortgage_index)%&
                vector_transition_real(time_period,age_index,financial_index,&
                unemployment_index,employment_index,housing_status_index,voucher_index)=&
                optimal_labor_supply_1
                
        end if
        
        policy_function_frac_spent_on_addiction(years_left_on_mortgage_index)%&
            vector_transition_real(time_period,age_index,financial_index,&
            unemployment_index,employment_index,housing_status_index,voucher_index)=optimal_frac_spent_on_addiction
                        
    end subroutine
    
    subroutine check_budget_constraint_clears(time_period,after_tax_wealth_net_of_expenses_1,financial_index)
        
        use Global_Vars
        
        implicit none
        
        integer,intent(in) :: financial_index
        integer, intent(in) :: time_period
        integer :: fin_index_frac_used,financial_index_used,amortization_used,housing_status_index_used
        real(8),intent(in) :: after_tax_wealth_net_of_expenses_1
        real(8) :: frac_used,total_consumption_used,consumption_used,&
            food_stamps_1,assets_1,avg_net_wealth_to_use_1,avg_income_to_use_1,labor_supply_used,income_1,&
            avg_income_to_use_2,checking_criterion,frac_spent_on_addiction_used,&
            neg_scale_1
        ! THE RESIDUAL WAS A MODULE VARIABLE, so every thread wrote the same one.
        ! This routine runs inside the parallel region, so one thread could
        ! overwrite the residual between another thread computing it and testing
        ! it, which printed records whose residual did not match their own
        ! operands. It is local now. Nothing in the model reads it, so the race
        ! only ever corrupted the diagnostic, but a diagnostic that cannot be
        ! trusted is worse than none.
        real(8) :: budget_residual_1
        
        avg_income_to_use_1=is_counterfactual*average_labor_income_calibrated+&
            (1-is_counterfactual)*model_average_labour_income(time_period)
            
        avg_net_wealth_to_use_1=is_counterfactual*average_net_wealth_calibrated+&
            (1-is_counterfactual)*model_average_net_wealth(time_period)
                    
        avg_income_to_use_2=is_counterfactual*average_labor_income_by_employment_calibrated(employment_index)+&
            (1-is_counterfactual)*model_average_labour_income_by_employment(time_period,employment_index)
                                    
        frac_used=frac_mov_optimal_1(years_left_on_mortgage_index)%vector_transition_real&
            (time_period,age_index,financial_index,unemployment_index,employment_index,housing_status_index,voucher_index)
            
        fin_index_frac_used=fin_index_frac_mov_to_optimal(years_left_on_mortgage_index)%vector_transition_integer&
            (time_period,age_index,financial_index,unemployment_index,employment_index,housing_status_index,voucher_index)

        financial_index_used=policy_function_financial_index(years_left_on_mortgage_index)%vector_transition_integer&
            (time_period,age_index,financial_index,unemployment_index,employment_index,housing_status_index,voucher_index)

        consumption_used=policy_function_consumption(years_left_on_mortgage_index)%vector_transition_real&
            (time_period,age_index,financial_index,unemployment_index,employment_index,housing_status_index,voucher_index)
            
        labor_supply_used=policy_function_labor_supply(years_left_on_mortgage_index)%vector_transition_real&
            (time_period,age_index,financial_index,unemployment_index,employment_index,housing_status_index,voucher_index)
            
        housing_status_index_used=policy_function_housing_status_index(years_left_on_mortgage_index)%&
            vector_transition_integer(time_period,age_index,financial_index,unemployment_index,employment_index,&
            housing_status_index,voucher_index)
            
        total_consumption_used=policy_function_total_consumption(years_left_on_mortgage_index)%vector_transition_real&
            (time_period,age_index,financial_index,unemployment_index,employment_index,housing_status_index,voucher_index)
            
        frac_spent_on_addiction_used=policy_function_frac_spent_on_addiction(years_left_on_mortgage_index)%vector_transition_real&
                (time_period,age_index,financial_index,unemployment_index,employment_index,housing_status_index,voucher_index)

        amortization_used=policy_function_years_of_amortization_index(years_left_on_mortgage_index)%&
            vector_transition_integer(time_period,age_index,financial_index,unemployment_index,employment_index,&
            housing_status_index,voucher_index) 

        call calculate_income(unemployment_index,employment_index,income_1,&
            avg_income_to_use_1,avg_income_to_use_2,labor_supply_used,in_retirement)        
    
        ! The fifteen income sites all read this as
        ! risk_free*max(a,0)+unsecured_borrowing_rate*min(a,0). This one charged
        ! only the first half, so the check's income omitted the interest cost of
        ! a renter's debt that the model itself does charge.
        income_1=income_1+(risk_free_rate(time_period)*max(financial_grid(financial_index),0.d0)+&
            unsecured_borrowing_rate*min(financial_grid(financial_index),0.d0))
            
        assets_1=2*threshold_for_food_stamps_as_perc_of_average_net_wealth*&
            avg_net_wealth_to_use_1
        
        ! This one is a homeowner who chooses to rent
        if ((years_left_on_mortgage_index>1) .AND. (amortization_used==1)) then

            assets_1=max(housing_price(time_period)*housing_size(housing_status_index)*&
                (1-cost_of_selling-property_tax(time_period)-housing_depreciation_rate)+&
                min(financial_grid(financial_index),0.d0)*(1+mortgage_interest_rate(time_period))*&
                housing_price(time_period)*housing_size(housing_status_index)+&
                max(financial_grid(financial_index),0.d0),0.d0)
    
        ! This one is a renter who stays renting
        elseif ((years_left_on_mortgage_index==1) .AND. (amortization_used==1)) then
        
            assets_1=max(financial_grid(financial_index),0.d0)

        end if
        
        food_stamps_1=0
        
        ! If they have no assets, they get can qualift for food stamps
        if (assets_1<threshold_for_food_stamps_as_perc_of_average_net_wealth*&
            avg_net_wealth_to_use_1) then
                                
            food_stamps_1=snap_benefit(actual_household_size(age_index),income_1,avg_income_to_use_1)
                                        
        end if
                                                                                                                            
        ! THE SAME TWO MEANINGS, and this site dropped one of them outright.
        ! max(amortization_used-1,0) is ZERO for a renter, so a renter's debt
        ! left the identity altogether and the residual came out equal to the
        ! debt -- 250,039 "budget does not clear" lines in one borrowing-ON solve
        ! against zero in every borrowing-OFF log. With include_homeownership=0
        ! every household is a renter, so this fired at every borrowing state
        ! rather than at some of them.
        if (amortization_used>1) then

            neg_scale_1=housing_price(time_period)*housing_size(housing_status_index_used)

        else

            neg_scale_1=1.d0

        end if

        budget_residual_1=after_tax_wealth_net_of_expenses_1-&
            ((frac_used*min(financial_grid(fin_index_frac_used),0.d0)+&
            (1-frac_used)*min(financial_grid(financial_index_used),0.d0))*&
            neg_scale_1+&
            frac_used*max(financial_grid(fin_index_frac_used),0.d0)+&
            (1-frac_used)*max(financial_grid(financial_index_used),0.d0)+&            
            (1+consumption_tax)*(consumption_used+frac_spent_on_addiction_used*total_consumption_used))
                
        checking_criterion=5*10.d0**(-8)
                        
        if ((abs(budget_residual_1)>checking_criterion) .AND. (after_tax_wealth_net_of_expenses_1>0) .AND. &
           (frac_spent_on_addiction_used>=0) .AND. (consumption_used>0))  then
                         
!            write(*,*) "error budget does not clear"
            write(*,*) "budget does not clear by", budget_residual_1
            write(*,*) "min(financial_grid(fin_index_frac_used),0.d0)=", min(financial_grid(fin_index_frac_used),0.d0)
            write(*,*) "min(financial_grid(financial_index_used),0.d0)=", min(financial_grid(financial_index_used),0.d0)
            write(*,*) "amortization_used=", amortization_used
            write(*,*) "years_left_on_mortgage_index=", years_left_on_mortgage_index
            write(*,*) "housing_status_index=", housing_status_index
            write(*,*) "housing_status_index_used=", housing_status_index_used
!            write(*,*) "total_consumption_used=",total_consumption_used
            write(*,*) "food_stamps_1=", food_stamps_1
!            write(*,*) "checking_criterion=", checking_criterion  
            write(*,*) "consumption_used=", consumption_used
!            write(*,*) "(1-frac_spent_on_addiction_used)*total_consumption_used=", &
!                (1-frac_spent_on_addiction_used)*total_consumption_used
!            write(*,*) "consumption_used-(1-frac_spent_on_addiction_used)*total_consumption_used=", &
!                consumption_used-(1-frac_spent_on_addiction_used)*total_consumption_used
!            write(*,*) "financial_index_used=", financial_index_used  
!            write(*,*) "fin_index_frac_used=", fin_index_frac_used
!            write(*,*) "age_index=", age_index                
!            write(*,*) "years_left_on_mortgage_index=", years_left_on_mortgage_index                    
!            write(*,*) "amortization_used=", amortization_used
!            write(*,*) "unemployment_index=", unemployment_index                                                
!            write(*,*) "financial_index=", financial_index                
!            write(*,*) "frac_used=", frac_used
!            
!            write(*,*) "consumption+savings=",&
!                frac_used*(financial_grid(fin_index_frac_used)-&
!                can_get_mortgage*abs(min(financial_grid(financial_index_used),0.d0)))+&
!                (1-frac_used)*(financial_grid(financial_index_used)-&
!                can_get_mortgage*abs(min(financial_grid(financial_index_used),0.d0)))+&
!                (1+consumption_tax)*consumption_used
!                
!            write(*,*) "frac_spent_on_addiction_used=", frac_spent_on_addiction_used
!            write(*,*) "after_tax_wealth_net_of_expenses_1=", after_tax_wealth_net_of_expenses_1     
!            write(*,*) "rent=", rent(time_period,:)
                                                    
        end if
            
        if ((value_function(years_left_on_mortgage_index)%&
            vector_transition_real(time_period,age_index,financial_index,&
            unemployment_index,employment_index,housing_status_index,voucher_index)==&
            large_negative_num) .AND. (after_tax_wealth_net_of_expenses_1>0) .AND. &
            (years_left_on_mortgage_index<=1) .AND. (age_index<life_span)) then
                                                                       
            negative_consumption=1
                        
        end if
    
    end subroutine
    
    subroutine initialize_feasible_distribution(time_period)
    
        use Global_Vars
        
        implicit none
        
        integer, intent(in) :: time_period
        integer :: has_house,financial_index
        integer, parameter :: only_26_year_olds=1
        character*1 :: string_used
                        
        do i=1,2
                
            distribution_guess(i)%vector_transition_real(time_period,:,:,:,:,:,:)=0
                                
        end do
                
        if (include_exogenous_endowment==1) then
        
            value_of_initial_assets=0
            
            if (only_26_year_olds==1) then
            
                if (start_assets_of_newborns_at_zero==0) then
                
                    relative_endowments=0
                    fraction_with_positive_wealth=0
                
                elseif (uniform_newborn_endowment==1) then

                    ! ZERO ASSETS AT BIRTH, and the endowment arrives in the
                    ! first budget constraint instead -- see newborn_age_transfer.
                    ! Endowing the distribution here would put every newborn on
                    ! an asset grid point, which is what made the instrument a
                    ! step function; leaving them at zero and handing them cash
                    ! makes it continuous. value_of_initial_assets is therefore
                    ! zero in this branch, and the transfer is funded out of the
                    ! bequests the government now collects.
                    relative_endowments=0
                    fraction_with_positive_wealth=0

                elseif (uniform_newborn_endowment==2) then

                    ! EVERY NEWBORN GETS THE SAME AMOUNT, on the author's
                    ! instruction of 1 September: "you give all newborns the same
                    ! amount of wealth so that we match the share of newborns who
                    ! are homeless".
                    !
                    ! So the endowment is ONE number rather than a distribution:
                    ! relative_endowments is 1 in every productivity bin and
                    ! fraction_with_positive_wealth is 1, and the level is set by
                    ! newborn_endowment_scale times average labour income. That
                    ! makes it a single free parameter with a single target,
                    ! which is what a calibrated instrument has to be.
                    !
                    ! It deliberately departs from RS-2024, whose theta(x) and
                    ! a1(x) both vary with the productivity fixed effect from the
                    ! 2019 SCF. That version is the branch below and is kept, so
                    ! switching uniform_newborn_endowment to 0 restores it.
                    relative_endowments(:)=1.d0
                    fraction_with_positive_wealth(:)=1.d0

                else

                    ! THESE ARE A NINE NODE PROFILE AND THE GRID IS NOW SEVEN.
                    ! The levels come from the 2019 SCF at nine productivity bins
                    ! and were written as literal indices 1..9. Cutting the grid
                    ! to seven made every index above seven an out of bounds
                    ! write, which gfortran caught at once -- the branch is
                    ! INACTIVE (uniform_newborn_endowment is on, so the live path
                    ! is relative_endowments(:)=1) but a compile time out of
                    ! bounds store is not something to leave in place.
                    !
                    ! The indices are clamped with min(i,employment_grid_size) so
                    ! the code is safe at any grid size and IDENTICAL at nine.
                    ! That is a guard and NOT a re-mapping: at seven nodes the
                    ! top three levels collapse onto the top node and the profile
                    ! is no longer the SCF's. If uniform_newborn_endowment is
                    ! ever switched back off, these nine numbers have to be
                    ! re-read onto the grid actually in use before the branch
                    ! means anything.
                    relative_endowments(min(9,employment_grid_size))=1.3853
                    relative_endowments(min(8,employment_grid_size))=1.3853
                    relative_endowments(min(7,employment_grid_size))=1.3853
                    relative_endowments(min(6,employment_grid_size))=0.8520
                    relative_endowments(min(5,employment_grid_size))=0.2609
                    relative_endowments(min(4,employment_grid_size))=0.1964
                    relative_endowments(min(3,employment_grid_size))=0.1338
                    relative_endowments(min(2,employment_grid_size))=0.1319
                    relative_endowments(min(1,employment_grid_size))=0.1319
                    
                    relative_endowments(:)=&
                        max(relative_endowments(:),relative_endowments(:)*increase_in_newborns_bequests)

                    fraction_with_positive_wealth(min(9,employment_grid_size))=0.7690
                    fraction_with_positive_wealth(min(8,employment_grid_size))=0.7690
                    fraction_with_positive_wealth(min(7,employment_grid_size))=0.7690
                    fraction_with_positive_wealth(min(6,employment_grid_size))=0.6654
                    fraction_with_positive_wealth(min(5,employment_grid_size))=0.5946
                    fraction_with_positive_wealth(min(4,employment_grid_size))=0.6482
                    fraction_with_positive_wealth(min(3,employment_grid_size))=0.5171
                    fraction_with_positive_wealth(min(2,employment_grid_size))=0.4779
                    fraction_with_positive_wealth(min(1,employment_grid_size))=0.4779
                    
                    fraction_with_positive_wealth(:)=&
                        min(max(fraction_with_positive_wealth(:),&
                        fraction_with_positive_wealth(:)*increase_in_newborns_bequests),1.d0)
                        
    !                write(*,*) "fraction_with_positive_wealth=", fraction_with_positive_wealth(:)
    
                end if
                            
            else    
            
                relative_endowments(min(9,employment_grid_size))=3.4658762
                relative_endowments(min(8,employment_grid_size))=3.3657614
                relative_endowments(min(7,employment_grid_size))=0.89245148
                relative_endowments(min(6,employment_grid_size))=0.6887341
                relative_endowments(min(5,employment_grid_size))=0.25194367
                relative_endowments(min(4,employment_grid_size))=0.14127229
                relative_endowments(min(3,employment_grid_size))=0.04659514
                relative_endowments(min(2,employment_grid_size))=0
                relative_endowments(min(1,employment_grid_size))=0
                
            end if
                        
            max_initial_endowment=newborn_endowment_scale*&
                (is_counterfactual*average_labor_income_calibrated+&
                (1-is_counterfactual)*model_average_labour_income(time_period))

            if (is_counterfactual==0) then

                initial_endowment=negative_financial_grid_size

            end if
            
            do employment_index=1,employment_grid_size
            
                do unemployment_index=1,threshold_addiction_index

                    if (is_counterfactual==0) then
                
                        ! THE ENDOWMENT IS A TRANSFER, NOT A STOCK, when
                        ! endowment_is_a_transfer=1. The author, 3 September, asked
                        ! that it not be counted as wealth -- *"Only the actual
                        ! savings they have (based on the financial grid which is
                        ! 0)"* -- and chose this reading over netting it out of the
                        ! wealth statistics afterwards.
                        !
                        ! So the newborn ENTERS at the grid's zero index and
                        ! receives the endowment as cash on hand in its first
                        ! period, where it is consumed or saved like any other
                        ! resource. Whatever it chooses to carry forward is its own
                        ! saving and counts in w_bot and in wealth over output;
                        ! the transfer itself never appears as a stock anybody
                        ! holds. That is what makes it family support a survey does
                        ! not see, which is the justification for having it at all.
                        !
                        ! The old branch below placed the newborn ON the grid point
                        ! nearest the endowment, so the full amount was measured
                        ! wealth before the household had made any decision. That
                        ! is what inflated w_bot and caused the parameter to be
                        ! parked on 2 September.
                        if (endowment_is_a_transfer==1) then

                            initial_endowment(employment_index)=negative_financial_grid_size

                        else if (fraction_with_positive_wealth(employment_index)>0) then
                    
                            initial_endowment(employment_index)=&
                                min(minloc(financial_grid(:)-relative_endowments(employment_index)*max_initial_endowment,1,&
                                mask=financial_grid(:)-relative_endowments(employment_index)*max_initial_endowment>0),&
                                financial_grid_size)
                                
                            if (initial_endowment(employment_index)==0) then
                            
                                initial_endowment(employment_index)=financial_grid_size
                                
                            end if
                            
                        else
                        
                            initial_endowment(employment_index)=negative_financial_grid_size
                                                            
                        end if

                    end if
                                    
                    distribution_guess(1)%vector_transition_real&
                        (time_period,1,initial_endowment(employment_index),&
                        unemployment_index,employment_index,0,0)=&
                        fraction_with_positive_wealth(employment_index)*&
                        unconditional_employment_probability(employment_index)*&
                        unconditional_unemployment_probability(unemployment_index)
                        
                    distribution_guess(1)%vector_transition_real&
                        (time_period,1,negative_financial_grid_size,&
                        unemployment_index,employment_index,0,0)=&
                        (1-fraction_with_positive_wealth(employment_index))*&
                        unconditional_employment_probability(employment_index)*&
                        unconditional_unemployment_probability(unemployment_index)
                        
                    value_of_initial_assets=value_of_initial_assets+&
                        distribution_guess(1)%vector_transition_real&
                        (time_period,1,initial_endowment(employment_index),&
                        unemployment_index,employment_index,0,0)*&
                        financial_grid(initial_endowment(employment_index))
                        
                end do
                
            end do

!            write(*,*) "initial_endowment=", initial_endowment      
                        
        else

            fraction_with_positive_wealth=0
        
            distribution_guess(1)%vector_transition_real(time_period,1,negative_financial_grid_size,1,1,0,0)=1
        
        end if
                        
        do age_index=2,life_span
        
            do employment_index=1,employment_grid_size
            
                do unemployment_index=1,threshold_addiction_index

                    if (include_exogenous_endowment==1) then
                                                
                        distribution_guess(1)%vector_transition_real&
                            (time_period,age_index,initial_endowment(employment_index),unemployment_index,employment_index,0,0)=&
                            survival_probability(age_index-1,1,0,0)*distribution_guess(1)%vector_transition_real&
                            (time_period,age_index-1,initial_endowment(employment_index),unemployment_index,employment_index,0,0)

                    end if
                        
                    distribution_guess(1)%vector_transition_real&
                        (time_period,age_index,negative_financial_grid_size,unemployment_index,employment_index,0,0)=&
                        survival_probability(age_index-1,1,0,0)*distribution_guess(1)%vector_transition_real&
                        (time_period,age_index-1,negative_financial_grid_size,unemployment_index,employment_index,0,0)
                        
                end do
                
            end do
                                                  
        end do
        
        sum_of_distribution=0
        
        do i=1,2
        
            sum_of_distribution=sum_of_distribution+&
                sum(distribution_guess(i)%vector_transition_real(time_period,:,:,:,:,:,:))
                
        end do
        
        write(*,*) "sum(distribution_guess)=", sum_of_distribution
        
        if (use_old_distribution==1)  then
        
            do i=1,2
            
                write(string_used,'(i1)') i
        
                open(unit=12,file="distribution_stationary"//trim(string_used)//trim(old_results)//".dat",action='read')
                    read(12,'(F30.28)') distribution_guess(i)%vector_transition_real(1,:,:,:,:,:,:)
                close(12)
                            
                if (hold_distribution_fixed==1) then
                
                    distribution_stationary(i)%vector_transition_real(1,:,:,:,:,:,:)=&
                        distribution_guess(i)%vector_transition_real(1,:,:,:,:,:,:)
                
                end if
                
            end do
            
        end if
        
        if (solve_transition_dynamics==1) then
                        
            do i=1,2
            
                distribution_guess(i)%vector_transition_real(0,:,:,:,:,:,:)=0
                
            end do
                
            do age_index=1,life_span
                            
                do years_left_on_mortgage_index=1,max_amortization_years
                            
                    if (years_left_on_mortgage_index>1) then
                        
                        has_house=1
                        
                    else
                    
                        has_house=0
                        
                    end if
                                                                                        
                    do unemployment_index=1,unemployment_grid_size
                    
                        do employment_index=1,employment_grid_size
                        
                            do voucher_index=0,(1-has_house)*include_vouchers
                                                                                        
                                do financial_index=has_house*1+(1-has_house)*renter_floor_by_age(min(max(age_index,1),life_span)),financial_grid_size
                                                   
                                    do housing_status_index=(1-has_house)*lowest_housing_grid_point+&
                                        has_house*index_of_smallest_house_hhld_can_buy,housing_status_grid_size-1
                                                                                
                                        ! WAS years_left_on_mortgage_index_used, WHICH IS ASSIGNED
                                        ! NOWHERE IN THE FILE. distribution_guess is dimension(1:2),
                                        ! so an uninitialised integer here subscripts a derived type
                                        ! out of bounds on both a read and a write, and it would not
                                        ! fail loudly: a local integer most often reads 0, which is
                                        ! one element below the array. The loop this sits inside runs
                                        ! over years_left_on_mortgage_index, which is plainly what was
                                        ! meant. Dead while solve_transition_dynamics=0; live the
                                        ! moment the transition is switched on, which is being built.
                                        distribution_guess(years_left_on_mortgage_index)%vector_transition_real&
                                            (0,age_index,financial_index,unemployment_index,employment_index,&
                                            housing_status_index,voucher_index)=&
                                            distribution_guess(years_left_on_mortgage_index)%&
                                            vector_transition_real(0,age_index,financial_index,&
                                            unemployment_index,employment_index,housing_status_index,voucher_index)+&
                                            distribution_to_fetch(years_left_on_mortgage_index)%vector_real&
                                            (age_index,financial_index,unemployment_index,employment_index,&
                                            housing_status_index,voucher_index)
                            
                                    end do
                                    
                                end do
                                    
                            end do
                            
                        end do
                        
                    end do
                    
                end do
            
            end do
            
            sum_of_distribution=0
        
            do i=1,2
            
                sum_of_distribution=sum_of_distribution+sum(distribution_guess(i)%vector_transition_real(0,:,:,:,:,:,:))
                    
                distribution_stationary(i)%vector_transition_real(0,:,:,:,:,:,:)=&
                    distribution_guess(i)%vector_transition_real(0,:,:,:,:,:,:)
                    
            end do
                        
            write(*,*) "sum_of_distribution 1=", sum_of_distribution
                        
        end if
        
    end subroutine
    
    subroutine compute_voucher_index_1(is_homeless_1,voucher_index_1)
    
        use global_vars
        
        implicit none
        
        integer, intent(out) :: voucher_index_1
        integer, intent(in) :: is_homeless_1
        integer :: meets_condition_1
        
        voucher_index_1=1

        ! TREATMENT MEETS THE SOBRIETY CONDITION, and is rewarded for it.
        !
        ! Index 3 is the branch Treatment First uses to take the voucher away
        ! from a household carrying the disorder. A household in treatment is
        ! abstaining by construction, v=0, so on the rule the policy actually
        ! states it is not the household the condition is aimed at. Sending it
        ! to index 3 anyway would punish the one response the policy is trying
        ! to buy, and would make the treatment choice strictly worse than doing
        ! nothing under the very policy named after it.
        !
        ! So the disorder alone no longer routes to index 3: the disorder
        ! WITHOUT treatment does.
        meets_condition_1=0

        if ((include_treatment==1) .AND. (treatment_choice_now==1)) then

            meets_condition_1=1

        end if
        
        if (is_homeless_1==1) then
        
            voucher_index_1=2
                                    
            if ((unemployment_index>threshold_addiction_index) .AND. &
                (meets_condition_1==0)) then
            
                voucher_index_1=3
                
            end if
            
        elseif ((is_counterfactual==1) .AND. (unemployment_index>threshold_addiction_index) .AND. &
            (meets_condition_1==0) .AND. &
            (increased_prob_of_voucher_if_homeless_and_addicted==0)) then
            
            voucher_index_1=3
            
        end if 
    
    end subroutine
    
    subroutine calculate_future_voucher_index_and_opportunity&
        (has_opportunity,first_voucher_index,second_voucher_index,&
        time_period,has_house,choose_to_own_1,voucher_index_1,income_to_use_5)
    
        use global_vars
        
        implicit none
        
        integer, intent(in) :: time_period,has_house,voucher_index_1,choose_to_own_1
        real(8) :: income_to_use_5
        integer, intent(inout) :: has_opportunity,first_voucher_index,second_voucher_index
        
        has_opportunity=0
        first_voucher_index=0
        second_voucher_index=0

        if ((income_to_use_5<threshold_income_vouchers*&
            ((1-is_counterfactual)*median_income(time_period)+&
            is_counterfactual*median_income_calibrated)) .AND. &
            (include_vouchers==1)) then
            
            if ((has_house==0) .AND. (choose_to_own_1==0) .AND. (voucher_index==0)) then

                has_opportunity=1
                first_voucher_index=0
                second_voucher_index=include_vouchers

            elseif ((has_house==0) .AND. (choose_to_own_1==0) .AND. (voucher_index==1)) then

                has_opportunity=1
                first_voucher_index=include_vouchers
                second_voucher_index=include_vouchers
                
                ! Those who are addicted in a counterfactual, has the option to move to both not getting a vouchers                
                if ((is_counterfactual==1) .AND. (voucher_index_1==3) .AND. &
                    (increased_prob_of_voucher_if_homeless_and_addicted==0)) then
                    
                    has_opportunity=1
                    first_voucher_index=0
                    second_voucher_index=include_vouchers
                    
                end if             
                
            elseif ((has_house==1) .AND. (choose_to_own_1==0)) then

                has_opportunity=1
                first_voucher_index=0
                second_voucher_index=include_vouchers

            end if

        end if
        
    end subroutine
    
    subroutine converge_to_stationary_equilibrium(time_period)
    
        use Global_Vars
        !$ use omp_lib
               
        implicit none
        
        integer :: financial_index,has_house,time_period,track_housing_1,voucher_index_1
        integer :: number_of_threads_used,loop_only_over_oldest,amortization_used,is_addicted_1
        real(8) :: sum_distribution_implied,sum_distribution_guess,avg_income_to_use_1,avg_income_to_use_2
        integer, dimension(6) :: dist_argmax_1
        integer :: dist_dim_1
        real(8) :: dist_mass_1,dist_wealth_1
        ! FROM lowest_housing_grid_point, NOT FROM 0. The housing dimension of
        ! the distribution starts at -1 -- homelessness -- and the loop that
        ! fills this runs over that dimension's own bounds, so a declaration
        ! from 0 made dist_housing_1(-1) a read-modify-write of the 8 bytes
        ! below the array on every 100th sweep of every run: -fcheck caught it
        ! at line ~21426 the first time the diagnostic fired. The victim of the
        ! write is whatever the compiler placed there, and the homeless mass
        ! never reached the DIST_MOM by_housing column it was meant for.
        real(8), dimension(lowest_housing_grid_point:housing_status_grid_size-1) :: dist_housing_1
        integer :: newborn_census_i
        real(8) :: newborn_census_clean,newborn_census_smi
        character*1 :: string_used

        ! Negative rather than zero, so a DIST_DONE printed without a sweep
        ! having run says so instead of claiming perfect convergence.
        distance_distribution_reached=-1.d0
                
        if (partial_equilibrium==1) then
        
            do i=1,2
            
                write(string_used,'(i1)') i
        
                open(unit=12,file="distribution_stationary"//trim(string_used)//trim(benchmark_simulation)//".dat",action='read')
                    read(12,'(F30.28)') distribution_stationary(i)%vector_transition_real(1,:,:,:,:,:,:)
                close(12)
                
                distribution_guess(i)%vector_transition_real(1,:,:,:,:,:,:)=&
                    distribution_stationary(i)%vector_transition_real(1,:,:,:,:,:,:)
                
            end do
        
        end if

        avg_income_to_use_1=is_counterfactual*average_labor_income_calibrated+&
            (1-is_counterfactual)*model_average_labour_income(time_period)

        if (have_probablistic_death==0) then

            loop_only_over_oldest=1

        else

            loop_only_over_oldest=1

        end if
        
        if (solve_transition_dynamics>=0) then
        
!            !$omp parallel
!            !$omp master
!            !$ total_number_of_threads=omp_get_num_threads()
!!            write(*,*) "total_number_of_threads=", total_number_of_threads
!            !$omp end master
!            !$omp end parallel
                    
        end if
        
        if ((is_counterfactual==1) .AND. (solve_transition_dynamics==1)) then
        
            write(*,*) "time_period=", time_period
        
        end if
        
        if (partial_equilibrium==1) then
        
            if (how_many_iterations_to_do_on_distribution==0) then
        
                distance_distribution=0
                
            else
            
                distance_distribution=1
                
            end if
        
        else
        
            distance_distribution=1
            
        end if
                
        loop_count_dist=0
               
        do while (distance_distribution>stopping_rule_stationary_distribution)
        
            do i=1,2
                
                distribution_implied_private(i)%vector_cpu_real(:,:,:,:,:,:,:)=0
                distribution_implied(i)%vector_transition_real(:,:,:,:,:,:,:)=0
                
            end do
            
             if (solve_transition_dynamics>=0) then
             
                number_of_threads_used=max_CPUs
            ! max_CPUs stays a compile-time parameter because it dimensions vector_cpu_real.
            ! Use it only as an upper bound; take the actual thread count from the runtime so
            ! the same binary is correct on a 4-core laptop and a 40-core server. Honours
            ! OMP_NUM_THREADS when set.
            !$ number_of_threads_used=max(1,min(max_CPUs,omp_get_max_threads()))

                CALL OMP_SET_NUM_THREADS(number_of_threads_used)
        
                !$omp parallel
                !$omp master
                !$ total_number_of_threads=omp_get_num_threads()
                !$omp end master
                !$omp end parallel
                    
            end if
            
            do m=1,2
                
                do age_index=1,life_span-1

                    if (age_index>(life_span-retirement_span)) then
                    
                        in_retirement=1
                    
                    else
                    
                        in_retirement=0
                    
                    end if
                    
                    if (age_index>=(life_span-retirement_span)) then
                    
                        at_least_one_period_before_retirement=1
                    
                    else
                    
                        at_least_one_period_before_retirement=0
                    
                    end if
                    
                    one_period_before_death=0
                    
                    if (age_index==life_span) then
                    
                        one_period_before_death=1
                        
                    end if
                                                            
                    if (age_index==1) then
                
                        newborn_household=1
                        
                    else
                
                        newborn_household=0
                    
                    end if
                
                    do years_left_on_mortgage_index=1,newborn_household*1+(1-newborn_household)*max_amortization_years
                                            
                        if (years_left_on_mortgage_index>1) then
                        
                            has_house=1
                            
                        else
                        
                            has_house=0
                            
                        end if
                        
                        track_housing_1=1
                        
                        if (has_house==0) then
                        
                            if (track_renters_housing==0) then
                            
                                track_housing_1=0
                                
                            end if
                            
                        end if
                                
                        do unemployment_index=1,unemployment_grid_size
                        
                            do employment_index=1,employment_grid_size

                                avg_income_to_use_2=is_counterfactual*&
                                    average_labor_income_by_employment_calibrated(employment_index)+&
                                    (1-is_counterfactual)*model_average_labour_income_by_employment(time_period,employment_index)
                            
                                do voucher_index=0,(1-has_house)*include_vouchers
                                                                             
                                    !$omp parallel do default(none) &
                                    !$omp& shared(&
                                    !$omp& distribution_implied_private,distribution_guess,&
                                    !$omp& frac_mov_optimal_1,fin_index_frac_mov_to_optimal,policy_function_addiction,&
                                    !$omp& policy_function_financial_index,policy_function_years_of_amortization_index,&
                                    !$omp& policy_function_housing_status_index,unemployment_process,one_period_before_death,&
                                    !$omp& m,time_period,has_mortgage,newborn_household,track_housing_1,voucher_index,&
                                    !$omp& at_least_one_period_before_retirement,survival_probability,employment_process,&
                                    !$omp& age_index,has_house,years_left_on_mortgage_index,unemployment_index,employment_index,&
                                    !$omp& index_of_smallest_house_hhld_can_buy,addiction_probabilities,voucher_probabilities,&
                                    !$omp& policy_function_frac_spent_on_addiction,policy_function_total_consumption,&
                                    !$omp& price_of_addictive_good,policy_function_treatment,&
                                    !$omp& avg_income_to_use_1,avg_income_to_use_2,policy_function_labor_supply,in_retirement,&
                                    !$omp& median_income,financial_grid,risk_free_rate,median_income_calibrated,is_addicted_1,&
                                    !$omp& unsecured_borrowing_rate,renter_floor_by_age,&
                                    !$omp& survival_probability_for_dist_iteration) &
!
! voucher_index_1 IS PRIVATE, NOT SHARED. It is WRITTEN inside this loop, once
! per iteration, by compute_voucher_index_1, from is_homeless_2 -- which depends
! on the policy's chosen future housing status and so varies with
! financial_index, the loop index. Shared, that is a data race: two threads write
! it and either may read the other's value, as the fourth subscript of
! voucher_probabilities and as an argument to
! calculate_future_voucher_index_and_opportunity.
!
! It is harmless in the benchmark ONLY by arithmetic accident: both
! increased_prob_of_voucher_if_homeless multipliers are 1, so
! voucher_probabilities is identical across its fourth index and a raced index
! selects the same number. It becomes live nondeterminism the moment either
! multiplier moves off 1 -- and line 36622 already carries a commented-out 5.81,
! so someone has tried -- or in any Treatment First counterfactual, where
! voucher_conditional_on_clean makes index 3 differ from 1 and 2 by the whole
! detection and false-positive structure.
!
! Every other temporary in this loop body is a threadprivate module variable.
! voucher_index_1 and is_addicted_1 were the two that are not, and is_addicted_1
! is benign: it is a function of unemployment_index, an OUTER loop variable, so
! every thread writes the same value to it.
                                    !$omp& private(voucher_index_1)
!                                                                        
                                    do financial_index=newborn_household*negative_financial_grid_size+&
                                         (1-newborn_household)*(has_house*1+(1-has_house)*renter_floor_by_age(min(max(age_index,1),life_span))),&
                                         include_exogenous_endowment*financial_grid_size+(1-include_exogenous_endowment)*&
                                         (newborn_household*negative_financial_grid_size+(1-newborn_household)*financial_grid_size)
                                
                                        thread_num=0
                                        !$ thread_num=omp_get_thread_num()

                                        do housing_status_index=(1-has_house)*lowest_housing_grid_point+&
                                            has_house*index_of_smallest_house_hhld_can_buy,&
                                            track_housing_1*(1-newborn_household)*(housing_status_grid_size-1)    

                                            ! STATES WITH NO MASS PROPAGATE NO MASS.
                                            !
                                            ! The distribution iteration is now four fifths of a
                                            ! calibration loop, and most of what it does is push
                                            ! zeros around: the distribution is concentrated, over
                                            ! half of it sits at the lowest asset point alone, and
                                            ! every empty state still pays for a policy lookup, an
                                            ! income calculation and a four deep accumulation.
                                            !
                                            ! Skipping them is exact to the threshold, which is set
                                            ! twelve orders of magnitude below the stopping rule, so
                                            ! the mass discarded cannot reach the convergence test
                                            ! let alone a reported moment.
                                            if (distribution_guess(years_left_on_mortgage_index)%&
                                                vector_transition_real(time_period-solve_transition_dynamics,&
                                                age_index,financial_index,unemployment_index,employment_index,&
                                                housing_status_index,voucher_index)<=negligible_mass) cycle
                                                                                                            
                                            if (policy_function_years_of_amortization_index(years_left_on_mortgage_index)%&
                                                vector_transition_integer(time_period,age_index,financial_index,&
                                                unemployment_index,employment_index,housing_status_index,voucher_index)>1) then
                                                
                                                choose_to_own=1
                                                
                                            else
                                            
                                                choose_to_own=0
                                                
                                            end if
                                            
                                            income_to_use_4=2*((1-is_counterfactual)*median_income(time_period)+&
                                                is_counterfactual*median_income_calibrated)

                                            if (choose_to_own==0) then

                                                labor_supply_to_use=&
                                                    policy_function_labor_supply(years_left_on_mortgage_index)%&
                                                    vector_transition_real(time_period,age_index,financial_index,&
                                                    unemployment_index,employment_index,housing_status_index,voucher_index)

                                                call calculate_income(unemployment_index,employment_index,income_to_use_4,&
                                                    avg_income_to_use_1,avg_income_to_use_2,labor_supply_to_use,in_retirement)

                                                income_to_use_4=income_to_use_4+&
                                                    (risk_free_rate(time_period)*max(financial_grid(financial_index),0.d0)+unsecured_borrowing_rate*min(financial_grid(financial_index),0.d0))

                                            end if

                                            track_housing_2=1
                                            
                                            if (choose_to_own==0) then
                                            
                                                if (track_renters_housing==0) then
                                                
                                                    track_housing_2=0
                                                    
                                                end if
                                                
                                            end if
                                            
                                            if (m==1) then
                                                    
                                                financial_index_copy=policy_function_financial_index&
                                                    (years_left_on_mortgage_index)%vector_transition_integer&
                                                    (time_period,age_index,financial_index,unemployment_index,&
                                                    employment_index,housing_status_index,voucher_index)
                                                    
                                                fraction_copy=(1-frac_mov_optimal_1(years_left_on_mortgage_index)%&
                                                    vector_transition_real(time_period,age_index,&
                                                    financial_index,unemployment_index,employment_index,&
                                                    housing_status_index,voucher_index))
                                                                                                    
                                            elseif (m==2) then
                                            
                                                financial_index_copy=fin_index_frac_mov_to_optimal&
                                                    (years_left_on_mortgage_index)%vector_transition_integer&
                                                    (time_period,age_index,financial_index,unemployment_index,&
                                                    employment_index,housing_status_index,voucher_index)
                                                    
                                                fraction_copy=frac_mov_optimal_1(years_left_on_mortgage_index)%&
                                                    vector_transition_real(time_period,&
                                                    age_index,financial_index,unemployment_index,employment_index,&
                                                    housing_status_index,voucher_index)
                                                                                                                                                                                                                                                           
                                            end if

                                            amortization_used_dist=policy_function_years_of_amortization_index&
                                                (years_left_on_mortgage_index)%vector_transition_integer&
                                                (min(time_period,transition_length),age_index,financial_index,&
                                                unemployment_index,employment_index,housing_status_index,voucher_index)
                                                
                                            future_housing_status_index_to_use_2=&
                                                policy_function_housing_status_index(years_left_on_mortgage_index)%&
                                                vector_transition_integer(time_period,age_index,financial_index,&
                                                unemployment_index,employment_index,housing_status_index,voucher_index)
                                                
                                            if (track_housing_2==0) then
                                            
                                                if (future_housing_status_index_to_use_2>second_lowest_housing_grid_point) then
                                                
                                                    future_housing_status_index_to_use_2=0
                                                    
                                                end if
                                                
                                            end if
                                            
                                            is_homeless_2=1
                                            
                                            if (future_housing_status_index_to_use_2==lowest_housing_grid_point) then
                                            
                                                is_homeless_2=2
                                            
                                            end if
                                            
                                            call compute_voucher_index_1(is_homeless_2,voucher_index_1)
                                            
                                            call calculate_future_voucher_index_and_opportunity&
                                                (has_opportunity_2,first_voucher_index_1,second_voucher_index_1,&
                                                time_period,has_house,choose_to_own,voucher_index_1,income_to_use_4)
                                                                                        
                                            addiction_choice_1=&
                                                policy_function_addiction(years_left_on_mortgage_index)%&
                                                vector_transition_integer(time_period,age_index,financial_index,&
                                                unemployment_index,employment_index,housing_status_index,voucher_index)

                                            treatment_choice_dist_1=&
                                                policy_function_treatment(years_left_on_mortgage_index)%&
                                                vector_transition_integer(time_period,age_index,financial_index,&
                                                unemployment_index,employment_index,housing_status_index,voucher_index)

                                            drug_quantity_dist_1=&
                                                (policy_function_frac_spent_on_addiction(years_left_on_mortgage_index)%&
                                                vector_transition_real(time_period,age_index,financial_index,&
                                                unemployment_index,employment_index,housing_status_index,voucher_index)*&
                                                policy_function_total_consumption(years_left_on_mortgage_index)%&
                                                vector_transition_real(time_period,age_index,financial_index,&
                                                unemployment_index,employment_index,housing_status_index,voucher_index))/&
                                                price_of_addictive_good
                                                
                                            is_addicted_1=0                                                
                                            loop_over_addiction_2=0
                                                                                                                                                                                   
                                            if (unemployment_index>threshold_addiction_index) then
                                            
                                                is_addicted_1=1
                                                loop_over_addiction_2=1
                                                
                                            elseif ((addiction_choice_1>=1) .AND. &
                                                (unemployment_index<=threshold_addiction_index) .AND. &
                                                (include_probability_of_becoming_addicted==1)) then
                                                
                                                loop_over_addiction_2=1
                                                
                                            end if
                                            
                                            do future_addiction_index_2=&
                                                (1-loop_over_addiction_2)*addiction_choice_1+loop_over_addiction_2*0,&
                                                (1-loop_over_addiction_2)*addiction_choice_1+loop_over_addiction_2*include_addiction
                                                
                                                check_2=0
                                                
                                                if (future_addiction_index_2==1) then
                                                
                                                    check_2=1
                                                    
                                                end if
                                            
                                                do future_unemployment_index=include_addiction*&
                                                    ((1-check_2)*1+check_2*(threshold_addiction_index+1))+&
                                                    (1-include_addiction)*(at_least_one_period_before_retirement*&
                                                    (one_period_before_death*1+(1-one_period_before_death)*unemployment_index)+&
                                                    (1-at_least_one_period_before_retirement)*1),include_addiction*&
                                                    ((1-check_2)*threshold_addiction_index+check_2*unemployment_grid_size)+&
                                                    (1-include_addiction)*(at_least_one_period_before_retirement*&
                                                    (one_period_before_death*unemployment_grid_size+&
                                                    (1-one_period_before_death)*unemployment_index)+&
                                                    (1-at_least_one_period_before_retirement)*unemployment_grid_size)
                                                                                 
                                                    do future_employment_index=&
                                                        at_least_one_period_before_retirement*employment_index+&
                                                        (1-at_least_one_period_before_retirement)*1,&
                                                        at_least_one_period_before_retirement*employment_index+&
                                                        (1-at_least_one_period_before_retirement)*employment_grid_size

                                                        do future_voucher_index=first_voucher_index_1,second_voucher_index_1
                                                        
                                                            distribution_implied_private(amortization_used_dist)%&
                                                                vector_cpu_real(thread_num+1,age_index+1,financial_index_copy,&
                                                                future_unemployment_index,future_employment_index,&
                                                                future_housing_status_index_to_use_2,future_voucher_index)=&
                                                                fraction_copy*survival_probability_for_dist_iteration&
                                                                (age_index,is_homeless_2,&
                                                                survival_sud_of(is_addicted_1,treatment_choice_dist_1),&
                                                                smi_of(unemployment_index))*&
                                                                voucher_probabilities(voucher_index,&
                                                                future_voucher_index,has_opportunity_2,voucher_index_1)*&
                                                                employment_process(age_index,employment_index,&
                                                                future_employment_index)*unemployment_process&
                                                                (age_index,unemployment_index,future_unemployment_index,&
                                                                is_homeless_2,future_addiction_index_2,employment_index)*&
                                                                addiction_transition(is_addicted_1,&
                                                                future_addiction_index_2,addiction_choice_1,is_homeless_2,&
                                                                drug_quantity_dist_1,0,treatment_choice_dist_1)*&
                                                                distribution_guess(years_left_on_mortgage_index)%&
                                                                vector_transition_real(time_period-solve_transition_dynamics,&
                                                                age_index,financial_index,unemployment_index,employment_index,&
                                                                housing_status_index,voucher_index)+&
                                                                distribution_implied_private(amortization_used_dist)%&
                                                                vector_cpu_real&
                                                                (thread_num+1,age_index+1,financial_index_copy,&
                                                                future_unemployment_index,future_employment_index,&
                                                                future_housing_status_index_to_use_2,future_voucher_index)

                                                        end do
                                                                                                                                                                                                                
                                                    end do
                                                    
                                                end do
                                                
                                            end do
                                                
                                        end do
                                
                                    end do
                                                                  
                                    !$omp end parallel do
                                    
                                end do
                                
                            end do
                        
                        end do
                
                    end do
                                                
                end do
            
            end do
            
            if (solve_transition_dynamics>=0) then
            
                number_of_threads_used=max_CPUs
            ! max_CPUs stays a compile-time parameter because it dimensions vector_cpu_real.
            ! Use it only as an upper bound; take the actual thread count from the runtime so
            ! the same binary is correct on a 4-core laptop and a 40-core server. Honours
            ! OMP_NUM_THREADS when set.
            !$ number_of_threads_used=max(1,min(max_CPUs,omp_get_max_threads()))

                CALL OMP_SET_NUM_THREADS(number_of_threads_used)
        
                !$omp parallel
                !$omp master
                !$ total_number_of_threads=omp_get_num_threads()
                !$omp end master
                !$omp end parallel
                    
            end if
            
            if ((have_probablistic_death==1) .OR. (newborns_inherit_addiction==0)) then

                ! THIS IS THE NEWBORN ROW, AND IT IS THE ONLY ONE. The branch
                ! below, which builds newborns out of the households that die and
                ! is the one both newborn arrays were written for, is unreachable:
                ! have_probablistic_death is one and newborns_inherit_addiction is
                ! zero, so this arm always runs. Everything the model says about
                ! who a newborn is has to be said here.
                !
                ! It used to say two things that are not the model's.
                !
                ! THE PRODUCTIVITY DRAW IGNORED THE PARENT. It was
                ! unconditional_employment_probability, the ergodic distribution of
                ! the productivity process, so delta_d moved
                ! newborn_employment_probability and nothing downstream ever read
                ! it. The child penalty entered the parent's continuation value
                ! through expected_child_value and entered the cross section
                ! nowhere: parents were told their child would be poorer and the
                ! children were then drawn as though it were not so. The moment
                ! delta_d is calibrated on is computed off
                ! newborn_employment_probability directly, so it would have
                ! converged with the mechanism absent from the model.
                !
                ! THE SMI DRAW WAS EMPTY. unconditional_unemployment_probability is
                ! (1,0,0) on its first three entries and zero on the SMI block,
                ! hardcoded, so every newborn was born clean, employed and without
                ! mental illness. The profile says 12.1 per cent of them have it at
                ! age one. With nobody born carrying it, prevalence was built by
                ! onset from age two alone and came out at 1.4 per cent against a
                ! profile averaging 4.8, age one read exactly 0.00000 against
                ! 0.12129, and lambda_m, kappa_uem, rho_m and rho_d are all
                ! calibrated on moments of a population that was three times too
                ! small. verify_newborn_process passes and always did: the array it
                ! checks is right and was never read.
                !
                ! Newborns are still born employed and clean, which is the model's
                ! convention and not what was wrong.
                newborn_productivity_draw(:)=0

                ! Contracted over the parent's productivity node as well as its
                ! disorder and housing status, which is the whole of the
                ! persistence change: newborn_parent_share now resolves the
                ! dying mass by node and newborn_employment_probability holds
                ! the child's distribution conditional on it.
                do newborn_d_index_1=0,1

                    do newborn_h_index_1=1,2

                        do newborn_parent_node_1=1,employment_grid_size

                            newborn_productivity_draw(:)=newborn_productivity_draw(:)+&
                                newborn_parent_share(newborn_parent_node_1,&
                                newborn_d_index_1,newborn_h_index_1)*&
                                newborn_employment_probability(:,newborn_parent_node_1,&
                                newborn_d_index_1,newborn_h_index_1)

                        end do

                    end do

                end do

                ! WHY THE POPULATION IS NOT SHIFTING. The realised mass by
                ! productivity node matches the unconditional lognormal to three
                ! significant figures at every node, and it should not: a tenth
                ! of parents carry the disorder, their children's draw puts
                ! nearly four times the mass in the bottom three nodes, and
                ! productivity is permanent, so the stationary cross section IS
                ! the newborn draw. Something between this mixture and the
                ! distribution is losing the penalty. Print the mixture and the
                ! shares that built it, so the next loop says which.
                write(*,*) "newborn_parent_share (clean housed, disordered housed, clean street, disordered street)=", &
                    sum(newborn_parent_share(:,0,1)), sum(newborn_parent_share(:,1,1)), &
                    sum(newborn_parent_share(:,0,2)), sum(newborn_parent_share(:,1,2))
                write(*,*) "newborn_productivity_draw=", newborn_productivity_draw(:)
                write(*,*) "newborn_employment_probability, clean housed, parent at the median node=", &
                    newborn_employment_probability(:,(employment_grid_size+1)/2,0,1)
                write(*,*) "newborn_employment_probability, disordered housed, parent at the median node=", &
                    newborn_employment_probability(:,(employment_grid_size+1)/2,1,1)

                newborn_smi_at_birth=0

                if ((number_of_smi_states>1) .AND. (allocated(smi_prevalence_by_age))) then

                    newborn_smi_at_birth=smi_prevalence_by_age(1)

                end if

                ! EVERY NEWBORN ENTERS EMPLOYED. Reverted 5 September on the
                ! author's instruction: *"actually, no revert to no unemployment
                ! for newborns"*.
                !
                ! Entry at the unconditional joblessness rate was implemented
                ! earlier the same hour -- 13.93 per cent of each cohort arriving in
                ! state 2, read from unemployment_rate_data so it tracked the target
                ! -- and REVERTED BEFORE ANY POINT LANDED. There is therefore NO
                ! MEASUREMENT of what it does, and nothing here should be read as
                ! one.
                !
                ! What prompted it stands regardless and is worth keeping: because
                ! the whole cohort enters employed AND with zero assets -- renter
                ! wealth is 0.00000 at data age 26 -- "no assets and no income" is a
                ! state this model cannot reach. A household must work at least one
                ! period, and save out of it, before unemployment can touch it:
                ! 0.109 of average income by 27, 0.414 by 30. Age 26 is the only age
                ! at which every household has zero wealth and also the only age
                ! with exactly zero homelessness.
                newborn_state_draw(:)=0
                newborn_state_draw(idx_of(1,0,0))=1-newborn_smi_at_birth

                if (number_of_smi_states>1) then

                    newborn_state_draw(idx_of(1,1,0))=newborn_smi_at_birth

                end if

                do future_employment_index=1,employment_grid_size
            
                    do future_unemployment_index=1,threshold_addiction_index
                                
                        if (include_exogenous_endowment==1) then
                    
                            distribution_implied_private(1)%vector_cpu_real(1,1,&
                                initial_endowment(future_employment_index),&
                                future_unemployment_index,future_employment_index,0,0)=&
                                fraction_with_positive_wealth(future_employment_index)*&
                                newborn_productivity_draw(future_employment_index)*&
                                newborn_state_draw(future_unemployment_index)
                                                                                                
                        end if
                        
                        distribution_implied_private(1)%vector_cpu_real(1,1,&
                            negative_financial_grid_size,future_unemployment_index,&
                            future_employment_index,0,0)=&
                            (1-fraction_with_positive_wealth(future_employment_index))*&
                            newborn_productivity_draw(future_employment_index)*&    
                            newborn_state_draw(future_unemployment_index)
                            
                    end do
                        
                end do
            
            else
            
                do m=1,2
                
                    do age_index=loop_only_over_oldest*life_span+(1-loop_only_over_oldest)*1,life_span
                                                                            
                        if (age_index==1) then
                    
                            newborn_household=1
                                                
                        else
                    
                            newborn_household=0
                        
                        end if
                    
                        do years_left_on_mortgage_index=1,newborn_household*1+(1-newborn_household)*max_amortization_years
                                                
                            if (years_left_on_mortgage_index>1) then
                            
                                has_house=1
                                
                            else
                            
                                has_house=0
                                
                            end if
                            
                            track_housing_1=1
                            
                            if (has_house==0) then
                            
                                if (track_renters_housing==0) then
                                
                                    track_housing_1=0
                                    
                                end if
                                
                            end if
                                                                    
                            do unemployment_index=1,unemployment_grid_size
                            
                                do employment_index=1,employment_grid_size

                                    do voucher_index=0,(1-has_house)*include_vouchers
                                                                  
                                        !$omp parallel do default(none) &
                                        !$omp& shared(distribution_implied_private,distribution_guess,&
                                        !$omp& frac_mov_optimal_1,fin_index_frac_mov_to_optimal,policy_function_addiction,&
                                        !$omp& policy_function_financial_index,policy_function_years_of_amortization_index,&
                                        !$omp& policy_function_housing_status_index,initial_endowment,&
                                        !$omp& m,time_period,has_mortgage,at_least_one_period_before_retirement,&
                                        !$omp& has_house,survival_probability,unemployment_process,newborn_household,&
                                        !$omp& newborn_unemployment_process,&
                                        !$omp& unconditional_employment_probability,fraction_with_positive_wealth,&
                                        !$omp& newborn_employment_probability,&
                                        !$omp& age_index,years_left_on_mortgage_index,unemployment_index,employment_index,&
                                        !$omp& index_of_smallest_house_hhld_can_buy,financial_grid,voucher_index,&
                                        !$omp& value_of_initial_assets,track_housing_1,addiction_probabilities,&
                                        !$omp& policy_function_frac_spent_on_addiction,policy_function_total_consumption,&
                                        !$omp& price_of_addictive_good,policy_function_treatment,&
                                        !$omp& is_addicted_1,survival_probability_for_dist_iteration,renter_floor_by_age)
                                                                                            
                                        do financial_index=newborn_household*negative_financial_grid_size+&
                                            (1-newborn_household)*(has_house*1+(1-has_house)*renter_floor_by_age(min(max(age_index,1),life_span))),&
                                            include_exogenous_endowment*financial_grid_size+&
                                            (1-include_exogenous_endowment)*(newborn_household*negative_financial_grid_size+&
                                            (1-newborn_household)*financial_grid_size)
                                    
                                            thread_num=0
                                            !$ thread_num=omp_get_thread_num()
                    
                                            do housing_status_index=(1-has_house)*lowest_housing_grid_point+&
                                                has_house*index_of_smallest_house_hhld_can_buy,&
                                                track_housing_1*(1-newborn_household)*(housing_status_grid_size-1)
                                                                                                                
                                                if (policy_function_years_of_amortization_index(years_left_on_mortgage_index)%&
                                                    vector_transition_integer(time_period,age_index,financial_index,&
                                                    unemployment_index,employment_index,housing_status_index,voucher_index)>1) then
                                                    
                                                    choose_to_own=1
                                                    
                                                else
                                                
                                                    choose_to_own=0
                                                    
                                                end if
                                                
                                                if (m==1) then
                                                            
                                                    financial_index_copy=policy_function_financial_index&
                                                        (years_left_on_mortgage_index)%&
                                                        vector_transition_integer(time_period,age_index,financial_index,&
                                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                                        
                                                    fraction_copy=1-frac_mov_optimal_1(years_left_on_mortgage_index)%&
                                                        vector_transition_real(time_period,age_index,&
                                                        financial_index,unemployment_index,employment_index,&
                                                        housing_status_index,voucher_index)
                                                    
                                                elseif (m==2) then
                                                
                                                    financial_index_copy=fin_index_frac_mov_to_optimal&
                                                        (years_left_on_mortgage_index)%&
                                                        vector_transition_integer(time_period,age_index,financial_index,&
                                                        unemployment_index,employment_index,housing_status_index,voucher_index)
                                                        
                                                    fraction_copy=frac_mov_optimal_1(years_left_on_mortgage_index)%&
                                                        vector_transition_real(time_period,age_index,&
                                                        financial_index,unemployment_index,employment_index,&
                                                        housing_status_index,voucher_index)
                                                
                                                end if
                                                
                                                future_housing_status_index_to_use_2=&
                                                    policy_function_housing_status_index(years_left_on_mortgage_index)%&
                                                    vector_transition_integer(time_period,age_index,financial_index,&
                                                    unemployment_index,employment_index,housing_status_index,voucher_index)
                                                                                                    
                                                is_homeless_2=1
                                                                                                
                                                if (future_housing_status_index_to_use_2==lowest_housing_grid_point) then
                                                
                                                    is_homeless_2=2
                                                
                                                end if
                                                
                                                addiction_choice_1=&
                                                    policy_function_addiction(years_left_on_mortgage_index)%&
                                                    vector_transition_integer(time_period,age_index,financial_index,&
                                                    unemployment_index,employment_index,housing_status_index,voucher_index)

                                                treatment_choice_dist_1=&
                                                policy_function_treatment(years_left_on_mortgage_index)%&
                                                vector_transition_integer(time_period,age_index,financial_index,&
                                                unemployment_index,employment_index,housing_status_index,voucher_index)

                                            drug_quantity_dist_1=&
                                                    (policy_function_frac_spent_on_addiction(years_left_on_mortgage_index)%&
                                                    vector_transition_real(time_period,age_index,financial_index,&
                                                    unemployment_index,employment_index,housing_status_index,voucher_index)*&
                                                    policy_function_total_consumption(years_left_on_mortgage_index)%&
                                                    vector_transition_real(time_period,age_index,financial_index,&
                                                    unemployment_index,employment_index,housing_status_index,voucher_index))/&
                                                    price_of_addictive_good
                                                
                                                is_addicted_1=0
                                                loop_over_addiction_2=0
                                                
                                                if (unemployment_index>threshold_addiction_index) then
                                                
                                                    is_addicted_1=1
                                                    loop_over_addiction_2=1
                                                    
                                                elseif ((addiction_choice_1>=1) .AND. &
                                                    (include_probability_of_becoming_addicted==1)) then
                                                
                                                    loop_over_addiction_2=1
                                                    
                                                end if
                                                
                                                ! NEWBORNS ARE BORN CLEAN, SO THE SUD INDEX IS ZERO.
                                                !
                                                ! These bounds used to add
                                                ! (1-newborns_inherit_addiction), which pins the index at
                                                ! ONE when newborns do not inherit the disorder, that is
                                                ! at the SUD state. The transition array is non-zero only
                                                ! where sud_of(j) agrees with this index, and the
                                                ! future_unemployment_index loop below runs over the CLEAN
                                                ! block, so every newborn term was multiplied by a zero
                                                ! weight and the newborn push contributed nothing at all.
                                                !
                                                ! Measured at startup: the array sums to one over the clean
                                                ! block at index zero and to exactly zero at index one,
                                                ! which is what the loop was asking for.
                                                !
                                                ! The age one row was therefore whatever
                                                ! initialize_feasible_distribution had left there, all of it
                                                ! on a single clean employed state. That is why age one SMI
                                                ! prevalence read exactly 0.00000 against a profile of
                                                ! 0.12719, and why prevalence overall came out near two per
                                                ! cent against a profile averaging five: mental illness was
                                                ! built up by onset from age two alone, with nobody ever
                                                ! born carrying it. It also means the age one cross section
                                                ! did not respond to the newborn productivity draw or to
                                                ! anything else in the transition.
                                                do future_addiction_index_2=&
                                                    newborns_inherit_addiction*((1-loop_over_addiction_2)*addiction_choice_1+& 
                                                    loop_over_addiction_2*0),& 
                                                    newborns_inherit_addiction*((1-loop_over_addiction_2)*addiction_choice_1+& 
                                                    loop_over_addiction_2*include_addiction)
                                                    
                                                    check_2=0
                                                    
                                                    if (future_addiction_index_2==1) then
                                                    
                                                        check_2=1
                                                        
                                                    end if
                                        
                                                    do future_unemployment_index=&
                                                        newborns_inherit_addiction*include_addiction*&
                                                        ((1-check_2)*1+check_2*(threshold_addiction_index+1))+&
                                                        (1-newborns_inherit_addiction),newborns_inherit_addiction*&
                                                        (include_addiction*((1-check_2)*threshold_addiction_index+&
                                                        check_2*unemployment_grid_size)+(1-include_addiction)*&
                                                        unemployment_grid_size)+&
                                                        (1-newborns_inherit_addiction)*threshold_addiction_index
                                                                                                                                                          
                                                        do future_employment_index=1,employment_grid_size
                                                                                                                                                                                        
                                                            if (include_exogenous_endowment==1) then
                                                                                                                                                                        
                                                                distribution_implied_private(1)%vector_cpu_real(thread_num+1,1,&
                                                                    initial_endowment(future_employment_index),&
                                                                    future_unemployment_index,future_employment_index,0,0)=&
                                                                    fraction_copy*&
                                                                    (1-survival_probability_for_dist_iteration(age_index,1,0,0))*&
                                                                    fraction_with_positive_wealth(employment_index)*&
                                                                    newborn_employment_probability(future_employment_index,&
                                                                    employment_index,is_addicted_1,is_homeless_2)*&
                                                                    newborn_unemployment_process(age_index,unemployment_index,&
                                                                    future_unemployment_index,is_homeless_2,&
                                                                    future_addiction_index_2,employment_index)*&
                                                                    addiction_transition(is_addicted_1,&
                                                                    future_addiction_index_2,addiction_choice_1,is_homeless_2,&
                                                                    drug_quantity_dist_1,0,treatment_choice_dist_1)*& 
                                                                    distribution_guess(years_left_on_mortgage_index)%&
                                                                    vector_transition_real(time_period-solve_transition_dynamics,&
                                                                    age_index,financial_index,unemployment_index,employment_index,&
                                                                    housing_status_index,voucher_index)+&
                                                                    distribution_implied_private(1)%&
                                                                    vector_cpu_real(thread_num+1,1,initial_endowment&
                                                                    (future_employment_index),future_unemployment_index,&
                                                                    future_employment_index,0,0)

                                                            end if
                                                                                                                    
                                                            distribution_implied_private(1)%vector_cpu_real(thread_num+1,1,&
                                                                negative_financial_grid_size,future_unemployment_index,&
                                                                future_employment_index,0,0)=fraction_copy*&
                                                                (1-survival_probability_for_dist_iteration(age_index,1,0,0))*&
                                                                (1-fraction_with_positive_wealth(employment_index))*&
                                                                newborn_employment_probability(future_employment_index,&
                                                                employment_index,is_addicted_1,is_homeless_2)*&
                                                                newborn_unemployment_process(age_index,unemployment_index,&
                                                                future_unemployment_index,is_homeless_2,future_addiction_index_2,&
                                                                employment_index)*addiction_transition(is_addicted_1,&
                                                                future_addiction_index_2,addiction_choice_1,is_homeless_2,&
                                                                drug_quantity_dist_1,0,treatment_choice_dist_1)*&
                                                                distribution_guess(years_left_on_mortgage_index)%&
                                                                vector_transition_real&
                                                                (time_period-solve_transition_dynamics,age_index,financial_index,&
                                                                unemployment_index,employment_index,housing_status_index,&
                                                                voucher_index)+distribution_implied_private(1)%vector_cpu_real&
                                                                (thread_num+1,1,negative_financial_grid_size,&
                                                                future_unemployment_index,future_employment_index,0,0)
                                                                                                                                                                                                                                                                                            
                                                        end do
                                                                
                                                    end do
                                                    
                                                end do 
                                                                                                    
                                            end do
                                        
                                        end do
                                                                        
                                        !$omp end parallel do

                                    end do            
                                    
                                end do
                                
                            end do
                    
                        end do
                                    
                    end do
                
                end do
                
            end if
            
            if (solve_transition_dynamics>=0) then
            
                number_of_threads_used=max_CPUs
            ! max_CPUs stays a compile-time parameter because it dimensions vector_cpu_real.
            ! Use it only as an upper bound; take the actual thread count from the runtime so
            ! the same binary is correct on a 4-core laptop and a 40-core server. Honours
            ! OMP_NUM_THREADS when set.
            !$ number_of_threads_used=max(1,min(max_CPUs,omp_get_max_threads()))

                CALL OMP_SET_NUM_THREADS(number_of_threads_used)
        
                !$omp parallel
                !$omp master
                !$ total_number_of_threads=omp_get_num_threads()
                !$omp end master
                !$omp end parallel
                    
            end if
                        
            do age_index=1,life_span
            
                if (age_index==1) then
                
                    newborn_household=1
                    
                else
                
                    newborn_household=0
                    
                end if
                                                      
                do years_left_on_mortgage_index=1,newborn_household*1+(1-newborn_household)*max_amortization_years
                
                    if (years_left_on_mortgage_index>1) then
                    
                        has_house=1
                        
                    else
                    
                        has_house=0
                        
                    end if
                    
                    track_housing_1=1
                        
                    if (has_house==0) then
                    
                        if (track_renters_housing==0) then
                        
                            track_housing_1=0
                            
                        end if
                        
                    end if
                                    
                    do unemployment_index=1,unemployment_grid_size
                    
                        do employment_index=1,employment_grid_size
                        
                            do voucher_index=0,(1-has_house)*include_vouchers
                                            
                                !$omp parallel do default(none) &
                                !$omp& shared(distribution_implied_private,distribution_implied,track_housing_1,&
                                !$omp& total_number_of_threads,time_period,age_index,has_mortgage,has_house,&
                                !$omp& years_left_on_mortgage_index,newborn_household,&
                                !$omp& unemployment_index,employment_index,voucher_index,index_of_smallest_house_hhld_can_buy,&
                                !$omp& renter_floor_by_age)
                                                                                    
                                do financial_index=newborn_household*negative_financial_grid_size+&
                                    (1-newborn_household)*(has_house*1+(1-has_house)*renter_floor_by_age(min(max(age_index,1),life_span))),&
                                    include_exogenous_endowment*financial_grid_size+(1-include_exogenous_endowment)*&
                                    (newborn_household*negative_financial_grid_size+(1-newborn_household)*financial_grid_size)
                                
                                    do housing_status_index=(1-has_house)*lowest_housing_grid_point+&
                                        has_house*index_of_smallest_house_hhld_can_buy,&
                                        track_housing_1*(1-newborn_household)*(housing_status_grid_size-1)
                                                                                                                                                           
                                        do thread_index=1,total_number_of_threads ! 1
                                
                                            distribution_implied(years_left_on_mortgage_index)%vector_transition_real&
                                                (time_period,age_index,financial_index,unemployment_index,&
                                                employment_index,housing_status_index,voucher_index)=&
                                                distribution_implied(years_left_on_mortgage_index)%vector_transition_real&
                                                (time_period,age_index,financial_index,unemployment_index,&
                                                employment_index,housing_status_index,voucher_index)+&
                                                distribution_implied_private(years_left_on_mortgage_index)%vector_cpu_real&
                                                (thread_index,age_index,financial_index,unemployment_index,&
                                                employment_index,housing_status_index,voucher_index)
                                                
                                        end do
                                        
                                    end do
                                    
                                end do
                                                        
                                !$omp end parallel do
                                
                            end do
                            
                        end do
                        
                    end do
                                        
                end do
                                
            end do
            
            value_of_initial_assets=0

            if (include_exogenous_endowment==1) then
            
                do employment_index=1,employment_grid_size
                
                    do unemployment_index=1,unemployment_grid_size
                
                        value_of_initial_assets=value_of_initial_assets+&
                            distribution_implied(1)%vector_transition_real(thread_num+1,1,&
                            initial_endowment(employment_index),unemployment_index,employment_index,0,0)*&
                            financial_grid(initial_endowment(employment_index))
                            
                    end do
                
                end do

            end if

            if (solve_transition_dynamics==0) then
            
                distance_distribution=0
            
                do i=1,2
            
                    if (maxval(abs(distribution_implied(i)%vector_transition_real(time_period,:,:,:,:,:,:)-&
                        distribution_guess(i)%vector_transition_real(time_period,:,:,:,:,:,:)))>distance_distribution) then
                        
                        distance_distribution=&
                            maxval(abs(distribution_implied(i)%vector_transition_real(time_period,:,:,:,:,:,:)-&
                            distribution_guess(i)%vector_transition_real(time_period,:,:,:,:,:,:)))
                            
                    end if
                        
                end do
                    
            else
            
                distance_distribution=0
                    
            end if

            distance_distribution_reached=distance_distribution

            ! WHERE THE WORST CELL IS AND WHETHER THE MOMENTS STILL MOVE,
            ! every hundredth sweep.
            !
            ! TWO QUESTIONS, AND THE SECOND IS THE ONE THAT MATTERS. The first is
            ! whether the max is pinned to one state or wanders, which tells an
            ! oscillating knife edge apart from a distribution still propagating.
            ! The second is whether the AGGREGATES have stopped moving while the
            ! max has not. The stopping rule is a max over cells of a difference
            ! in LEVELS, and the calibration does not read a cell: it reads
            ! integrals. A max of 2e-3 in a distribution carrying mass 51 can sit
            ! on top of aggregates that are stable to five decimal places, and if
            ! it does then the rule is testing the wrong thing and a solve that
            ! runs 4000 sweeps was finished at 100.
            !
            ! THE INDICES HAVE TO BE PUT BACK. maxloc on an array EXPRESSION
            ! returns positions counted from one, and this array does not start
            ! at one in any of its dimensions: assets run from
            ! negative_financial_grid_size, housing from lowest_housing_grid_point
            ! and vouchers from zero. Reading the mass at the raw maxloc is
            ! reading a different cell, and for assets it is outside the array
            ! altogether. The first version of this did exactly that.
            if ((diagnose_distribution_max==1) .AND. (solve_transition_dynamics==0) .AND. &
                (mod(loop_count_dist,100)==0)) then

                do i=1,2

                    dist_argmax_1=maxloc(abs(&
                        distribution_implied(i)%vector_transition_real(time_period,:,:,:,:,:,:)-&
                        distribution_guess(i)%vector_transition_real(time_period,:,:,:,:,:,:)))

                    do dist_dim_1=1,6

                        dist_argmax_1(dist_dim_1)=dist_argmax_1(dist_dim_1)+&
                            lbound(distribution_guess(i)%vector_transition_real,dist_dim_1+1)-1

                    end do

                    write(*,*) "DIST_MAX sweep=", loop_count_dist, " block=", i, &
                        " age=", dist_argmax_1(1), " fin=", dist_argmax_1(2), &
                        " uem=", dist_argmax_1(3), " emp=", dist_argmax_1(4), &
                        " hou=", dist_argmax_1(5), " vch=", dist_argmax_1(6), &
                        " gap=", maxval(abs(&
                        distribution_implied(i)%vector_transition_real(time_period,:,:,:,:,:,:)-&
                        distribution_guess(i)%vector_transition_real(time_period,:,:,:,:,:,:))), &
                        ! CLAMPED, AND NOT ONLY FOR THIS GRID. dist_argmax_1 is
                        ! built as maxloc + lbound - 1, and maxloc returns ZERO for
                        ! a degenerate slice, so the index becomes lbound-1 and the
                        ! read is illegal BY CONSTRUCTION whenever that happens. It
                        ! is latent at any grid size; the one-rental run is simply
                        ! what made it happen, and the -fcheck=bounds build named
                        ! it as index -1 of dimension 7 below a lower bound of 0.
                        ! The -O3 build had segfaulted here with no explanation.
                        !
                        ! This is a DIAGNOSTIC write and nothing downstream reads
                        ! it, so clamping each index into its own bound is the
                        ! whole fix: a degenerate slice now prints the corner cell
                        ! instead of killing a solve that had run for two minutes.
                        ! THE mass_there TERM IS GONE, and it is not coming back
                        ! as another clamp. Indexing this array by an argmax has
                        ! now killed FIVE runs: first as index -1 of dimension 7
                        ! below a lower bound of 0, and then -- after every index
                        ! was clamped with max(argmax, lbound) -- as index 1 of
                        ! dimension 6 below a lower bound of 2, which that clamp
                        ! cannot produce. Whatever dist_argmax_1 holds, it does
                        ! not map onto this array's dimensions the way the write
                        ! assumed, and a diagnostic is not worth a sixth run to
                        ! find out.
                        !
                        ! Nothing downstream reads it. The gap above is the number
                        ! the sweep is actually watched on; the cell's own mass was
                        ! decoration. maxval of the slice gives the same reassurance
                        ! with no indexing at all.
                        " max_mass=", maxval(distribution_guess(i)%vector_transition_real(time_period,:,:,:,:,:,:))

                end do

                ! THE AGGREGATES, on the implied distribution, to fifteen digits
                ! so that "stopped moving" can be read off two consecutive lines
                ! rather than guessed at. Mass by housing status is the closest
                ! cheap stand-in for the moments the calibration brackets on: the
                ! homelessness rate and the size distribution are both built out
                ! of these sums, and the mean asset holding drives the wealth
                ! target.
                dist_mass_1=0
                dist_wealth_1=0
                dist_housing_1(:)=0

                do i=1,2

                    dist_mass_1=dist_mass_1+&
                        sum(distribution_implied(i)%vector_transition_real(time_period,:,:,:,:,:,:))

                    do dist_dim_1=lbound(distribution_implied(i)%vector_transition_real,6),&
                        ubound(distribution_implied(i)%vector_transition_real,6)

                        dist_housing_1(dist_dim_1)=dist_housing_1(dist_dim_1)+&
                            sum(distribution_implied(i)%vector_transition_real&
                            (time_period,:,:,:,:,dist_dim_1,:))

                    end do

                    do dist_dim_1=lbound(distribution_implied(i)%vector_transition_real,3),&
                        ubound(distribution_implied(i)%vector_transition_real,3)

                        dist_wealth_1=dist_wealth_1+max(financial_grid(dist_dim_1),0.d0)*&
                            sum(distribution_implied(i)%vector_transition_real&
                            (time_period,:,dist_dim_1,:,:,:,:))

                    end do

                end do

                write(*,'(A,I6,A,F22.15,A,F22.15,A,3F22.15)') " DIST_MOM sweep=", &
                    loop_count_dist, " mass=", dist_mass_1, " wealth=", dist_wealth_1, &
                    " by_housing=", dist_housing_1(:)

            end if
                        
            do i=1,2
            
                if (minval(distribution_implied(i)%vector_transition_real(:,:,:,:,:,:,:))<0) then
                
                    write(*,*) "minval distribution_implied=", minval(distribution_implied(i)%vector_transition_real(:,:,:,:,:,:,:))            
                
                end if
                
            end do
            
            sum_distribution_implied=0
            sum_distribution_guess=0
                                    
            do i=1,2
            
                sum_distribution_implied=sum_distribution_implied+&
                    sum(distribution_implied(i)%vector_transition_real(time_period,:,:,:,:,:,:))
            
                sum_distribution_guess=sum_distribution_guess+&
                    sum(distribution_guess(i)%vector_transition_real(time_period-solve_transition_dynamics,:,:,:,:,:,:))
            
            end do
                        
            if ((abs(sum_distribution_guess-sum_distribution_implied)>10.d0**(-10)) .AND. &
                (have_probablistic_death==0)) then
                                
                write(*,*) "sum(distribution_guess(",time_period,")=", sum_distribution_guess
                                                            
                write(*,*) "sum(distribution_implied(",time_period,")=", sum_distribution_implied
                    
            end if
                                    
            if (solve_transition_dynamics==0) then
                
                write(*,*) "distribution distance=", distance_distribution
                
            end if
                
            ! AITKEN EXTRAPOLATION ON THE WHOLE DISTRIBUTION.
            !
            ! This iteration contracts at roughly the per period survival rate,
            ! because mass turns over once per lifetime and there is nothing
            ! faster in the operator. That is a contraction factor near 0.99, so
            ! it takes hundreds of sweeps, and the last two orders of magnitude
            ! cost as much as everything before them. It was four fifths of a
            ! calibration loop.
            !
            ! Three successive iterates of a linearly converging sequence
            ! identify the limit: with d1 = x1 - x0 and d2 = x2 - x1, the ratio
            ! d2/d1 is the contraction factor and x2 + d2*rho/(1-rho) is the
            ! limit. Applied elementwise to the whole distribution it is the
            ! standard delta squared step.
            !
            ! IT IS GUARDED THREE WAYS, because an extrapolation that overshoots
            ! into negative mass would be far worse than a slow iteration. The
            ! step is taken only when the estimated rho is in (0,1) and bounded
            ! away from one, only every third iteration so the two intervening
            ! plain sweeps re-establish the sequence, and the result is
            ! rejected outright if it produces negative mass or changes the total
            ! by more than a part in a thousand. A rejected step costs one
            ! wasted vector operation and the iteration carries on exactly as it
            ! would have.
            if (accelerate_distribution==1) then

                do i=1,2

                    dist_prev_2(i)%vector_transition_real(time_period,:,:,:,:,:,:)=&
                        dist_prev_1(i)%vector_transition_real(time_period,:,:,:,:,:,:)

                    dist_prev_1(i)%vector_transition_real(time_period,:,:,:,:,:,:)=&
                        distribution_guess(i)%vector_transition_real(time_period,:,:,:,:,:,:)

                end do

            end if

            do i=1,2
                
                distribution_guess(i)%vector_transition_real(time_period,:,:,:,:,:,:)=&
                    distribution_implied(i)%vector_transition_real(time_period,:,:,:,:,:,:)
                    
            end do

            if ((accelerate_distribution==1) .AND. (loop_count_dist>=3) .AND. &
                (mod(loop_count_dist,3)==0)) then

                call aitken_on_distribution(time_period)

            end if
                        
            loop_count_dist=loop_count_dist+1
            
            if (partial_equilibrium==1) then
            
                distance_distribution=1
            
                if (loop_count_dist==how_many_iterations_to_do_on_distribution) then
                
                    distance_distribution=0
                
                end if
                
            end if

            ! STOP RATHER THAN SPIN. See max_distribution_sweeps above. The loop
            ! carries on with the best distribution it reached, which is what the
            ! caller would have got from another thousand sweeps anyway, and says
            ! so loudly enough to be greppable.
            if (loop_count_dist>=max_distribution_sweeps) then

                if (distance_distribution>distribution_alarm_distance) then

                    write(*,*) "DIST_STALL: gave up after ", loop_count_dist, &
                        " sweeps with distance ", distance_distribution, &
                        " against a stopping rule of ", stopping_rule_stationary_distribution

                end if

                distance_distribution=0

            end if
                       
        end do
        
        ! WHAT THE DISTRIBUTION COST AND WHAT IT REACHED, one line a loop, so a
        ! sweep count that is creeping up across calibration loops is visible
        ! before it becomes a run that never ends.
        if (solve_transition_dynamics==0) then

            write(*,*) "DIST_DONE sweeps=", loop_count_dist, &
                " final_distance=", distance_distribution_reached

        end if

        if ((partial_equilibrium==0) .OR. (how_many_iterations_to_do_on_distribution>0)) then
        
            do i=1,2
                   
                distribution_stationary(i)%vector_transition_real(time_period,:,:,:,:,:,:)=&
                    distribution_implied(i)%vector_transition_real(time_period,:,:,:,:,:,:)

            end do

        end if

    end subroutine

    subroutine aitken_on_distribution(time_period)

        ! Delta squared on three successive iterates, elementwise, with the
        ! contraction factor estimated from the sums rather than pointwise. A
        ! pointwise rho is noisy where the mass is near zero and would produce
        ! wild extrapolations in exactly the states that matter least; the sums
        ! are dominated by the states that carry mass, which is where the
        ! sequence's actual convergence rate lives.

        use Global_Vars

        implicit none

        integer, intent(in) :: time_period
        integer :: i_1
        real(8) :: d1_1,d2_1,contraction_1,total_before_1,total_after_1,worst_1

        d1_1=0
        d2_1=0
        total_before_1=0

        do i_1=1,2

            d1_1=d1_1+sum(abs(dist_prev_1(i_1)%vector_transition_real(time_period,:,:,:,:,:,:)-&
                dist_prev_2(i_1)%vector_transition_real(time_period,:,:,:,:,:,:)))

            d2_1=d2_1+sum(abs(distribution_guess(i_1)%vector_transition_real(time_period,:,:,:,:,:,:)-&
                dist_prev_1(i_1)%vector_transition_real(time_period,:,:,:,:,:,:)))

            total_before_1=total_before_1+&
                sum(distribution_guess(i_1)%vector_transition_real(time_period,:,:,:,:,:,:))

        end do

        if ((d1_1<=10.d0**(-30)) .OR. (d2_1<=10.d0**(-30))) return

        contraction_1=d2_1/d1_1

        ! Only extrapolate a sequence that is actually contracting, and not one
        ! so close to one that the step becomes enormous.
        if ((contraction_1<=0) .OR. (contraction_1>=0.999)) return

        do i_1=1,2

            dist_prev_2(i_1)%vector_transition_real(time_period,:,:,:,:,:,:)=&
                distribution_guess(i_1)%vector_transition_real(time_period,:,:,:,:,:,:)+&
                (contraction_1/(1-contraction_1))*&
                (distribution_guess(i_1)%vector_transition_real(time_period,:,:,:,:,:,:)-&
                dist_prev_1(i_1)%vector_transition_real(time_period,:,:,:,:,:,:))

        end do

        worst_1=0
        total_after_1=0

        do i_1=1,2

            worst_1=min(worst_1,minval(dist_prev_2(i_1)%vector_transition_real(time_period,:,:,:,:,:,:)))
            total_after_1=total_after_1+sum(dist_prev_2(i_1)%vector_transition_real(time_period,:,:,:,:,:,:))

        end do

        ! Reject rather than repair. Negative mass or a total that has moved is
        ! a sign the sequence was not linear here, and one wasted vector
        ! operation is cheaper than a distribution that has to be trusted.
        if ((worst_1<-10.d0**(-14)) .OR. &
            (abs(total_after_1-total_before_1)>10.d0**(-3)*max(total_before_1,10.d0**(-12)))) then

            return

        end if

        do i_1=1,2

            distribution_guess(i_1)%vector_transition_real(time_period,:,:,:,:,:,:)=&
                max(dist_prev_2(i_1)%vector_transition_real(time_period,:,:,:,:,:,:),0.d0)

        end do

    end subroutine

    subroutine compute_homelessness_duration(time_period)
    
        use global_vars
        
        implicit none
        
        integer, intent(in) :: time_period
        integer :: has_house,track_housing_1,financial_index,is_addicted_1,amortization_used
        integer :: age_index_1,addiction_index_1,addiction_lower_bound,addiction_upper_bound,voucher_index_1
        real(8) :: avg_income_to_use_2,avg_income_to_use_1
        real(8), dimension(0:2) :: total_homeless_count
        
        avg_income_to_use_1=is_counterfactual*average_labor_income_calibrated+&
            (1-is_counterfactual)*model_average_labour_income(time_period)
                
        do addiction_index_1=0,2
    
            total_homeless_count(addiction_index_1)=0
            homelessness_duration_everyone(time_period,addiction_index_1)=0
    
            do age_index_1=1,life_span
                
                addiction_lower_bound=addiction_index_1
                addiction_upper_bound=addiction_index_1
            
                if (addiction_index_1==2) then
                
                    addiction_lower_bound=0
                    addiction_upper_bound=include_addiction
                    
                end if
        
                homelessness_duration(time_period,age_index_1,addiction_index_1)=0
                homelessness_mass_by_age(time_period,:)=0
                                
                do i=1,2
                
                    distribution_forward(i)%vector_transition_real(time_period,:,:,:,:,:,:)=0
                    
                    if (addiction_index_1==1) then
                    
                        do j=threshold_addiction_index+1,unemployment_grid_size
                           
                            distribution_forward(i)%vector_transition_real(time_period,age_index_1,:,j,:,:,:)=&
                                distribution_stationary(i)%vector_transition_real(time_period,age_index_1,:,j,:,:,:)
                                
                        end do
                            
                    elseif (addiction_index_1==0) then
                    
                        do j=1,threshold_addiction_index
                        
                            distribution_forward(i)%vector_transition_real(time_period,age_index_1,:,j,:,:,:)=&
                                distribution_stationary(i)%vector_transition_real(time_period,age_index_1,:,j,:,:,:)
                                
                        end do
                        
                    else
                                            
                        distribution_forward(i)%vector_transition_real(time_period,age_index_1,:,:,:,:,:)=&
                            distribution_stationary(i)%vector_transition_real(time_period,age_index_1,:,:,:,:,:)
                           
                    end if

                end do
                        
                do age_index=age_index_1,life_span
                
                    if (age_index>(life_span-retirement_span)) then
                    
                        in_retirement=1
                    
                    else
                    
                        in_retirement=0
                    
                    end if
                    
                    if (age_index>=(life_span-retirement_span)) then
                    
                        at_least_one_period_before_retirement=1
                    
                    else
                    
                        at_least_one_period_before_retirement=0
                    
                    end if
                    
                    one_period_before_death=0
                    
                    if (age_index==life_span) then
                    
                        one_period_before_death=1
                        
                    end if
                                                            
                    if (age_index==1) then
                
                        newborn_household=1
                        
                    else
                
                        newborn_household=0
                    
                    end if
                
                    do years_left_on_mortgage_index=1,newborn_household*1+(1-newborn_household)*max_amortization_years
                                            
                        if (years_left_on_mortgage_index>1) then
                        
                            has_house=1
                            
                        else
                        
                            has_house=0
                            
                        end if
                        
                        track_housing_1=1
                        
                        if (has_house==0) then
                        
                            if (track_renters_housing==0) then
                            
                                track_housing_1=0
                                
                            end if
                            
                        end if
                                
                        do unemployment_index=1,unemployment_grid_size
                        
                            do employment_index=1,employment_grid_size

                                avg_income_to_use_2=is_counterfactual*&
                                    average_labor_income_by_employment_calibrated(employment_index)+&
                                    (1-is_counterfactual)*model_average_labour_income_by_employment(time_period,employment_index)
                            
                                do voucher_index=0,(1-has_house)*include_vouchers
                                                                             !                                                                        
                                    do financial_index=newborn_household*negative_financial_grid_size+&
                                         (1-newborn_household)*(has_house*1+(1-has_house)*renter_floor_by_age(min(max(age_index,1),life_span))),&
                                         include_exogenous_endowment*financial_grid_size+(1-include_exogenous_endowment)*&
                                         (newborn_household*negative_financial_grid_size+(1-newborn_household)*financial_grid_size)
                                
                                        do housing_status_index=(1-has_house)*lowest_housing_grid_point+&
                                            has_house*index_of_smallest_house_hhld_can_buy,&
                                            track_housing_1*(1-newborn_household)*(housing_status_grid_size-1) 
                                            
                                            if (policy_function_years_of_amortization_index(years_left_on_mortgage_index)%&
                                                vector_transition_integer(time_period,age_index,financial_index,&
                                                unemployment_index,employment_index,housing_status_index,voucher_index)>1) then
                                                
                                                choose_to_own=1
                                                
                                            else
                                            
                                                choose_to_own=0
                                                
                                            end if
                                            
                                            income_to_use_4=2*((1-is_counterfactual)*median_income(time_period)+&
                                                is_counterfactual*median_income_calibrated)

                                            if (choose_to_own==0) then

                                                labor_supply_to_use=&
                                                    policy_function_labor_supply(years_left_on_mortgage_index)%&
                                                    vector_transition_real(time_period,age_index,financial_index,&
                                                    unemployment_index,employment_index,housing_status_index,voucher_index)

                                                call calculate_income(unemployment_index,employment_index,income_to_use_4,&
                                                    avg_income_to_use_1,avg_income_to_use_2,labor_supply_to_use,in_retirement)

                                                income_to_use_4=income_to_use_4+&
                                                    (risk_free_rate(time_period)*max(financial_grid(financial_index),0.d0)+unsecured_borrowing_rate*min(financial_grid(financial_index),0.d0))

                                            end if
                                            
                                            track_housing_2=1
                                            
                                            if (choose_to_own==0) then
                                            
                                                if (track_renters_housing==0) then
                                                
                                                    track_housing_2=0
                                                    
                                                end if
                                                
                                            end if
                                            
                                            if (m==1) then
                                                    
                                                financial_index_copy=policy_function_financial_index&
                                                    (years_left_on_mortgage_index)%vector_transition_integer&
                                                    (time_period,age_index,financial_index,unemployment_index,&
                                                    employment_index,housing_status_index,voucher_index)
                                                    
                                                fraction_copy=(1-frac_mov_optimal_1(years_left_on_mortgage_index)%&
                                                    vector_transition_real(time_period,age_index,&
                                                    financial_index,unemployment_index,employment_index,&
                                                    housing_status_index,voucher_index))
                                                                                                    
                                            elseif (m==2) then
                                            
                                                financial_index_copy=fin_index_frac_mov_to_optimal&
                                                    (years_left_on_mortgage_index)%vector_transition_integer&
                                                    (time_period,age_index,financial_index,unemployment_index,&
                                                    employment_index,housing_status_index,voucher_index)
                                                    
                                                fraction_copy=frac_mov_optimal_1(years_left_on_mortgage_index)%&
                                                    vector_transition_real(time_period,&
                                                    age_index,financial_index,unemployment_index,employment_index,&
                                                    housing_status_index,voucher_index)
                                                                                                                                                                                                                                                           
                                            end if

                                            amortization_used_dist=policy_function_years_of_amortization_index&
                                                (years_left_on_mortgage_index)%vector_transition_integer&
                                                (min(time_period,transition_length),age_index,financial_index,&
                                                unemployment_index,employment_index,housing_status_index,voucher_index)
                                                
                                            future_housing_status_index_to_use_2=&
                                                policy_function_housing_status_index(years_left_on_mortgage_index)%&
                                                vector_transition_integer(time_period,age_index,financial_index,&
                                                unemployment_index,employment_index,housing_status_index,voucher_index)
                                                
                                            if (track_housing_2==0) then
                                            
                                                if (future_housing_status_index_to_use_2>second_lowest_housing_grid_point) then
                                                
                                                    future_housing_status_index_to_use_2=0
                                                    
                                                end if
                                                
                                            end if
                                            
                                            is_homeless_2=1
                                            
                                            if (future_housing_status_index_to_use_2==lowest_housing_grid_point) then
                                            
                                                is_homeless_2=2
                                            
                                            end if
                                            
                                            call compute_voucher_index_1(is_homeless_2,voucher_index_1)
                                            
                                            call calculate_future_voucher_index_and_opportunity&
                                                (has_opportunity_2,first_voucher_index_1,second_voucher_index_1,&
                                                time_period,has_house,choose_to_own,voucher_index_1,income_to_use_4)
                                                
                                            addiction_choice_1=&
                                                policy_function_addiction(years_left_on_mortgage_index)%&
                                                vector_transition_integer(time_period,age_index,financial_index,&
                                                unemployment_index,employment_index,housing_status_index,voucher_index)

                                            treatment_choice_dist_1=&
                                                policy_function_treatment(years_left_on_mortgage_index)%&
                                                vector_transition_integer(time_period,age_index,financial_index,&
                                                unemployment_index,employment_index,housing_status_index,voucher_index)

                                            drug_quantity_dist_1=&
                                                (policy_function_frac_spent_on_addiction(years_left_on_mortgage_index)%&
                                                vector_transition_real(time_period,age_index,financial_index,&
                                                unemployment_index,employment_index,housing_status_index,voucher_index)*&
                                                policy_function_total_consumption(years_left_on_mortgage_index)%&
                                                vector_transition_real(time_period,age_index,financial_index,&
                                                unemployment_index,employment_index,housing_status_index,voucher_index))/&
                                                price_of_addictive_good
                                                
                                            is_addicted_1=0                                                
                                            loop_over_addiction_2=0
                                                                                                                                                                                   
                                            if (unemployment_index>threshold_addiction_index) then
                                            
                                                is_addicted_1=1
                                                loop_over_addiction_2=1
                                                
                                            elseif ((addiction_choice_1>=1) .AND. &
                                                (unemployment_index<=threshold_addiction_index) .AND. &
                                                (include_probability_of_becoming_addicted==1)) then
                                                
                                                loop_over_addiction_2=1
                                                
                                            end if
                                                         
                                            ! Either the household is at the age and addiction status of interest and do not start as homeless, 
                                            ! and then chooe to be homeless 
                                            ! or they are older, and are starting as homeless and also choose to be homeless
                                            if (((age_index==age_index_1) .AND. &
                                                (is_homeless_2==2) .AND. (is_addicted_1>=addiction_lower_bound) .AND. &
                                                (is_addicted_1<=addiction_upper_bound) .AND. &
                                                (housing_status_index>lowest_housing_grid_point)) .OR. &
                                                ((age_index>age_index_1) .AND. (is_homeless_2==2) .AND. &
                                                (housing_status_index==lowest_housing_grid_point))) then
                                                                                                                                
                                                do future_addiction_index_2=&
                                                    (1-loop_over_addiction_2)*addiction_choice_1+loop_over_addiction_2*0,&
                                                    (1-loop_over_addiction_2)*addiction_choice_1+&
                                                    loop_over_addiction_2*include_addiction
                                                    
                                                    check_2=0
                                                    
                                                    if (future_addiction_index_2==1) then
                                                    
                                                        check_2=1
                                                        
                                                    end if
                                                
                                                    do future_unemployment_index=include_addiction*&
                                                        ((1-check_2)*1+check_2*(threshold_addiction_index+1))+&
                                                        (1-include_addiction)*(at_least_one_period_before_retirement*&
                                                        (one_period_before_death*1+(1-one_period_before_death)*unemployment_index)+&
                                                        (1-at_least_one_period_before_retirement)*1),include_addiction*&
                                                        ((1-check_2)*threshold_addiction_index+check_2*unemployment_grid_size)+&
                                                        (1-include_addiction)*(at_least_one_period_before_retirement*&
                                                        (one_period_before_death*unemployment_grid_size+&
                                                        (1-one_period_before_death)*unemployment_index)+&
                                                        (1-at_least_one_period_before_retirement)*unemployment_grid_size)
                                                                                     
                                                        do future_employment_index=&
                                                            at_least_one_period_before_retirement*employment_index+&
                                                            (1-at_least_one_period_before_retirement)*1,&
                                                            at_least_one_period_before_retirement*employment_index+&
                                                            (1-at_least_one_period_before_retirement)*employment_grid_size

                                                            do future_voucher_index=first_voucher_index_1,second_voucher_index_1
                                                                                                        
                                                                distribution_forward(amortization_used_dist)%&
                                                                    vector_transition_real(time_period,&
                                                                    age_index+1,financial_index_copy,&
                                                                    future_unemployment_index,future_employment_index,&
                                                                    future_housing_status_index_to_use_2,future_voucher_index)=&
                                                                    fraction_copy*survival_probability&
                                                                    (age_index,is_homeless_2,is_addicted_1,smi_of(unemployment_index))*&
                                                                    voucher_probabilities(voucher_index,&
                                                                    future_voucher_index,has_opportunity_2,voucher_index_1)*&
                                                                    employment_process(age_index,employment_index,&
                                                                    future_employment_index)*unemployment_process&
                                                                    (age_index,unemployment_index,future_unemployment_index,&
                                                                    is_homeless_2,future_addiction_index_2,employment_index)*&
                                                                    addiction_transition(is_addicted_1,&
                                                                    future_addiction_index_2,addiction_choice_1,is_homeless_2,&
                                                                    drug_quantity_dist_1,0,treatment_choice_dist_1)*&
                                                                    distribution_forward(years_left_on_mortgage_index)%&
                                                                    vector_transition_real(time_period-solve_transition_dynamics,&
                                                                    age_index,financial_index,unemployment_index,employment_index,&
                                                                    housing_status_index,voucher_index)+&
                                                                    distribution_forward(amortization_used_dist)%&
                                                                    vector_transition_real&
                                                                    (time_period,age_index+1,financial_index_copy,&
                                                                    future_unemployment_index,future_employment_index,&
                                                                    future_housing_status_index_to_use_2,future_voucher_index)
                                                                    
                                                                homelessness_mass_by_age(time_period,age_index)=&
                                                                    homelessness_mass_by_age(time_period,age_index)+&
                                                                    distribution_forward(years_left_on_mortgage_index)%&
                                                                    vector_transition_real(time_period-solve_transition_dynamics,&
                                                                    age_index,financial_index,unemployment_index,employment_index,&
                                                                    housing_status_index,voucher_index)
                                                                                                                                                                            
                                                            end do
                                                        
                                                        end do
                                                        
                                                    end do
                                                                                                
                                                end do
                                                
                                            end if 
                                                                                    
                                        end do
                                        
                                    end do
                                    
                                end do
                                
                            end do
                            
                        end do
                        
                    end do
                    
                end do
                            
                ! computing the mass of homelessness at each future age given the beginning age of age_index_1
                do age_index=life_span,age_index_1+1,-1
                            
                    homelessness_mass_by_age(time_period,age_index-1)=&
                        homelessness_mass_by_age(time_period,age_index-1)-&
                        sum(homelessness_mass_by_age(time_period,age_index:life_span))
                                            
                end do
                
                ! computing the average homelessness duration given they start as not 
                ! homeless and choose to be homelessness at age age_index_1
                do age_index=age_index_1,life_span
                
                    if (sum(homelessness_mass_by_age(time_period,age_index_1:life_span))>0) then
                
                        homelessness_duration(time_period,age_index_1,addiction_index_1)=&
                            homelessness_duration(time_period,age_index_1,addiction_index_1)+&
                            (age_index-(age_index_1-1))*homelessness_mass_by_age(time_period,age_index)/&
                            sum(homelessness_mass_by_age(time_period,age_index_1:life_span))
                        
                    end if
                          
                end do
                                
                ! this computes the average homelessness duration for everyone in a given addiction status of interest
                ! by taking adding the average duration of that age multiplied by the mass of future homeless for that age
                homelessness_duration_everyone(time_period,addiction_index_1)=&
                    homelessness_duration_everyone(time_period,addiction_index_1)+&
                    homelessness_duration(time_period,age_index_1,addiction_index_1)
                    
                ! counting total mass of homeless for all ages for the given addiction stauts of interest
                total_homeless_count(addiction_index_1)=total_homeless_count(addiction_index_1)+&
                    sum(homelessness_mass_by_age(time_period,age_index_1:life_span))
                                   
            end do
            
            if (total_homeless_count(addiction_index_1)>0) then
            
                ! computes the average duration for each addiction case
                homelessness_duration_everyone(time_period,addiction_index_1)=&
                    homelessness_duration_everyone(time_period,addiction_index_1)/&
                    total_homeless_count(addiction_index_1)
                    
            end if
            
        end do
                        
    end subroutine
            
    subroutine function_of_utility_advantage_from_homeowning(time_period)
    
        use Global_Vars
        
        implicit none
        
        integer, intent(in) :: time_period
        
        total_constrcution_profits(time_period)=0
        
        if ((is_counterfactual==1) .AND. (solve_transition_dynamics==0)) then
           
            housing_stock(time_period)=(1/housing_depreciation_rate)*(housing_price(time_period)/&
                c_1_calibrated)**(empirical_housing_supplpy_elasticity)
                
            housing_investment(time_period)=(housing_price(time_period)/&
                c_1_calibrated)**(empirical_housing_supplpy_elasticity)
                                                                     
        elseif ((is_counterfactual==1) .AND. (solve_transition_dynamics==1)) then
            
            housing_investment(time_period)=(housing_price(time_period)/&
                c_1_calibrated)**(empirical_housing_supplpy_elasticity)
                                    
        elseif ((is_counterfactual==0)) then
                                    
            c_1=(housing_price(time_period))/(housing_depreciation_rate*&
                total_housing_demand(time_period))**(1/empirical_housing_supplpy_elasticity)
                                                                            
            housing_stock(time_period)=(1/housing_depreciation_rate)*&
                (housing_price(time_period)/c_1)**(empirical_housing_supplpy_elasticity)
                                                
            housing_investment(time_period)=(housing_price(time_period)/c_1)**&
                (empirical_housing_supplpy_elasticity)
            
            housing_investment_value(time_period)=housing_price(time_period)*housing_investment(time_period)
                
            cutoff_housing_investment_bisection(1)=0
            cutoff_housing_investment_bisection(2)=housing_investment(time_period)
            
            distance_cutoff_housing_investment=1
            
            do while (distance_cutoff_housing_investment>stopping_rule_cutoff_housing_investment)
            
                cutoff_housing_investment=&
                    (cutoff_housing_investment_bisection(1)+cutoff_housing_investment_bisection(2))/2
            
                c_min=c_1*(cutoff_housing_investment)**(1/empirical_housing_supplpy_elasticity)
                                
                construction_company_profits(time_period)=0
                construction_company_profits(time_period)=construction_company_profits(time_period)+&
                    (housing_price(time_period)-c_min)*cutoff_housing_investment
                construction_company_profits(time_period)=construction_company_profits(time_period)+&
                    housing_price(time_period)*(housing_investment(time_period)-cutoff_housing_investment)-&
                    ((c_1*(housing_investment(time_period))**((1/empirical_housing_supplpy_elasticity)+1))/&
                    ((1/empirical_housing_supplpy_elasticity)+1)-(c_1*(cutoff_housing_investment)**&
                    ((1/empirical_housing_supplpy_elasticity)+1))/((1/empirical_housing_supplpy_elasticity)+1))
                            
                land_value=construction_company_profits(time_period)
                        
                land_to_housing_stock=land_value/housing_investment_value(time_period)
                
                distance_cutoff_housing_investment=abs(land_to_housing_stock-empirical_land_to_housing_stock)
                
                if (land_to_housing_stock<empirical_land_to_housing_stock) then
        
                    cutoff_housing_investment_bisection(2)=cutoff_housing_investment
        
                else
            
                    cutoff_housing_investment_bisection(1)=cutoff_housing_investment
                
                end if
                
            
            end do
                                        
            total_constrcution_profits(time_period)=total_constrcution_profits(time_period)+&
                construction_company_profits(time_period)
                
            distance_housing_market(time_period)=&
                abs(total_housing_demand(time_period)-housing_stock(time_period))
                                    
        end if
        
        total_constrcution_profits(time_period)=housing_price(time_period)*housing_investment(time_period)-&
            (((1-is_counterfactual)*c_1+is_counterfactual*c_1_calibrated)*&
            (housing_investment(time_period))**((1/empirical_housing_supplpy_elasticity)+1))/&
            ((1/empirical_housing_supplpy_elasticity)+1)
                
        if ((loop_count==0) .AND. (solve_transition_dynamics==0)) then
        
            write(*,*) "total_constrcution_profits(time_period)=", total_constrcution_profits(time_period)
            write(*,*) "c_1=", c_1
            
        end if
        
        if (is_counterfactual==0) then

            ! PINNED WHEN THE RENT IS FIXED. This is the assignment that sets the
            ! rent every loop, and it tracks housing_price; leaving it free while
            ! the calibration constants were fixed is what let the two disagree.
            ! With fix_rent on, the level is rent_calibrated and the management
            ! cost below is derived from it, so the counterfactual's inverse of
            ! that formula returns the same rent.
            if (fix_rent==0) then

                rent(time_period,:)=rent_to_housing_price*housing_price(time_period)

            else

                rent(time_period,:)=rent_calibrated(:)

            end if
                            
            if (infinite_elasticity_of_rental_supply==1) then
                                                
                rental_management_costs(:)=&
                    rent(time_period,:)+housing_price(time_period)*&
                    ((1-housing_depreciation_rate-property_tax(time_period))/(1+risk_free_rate(time_period))-1)
                                            
            else
            
                rental_management_costs(:)=&
                    (rent(time_period,:)-housing_price(time_period)*&
                    (risk_free_rate(time_period)+housing_depreciation_rate+property_tax(time_period)+&
                    property_tax_on_rental_housing)/&
                    (1+risk_free_rate(time_period)))/((total_rental_demand(time_period,:)**&
                    (convexity_of_rental_company(:)-1))*convexity_of_rental_company(:))
                             
            end if
                        
        elseif (is_counterfactual==1) then
                
            if (infinite_elasticity_of_rental_supply==1) then
                            
                rent(time_period,:)=max(rental_management_costs_calibrated(:)+housing_price(time_period)-&
                    housing_price(time_period-solve_transition_dynamics)*&
                    (1-housing_depreciation_rate-property_tax(time_period-solve_transition_dynamics))/&
                    (1+risk_free_rate(time_period)),0.d0)
                                 
            else
            
                rent(time_period,:)=partial_equilibrium*rent(time_period,:)+&
                    (1-partial_equilibrium)*(weight_on_housing_price*&
                    (convexity_of_rental_company(:)*rental_management_costs_calibrated(:)*&
                    total_rental_demand(time_period,:)**(convexity_of_rental_company(:)-1)+housing_price(time_period)-&
                    (housing_price(time_period-solve_transition_dynamics)*&
                    (1-housing_depreciation_rate-property_tax(time_period-solve_transition_dynamics)-&
                    property_tax_on_rental_housing)/(1+risk_free_rate(time_period))))+(1-weight_on_housing_price)*&
                    rent(time_period,:))
                
            end if
            
        end if
        
        total_rental_company_profits(time_period,:)=0
                           
        if (infinite_elasticity_of_rental_supply==1) then
                                         
        else
                        
            total_rental_company_profits(time_period,:)=total_rental_company_profits(time_period,:)+&
                total_rental_demand(time_period,:)*rent(time_period,:)
                                        
            total_rental_company_profits(time_period,:)=total_rental_company_profits(time_period,:)-&
                (housing_price(time_period)*total_rental_demand(time_period,:)-&
                housing_price(time_period-solve_transition_dynamics)*&
                total_rental_demand(time_period-solve_transition_dynamics,:)*&
                (1-property_tax(time_period-solve_transition_dynamics)-housing_depreciation_rate)+&
                (is_counterfactual*rental_management_costs_calibrated+&
                (1-is_counterfactual)*rental_management_costs)*&
                total_rental_demand(time_period,:)**convexity_of_rental_company(:))
            
        end if
            
!        write(*,*) "total_profits(time_period)=", total_profits(time_period)
!        write(*,*) "total_constrcution_profits(time_period)/(1-alpha_1)=", total_constrcution_profits(time_period)/(1-alpha_1)
!        write(*,*) "total_rental_company_profits(time_period)/(1-alpha_1)=", total_rental_company_profits(time_period)/(1-alpha_1)
!        write(*,*) "risk_free_rate(time_period)=", risk_free_rate(time_period)
                                   
        if (loop_count>=0) then
                        
            housing_size(0)=smallest_house_size
        
            housing_size(housing_status_grid_size-1)=largest_house_size
            
            if (housing_status_grid_size>2) then
                                                   
                do i=1,housing_status_grid_size-1
        
                    housing_status_grid_distance(i)=&
                        i*((housing_size(housing_status_grid_size-1)-housing_size(0))**&
                        (real(1)/housing_status_grid_expander))/(real(housing_status_grid_size)-real(1))
    
                end do
                
                housing_size=housing_size(0)+housing_status_grid_distance**(housing_status_grid_expander)
                
            end if

            ! THE WHOLE RENTAL LADDER IS ASSIGNED OFF THE BOTTOM RUNG,
            ! EXTERNALLY, on the author's instruction of 1 September, in the
            ! note's own indexing: "h2 match fraction spending over 50% of income
            ! on housing, h3 being double of h2, and h4 being tripple h2".
            !
            !     h_1  the street          = housing_size(0)*size_homelessness,
            !                                calibrated on the homelessness rate
            !                                through size_homelessness. NOT set here.
            !     h_2  cheapest rental     = housing_size(0) = smallest_house_size,
            !                                calibrated on the share of renters
            !                                paying over half their income
            !     h_3  middle rental       = housing_size(1) = 2*h_2   ASSIGNED
            !     h_4  largest rental      = housing_size(2) = 3*h_2   ASSIGNED
            !
            ! So ONE free parameter sets the whole rental ladder.
            !
            ! What that retires. largest_house_size and
            ! housing_status_grid_expander no longer determine anything here --
            ! the top rung is 3h and the middle is 2h whatever they hold. Both
            ! stay in the vector so a point still records them, and both should
            ! be held rather than calibrated; leaving either mapped to a moment
            ! would be an instrument that cannot move its target.
            !
            ! It overrides whatever the expander produced for the interior
            ! points, and it is written after that block rather than replacing it
            ! so the endpoints are still set the same way and a grid of more than
            ! three points still has a shape to fall back on.
            !
            ! Why it matters beyond tidiness. The rungs were 0.0377, 0.0937 and
            ! 0.1498, a spread of 2.49 then 1.60, and the consequence was that
            ! the cheapest unit was so far below the others that nobody in it was
            ! cost burdened at all -- the burden decomposes as 0.7108 x 0.5100 =
            ! 0.362531, the whole of it in the LARGEST unit, with the cheapest
            ! contributing exactly zero. Fixing the middle at twice the bottom
            ! compresses the ladder and makes the bottom rung an object the rent
            ! burden can actually see.
            ! THE GUARD WAS WRONG FOR A TWO-RUNG LADDER. It read
            ! `housing_status_grid_size>2`, which is FALSE at two rentals, so the
            ! second rung would never have been assigned and housing_size(1)
            ! would have kept whatever the grid constructor left there. Split so
            ! that rung_ratio_h3 applies from two rungs up and rung_ratio_h4 only
            ! from three, which leaves the three-rung behaviour exactly as it was.
            !
            ! The index is still clamped: gfortran cannot prove the guard protects
            ! it and the warning would mask a real one next time.
            ! AT TWO RUNGS THE TOP ONE IS AN ABSOLUTE SIZE, NOT A MULTIPLE OF THE
            ! BOTTOM. The author, 5 September: *"adjust h2 down until it hits
            ! 17.5%. and adjust h3 independently of h2"*.
            !
            ! This is what breaks the collinearity that made the two-rung design
            ! infeasible an hour ago. Measured then: both instruments moved both
            ! moments the same way, h2 delivering +3.04 burden50 per unit gamma
            ! and the rung ratio +4.12, while the target needed -0.57. The cause
            ! was MECHANICAL, not economic -- h3 was rung_ratio_h3*h2, so cutting
            ! the bottom rung dragged the top rung down with it and both moments
            ! fell together. Two knobs chained into one.
            !
            ! housing_size(housing_status_grid_size-1) is ALREADY set to
            ! largest_house_size a few lines above, an independent absolute size.
            ! The overwrite below was what chained them, so it now runs only from
            ! THREE rungs up, where the ladder genuinely is a ratio ladder and the
            ! three-rung behaviour is unchanged.
            !
            !   two rungs:  h2 = smallest_rental_relative_to_lowest_income -> burden50
            !               h3 = largest_house_size                        -> gamma
            !
            ! THE LADDER INVERTS IF h3 <= h2, and nothing in the Fortran notices:
            ! the run completes and reports the share in "the largest unit" when
            ! it is really the smallest. run_one_point.sh carries the guard.
            ! ONLY THE MIDDLE RUNG IS ASSIGNED, AND THE TOP ONE STAYS FREE.
            !
            ! This block used to set BOTH interior and top rungs as multiples of
            ! h2, which chained the top rung to the bottom one -- exactly the
            ! collinearity that made the ladder infeasible before
            ! largest_house_size was freed on 5 September. Restoring the third
            ! rung with the old body would have undone that fix silently: at
            ! three rungs the guard reactivates and housing_size(2) would go back
            ! to rung_ratio_h4*h2.
            !
            ! housing_size(housing_status_grid_size-1) is already largest_house_size,
            ! an independent absolute level, and it OWNS h_3. h2 owns burden50.
            ! The middle rung carries no moment, so it is placed at the geometric
            ! mean: monotone by construction for any 0 < h2 < h_top, and it adds
            ! no free parameter to the search.
            !
            ! rung_ratio_h3 and rung_ratio_h4 no longer determine anything. They
            ! stay in the vector so a point still records them and both should be
            ! held rather than calibrated.
            ! THE INTERIOR IS GEOMETRIC BETWEEN TWO FREE ENDPOINTS.
            !
            ! housing_size(0) is smallest_rental_relative_to_lowest_income and
            ! owns burden50; housing_size(housing_status_grid_size-1) is
            ! largest_house_size and owns h_3. Neither is touched here. The
            ! interior rungs carry no moment and are placed so the ladder is
            ! monotone by construction for any 0 < bottom < top, adding no free
            ! parameter to the search.
            !
            ! Geometric rather than linear because the choice is Cobb-Douglas:
            ! utility differences between rungs go with LOG size, so equal log
            ! spacing is equal economic spacing. At three rungs this reduces
            ! exactly to the geometric mean it replaces, so the three-rung
            ! behaviour is unchanged.
            !
            ! rung_ratio_h3 and rung_ratio_h4 determine nothing and should be
            ! held rather than calibrated.
            if (housing_status_grid_size>2) then

                housing_size(1)=rung_ratio_h3*housing_size(0)
                housing_size(housing_status_grid_size-1)=rung_ratio_h4*housing_size(0)

            end if
            
            ! ONLY WHEN THERE IS SOMETHING TO BUY. smallest_house_for_purchase
            ! is the size at which a dwelling becomes eligible for a mortgage,
            ! so overwriting a grid point with it is an OWNERSHIP construct. With
            ! include_homeownership=0 that point is a rental size and nothing
            ! else, and the overwrite destroyed the geometric spread the note
            ! describes: at a three point grid it turned (0.040, 0.119, 0.315)
            ! into (0.040, 0.250, 0.315), a sixfold gap at the bottom. Every
            ! household then took the near free 0.040 unit and the model produced
            ! EXACTLY ZERO homelessness, which made every homeless moment NaN.
            if (include_homeownership==1) then

                housing_size(housing_status_grid_size-2)=smallest_house_for_purchase

            end if

            ! THE ABSOLUTE FLOOR IS APPLIED HERE, not on the ratio at handover.
            ! This line runs after both the rung and the ratio are set, so it is
            ! the only place that can see the product. A handover clamp cannot:
            ! size_homelessness and smallest_rental arrive in whichever order the
            ! caller wrote them, so a clamp there would depend on the order of
            ! the command line.
            ! THE STREET IS AN ABSOLUTE LEVEL, NOT A RATIO OF THE BOTTOM RUNG,
            ! on the author's instruction of 5 September: *"you should disentangle
            ! the homeless size from the smallest rental. it should be free to
            ! move alone"*.
            !
            ! It was housing_size(0)*size_homelessness, so every move in h2
            ! dragged the street with it -- the same mechanical chaining that made
            ! h2 and h3 collinear until largest_house_size was freed. It is not a
            ! small effect: the h2 sweep of 0.060 -> 0.16 run earlier today moved
            ! the street 0.0345 -> 0.0921 underneath it, so those points were not
            ! one-coordinate measurements at all.
            !
            ! ENGINE.md records the ratio form and says the stepper compensates by
            ! working in (rung, absolute street) coordinates. That is a workaround
            ! for the parameterisation; this removes the need for it. The ladder is
            ! now three independent absolute levels:
            !
            !   street = size_homelessness            -> h_1
            !   h2     = smallest_rental_...          -> the affordability floor
            !   h3     = largest_house_size           -> gamma
            !
            ! increase_homeless_size still multiplies, and street_size_floor still
            ! guards against zero, so the counterfactual machinery is untouched.
            housing_size(lowest_housing_grid_point)=max(&
                size_homelessness*(1+increase_homeless_size*5),&
                street_size_floor)

            write(*,*) "DIAG unsecured borrowing limit, yrs of income   =",&
                unsecured_borrowing_limit*include_unsecured_borrowing
            write(*,*) "DIAG borrowing floor, model units                =",&
                financial_grid(renter_array_floor)
            write(*,*) "DIAG patient type barred from the negative grid   =",&
                restrict_borrowing_to_impatient*include_unsecured_borrowing*&
                min(max(number_of_beta_types-1,0),1)
            write(*,*) "DIAG street size, absolute                       =",&
                housing_size(lowest_housing_grid_point)
            write(*,*) "DIAG street as a share of the cheapest unit      =",&
                housing_size(lowest_housing_grid_point)/max(housing_size(0),10.d0**(-14))
                        
            open(unit=3,file="housing_status_grid_points"//trim(file_number)//".txt",action="write",status="replace")
                do i=lowest_housing_grid_point,housing_status_grid_size-1
                    write(3,*) housing_size(i)
                end do
            close(3)
        
        end if
        
        if (solve_transition_dynamics==0) then
        
            write(*,*) "size_of_smallest_house_hhld_can_buy=", size_of_smallest_house_hhld_can_buy
            
        end if

        if (calibrate_size_of_smallest_house_hhld_can_buy==1) then 
                    
!            index_of_smallest_house_hhld_can_buy=&
!                minloc((housing_size-size_of_smallest_house_hhld_can_buy),1,&
!                mask=(housing_size-size_of_smallest_house_hhld_can_buy)>0)
!            
!            write(*,*) "index_of_smallest_house_hhld_can_buy=", index_of_smallest_house_hhld_can_buy
!            
!            index_of_smallest_house_hhld_can_buy_minus_one=&
!                max(index_of_smallest_house_hhld_can_buy-1,lowest_housing_grid_point)
!            
!            size_of_smallest_house_hhld_can_buy=&
!                (housing_size(max(min(index_of_smallest_house_hhld_can_buy,housing_status_grid_size-1),lowest_housing_grid_point))+&
!                housing_size(index_of_smallest_house_hhld_can_buy_minus_one))/2
                
!            size_of_smallest_house_hhld_can_buy=0.25
                
            index_of_smallest_house_hhld_can_buy=smallest_index_for_purchase
                
        else
        
            index_of_smallest_house_hhld_can_buy=smallest_index_for_purchase
                
        end if
                
        if ((loop_count<1) .AND. (solve_transition_dynamics==0)) then
        
            ! CLAMPED FOR THE ONE-RENTAL GRID. index_of_smallest_house_hhld_can_buy
            ! is smallest_index_for_purchase, an OWNERSHIP constant fixed at 2,
            ! while housing_size is now dimensioned -1:0. Every other use of the
            ! index is `has_house*index` as a LOOP LOWER BOUND against
            ! housing_status_grid_size-1, which is zero-trip for an owner and
            ! therefore safe; this diagnostic write is the one place it is read
            ! directly, and it read two doubles past the end of the array.
            !
            ! It is what the -fcheck=bounds build caught. The -O3 build did not
            ! trap it and instead printed garbage (0.23) and segfaulted much later
            ! inside an unrelated distribution diagnostic, which is exactly why
            ! the bounds build is a standing check rather than an optional one.
            write(*,*) "housing_size(index_of_smallest_house_hhld_can_buy)=", & 
                housing_size(max(min(index_of_smallest_house_hhld_can_buy,&
                housing_status_grid_size-1),lowest_housing_grid_point))
            write(*,*) "size_of_smallest_house_hhld_can_buy=", size_of_smallest_house_hhld_can_buy
            write(*,*) "index_of_smallest_house_hhld_can_buy=", index_of_smallest_house_hhld_can_buy
            write(*,*) "smallest_house_size=", smallest_house_size
            write(*,*) "housing_status_grid_expander=", housing_status_grid_expander
        
        end if
        
        do age_index=1,life_span
            
            do housing_status_index=lowest_housing_grid_point,(housing_status_grid_size-1)
            
                if ((use_cobb_douglas==1) .OR. (use_cobb_douglas_2==1)) then
                                                
                    housing_status_utility_function(housing_status_index,:,0,0)=&
                        (housing_size(housing_status_index))**&
                        ((1-risk_aversion_consumption)*relative_share_of_housing)
                        
                    housing_status_utility_function(housing_status_index,:,1,0)=&
                        (housing_size(housing_status_index)*(1+advantage_to_owning))**&
                        ((1-risk_aversion_consumption)*relative_share_of_housing)
                        
                    housing_status_utility_function(housing_status_index,:,0,1)=&
                        (housing_size(housing_status_index))**&
                        ((1-risk_aversion_consumption)*relative_share_of_housing)
                        
                    housing_status_utility_function(housing_status_index,:,1,1)=&
                        (housing_size(housing_status_index)*(1+advantage_to_owning))**&
                        ((1-risk_aversion_consumption)*relative_share_of_housing)
                        
                elseif (include_probability_of_becoming_addicted==1) then
                                
                    housing_status_utility_function(housing_status_index,:,0,0)=&
                        (housing_size(housing_status_index))**&
                        ((1-risk_aversion_consumption)*relative_share_of_housing_1)
                        
                    housing_status_utility_function(housing_status_index,:,1,0)=&
                        (housing_size(housing_status_index)*(1+advantage_to_owning))**&
                        ((1-risk_aversion_consumption)*relative_share_of_housing_1)
                        
                    housing_status_utility_function(housing_status_index,:,0,1)=&
                        (housing_size(housing_status_index))**&
                        ((1-risk_aversion_consumption)*relative_share_of_housing_2)
                        
                    housing_status_utility_function(housing_status_index,:,1,1)=&
                        (housing_size(housing_status_index)*(1+advantage_to_owning))**&
                        ((1-risk_aversion_consumption)*relative_share_of_housing_2)
                                      
                else
                
                    housing_status_utility_function(housing_status_index,:,0,0)=&
                        relative_share_of_housing*(housing_size(housing_status_index)/&
                        sqrt_household_size(age_index))**(power_1)
                        
                    housing_status_utility_function(housing_status_index,:,1,0)=&
                        relative_share_of_housing*((housing_size(housing_status_index)*&
                        (1+advantage_to_owning)/sqrt_household_size(age_index)))**(power_1)
                        
                    housing_status_utility_function(housing_status_index,age_index,0,1)=&
                        relative_share_of_housing_2*(housing_size(housing_status_index)/&
                        sqrt_household_size(age_index))**(power_1)
                        
                    housing_status_utility_function(housing_status_index,age_index,1,1)=&
                        relative_share_of_housing_2*((housing_size(housing_status_index)*&
                        (1+advantage_to_owning))/sqrt_household_size(age_index))**(power_1)
                
                end if
                                                        
                if (loop_count<0) then
            
                    do i=0,1
                                    
                        write(*,*) "utility from housing size", housing_size(housing_status_index), " gives utility of ", &
                            housing_status_utility_function(housing_status_index,1,i,0)
                        write(*,*) "housing_status_index=", housing_status_index
                        write(*,*) "ownership_status_index=", i
                    
                    end do
            
                end if
                                      
            end do
                    
        end do
        
    end subroutine
    
    subroutine initialize_variables_and_grids()
    
        use Global_Vars
        
        implicit none
                                        
        do i=1,life_span
        
            scaled_household_size(i)=(sqrt(actual_household_size(i)))**risk_aversion_consumption
            sqrt_household_size(i)=sqrt(actual_household_size(i))
            
            if (loop_count<1) then
            
                write(*,*) "scaled_household_size(i)=", scaled_household_size(i)
                
            end if
            
            survival_probability(i,:,:,:)=1
        
            do j=i,min(i,life_span)
        
                survival_probability(i,:,:,:)=survival_probability(i,:,:,:)*actual_survival_probability(j)
                
            end do
                
        end do
        
        if (life_span<60) then
        
            survival_probability(life_span,:,:,:)=0
            
            if (loop_count==0) then
            
!                write(*,*) "survival_probability=", survival_probability
                
            end if
        
        end if  
        
        ! EQUATION (24), MULTIPLICATIVE AND AGE VARYING.
        !
        !   phi(j,h',d) = 1 - min{1, (1-phibar(j)) * kappa_phi_H(j)^1{h1} * kappa_phi_d(j)^1{d=1}}
        !
        ! The old lines subtracted a flat excess times the death hazard and, for
        ! a household that was both homeless and carrying the disorder, ADDED the
        ! two excesses. The note multiplies the two multipliers, which is a
        ! different and larger number whenever both are large, and both are large
        ! exactly for the households this paper is about.
        !
        ! THE PROFILES HAVE TO BE ON DISK BEFORE THE MULTIPLIERS ARE BUILT, and
        ! for a long time they were not.
        !
        ! build_mortality_multipliers is called from here and nowhere else, and
        ! load_mortality_profiles used to be called only from
        ! GKKOC_intergenerational_employment_process, which runs AFTER this
        ! routine. So the multipliers were built from profiles that were still
        ! all zero, which makes kappa_phi_d_by_age = 1 and kappa_phi_h_by_age = 1
        ! at every age, and survival_probability was then built from those. The
        ! whole age varying mortality specification, equation (25), was inert:
        ! the CSV was read a moment later and never used for anything.
        !
        ! It was invisible because every cell of the array still held a
        ! defensible looking survival probability, and because the confirming
        ! print, "mortality profiles loaded", appeared in the log a hundred lines
        ! after the array had already been built. The hazard ratio between a
        ! clean housed household and a homeless using one was exactly one.
        call load_mortality_profiles()

        call build_mortality_multipliers()

        do i=1,life_span

            ! THE MULTIPLIERS ARE HAZARD RATIOS, SO THEY GO ON THE HAZARD.
            ! A standardised mortality ratio is a ratio of RATES, and this
            ! multiplied the death PROBABILITY instead. The two agree only while
            ! the baseline is small: at a baseline of 0.0012 at data age 26 they
            ! are the same to three decimals, and at 0.0805 at 85 a ratio of
            ! eight gives 0.644 one way and 0.489 the other. Raising survival to
            ! the power of the multiplier is the constant hazard ratio, it is
            ! bounded in [0,1] by construction so the min disappears with it, and
            ! it reproduces on its own the compression of the measured ratio with
            ! age that the literature reports.
            ! THE MULTIPLIER GOES ON THE DEATH PROBABILITY, CAPPED AT ONE.
            !
            ! The previous line raised SURVIVAL to the power of the multiplier,
            ! which is a constant hazard ratio and is bounded in [0,1] on its
            ! own. It has one consequence the author does not want: the
            ! multiplier it delivers on the DEATH PROBABILITY is not constant.
            ! At kappa 8 it is 7.97 at data age 26 and 6.17 at 84, because
            ! 1 - s**k saturates as s falls. The literature's number is a ratio
            ! of death rates, and the author's requirement is that the disorder
            ! raise the probability of death by the same factor at every age.
            !
            ! So the multiplier goes on the death probability and the result is
            ! capped, which is what the min is for and why the exponent form's
            ! automatic boundedness is no longer doing that job. The cap does
            ! not bind at kappa_phi_d alone -- eight times the 0.0758 baseline
            ! at 84 is 0.61 -- and can only bind where the homelessness
            ! multiplier is also large, which is at young ages where the
            ! baseline is tiny.
            survival_probability(i,2,0,0)=&
                1.d0-min(1.d0,kappa_phi_h_by_age(i)*(1.d0-survival_probability(i,1,0,0)))

        end do
                    
!        survival_probability(1:life_span-retirement_span,2,0)=&
!            survival_probability(1:life_span-retirement_span,1,0)
        
        if (include_addiction==1) then
        
            do i=1,life_span

                survival_probability(i,1,include_addiction,0)=&
                    1.d0-min(1.d0,kappa_phi_d_by_age(i)*(1.d0-survival_probability(i,1,0,0)))

            end do
                                
!            survival_probability(1:life_span-retirement_span,1,include_addiction)=&
!                survival_probability(1:life_span-retirement_span,1,0)
                
            do i=1,life_span

                ! The two multipliers multiply, as the exponents used to.
                survival_probability(i,2,include_addiction,0)=&
                    1.d0-min(1.d0,kappa_phi_h_by_age(i)*kappa_phi_d_by_age(i)*&
                    (1.d0-survival_probability(i,1,0,0)))

            end do
                
!            survival_probability(1:life_span-retirement_span,2,include_addiction)=&
!                survival_probability(1:life_span-retirement_span,1,0)

        end if

        ! THE SMI LAYER, and it is built LAST for a reason.
        !
        ! kappa_phi_m multiplies the death hazard a household already faces, so
        ! it has to be applied to a base that already carries the housing and
        ! SUD multipliers. Building it earlier would give a household that is
        ! homeless, using and mentally ill the SMI multiplier on the clean
        ! housed hazard, which is the same error as adding excesses instead of
        ! multiplying hazards, one level up.
        !
        ! survival_with_smi is the one place the arithmetic lives, and it is
        ! finally called from somewhere.
        if (number_of_smi_states>1) then

            do i=1,life_span

                do j=1,2

                    do k=0,include_addiction

                        survival_probability(i,j,k,1)=&
                            survival_with_smi(survival_probability(i,j,k,0),1)

                    end do

                end do

            end do

        end if

        ! HOW HARD THE HAZARDS STACK, reported rather than assumed.
        !
        ! The note multiplies the multipliers, so a household that is homeless,
        ! using and mentally ill faces kappa_phi_H * kappa_phi_d * kappa_phi_m
        ! times the baseline hazard, and at the oldest ages that product is large
        ! enough to drive the hazard past one. Both clips are deliberate and both
        ! are explicit in the code, but a clip means the multiplier has stopped
        ! doing what the calibration thinks it does: past the floor, raising
        ! kappa_phi_d no longer changes anything for that cell, so the moment
        ! stops responding to the parameter and the calibration stalls against a
        ! wall it cannot see.
        !
        ! So the floor is counted and printed once. A handful of clipped cells at
        ! the very oldest ages is expected and harmless. A large count means the
        ! multipliers are stacking past what the survival curve can carry, and
        ! that is a specification problem to be argued about, not a number to
        ! quietly accept.
        if (loop_count<1) then

            clipped_survival_cells=0
            min_survival_seen=1

            do i=1,life_span-1

                do j=1,2

                    do k=0,include_addiction

                        do m=0,number_of_smi_states-1

                            if (survival_probability(i,j,k,m)<=0.d0) then

                                clipped_survival_cells=clipped_survival_cells+1

                            end if

                            min_survival_seen=min(min_survival_seen,survival_probability(i,j,k,m))

                        end do

                    end do

                end do

            end do

            write(*,*) "survival: cells clipped to zero before the last age =", &
                clipped_survival_cells, " of ", &
                (life_span-1)*2*(1+include_addiction)*number_of_smi_states
            write(*,*) "survival: smallest probability before the last age =", min_survival_seen

            if (number_of_smi_states>1) then

                write(*,*) "survival: SMI multiplier is live, kappa_phi_m =", kappa_phi_m
                write(*,*) "survival: clean housed vs SMI homeless with SUD at age 40 =", &
                    survival_probability(40,1,0,0), survival_probability(40,2,include_addiction,&
                    number_of_smi_states-1)

            end if

        end if

        survival_probability_for_dist_iteration=survival_probability
        
        if (remove_increased_death==1) then
        
            survival_probability_for_dist_iteration(:,2,0,:)=survival_probability(:,1,0,:)
            survival_probability_for_dist_iteration(:,1,include_addiction,:)=survival_probability(:,1,0,:)
            survival_probability_for_dist_iteration(:,2,include_addiction,:)=survival_probability(:,1,0,:)
        
        end if
        
        expected_age_non_addicted=0
        expected_age_homeless=0
        expected_age_addicted=0
        expected_age_homeless_and_addicted=0
        
        do age_index=1,life_span
        
            mass_2(:)=1
        
            do i=1,age_index
            
                if (i==age_index) then
                
                    mass_2(1)=(1-survival_probability(i,1,0,0))*mass_2(1)
                    mass_2(2)=(1-survival_probability(i,2,0,0))*mass_2(2)
        
                else
        
                    mass_2(1)=survival_probability(i,1,0,0)*mass_2(1)
                    mass_2(2)=survival_probability(i,2,0,0)*mass_2(2)
                    
                end if
                
            end do
                        
            expected_age_non_addicted=expected_age_non_addicted+mass_2(1)*age_index
            expected_age_homeless=expected_age_homeless+mass_2(2)*age_index
        
            if (include_addiction==1) then
        
                do i=1,age_index
                            
                    if (i==age_index) then
                
                        mass_2(3)=(1-survival_probability(i,1,include_addiction,0))*mass_2(3)
                        mass_2(4)=(1-survival_probability(i,2,include_addiction,0))*mass_2(4)
            
                    else
            
                        mass_2(3)=survival_probability(i,1,include_addiction,0)*mass_2(3)
                        mass_2(4)=survival_probability(i,2,include_addiction,0)*mass_2(4)
                        
                    end if
                    
                end do
                    
                expected_age_addicted=expected_age_addicted+mass_2(3)*age_index                    
                expected_age_homeless_and_addicted=expected_age_homeless_and_addicted+mass_2(4)*age_index
                    
            end if
            
        end do
                                    
        if (have_probablistic_death==0) then
        
            survival_probability=1
            survival_probability(life_span,:,:,:)=0
            
            if (loop_count==0) then
            
!                write(*,*) "survival_probability=", survival_probability
                
            end if
            
        end if
                
        if (loop_count<1) then
                                    
            do age_index=1,life_span
                
                if (solve_transition_dynamics==0) then
            
                    write(*,*) "survival_probability(",age_index,")=", survival_probability(age_index,1,0,0)
                    
                end if
                    
            end do

        end if
                
        cohort_population(1)=1
        
        total_population=cohort_population(1)
            
        do i=2,life_span
        
            cohort_population(i)=cohort_population(i-1)*survival_probability(i-1,1,0,0)
            
            total_population=total_population+cohort_population(i)
            
        end do
        
        if ((solve_transition_dynamics==0) .AND. &
           (loop_count<1)) then
                
            write(*,*) "total population=", total_population
        
        end if
         
        stopping_rule_wealth_dist(1)=0.01
        stopping_rule_wealth_dist(2)=0.1
        stopping_rule_wealth_dist(3)=0.2
        stopping_rule_wealth_dist(4)=0.5
        stopping_rule_wealth_dist(5)=0.9
        stopping_rule_wealth_dist(6)=0.95
        stopping_rule_wealth_dist(7)=0.99
        stopping_rule_wealth_dist(8)=0.99999
        
        stopping_rule_income_dist(1)=0.01
        stopping_rule_income_dist(2)=0.05
        stopping_rule_income_dist(3)=0.1
        stopping_rule_income_dist(4)=0.1
        stopping_rule_income_dist(5)=0.05
        stopping_rule_income_dist(6)=0.01        
        
        stopping_rule_wealth_dist_of_old(1)=0.25
        stopping_rule_wealth_dist_of_old(2)=0.5
        stopping_rule_wealth_dist_of_old(3)=0.75
        
    end subroutine             
            
    subroutine build_a_prime_window(time_period)
    
        ! Collect every asset index the policy function chose anywhere, dilate by
        ! a_prime_window on each side, and report how much of the grid that is.
        ! Called after a solve; the next solve uses it.
    
        use Global_Vars
        
        implicit none
        
        integer, intent(in) :: time_period
        integer :: j_1,k_1,lo_1,hi_1,kept_1
        logical, dimension(:), allocatable :: chosen_1
        
        if (restrict_a_prime==0) return
        
        if (.NOT. allocated(a_prime_allowed)) allocate(a_prime_allowed(financial_grid_size))
        
        allocate(chosen_1(financial_grid_size))
        
        chosen_1=.FALSE.
        
        do j_1=1,financial_grid_size
        
            if (any(policy_function_financial_index(1)%vector_transition_integer&
                (time_period,:,:,:,:,:,:)==j_1)) chosen_1(j_1)=.TRUE.
        
        end do
        
        a_prime_allowed=.FALSE.
        
        do j_1=1,financial_grid_size
        
            if (.NOT. chosen_1(j_1)) cycle
            
            lo_1=max(j_1-a_prime_window,1)
            hi_1=min(j_1+a_prime_window,financial_grid_size)
            
            do k_1=lo_1,hi_1
            
                a_prime_allowed(k_1)=.TRUE.
            
            end do
        
        end do
        
        kept_1=count(a_prime_allowed)
        
        a_prime_set_ready=1
        
        write(*,*) "a' window: keeping", kept_1, "of", financial_grid_size, &
            "asset points; boundary hits last solve:", a_prime_boundary_hits
        
        a_prime_boundary_hits=0
        
        deallocate(chosen_1)
    
    end subroutine
    
    subroutine verify_index_map()
    
        ! THE INDEX MAP CHECKS ITSELF. Every fine grained test that used to be
        ! written against threshold_addiction_index is now written through
        ! emp_of and sud_of, and at number_of_smi_states = 1 the two forms have
        ! to agree on every index in the grid. This runs once at startup and
        ! stops the model if they do not, so the rewrite is verified rather than
        ! asserted. At number_of_smi_states = 2 the old forms are WRONG by
        ! construction, which is the whole point, so that comparison is only
        ! made at one.
        !
        ! THAT GUARD IS ALSO HOW A REAL BUG SURVIVED, so there is now a second
        ! block that runs at every grid size.
        !
        ! The accessor rewrite replaced the simple tests and left the COMPOSITE
        ! ones enumerating index values: "employed" was written as
        !
        !     index == 1  .OR.  (sud_of == 1 .AND. emp_of == 1)
        !
        ! which at one SMI state is exactly {1,4} and correct, and at two states
        ! is {1,7,10} and misses index 4, the household that is EMPLOYED and
        ! carries SMI without a SUD. That household was handed zero labour
        ! income by calculate_income and counted as not working everywhere else,
        ! which is precisely the population the SMI calibration targets are
        ! about. Eighteen tests were wrong in this way and the run produced
        ! numbers throughout.
        !
        ! The check below is written on CARDINALITIES rather than on membership,
        ! because that is what a composite test gets wrong: any predicate that
        ! partitions on employment alone must split the grid into three equal
        ! blocks whatever the SMI grid size, and a test that forgets a state
        ! lands a block short. It would have failed on the old forms at two
        ! states, which is the test that was missing.

        use Global_Vars

        implicit none

        integer :: i_1,bad_1,count_emp_1,count_ui_1,count_out_1,count_smi_1,count_sud_1
        integer :: expected_block_1

        bad_1=0

        count_emp_1=0
        count_ui_1=0
        count_out_1=0
        count_smi_1=0
        count_sud_1=0

        do i_1=1,unemployment_grid_size

            if (emp_of(i_1)==1) count_emp_1=count_emp_1+1
            if (emp_of(i_1)==3) count_ui_1=count_ui_1+1
            if (emp_of(i_1)>1) count_out_1=count_out_1+1
            if (smi_of(i_1)==1) count_smi_1=count_smi_1+1
            if (sud_of(i_1)==1) count_sud_1=count_sud_1+1

            ! The round trip, which is the one identity that has to hold at
            ! every grid size.
            if (idx_of(emp_of(i_1),smi_of(i_1),sud_of(i_1))/=i_1) bad_1=bad_1+1

            ! Every accessor in range.
            if ((emp_of(i_1)<1) .OR. (emp_of(i_1)>3)) bad_1=bad_1+1
            if ((smi_of(i_1)<0) .OR. (smi_of(i_1)>(number_of_smi_states-1))) bad_1=bad_1+1
            if ((sud_of(i_1)<0) .OR. (sud_of(i_1)>1)) bad_1=bad_1+1

        end do

        expected_block_1=unemployment_grid_size/3

        ! The employment partition holds at every configuration, since the grid
        ! is three employment states however many factors are folded around them.
        if (count_emp_1/=expected_block_1) bad_1=bad_1+1
        if (count_ui_1/=expected_block_1) bad_1=bad_1+1
        if (count_out_1/=(2*expected_block_1)) bad_1=bad_1+1

        ! The SUD and SMI blocks only exist when the SUD is in the model: with
        ! include_addiction = 0 the grid is three states and carries neither,
        ! whatever number_of_smi_states happens to say. Checking them
        ! unconditionally would abort a configuration that is in fact correct.
        if (include_addiction==1) then

            if (count_smi_1/=((number_of_smi_states-1)*unemployment_grid_size/number_of_smi_states)) bad_1=bad_1+1
            if (count_sud_1/=(unemployment_grid_size/2)) bad_1=bad_1+1

        else

            if (count_smi_1/=0) bad_1=bad_1+1
            if (count_sud_1/=0) bad_1=bad_1+1

        end if

        if (bad_1>0) then

            write(*,*) "INDEX MAP IS WRONG at number_of_smi_states=", number_of_smi_states
            write(*,*) "mismatches:", bad_1
            write(*,*) "employed=", count_emp_1, " on UI=", count_ui_1, &
                " not employed=", count_out_1, " expected block=", expected_block_1
            write(*,*) "with SMI=", count_smi_1, " with SUD=", count_sud_1

            stop

        end if

        write(*,*) "index map: accessors consistent at number_of_smi_states=", &
            number_of_smi_states, " employed block=", count_emp_1

        if (number_of_smi_states/=1) then

            write(*,*) "index map: threshold comparison not made, number_of_smi_states=", number_of_smi_states

            return

        end if

        bad_1=0

        do i_1=1,unemployment_grid_size
        
            if ((sud_of(i_1)==1) .NEQV. (i_1>threshold_addiction_index)) bad_1=bad_1+1
            if ((sud_of(i_1)==0) .NEQV. (i_1<=threshold_addiction_index)) bad_1=bad_1+1
            if (((sud_of(i_1)==0) .AND. (emp_of(i_1)==3)) .NEQV. &
                (i_1==threshold_addiction_index)) bad_1=bad_1+1
            if (((sud_of(i_1)==0) .AND. (emp_of(i_1)==2)) .NEQV. &
                (i_1==threshold_addiction_index-1)) bad_1=bad_1+1
            if (((sud_of(i_1)==1) .AND. (emp_of(i_1)==1)) .NEQV. &
                (i_1==threshold_addiction_index+1)) bad_1=bad_1+1
            if (((sud_of(i_1)==1) .AND. (emp_of(i_1)==2)) .NEQV. &
                (i_1==threshold_addiction_index+2)) bad_1=bad_1+1
            if (((sud_of(i_1)==1) .AND. (emp_of(i_1)==3)) .NEQV. &
                (i_1==unemployment_grid_size)) bad_1=bad_1+1
            if (((sud_of(i_1)==1) .AND. (emp_of(i_1)>1)) .NEQV. &
                (i_1>threshold_addiction_index+1)) bad_1=bad_1+1
            if (idx_of(emp_of(i_1),smi_of(i_1),sud_of(i_1))/=i_1) bad_1=bad_1+1
            
        end do
        
        if (bad_1>0) then
        
            write(*,*) "INDEX MAP IS WRONG, mismatches:", bad_1
            
            stop
            
        end if
        
        write(*,*) "index map verified against the old thresholds, grid=", unemployment_grid_size
    
    end subroutine
    
    subroutine compute_expected_child_value(time_period)
    
        ! E V_1(0, y_child, employed, clean, no voucher), by the parent's SUD
        ! status and whether it was homeless. The newborn lands where the
        ! distribution iteration puts it: age one, the zero asset index, the
        ! employed and clean unemployment state, no housing carried in and no
        ! voucher, with productivity drawn from the penalised distribution.
    
        use Global_Vars
        
        implicit none
        
        integer, intent(in) :: time_period
        integer :: node_index_1,d_index_1,h_index_1,parent_node_1
        
        expected_child_value=0

        ! THE VALUE FUNCTION IS NOT ZERO BEFORE IT IS SOLVED, it is
        ! large_negative_num, and reading it then put roughly -1.8e10 into every
        ! household's continuation on the first pass. That is not a small error:
        ! it makes death arbitrarily bad, so the first pass would buy survival at
        ! any price and the whole solve starts from a distorted policy.
        !
        ! So the sentinel is checked rather than assumed. Until age one has
        ! actually been solved the child is worth zero, which is where the model
        ! sat before this term existed, and the term switches itself on at the
        ! second pass when there is something real to read.
        if (value_function(1)%vector_transition_real&
            (min(time_period+solve_transition_dynamics,transition_length),1,&
            negative_financial_grid_size,1,1,0,0)<=large_negative_num/2) then

            return

        end if
        
        do d_index_1=0,1
        
            do h_index_1=1,2

              do parent_node_1=1,employment_grid_size

                do node_index_1=1,employment_grid_size
                
                    expected_child_value(parent_node_1,d_index_1,h_index_1)=&
                        expected_child_value(parent_node_1,d_index_1,h_index_1)+&
                        newborn_employment_probability(node_index_1,parent_node_1,d_index_1,h_index_1)*&
                        value_function(1)%vector_transition_real&
                        (min(time_period+solve_transition_dynamics,transition_length),1,&
                        negative_financial_grid_size,1,node_index_1,0,0)
                
                end do

              end do

            end do

        end do

        ! ONLY THE PENALTY ENTERS, NOT THE LEVEL.
        !
        ! The term is beta*(1-phi(d,h))*omega*E[V_child(d,h)], weighted by the
        ! probability of dying because a newborn replaces a household that dies.
        ! Written with the level in it, it pays a household MORE the likelier it is
        ! to die, and the disorder raises the death hazard eightfold, so it paid
        ! most to exactly the households the paper wants deterred. Measured at the
        ! calibrated point: omega*E[V_child] was 0.826 utils, worth 0.008 to a
        ! clean housed household and 0.066 to one with the disorder, a differential
        ! of 0.058 utils REWARDING the disorder, against a genuine gradient in
        ! E[V_child] of 60.291 versus 60.276, or 0.02 per cent. The externality was
        ! a rounding error beside a perverse incentive.
        !
        ! So the level is netted out and the term becomes
        ! beta*(1-phi(d,h))*omega*[E[V_child(d,h)] - E[V_child(0,1)]], which is
        ! zero for a clean housed parent and negative otherwise. What remains is
        ! the loss the parent's own state imposes on its child, weighted by the
        ! chance the child is actually born, which is what omega is the weight on.
        !
        ! The model already has a separate bequest motive for the value of leaving
        ! something behind, so the level was double counting it.
        child_value_ready=1

        ! Differenced WITHIN each parent node, so what remains is the loss the
        ! parent's own state imposes on its child holding the parent's
        ! productivity fixed -- which is the object omega is the weight on, and
        ! which is now different for a rich parent and a poor one.
        expected_child_value(:,1,1)=expected_child_value(:,1,1)-expected_child_value(:,0,1)
        expected_child_value(:,0,2)=expected_child_value(:,0,2)-expected_child_value(:,0,1)
        expected_child_value(:,1,2)=expected_child_value(:,1,2)-expected_child_value(:,0,1)
        expected_child_value(:,0,1)=0

        ! The counterfactual now simply removes what is left, which is the penalty
        ! alone. Switching it off makes using cheaper, so use RISES, which is the
        ! sign the moment in the note describes.
        if (child_penalty_off==1) then

            expected_child_value=0

        end if
    
    end subroutine
    
    subroutine create_newborn_employment_probability()

        ! THE CHILD'S PRODUCTIVITY DRAW, CONDITIONAL ON THE PARENT'S.
        !
        ! An AR(1) in logs on the existing grid, with a level shift for the
        ! parent's disorder and homelessness:
        !
        !   log y_child - mu = rho (log y_parent - mu) + log(penalty) + eps
        !   eps ~ N(0, sigma^2 (1 - rho^2))
        !
        ! The innovation variance is sigma^2(1-rho^2) so that the STATIONARY
        ! cross section still has log standard deviation sigma. That matters:
        ! sd_permanent_productivity is calibrated on the bottom half earnings
        ! share, and an AR(1) with the full sigma as its innovation would widen
        ! the cross section and break that moment.
        !
        ! WHAT CHANGED AND WHY. rho used to be zero -- the draw was indexed by
        ! the parent's disorder and housing status and nothing else, so children
        ! of the top node and of the bottom node drew the same distribution and
        ! poverty was redrawn every generation. That is an identification
        ! problem: penalty_child_addicted is calibrated on the child disorder
        ! ratio and with no baseline persistence it had to explain all of it,
        ! when the literature finds that adjusting for parental education,
        ! income, social class and family type removes about HALF the effect of
        ! parental substance abuse on offspring outcomes. Both channels are real
        ! and roughly equal, and only one of them was here.
        !
        ! At rho = 0 this reduces to the unconditional distribution shifted by
        ! the penalty, which is the old behaviour, so the two are comparable.
        !
        ! THE PROBABILITIES ARE INTEGRATED, NOT SPLIT. Each cell's mass is the
        ! normal measure of its own log interval, so a penalty is applied to the
        ! distribution rather than to a pair of neighbouring nodes. The old two
        ! point split was linear in logs and so preserved the geometric mean of
        ! the pair, which overstated E[y] by about four per cent -- almost all
        ! of it at the top node, where the gap from 1.32 to 3.09 is widest.

        use Global_Vars

        implicit none

        integer :: d_index,h_index,child_index,parent_index
        real(8) :: penalty,mu_1,sigma_e_1,mean_1,mass_1,sd_log_y_1

        ! THE WIDTH OF THE DISTRIBUTION THE NODES WERE CUT FROM. Under the
        ! quantile grid that is sd_permanent_productivity by construction, and
        ! under the KKK grid it is the age one cross sectional sd the process
        ! implies, which is 0.409 rather than 0.965. Using the wrong one here
        ! would not fail: it would integrate a lognormal of the wrong width over
        ! the right intervals and hand back a child distribution that is far too
        ! spread out or far too tight, with nothing in the output to say so.
        sd_log_y_1=sd_permanent_productivity

        if (fixed_productivity==0) sd_log_y_1=sd_log_y_newborn

        mu_1=-sd_log_y_1**2/2
        sigma_e_1=sd_log_y_1*&
            sqrt(max(1.d0-rho_intergenerational**2,10.d0**(-12)))

        newborn_employment_probability=0

        do d_index=0,1

            do h_index=1,2

                penalty=((1-penalty_child_addicted)**(d_index*include_child_penalty))*&
                    ((1-penalty_child_homeless)**((h_index-1)*include_child_penalty))

                do parent_index=1,employment_grid_size

                    mean_1=mu_1+rho_intergenerational*&
                        (log(employment_grid(1,parent_index))-mu_1)+log(penalty)

                    do child_index=1,employment_grid_size

                        newborn_employment_probability(child_index,parent_index,d_index,h_index)=&
                            normal_cdf((log_y_edge(child_index+1)-mean_1)/sigma_e_1)-&
                            normal_cdf((log_y_edge(child_index)-mean_1)/sigma_e_1)

                    end do

                    mass_1=sum(newborn_employment_probability(:,parent_index,d_index,h_index))

                    if (mass_1>10.d0**(-14)) then

                        newborn_employment_probability(:,parent_index,d_index,h_index)=&
                            newborn_employment_probability(:,parent_index,d_index,h_index)/mass_1

                    else

                        newborn_employment_probability(1,parent_index,d_index,h_index)=1

                    end if

                end do

            end do

        end do

    end subroutine

    subroutine GKKOC_intergenerational_employment_process(time_period)
    
        use Global_Vars
        
        implicit none

        ! persistence_fixed_employment_newborn, s_deviation_top and
        ! s_deviation_bottom used to be declared here. They are in Global_Vars,
        ! under the names kkk_s_deviation_top and kkk_s_deviation_bottom,
        ! now so that a point file can set them; a local declaration here would
        ! shadow the global and silently ignore every HANDOVER line.
        real(8) :: sd_fixed_y,width_fixed_y
        ! ABOVE ONE PACKS THE NODES TOWARD THE BOTTOM, which is the stylized
        ! model's GRID_KAPPA and the same reasoning: the drug, housing and
        ! homelessness margins all sit at the bottom, so that is where the
        ! resolution is worth paying for. At 2.5 with thirteen nodes the bottom
        ! interval carries 0.164 per cent of households, comfortably under the
        ! 0.399 per cent the homelessness target asks for.
        ! 2.8 -> 3.2 WITH THE MOVE TO SEVEN NODES. The bottom node's mass is
        ! (1/N)**kappa, so cutting N from seventeen to seven at kappa 2.8 would
        ! have taken it from 0.036 to 0.43 per cent -- straight back above the
        ! 0.399 per cent homelessness target and into the step function that
        ! broke the bracket before. 3.2 puts it at 0.198 per cent. See the block
        ! beside employment_grid_size for the whole design.
        real(8), dimension(employment_grid_size+1) :: p_edge_1,tail_mean_1
        real(8) :: sum_of_dist,sum_of_unconditional_unemployment
        real(8) :: mu_prod_1,sigma_prod_1,mean_prod_1,row_sum_prod_1
        real(8) :: bottom_mass_1,bottom_old_1,bottom_rescale_1
        integer :: merged_n_1,merge_lo_1
        real(8) :: low_sum_1
        integer, intent(in) :: time_period
         
        if (loop_count<1) then

            ! BOTH SDS CARRY kkk_sigma_scale. It is applied here rather than to
            ! the declarations so that the point file's sd_fixed_employment_newborn
            ! and sd_employment_surviving keep reading as the published GKOS
            ! numbers and the scale reads as what it is: a separate, calibrated
            ! statement about how much dispersion one productivity type has to
            ! carry in a model with no other permanent heterogeneity.
            call KKK_process(persistence_fixed_employment_newborn,&
                kkk_sigma_scale*sd_fixed_employment_newborn,persistence_employment_surviving,&
                kkk_sigma_scale*sd_employment_surviving,kkk_s_deviation_top,kkk_s_deviation_bottom,&
                employment_grid,unconditional_employment_probability,employment_process)
                
!            employment_grid(:,1)=log(0.035)*(employment_grid(:,1)/employment_grid(1,1))  !employment_grid(:,1) ! 1.12
            ! The bottom node override does NOT go here. fixed_productivity is 1,
            ! so the quantile construction further down REBUILDS employment_grid
            ! from tail_mean_1 and would silently overwrite anything set here.
            ! It was written here first and was inert. See the mean preserving
            ! version beside the tail_mean assignment.
!            employment_grid(:,2)=log(0.02) ! employment_grid(:,2) ! 1.48
!            employment_grid(:,3)=log(0.03) ! employment_grid(:,3) ! 1.68
!            employment_grid(:,4)=employment_grid(:,4)
                                                                                
            call get_probabilities_KKK_process(persistence_fixed_employment_newborn,&
                kkk_sigma_scale*sd_fixed_employment_newborn,&
                persistence_employment_surviving,kkk_sigma_scale*sd_employment_surviving,&
                employment_grid,unconditional_employment_probability,employment_process)

            ! ------------------------------------------------------------------
            ! WHAT THE KKK GRID NEEDS BEFORE IT CAN BE USED ON ITS OWN.
            !
            ! Everything in this block is dead when fixed_productivity is 1,
            ! because the quantile construction below rebuilds employment_grid
            ! from scratch and overwrites all of it. It matters only when the
            ! author's process IS the grid, and each piece is here because
            ! without it the KKK path is wrong rather than merely different.
            ! ------------------------------------------------------------------

            ! (1) THE RETIREMENT ROWS ARE UNDEFINED ON RETURN. KKK_process
            ! declares z_grid_by_age over the WHOLE life span but fills only
            ! ages 1 to life_span-retirement_span; the retired rows are never
            ! assigned, and the exp() below would then exponentiate whatever was
            ! in that memory. With fixed_productivity=1 nothing came of it,
            ! because every row is overwritten with row one a few hundred lines
            ! down. With the flag off those rows are the grid the retired
            ! actually face -- bequests at 21851 and the wage ceiling at 21911
            ! read employment_grid(age_index,:) -- so they are frozen here at the
            ! last working age, which is also the type the household retires as.
            do age_index=life_span-retirement_span+1,life_span

                employment_grid(age_index,:)=employment_grid(life_span-retirement_span,:)

            end do

            ! (2) THE CROSS SECTIONAL SD AT AGE ONE, in closed form from the same
            ! recursion KKK_process runs internally. The newborn draw integrates
            ! a lognormal over the node intervals and needs the width of the
            ! distribution the nodes were cut from; under the quantile grid that
            ! is sd_permanent_productivity, and here it is this.
            sd_log_y_newborn=kkk_sigma_scale*sqrt(sd_employment_surviving**2+&
                sd_fixed_employment_newborn**2/&
                max(1.d0-persistence_fixed_employment_newborn**2,10.d0**(-12)))

            ! (3) MEAN PRODUCTIVITY OF ONE. The process centres LOG productivity
            ! on zero at every age, so the LEVEL has mean exp(var(a)/2), which is
            ! 1.087 at age one rather than 1. Every level parameter in the model
            ! -- the food cost, the house sizes, the value of life -- is quoted
            ! in units of mean productivity, so leaving it at 1.087 would shift
            ! all of them by nine per cent for no reason. One constant is
            ! subtracted in logs, the SAME constant at every age, so the fanning
            ! is untouched: only the units move.
            !
            ! Mean productivity is then exactly 1 at age one and drifts to 1.022
            ! by the end of working life, which is the fan itself and not an
            ! error. The deterministic age profile carries the intended age
            ! profile of mean earnings on top of it.
            mean_prod_1=0

            do employment_index=1,employment_grid_size

                mean_prod_1=mean_prod_1+unconditional_employment_probability(employment_index)*&
                    exp(employment_grid(1,employment_index))

            end do

            employment_grid=employment_grid-log(max(mean_prod_1,10.d0**(-12)))

            ! (4) THE NODE BOUNDARIES IN LOGS, which the newborn draw and the
            ! intergenerational penalty both integrate over. The declaration
            ! initialiser leaves log_y_edge at zero, and zero edges make every
            ! interval empty: create_newborn_employment_probability would find
            ! mass_1 = 0 for every parent, fall into its else branch and put
            ! EVERY newborn on the bottom node. That is silent -- no stop, no
            ! NaN, just a model where all children are born destitute -- and it
            ! is the single largest reason this switch is not one line.
            !
            ! The interior edges are the midpoints of the age one log grid,
            ! which is exactly the partition KKK_process itself used to compute
            ! the node masses, so the draw reproduces those masses instead of
            ! some other set. The outer edges run to plus and minus twelve, as
            ! on the quantile grid.
            log_y_edge(1)=-12.d0
            log_y_edge(employment_grid_size+1)=12.d0

            do employment_index=2,employment_grid_size

                log_y_edge(employment_index)=&
                    (employment_grid(1,employment_index-1)+employment_grid(1,employment_index))/2.d0

            end do

            employment_grid=exp(employment_grid)

            if (fixed_productivity==0) then

                write(*,*) "KKK productivity process live. sd of log y at age 1 =", sd_log_y_newborn
                write(*,*) "  grid age 1  :", employment_grid(1,:)
                write(*,*) "  grid last working age:", employment_grid(life_span-retirement_span,:)
                write(*,*) "  masses at age 1:", unconditional_employment_probability
                write(*,*) "  mean productivity at age 1 =",&
                    sum(unconditional_employment_probability*employment_grid(1,:))

            end if

        end if
                                                                                    
        if (loop_count<1) then
        
            write(*,*) "employment_grid"
        
            do i=1,employment_grid_size
                    
                write(*,*) employment_grid(1,i)     
                
            end do
            
            write(*,*) "unconditional_employment_probability"
            
            do i=1,employment_grid_size
            
                write(*,*) unconditional_employment_probability(i)
                
            end do
                        
        end if
        
        unconditional_unemployment_probability(:)=0
        
        if (loop_count<1) then
        
            unconditional_unemployment_probability(1)=1 !0.95155279776391399
            unconditional_unemployment_probability(2)=0 !3.4048867272342742E-002
            ! COMPLETE THE ROW OVER THE WHOLE VECTOR, NOT OVER ITS FIRST TWO
            ! ENTRIES. unconditional_unemployment_probability is six long: the
            ! clean block 1:3 and the SMI block 4:6. Completing over 1:2 left the
            ! SMI entries, filled from the stationary distribution just above,
            ! outside the sum, so the vector totalled 1 plus the SMI share of the
            ! clean population. It is the initial guess for the distribution
            ! iteration, which converges to a fixed point independent of its
            ! guess, so no reported moment moves -- but it inflated the starting
            ! mass and the sum(distribution_guess) diagnostic, and cost sweeps.
            unconditional_unemployment_probability(3)=1-sum(unconditional_unemployment_probability(1:2))&
                -sum(unconditional_unemployment_probability(4:threshold_addiction_index))
            
        else
        
            sum_of_dist=0
                
            do unemployment_index=1,threshold_addiction_index
            
                do i=1,2
                
                    sum_of_dist=sum_of_dist+&
                        sum(distribution_stationary(i)%vector_transition_real(time_period,:,:,unemployment_index,:,:,:))
            
                    unconditional_unemployment_probability(unemployment_index)=&
                        unconditional_unemployment_probability(unemployment_index)+&
                        sum(distribution_stationary(i)%vector_transition_real(time_period,:,:,unemployment_index,:,:,:))
                    
                end do
                            
            end do
            
            unconditional_unemployment_probability(:)=&
                unconditional_unemployment_probability(:)/sum_of_dist
                
            sum_of_unconditional_unemployment=sum(unconditional_unemployment_probability(:))
            
            unconditional_unemployment_probability(:)=&
                unconditional_unemployment_probability(:)*(1/sum_of_unconditional_unemployment)
                
            unconditional_unemployment_probability(1)=1 !0.95155279776391399
            unconditional_unemployment_probability(2)=0 !3.4048867272342742E-002
            ! COMPLETE THE ROW OVER THE WHOLE VECTOR, NOT OVER ITS FIRST TWO
            ! ENTRIES. unconditional_unemployment_probability is six long: the
            ! clean block 1:3 and the SMI block 4:6. Completing over 1:2 left the
            ! SMI entries, filled from the stationary distribution just above,
            ! outside the sum, so the vector totalled 1 plus the SMI share of the
            ! clean population. It is the initial guess for the distribution
            ! iteration, which converges to a fixed point independent of its
            ! guess, so no reported moment moves -- but it inflated the starting
            ! mass and the sum(distribution_guess) diagnostic, and cost sweeps.
            unconditional_unemployment_probability(3)=1-sum(unconditional_unemployment_probability(1:2))&
                -sum(unconditional_unemployment_probability(4:threshold_addiction_index))
                    
        end if
                                     
        if (loop_count<1) then
            
            do employment_index=1,employment_grid_size
                        
                write(*,*) "employment_process(",1,employment_index,")=", employment_process(1,employment_index,:)
                            
            end do
                            
        end if
                
        ! With fixed_productivity the identity transition starts at age one
        ! rather than at retirement, and the grid is frozen at its mid working
        ! life width so that the cross sectional dispersion is the average of
        ! what the stochastic process delivered.
        ! A COUNTERFACTUAL AGAINST A ZEROED BENCHMARK PROFILE IS NOT A
        ! COUNTERFACTUAL. average_labor_income_by_employment_calibrated holds the
        ! benchmark's income by node and was taken on the nine node grid, so it
        ! is zero until the recalibrated benchmark refills it. Running anyway
        ! would price every household against an economy with no income in it and
        ! still produce numbers, which is the failure mode worth stopping for.
        if ((is_counterfactual==1) .AND. &
            (sum(abs(average_labor_income_by_employment_calibrated))<=0)) then

            write(*,*) "STOP: average_labor_income_by_employment_calibrated is empty."
            write(*,*) "   It was taken on the nine node grid and this build has",&
                employment_grid_size, " nodes placed by quantile."
            write(*,*) "   Recalibrate the benchmark and write the new profile in",&
                " before running a counterfactual."
            stop

        end if

        if (fixed_productivity==1) then
        
            ! NODES AT THE CONDITIONAL MEAN OF QUANTILE INTERVALS.
            !
            ! The old placement spread the nodes evenly in logs between plus and
            ! minus three standard deviations and then read each node's mass off
            ! a midpoint of that spacing. Two things came of it. The tails were
            ! truncated, so the truncation point rather than the model decided
            ! how many households could not afford to rent, which is the fault
            ! the stylized model recorded fixing and which was never checked
            ! against this one. And the mass sat in a few large lumps at the
            ! bottom, so homelessness moved in steps far wider than its target.
            !
            ! Now the CDF is cut at p_i = (i/n)^kappa, each node is the mean of
            ! the lognormal conditional on falling in its own interval, and each
            ! node's mass is that interval's mass. Nothing is truncated: the
            ! bottom interval runs to zero and the top to infinity, and both are
            ! represented by the mass they actually carry. Mean productivity is
            ! one by construction rather than by rescaling, since the interval
            ! means weighted by the interval masses sum to the whole mean.
            do employment_index=1,employment_grid_size+1

                p_edge_1(employment_index)=&
                    (real(employment_index-1,8)/real(employment_grid_size,8))**y_grid_kappa

            end do

            p_edge_1(1)=0
            p_edge_1(employment_grid_size+1)=1

            ! THE NODE BOUNDARIES IN LOG PRODUCTIVITY, kept for the newborn
            ! draw. The grid is a lognormal of mean one, so its log has mean
            ! -sigma^2/2, and node i covers the interval between the p_edge
            ! quantiles of that distribution. The child's conditional
            ! distribution is integrated over these intervals rather than split
            ! between two neighbouring nodes, which is exact where the split was
            ! not: the two point split preserved the GEOMETRIC mean of the pair
            ! and so overstated E[y] by about four per cent, almost all of it at
            ! the top node where the gap from 1.32 to 3.09 is widest.
            do employment_index=1,employment_grid_size+1
                if (p_edge_1(employment_index)<=0) then
                    log_y_edge(employment_index)=-12.d0
                else if (p_edge_1(employment_index)>=1) then
                    log_y_edge(employment_index)=12.d0
                else
                    log_y_edge(employment_index)=-sd_permanent_productivity**2/2+&
                        sd_permanent_productivity*normal_quantile(p_edge_1(employment_index))
                end if
            end do

            do employment_index=1,employment_grid_size+1

                tail_mean_1(employment_index)=&
                    lognormal_tail_mean(p_edge_1(employment_index),sd_permanent_productivity)

            end do

            ! THE NEWBORN'S PARENT SHARES HAVE TO START SOMEWHERE, and a
            ! declaration initialiser cannot do it: the array is now indexed by
            ! the parent's productivity node and the unconditional distribution
            ! over nodes is not known until this loop has run.
            !
            ! The old declaration was reshape((/1,0,0,0/)), mass one in the
            ! clean housed cell. Extending the array to carry the parent's node
            ! and initialising it to zero left NO mass anywhere, so
            ! newborn_productivity_draw came out zero, no newborns were created
            ! and the population died out. Every distribution based moment came
            ! back 0 or NaN while sigma_y, which is computed from the grid and
            ! not the distribution, looked perfectly healthy.
            !
            ! Set here, and only if nothing has set it: a resumed run reads its
            ! own shares from the state file and must not be overwritten.
            if (sum(newborn_parent_share)<=10.d0**(-12)) then

                newborn_parent_share=0

                do employment_index=1,employment_grid_size

                    newborn_parent_share(employment_index,0,1)=&
                        p_edge_1(employment_index+1)-p_edge_1(employment_index)

                end do

            end if

            do employment_index=1,employment_grid_size

                unconditional_employment_probability(employment_index)=&
                    p_edge_1(employment_index+1)-p_edge_1(employment_index)

                employment_grid(1,employment_index)=&
                    (tail_mean_1(employment_index+1)-tail_mean_1(employment_index))/&
                    max(unconditional_employment_probability(employment_index),10.d0**(-14))

            end do

            ! THE BOTTOM NODE'S LEVEL, MEAN PRESERVING. Live when
            ! bottom_productivity_level>0; at 0 this block does nothing and the
            ! quantile construction stands exactly as built.
            !
            ! The author, 3 September: *"choose the point on the y grid such that
            ! it gives the right productivity and the right mass exactly for what
            ! we need that still preserves the mean of 1"*. That is what this is,
            ! and it is better than the first version of this lever, which simply
            ! wrote the new level in and let the mean drift.
            !
            ! Sum m_i y_i is exactly one before the change, by construction. Move
            ! the bottom node to y_1_new and the other nodes carry
            !
            !     f = (1 - m_1 y_1_new) / (1 - m_1 y_1_old)
            !
            ! so that m_1 y_1_new + f (1 - m_1 y_1_old) = 1 again, exactly. The
            ! nodes above the bottom keep their RELATIVE spacing; only the scale
            ! of the upper part moves, and by a factor bounded by the bottom
            ! node's mass, which is a fifth of one per cent.
            !
            ! The mass is the OTHER instrument, y_grid_kappa, and it acts through
            ! p_edge_1 above. Level and mass are therefore set independently,
            ! which is what makes them two instruments for two moments rather
            ! than one dial with two names.
            if (bottom_productivity_level>0.d0) then

                merge_lo_1=max(1,min(int(merge_from_node+0.5d0),employment_grid_size-1))
                merged_n_1=max(merge_lo_1,min(int(merge_bottom_nodes+0.5d0),employment_grid_size-1))
                bottom_mass_1=sum(unconditional_employment_probability(merge_lo_1:merged_n_1))
                bottom_old_1=sum(unconditional_employment_probability(merge_lo_1:merged_n_1)*&
                    employment_grid(1,merge_lo_1:merged_n_1))/max(bottom_mass_1,10.d0**(-14))

                ! THE NODES BELOW merge_lo_1 ARE UNTOUCHED, so they carry their
                ! own contribution to the mean and it must come out of both sides
                ! of the rescale. A zero-length section sums to zero in Fortran,
                ! so at merge_lo_1=1 this is identically the old expression.
                low_sum_1=sum(unconditional_employment_probability(1:merge_lo_1-1)*&
                    employment_grid(1,1:merge_lo_1-1))
                bottom_rescale_1=(1.d0-low_sum_1-bottom_mass_1*bottom_productivity_level)/&
                    max(1.d0-low_sum_1-bottom_mass_1*bottom_old_1,10.d0**(-14))

                employment_grid(1,merge_lo_1:merged_n_1)=bottom_productivity_level
                employment_grid(1,merged_n_1+1:employment_grid_size)=&
                    employment_grid(1,merged_n_1+1:employment_grid_size)*bottom_rescale_1

                write(*,*) "merged nodes", merge_lo_1, "to", merged_n_1, ": level",&
                    bottom_old_1, "->", bottom_productivity_level
                write(*,*) "merged mass=", bottom_mass_1, " held below=", low_sum_1,&
                    " upper rescale=", bottom_rescale_1
                write(*,*) "mean productivity after override=",&
                    sum(unconditional_employment_probability(1:employment_grid_size)*&
                    employment_grid(1,1:employment_grid_size))

            end if

            do age_index=1,life_span
            
                employment_grid(age_index,:)=employment_grid(1,:)
                
            end do
            
            ! THE DISTRIBUTION HAS TO BE REBUILT ON THE FROZEN GRID, not left as
            ! it was. get_probabilities_KKK_process fills
            ! unconditional_employment_probability from the variance of log
            ! productivity at AGE ONE, on the age one grid. Freezing the grid at
            ! its mid working life width without touching the probabilities
            ! would put age one mass on a wider grid, which silently changes the
            ! dispersion of permanent income and takes the wealth targets with
            ! it. Both are rebuilt here from the single variance the frozen grid
            ! implies, recovered from the grid itself: the top node sits
            ! kkk_s_deviation_top standard deviations above the mean of log
            ! productivity, which is zero by construction.
            ! The top node is exp(-sigma^2/2 + kkk_s_deviation_top*sigma) now, so
            ! sigma cannot be read off it by dividing. It is taken directly.
            sd_fixed_y=sd_permanent_productivity
            
            ! THE MASSES CAME WITH THE NODES, so there is nothing to rebuild.
            ! This used to recover a width from the grid and read each node's
            ! mass off a midpoint of that width, which only works when the nodes
            ! are evenly spaced. They are not any more: the mass IS the interval
            ! it was cut from, and it sums to one by construction.
            sd_fixed_y=sd_permanent_productivity

            ! THE MOMENT sigma_y IS CALIBRATED ON, computed in one place for
            ! both grids. It used to be written out here, inside the quantile
            ! branch, which meant that with fixed_productivity=0 the share stayed
            ! at zero and sigma_y's adjuster was chasing a moment nobody filled.
            call compute_bottom_half_earnings_share()

            if (loop_count<1) then

                write(*,*) "fixed productivity: sd of log y =", sd_fixed_y
                write(*,*) "bottom half's share of productivity =",&
                    model_bottom_half_earnings_share, " target =", bottom_half_earnings_share_data
                write(*,*) "unconditional_employment_probability on the frozen grid"
                write(*,*) unconditional_employment_probability

            end if

        end if

        ! THE SAME HOUSEKEEPING FOR THE KKK GRID. The quantile branch above sets
        ! two things besides the grid itself: the share of newborn parents by
        ! node, and the moment sigma_y is calibrated on. Neither is optional and
        ! neither belongs to the quantile construction, so both are done here
        ! when that construction did not run.
        if (fixed_productivity==0) then

            ! The newborn's parent shares, as at 27975 in the quantile branch and
            ! for the same reason: the array is indexed by the parent's node and
            ! a declaration initialiser cannot know the distribution over nodes.
            ! Left at zero, newborn_productivity_draw comes out zero, no newborns
            ! are created and the population dies out while sigma_y still looks
            ! healthy, because sigma_y is read off the grid and not the
            ! distribution. Set only if nothing has set it: a resumed run reads
            ! its own shares from the state file.
            if (sum(newborn_parent_share)<=10.d0**(-12)) then

                newborn_parent_share=0

                do employment_index=1,employment_grid_size

                    newborn_parent_share(employment_index,0,1)=&
                        unconditional_employment_probability(employment_index)

                end do

            end if

            ! THE BOTTOM NODE'S LEVEL UNDER KKK, MEAN PRESERVING AT EVERY AGE.
            !
            ! On the author's instruction of 3 September: *"I also want the other
            ! levers we discussed"*. bottom_productivity_level was built for the
            ! quantile grid and lives inside `if (fixed_productivity==1)`, so
            ! under KKK it did nothing at all and the only bottom-node control
            ! was kkk_s_deviation_bottom -- which moves the node's MASS and its
            ! LEVEL together and so cannot separate them.
            !
            ! Here it is the same construction as the quantile version and for
            ! the same reason. Sum m_i y_i is one at age one by construction, so
            ! moving the bottom node to y_new and scaling the rest by
            !
            !     f = (1 - m_1 y_new) / (1 - m_1 y_old)
            !
            ! restores the mean exactly. The nodes above the bottom keep their
            ! relative spacing.
            !
            ! APPLIED AT EVERY AGE, not only at age one, and that is what makes
            ! it right under a fanning grid. The masses are the same at every age
            ! -- the grid scales with sd(a), so in standardised units the nodes
            ! and their masses do not move -- but the LEVELS do, so each age gets
            ! its own rescale factor computed from its own bottom node. The fan
            ! survives: only the bottom node and the scale of the block above it
            ! move, and they move by the same proportion at every age.
            if (bottom_productivity_level>0.d0) then

                merge_lo_1=max(1,min(int(merge_from_node+0.5d0),employment_grid_size-1))
                merged_n_1=max(merge_lo_1,min(int(merge_bottom_nodes+0.5d0),employment_grid_size-1))
                bottom_mass_1=sum(unconditional_employment_probability(merge_lo_1:merged_n_1))

                do age_index=1,life_span

                    bottom_old_1=sum(unconditional_employment_probability(merge_lo_1:merged_n_1)*&
                        employment_grid(age_index,merge_lo_1:merged_n_1))/max(bottom_mass_1,10.d0**(-14))

                    ! The held block is age-specific because the grid fans, so its
                    ! sum is recomputed inside the age loop rather than hoisted.
                    low_sum_1=sum(unconditional_employment_probability(1:merge_lo_1-1)*&
                        employment_grid(age_index,1:merge_lo_1-1))
                    bottom_rescale_1=(1.d0-low_sum_1-bottom_mass_1*bottom_productivity_level)/&
                        max(1.d0-low_sum_1-bottom_mass_1*bottom_old_1,10.d0**(-14))

                    employment_grid(age_index,merge_lo_1:merged_n_1)=bottom_productivity_level
                    employment_grid(age_index,merged_n_1+1:employment_grid_size)=&
                        employment_grid(age_index,merged_n_1+1:employment_grid_size)*bottom_rescale_1

                end do

                if (loop_count<1) then

                    write(*,*) "KKK bottom node overridden to", bottom_productivity_level
                    write(*,*) "  mass", bottom_mass_1, " mean productivity at age 1 =",&
                        sum(unconditional_employment_probability*employment_grid(1,:))
                    write(*,*) "  grid age 1  :", employment_grid(1,:)
                    write(*,*) "  grid last working age:", employment_grid(life_span-retirement_span,:)

                end if

            end if

            call compute_bottom_half_earnings_share()

            if (loop_count<1) then

                write(*,*) "KKK grid: bottom half's share of productivity =",&
                    model_bottom_half_earnings_share, " target =", bottom_half_earnings_share_data

            end if

        end if
        
        ! PERSISTENT INCOME RISK OVER THE LIFE CYCLE, on the author's instruction
        ! of 3 September: *"I say build it with the right persistence and SD as in
        ! guvenen et al."*
        !
        ! WHY THIS IS NOT fixed_productivity=0. Setting that flag to zero does not
        ! add risk to this grid -- it abandons the grid. The quantile construction,
        ! y_grid_kappa, the bottom node's mass and bottom_productivity_level all
        ! live inside `if (fixed_productivity==1)`, and with the flag off the grid
        ! comes from KKK_process instead, whose bottom node carries binomial mass
        ! of 1.6 per cent rather than the 0.198 the design asks for. Everything
        ! built tonight would be discarded to buy the risk.
        !
        ! So the grid STAYS the quantile grid and only the TRANSITION changes. The
        ! AR(1) is discretised onto the intervals the grid already defines, using
        ! the same construction the intergenerational draw uses a few hundred
        ! lines above with rho_intergenerational:
        !
        !     mean_i    = mu + rho (log y_i - mu),   mu = -sigma_z^2/2
        !     P(i -> j) = Phi((edge_{j+1}-mean_i)/sigma_eps)
        !               - Phi((edge_j    -mean_i)/sigma_eps)
        !
        ! with sigma_eps = sigma_z sqrt(1-rho^2).
        !
        ! THE STATIONARY DISTRIBUTION IS PRESERVED EXACTLY, because the grid IS
        ! the quantile partition of the stationary lognormal and the transition is
        ! that lognormal's own conditional law. sigma_y therefore survives, which
        ! is the thing the comment beside fixed_productivity warns is lost when
        ! the flag is flipped.
        !
        ! PERSISTENCE. rho_productivity defaults to 0.98, which is the region
        ! Guvenen, Karahan, Ozkan and Song estimate for the persistent component
        ! of annual earnings. The innovation is then pinned, not free:
        ! sd_permanent_productivity is 0.9651 and 0.9651*sqrt(1-0.98^2) = 0.1921,
        ! which is almost exactly the 0.20 that sd_employment_surviving already
        ! held. The number in the file was right all along; rho at 0.90 was what
        ! collapsed the dispersion to 0.459.
        !
        ! WHAT IS NOT YET HERE. GKOS's central finding is that earnings shocks are
        ! strongly LEPTOKURTIC and LEFT-SKEWED, and a Gaussian AR(1) has no such
        ! tail: a one-in-a-hundred ten year path under this process lands at 0.37
        ! times earnings, which is a bad decade and not a catastrophe. The rare
        ! large fall is the thing that would put a middle-aged household with
        ! savings onto the street, and it needs a mixture innovation rather than a
        ! normal one. That is a second step and it is deliberately not in this one.
        if ((persistent_income_risk==1) .AND. (fixed_productivity==1)) then

            mu_prod_1=-sd_permanent_productivity**2/2
            sigma_prod_1=sd_permanent_productivity*&
                sqrt(max(1.d0-rho_productivity**2,10.d0**(-12)))

            do age_index=1,life_span-retirement_span-1

                do employment_index=1,employment_grid_size

                    mean_prod_1=mu_prod_1+rho_productivity*&
                        (log(employment_grid(1,employment_index))-mu_prod_1)

                    do future_employment_index=1,employment_grid_size

                        employment_process(age_index,employment_index,future_employment_index)=&
                            normal_cdf((log_y_edge(future_employment_index+1)-mean_prod_1)/sigma_prod_1)-&
                            normal_cdf((log_y_edge(future_employment_index)-mean_prod_1)/sigma_prod_1)

                    end do

                    ! ROWS MUST SUM TO ONE. The outer edges are set to plus and
                    ! minus twelve rather than infinity, so the two tail cells lose
                    ! a sliver of probability that has to go back somewhere.
                    row_sum_prod_1=sum(employment_process(age_index,employment_index,:))

                    if (row_sum_prod_1>10.d0**(-12)) then

                        employment_process(age_index,employment_index,:)=&
                            employment_process(age_index,employment_index,:)/row_sum_prod_1

                    else

                        employment_process(age_index,employment_index,:)=0
                        employment_process(age_index,employment_index,employment_index)=1

                    end if

                end do

            end do

        end if

        ! The identity transition. With persistent_income_risk it covers
        ! retirement only, which is what makes social security depend on the type
        ! the household RETIRES as -- income_1=model_ss_benefits(employment_index_1)
        ! reads the current index and it stops moving here. The author asked for
        ! exactly that on 3 September.
        do age_index=(1-persistent_income_risk)*(fixed_productivity*1+&
            (1-fixed_productivity)*(life_span-retirement_span))+&
            persistent_income_risk*(life_span-retirement_span),life_span
        
            do employment_index=1,employment_grid_size
            
                do future_employment_index=1,employment_grid_size
                
                    if (future_employment_index==employment_index) then
                    
                        employment_process(age_index,employment_index,future_employment_index)=1
                    
                    else
                    
                        employment_process(age_index,employment_index,future_employment_index)=0
                    
                    end if
                    
                end do
                
            end do
            
        end do
        
        call load_mortality_profiles()

        ! Before recompute_derived_parameters, which builds the onset from this
        ! profile and the current lambda_m.
        call load_smi_prevalence_profile()

        call recompute_derived_parameters()

        call verify_index_map()

        call create_newborn_employment_probability()

        call create_unemployment_process()

        ! After the array exists, not before: the first placement ran the check on
        ! an unbuilt array of zeros.
        call verify_newborn_process()

        if (is_counterfactual==0) then
                   
            standard_deduction=(model_average_labour_income(1)*standard_deduction_as_percent_of_average_labor_income)
                                        
            personal_exemption=(real(personal_exemption_data)/max(real(standard_deduction_data),1.d0))*standard_deduction
                        
        end if
            
        if (loop_count<1) then

            write(*,*) "personal_exemption=", personal_exemption
            write(*,*) "standard_deduction=", standard_deduction
                
        end if
        
        if (loop_count<1) then
                                                                        
            do age_index=1,(life_span-retirement_span)
            
                if (use_GKKOC_deterministic_process==1) then
                
                    labour_deterministic_efficiency(age_index)=&
                        exp(-((real(age_index)-1.d0)**2.d0)/1800.d0+(real(age_index)-1.d0)/30.d0)
                                                    
                else
            
                    if (age_index<=life_span-retirement_span-10) then
                
                        labour_deterministic_efficiency(age_index)=(1+life_cycle_component_a*(age_index-1))
                            
                    else
                    
                        labour_deterministic_efficiency(age_index)=labour_deterministic_efficiency(life_span-retirement_span-10)-&
                            life_cycle_component_b*(age_index-(life_span-retirement_span-10))
                    
                    end if
                    
                end if
                    
                if (loop_count<1) then
                
                    if (solve_transition_dynamics==0) then
                                
!                        write(*,*) "labour efficiency=", labour_deterministic_efficiency(age_index)
!                        write(*,*) "age_index=", age_index
                        
                    end if
                    
                end if
                
            end do
                
            labour_deterministic_efficiency((life_span-retirement_span)+1:life_span)=0
            
        end if
    
    end subroutine
    
    subroutine create_unemployment_process()
    
        use global_vars
        
        ! THE LOSS-SIDE MULTIPLIER, CLAMPED SO THE SEPARATION PROBABILITY CANNOT
        ! EXCEED ONE. The two branches below split the separation probability by
        ! whether unemployment insurance is received, so they must be scaled by the
        ! SAME factor or they stop summing to it; clamping the factor rather than
        ! each branch is what preserves that.
        real(8) :: loss_mult_homeless_1,find_mult_homeless_1
        
        integer :: cutoff_age_1,cutoff_age_2
        ! THIS IS AN EXTERNALLY SET PENALTY AND IT IS NOT A DIAL. 0.2 means the
        ! separation rate times 1.2 and the job finding rate divided by 1.2: a
        ! twenty per cent penalty on each margin.
        !
        ! IT WAS RAISED TO 8.0 AND THAT WAS WRONG. The employed share of the
        ! homeless read 0.94 against a target of 0.50, and the arithmetic said a
        ! steady state of 0.50 needs a penalty near 6, so it went to 8. A steady
        ! state that needs an eight hundred per cent penalty is not evidence
        ! about the penalty, it is evidence that the moment is being asked of the
        ! wrong parameter: every parameter here is disciplined either by a moment
        ! or by an estimate from outside the model, and moving an external
        ! estimate by a factor of forty to close a moment abandons both.
        !
        ! What the moment was actually reporting was the child's penalty at 0.9
        ! manufacturing a class of workers too poor for any room. That is capped
        ! at 0.4 now, and this stays where the evidence put it.
        real(8), parameter :: increased_prob_to_be_addicted=0
        
        if (include_vouchers==0) then
        
            voucher_probabilities(0,0,0,:)=1
        
        else
        
            ! from getting a voucher to not when income goes above the threshold
            voucher_probabilities(1,0,0,:)=1
            
            ! from getting a voucher to keeping it if income is below threshold
            voucher_probabilities(1,1,1,:)=1
            
            if (increased_prob_of_voucher_if_homeless_and_addicted==0) then
            
                ! from getting a voucher to not when income is below threshold and is addicted
                voucher_probabilities(1,0,1,3)=1
                
                ! from getting a voucher to getting it when income is below threshold and is addicted
                voucher_probabilities(1,1,1,3)=0
                
                ! from not getting a voucher to getting it when income is below threshold and is addicted 
                voucher_probabilities(0,1,1,3)=0
                
                ! from not getting a voucher to not getting it when income is below threshold and is addicted
                voucher_probabilities(0,0,1,3)=1
                
            end if
            
            ! from not getting a voucher to not getting one when income is above threhsold
            voucher_probabilities(0,0,0,:)=1
            
            ! from not getting a voucher to potentially get one (if income is below the threshold)
            voucher_probabilities(0,1,1,:)=&
                (/real(probability_of_voucher_benchmark_used_1),&
                min(real(probability_of_voucher_benchmark_used_1*increased_prob_of_voucher_if_homeless_1),1.0),&
                min(real(probability_of_voucher_benchmark_used_1*increased_prob_of_voucher_if_homeless_and_addicted),1.0)/)
                
            voucher_probabilities(0,0,1,:)=(1-voucher_probabilities(0,1,1,:))
            
            ! ---- IMPERFECT ENFORCEMENT, equation (32) of the note -------------
            ! Under Treatment First the condition is checked by a test that is
            ! wrong in both directions. A household that FAILS the condition
            ! keeps the voucher with probability 1 - probability_of_detection,
            ! because the test does not always catch it; a household that MEETS
            ! the condition loses it with probability_of_false_positive.
            !
            ! This is applied to the voucher transition rather than to the
            ! voucher amount, because it is a lottery over receipt: a household
            ! that is not caught gets the whole voucher, not a fraction of one.
            ! Scaling the amount would be the certainty equivalent under risk
            ! neutrality, which is the wrong object in a model whose point is
            ! insurance.
            !
            ! INERT IN THE BENCHMARK. voucher_conditional_on_clean is zero there,
            ! nothing is conditional, no household is tested and the block does
            ! not execute. It is the counterfactual's machinery.
            if (voucher_conditional_on_clean==1) then
            
                ! category 3 is the household that fails the condition
                voucher_probabilities(0,1,1,3)=(1-probability_of_detection)*&
                    min(real(probability_of_voucher_benchmark_used_1*&
                    increased_prob_of_voucher_if_homeless_and_addicted),1.0)
                voucher_probabilities(0,0,1,3)=1-voucher_probabilities(0,1,1,3)
                voucher_probabilities(1,1,1,3)=1-probability_of_detection
                voucher_probabilities(1,0,1,3)=probability_of_detection
                
                ! categories 1 and 2 meet the condition and face the false
                ! positive rate instead
                voucher_probabilities(0,1,1,1:2)=(1-probability_of_false_positive)*&
                    voucher_probabilities(0,1,1,1:2)
                voucher_probabilities(0,0,1,1:2)=1-voucher_probabilities(0,1,1,1:2)
                voucher_probabilities(1,1,1,1:2)=1-probability_of_false_positive
                voucher_probabilities(1,0,1,1:2)=probability_of_false_positive
                
            end if
            
        end if
        
        if (is_counterfactual==1) then
        
            open(unit=23,file="voucher_probabilities_benchmark"//trim(benchmark_simulation)//".dat",action='read')
                read(23,'((F35.13))') voucher_probabilities_benchmark
            close(23)
            
        else
        
            voucher_probabilities_benchmark=voucher_probabilities
            
            ! from getting a voucher to not if addicted when income is below threshold
            voucher_probabilities_benchmark(1,0,1,3)=0
            
            ! from getting a voucher to getting it if addicted when income is below threshold
            voucher_probabilities_benchmark(1,1,1,3)=1
                    
            voucher_probabilities_benchmark(0,1,1,:)=probability_of_voucher_benchmark
            voucher_probabilities_benchmark(0,0,1,:)=(1-voucher_probabilities_benchmark(0,1,1,:))
            
        end if
            
        ! Every quantity built from a calibrated parameter, rebuilt before the
        ! hazards that read them.
        call recompute_derived_parameters()

        ! the base is calibrated now, so the derived heavy user rate has to be
        ! recomputed here rather than only at declaration
        increased_probability_of_becoming_addicted_if_heavy_user=&
            6.4761*probability_of_becoming_addicted_if_experiment

        addiction_probabilities=0
        addiction_probabilities(0,0,:,:)=1
        
        if (include_probability_of_becoming_addicted==1) then
        
            if (include_addiction==1) then
        
                addiction_probabilities(0,include_addiction,1,:)=probability_of_becoming_addicted_if_experiment
                addiction_probabilities(0,0,1,:)=1-probability_of_becoming_addicted_if_experiment
                
                ! The heavy use row only EXISTS while the split does: the third
                ! dimension is 0:include_addiction+include_heavy_vs_light_use_transitions,
                ! so with the regimes collapsed index 2 is off the end of the
                ! array. Writing to it was an out of bounds store that the
                ! compiler caught and that nothing at run time would have.
                if (include_heavy_vs_light_use_transitions==1) then

                    addiction_probabilities(0,include_addiction,&
                        include_heavy_vs_light_use_transitions+1,:)=&
                        increased_probability_of_becoming_addicted_if_heavy_user
                    addiction_probabilities(0,0,include_heavy_vs_light_use_transitions+1,:)=&
                        1-increased_probability_of_becoming_addicted_if_heavy_user

                end if
                
            else
            
                addiction_probabilities(0,0,:,:)=1
            
            end if
        
        else
        
            addiction_probabilities(0,include_addiction,:,:)=1
            
        end if
            
        if (include_addiction==1) then
            
            addiction_probabilities(include_addiction,0,:,1)=probability_of_stopping_addiction
            addiction_probabilities(include_addiction,include_addiction,:,1)=1-probability_of_stopping_addiction        
            
            addiction_probabilities(include_addiction,0,:,2)=probability_of_stopping_addiction_if_homeless
            addiction_probabilities(include_addiction,include_addiction,:,2)=1-probability_of_stopping_addiction_if_homeless    
            
        end if
        
        addiction_probabilities_percieved=addiction_probabilities
        
        if (include_addiction==1) then
        
            addiction_probabilities_percieved(0,include_addiction,1,:)=&
                addiction_probabilities_percieved(0,include_addiction,1,:)*&
                difference_in_perceived_of_becoming_addicted_if_experiment
                
            addiction_probabilities_percieved(0,0,1,:)=1-addiction_probabilities_percieved(0,include_addiction,1,:)
            
        end if        

        call adjusting_unemployment_probabilities_based_on_productivity(adjusted_probability)
                        
        unemployment_process=0
        
        ! THE STREET'S LABOUR-MARKET MULTIPLIERS, SET BEFORE EITHER BRANCH.
        !
        ! THEY WERE SET INSIDE if (include_addiction==0) AND USED IN BOTH. This
        ! model has include_addiction=1 as a compile-time parameter, so the setter
        ! was DEAD CODE and the live branch read two UNINITIALISED locals. Every
        ! value of homeless_job_penalty_pp then gave bit-identical output -- delta
        ! 0.05, 0.30 and 0.55 agreed to seven decimals on h_1, y_h and
        ! emp_homeless -- and that was read as the parameter having no economic
        ! effect when it was never applied at all. The same fault silently replaced
        ! the (1+increased_prob_if_homeless) factor on the addiction path.
        !
        ! Anything set here must be set for BOTH branches. Do not move it back
        ! inside one.
        if (homeless_job_penalty_pp>0.d0) then
        
            ! DELTA ACTS ON THE SEPARATION RATE ALONE, on the author's
            ! instruction of 5 September: *"wait, delta does not affect the job
            ! finding rate...."*, *"it should not"*, *"delta only affects the
            ! separate rate...we already know that if it affects the job fining
            ! rate it discourages the unemployed to be homeless"*.
            !
            ! IT WAS SYMMETRIC UNTIL NOW and that is what the ruling in
            ! directions_table.py already said it should not be -- *"Delta now
            ! acts on separation alone"*, recorded 5 September -- while the code
            ! kept cutting both sides. The comment and the source disagreed for a
            ! day and the source was what ran.
            !
            ! WHY THE FINDING SIDE IS THE WRONG LEVER. It falls on households
            ! ALREADY out of work, which is exactly the group that should be
            ! choosing the street. Measured earlier: removing the finding penalty
            ! entirely (increased_prob_if_homeless 0.2 -> 0) raises homelessness
            ! among the unemployed FIVE-FOLD. Cutting job finding prices the poor
            ! off the street, which is the opposite of what delta is for.
            !
            ! Separation stays additive in POINTS: the homeless separation
            ! probability is probability_becoming_unemployed + delta.
            loss_mult_homeless_1=(probability_becoming_unemployed+&
                homeless_job_penalty_pp)/&
                max(probability_becoming_unemployed,10.d0**(-12))
                
            find_mult_homeless_1=1.d0
                
        else
        
            loss_mult_homeless_1=1.d0+increased_prob_if_homeless+&
                extra_job_loss_if_homeless
                
            find_mult_homeless_1=1.d0-increased_prob_if_homeless
            
        end if
        
        ! THE SEPARATION PROBABILITY CANNOT EXCEED ONE, clamped on the FACTOR
        ! rather than per branch: the branches split it by whether unemployment
        ! insurance is received and must scale together or stop summing to it.
        loss_mult_homeless_1=min(loss_mult_homeless_1,&
            1.d0/max(probability_becoming_unemployed,10.d0**(-12)))
        
        if (include_addiction==0) then
        
            cutoff_age_1=life_span-retirement_span-1
        
            unemployment_process(1:cutoff_age_1,1,2,1,0,:)=probability_becoming_unemployed*(1-probability_of_ui)
            unemployment_process(1:cutoff_age_1,1,2,2,0,:)=probability_becoming_unemployed*(1-probability_of_ui)*&
                loss_mult_homeless_1
            
            unemployment_process(1:cutoff_age_1,1,3,1,0,:)=probability_becoming_unemployed*probability_of_ui
            unemployment_process(1:cutoff_age_1,1,3,2,0,:)=probability_becoming_unemployed*probability_of_ui*&
                loss_mult_homeless_1
                
            do employment_index=1,employment_grid_size
            
                unemployment_process(1:cutoff_age_1,1,1,1,0,employment_index)=&
                    1-sum(unemployment_process(1,1,2:3,1,0,employment_index))
                    
                unemployment_process(1:cutoff_age_1,1,1,2,0,employment_index)=&
                    1-sum(unemployment_process(1,1,2:3,2,0,employment_index))
                    
            end do
        
            unemployment_process(1:cutoff_age_1,2,1,1,0,:)=probability_becoming_employed
            unemployment_process(1:cutoff_age_1,2,1,2,0,:)=probability_becoming_employed*find_mult_homeless_1
            unemployment_process(1:cutoff_age_1,2,2,1,0,:)=1-probability_becoming_employed
            ! WAS probability_becoming_employed1, WITH A TRAILING 1, AND THAT
            ! NAME IS DECLARED NOWHERE IN THE FILE. This subroutine has no
            ! implicit none -- the module it uses has one, but that does not
            ! reach a scope that merely uses it -- so the misspelling was typed
            ! implicitly as an uninitialised real and the line read
            ! 1 - undefined/1.2 rather than 1 - 0.55/1.2. The row for an
            ! unemployed homeless household then did not sum to one: its find-a-
            ! job entry two lines above is 0.4583, so the pair summed to about
            ! 1.4583 and the process was creating mass inside unemployment.
            ! The identical block six lines below, for state 3, spells it
            ! correctly, which is what settles that this is a typo and not a
            ! deliberate asymmetry.
            unemployment_process(1:cutoff_age_1,2,2,2,0,:)=1-probability_becoming_employed*find_mult_homeless_1
            
            unemployment_process(1:cutoff_age_1,3,1,1,0,:)=probability_becoming_employed
            unemployment_process(1:cutoff_age_1,3,1,2,0,:)=probability_becoming_employed*find_mult_homeless_1
            unemployment_process(1:cutoff_age_1,3,3,1,0,:)=1-probability_becoming_employed
            unemployment_process(1:cutoff_age_1,3,3,2,0,:)=1-probability_becoming_employed*find_mult_homeless_1
                        
            cutoff_age_2=life_span-1
                        
            do age_index=cutoff_age_1+1,cutoff_age_2
            
                do unemployment_index=1,unemployment_grid_size
            
                    unemployment_process(age_index,unemployment_index,unemployment_index,:,0,:)=1
                                        
                end do
                
            end do
                                        
            cutoff_age_2=life_span
            
            unemployment_process(cutoff_age_2,1,2,1,0,:)=probability_becoming_unemployed*(1-probability_of_ui)
            unemployment_process(cutoff_age_2,1,2,2,0,:)=probability_becoming_unemployed*(1-probability_of_ui)*&
                loss_mult_homeless_1
            
            unemployment_process(cutoff_age_2,1,3,1,0,:)=probability_becoming_unemployed*probability_of_ui
            unemployment_process(cutoff_age_2,1,3,2,0,:)=probability_becoming_unemployed*probability_of_ui*&
                loss_mult_homeless_1
                
            do employment_index=1,employment_grid_size
            
                unemployment_process(cutoff_age_2,1,1,1,0,employment_index)=&
                    1-sum(unemployment_process(1,1,2:3,1,0,employment_index))
                    
                unemployment_process(cutoff_age_2,1,1,2,0,employment_index)=&
                    1-sum(unemployment_process(1,1,2:3,2,0,employment_index))
                
            end do
            
            unemployment_process(cutoff_age_2,2,1,1,0,:)=probability_becoming_employed
            unemployment_process(cutoff_age_2,2,1,2,0,:)=probability_becoming_employed*find_mult_homeless_1
            unemployment_process(cutoff_age_2,2,2,1,0,:)=1-probability_becoming_employed
            unemployment_process(cutoff_age_2,2,2,2,0,:)=1-probability_becoming_employed*find_mult_homeless_1
            
            unemployment_process(cutoff_age_2,3,1,1,0,:)=probability_becoming_employed
            unemployment_process(cutoff_age_2,3,1,2,0,:)=probability_becoming_employed*find_mult_homeless_1
            unemployment_process(cutoff_age_2,3,3,1,0,:)=1-probability_becoming_employed
            unemployment_process(cutoff_age_2,3,3,2,0,:)=1-probability_becoming_employed*find_mult_homeless_1
                        
        else
            
            do employment_index=1,employment_grid_size
                    
                unemployment_process(:,1,2,1,0,employment_index)=&
                    probability_becoming_unemployed*(1-probability_of_ui)*adjusted_probability(employment_index)
                    
                unemployment_process(:,1,2,2,0,employment_index)=probability_becoming_unemployed*(1-probability_of_ui)*&
                    loss_mult_homeless_1*adjusted_probability(employment_index)
            
                unemployment_process(:,1,3,1,0,employment_index)=probability_becoming_unemployed*probability_of_ui*&
                    adjusted_probability(employment_index)
                    
                unemployment_process(:,1,3,2,0,employment_index)=probability_becoming_unemployed*probability_of_ui*&
                    loss_mult_homeless_1*adjusted_probability(employment_index)
                    
                unemployment_process(:,1,1,1,0,employment_index)=1-sum(unemployment_process(1,1,2:3,1,0,employment_index))
                unemployment_process(:,1,1,2,0,employment_index)=1-sum(unemployment_process(1,1,2:3,2,0,employment_index))
                
            end do
                                        
            unemployment_process(:,3,1,1,0,:)=probability_becoming_employed
            unemployment_process(:,3,1,2,0,:)=probability_becoming_employed*find_mult_homeless_1
            
            ! 3 -> 2, not 3 -> 3: the insured period is the first one only, so
            ! a spell that continues moves to the state that pays nothing. Kept
            ! in step with employment_transition, which is the live builder at
            ! two SMI states and which verify_unemployment_process checks this
            ! block against at one.
            unemployment_process(:,3,2,1,0,:)=(1-probability_becoming_employed)
            unemployment_process(:,3,2,2,0,:)=1-probability_becoming_employed*find_mult_homeless_1
            
            unemployment_process(:,2,1,1,0,:)=probability_becoming_employed
            unemployment_process(:,2,1,2,0,:)=probability_becoming_employed*find_mult_homeless_1
            
            unemployment_process(:,2,2,1,0,:)=(1-probability_becoming_employed)
            unemployment_process(:,2,2,2,0,:)=1-probability_becoming_employed*find_mult_homeless_1
                
            unemployment_process(:,4,5,1,1,:)=probability_becoming_unemployed_if_addicted*(1-probability_of_ui)
            unemployment_process(:,4,5,2,1,:)=probability_becoming_unemployed_if_addicted*(1-probability_of_ui)*&
                loss_mult_homeless_1
                
            unemployment_process(:,4,6,1,1,:)=probability_becoming_unemployed_if_addicted*probability_of_ui
            unemployment_process(:,4,6,2,1,:)=probability_becoming_unemployed_if_addicted*probability_of_ui*&
                loss_mult_homeless_1
                
            do employment_index=1,employment_grid_size

                unemployment_process(:,4,4,1,1,employment_index)=1-sum(unemployment_process(1,4,5:6,1,1,employment_index))
                unemployment_process(:,4,4,2,1,employment_index)=1-sum(unemployment_process(1,4,5:6,2,1,employment_index))
                
            end do
                        
            unemployment_process(:,6,4,1,1,:)=probability_becoming_employed_if_addicted
            unemployment_process(:,6,4,2,1,:)=probability_becoming_employed_if_addicted*find_mult_homeless_1
            
            unemployment_process(:,6,5,1,1,:)=(1-probability_becoming_employed_if_addicted)
            unemployment_process(:,6,5,2,1,:)=1-probability_becoming_employed_if_addicted*find_mult_homeless_1
            
            unemployment_process(:,5,4,1,1,:)=probability_becoming_employed_if_addicted
            unemployment_process(:,5,4,2,1,:)=probability_becoming_employed_if_addicted*find_mult_homeless_1
            
            unemployment_process(:,5,5,1,1,:)=(1-probability_becoming_employed_if_addicted)
            unemployment_process(:,5,5,2,1,:)=1-probability_becoming_employed_if_addicted*find_mult_homeless_1
            
            !!! transition between states of addiction
            !!! this one moves from no addiction to addiction
            do employment_index=1,employment_grid_size
                            
                unemployment_process(:,1,5,1,1,employment_index)=&
                    probability_becoming_unemployed_if_addicted*(1-probability_of_ui)*adjusted_probability(employment_index)
                    
                unemployment_process(:,1,5,2,1,employment_index)=&
                    probability_becoming_unemployed_if_addicted*(1-probability_of_ui)*loss_mult_homeless_1*&
                    adjusted_probability(employment_index)
                    
                unemployment_process(:,1,6,1,1,employment_index)=&
                    probability_becoming_unemployed_if_addicted*probability_of_ui*adjusted_probability(employment_index)
                
                unemployment_process(:,1,6,2,1,employment_index)=&
                    probability_becoming_unemployed_if_addicted*probability_of_ui*&
                    loss_mult_homeless_1*adjusted_probability(employment_index)
                                        
                unemployment_process(:,1,4,1,1,employment_index)=1-sum(unemployment_process(1,1,5:6,1,1,employment_index))
                unemployment_process(:,1,4,2,1,employment_index)=1-sum(unemployment_process(1,1,5:6,2,1,employment_index))
                    
            end do
                
            unemployment_process(:,2,4,1,1,:)=probability_becoming_employed_if_addicted
            unemployment_process(:,2,4,2,1,:)=probability_becoming_employed_if_addicted*find_mult_homeless_1
                
            unemployment_process(:,2,5,1,1,:)=(1-probability_becoming_employed_if_addicted)
            unemployment_process(:,2,5,2,1,:)=(1-probability_becoming_employed_if_addicted*find_mult_homeless_1)
            
            unemployment_process(:,3,5,1,1,:)=(1-probability_becoming_employed_if_addicted)
            unemployment_process(:,3,5,2,1,:)=(1-probability_becoming_employed_if_addicted*find_mult_homeless_1)
            
            unemployment_process(:,3,4,1,1,:)=probability_becoming_employed_if_addicted
            unemployment_process(:,3,4,2,1,:)=probability_becoming_employed_if_addicted*find_mult_homeless_1
            
            do employment_index=1,employment_grid_size
            
                !! this one moves from addiction to no addiction
                unemployment_process(:,4,2,1,0,employment_index)=&
                    probability_becoming_unemployed*(1-probability_of_ui)*adjusted_probability(employment_index)
                    
                unemployment_process(:,4,2,2,0,employment_index)=probability_becoming_unemployed*(1-probability_of_ui)*&
                    loss_mult_homeless_1*adjusted_probability(employment_index)
                
                unemployment_process(:,4,3,1,0,employment_index)=&
                    probability_becoming_unemployed*probability_of_ui*adjusted_probability(employment_index)
                
                unemployment_process(:,4,3,2,0,employment_index)=&
                    probability_becoming_unemployed*probability_of_ui*loss_mult_homeless_1*&
                    adjusted_probability(employment_index)
            
                unemployment_process(:,4,1,1,0,employment_index)=1-sum(unemployment_process(1,4,2:3,1,0,employment_index))
                unemployment_process(:,4,1,2,0,employment_index)=1-sum(unemployment_process(1,4,2:3,2,0,employment_index))
                                
            end do
            
            unemployment_process(:,6,1,1,0,:)=probability_becoming_employed
            unemployment_process(:,6,1,2,0,:)=probability_becoming_employed*find_mult_homeless_1
            
            unemployment_process(:,6,2,1,0,:)=(1-probability_becoming_employed)
            unemployment_process(:,6,2,2,0,:)=1-probability_becoming_employed*find_mult_homeless_1
            
            unemployment_process(:,5,1,1,0,:)=probability_becoming_employed
            unemployment_process(:,5,1,2,0,:)=probability_becoming_employed*find_mult_homeless_1
            
            unemployment_process(:,5,2,1,0,:)=(1-probability_becoming_employed)
            unemployment_process(:,5,2,2,0,:)=(1-probability_becoming_employed*find_mult_homeless_1)

        end if

        ! AT ONE SMI STATE the hand written block above is the live array and the
        ! generic builder is only checked against it. At two the hand written
        ! block cannot express the layout at all, so the generic builder becomes
        ! the live one. Flipping number_of_smi_states is therefore the whole
        ! switch, and the run says out loud which path it took.
        if (number_of_smi_states==1) then

            if (loop_count<1) then

                ! Restores the hand written array before returning, so at one
                ! state the model stays bit identical to before the port.
                call verify_unemployment_process(increased_prob_if_homeless)

            end if

        else

            write(*,*) "unemployment_process: generic builder, number_of_smi_states=", number_of_smi_states

            call build_unemployment_process_smi(increased_prob_if_homeless)

            ! The onset entry itself: index 1 is (employed, no SMI, no SUD) and
            ! index 4 is (employed, SMI, no SUD), so this is the probability of
            ! acquiring SMI while staying employed and clean. If it is zero the
            ! chain cannot populate and no calibration of lambda_m means anything.
            write(*,*) "unemployment_process onset 1->4 =", &
                unemployment_process(1,1,4,1,0,1), " stay 1->1 =", unemployment_process(1,1,1,1,0,1)

        end if

        if (loop_count<1) then
                
!            do unemployment_index=1,unemployment_grid_size
!            
!                do future_unemployment_index=1,unemployment_grid_size
!                
!                    do i=1,2
!                    
!                        do j=0,include_addiction
!                
!                            write(*,*) "unemployment_process", unemployment_index, " to ", future_unemployment_index,"=",&
!                                unemployment_process(1,unemployment_index,future_unemployment_index,i,j)
!                                
!                        end do
!                            
!                    end do
!                
!                end do
!                
!            end do
            
            do unemployment_index=1,threshold_addiction_index
                                        
                do i=1,2
                
                    do j=0,0
                    
                        do employment_index=1,employment_grid_size
                            
!                            write(*,*) "sum(unemployment_process)1", unemployment_index,"=",&
!                                sum(unemployment_process(1,unemployment_index,1:threshold_addiction_index,i,j,employment_index))
                                
                        end do
                        
                    end do
                        
                end do
                        
            end do
            
            do unemployment_index=threshold_addiction_index+1,unemployment_grid_size
                            
                do i=1,2
                
                    do j=0,0
                    
                        do employment_index=1,employment_grid_size
            
!                            write(*,*) "sum(unemployment_process)2", unemployment_index,"=",&
!                                sum(unemployment_process(1,unemployment_index,1:threshold_addiction_index,i,j,employment_index))
                                
                        end do
                            
                    end do
                        
                end do
                        
            end do

            do unemployment_index=threshold_addiction_index+1,unemployment_grid_size
                            
                do i=1,2
                
                    do j=1,include_addiction
                    
                        do employment_index=1,employment_grid_size
            
!                            write(*,*) "sum(unemployment_process)3", unemployment_index,"=",&
!                                sum(unemployment_process&
!                                    (1,unemployment_index,threshold_addiction_index+1:unemployment_grid_size,&
!                                    i,j,employment_index))
                                    
                        end do
                        
                    end do
                        
                end do
                        
            end do
            
            do unemployment_index=1,threshold_addiction_index
                            
                do i=1,2
                
                    do j=include_addiction,include_addiction
                    
                        do employment_index=1,employment_grid_size
            
!                            write(*,*) "sum(unemployment_process)4", unemployment_index,",",employment_index,"=",&
!                                sum(unemployment_process&
!                                    (1,unemployment_index,threshold_addiction_index+1:unemployment_grid_size,&
!                                    i,j,employment_index))
                                    
                        end do
                        
                    end do
                        
                end do
                        
            end do
!            
!            do unemployment_index=1,unemployment_grid_size
!                            
!                do i=1,2
!                
!                    do j=0,include_addiction
!            
!                        write(*,*) "sum(unemployment_process)", unemployment_index,"=",&
!                            sum(unemployment_process(life_span,unemployment_index,:,i,j))
!                            
!                    end do
!                        
!                end do
!                        
!            end do
        
        end if
        
    end subroutine
    

    subroutine build_unemployment_process_smi(iph_1)

        ! THE JOINT (employment, SMI, SUD) TRANSITION, BUILT RATHER THAN
        ! ENUMERATED.
        !
        ! The block above writes this array out by hand, one index pair at a
        ! time. That is readable at six states and unmaintainable at twelve, and
        ! twelve is what a second SMI state costs. The transition factorises,
        !
        !     P(e,m,d -> e',m',d') = P_emp(e -> e' | d', m', h, p) * P_smi(m -> m' | d, j)
        !
        ! so it can be built from the two legs directly. The SMI leg takes the
        ! CURRENT disorder state, because the note's iota raises the onset of SMI
        ! for a household that already carries the SUD; the employment leg takes
        ! the future one, for the reason given in employment_transition.
        !
        ! This is verified against the hand written array rather than trusted:
        ! see verify_unemployment_process.

        use Global_Vars

        implicit none

        real(8), intent(in) :: iph_1
        integer :: a_1,p_1,h_1,d_c_1,d_f_1,m_c_1,m_f_1,e_c_1,e_f_1,i_1,j_1
        real(8) :: smi_1,newborn_smi_1

        unemployment_process=0
        newborn_unemployment_process=0

        ! The newborn's own SMI draw, from prevalence at age one. Independent of
        ! the parent, which is the whole point.
        newborn_smi_1=0
        if (number_of_smi_states>1) newborn_smi_1=smi_prevalence_by_age(1)

        do a_1=1,life_span

            do p_1=1,employment_grid_size

                do h_1=1,2

                    do d_c_1=0,include_addiction

                        do d_f_1=0,include_addiction

                            do m_c_1=0,number_of_smi_states-1

                                do m_f_1=0,number_of_smi_states-1

                                    smi_1=smi_transition(m_c_1,m_f_1,d_c_1,a_1)

                                    ! The zero skip that used to sit here has
                                    ! gone. It saved nothing measurable and it
                                    ! would leave newborn_unemployment_process
                                    ! unfilled at exactly the (m,m') pairs the
                                    ! newborn draw does not care about, since
                                    ! that leg does not depend on m at all.

                                    do e_c_1=1,3

                                        i_1=idx_of(e_c_1,m_c_1,d_c_1)

                                        do e_f_1=1,3

                                            j_1=idx_of(e_f_1,m_f_1,d_f_1)

                                            unemployment_process(a_1,i_1,j_1,h_1,d_f_1,p_1)=&
                                                employment_transition(e_c_1,e_f_1,d_f_1,m_f_1,h_1,p_1,iph_1)*smi_1

                                            ! Same employment leg, SMI drawn from
                                            ! p(1) rather than from the parent.
                                            newborn_unemployment_process(a_1,i_1,j_1,h_1,d_f_1,p_1)=&
                                                employment_transition(e_c_1,e_f_1,d_f_1,m_f_1,h_1,p_1,iph_1)*&
                                                (m_f_1*newborn_smi_1+(1-m_f_1)*(1-newborn_smi_1))

                                        end do

                                    end do

                                end do

                            end do

                        end do

                    end do

                end do

            end do

        end do

    end subroutine

    subroutine verify_newborn_process()

        ! THE NEWBORN DRAW HAS TO DELIVER p(1), and it is checked rather than
        ! argued, because the bug it replaces was invisible: the model ran and
        ! reported an SMI prevalence of about two per cent against a profile
        ! averaging five, and nothing said the newborns were the reason.
        !
        ! Two conditions. The newborn process must be a distribution, summing to
        ! one over the future index for every state it is read at. And the mass it
        ! puts on the SMI states must be p(1), independently of the parent's own
        ! SMI state, which is the property the old array did not have.

        use Global_Vars

        implicit none

        integer :: a_1,i_1,j_1,h_1,d_f_1,p_1,bad_sum_1,bad_prev_1
        real(8) :: sum_1,smi_mass_1,target_1

        if (number_of_smi_states<=1) then

            write(*,*) "newborn process: not checked, number_of_smi_states=", number_of_smi_states
            return

        end if

        target_1=smi_prevalence_by_age(1)
        bad_sum_1=0
        bad_prev_1=0

        do a_1=1,life_span

            do p_1=1,employment_grid_size

                do h_1=1,2

                    do d_f_1=0,include_addiction

                        do i_1=1,unemployment_grid_size

                            sum_1=0
                            smi_mass_1=0

                            do j_1=1,unemployment_grid_size

                                if (sud_of(j_1)/=d_f_1) cycle

                                sum_1=sum_1+newborn_unemployment_process(a_1,i_1,j_1,h_1,d_f_1,p_1)

                                if (smi_of(j_1)==1) then

                                    smi_mass_1=smi_mass_1+&
                                        newborn_unemployment_process(a_1,i_1,j_1,h_1,d_f_1,p_1)

                                end if

                            end do

                            if (abs(sum_1-1.d0)>10.d0**(-8)) bad_sum_1=bad_sum_1+1

                            if (abs(smi_mass_1-target_1)>10.d0**(-8)) bad_prev_1=bad_prev_1+1

                        end do

                    end do

                end do

            end do

        end do

        write(*,*) "newborn process: p(1)=", target_1, &
            " rows not summing to one=", bad_sum_1, " rows off p(1)=", bad_prev_1

        if ((bad_sum_1>0) .OR. (bad_prev_1>0)) then

            write(*,*) "NEWBORN PROCESS IS WRONG. stopping."
            stop

        end if

    end subroutine

    subroutine verify_unemployment_process(iph_1)

        ! Build the generic array into scratch and compare it, element by
        ! element, with whatever is currently in unemployment_process. At one SMI
        ! state the two are meant to describe the same object, so any difference
        ! is a real disagreement and is printed with its indices rather than
        ! summarised away.
        !
        ! This is the same discipline as verify_index_map: the rewrite is
        ! checked at run time instead of being asserted in a comment.

        use Global_Vars

        implicit none

        real(8), intent(in) :: iph_1
        real(8), allocatable, dimension(:,:,:,:,:,:) :: hand_1
        integer :: a_1,i_1,j_1,h_1,d_1,p_1,bad_1
        real(8) :: worst_1,diff_1,rowsum_1
        integer :: worst_i_1,worst_j_1,worst_d_1,worst_h_1

        allocate(hand_1(life_span,unemployment_grid_size,unemployment_grid_size,2,&
            0:include_addiction,employment_grid_size))

        hand_1=unemployment_process

        call build_unemployment_process_smi(iph_1)

        worst_1=0
        bad_1=0
        worst_i_1=0
        worst_j_1=0
        worst_d_1=0
        worst_h_1=0

        do p_1=1,employment_grid_size
            do d_1=0,include_addiction
                do h_1=1,2
                    do i_1=1,unemployment_grid_size
                        do j_1=1,unemployment_grid_size

                            diff_1=abs(hand_1(1,i_1,j_1,h_1,d_1,p_1)-&
                                unemployment_process(1,i_1,j_1,h_1,d_1,p_1))

                            if (diff_1>10.d0**(-10)) bad_1=bad_1+1

                            if (diff_1>worst_1) then

                                worst_1=diff_1
                                worst_i_1=i_1
                                worst_j_1=j_1
                                worst_d_1=d_1
                                worst_h_1=h_1

                            end if

                        end do
                    end do
                end do
            end do
        end do

        write(*,*) "verify_unemployment_process: differing entries=", bad_1, " worst=", worst_1
        write(*,*) "  worst at from=", worst_i_1, " to=", worst_j_1, &
            " homeless=", worst_h_1, " future_sud=", worst_d_1
        write(*,*) "  hand=", hand_1(1,max(worst_i_1,1),max(worst_j_1,1),max(worst_h_1,1),worst_d_1,1), &
            " generic=", unemployment_process(1,max(worst_i_1,1),max(worst_j_1,1),max(worst_h_1,1),worst_d_1,1)

        ! Whatever else is true, every row of a transition matrix has to sum to
        ! one over the future states it can reach. The sum is taken across BOTH
        ! future disorder blocks, since the disorder leg is applied separately by
        ! addiction_transition and this array is conditional on it.
        do p_1=1,1
            do h_1=1,2
                do i_1=1,unemployment_grid_size

                    rowsum_1=0

                    do d_1=0,include_addiction
                        do j_1=1,unemployment_grid_size

                            rowsum_1=rowsum_1+unemployment_process(1,i_1,j_1,h_1,d_1,p_1)

                        end do
                    end do

                    ! One per disorder block, so include_addiction+1 in total.
                    if (abs(rowsum_1-real(include_addiction+1,8))>10.d0**(-8)) then

                        write(*,*) "verify_unemployment_process: ROW SUM WRONG from=", i_1, &
                            " homeless=", h_1, " sum=", rowsum_1

                    end if

                end do
            end do
        end do

        ! PUT THE HAND WRITTEN ARRAY BACK. This routine is a check, not a
        ! build: at one SMI state the hand written block stays live, so the
        ! comparison must not have side effects on the model.
        unemployment_process=hand_1

        deallocate(hand_1)

    end subroutine

    subroutine adjusting_unemployment_probabilities_based_on_productivity(adjusted_probability_1)
    
        use Global_Vars
        
        implicit none
        
        real(8), dimension(employment_grid_size), intent(out) :: adjusted_probability_1
        real(8) :: mean_tilt_1
        real(8), dimension(4) :: edu_share_1,edu_rate_1,edu_odds_1,edu_hi_1
        real(8) :: cum_lo_1,cum_hi_1,acc_1,w_1,elo_1,ovl_1
        integer :: i_edu_1,j_edu_1
        
        do i=1,employment_grid_size
        
            adjusted_probability_1(i)=(real(2*employment_grid_size)-real(2*i))/(real(2*employment_grid_size)-real(2*5))
            
        end do
        
        ! THE LINE ABOVE IS DEAD. The profile is computed and then thrown away,
        ! so the separation rate does not vary with permanent productivity at
        ! all. Left as it stands because switching it on is a modelling change
        ! and not a repair, but it should be a decision rather than an accident.
        !
        ! One consequence to know about: because this is uniformly one, the
        ! comparison in verify_unemployment_process cannot discriminate on it,
        ! so that check confirms the structure of the transition and not the
        ! placement of this factor.
        ! THE PROFILE IS LIVE WHEN use_unemployment_by_productivity=1, and the
        ! numbers are from BLS rather than the formula above.
        !
        ! The author, 3 September: *"you can still make the unemployment
        ! probability higher for lower productivity guys. But you have to explain
        ! to me what data you use, and exactly how you map it to the y grid"*.
        ! The whole derivation is in data/UNEMPLOYMENT_BY_PRODUCTIVITY.md. In
        ! short: BLS 2019 annual averages, age 25 and over, unemployment rate by
        ! educational attainment; education orders productivity by median
        ! earnings so each group takes a contiguous block of the distribution as
        ! wide as its population share; each node takes the share-weighted average
        ! over its own quantile interval; and because this multiplies a SEPARATION
        ! rate while BLS reports a STOCK, the average is taken over the ODDS
        ! u/(1-u) rather than over u.
        !
        ! Normalised to a mass-weighted mean of one, which leaves the AGGREGATE
        ! separation rate and therefore pi_eu's calibration undisturbed. Bottom to
        ! top the spread is 2.57.
        !
        ! The formula above is DEAD and stays dead. At seven nodes it runs 3.00
        ! down to exactly 0.00, giving the top type zero separation risk, which is
        ! not a fact about the world.
        ! COMPUTED FROM THE EDUCATION TABLE, NOT WRITTEN OUT AS A LITERAL, from
        ! 7 September. It used to be seven numbers guarded by
        ! employment_grid_size==7, which is a trap: change the grid and the guard
        ! goes false, the profile silently becomes uniform, every productivity
        ! type gets the same separation rate, and since job loss is what puts a
        ! household on the street, homelessness moves for a reason nothing
        ! reports. The model compiles, runs, and passes all sixteen invariants.
        !
        ! The same file already carries the scar: relative_endowments is a NINE
        ! node SCF profile with min(9,employment_grid_size) guards bolted on after
        ! the grid was cut to seven, so three distinct levels collapsed onto one.
        !
        ! So the method in data/UNEMPLOYMENT_BY_PRODUCTIVITY.md is implemented
        ! here instead of its output being pasted in. BLS 2019 annual averages,
        ! age 25 and over, unemployment by educational attainment; education
        ! orders productivity by median earnings so each group takes a contiguous
        ! block of the distribution as wide as its population share; each node
        ! takes the share-weighted average over its own quantile interval; and the
        ! average is over the ODDS u/(1-u) because this multiplies a SEPARATION
        ! rate while BLS reports a STOCK.
        !
        ! It reproduces the old literal exactly at seven nodes -- node 4's blend
        ! of "less than high school" and "high school" comes out at 0.0439 against
        ! the 0.0439 in that file -- and now follows the grid wherever it goes.
        if (use_unemployment_by_productivity==1) then

            edu_share_1=(/0.096d0,0.274d0,0.264d0,0.366d0/)
            edu_rate_1=(/0.054d0,0.037d0,0.033d0,0.021d0/)
            edu_odds_1=edu_rate_1/(1.d0-edu_rate_1)

            edu_hi_1(1)=edu_share_1(1)
            do j_edu_1=2,4
                edu_hi_1(j_edu_1)=edu_hi_1(j_edu_1-1)+edu_share_1(j_edu_1)
            end do

            cum_lo_1=0.d0
            do i_edu_1=1,employment_grid_size
                cum_hi_1=cum_lo_1+unconditional_employment_probability(i_edu_1)
                acc_1=0.d0
                w_1=0.d0
                elo_1=0.d0
                do j_edu_1=1,4
                    ovl_1=max(0.d0,min(cum_hi_1,edu_hi_1(j_edu_1))-max(cum_lo_1,elo_1))
                    acc_1=acc_1+ovl_1*edu_odds_1(j_edu_1)
                    w_1=w_1+ovl_1
                    elo_1=edu_hi_1(j_edu_1)
                end do
                if (w_1>10.d0**(-14)) then
                    adjusted_probability_1(i_edu_1)=acc_1/w_1
                else
                    adjusted_probability_1(i_edu_1)=1.d0
                end if
                cum_lo_1=cum_hi_1
            end do

            ! RENORMALISED ON THE LIVE MASSES, not on the ones this vector was
            ! built with. The numbers above average to one under the QUANTILE
            ! grid's masses, where the bottom three nodes together carry 6.6 per
            ! cent. The KKK grid puts different mass on the same seven nodes --
            ! the bottom node alone moves from 0.198 per cent to 0.62 -- so the
            ! same vector would no longer average to one there, the AGGREGATE
            ! separation rate would move, and probability_becoming_unemployed
            ! would be silently recalibrated by a change that was meant to be
            ! purely distributional. Dividing by the live mass-weighted mean
            ! costs nothing on the grid it was built for, where the mean is
            ! already one, and keeps pi_eu's calibration intact on the other.
            ! ONLY WHERE IT DOES REAL WORK, so the quantile path is bit
            ! identical to what the archive was measured on. The vector above was
            ! CONSTRUCTED to have mass-weighted mean one on the quantile masses;
            ! it comes out at 1.000017 there, and that residue is a rounding
            ! artefact of quoting it to four decimals, not a correction. Dividing
            ! by it would move every measured point by 1.7 parts in a hundred
            ! thousand and, far more expensively, would put 611 archived points
            ! on a different model hash for no gain. On the KKK grid the masses
            ! are genuinely different -- the bottom three nodes carry 24 per cent
            ! rather than 6.6 -- and the renormalisation is doing real work.
            mean_tilt_1=sum(unconditional_employment_probability(1:employment_grid_size)*&
                adjusted_probability_1(1:employment_grid_size))

            if ((mean_tilt_1>10.d0**(-10)) .AND. (fixed_productivity==0)) then

                adjusted_probability_1=adjusted_probability_1/mean_tilt_1

            end if

        else

            adjusted_probability_1=1

        end if
                
    end subroutine
    
    ! THE SHARE OF LABOUR PRODUCTIVITY HELD BY THE BOTTOM HALF, which is the
    ! moment the dispersion of productivity is calibrated on: 17.2 per cent in
    ! the SCF 2022, households aged 26 to 65 with positive wage and salary
    ! income. For a lognormal the share is exactly Phi(-sigma), so the moment IS
    ! a statement about sigma and about nothing else.
    !
    ! The node the median falls inside is SPLIT at the median rather than
    ! assigned whole, so the share moves smoothly in the dispersion instead of
    ! jumping node to node.
    !
    ! IT IS POOLED OVER WORKING AGES WHEN THE GRID FANS OUT, and that is not a
    ! refinement. The SCF number is a cross section of households aged 26 to 65.
    ! On the frozen quantile grid every age has the same distribution and the
    ! age one share IS the pooled share, so the distinction never arose. Under
    ! KKK the grid widens with age: at the persistence the earnings literature
    ! supports the age 26 share is 22.8 per cent while the pooled share is 16.9,
    ! so reading age 26 would report a 32 per cent miss on an economy whose
    ! dispersion is within 2 per cent of target -- and the calibrator would then
    ! chase that phantom gap by inflating sigma.
    !
    ! Ages are weighted equally. Survival weights would be better and are not
    ! available here: load_mortality_profiles runs after this on the first pass.
    ! The SCF sample is a span of ages rather than a survival weighted cohort,
    ! so equal weights are also the closer analogue of what is measured.
    subroutine compute_bottom_half_earnings_share()

        use Global_Vars

        implicit none

        integer, parameter :: pooled_size_1=employment_grid_size*(life_span-retirement_span)
        real(8), dimension(pooled_size_1) :: pooled_y_1,pooled_m_1
        real(8) :: cum_mass_1,total_y_1,swap_y_1,swap_m_1
        integer :: node_1,age_1,slot_1,scan_1,n_used_1

        ! THE MASSES ARE THE SAME AT EVERY AGE. The grid at age a runs from
        ! -s_bottom*sd(a) to +s_top*sd(a) and the marginal is N(0,var(a)), so in
        ! standardised units the nodes and their masses do not move with age.
        ! Only the LEVELS the nodes sit at do, which is exactly the fanning out.
        if (fixed_productivity==0) then

            n_used_1=0

            do age_1=1,life_span-retirement_span

                do node_1=1,employment_grid_size

                    n_used_1=n_used_1+1
                    pooled_y_1(n_used_1)=employment_grid(age_1,node_1)
                    pooled_m_1(n_used_1)=unconditional_employment_probability(node_1)/&
                        real(life_span-retirement_span,8)

                end do

            end do

        else

            n_used_1=employment_grid_size

            do node_1=1,employment_grid_size

                pooled_y_1(node_1)=employment_grid(1,node_1)
                pooled_m_1(node_1)=unconditional_employment_probability(node_1)

            end do

        end if

        ! SORTED ASCENDING IN PRODUCTIVITY, because "the bottom half" is defined
        ! on the pooled distribution and the age blocks interleave: node 1 at age
        ! 65 is poorer than node 1 at age 26, and node 7 at 65 is richer than
        ! node 7 at 26. Insertion sort over at most 280 entries, run once per
        ! calibration loop.
        do slot_1=2,n_used_1

            swap_y_1=pooled_y_1(slot_1)
            swap_m_1=pooled_m_1(slot_1)
            scan_1=slot_1-1

            do while (scan_1>=1)

                if (pooled_y_1(scan_1)<=swap_y_1) exit

                pooled_y_1(scan_1+1)=pooled_y_1(scan_1)
                pooled_m_1(scan_1+1)=pooled_m_1(scan_1)
                scan_1=scan_1-1

            end do

            pooled_y_1(scan_1+1)=swap_y_1
            pooled_m_1(scan_1+1)=swap_m_1

        end do

        total_y_1=0

        do slot_1=1,n_used_1

            total_y_1=total_y_1+pooled_y_1(slot_1)*pooled_m_1(slot_1)

        end do

        model_bottom_half_earnings_share=0
        cum_mass_1=0

        do slot_1=1,n_used_1

            if ((cum_mass_1+pooled_m_1(slot_1))<=0.5d0) then

                model_bottom_half_earnings_share=model_bottom_half_earnings_share+&
                    pooled_y_1(slot_1)*pooled_m_1(slot_1)

                cum_mass_1=cum_mass_1+pooled_m_1(slot_1)

            else

                model_bottom_half_earnings_share=model_bottom_half_earnings_share+&
                    pooled_y_1(slot_1)*(0.5d0-cum_mass_1)

                exit

            end if

        end do

        model_bottom_half_earnings_share=model_bottom_half_earnings_share/&
            max(total_y_1,10.d0**(-10))

    end subroutine

    subroutine KKK_process(rho_fixed,sigma_fixed,rho_shock,sigma_shock,s_deviation_top,s_deviation_bottom,&
        z_grid_by_age,unconditional_probability_distribution,transition_prob_by_age)
        
        use Global_Vars
        
        implicit none
        
        real(8), intent(in) :: s_deviation_top,s_deviation_bottom
        real(8), intent(in) :: rho_fixed,rho_shock,sigma_fixed,sigma_shock
        real(8) :: variance_1,variance_eta,variance_fix
        real(8), dimension(life_span-retirement_span) :: variance_by_age
        real(8), dimension(life_span,employment_grid_size), intent(out) :: z_grid_by_age
        real(8), dimension(life_span,employment_grid_size,employment_grid_size), intent(out) :: transition_prob_by_age
        real(8), dimension(life_span-retirement_span,employment_grid_size) :: probability_distribution
        ! intent(inout), NOT out: this routine never assigns the array, and
        ! intent(out) makes it formally undefined on entry, so a compiler that
        ! poisons intent(out) arguments would hand the caller garbage. The
        ! caller builds the distribution itself afterwards, on the equal-mass
        ! grid; this argument is carried for the interface only.
        real(8), dimension(employment_grid_size), intent(inout) :: unconditional_probability_distribution
        real(8), dimension(life_span-retirement_span) :: width
        real(8) :: temp_upper,temp_lower
                
        variance_1=sigma_fixed**2
        variance_eta=sigma_shock**2
        variance_fix=variance_1/(1-rho_fixed**(2))
        
        variance_by_age(1)=variance_eta+variance_fix
        
        do i=2,life_span-retirement_span
        
            variance_by_age(i)=(rho_shock**2)*variance_by_age(i-1)+variance_eta
            
        end do
                
        do i=1,life_span-retirement_span
        
            z_grid_by_age(i,1)=-s_deviation_bottom*sqrt(variance_by_age(i))
            z_grid_by_age(i,employment_grid_size)=s_deviation_top*sqrt(variance_by_age(i))
            
            width(i)=(z_grid_by_age(i,employment_grid_size)-z_grid_by_age(i,1))/(employment_grid_size-1)
            
            do j=2,employment_grid_size-1
            
                z_grid_by_age(i,j)=z_grid_by_age(i,1)+width(i)*(j-1)
                
            end do
                        
        end do
        
        do i=1,life_span-retirement_span-1
        
            do j=1,employment_grid_size
            
                transition_prob_by_age(i,j,1)=&
                    (1+erf(((z_grid_by_age(i+1,1)+0.5*width(i+1)-rho_shock*z_grid_by_age(i,j))/sqrt(variance_eta))/sqrt(2.d0)))/2
                
                do k=2,employment_grid_size-1
               
                    temp_upper=(1+erf(((z_grid_by_age(i+1,k)+0.5*width(i+1)-rho_shock*z_grid_by_age(i,j))/&
                        sqrt(variance_eta))/sqrt(2.d0)))/2                    
                    temp_lower=(1+erf(((z_grid_by_age(i+1,k)-0.5*width(i+1)-rho_shock*z_grid_by_age(i,j))/&
                        sqrt(variance_eta))/sqrt(2.d0)))/2
                    
                    transition_prob_by_age(i,j,k)=temp_upper-temp_lower
                    
                end do
                
                transition_prob_by_age(i,j,employment_grid_size)=&
                    1-(1+erf(((z_grid_by_age(i+1,employment_grid_size)-0.5*width(i+1)-rho_shock*z_grid_by_age(i,j))/&
                    sqrt(variance_eta))/sqrt(2.d0)))/2
                
                transition_prob_by_age(i,j,:)=transition_prob_by_age(i,j,:)/sum(transition_prob_by_age(i,j,:))
                    
            end do
            
        end do
                
        transition_prob_by_age(life_span-retirement_span,:,:)=0
        
        do i=1,employment_grid_size
                
            transition_prob_by_age(life_span-retirement_span,i,i)=1
            
        end do
        
        do j=life_span-retirement_span+1,life_span
        
            transition_prob_by_age(j,:,:)=transition_prob_by_age(life_span-retirement_span,:,:)
            
        end do
                
        probability_distribution(1,1)=(1+erf(((z_grid_by_age(1,1)+0.5*width(1))/sqrt(variance_by_age(1)))/sqrt(2.d0)))/2
        
        do j=2,employment_grid_size-1
        
            temp_upper=(1+erf(((z_grid_by_age(1,j)+0.5*width(1))/sqrt(variance_by_age(1)))/sqrt(2.d0)))/2
            temp_lower=(1+erf(((z_grid_by_age(1,j)-0.5*width(1))/sqrt(variance_by_age(1)))/sqrt(2.d0)))/2
            probability_distribution(1,j)=temp_upper-temp_lower
            
        end do
        
        probability_distribution(1,employment_grid_size)=&
            1-(1+erf(((z_grid_by_age(1,employment_grid_size)-&
            0.5*width(1))/sqrt(variance_by_age(1)))/sqrt(2.d0)))/2
            
        probability_distribution(1,:)=probability_distribution(1,:)/sum(probability_distribution(1,:))
        
        unconditional_employment_probability=probability_distribution(1,:)
                
    end subroutine
    
    subroutine get_probabilities_KKK_process(rho_fixed,sigma_fixed,rho_shock,sigma_shock,&
        z_grid_by_age,unconditional_probability_distribution,transition_prob_by_age)
        
        use Global_Vars
        
        implicit none
        
        real(8), intent(in) :: rho_fixed,rho_shock,sigma_fixed,sigma_shock
        real(8) :: variance_1,variance_eta,variance_fix
        real(8), dimension(life_span-retirement_span) :: variance_by_age
        real(8), dimension(life_span,employment_grid_size), intent(in) :: z_grid_by_age
        real(8), dimension(life_span,employment_grid_size,employment_grid_size), intent(out) :: transition_prob_by_age
        real(8), dimension(life_span-retirement_span,employment_grid_size) :: probability_distribution
        ! intent(inout), NOT out: this routine never assigns the array, and
        ! intent(out) makes it formally undefined on entry, so a compiler that
        ! poisons intent(out) arguments would hand the caller garbage. The
        ! caller builds the distribution itself afterwards, on the equal-mass
        ! grid; this argument is carried for the interface only.
        real(8), dimension(employment_grid_size), intent(inout) :: unconditional_probability_distribution
        real(8), dimension(life_span-retirement_span) :: width
        real(8) :: temp_upper,temp_lower
                
        variance_1=sigma_fixed**2
        variance_eta=sigma_shock**2
        variance_fix=variance_1/(1-rho_fixed**(2))
        
        variance_by_age(1)=variance_eta+variance_fix
        
        do i=2,life_span-retirement_span
        
            variance_by_age(i)=(rho_shock**2)*variance_by_age(i-1)+variance_eta
            
        end do

        ! WIDTH WAS NEVER ASSIGNED IN THIS ROUTINE, AND IT IS READ SIX TIMES
        ! BELOW. The loop that fills it exists in KKK_process and does not exist
        ! here, so every use of width(i) was a read of uninitialised memory: the
        ! three transition cells, and all three branches of the unconditional
        ! distribution that this routine writes back into
        ! unconditional_employment_probability.
        !
        ! WHY IT NEVER SHOWED UP. With fixed_productivity=1 both of this
        ! routine's outputs are thrown away downstream -- the quantile
        ! construction rebuilds the masses, and the identity transition loop
        ! starts at age one and overwrites the whole of employment_process. So
        ! the garbage was written and then covered, every run, for as long as the
        ! frozen grid was the only grid.
        !
        ! WHAT IT DID WHEN THE COVER CAME OFF. Fresh pages come back zeroed, so
        ! width reads as zero, every interior cell of the transition collapses to
        ! temp_upper - temp_lower = 0, and a row's mass is whatever the two tail
        ! cells hold. For a node near the middle of the grid both tails are
        ! essentially zero, the row sum underflows, and the normalisation
        ! immediately below divides by it. That is where batch_kkk line 4's NaN
        ! came from: renter income went non-finite at the very first age and the
        ! whole aggregation followed.
        !
        ! A BOUNDS CHECK CANNOT FIND THIS. Reading an uninitialised local is not
        ! an out of bounds access, and -fcheck=bounds,pointer ran clean over this
        ! exact code. -finit-real=snan with -ffpe-trap=invalid is the flag that
        ! catches it, and it belongs in the standing check from now on.
        !
        ! Recovered from the grid rather than recomputed from the deviations: the
        ! nodes are equally spaced within each age by construction, so this is
        ! exactly the width KKK_process used, and it needs no argument this
        ! routine was not given.
        do i=1,life_span-retirement_span

            width(i)=(z_grid_by_age(i,employment_grid_size)-z_grid_by_age(i,1))/&
                real(employment_grid_size-1,8)

        end do

        do i=1,life_span-retirement_span-1
        
            do j=1,employment_grid_size
            
                transition_prob_by_age(i,j,1)=&
                    (1+erf(((z_grid_by_age(i+1,1)+0.5*width(i+1)-rho_shock*z_grid_by_age(i,j))/sqrt(variance_eta))/sqrt(2.d0)))/2
                
                do k=2,employment_grid_size-1
               
                    temp_upper=(1+erf(((z_grid_by_age(i+1,k)+0.5*width(i+1)-rho_shock*z_grid_by_age(i,j))/&
                        sqrt(variance_eta))/sqrt(2.d0)))/2                    
                    temp_lower=(1+erf(((z_grid_by_age(i+1,k)-0.5*width(i+1)-rho_shock*z_grid_by_age(i,j))/&
                        sqrt(variance_eta))/sqrt(2.d0)))/2
                    
                    transition_prob_by_age(i,j,k)=temp_upper-temp_lower
                    
                end do
                
                transition_prob_by_age(i,j,employment_grid_size)=&
                    1-(1+erf(((z_grid_by_age(i+1,employment_grid_size)-0.5*width(i+1)-rho_shock*z_grid_by_age(i,j))/&
                    sqrt(variance_eta))/sqrt(2.d0)))/2
                
                transition_prob_by_age(i,j,:)=transition_prob_by_age(i,j,:)/sum(transition_prob_by_age(i,j,:))
                    
            end do
            
        end do
                
        transition_prob_by_age(life_span-retirement_span,:,:)=0
        
        do i=1,employment_grid_size
                
            transition_prob_by_age(life_span-retirement_span,i,i)=1
            
        end do
        
        do j=life_span-retirement_span+1,life_span
        
            transition_prob_by_age(j,:,:)=transition_prob_by_age(life_span-retirement_span,:,:)
            
        end do
                
        probability_distribution(1,1)=(1+erf(((z_grid_by_age(1,1)+0.5*width(1))/sqrt(variance_by_age(1)))/sqrt(2.d0)))/2
        
        do j=2,employment_grid_size-1
        
            temp_upper=(1+erf(((z_grid_by_age(1,j)+0.5*width(1))/sqrt(variance_by_age(1)))/sqrt(2.d0)))/2
            temp_lower=(1+erf(((z_grid_by_age(1,j)-0.5*width(1))/sqrt(variance_by_age(1)))/sqrt(2.d0)))/2
            probability_distribution(1,j)=temp_upper-temp_lower
            
        end do
        
        probability_distribution(1,employment_grid_size)=&
            1-(1+erf(((z_grid_by_age(1,employment_grid_size)-&
            0.5*width(1))/sqrt(variance_by_age(1)))/sqrt(2.d0)))/2
            
        probability_distribution(1,:)=probability_distribution(1,:)/sum(probability_distribution(1,:))
        
        unconditional_employment_probability=probability_distribution(1,:)
                
    end subroutine
    
    subroutine tauchen_method(mu,rho,sigma,s_deviation_top,s_deviation_bottom,number_of_grids,z_grid,probability_matrix)
    
        use Global_Vars
        
        implicit none
        
        integer, intent(in) :: number_of_grids
        real(8), intent(in) :: s_deviation_top,s_deviation_bottom
        real(8), dimension(number_of_grids-1) :: mid_points
        real(8), dimension(1,number_of_grids), intent(out) :: z_grid
        real(8), dimension(number_of_grids,number_of_grids),intent(out) :: probability_matrix
        real(8), intent(in) :: mu,rho,sigma
        real(8) :: sigma_1
        
        write(*,*) "s_deviation_bottom=", s_deviation_bottom
                
        sigma_1=sigma/sqrt(1-rho**2)
                
        z_grid(1,1)=mu-s_deviation_bottom*sigma_1
        z_grid(number_of_grids,1)=mu+s_deviation_top*sigma_1
        
        do i=2,number_of_grids-1
        
            z_grid(1,i)=z_grid(1,1)+((z_grid(1,number_of_grids)-z_grid(1,1))/(number_of_grids-1))*(i-1)
            
        end do
                                
        do i=1,number_of_grids-1
        
            mid_points(i)=(z_grid(1,i+1)+z_grid(1,i))/2
                        
        end do
        
        do i=1,number_of_grids
        
            probability_matrix(i,1)=(1+ERF(((mid_points(1)-mu*(1-rho)-rho*z_grid(1,i))/sigma)/sqrt(2.d0)))/2
            probability_matrix(i,number_of_grids)=1-(1+ERF(((mid_points(number_of_grids-1)-&
                mu*(1-rho)-rho*z_grid(1,i))/sigma)/sqrt(2.d0)))/2
            
            do j=2,number_of_grids-1
            
                probability_matrix(i,j)=(1+ERF(((mid_points(j)-mu*(1-rho)-rho*z_grid(1,i))/sigma)/sqrt(2.d0)))/2-&
                    (1+ERF(((mid_points(j-1)-mu*(1-rho)-rho*z_grid(1,i))/sigma)/sqrt(2.d0)))/2
            
            end do   
            
        end do
    
    end subroutine
    
    subroutine calculate_updated_inheritance_amounts(time_period)
    
        use Global_Vars
        
        implicit none
        
        integer, intent(in) :: time_period
        real(8) :: distribution_used,bequests_less_initial_endowments
                
        total_population_group_1(:)=0
        
        do years_left_on_mortgage_index=1,max_amortization_years
        
            do i=1,number_of_inheritance_ages
                                                                                                                    
                distribution_used=&
                    sum(distribution_stationary(years_left_on_mortgage_index)%vector_transition_real&
                    (time_period,inheritance_age_grid(i),:,:,:,:,:))
                    
                total_population_group_1(i)=total_population_group_1(i)+distribution_used
                                                                                                   
            end do
            
        end do
        
!        write(*,*) "inheritance_amount 1=", inheritance_amount
        
        bequests_less_initial_endowments=model_bequests(time_period)-value_of_initial_assets
                    
        do i=1,number_of_inheritance_ages
        
            inheritance_amount(i)=proportion_of_inheritance_per_group(i)*&
                 (bequests_less_initial_endowments/total_population_group_1(i))
                 
        end do
                         
!        write(*,*) "inheritance_amount 2=", inheritance_amount
                               
    end subroutine
    
