    subroutine load_smi_prevalence_profile()

        ! Read the NSDUH SMI prevalence profile, ages 26 to 85. Built by
        ! data/make_mh_onset.py, which is also what code/simple reads. The file
        ! carries the shape and an implied onset alongside; only the prevalence
        ! column is used here, because this file derives onset from the note's
        ! identity rather than from a shape/level split.

        use Global_Vars

        implicit none

        integer :: age_1,i_1,ios_1
        real(8) :: shape_1,implied_1,prev_1
        character(len=400) :: header_1
        logical :: file_exists_1

        ! This routine is called more than once per run, so the allocation is
        ! guarded and the file is read once. Allocating unconditionally aborted
        ! the run on the second call.
        if (allocated(smi_prevalence_by_age)) return

        allocate(smi_prevalence_by_age(life_span))
        allocate(smi_onset_by_age(life_span))
        allocate(smi_onset_shape_by_age(life_span))

        smi_prevalence_by_age=0
        smi_onset_by_age=0
        smi_onset_shape_by_age=0

        inquire(file="../data/us_mh_onset_shape.csv",exist=file_exists_1)

        if (.NOT. file_exists_1) then

            inquire(file="us_mh_onset_shape.csv",exist=file_exists_1)

            if (.NOT. file_exists_1) then

                write(*,*) "us_mh_onset_shape.csv not found. stopping."
                stop

            end if

            open(unit=75,file="us_mh_onset_shape.csv",action='read')

        else

            open(unit=75,file="../data/us_mh_onset_shape.csv",action='read')

        end if

            read(75,'(A)') header_1

            do i_1=1,life_span

                read(75,*,iostat=ios_1) age_1,shape_1,implied_1,prev_1

                if (ios_1/=0) then

                    prev_1=smi_prevalence_by_age(max(i_1-1,1))
                    shape_1=smi_onset_shape_by_age(max(i_1-1,1))

                end if

                smi_prevalence_by_age(i_1)=prev_1
                ! KEPT, not discarded. The profile is still read, because it is
                ! what the calibrated level is judged against.
                smi_onset_shape_by_age(i_1)=shape_1

            end do

        close(75)

        ! The floor, from the profile itself rather than a hardcoded guess.
        lambda_m_floor=0

        do i_1=1,life_span-1

            if (smi_prevalence_by_age(i_1)>10.d0**(-12)) then

                lambda_m_floor=max(lambda_m_floor,&
                    1.d0-smi_prevalence_by_age(i_1+1)/smi_prevalence_by_age(i_1))

            end if

        end do

        ! A small margin, so onset is strictly positive rather than exactly zero
        ! at the steepest age.
        lambda_m_floor=lambda_m_floor+10.d0**(-3)

        write(*,*) "SMI prevalence, first and last=", &
            smi_prevalence_by_age(1), smi_prevalence_by_age(life_span)
        write(*,*) "lambda_m floor implied by the profile=", lambda_m_floor

    end subroutine

    subroutine build_smi_onset()

        ! eq:fonsetage. Given the observed prevalence profile and the recovery
        ! hazard, this is the onset that reproduces the profile exactly:
        !
        !     onset(j) = [ p(j+1) - p(j)(1-lambda_m) ] / (1 - p(j))
        !
        ! Called from recompute_derived_parameters, because it depends on
        ! lambda_m and lambda_m is calibrated.
        !
        ! IT CAN GO NEGATIVE, and that is information rather than an error. A
        ! negative value means the observed profile falls faster than the
        ! recovery hazard alone can explain, so no non negative onset reproduces
        ! it at that lambda_m. It is clamped at zero and counted; a large count
        ! means lambda_m has been pushed too low for the data, and the
        ! calibration should not be reading a fit through it silently.

        use Global_Vars

        implicit none

        integer :: j_1,clipped_1
        real(8) :: p_now_1,p_next_1,onset_1

        clipped_1=0

        if (smi_onset_from_shape==1) then

            ! The assigned shape, scaled by the calibrated level. No identity, so
            ! no floor under lambda_m and no clipping: onset is positive wherever
            ! the shape is.
            smi_onset_by_age=min(max(smi_onset_level*smi_onset_shape_by_age,0.d0),1.d0)

            write(*,*) "build_smi_onset: shape x level. level=", smi_onset_level, &
                " onset(1)=", smi_onset_by_age(1), " onset(30)=", smi_onset_by_age(30), &
                " max=", maxval(smi_onset_by_age), " lambda_m=", lambda_m, &
                " implied ergodic prevalence=", &
                smi_onset_by_age(1)/max(smi_onset_by_age(1)+lambda_m,10.d0**(-12))

            return

        end if

        do j_1=1,life_span

            p_now_1=smi_prevalence_by_age(j_1)

            if (j_1<life_span) then

                p_next_1=smi_prevalence_by_age(j_1+1)

            else

                p_next_1=p_now_1

            end if

            if (p_now_1>=1.d0-10.d0**(-8)) then

                smi_onset_by_age(j_1)=0
                cycle

            end if

            onset_1=(p_next_1-p_now_1*(1-lambda_m))/(1-p_now_1)

            if (onset_1<0.d0) then

                onset_1=0
                clipped_1=clipped_1+1

            end if

            smi_onset_by_age(j_1)=min(onset_1,1.d0)

        end do

        if (clipped_1>0) then

            write(*,*) "build_smi_onset: onset clipped at zero for ", &
                clipped_1, " ages; lambda_m too low for the profile. lambda_m=", lambda_m

        end if

        write(*,*) "build_smi_onset: lambda_m=", lambda_m, " onset(1)=", smi_onset_by_age(1), &
            " onset(30)=", smi_onset_by_age(30), " max=", maxval(smi_onset_by_age), &
            " implied ergodic prevalence=", smi_onset_by_age(1)/max(smi_onset_by_age(1)+lambda_m,10.d0**(-12))

    end subroutine


    subroutine load_mortality_profiles()

        ! Read the CDC and Baggett profiles once. The file has a header and sixty
        ! rows, ages 26 to 85, and the last row's shape is nan because the
        ! difference that defines it has no next age; it is read as zero, which
        ! is right, since the SUD's excess mortality has gone by 85.
        !
        ! IDEMPOTENT, because it is now called from two places. It has to run
        ! before build_mortality_multipliers, which lives in
        ! initialize_variables_and_grids, and the original call sat in
        ! GKKOC_intergenerational_employment_process, which runs after it.

        use Global_Vars

        implicit none

        integer :: age_1,i_1,ios_1,hold_i_1
        real(8) :: shape_1,rr_1,d1_1,d2_1,d3_1
        character(len=400) :: header_1
        logical :: file_exists_1

        if (mortality_profiles_loaded==1) return

        inquire(file="../data/us_mortality_multipliers.csv",exist=file_exists_1)

        if (.NOT. file_exists_1) then

            inquire(file="us_mortality_multipliers.csv",exist=file_exists_1)

            if (.NOT. file_exists_1) then

                write(*,*) "us_mortality_multipliers.csv not found. stopping."
                stop

            end if

            open(unit=74,file="us_mortality_multipliers.csv",action='read')

        else

            open(unit=74,file="../data/us_mortality_multipliers.csv",action='read')

        end if

            read(74,'(A)') header_1

            hold_i_1=0

            do i_1=1,life_span

                read(74,*,iostat=ios_1) age_1,shape_1,rr_1,d1_1,d2_1,d3_1

                if (ios_1/=0) then

                    shape_1=0
                    rr_1=1

                end if

                if (shape_1/=shape_1) shape_1=0
                if (rr_1/=rr_1) rr_1=1

                ! THE SUD MULTIPLIER IS FLAT AT ITS LEVEL, NOT SHAPED BY
                ! OVERDOSE. shape_sud in the csv is r(a)/max(r) with
                !
                !     r(a) = overdose hazard given SUD / all cause baseline
                !
                ! and make_mortality_multipliers.py says in as many words that
                ! overdose is only ABOUT HALF of SUD excess mortality, the rest
                ! running through liver disease, endocarditis, hepatitis, HIV,
                ! suicide and accidents. Applying overdose's profile to the whole
                ! penalty imposes a collapse the other half does not have, and
                ! the denominator makes it worse: all cause baseline mortality
                ! explodes with age, so r(a) falls two orders of magnitude
                ! largely because of what is underneath it rather than because
                ! the disorder becomes safe.
                !
                ! What it produced: a multiplier of 1.07 at data age 75, a
                ! disorder that raises a seventy five year old's chance of dying
                ! by seven per cent, against published all cause SMRs for the
                ! disorder of six to ten. Every household in the model started
                ! using at data age 69, where the shape collapses, and the use
                ! rate went from zero to ninety nine per cent in three years.
                !
                ! Flat at the level puts the multiplier at the literature's own
                ! number at every age. rr_homeless is still read from the file
                ! and still age varying: it is measured directly by Baggett et
                ! al. and nothing here touches it.
                shape_sud_profile(i_1)=1.d0
                rr_homeless_profile(i_1)=max(rr_1,1.d0)

                ! The row whose age is the hold age, found by reading the age
                ! column rather than assuming the file starts at 26.
                if (age_1==rr_homeless_hold_age) hold_i_1=i_1

            end do

        close(74)

        ! HOLD THE RELATIVE RISK FLAT ABOVE THE HOLD AGE. See the declaration of
        ! rr_homeless_hold_age for why the tail it replaces is not a measurement.
        if ((rr_homeless_hold_age>0) .AND. (hold_i_1>0) .AND. &
            (hold_i_1<life_span)) then

            do i_1=hold_i_1+1,life_span

                if (rr_homeless_old_level>0.d0) then

                    rr_homeless_profile(i_1)=rr_homeless_old_level

                else

                    rr_homeless_profile(i_1)=rr_homeless_profile(hold_i_1)

                end if

            end do

            write(*,*) "rr_homeless above data age", rr_homeless_hold_age, &
                "set to", rr_homeless_profile(life_span), &
                " (calibrated=", rr_homeless_old_level, ")"

        else if (rr_homeless_hold_age>0) then

            write(*,*) "rr_homeless_hold_age", rr_homeless_hold_age, &
                "is not an age in the file; profile left as read"

        end if

        mortality_profiles_loaded=1

        write(*,*) "mortality profiles loaded, shape_sud(1)=", shape_sud_profile(1), &
            " rr_homeless(1)=", rr_homeless_profile(1)

    end subroutine

    subroutine build_mortality_multipliers()

        ! Equation (25). Called whenever the level moves.

        use Global_Vars

        implicit none

        integer :: j_1

        do j_1=1,life_span

            kappa_phi_d_by_age(j_1)=1+(kappa_phi_d_level-1)*shape_sud_profile(j_1)

            ! THE EXCESS DEATH RISK FROM THE STREET IS FLAT IN AGE, on the
            ! author's instruction of 31 August. Not the MULTIPLIER, which is a
            ! different thing and the wrong one.
            !
            ! The multiplier route -- Baggett's ratios, or the flat 1.6 the
            ! note's external calibration table quotes from Meyer, Wyse and
            ! Logani -- makes the excess ANNUAL DEATH PROBABILITY proportional
            ! to baseline mortality, and baseline mortality rises elevenfold
            ! between 26 and 65. Measured on this life table, the excess risk
            ! from sleeping rough runs 1.00, 2.19 and 4.84 across 26, 45 and 65
            ! under Baggett, and 1.00, 2.62 and 11.34 under a flat 1.6. Since
            ! ninety four per cent of this model's homeless could afford rent
            ! and are CHOOSING the street, that gradient is the deterrent they
            ! choose against, and it is why the model puts ninety eight per cent
            ! of its homeless under 35 against twenty six in the HUD count.
            !
            ! Holding the excess RISK flat instead makes the multiplier fall
            ! with age -- 4.41 at 26 to 1.30 at 65 -- which is the only one of
            ! the three specifications that is age neutral in the thing the
            ! household actually trades off.
            if (homeless_death_risk_flat_in_age==1) then

                kappa_phi_h_by_age(j_1)=max(1.d0,1.d0+homeless_excess_death_risk/&
                    max(1.d0-actual_survival_probability(j_1),10.d0**(-12)))

            elseif (homeless_death_risk_flat_in_age==2) then

                ! THE NOTE'S OWN CALIBRATION: a flat MULTIPLIER of 1.6 from
                ! Meyer, Wyse and Logani, which is what external_calibration.tex
                ! says and what increased_risk_of_death_homeless already holds.
                ! Kept as a setting rather than argued about, because whether it
                ! shifts the age profile older or younger is a general
                ! equilibrium question and not an arithmetic one.
                kappa_phi_h_by_age(j_1)=1.d0+increased_risk_of_death_homeless

            else

                kappa_phi_h_by_age(j_1)=max(1.d0,rr_homeless_profile(j_1)/&
                    ((1-sud_share_of_homeless)+sud_share_of_homeless*kappa_phi_d_by_age(j_1)))

            end if

        end do

    end subroutine

    subroutine recompute_derived_parameters()

        ! EVERY QUANTITY DERIVED FROM A CALIBRATED ONE, REBUILT IN ONE PLACE.
        !
        ! Eleven parameters the note calls calibrated were compile time
        ! constants. Freeing them is only half the job: a dozen more quantities
        ! were initialised FROM them in their declarations, which in Fortran
        ! happens once, so a freed parameter would move and everything computed
        ! from it would silently keep the starting value.
        !
        ! So the derived ones now start at zero and are built here, and this is
        ! called at initialisation and again after every calibration update.
        ! Anything derived from a calibrated parameter belongs in this routine
        ! and nowhere else.

        use Global_Vars

        implicit none

        ! The Cobb-Douglas weights. With change_utility_for_addicts and
        ! size_of_penalty both zero the disorder does not move them, so the two
        ! versions agree, which optimize_frac_spent_on_addiciton checks.
        relative_share_of_addiction_2=&
            change_utility_for_addicts*((1-perceived_probability_lower)*0.45+&
            perceived_probability_lower*0.44)+&
            (1-change_utility_for_addicts)*&
            (size_of_penalty*((0.39-relative_share_of_addiction_1))+relative_share_of_addiction_1)

        relative_share_of_addiction=relative_share_of_addiction_1

        ! GAMMA IS THE HOUSING WEIGHT AND HAS TO BE THE ONE THE UTILITY READS.
        ! These four lines built the weights from relative_share_of_housing_0, a
        ! PARAMETER fixed at 0.278, while the sweep calibrated
        ! relative_share_of_housing against the rent to income share. So the
        ! instrument could not move its own moment: gamma ran to its floor of
        ! 0.01 and the moment sat at 0.52 against a target of 0.268 for the whole
        ! run, and gamma's only remaining effect was as (1-gamma) on the
        ! consumption term of the executed branch.
        !
        ! It is a wiring error and not a modelling choice. The note defines gamma
        ! as the Cobb-Douglas share of the bundle that goes on housing, targeted
        ! at 26.8 per cent of expenditure net of drugs from the 2024 CEX, which is
        ! exactly avg_rent_to_income_data. Same object, same target; the utility
        ! was simply reading a different variable.
        !
        ! The nesting is unchanged, so the weights still sum to one: within the
        ! non-drug bundle gamma goes to housing and 1-gamma to consumption, and
        ! the bundle itself carries 1-theta.
        relative_share_of_housing_1=relative_share_of_housing*(1-relative_share_of_addiction_1)
        relative_share_of_housing_2=relative_share_of_housing*(1-relative_share_of_addiction_2)

        relative_share_of_consumption_1=(1-relative_share_of_housing)*(1-relative_share_of_addiction_1)
        relative_share_of_consumption_2=(1-relative_share_of_housing)*(1-relative_share_of_addiction_2)

        ! The Stone-Geary shifter. b is constant across every state and choice,
        ! so b_sud_ratio is one and the two are the same number; the line is kept
        ! so a robustness run can separate them in one place.
        addiction_scalar_2=b_sud_ratio*addiction_scalar_1

        ! PREFERENCES ARE THE SAME IN BOTH STATES, AND THIS CHECKS IT RATHER
        ! THAN ASSUMING IT. The _1 and _2 weights exist so that a robustness run
        ! can let the disorder move tastes, which an earlier version of this
        ! programme did. The benchmark does not: change_utility_for_addicts and
        ! size_of_penalty are both parameters fixed at zero, so the algebra above
        ! collapses _2 onto _1 and the housing and consumption weights follow,
        ! and b_sud_ratio is one so the Stone-Geary shifter does too.
        !
        ! That is an argument about four compile-time constants, and it is the
        ! kind of argument that stops being true without anyone noticing. The
        ! shares enter the addicted state's utility directly, so a divergence
        ! would not crash and would not look wrong in any moment -- it would
        ! quietly make the disordered a different kind of household, which is a
        ! claim the note does not make. This routine runs at initialisation and
        ! after every calibration update, so checking here checks every solve.
        if (abs(relative_share_of_addiction_2-relative_share_of_addiction_1)>10.d0**(-12) .OR. &
            abs(relative_share_of_housing_2-relative_share_of_housing_1)>10.d0**(-12) .OR. &
            abs(relative_share_of_consumption_2-relative_share_of_consumption_1)>10.d0**(-12) .OR. &
            abs(addiction_scalar_2-addiction_scalar_1)>10.d0**(-12)) then

            write(*,*) "PREFERENCES DIFFER ACROSS STATES, which the benchmark does not allow."
            write(*,*) "   addiction   _1=", relative_share_of_addiction_1,&
                " _2=", relative_share_of_addiction_2
            write(*,*) "   housing     _1=", relative_share_of_housing_1,&
                " _2=", relative_share_of_housing_2
            write(*,*) "   consumption _1=", relative_share_of_consumption_1,&
                " _2=", relative_share_of_consumption_2
            write(*,*) "   scalar      _1=", addiction_scalar_1,&
                " _2=", addiction_scalar_2
            write(*,*) "   change_utility_for_addicts=", change_utility_for_addicts,&
                " size_of_penalty=", size_of_penalty, " b_sud_ratio=", b_sud_ratio
            stop

        end if

        ! The SMI onset profile. Depends on lambda_m, which is calibrated, so it
        ! is rebuilt here rather than once at startup.
        if (allocated(smi_onset_by_age)) then

            call build_smi_onset()

        end if

        ! Recovery on the street, as a multiple of recovery while housed.
        probability_of_stopping_addiction_if_homeless=&
            mu_homeless*probability_of_stopping_addiction

        ! The employment margins with the disorder.
        probability_becoming_unemployed_if_addicted=&
            max(min(probability_becoming_unemployed*&
            multiple_of_probabilities_of_employment_if_addicted,1.d0),0.d0)

        probability_becoming_employed_if_addicted=&
            max(min(probability_becoming_employed/&
            multiple_find_if_addicted,1.d0),0.d0)

        ! Mortality with both. The note multiplies the two hazards; the code used
        ! to add the two excesses, which is not the same thing once either is
        ! large. See the age varying block for the rest of that repair.
        increased_risk_of_death_homeless_addicted=&
            (1+increased_risk_of_death_homeless)*(1+increased_risk_of_death_addicted)-1

        ! The voucher lottery.
        probability_of_voucher_benchmark_used_1=probability_of_voucher_benchmark_used

        probability_of_voucher_benchmark=&
            (1-perceived_probability_lower)*&
            (/real(probability_of_voucher_benchmark_used,8),&
            min(real(probability_of_voucher_benchmark_used*increased_prob_of_voucher_if_homeless,8),1.d0),&
            min(real(probability_of_voucher_benchmark_used*&
            increased_prob_of_voucher_if_homeless_and_addicted,8),1.d0)/)+&
            perceived_probability_lower*probability_of_voucher_benchmark_used*&
            (/real(probability_of_voucher_benchmark_used,8),&
            min(real(probability_of_voucher_benchmark_used*increased_prob_of_voucher_if_homeless,8),1.d0),&
            min(real(probability_of_voucher_benchmark_used*&
            increased_prob_of_voucher_if_homeless_and_addicted,8),1.d0)/)

        probability_of_voucher=probability_of_voucher_benchmark

    end subroutine

    subroutine clear_drug_market(time_period)

        ! See the block at drug_supply_elasticity for what this is and why the
        ! benchmark normalises while the counterfactuals clear.

        use Global_Vars

        implicit none

        integer, intent(in) :: time_period
        real(8) :: quantity_1,implied_price_1,gap_1,step_1
        logical :: shifter_exists_1

        ! Partial equilibrium holds prices fixed by definition, and the
        ! elasticity test perturbs this price on purpose, so neither may have it
        ! moved underneath them.
        if ((include_addiction==0) .OR. (partial_equilibrium==1) .OR. &
            (test_elasticity==1)) then

            distance_drug_market=0

            return

        end if

        quantity_1=model_drugs_consumed_by_users(time_period)

        if (quantity_1<=0) then

            write(*,*) "no drug use at all, the drug market is left alone"
            distance_drug_market=0

            return

        end if

        if (is_counterfactual==0) then

            ! Normalise: pick the shifter that puts the price at one here.
            drug_supply_shifter=1/(quantity_1**(drug_supply_curvature-1))

            price_of_addictive_good=price_of_addictive_good_benchmark
            distance_drug_market=0

            open(unit=73,file="drug_supply_shifter"//trim(benchmark_simulation)//".dat",&
                action='write',status='replace')
                write(73,'(F35.20)') drug_supply_shifter
            close(73)

            write(*,*) "drug quantity V=", quantity_1
            write(*,*) "drug_supply_shifter (normalised)=", drug_supply_shifter

        else

            inquire(file="drug_supply_shifter"//trim(benchmark_simulation)//".dat",&
                exist=shifter_exists_1)

            if (shifter_exists_1) then

                open(unit=73,file="drug_supply_shifter"//trim(benchmark_simulation)//".dat",&
                    action='read')
                    read(73,'(F35.20)') drug_supply_shifter
                close(73)

            else

                write(*,*) "no drug_supply_shifter from the benchmark. stopping."
                stop

            end if

            implied_price_1=drug_supply_shifter*(quantity_1**(drug_supply_curvature-1))

            gap_1=implied_price_1-price_of_addictive_good

            distance_drug_market=abs(gap_1)

            ! Secant where two usable points exist, damped step otherwise. The
            ! supply price rises in quantity and demand falls in price, so the
            ! gap is monotone in the price and the secant is well behaved; the
            ! clip is there for the first loops, before it is.
            step_1=price_of_addictive_good+drug_market_adjuster*gap_1

            if ((have_drug_price_secant==1) .AND. &
                (abs(gap_1-previous_drug_price_gap)>10.d0**(-10)) .AND. &
                (abs(price_of_addictive_good-previous_price_of_addictive_good)>10.d0**(-10))) then

                step_1=price_of_addictive_good-gap_1*&
                    (price_of_addictive_good-previous_price_of_addictive_good)/&
                    (gap_1-previous_drug_price_gap)

            end if

            step_1=max(min(step_1,2*price_of_addictive_good),price_of_addictive_good/2)

            previous_price_of_addictive_good=price_of_addictive_good
            previous_drug_price_gap=gap_1
            have_drug_price_secant=1

            price_of_addictive_good=max(step_1,10.d0**(-6))

            write(*,*) "drug quantity V=", quantity_1
            write(*,*) "implied supply price=", implied_price_1
            write(*,*) "price_of_addictive_good=", price_of_addictive_good
            write(*,*) "distance_drug_market=", distance_drug_market

        end if

    end subroutine

    subroutine write_calibration_state()

        ! RESUMING AFTER A KILL. A calibration is days of wall clock and it used
        ! to lose all of it on a kill: the only memory of where the bisection had
        ! got to was three starting values edited into the declarations by hand,
        ! so a restart went back to whatever they last happened to say.
        !
        ! Every loop now writes the parameters the update block moves, together
        ! with the prices and the damping state, so a restart picks up where the
        ! last completed loop left off. The damping state matters as much as the
        ! parameters: drop it and a resumed run rings again from a full step, and
        ! the loops spent settling the first time are spent again.
        !
        ! Written to a temporary and renamed, because a kill during the write is
        ! the one moment when this file is being touched and a half written file
        ! that parses is worse than no file at all.
        !
        ! V3 ADDS EVERYTHING ELSE THE UPDATE BLOCK MOVES, which was most of it.
        ! v2 saved thirty eight items and the update block moves sixty. Among the
        ! twenty two missing were b, aleph, cbar, pi_V, theta, sigma_y, omega,
        ! delta_d, mu_homeless, the separation rate and the employment multiplier,
        ! together with the damping and bracket state of beta, delta_d, b and
        ! size_homelessness.
        !
        ! This is not a small loss on a restart, it is a WORSE state than a cold
        ! start. Measured: a resume put lambda back at 1.7585, where six loops had
        ! left it, and b back at its declared 0.2537, where loop zero had left it.
        ! Those two are calibrated against each other, so the model came back with
        ! a hazard tuned for a population that b no longer produces, and
        ! participation jumped from 0.0044 to 0.117 against a target of 0.0513.
        ! The container kills this run about every fifty minutes and a loop takes
        ! fifteen, so without this the sweep cannot accumulate three loops of
        ! progress before losing most of it again.
        !
        ! Deliberately NOT saved: rental_market_adjuster, which is set before it
        ! is read, and the three previous_* convergence checks, which only make
        ! the first resumed loop report a large distance against its own last
        ! value. Saving something set before use is how a resume starts differing
        ! from a run that was never killed.
        !
        ! V2 ADDED THE FOUR SMI PARAMETERS. They were wired into the update block
        ! and not into this file, so a resumed run picked the housing and drug
        ! parameters up where they left off and sent lambda_m, kappa_uem, rho_m
        ! and rho_d back to their declared values. That is worse than not
        ! resuming at all: the parameters that resume are the ones the SMI
        ! parameters have to be consistent with. The version tag is bumped so a
        ! v1 file is ignored rather than read short and misaligned.

        use Global_Vars

        implicit none

        open(unit=71,file="calibration_state.tmp",action='write',status='replace')

            write(71,'(A)') "calibration_state_v3"
            write(71,'(F30.15)') discount_factor
            write(71,'(F30.15)') discount_factor_on_child
            write(71,'(F30.15)') minimum_inheritance
            write(71,'(F30.15)') advantage_to_owning
            write(71,'(F30.15)') relative_share_of_housing
            write(71,'(F30.15)') relative_share_of_leisure
            write(71,'(F30.15)') largest_house_size
            write(71,'(F30.15)') smallest_rental_relative_to_lowest_income
            write(71,'(F30.15)') labor_income_tax_rate
            write(71,'(F30.15)') standard_deduction_as_percent_of_average_labor_income
            write(71,'(F30.15)') probability_of_becoming_addicted_if_experiment
            write(71,'(F30.15)') lambda_addiction
            write(71,'(F30.15)') price_of_addictive_good
            write(71,'(F30.15)') drug_supply_shifter
            write(71,'(F30.15)') utility_cost_of_treatment
            write(71,'(F30.15)') previous_utility_cost_of_treatment
            write(71,'(F30.15)') previous_treatment_take_up
            write(71,'(I10)') have_treatment_secant
            write(71,'(F30.15)') previous_onset_at_mean
            write(71,'(F30.15)') previous_sud_rate
            write(71,'(I10)') have_lambda_secant
            write(71,'(F30.15)') size_homelessness
            write(71,'(F30.15)') fixed_cost_to_moving
            write(71,'(F30.15)') housing_status_grid_expander
            write(71,'(F30.15)') smallest_house_size_adjuster
            write(71,'(F30.15)') largest_house_size_adjuster
            write(71,'(F30.15)') previous_gap_smallest_house_size
            write(71,'(F30.15)') previous_gap_largest_house_size
            write(71,'(I10)') have_gap_smallest_house_size
            write(71,'(I10)') have_gap_largest_house_size
            write(71,'(I10)') loop_count
            write(71,'(F30.15)') housing_price(1)
            write(71,'(F30.15)') rent(1,:)
            write(71,'(F30.15)') convexity_of_rental_company
            write(71,'(F30.15)') inheritance_amount
            write(71,'(F30.15)') lambda_m
            write(71,'(F30.15)') kappa_uem
            write(71,'(F30.15)') rho_m
            write(71,'(F30.15)') rho_d
            write(71,'(F30.15)') addiction_scalar_1
            write(71,'(F30.15)') addiction_scalar_adjuster
            write(71,'(F30.15)') previous_gap_addiction_scalar
            write(71,'(I10)') have_gap_addiction_scalar
            write(71,'(F30.15)') max_food_cost
            write(71,'(F30.15)') mu_homeless
            write(71,'(F30.15)') penalty_child_addicted
            write(71,'(F30.15)') penalty_child_addicted_adjuster

            write(71,'(F30.15)') previous_gap_penalty_child
            write(71,'(I10)') have_gap_penalty_child
            write(71,'(F30.15)') probability_becoming_unemployed
            write(71,'(F30.15)') probability_of_voucher_benchmark_used
            write(71,'(F30.15)') relative_share_of_addiction_1
            write(71,'(F30.15)') sd_permanent_productivity
            write(71,'(F30.15)') value_of_life
            write(71,'(F30.15)') value_of_life_at_bracket
            write(71,'(F30.15)') weight_on_child
            write(71,'(F30.15)') multiple_of_probabilities_of_employment_if_addicted
            write(71,'(F30.15)') discount_factor_adjuster
            write(71,'(F30.15)') discount_factor_lo
            write(71,'(F30.15)') discount_factor_hi
            write(71,'(F30.15)') discount_factor_lo_moment
            write(71,'(F30.15)') discount_factor_hi_moment
            write(71,'(F30.15)') previous_gap_discount_factor

            ! THE SHARES THE CHILD'S PENALTY IS APPLIED THROUGH, IN THEIR OWN
            ! FILE. Leaving them unbanked switched the intergenerational channel
            ! off at every restart: newborn_parent_share is built by the
            ! AGGREGATION, which runs after the distribution, so the first
            ! distribution of a fresh process used the declared default, all mass
            ! on clean and housed parents, which is the UNPENALISED draw. The
            ! trace showed exactly that, (1, 0, 0, 0) at the point the draw is
            ! mixed, while the previous process had measured 0.894 clean against
            ! 0.106 disordered.
            !
            ! NOT APPENDED TO calibration_state.dat, AND THAT WAS TRIED FIRST.
            ! The state record's write and read orders diverge at the tail: the
            ! writer ends at previous_gap_discount_factor and the reader at
            ! voucher_probability_adjuster, so the file carries records the
            ! reader never consumes. Four reads appended at the end therefore
            ! picked up those trailing values rather than hitting end of file,
            ! and resumed the shares as 0.0102 and 1e-15. A separate file cannot
            ! be misaligned by anything.
            open(unit=73,file="newborn_parent_share.dat",status='replace')
                ! THE WHOLE ARRAY, because it now resolves the dying mass by
                ! the parent's productivity node as well and four scalars can no
                ! longer carry it.
                write(73,'(F30.15)') newborn_parent_share
            close(73)

            write(71,'(I10)') have_gap_discount_factor
            write(71,'(F30.15)') size_homelessness_lo
            write(71,'(F30.15)') size_homelessness_hi
            write(71,'(F30.15)') size_homelessness_lo_moment
            write(71,'(F30.15)') size_homelessness_hi_moment
            write(71,'(F30.15)') value_of_life_trust
            write(71,'(F30.15)') previous_gap_value_of_life
            write(71,'(I10)') have_gap_value_of_life
            write(71,'(F30.15)') size_homelessness_adjuster
            write(71,'(F30.15)') previous_gap_size_homelessness
            write(71,'(I10)') have_gap_size_homelessness
            write(71,'(F30.15)') voucher_probability_adjuster
            write(71,'(F30.15)') previous_gap_voucher_probability
            write(71,'(I10)') have_gap_voucher_probability
            write(71,'(F30.15)') separation_rate_adjuster
            write(71,'(F30.15)') previous_gap_separation_rate
            write(71,'(I10)') have_gap_separation_rate
            write(71,'(F30.15)') employment_multiplier_adjuster
            write(71,'(F30.15)') previous_gap_employment_multiplier
            write(71,'(I10)') have_gap_employment_multiplier
            ! Appended last, so a state file written before the curvature became
            ! an instrument still reads: the tolerant reads below stop at the
            ! end of it and leave these at their declared values.
            write(71,'(F30.15)') housing_status_grid_expander_adjuster
            write(71,'(F30.15)') previous_gap_housing_status_grid_expander
            write(71,'(I10)') have_gap_housing_status_grid_expander
            write(71,'(F30.15)') relative_share_of_housing_adjuster
            write(71,'(F30.15)') previous_gap_relative_share_of_housing
            write(71,'(I10)') have_gap_relative_share_of_housing
            write(71,'(F30.15)') labor_income_tax_rate_adjuster
            write(71,'(F30.15)') previous_gap_labor_income_tax_rate
            write(71,'(I10)') have_gap_labor_income_tax_rate
            write(71,'(F30.15)') lambda_clamp
            write(71,'(F30.15)') previous_gap_lambda_addiction
            write(71,'(I10)') have_gap_lambda_addiction
            write(71,'(F30.15)') relative_share_of_leisure_adjuster
            write(71,'(F30.15)') previous_gap_relative_share_of_leisure
            ! AT THE TAIL, AND NOT WHERE IT READS BEST. calibration_state.dat is
            ! positional: an entry inserted in the middle shifts every value
            ! after it, and a checkpoint written before delta_h existed would be
            ! read one field out from that point on, silently. The tail is the
            ! only place a new field can go, because the read there is guarded by
            ! iostat and an older file simply runs out.
            write(71,'(I10)') have_gap_relative_share_of_leisure
            write(71,'(F30.15)') penalty_child_homeless
            write(71,'(F30.15)') penalty_child_homeless_adjuster
            write(71,'(F30.15)') previous_gap_penalty_child_homeless
            write(71,'(I10)') have_gap_penalty_child_homeless
            ! AT THE TAIL, for the reason the comment above gives.
            write(71,'(F30.15)') kkk_sigma_scale

        close(71)

        call rename("calibration_state.tmp","calibration_state.dat")

    end subroutine

    subroutine read_calibration_state()

        ! The other half of the resume. Absent file means a fresh start, which is
        ! what a first run wants, so this is silent rather than an error. Delete
        ! calibration_state.dat to force one.

        use Global_Vars

        implicit none

        logical :: state_exists_1
        character(len=40) :: state_tag_1
        integer :: state_ios_1

        inquire(file="calibration_state.dat",exist=state_exists_1)

        if (.NOT. state_exists_1) then

            write(*,*) "no calibration_state.dat, starting from the declared values"

            return

        end if

        open(unit=72,file="calibration_state.dat",action='read')

            read(72,'(A)') state_tag_1

            if (trim(state_tag_1) .NE. "calibration_state_v3") then

                write(*,*) "calibration_state.dat is not version 3, ignoring it"
                close(72)

                return

            end if

            read(72,'(F30.15)') discount_factor
            read(72,'(F30.15)') discount_factor_on_child
            read(72,'(F30.15)') minimum_inheritance
            read(72,'(F30.15)') advantage_to_owning
            read(72,'(F30.15)') relative_share_of_housing
            read(72,'(F30.15)') relative_share_of_leisure
            read(72,'(F30.15)') largest_house_size
            read(72,'(F30.15)') smallest_rental_relative_to_lowest_income
            read(72,'(F30.15)') labor_income_tax_rate
            read(72,'(F30.15)') standard_deduction_as_percent_of_average_labor_income
            read(72,'(F30.15)') probability_of_becoming_addicted_if_experiment
            read(72,'(F30.15)') lambda_addiction
            read(72,'(F30.15)') price_of_addictive_good
            read(72,'(F30.15)') drug_supply_shifter
            read(72,'(F30.15)') utility_cost_of_treatment
            read(72,'(F30.15)') previous_utility_cost_of_treatment
            read(72,'(F30.15)') previous_treatment_take_up
            read(72,'(I10)') have_treatment_secant
            read(72,'(F30.15)') previous_onset_at_mean
            read(72,'(F30.15)') previous_sud_rate
            read(72,'(I10)') have_lambda_secant
            read(72,'(F30.15)') size_homelessness
            read(72,'(F30.15)') fixed_cost_to_moving
            read(72,'(F30.15)') housing_status_grid_expander
            read(72,'(F30.15)') smallest_house_size_adjuster
            read(72,'(F30.15)') largest_house_size_adjuster
            read(72,'(F30.15)') previous_gap_smallest_house_size
            read(72,'(F30.15)') previous_gap_largest_house_size
            read(72,'(I10)') have_gap_smallest_house_size
            read(72,'(I10)') have_gap_largest_house_size
            read(72,'(I10)') resumed_loop_count
            read(72,'(F30.15)') housing_price(1)
            read(72,'(F30.15)') rent(1,:)
            read(72,'(F30.15)') convexity_of_rental_company
            read(72,'(F30.15)') inheritance_amount
            read(72,'(F30.15)') lambda_m
            read(72,'(F30.15)') kappa_uem
            read(72,'(F30.15)') rho_m
            read(72,'(F30.15)') rho_d
            read(72,'(F30.15)') addiction_scalar_1
            read(72,'(F30.15)') addiction_scalar_adjuster
            read(72,'(F30.15)') previous_gap_addiction_scalar
            read(72,'(I10)') have_gap_addiction_scalar
            read(72,'(F30.15)') max_food_cost
            read(72,'(F30.15)') mu_homeless
            read(72,'(F30.15)') penalty_child_addicted
            ! A STATE FILE WRITTEN UNDER THE OLD CEILING MUST NOT SURVIVE THE NEW
            ! ONE. The banked value is 0.9, and without this clamp the solve that
            ! reads it runs a whole loop at the old penalty before the update at
            ! the end of it brings the parameter inside the cap.
            ! THE CEILING IS 0.6, NOT 0.4. delta_d is 57 per cent short at the
            ! leader and the simplex's vertex at 0.421 was SILENTLY CLAMPED to
            ! 0.4, so the point measured the base and the search learned
            ! nothing -- the same failure kappa_uem's arms had at 0.10 and 0.30.
            penalty_child_addicted=max(min(penalty_child_addicted,0.6d0),0.d0)
            read(72,'(F30.15)') penalty_child_addicted_adjuster
            read(72,'(F30.15)') previous_gap_penalty_child
            read(72,'(I10)') have_gap_penalty_child
            read(72,'(F30.15)') probability_becoming_unemployed
            read(72,'(F30.15)') probability_of_voucher_benchmark_used
            read(72,'(F30.15)') relative_share_of_addiction_1
            read(72,'(F30.15)') sd_permanent_productivity
            read(72,'(F30.15)') value_of_life
            read(72,'(F30.15)') value_of_life_at_bracket
            read(72,'(F30.15)') weight_on_child
            read(72,'(F30.15)') multiple_of_probabilities_of_employment_if_addicted
            read(72,'(F30.15)') discount_factor_adjuster
            read(72,'(F30.15)') discount_factor_lo
            read(72,'(F30.15)') discount_factor_hi
            read(72,'(F30.15)') discount_factor_lo_moment
            read(72,'(F30.15)') discount_factor_hi_moment
            read(72,'(F30.15)') previous_gap_discount_factor
            read(72,'(I10)') have_gap_discount_factor
            read(72,'(F30.15)') size_homelessness_lo
            read(72,'(F30.15)') size_homelessness_hi
            read(72,'(F30.15)') size_homelessness_lo_moment
            read(72,'(F30.15)') size_homelessness_hi_moment

            ! READ TOLERANTLY FROM HERE ON, so a state file written before these
            ! fields existed still resumes instead of being thrown away. A short
            ! file leaves them at their declared values, which is what a fresh
            ! start would use anyway, and the alternative is a version bump that
            ! discards every loop already paid for.
            read(72,'(F30.15)',iostat=state_ios_1) value_of_life_trust

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) previous_gap_value_of_life

            end if

            if (state_ios_1==0) then

                read(72,'(I10)',iostat=state_ios_1) have_gap_value_of_life

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) size_homelessness_adjuster

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) previous_gap_size_homelessness

            end if

            if (state_ios_1==0) then

                read(72,'(I10)',iostat=state_ios_1) have_gap_size_homelessness

            end if


            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) voucher_probability_adjuster

            ! Its own file, so nothing in the state record can misalign it.
            open(unit=73,file="newborn_parent_share.dat",status='old',iostat=state_ios_1)
            if (state_ios_1==0) then
                read(73,'(F30.15)',iostat=state_ios_1) newborn_parent_share
                close(73)
            end if
            if (state_ios_1/=0) then
                ! Every parent clean and housed, spread over nodes by the
                ! unconditional distribution, which is what a newborn faces
                ! before any distribution has been solved.
                newborn_parent_share=0
                newborn_parent_share(:,0,1)=unconditional_employment_probability(:)
                write(*,*) "no banked newborn parent shares, so the first distribution is"
                write(*,*) "   built with no transmission and it rebuilds from loop two"
            end if
            write(*,*) "newborn_parent_share resumed: clean housed=", sum(newborn_parent_share(:,0,1)), &
                " disordered housed=", sum(newborn_parent_share(:,1,1))


            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) previous_gap_voucher_probability

            end if

            if (state_ios_1==0) then

                read(72,'(I10)',iostat=state_ios_1) have_gap_voucher_probability

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) separation_rate_adjuster

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) previous_gap_separation_rate

            end if

            if (state_ios_1==0) then

                read(72,'(I10)',iostat=state_ios_1) have_gap_separation_rate

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) employment_multiplier_adjuster

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) previous_gap_employment_multiplier

            end if

            if (state_ios_1==0) then

                read(72,'(I10)',iostat=state_ios_1) have_gap_employment_multiplier

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) housing_status_grid_expander_adjuster

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) previous_gap_housing_status_grid_expander

            end if

            if (state_ios_1==0) then

                read(72,'(I10)',iostat=state_ios_1) have_gap_housing_status_grid_expander

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) relative_share_of_housing_adjuster

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) previous_gap_relative_share_of_housing

            end if

            if (state_ios_1==0) then

                read(72,'(I10)',iostat=state_ios_1) have_gap_relative_share_of_housing

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) labor_income_tax_rate_adjuster

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) previous_gap_labor_income_tax_rate

            end if

            if (state_ios_1==0) then

                read(72,'(I10)',iostat=state_ios_1) have_gap_labor_income_tax_rate

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) lambda_clamp

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) previous_gap_lambda_addiction

            end if

            if (state_ios_1==0) then

                read(72,'(I10)',iostat=state_ios_1) have_gap_lambda_addiction

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) relative_share_of_leisure_adjuster

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) previous_gap_relative_share_of_leisure

            end if

            if (state_ios_1==0) then

                read(72,'(I10)',iostat=state_ios_1) have_gap_relative_share_of_leisure
                read(72,'(F30.15)',iostat=state_ios_1) penalty_child_homeless
                read(72,'(F30.15)',iostat=state_ios_1) penalty_child_homeless_adjuster
                read(72,'(F30.15)',iostat=state_ios_1) previous_gap_penalty_child_homeless
                read(72,'(I10)',iostat=state_ios_1) have_gap_penalty_child_homeless
                read(72,'(F30.15)',iostat=state_ios_1) kkk_sigma_scale

            end if

            if (state_ios_1/=0) then

                write(*,*) "calibration_state.dat predates some damping state; anything missing",&
                    " starts from its declared value. The trust region",&
                    " starts at", value_of_life_trust_start, " and the homelessness adjuster at",&
                    size_homelessness_adjuster_start
                value_of_life_trust=value_of_life_trust_start
                previous_gap_value_of_life=0
                have_gap_value_of_life=0
                size_homelessness_adjuster=size_homelessness_adjuster_start
                previous_gap_size_homelessness=0
                have_gap_size_homelessness=0

            end if

            ! AND CLAMP WHAT WAS READ, because a checkpoint written before this
            ! floor existed carries the degenerate zero and would reinstate it
            ! on the next resume, silently, having just been told the floor is
            ! 0.01. The banked state at the time this was written held exactly
            ! that.
            if (size_homelessness<size_homelessness_floor) then
                write(*,*) "size_homelessness read as", size_homelessness,&
                    " which prices the street at minus infinity; raised to",&
                    size_homelessness_floor
                size_homelessness=size_homelessness_floor
            end if

        close(72)

        ! CLAMP THETA AND b INTO THEIR BAND ON RESUME. The bounds in the update
        ! rules only bite when an update runs, so a resumed state carrying the
        ! old out of band values would spend a whole loop on them first. A state
        ! written before the band existed carries theta at 0.667 and b at 0.99.
        if ((relative_share_of_addiction_1<theta_lo) .OR. &
            (relative_share_of_addiction_1>theta_hi)) then

            write(*,*) "theta out of band on resume:", relative_share_of_addiction_1, &
                " clamped into [", theta_lo, ",", theta_hi, "]"
            relative_share_of_addiction_1=max(min(relative_share_of_addiction_1,theta_hi),theta_lo)

        end if

        if ((addiction_scalar_1<b_lo) .OR. (addiction_scalar_1>b_hi)) then

            write(*,*) "b out of band on resume:", addiction_scalar_1, &
                " clamped into [", b_lo, ",", b_hi, "]"
            addiction_scalar_1=max(min(addiction_scalar_1,b_hi),b_lo)

        end if

        ! THE HANDOVER IS NOT READ HERE ANY MORE, AND MOVING IT WAS THE
        ! WHOLE BUG. It used to sit at the foot of this subroutine, which has
        ! TWO early returns above it: one when calibration_state.dat does not
        ! exist and one when it is not version 3. A container that had never
        ! run the model -- which is every freshly cloned worker, because the
        ! state file is not in the repository -- took the first of those and
        ! returned before the handover was ever opened. The run then solved at
        ! the values in the declarations, printed a full moments block, and
        ! looked in every respect like a measured point. Three archived points
        ! with different vectors re-ran to the same loss to four decimals with
        ! no HANDOVER line anywhere in their logs; the parameters had never
        ! reached the model. It is now apply_param_handover(), called by the
        ! caller straight after this returns, so it runs on both paths.

        write(*,*) "resumed from calibration_state.dat, written after loop", resumed_loop_count
        write(*,*) "relative_share_of_addiction_1=", relative_share_of_addiction_1
        write(*,*) "addiction_scalar_1=", addiction_scalar_1
        write(*,*) "lambda_addiction=", lambda_addiction
        write(*,*) "largest_house_size=", largest_house_size
        write(*,*) "smallest_rental_relative_to_lowest_income=", smallest_rental_relative_to_lowest_income
        write(*,*) "lambda_m=", lambda_m
        write(*,*) "kappa_uem=", kappa_uem
        write(*,*) "rho_m=", rho_m
        write(*,*) "rho_d=", rho_d

    end subroutine

    subroutine apply_param_handover()

        ! THE ONE SHOT SEED, SPLIT OUT OF read_calibration_state SO THAT IT RUNS
        ! WHETHER OR NOT THERE IS A STATE FILE TO RESUME FROM. See the note at
        ! the point it was taken from. Everything below is unchanged.

        use Global_Vars

        implicit none

        ! THE HANDOVER FILE, AND IT CONSUMES ITSELF.
        !
        ! Putting a value chosen outside the loop back into it means putting it
        ! into calibration_state.dat, which is written positionally: 128 of its
        ! lines differ between two runs, so no diff identifies a parameter's
        ! offset and it cannot be edited by hand. The model takes the value from
        ! a file instead, AFTER the state is read, and deletes the file as it
        ! does. One pass later the state carries it like any other parameter and
        ! the loop owns it again; a standing override would PIN a parameter
        ! rather than seed it, which is the opposite of what a handover is for.
        !
        ! One "name value" pair a line. Unknown names are reported and ignored
        ! rather than silently dropped, because a typo in a handover is
        ! indistinguishable from a parameter that would not move.
        open(unit=79,file="PARAM_HANDOVER.txt",action='read',status='old',iostat=handover_status)
        if (handover_status==0) then

            do

                read(79,*,iostat=handover_status) handover_name, handover_value
                if (handover_status/=0) exit

                select case (trim(handover_name))

                case ("addiction_scalar_1")
                    write(*,*) "HANDOVER addiction_scalar_1:", addiction_scalar_1, "->", handover_value
                    ! A SILENT CLAMP MISLABELS A POINT. The point's identity is
                    ! the md5 of the vector REQUESTED, so if this clamp bites,
                    ! the file is named for a value the model never ran and the
                    ! archive quietly contains a lie. It has never bitten, and
                    ! the floor below it is now 1e-30, but it must say so if it
                    ! ever does.
                    if (handover_value>b_hi .or. handover_value<b_lo) then
                        write(*,*) "HANDOVER CLAMPED addiction_scalar_1: requested",&
                            handover_value, "outside [", b_lo, ",", b_hi, "] -- THIS POINT IS MISLABELLED"
                    end if
                    addiction_scalar_1=max(min(handover_value,b_hi),b_lo)

                case ("persistent_income_risk")
                    write(*,*) "HANDOVER persistent_income_risk:", persistent_income_risk, "->", handover_value
                    persistent_income_risk=nint(max(min(handover_value,1.d0),0.d0))
                case ("rho_productivity")
                    write(*,*) "HANDOVER rho_productivity:", rho_productivity, "->", handover_value
                    rho_productivity=max(min(handover_value,0.999d0),0.d0)
                case ("endowment_is_a_transfer")
                    write(*,*) "HANDOVER endowment_is_a_transfer:", endowment_is_a_transfer, "->", handover_value
                    endowment_is_a_transfer=nint(max(min(handover_value,1.d0),0.d0))
                case ("ssi_floor_takeup")
                    write(*,*) "HANDOVER ssi_floor_takeup:", ssi_floor_takeup, "->", handover_value
                    ssi_floor_takeup=max(min(handover_value,1.d0),0.d0)
                ! THE FLOOR'S LEVEL IS SETTABLE, and until now only its TAKE-UP
                ! was. The author, 3 September: *"maybe the floor is too low
                ! still if so many old are homeless.... Because if the ssi was
                ! high, no old would be homeless"*.
                !
                ! WHY THE TAKE-UP DIAL COULD NEVER TEST THAT. The benefit is
                ! max(PIA_i, takeup*ssi_floor_level) and takeup is clamped to
                ! [0,1], so the effective floor could never exceed 0.1774. On
                ! the grid this model runs, node 4's own PIA is 0.30015 and node
                ! 4 carries 39.8 per cent of the mass, so the floor was
                ! structurally incapable of reaching the households that are
                ! actually homeless in retirement -- it binds only on nodes 1 to
                ! 3, and node 3's gain at full take-up is 7 per cent. That is
                ! why 0.5 to 1.0 moved h_share5 by 0.005 in the wrong direction.
                !
                ! 0.1774 IS THE REAL BENEFIT RATE -- $943 a month in 2024 over
                ! the average wage index -- so a CALIBRATED value above it is a
                ! change to the policy environment and not a free parameter. It
                ! is made settable here so the mechanism can be MEASURED; what
                ! value the benchmark carries is the author's call.
                case ("ssi_floor_level")
                    write(*,*) "HANDOVER ssi_floor_level:", ssi_floor_level, "->", handover_value
                    ssi_floor_level=max(min(handover_value,5.d0),0.d0)
                case ("use_pia_formula")
                    write(*,*) "HANDOVER use_pia_formula:", use_pia_formula, "->", handover_value
                    use_pia_formula=nint(max(min(handover_value,1.d0),0.d0))
                case ("use_unemployment_by_productivity")
                    write(*,*) "HANDOVER use_unemployment_by_productivity:",&
                        use_unemployment_by_productivity, "->", handover_value
                    use_unemployment_by_productivity=nint(max(min(handover_value,1.d0),0.d0))
                ! THE PRODUCTIVITY PROCESS ITSELF. 1 is the quantile grid,
                ! 0 is the author's KKK_process. Nothing below it is shared:
                ! y_grid_kappa and bottom_productivity_level are inert under
                ! KKK, and s_deviation_bottom, the two persistences and the two
                ! innovation sds are inert under the quantile grid.
                case ("fixed_productivity")
                    write(*,*) "HANDOVER fixed_productivity:", fixed_productivity, "->", handover_value
                    fixed_productivity=max(min(nint(handover_value),1),0)

                ! THE KKK GRID'S WIDTH AT THE BOTTOM, which is what
                ! y_grid_kappa is on the quantile grid: the instrument for how
                ! much mass sits on the node too poor to rent. Widening it
                ! pushes mass off the bottom node -- 3.00 gives 0.621 per cent,
                ! 3.25 gives 0.318, 3.50 gives 0.155 -- against a design target
                ! of 0.198 from the homelessness bands.
                ! THE DISPERSION INSTRUMENT UNDER KKK, and the ONE number that
                ! reconciles the process with the SCF bottom half share. It
                ! multiplies both innovation sds, so the ratio between them --
                ! which is what sets the fanning out -- is untouched.
                case ("kkk_sigma_scale")
                    write(*,*) "HANDOVER kkk_sigma_scale:", kkk_sigma_scale, "->", handover_value
                    kkk_sigma_scale=max(min(handover_value,10.d0),0.1d0)

                case ("kkk_s_deviation_bottom")
                    write(*,*) "HANDOVER kkk_s_deviation_bottom:",&
                        kkk_s_deviation_bottom, "->", handover_value
                    kkk_s_deviation_bottom=max(min(handover_value,6.d0),1.d0)

                case ("kkk_s_deviation_top")
                    write(*,*) "HANDOVER kkk_s_deviation_top:",&
                        kkk_s_deviation_top, "->", handover_value
                    kkk_s_deviation_top=max(min(handover_value,6.d0),1.d0)

                ! THE FOUR NUMBERS OF THE TWO COMPONENT PROCESS. The defaults
                ! are the author's own: 0.5 and 0.309 for the fixed effect,
                ! 0.9 and 0.2 for the persistent component, which are the
                ! Guvenen, Karahan, Ozkan and Song "use it or lose it" values.
                ! They are here so a point file can move them, not because
                ! anything says they should be moved.
                case ("persistence_fixed_employment_newborn")
                    write(*,*) "HANDOVER persistence_fixed_employment_newborn:",&
                        persistence_fixed_employment_newborn, "->", handover_value
                    persistence_fixed_employment_newborn=max(min(handover_value,0.999d0),0.d0)

                case ("sd_fixed_employment_newborn")
                    write(*,*) "HANDOVER sd_fixed_employment_newborn:",&
                        sd_fixed_employment_newborn, "->", handover_value
                    sd_fixed_employment_newborn=max(min(handover_value,3.d0),10.d0**(-3))

                case ("persistence_employment_surviving")
                    write(*,*) "HANDOVER persistence_employment_surviving:",&
                        persistence_employment_surviving, "->", handover_value
                    persistence_employment_surviving=max(min(handover_value,0.999d0),0.d0)

                case ("sd_employment_surviving")
                    write(*,*) "HANDOVER sd_employment_surviving:",&
                        sd_employment_surviving, "->", handover_value
                    sd_employment_surviving=max(min(handover_value,3.d0),10.d0**(-3))

                case ("y_grid_kappa")
                    write(*,*) "HANDOVER y_grid_kappa:", y_grid_kappa, "->", handover_value
                    y_grid_kappa=max(min(handover_value,8.d0),1.d0)
                case ("bottom_productivity_level")
                    write(*,*) "HANDOVER bottom_productivity_level:", bottom_productivity_level, "->", handover_value
                    bottom_productivity_level=max(min(handover_value,1.d0),0.d0)
                case ("size_homelessness")
                    write(*,*) "HANDOVER size_homelessness:", size_homelessness, "->", handover_value
                    size_homelessness=max(min(handover_value,0.9d0),size_homelessness_floor)

                case ("smallest_rental_relative_to_lowest_income")
                    ! BOTH, because the ratio is what the bracket moves and the
                    ! size is what the model prices, and the size is only rebuilt
                    ! from the ratio before the first loop. A resumed run that
                    ! set one and not the other would carry the old dwelling.
                    write(*,*) "HANDOVER smallest_rental:",&
                        smallest_rental_relative_to_lowest_income, "->", handover_value
                    smallest_rental_relative_to_lowest_income=handover_value
                    smallest_house_size=handover_value

                case ("housing_status_grid_expander")
                    write(*,*) "HANDOVER housing_status_grid_expander:",&
                        housing_status_grid_expander, "->", handover_value
                    housing_status_grid_expander=handover_value

                case ("lambda_addiction")
                    write(*,*) "HANDOVER lambda_addiction:", lambda_addiction, "->", handover_value
                    lambda_addiction=handover_value

                case ("largest_house_size")
                    write(*,*) "HANDOVER largest_house_size:", largest_house_size, "->", handover_value
                    largest_house_size=handover_value

                case ("lambda_m")
                    write(*,*) "HANDOVER lambda_m:", lambda_m, "->", handover_value
                    lambda_m=max(min(handover_value,0.5d0),lambda_m_floor)

                case ("smi_onset_level")
                    write(*,*) "HANDOVER smi_onset_level:", smi_onset_level, "->", handover_value
                    smi_onset_level=max(min(handover_value,1.d0),10.d0**(-8))

                case ("zeta_DI")
                    write(*,*) "HANDOVER zeta_DI:", zeta_DI, "->", handover_value
                    zeta_DI=max(min(handover_value,1.d0),0.d0)

                ! psi AND ITS CAP. Bounded at 1 and at 5 times average income
                ! respectively: psi above one would pay a household more out of
                ! work than in it, which inverts the participation margin the
                ! model is built on, and a cap of five times average income is
                ! already far above any real benefit schedule.
                case ("replacement_rate_ui")
                    write(*,*) "HANDOVER replacement_rate_ui:", &
                        replacement_rate_ui, "->", handover_value
                    replacement_rate_ui=max(min(handover_value,1.d0),0.d0)

                case ("max_ui_as_perc_of_avg_inc")
                    write(*,*) "HANDOVER max_ui_as_perc_of_avg_inc:", &
                        max_ui_as_perc_of_avg_inc, "->", handover_value
                    max_ui_as_perc_of_avg_inc=max(min(handover_value,5.d0),0.d0)

                case ("merge_from_node")
                    write(*,*) "HANDOVER merge_from_node:", &
                        merge_from_node, "->", handover_value
                    merge_from_node=max(min(handover_value,4.d0),1.d0)

                case ("merge_bottom_nodes")
                    write(*,*) "HANDOVER merge_bottom_nodes:", &
                        merge_bottom_nodes, "->", handover_value
                    merge_bottom_nodes=max(min(handover_value,4.d0),1.d0)
                case ("kappa_find_smi")

                    write(*,*) "HANDOVER kappa_find_smi:", &
                        kappa_find_smi, "->", handover_value
                    kappa_find_smi=max(min(handover_value,100.d0),1.d0)

                case ("kappa_uem")
                    write(*,*) "HANDOVER kappa_uem:", kappa_uem, "->", handover_value
                    kappa_uem=max(min(handover_value,100.d0),1.d0)

                case ("weight_on_child")
                    write(*,*) "HANDOVER weight_on_child:", weight_on_child, "->", handover_value
                    weight_on_child=max(min(handover_value,1.d0),0.d0)

                ! THE LABOUR MARKET COST OF THE STREET. See the declaration for
                ! the arithmetic that makes this the instrument for the employed
                ! share of the homeless. The floor is zero, which is no penalty
                ! at all; the ceiling is 20, well past the 3.8 the steady state
                ! formula asks for, so the bracket is not clipped before it gets
                ! there.
                case ("increased_prob_if_homeless")
                    write(*,*) "HANDOVER increased_prob_if_homeless:", &
                        increased_prob_if_homeless, "->", handover_value
                    ! THE CEILING IS BELOW ONE NOW, AND THAT IS NOT A TASTE.
                    ! The job finding rate is multiplied by (1-x) rather than
                    ! divided by (1+x), so anything at or above one makes it
                    ! zero or NEGATIVE -- a negative probability that the
                    ! process verifier would catch only after a wasted solve.
                    ! The old ceiling of 20 was safe under division and is not
                    ! under multiplication.
                    increased_prob_if_homeless=max(min(handover_value,0.95d0),0.d0)

                case ("consumption_penalty_homeless")
                    write(*,*) "HANDOVER consumption_penalty_homeless:",&
                        consumption_penalty_homeless, "->", handover_value
                    ! CEILING BELOW ONE for the same reason as the line above:
                    ! consumption enters as c**((1-sigma)*(1-gamma)), so a scale
                    ! factor of zero or below is not a consumption level.
                    consumption_penalty_homeless=max(min(handover_value,0.95d0),0.d0)

                case ("extra_job_loss_if_homeless")
                    write(*,*) "HANDOVER extra_job_loss_if_homeless:",&
                        extra_job_loss_if_homeless, "->", handover_value
                    ! NO LOW CEILING HERE. This side is bounded by the separation
                    ! probability reaching one, which the clamp in
                    ! create_unemployment_process enforces, not by an algebraic
                    ! sign condition. At the calibrated separation rate of 0.0136
                    ! the clamp binds around 72.
                    extra_job_loss_if_homeless=max(min(handover_value,200.d0),0.d0)

                case ("homeless_job_penalty_pp")
                    write(*,*) "HANDOVER homeless_job_penalty_pp:",&
                        homeless_job_penalty_pp, "->", handover_value
                    ! Above probability_becoming_employed the finding rate is
                    ! already floored at zero and delta only raises separations,
                    ! so the useful range ends there; one is the hard bound.
                    homeless_job_penalty_pp=max(min(handover_value,1.d0),0.d0)

                ! THE EARNINGS PENALTY OF A SUBSTANCE USE DISORDER. It enters as
                ! rho_d**(sud*include_rho_d), so it is a multiplier on the wage
                ! of a household with the disorder and one means no penalty. The
                ! floor is 0.05 rather than zero because zero earnings for every
                ! addict is a corner, not a calibration, and the ceiling is one
                ! because a disorder that RAISES the wage is not on the table.
                case ("rho_d")
                    write(*,*) "HANDOVER rho_d:", rho_d, "->", handover_value
                    rho_d=max(min(handover_value,1.d0),0.05d0)

                ! rho_m, WHICH HAD NO HANDOVER AT ALL. Same ceiling and the same
                ! reason as rho_d: an illness that RAISES the wage is not on the
                ! table. The author's instruction of 2 September is that both sit
                ! at one and are not lowered, so this exists to make that
                ! settable and visible in a point file rather than buried in a
                ! declaration.
                ! THE UNSECURED BORROWING PARAMETERS, so the rate and the limit
                ! can be revisited without another model change. The author named
                ! 5.5 per cent after quoting a figure that was a debt-to-income
                ! QUANTITY rather than a rate, so this one in particular is
                ! expected to move.
                case ("include_unsecured_borrowing")
                    write(*,*) "HANDOVER include_unsecured_borrowing:", &
                        include_unsecured_borrowing, "->", handover_value
                    include_unsecured_borrowing=max(min(nint(handover_value),1),0)

                case ("unsecured_borrowing_limit")
                    write(*,*) "HANDOVER unsecured_borrowing_limit:", &
                        unsecured_borrowing_limit, "->", handover_value
                    unsecured_borrowing_limit=max(min(handover_value,3.d0),0.d0)

                case ("unsecured_borrowing_rate")
                    write(*,*) "HANDOVER unsecured_borrowing_rate:", &
                        unsecured_borrowing_rate, "->", handover_value
                    unsecured_borrowing_rate=max(min(handover_value,0.40d0),0.d0)

                case ("restrict_borrowing_to_impatient")
                    write(*,*) "HANDOVER restrict_borrowing_to_impatient:", &
                        restrict_borrowing_to_impatient, "->", handover_value
                    restrict_borrowing_to_impatient=max(min(nint(handover_value),1),0)

                case ("rho_m")
                    write(*,*) "HANDOVER rho_m:", rho_m, "->", handover_value
                    rho_m=max(min(handover_value,1.d0),0.05d0)

                ! THE CHILD GAP SWITCH, for omega_c in the final round.
                case ("measure_child_gap")
                    write(*,*) "HANDOVER measure_child_gap:", &
                        measure_child_gap, "->", handover_value
                    measure_child_gap=max(min(nint(handover_value),1),0)

                ! THE SUD MORTALITY LEVEL, WHICH IS SETTABLE BUT WAS NOT
                ! HANDABLE. It is assigned at 8, the midpoint of the 6 to 10
                ! range the literature gives for all cause standardised
                ! mortality ratios in opioid use disorder, and it is the knob on
                ! what the disorder COSTS a household: survival is raised to the
                ! power of the multiplier, so the whole continuation value is
                ! what a using household puts at risk. That makes it the natural
                ! instrument for who is willing to use, and therefore for the
                ! average income of users, which the model puts at 0.31 of
                ! average against 0.74 in NSDUH.
                !
                ! The clamp is wide on purpose, 1 to 30, rather than the
                ! literature's 6 to 10. A search that cannot leave the range
                ! cannot report that the range is where the answer is not, and
                ! that is a finding worth being able to reach. 1 is no excess
                ! mortality at all, which is the floor the specification allows.
                !
                ! No rebuild is needed here: apply_param_handover runs before
                ! initialize_variables_and_grids, which is the one place
                ! build_mortality_multipliers is called from and where
                ! survival_probability is built out of it.
                case ("kappa_phi_d_level")
                    write(*,*) "HANDOVER kappa_phi_d_level:", kappa_phi_d_level, "->", handover_value
                    kappa_phi_d_level=max(min(handover_value,30.d0),1.d0)

                ! THE LAST TWO INTERNALLY CALIBRATED PARAMETERS THAT COULD NOT
                ! BE HANDED IN. The paper calibrates twenty four parameters
                ! internally; the search could set twenty one of them, so the
                ! food stamp ceiling and the recovery ratio were being carried
                ! at whatever the declaration said while their moments were
                ! counted as misses. A parameter that owns a moment and cannot
                ! be set is a parameter that cannot be calibrated.
                case ("max_food_cost")
                    write(*,*) "HANDOVER max_food_cost:", max_food_cost, "->", handover_value
                    max_food_cost=max(handover_value,0.d0)

                case ("mu_homeless")
                    write(*,*) "HANDOVER mu_homeless:", mu_homeless, "->", handover_value
                    mu_homeless=max(min(handover_value,1.d0),0.d0)

                ! THE INSTRUMENTS THAT RAN AWAY AT THE CORNER, so a good
                ! starting point can be handed in rather than hand edited into a
                ! positional checkpoint. Measured against their own declared
                ! values after loops run at 75 per cent participation:
                ! lambda 33x, the treatment cost 106x, kappa_uem 23x and the
                ! employment multiplier 6x. A one per cent per loop trust region
                ! only makes sense from a sensible start, and these were not one.
                case ("money_cost_of_treatment")
                    write(*,*) "HANDOVER money_cost_of_treatment:", money_cost_of_treatment, "->", handover_value
                    money_cost_of_treatment=max(handover_value,0.d0)

                case ("utility_cost_of_treatment")
                    write(*,*) "HANDOVER utility_cost_of_treatment:",&
                        utility_cost_of_treatment, "->", handover_value
                    utility_cost_of_treatment=max(min(handover_value,10.d0),0.d0)

                case ("probability_becoming_unemployed")
                    write(*,*) "HANDOVER probability_becoming_unemployed:",&
                        probability_becoming_unemployed, "->", handover_value
                    probability_becoming_unemployed=&
                        max(min(handover_value,1.d0),10.d0**(-6))

                case ("multiple_of_probabilities_of_employment_if_addicted")
                    write(*,*) "HANDOVER employment multiplier:",&
                        multiple_of_probabilities_of_employment_if_addicted,&
                        "->", handover_value
                    multiple_of_probabilities_of_employment_if_addicted=&
                        max(min(handover_value,20.d0),1.d0)

                case ("multiple_find_if_addicted")
                    write(*,*) "HANDOVER multiple_find_if_addicted:",&
                        multiple_find_if_addicted, "->", handover_value
                    multiple_find_if_addicted=&
                        max(min(handover_value,100.d0),1.d0)

                case ("financial_grid_expander_positive")
                    write(*,*) "HANDOVER financial_grid_expander_positive:",&
                        financial_grid_expander_positive, "->", handover_value
                    financial_grid_expander_positive=max(min(handover_value,6.d0),1.d0)
                case ("rung_ratio_h3")
                    write(*,*) "HANDOVER rung_ratio_h3:", rung_ratio_h3, "->", handover_value
                    rung_ratio_h3=max(min(handover_value,6.d0),1.01d0)
                case ("rung_ratio_h4")
                    write(*,*) "HANDOVER rung_ratio_h4:", rung_ratio_h4, "->", handover_value
                    rung_ratio_h4=max(min(handover_value,9.d0),1.02d0)
                case ("newborn_endowment_scale")
                    write(*,*) "HANDOVER newborn_endowment_scale:",&
                        newborn_endowment_scale, "->", handover_value
                    newborn_endowment_scale=max(min(handover_value,50.d0),0.d0)

                case ("value_of_life")
                    write(*,*) "HANDOVER value_of_life:", value_of_life, "->", handover_value
                    value_of_life=max(min(handover_value,10.d0**(4)),10.d0**(-2))

                case ("penalty_child_addicted")
                    write(*,*) "HANDOVER penalty_child_addicted:",&
                        penalty_child_addicted, "->", handover_value
                    penalty_child_addicted=max(min(handover_value,0.6d0),0.d0)

                ! BLOCK A, SO IT CAN BE PINNED WHILE A LATER BLOCK IS SWEPT.
                ! Income, hours, wealth and the tax rate are upstream of every
                ! other moment, and while block C was being swept they were
                ! running at whatever the corner had left them: labour supply
                ! 0.4567 against 0.400, wealth over output 4.23 against 3. A
                ! block cannot be held if the handover cannot name it.
                case ("financial_grid_expander_negative")
                    write(*,*) "HANDOVER financial_grid_expander_negative:",&
                        financial_grid_expander_negative, "->", handover_value
                    financial_grid_expander_negative=min(max(handover_value,1.0d0),6.0d0)

                case ("discount_factor")
                    write(*,*) "HANDOVER discount_factor:", discount_factor, "->", handover_value
                    discount_factor=min(max(handover_value,0.5d0),1.05d0)

                case ("max_age_to_choose_homelessness")
                    write(*,*) "HANDOVER max_age_to_choose_homelessness:",&
                        max_age_to_choose_homelessness, "->", handover_value
                    max_age_to_choose_homelessness=&
                        max(min(nint(handover_value),life_span),1)

                case ("addiction_onset_base")
                    write(*,*) "HANDOVER addiction_onset_base:",&
                        addiction_onset_base, "->", handover_value
                    addiction_onset_base=max(min(handover_value,1.d0),0.d0)

                case ("rr_homeless_old_level")
                    write(*,*) "HANDOVER rr_homeless_old_level:",&
                        rr_homeless_old_level, "->", handover_value
                    rr_homeless_old_level=max(min(handover_value,50.d0),0.d0)

                case ("rr_homeless_hold_age")
                    write(*,*) "HANDOVER rr_homeless_hold_age:",&
                        rr_homeless_hold_age, "->", handover_value
                    rr_homeless_hold_age=max(min(nint(handover_value),85),0)

                case ("homeless_death_risk_flat_in_age")
                    write(*,*) "HANDOVER homeless_death_risk_flat_in_age:",&
                        homeless_death_risk_flat_in_age, "->", handover_value
                    homeless_death_risk_flat_in_age=max(min(nint(handover_value),2),0)

                case ("homeless_excess_death_risk")
                    write(*,*) "HANDOVER homeless_excess_death_risk:",&
                        homeless_excess_death_risk, "->", handover_value
                    homeless_excess_death_risk=max(min(handover_value,0.5d0),0.d0)

                case ("number_of_beta_types")
                    write(*,*) "HANDOVER number_of_beta_types:",&
                        number_of_beta_types, "->", handover_value
                    number_of_beta_types=max(min(nint(handover_value),2),1)

                case ("discount_factor_impatient")
                    write(*,*) "HANDOVER discount_factor_impatient:",&
                        discount_factor_impatient, "->", handover_value
                    discount_factor_impatient=max(min(handover_value,0.999d0),0.5d0)

                case ("relative_share_of_leisure")
                    write(*,*) "HANDOVER relative_share_of_leisure:",&
                        relative_share_of_leisure, "->", handover_value
                    relative_share_of_leisure=min(max(handover_value,0.01d0),1000.d0)

                case ("labor_income_tax_rate")
                    write(*,*) "HANDOVER labor_income_tax_rate:",&
                        labor_income_tax_rate, "->", handover_value
                    labor_income_tax_rate=max(min(handover_value,2.d0),0.d0)

                case ("relative_share_of_housing")
                    write(*,*) "HANDOVER relative_share_of_housing:",&
                        relative_share_of_housing, "->", handover_value
                    relative_share_of_housing=min(max(handover_value,0.01d0),0.9d0)

                case ("sd_permanent_productivity")
                    write(*,*) "HANDOVER sd_permanent_productivity:",&
                        sd_permanent_productivity, "->", handover_value
                    sd_permanent_productivity=max(min(handover_value,3.d0),10.d0**(-2))

                case ("penalty_child_homeless")
                    write(*,*) "HANDOVER penalty_child_homeless:",&
                        penalty_child_homeless, "->", handover_value
                    penalty_child_homeless=max(min(handover_value,0.6d0),0.d0)

                case ("probability_of_voucher_benchmark_used")
                    write(*,*) "HANDOVER voucher probability:",&
                        probability_of_voucher_benchmark_used, "->", handover_value
                    probability_of_voucher_benchmark_used=&
                        max(min(handover_value,1.d0),10.d0**(-5))

                case ("relative_share_of_addiction_1")
                    write(*,*) "HANDOVER relative_share_of_addiction_1:",&
                        relative_share_of_addiction_1, "->", handover_value
                    relative_share_of_addiction_1=max(min(handover_value,theta_hi),theta_lo)
                    call apply_gamma_tie()

                case default
                    write(*,*) "HANDOVER IGNORED, unknown name: ", trim(handover_name)

                end select

            end do

            close(79,status='delete')

            ! BANK THE HANDOVER BEFORE THE FIRST SOLVE, OR IT CAN BE LOST. The
            ! file is deleted as it is read, and calibration_state.dat is only
            ! rewritten at the END of a loop. A run that is killed part way
            ! through its first solve therefore loses the handover entirely: the
            ! file is gone, the state still holds the old value, and the next
            ! launch resumes at the value the handover was meant to replace with
            ! nothing anywhere saying so. That happened to h_2, which was handed
            ! 0.0015, killed mid solve, and came back at 0.0048.
            call write_calibration_state()
            write(*,*) "handover banked into calibration_state.dat before the first solve"

        end if

    end subroutine


    subroutine write_calibration_distribution()

    ! THE DISTRIBUTION IS THE OTHER HALF OF A WARM START, and it is the
    ! expensive half.
    !
    ! A resumed run that recovers the parameters still pays 655 sweeps to
    ! rebuild the distribution from the age one cross section, and those
    ! sweeps are most of a loop. The converged distribution of the last
    ! completed loop is a far better guess for the next parameter vector than
    ! a freshly initialised one, because consecutive vectors differ by a
    ! damped step.
    !
    ! Written on the same schedule as the parameters and to a temporary first,
    ! for the same reason. It is a large file, so it is written once per loop
    ! and not once per sweep.

    use Global_Vars

    implicit none

    integer :: dist_index_1
    character*1 :: string_used_1

    do dist_index_1=1,2

        write(string_used_1,'(i1)') dist_index_1

        open(unit=73,file="calibration_distribution"//trim(string_used_1)//".tmp",&
            action='write',status='replace')
            write(73,'(F30.28)') distribution_stationary(dist_index_1)%vector_transition_real(1,:,:,:,:,:,:)
        close(73)

        call rename("calibration_distribution"//trim(string_used_1)//".tmp",&
            "calibration_distribution"//trim(string_used_1)//".dat")

    end do

    ! THE SHAPE STAMP, AND WHY THE WARM START IS WORTHLESS WITHOUT IT. The two
    ! files are a bare list of numbers with nothing in them that says what shape
    ! they were written at, and the reader fills an array of whatever shape the
    ! build it is running in happens to have. So a run at a different asset grid
    ! reads them anyway. If the new array is SMALLER the read succeeds and
    ! silently loads a distribution that is the first fraction of each slice of
    ! another one, which is not a distribution: an asset grid cut from forty
    ! positive points to twenty five loaded a warm start summing to 45.7 against
    ! the 51.4 it was written with, took 2445 sweeps to grind back from it, and
    ! the moments it then reported were compared against another build's and read
    ! as evidence about the grid. They were evidence about this bug. If the new
    ! array is LARGER the read hits end of file and the run dies outright, which
    ! is the same bug wearing a louder coat.
    !
    ! So the count of elements is written beside them, and a warm start whose
    ! count does not match is refused.
    open(unit=73,file="calibration_distribution_shape.tmp",action='write',status='replace')
        write(73,*) size(distribution_stationary(1)%vector_transition_real(1,:,:,:,:,:,:))
    close(73)

    call rename("calibration_distribution_shape.tmp","calibration_distribution_shape.dat")

    end subroutine

    subroutine read_calibration_distribution()

    ! Loads the warm start if it is there, and records that it did, because the
    ! caller has to skip initialize_feasible_distribution when it did. Both
    ! files have to be present: half a warm start is two distributions from
    ! different loops, which is not a distribution of anything.

    use Global_Vars

    implicit none

    integer :: dist_index_1,stamped_size_1,actual_size_1
    logical :: exists_1,exists_2,exists_3
    character*1 :: string_used_1

    have_warm_distribution=0

    inquire(file="calibration_distribution1.dat",exist=exists_1)
    inquire(file="calibration_distribution2.dat",exist=exists_2)
    inquire(file="calibration_distribution_shape.dat",exist=exists_3)

    if (.NOT. (exists_1 .AND. exists_2)) then

        write(*,*) "no warm start distribution, initialising from the age one cross section"

        return

    end if

    ! THE SHAPE HAS TO MATCH. See write_calibration_distribution for what
    ! happens when it does not, which is that nothing happens: the read
    ! succeeds and the distribution is wrong. An unstamped pair is refused
    ! rather than trusted, because a pair from before the stamp existed cannot
    ! be told apart from a pair written at another grid.
    actual_size_1=size(distribution_stationary(1)%vector_transition_real(1,:,:,:,:,:,:))

    if (.NOT. exists_3) then

        write(*,*) "WARM START REFUSED: the distribution files carry no shape stamp, &
            &so the grid they were written at is unknown. Initialising from the age &
            &one cross section."

        return

    end if

    open(unit=74,file="calibration_distribution_shape.dat",action='read')
        read(74,*) stamped_size_1
    close(74)

    if (stamped_size_1/=actual_size_1) then

        write(*,*) "WARM START REFUSED: written at", stamped_size_1, &
            "elements, this build wants", actual_size_1, &
            ". Initialising from the age one cross section."

        return

    end if

    do dist_index_1=1,2

        write(string_used_1,'(i1)') dist_index_1

        open(unit=74,file="calibration_distribution"//trim(string_used_1)//".dat",action='read')
            read(74,'(F30.28)') distribution_stationary(dist_index_1)%vector_transition_real(1,:,:,:,:,:,:)
        close(74)

        distribution_guess(dist_index_1)%vector_transition_real(1,:,:,:,:,:,:)=&
            distribution_stationary(dist_index_1)%vector_transition_real(1,:,:,:,:,:,:)

    end do

    have_warm_distribution=1

    write(*,*) "warm start distribution loaded, sum=", &
        sum(distribution_guess(1)%vector_transition_real(1,:,:,:,:,:,:))+&
        sum(distribution_guess(2)%vector_transition_real(1,:,:,:,:,:,:))

    end subroutine

    subroutine calibrating_model()
    
        use Global_Vars
        
        implicit none
        
        logical :: file_exists
        
        real(8) :: mass_at_top_financial,a,b,c,d
        real(8) :: mean_drug_quantity_1,onset_at_mean_1,onset_step_1,treatment_step_1,&
            separation_step_1,b_move_1,lambda_move_1
        character*1 :: string_used
        integer :: last_period_of_life,addiction_index
        ! Its own name and not the file's shared i: the projection below runs
        ! inside the beta-type pass loop, where i is live.
        integer :: i_beta_floor
        integer, dimension(1) :: index_drug_1
                                
        simulation_ended=0

        ! Pick up where a killed run left off, if it left anything.
        call read_calibration_state()

        ! AND THEN THE HANDOVER, UNCONDITIONALLY. This call is the fix for the
        ! defect described in apply_param_handover: the seed must be applied on
        ! a first run in a fresh container exactly as it is on a resume, or a
        ! point measured on such a container is a point measured at the
        ! declared values with the vector it was asked for thrown away.
        call apply_param_handover()

        ! THE SMOOTH HAZARD NEEDS THE TABULATED EXPECTATION. With the hoist off
        ! the two continuations are never formed separately, so there is nothing
        ! to price the drug risk against and the household would face a hazard
        ! rising in v that it does not respond to, which is the defect this was
        ! meant to fix wearing a different hat. Stop rather than run: a model
        ! that still produces numbers is exactly how this would go unnoticed.
        if ((smooth_addiction_hazard==1) .AND. (hoist_expectation==0)) then

            write(*,*) "smooth_addiction_hazard needs hoist_expectation=1. stopping."
            stop

        end if

        call cpu_time(simulation_start_time)
        
        lump_sum_transfer(1)=0
        
        model_average_owner_occupied_unit_size(1)=calibrated_stationary_housing_price*&
            average_owner_occupied_house_size_calibrated
            
        model_average_rental_unit_size(1)=0.116

        loop_count=0  
        
        model_bequests(1)=2.5238247842094039
        
        model_drug_threshold(1)=drug_threshold_guess
        model_average_income(1)=average_labor_income_calibrated
        model_average_income_plus_assets(1)=average_labor_income_calibrated
        model_average_income_plus_all_assets(1)=average_labor_income_calibrated
        model_average_labour_income(1)=average_labor_income_calibrated
        call set_newborn_age_transfer(1)
        call set_renter_floor(1)
        model_average_labour_income_by_employment(1,:)=average_labor_income_by_employment_calibrated
        median_income(1)=median_income_calibrated
        model_average_financial(1)=average_financial_calibrated
        model_average_net_wealth(1)=average_net_wealth_calibrated
        
        call allocate_matrix()
        
        call initialize_variables_and_grids()
        call GKKOC_intergenerational_employment_process(1)
        call initialize_financial_grid(1)
                
        call initialize_feasible_distribution(1)
            
        if (use_old_results==1) then
        
            call upload_vars(1)
            
        else
        
            housing_price(1)=calibrated_stationary_housing_price
                    
            if (fix_rent==0) then
                rent(1,:)=rent_to_housing_price*housing_price(1)*1.05
            else
                ! FIXED RENT STILL HAS TO BE SET. rent has no initialiser, so
                ! guarding the assignments that would move it also removed the
                ! one that gave it a value, and it ran on whatever was in memory.
                rent(1,:)=rent_calibrated(:)
            end if
                                          
            risk_free_rate(1)=calibrated_risk_free_rate
            mortgage_interest_rate(1)=risk_free_rate(1)+mortgage_interest_gap
            
            model_average_labour_income(1)=average_labor_income_calibrated
            call set_newborn_age_transfer(1)
            call set_renter_floor(1)
        call set_renter_floor(1)
            total_housing_demand(1)=calibrated_housing_stock
            
            total_rental_demand(1,:)=total_rental_supply_calibrated
            total_rental_supply(1,:)=total_rental_supply_calibrated
            
        end if
                
        call function_of_utility_advantage_from_homeowning(1)
                                               
        call set_SS_benefits(1)
        
        call function_of_utility_advantage_from_homeowning(1)
        call initialize_financial_grid(1)
                
        distance_value_function=1
        distance_lambda_m=1
        distance_kappa_uem=1
        distance_rho_m=1
        distance_rho_d=1
        distance_discount_factor=1

        ! The convexity of the rental company is not calibrated, its adjuster is
        ! zero, and its distance was assigned in exactly one place: the branch
        ! taken when the parameters are held fixed. On the calibrating path it
        ! was never written at all, so the loop condition was testing
        ! uninitialised memory against 1e-3 and the sweep could not terminate.
        distance_convexity_of_rental_company=0

        distance_discount_factor_on_child=1
        distance_minimum_inheritance=1
        distance_advantage_to_owning=1
        distance_relative_share_of_housing=1
        distance_relative_share_of_leisure=1
        distance_standard_deduction=1
        distance_housing_status_grid_expander=1
        distance_largest_house_size=1
        distance_probability_of_becoming_addicted=1
        distance_lambda_addiction=1
        distance_utility_cost_of_treatment=1
        distance_relative_share_of_addiction_1=1
        distance_addiction_scalar=1
        distance_value_of_life=1
        distance_max_food_cost=1
        distance_voucher_probability=1
        distance_separation_rate=1
        distance_employment_multiplier=1
        distance_rent_to_price=1
        distance_smallest_house_size=1
        distance_rental_market=1
        distance_fixed_cost_to_moving=1
        distance_average_labor_income=1
        distance_inheritance_amount=1
        distance_size_homelessness=1
        
        do i=1,2
        
            value_function_guess(i)%vector_youngest_real(:,:,:,:,:)=0
            value_function(i)%vector_transition_real(1,:,:,:,:,:,:)=0
            
        end do
                                                          
        write(*,*) "mortgage_deductibility=", mortgage_deductibility
        write(*,*) "mortgage_interest_rate=", mortgage_interest_rate(1)
        write(*,*) "risk_free_rate=", risk_free_rate(1)
        write(*,*) "property_tax(1)=", property_tax(1)
        write(*,*) "infinite_elasticity_of_rental_supply=", infinite_elasticity_of_rental_supply
        write(*,*) "life_span=", life_span
        write(*,*) "retirement_span=", retirement_span    
        write(*,*) "discount_factor=", discount_factor
        write(*,*) "discount_factor_on_child=", discount_factor_on_child
        write(*,*) "minimum_inheritance=", minimum_inheritance
        write(*,*) "size_homelessness=", size_homelessness
        write(*,*) "labor_income_tax_rate=", labor_income_tax_rate
        write(*,*) "curvature_of_labor_income_taxes=", curvature_of_labor_income_taxes
        write(*,*) "rent_to_housing_price=", rent_to_housing_price
        write(*,*) "personal_deduction=", personal_exemption
        write(*,*) "standard_deduction=", standard_deduction      
        write(*,*) "rent=",rent(1,:)
        write(*,*) "lump_sum_transfer=", lump_sum_transfer(1)
        write(*,*) "minimum_downpayment=", minimum_downpayment
        write(*,*) "max_amortization_years=", max_amortization_years
        write(*,*) "model_average_owner_occupied_unit_size(1)=", model_average_owner_occupied_unit_size(1)
        write(*,*) "smallest_house_size=", smallest_house_size
        write(*,*) "housing_size(index_of_smallest_house_hhld_can_buy)=", housing_size(max(min(index_of_smallest_house_hhld_can_buy,housing_status_grid_size-1),lowest_housing_grid_point))
        write(*,*) "c_1=", c_1
        write(*,*) "c_min=", c_min
        write(*,*) "cutoff_housing_investment=", cutoff_housing_investment
        write(*,*) "infinite_elasticity_of_rental_supply=", infinite_elasticity_of_rental_supply
        write(*,*) "calibration"
        write(*,*) "advantage_to_owning=", advantage_to_owning
        write(*,*) "unconditional_employment_probability=", unconditional_employment_probability
                
        if (use_old_results==0) then
                    
            if (fix_rent==0) then
                rent(1,:)=housing_price(1)*himmelberg_etal_rent_to_price
            else
                rent(1,:)=rent_calibrated(:)
            end if
            
        end if
        
        ! TRACKS THE RENT rather than repeating its value. Hardcoded, this
        ! silently kept the old level after p_r was renormalised.
        model_average_rent(1)=rent(1,0)
        
        call set_smallest_house_size()
        
        call function_of_utility_advantage_from_homeowning(1)
                 
        write(*,*) "rent=", rent(1,:)
                  
        write(*,*) "property_tax=", property_tax
        write(*,*) "max_debt_to_income_ratio=", max_debt_to_income_ratio
        write(*,*) "max_debt_to_income_ratio_below_80=", max_debt_to_income_ratio_below_80
        write(*,*) "smallest_house_size=", smallest_house_size
        write(*,*) "housing_size(smallest_house_to_buy)=", housing_size(max(min(index_of_smallest_house_hhld_can_buy,housing_status_grid_size-1),lowest_housing_grid_point))
        write(*,*) "lowest_housing_grid_point=", lowest_housing_grid_point
        write(*,*) "employment_grid=", employment_grid(1,:)
        write(*,*) "value_of_initial_assets=", value_of_initial_assets
        write(*,*) "initial_endowment=", initial_endowment      
        write(*,*) "standard_deduction=", standard_deduction
        write(*,*) "personal_exemption=", personal_exemption
        write(*,*) "model_average_labour_income=", model_average_labour_income(1)
        write(*,*) "average_labor_income_calibrated=", average_labor_income_calibrated
        write(*,*) "weight_on_labor_income=", weight_on_labor_income
        write(*,*) "inheritance_amount=", inheritance_amount
        write(*,*) "relative_share_of_leisure=", relative_share_of_leisure
        
        INQUIRE(FILE="total_rental_demand"//trim(long_run_simulation)//".dat", EXIST=file_exists)
                
!        if ((re_calibrate_management_costs==1) .AND. (zero_elasticity==0) .AND. &
!            (infinite_elasticity_of_rental_supply==0) .AND. (file_exists)) then
!        
!            open(unit=39,file="total_rental_demand"//trim(long_run_simulation)//".dat",action='read')
!                read(39,'(F15.12)') total_rental_demand(1,:)
!            close(39)
!            
!            do j=0,have_two_rental_markets
!                        
!                call solve_elasticity_of_rental_housing(1,convexity_of_rental_company(j),j)
!                        
!                rental_management_costs=&
!                    (rent(1,j)-housing_price(1)*&
!                    (risk_free_rate(1)+housing_depreciation_rate+property_tax(1)+&
!                    property_tax_on_rental_housing)/(1+risk_free_rate(1)))/&
!                    ((total_rental_demand_segmented(1,j)**&
!                    (convexity_of_rental_company(j)-1))*convexity_of_rental_company(j))
!                    
!            end do
!        
!            open(unit=27,file="rental_management_costs"//trim(file_number)//".dat",status='replace')
!                write(27,'(F30.29)') rental_management_costs
!            close(27)
!            
!            open(unit=27,file="convexity_of_rental_company"//trim(file_number)//".dat",status='replace')
!                write(27,'(F15.12)') convexity_of_rental_company
!            close(27)
!                                    
!        end if
        
        write(*,*) "rental_management_costs=", rental_management_costs
        write(*,*) "file_number=", file_number
        write(*,*) "fraction_to_repay=", fraction_to_repay         
        write(*,*) "prepayment_penalty_starts_from=", prepayment_penalty_starts_from
        write(*,*) "file_number=", file_number
        write(*,*) "empirical_housing_supplpy_elasticity=", empirical_housing_supplpy_elasticity
        write(*,*) "replacement_rate_ui=", replacement_rate_ui
        write(*,*) "size_homelessness=", size_homelessness
        write(*,*) "model_average_financial=", model_average_financial(1)
        write(*,*) "model_average_net_wealth=", model_average_net_wealth(1)
        write(*,*) "relative_share_of_addiction=", relative_share_of_addiction_2
        write(*,*) "relative_share_of_consumption_2=", relative_share_of_consumption_2
        write(*,*) "relative_share_of_housing_2=", relative_share_of_housing_2
        write(*,*) "relative_share_of_addiction_2=", relative_share_of_addiction_2
        write(*,*) "relative_share_of_consumption_1=", relative_share_of_consumption_1
        write(*,*) "relative_share_of_housing_1=", relative_share_of_housing_1
        write(*,*) "relative_share_of_addiction_1=", relative_share_of_addiction_1
        write(*,*) "sum 2=", relative_share_of_consumption_2+relative_share_of_housing_2+relative_share_of_addiction_2
        write(*,*) "sum 1=", relative_share_of_consumption_1+relative_share_of_housing_1+relative_share_of_addiction_1
        write(*,*) "model_ss_benefits=", model_ss_benefits
        write(*,*) "price_of_addictive_good=", price_of_addictive_good
        write(*,*) "hello1"
        write(*,*) "expected_age_non_addicted=", expected_age_non_addicted+25
        write(*,*) "expected_age_homeless=", expected_age_homeless+25
        write(*,*) "expected_age_addicted=", expected_age_addicted+25
        write(*,*) "expected_age_homeless_and_addicted=", expected_age_homeless_and_addicted+25
                
        previous_average_labor_income=model_average_labour_income(1)
        previous_median_income=median_income(1)
        previous_average_net_wealth=model_average_net_wealth(1)
        previous_inheritance_amount=inheritance_amount
        
        write(*,*) "adjusted_probability=", adjusted_probability(:)
        write(*,*) "probability_of_voucher=", probability_of_voucher
        write(*,*) "addiction_scalar_1=", addiction_scalar_1
        
        do i=1,employment_grid_size
            write(*,*) "employment_grid(",i,")=", employment_grid(1,i)
        end do
        
        do i=1,employment_grid_size
            write(*,*) "employment_grid(",i,")=", employment_grid(30,i)
        end do
        
        write(*,*) "increased_risk_of_death_addicted=", increased_risk_of_death_addicted
        write(*,*) "multiple_of_probabilities_of_employment_if_addicted=", multiple_of_probabilities_of_employment_if_addicted
        write(*,*) "relative_share_of_addiction_2=", relative_share_of_addiction_2
        write(*,*) "relative_share_of_addiction_1=", relative_share_of_addiction_1
        write(*,*) "size_of_penalty=", size_of_penalty
        write(*,*) "voucher_probabilities=", voucher_probabilities(0,1,1,:)
        write(*,*) "voucher_probabilities=", voucher_probabilities(1,1,1,:)
        write(*,*) "voucher_probabilities_benchmark=", voucher_probabilities_benchmark(0,1,1,:)
        write(*,*) "voucher_probabilities_benchmark=", voucher_probabilities_benchmark(1,1,1,:)
        
        write(*,*) "increased_risk_of_death_addicted*(1-sum(actual_survival_probability)/life_span)=", &
            increased_risk_of_death_addicted*(1-sum(actual_survival_probability)/life_span)
            
        do i=1,bins_drug_spending_relative_to_average
        
            drug_spending_relative_to_average(i)=(i-1)/(real(bins_drug_spending_relative_to_average)/real(100))
        
        end do
        
        index_drug_1(1)=min(max(minloc(drug_spending_relative_to_average(:)-0.5,1,&
            mask=drug_spending_relative_to_average(:)-0.5>0),1),&
            bins_drug_spending_relative_to_average) 

        ! THE WARM START IS READ HERE AND NOT WITH THE PARAMETERS, because it
        ! writes into distribution_stationary and distribution_guess and those do
        ! not exist until allocate_matrix has run. Reading it beside
        ! read_calibration_state, which only moves scalars, wrote into unallocated
        ! derived type components and segfaulted before the first line of output.
        ! The symptom was a binary that had just run fine crashing on startup, and
        ! the only thing that had changed was that a previous loop had left a
        ! checkpoint on disk for it to read.
        call apply_gamma_tie()

        call read_calibration_distribution()

        ! THE SWEEP'S GRID, READ RATHER THAN COMPILED IN, so a container that
        ! rebuilds mid sweep resumes on the points that are left: the driver
        ! rewrites this file with the remainder before each launch, and
        ! loop_count then indexes it from one either way.
        if (sweep_addiction_scalar==1) then

            open(unit=77,file="B_SWEEP_GRID.txt",action='read',status='old',iostat=sweep_points)
            if (sweep_points/=0) then
                write(*,*) "B SWEEP: no B_SWEEP_GRID.txt, nothing to sweep"
                stop
            end if
            sweep_points=0
            do
                if (sweep_points>=max_sweep_points) exit
                read(77,*,end=7701) sweep_b_grid(sweep_points+1)
                sweep_points=sweep_points+1
            end do
7701        close(77)

            if (sweep_points==0) then
                write(*,*) "B SWEEP COMPLETE: the grid file is empty"
                stop
            end if

            addiction_scalar_1=sweep_b_grid(1)
            write(*,*) "B SWEEP: ", sweep_points, " points, starting at b=",&
                addiction_scalar_1

        end if

        do while((distance_rental_market(1)>stopping_rule_rental_market) .OR. &
            (distance_discount_factor>stopping_rule_discount_factor) .OR. &
            (distance_discount_factor_on_child>stopping_rule_discount_factor_on_child) .OR. &
            (distance_minimum_inheritance>stopping_rule_minimum_inheritance) .OR. &
            (distance_advantage_to_owning>stopping_rule_advantage_to_owning) .OR. &
            (distance_relative_share_of_housing>stopping_rule_relative_share_of_housing) .OR. &
            (distance_relative_share_of_leisure>stopping_rule_relative_share_of_leisure) .OR. &
            (distance_convexity_of_rental_company>stopping_rule_convexity_of_rental_company) .OR. &
            (distance_housing_status_grid_expander>stopping_rule_housing_status_grid_expander) .OR. &
            (distance_largest_house_size>stopping_rule_largest_house_size) .OR. &
            (distance_probability_of_becoming_addicted>&
             stopping_rule_probability_of_becoming_addicted) .OR. &
            (distance_lambda_addiction>stopping_rule_lambda_addiction) .OR. &
            (distance_drug_market>stopping_rule_drug_market) .OR. &
            (distance_relative_share_of_addiction_1>stopping_rule_relative_share_of_addiction_1) .OR. &
            (distance_addiction_scalar>stopping_rule_addiction_scalar) .OR. &
            (distance_value_of_life>stopping_rule_value_of_life) .OR. &
            (distance_max_food_cost>stopping_rule_max_food_cost) .OR. &
            (distance_voucher_probability>stopping_rule_voucher_probability) .OR. &
            (distance_separation_rate>stopping_rule_separation_rate) .OR. &
            (distance_employment_multiplier>stopping_rule_employment_multiplier) .OR. &
            (distance_utility_cost_of_treatment>stopping_rule_utility_cost_of_treatment) .OR. &
            (distance_rent_to_price>stopping_rule_rent_to_price) .OR. &
            (distance_smallest_house_size>stopping_rule_smallest_house_size) .OR. &
            (distance_fixed_cost_to_moving>stopping_rule_fixed_cost_to_moving) .OR. &
            (distance_standard_deduction>stopping_rule_standard_deduction) .OR. &
            (distance_inheritance_amount>stopping_rule_inheritance_amount) .OR. &
            (distance_size_homelessness>stopping_rule_size_homelessness) .OR. &
            (distance_average_labor_income>stopping_rule_average_labor_income) .OR. &
            (distance_median_income>stopping_rule_median_income) .OR. &
            (distance_average_net_wealth>stopping_rule_average_net_wealth) .OR. &
            (distance_drug_threshold>stopping_rule_drug_threshold) .OR. &
            (distance_lambda_m>stopping_rule_lambda_m) .OR. &
            (distance_kappa_uem>stopping_rule_kappa_uem) .OR. &
            (distance_rho_m>stopping_rule_rho_m) .OR. &
            (distance_rho_d>stopping_rule_rho_d) .OR. &
            (distance_mu_homeless>stopping_rule_mu_homeless) .OR. &
            (distance_weight_on_child>stopping_rule_weight_on_child) .OR. &
            (distance_penalty_child_addicted>stopping_rule_penalty_child_addicted) .OR. &
            (distance_penalty_child_homeless>stopping_rule_penalty_child_homeless) .OR. &
            (distance_labor_income_tax_rate>stopping_rule_labor_income_tax_rate) .OR. &
            (distance_sd_permanent_productivity>stopping_rule_sd_permanent_productivity) .OR. (loop_count<1))
                        
            ! SIGMA_Y, on the share of productivity held by the bottom half.
            ! The share FALLS in sigma_y, so a model share above target means
            ! the distribution is too equal and sigma_y has to rise. The grid is
            ! rebuilt from sigma_y at the top of every loop, so the new value is
            ! in force for the solve that follows.
            ! THE DISPERSION INSTRUMENT IS WHICHEVER GRID IS LIVE, and the two
            ! share the moment, the target and the distance slot -- so the long
            ! do while above needs no new term and exactly one of them steps.
            !
            ! sd_permanent_productivity builds the QUANTILE grid and nothing
            ! else. Under fixed_productivity=0 it moves no moment at all, and
            ! left to run it would step a number that changes nothing while the
            ! distance never fell under its stopping rule: the calibration would
            ! never terminate.
            if ((calibrate_sd_permanent_productivity==1) .AND. (loop_count>=1)&
                .AND. (fixed_productivity==0)) then

                write(*,*) "bottom half's share of productivity, pooled 26-65 =",&
                    model_bottom_half_earnings_share,&
                    " target =", bottom_half_earnings_share_data
                write(*,*) "kkk_sigma_scale=", kkk_sigma_scale,&
                    " sd of log y at age 1 =", sd_log_y_newborn

                kkk_sigma_scale=max(min(kkk_sigma_scale+kkk_sigma_scale_adjuster*&
                    (model_bottom_half_earnings_share-bottom_half_earnings_share_data),&
                    10.d0),0.1d0)

                distance_sd_permanent_productivity=&
                    (1-freeze_sd_permanent_productivity)*&
                    abs(model_bottom_half_earnings_share-bottom_half_earnings_share_data)

                write(*,*) "kkk_sigma_scale=", kkk_sigma_scale,&
                    " distance=", distance_sd_permanent_productivity

            end if

            if ((calibrate_sd_permanent_productivity==1) .AND. (loop_count>=1)&
                .AND. (fixed_productivity==1)) then

                write(*,*) "bottom half's share of productivity =",&
                    model_bottom_half_earnings_share,&
                    " target =", bottom_half_earnings_share_data
                write(*,*) "sd_permanent_productivity=", sd_permanent_productivity

                sd_permanent_productivity=max(min(sd_permanent_productivity+&
                    sd_permanent_productivity_adjuster*&
                    (model_bottom_half_earnings_share-bottom_half_earnings_share_data),&
                    3.d0),10.d0**(-2))

                distance_sd_permanent_productivity=&
                    (1-freeze_sd_permanent_productivity)*&
                    abs(model_bottom_half_earnings_share-bottom_half_earnings_share_data)

                write(*,*) "sd_permanent_productivity=", sd_permanent_productivity,&
                    " distance_sd_permanent_productivity=", distance_sd_permanent_productivity

            end if

            ! OMEGA'S MOMENT, measured before the baseline so that every statistic
            ! the rest of this loop reads describes the baseline and not this.
            ! Switching the child term off means setting its weight to zero, which
            ! is exactly what the moment describes.
            ! NOT DURING A SWEEP, for two reasons. It costs a full extra value
            ! function solve and distribution convergence on every pass, about a
            ! third of the pass, and nothing in a sweep of b reads it. Worse, it
            ! leaves its own converged distribution behind for the baseline solve
            ! to start from, so the number the sweep is measuring would carry the
            ! counterfactual's path in it. That path dependence is the fault
            ! already recorded against omega's own moment; there is no reason to
            ! feed it into a curve meant to isolate b.
            if ((calibrate_weight_on_child==1) .AND. (include_child_in_continuation==1)&
                .AND. (loop_count>=1) .AND. (sweep_addiction_scalar==0)) then

                child_penalty_off=1

                call solve_value_function_and_policy_functions(1)
                call converge_to_stationary_equilibrium(1)
                call stationary_equilibrium_statistics(1)

                ! model_total_drug_users IS BUILT IN govt_revenues_calc, NOT IN
                ! stationary_equilibrium_statistics. Both counterfactual blocks
                ! called only the latter, so the variable still held the BASELINE
                ! count when it was read back: the ratio was exactly one and
                ! omega came out as exactly 0.0000000000000000, at every value of
                ! omega_c, which is what a variable that was never updated looks
                ! like. The main path calls the two in this order, and so must
                ! anything that wants a fresh count.
                call govt_revenues_calc(1)

                drug_users_without_child=model_total_drug_users(1)

                child_penalty_off=0

                ! WHETHER THE COUNTERFACTUAL'S OWN DISTRIBUTION SETTLED, which
                ! decides whether its sign can be read at all. The counterfactual
                ! re-solves the distribution from the baseline's, and the sweep
                ! cap is two hundred; a solve that leaves on the cap has moved
                ! part of the way to the counterfactual and the gap it reports is
                ! a partial adjustment rather than the moment.
                !
                ! IT IS PRINTED BECAUSE THE SIGN CAME OUT WRONG ONCE, AND THE
                ! PRINT ANSWERED IT. At loop 3 of a cold run, removing the
                ! penalty CUT use by 75 per cent where the mechanism says it
                ! should raise it: the term is zero for a clean housed parent and
                ! negative otherwise, so removing it makes the disordered states
                ! cheaper and use should rise. That could have been the
                ! counterfactual's own distribution stopping half way, since it
                ! re-solves from the baseline's under the sweep cap.
                !
                ! IT WAS NOT. Measured once participation came down: 61 sweeps,
                ! reached 7.2e-5 against a stopping rule of 6e-4, capped = 0. The
                ! counterfactual converges properly and the sign is now the right
                ! one, +0.93 against a target of +0.18, which says omega is too
                ! large rather than that anything is broken. The gap RISES in
                ! omega, so the update lowers it, which is the documented
                ! direction. The print stays: it is two numbers a loop and it is
                ! the difference between reading that gap and guessing at it.
                write(*,*) "omega counterfactual: drug users with the child penalty off =",&
                    drug_users_without_child, " counterfactual distribution sweeps =",&
                    loop_count_dist, " reached =", distance_distribution_reached,&
                    " capped =", merge(1,0,loop_count_dist>=max_distribution_sweeps)

            end if

            ! THE PRIMING SOLVE, WITHOUT WHICH THE CHILD TERM IS NEVER LIVE.
            !
            ! compute_expected_child_value runs at the top of the solve and
            ! returns zero while age one is still the sentinel, so the FIRST
            ! solve of a run always faces a zero child term. The design assumed a
            ! second pass would pick it up, which the calibration loop provides
            ! and a point run does not. The consequence was total rather than
            ! partial: nineteen points carrying MOMENT omega every one reported a
            ! use gap of exactly 0.0000000000000000, because switching off a term
            ! that is already zero is a no-op, and weight_on_child multiplied
            ! nothing at 0.02, 0.5 and 0.7 alike.
            !
            ! So solve once to fill age one, which lets the next call compute the
            ! term for real, then solve again with it live. It costs one extra
            ! solve on the first pass of a run and nothing after that.
            if ((include_child_in_continuation==1) .AND. (child_value_ready==0)) then

                write(*,*) "PRIMING SOLVE: filling age one so the child term can be computed"

                call solve_value_function_and_policy_functions(1)

            end if

            ! ================= THE TWO TYPES =================
            ! Half the households are patient and half impatient, and a
            ! household never switches, so the two share prices and the
            ! government budget and nothing else. The whole chain -- solve,
            ! distribution, statistics -- runs once per type, and the moment
            ! accumulators are NOT reset on the second pass.
            !
            ! WHY THAT GIVES THE MIXTURE AND NOT THE SECOND TYPE. Every
            ! targeted moment in this model is a ratio or a share. Each type's
            ! distribution carries unit mass, so summing both passes doubles
            ! the numerator and the denominator of every one of them and the
            ! ratio is exactly the fifty-fifty mixture. No weighting is needed
            ! and none is applied. A LEVEL would come out doubled, which is why
            ! it is worth checking that no targeted moment is one.
            discount_factor_patient_saved=discount_factor

            do current_beta_type=1,number_of_beta_types

            accumulating_beta_types=current_beta_type-1
            mass_passes=current_beta_type
            if (current_beta_type==1) discount_factor=discount_factor_patient_saved
            if (current_beta_type==2) discount_factor=discount_factor_impatient

            ! THE FLOOR IS PER PASS NOW. set_renter_floor reads current_beta_type,
            ! so it has to run after the type is set and before anything that
            ! loops on renter_floor_by_age. Harmless when
            ! restrict_borrowing_to_impatient is zero: it recomputes the same
            ! array both passes.
            call set_renter_floor(1)

            ! AND THE WARM DISTRIBUTION HAS TO BE PROJECTED ONTO IT. From loop
            ! three onward initialize_feasible_distribution is skipped and the
            ! patient pass starts from the IMPATIENT pass's converged
            ! distribution, which carries mass at negative indices the patient
            ! pass no longer visits. That mass would sit untouched in the array
            ! and still be picked up by the full-slice sum() calls that form
            ! sum_of_distribution, inflating the denominator of every share.
            !
            ! Zeroing it is safe because this is only the ITERATION'S STARTING
            ! GUESS: converge_to_stationary_equilibrium runs to 6e-4 from
            ! whatever it is handed, so a projection changes the path and not
            ! the fixed point. lbound is read off the array rather than
            ! recomputed because the owner slabs start at 1 and have no negative
            ! region to clear.
            if ((include_unsecured_borrowing==1) .AND. &
                (restrict_borrowing_to_impatient==1) .AND. &
                (number_of_beta_types>1) .AND. (current_beta_type==1)) then

                do i_beta_floor=1,size(distribution_guess)

                    ! distribution_guess is the OPERATIVE one: the iteration
                    ! zeroes distribution_implied every sweep and rebuilds it
                    ! from the guess, and sum(distribution_guess) feeds both the
                    ! convergence distance and the Aitken step. Phantom mass at
                    ! an index the patient pass never visits would sit in that
                    ! sum. distribution_stationary is cleared with it because
                    ! every moment's denominator is a full-slice sum over it.
                    if (lbound(distribution_guess(i_beta_floor)%&
                        vector_transition_real,3)<negative_financial_grid_size) then

                        distribution_guess(i_beta_floor)%vector_transition_real&
                            (:,:,lbound(distribution_guess(i_beta_floor)%&
                            vector_transition_real,3):negative_financial_grid_size-1,&
                            :,:,:,:)=0

                    end if

                    if (lbound(distribution_stationary(i_beta_floor)%&
                        vector_transition_real,3)<negative_financial_grid_size) then

                        distribution_stationary(i_beta_floor)%vector_transition_real&
                            (:,:,lbound(distribution_stationary(i_beta_floor)%&
                            vector_transition_real,3):negative_financial_grid_size-1,&
                            :,:,:,:)=0

                    end if

                end do

            end if

            call solve_value_function_and_policy_functions(1)
                            
            ! A LOADED WARM START MUST NOT BE OVERWRITTEN. The initialisation
            ! puts everyone at age one with no assets, which is the right guess
            ! only when there is no better one on disk. Once a loop has run and
            ! converged, distribution_stationary is the better guess and the
            ! flag is cleared, so this reverts to the old behaviour from the
            ! second loop of a resumed run onwards.
            !
            ! A SWEEP IS EXEMPT, and it has to be. re_do_simulation_with_fixed_
            ! parameters is normally a single re-run of a finished calibration,
            ! where paying for a cold distribution once is nothing; a sweep is
            ! one pass per grid point, and forcing the age one cross section on
            ! every one of them costs the 655 sweeps this file warns about at
            ! each. Measured: forty eight minutes without a single completed
            ! pass, against seven for a calibration loop. Consecutive points
            ! differ in b alone, so the previous point's converged distribution
            ! is the better guess, exactly as it is between calibration loops.
            if (((loop_count<3) .OR. ((re_do_simulation_with_fixed_parameters==1)&
                .AND. (sweep_addiction_scalar==0))) .AND. &
                (have_warm_distribution==0)) then

                call initialize_feasible_distribution(1)

            end if

            have_warm_distribution=0
            
            ! THIS IS THE OPERATIVE DISTRIBUTION TOLERANCE. 2e-4, and it is
            ! already loose.
            !
            ! There used to be a second reset just above, to 1e-8, in both arms of
            ! an if whose branches were identical; it has been removed because it
            ! was dead, being overwritten here on the same pass. Both together
            ! meant the declared value never reached the iteration.
            !
            ! Worth stating plainly since it was got wrong once: there is no
            ! speed left in this number. The 655 sweeps a loop takes are what
            ! reaching 2e-4 costs, not what reaching 1e-8 would cost. Loosening
            ! it further trades directly against the moments, which are shares
            ! read to three and four decimals.
            if (include_addiction==1) then

                stopping_rule_stationary_distribution=6*10.d0**(-4)

            end if
            
            if (load_test_distribution==0) then
            
                call converge_to_stationary_equilibrium(1)
                
            else
            
                do i=1,2
    
                    write(string_used,'(i1)') i
                                   
                    open(unit=10,file="distribution_stationary"//trim(string_used)//trim(old_results)//".dat",action='read')
                        read(10,'(F30.28)') distribution_stationary(i)%vector_transition_real(1,:,:,:,:,:,:)
                    close(10)
                    
                end do
                
            end if
            
            ! CAPTURE THE PREVIOUS LOOP'S VALUES ONCE, ON THE FIRST PASS.
            !
            ! These four are the damping anchors: the block near the end of the
            ! iteration blends the new value with the previous one at
            ! weight_on_labor_income and its siblings. "Previous" means the
            ! previous CALIBRATION LOOP. Unguarded, this sits inside
            ! `do current_beta_type=1,number_of_beta_types` and so ran again on
            ! the second pass -- and by then model_average_labour_income holds
            ! what the FIRST pass left, which is a raw mass-weighted SUM, because
            ! the division by model_total_workers is guarded to the LAST pass and
            ! pass one skips it.
            !
            ! The blend downstream therefore averaged a true per-worker mean with
            ! an undivided sum, inflating the denominator by roughly (1+W)/2 for
            ! W the first type's worker mass. That is the factor of seventeen
            ! that has been chased all evening: aleph read 2.61 against a target
            ! of 80, and two lines in the SAME point implied 0.6 and 10.2 for the
            ! same quantity.
            !
            ! It is not confined to a printed moment. set_SS_benefits multiplies
            ! benefits by this, and the next iteration's solve reads it as
            ! avg_income_to_use_1 and as the standard deduction, so a corrupted
            ! value walks into the household's budget constraint.
            !
            ! At ONE beta type the division happens on the only pass and the
            ! guard below is always true, so nothing measured at one type moves.
            ! That matches the symptom: aleph sits still at one type and swings
            ! at two.
            if (accumulating_beta_types==0) then

                previous_average_labor_income=model_average_labour_income(1)
                previous_median_income=median_income(1)
                previous_average_net_wealth=model_average_net_wealth(1)

                previous_inheritance_amount=inheritance_amount

            end if
            
            call stationary_equilibrium_statistics(1)
            call stationary_equilibirum_homeownership_rate(1)
            call govt_revenues_calc(1)
            call calculate_aggregate_consumption(1)
            call calculate_welfare(1)
            call calculate_household_housing_spending(1)
            call calculate_welfare_by_characteristics(1)
                        
            call calculate_homeownership_by_characteristics(1)            
            call stationary_equilibrium_wealth_distribution_of_old(1)

            end do

            ! Back to the patient value, which is the one the calibration owns,
            ! and back to resetting accumulators so nothing downstream inherits
            ! the suppression.
            discount_factor=discount_factor_patient_saved
            mass_passes=number_of_beta_types
            accumulating_beta_types=0
            current_beta_type=1
            
            if (loop_count>0) then
            
                if ((include_bequests==1) .AND. (residual_bequests_to_government==0)) then
            
                    if (inheritance_function_of_productivity==0) then
            
                        if (include_bequests_in_govt_constraint==0) then
                        
                            call calculate_updated_inheritance_amounts(1)
                                        
                        end if
                        
                        distance_inheritance_amount=maxval((1-include_bequests_in_govt_constraint)*&
                            abs(previous_inheritance_amount-inheritance_amount))
                        
                        inheritance_amount=inheritance_amount_weight*inheritance_amount+&
                            (1-inheritance_amount_weight)*previous_inheritance_amount
                            
                    else
                    
                        distance_inheritance_amount=&
                            abs(model_bequests(1)-value_of_initial_assets-model_total_inheritance(1))
                        
                        inheritance_amount=inheritance_amount+&
                             inheritance_amount_adjuster*&
                             (model_bequests(1)-value_of_initial_assets-model_total_inheritance(1))
                    
                    end if
                        
                else
                    
                    distance_inheritance_amount=0
                    
                end if
                    
            else
            
                distance_inheritance_amount=1
            
            end if
                             
            if (re_do_simulation_with_fixed_parameters==1) then
            
                distance_discount_factor=0
                distance_discount_factor_on_child=0
                distance_minimum_inheritance=0
                distance_housing_status_grid_expander=0
                distance_largest_house_size=0
                distance_probability_of_becoming_addicted=0
                distance_lambda_addiction=0
                distance_utility_cost_of_treatment=0
                distance_relative_share_of_addiction_1=0
                distance_addiction_scalar=0
                distance_value_of_life=0
                distance_max_food_cost=0
                distance_voucher_probability=0
                distance_separation_rate=0
                distance_employment_multiplier=0
                distance_rent_to_price=0
                distance_smallest_house_size=0
                distance_advantage_to_owning=0
                distance_relative_share_of_housing=0
                distance_relative_share_of_leisure=0
                distance_standard_deduction=0
                distance_convexity_of_rental_company=0
                distance_fixed_cost_to_moving=0
                distance_size_homelessness=0
                distance_lambda_m=0
                distance_kappa_uem=0
                distance_rho_m=0
                distance_rho_d=0
                        
            else
            
                if (loop_count>aftr_how_mny_lps_start_update) then
            
                    write(*,*) "discount_factor=", discount_factor
                                            
                    ! RETARGETED ONTO WEALTH OVER OUTPUT. This used to be driven
                    ! by the mortgage share of gross housing wealth against the
                    ! SCF's 0.345, and with include_ownership at zero that moment
                    ! is not merely dead, it is NOT A NUMBER: mortgages and gross
                    ! housing wealth are both identically zero, so the ratio is
                    ! 0/0. The consequence was worse than a frozen parameter.
                    ! beta + adjuster*NaN is NaN, and min(max(NaN,0),1.3) collapses
                    ! to zero under gfortran, so the discount factor was SET TO
                    ! ZERO at the end of the first calibration loop and every loop
                    ! after the first solved a completely myopic household. The
                    ! distance was NaN too, and NaN > tolerance is false, so the
                    ! convergence test read the broken parameter as converged and
                    ! said nothing.
                    !
                    ! The note has always said beta is chosen to reproduce wealth
                    ! over output in the national accounts, and the model
                    ! counterpart was already being computed and printed two lines
                    ! below the update that ignored it. That is what it targets now.
                    !
                    ! SIGN. Wealth rises with patience, so a model below target
                    ! calls for a higher beta: the update is minus the adjuster
                    ! times (model minus data), which is the same convention as
                    ! every other parameter in this loop.
                    wealth_to_output_model_1=model_total_net_wealth(1)/model_GDP_incl_imput_rent(1)

                    if (wealth_to_output_model_1 .NE. wealth_to_output_model_1) then

                        ! A MOMENT THAT IS NOT A NUMBER MUST NOT MOVE A PARAMETER
                        ! AND MUST NOT BE READ AS CONVERGED. Leave beta where it
                        ! is and force the distance large so the loop stays open
                        ! and the failure is visible.
                        write(*,*) "wealth over output is NaN: beta held at", discount_factor
                        distance_discount_factor=1

                    else

                        gap_discount_factor_1=wealth_to_output_model_1-wealth_to_output_data

                        ! The usual sign flip ratchet. Wealth over output is very
                        ! sensitive to beta close to one, so a fixed step
                        ! overshoots and then oscillates.
                        if (have_gap_discount_factor==1) then

                            if ((gap_discount_factor_1*previous_gap_discount_factor)<0) then

                                discount_factor_adjuster=&
                                    max(discount_factor_adjuster*discount_factor_damping,&
                                    discount_factor_adjuster_floor)

                            else

                                discount_factor_adjuster=&
                                    min(discount_factor_adjuster*discount_factor_growth,&
                                    discount_factor_adjuster_start)

                            end if

                        end if

                        previous_gap_discount_factor=gap_discount_factor_1
                        have_gap_discount_factor=1

                        ! BRACKET AND BISECT, for the same reason the homelessness
                        ! size does it. Wealth over output is very nearly a step
                        ! function in beta near the knife edge where beta*(1+r)
                        ! reaches one: measured here, beta of 0.957 gave 0.78 and
                        ! beta of 0.968 gave 20.79, so a twenty six fold move in
                        ! the moment across eleven thousandths of the parameter.
                        ! A proportional adjuster cannot land inside a window that
                        ! narrow, however hard it is damped; it can only straddle
                        ! it. Bisection halves the window every solve regardless
                        ! of how steep the schedule is.
                        !
                        ! Wealth over output RISES with beta, so a model below
                        ! target makes this beta the low endpoint and a model
                        ! above target makes it the high one.
                        if (wealth_to_output_model_1<wealth_to_output_data) then

                            if (discount_factor_lo<0) then

                                discount_factor_lo=discount_factor
                                discount_factor_lo_moment=wealth_to_output_model_1

                            else if ((discount_factor>discount_factor_lo) .AND. &
                                (wealth_to_output_model_1<discount_factor_lo_moment-10.d0**(-5))) then

                                ! Raised patience and wealth fell. Something else
                                ! moved under the bracket, so its endpoints are no
                                ! longer comparable.
                                write(*,*) "beta BRACKET DISCARDED: raised to ", discount_factor, &
                                    " and wealth over output fell from ", discount_factor_lo_moment, &
                                    " to ", wealth_to_output_model_1
                                discount_factor_lo=-1
                                discount_factor_hi=-1
                                discount_factor_lo_moment=-1
                                discount_factor_hi_moment=-1

                            else if (discount_factor>discount_factor_lo) then

                                discount_factor_lo=discount_factor
                                discount_factor_lo_moment=wealth_to_output_model_1

                            end if

                        else

                            if (discount_factor_hi<0) then

                                discount_factor_hi=discount_factor
                                discount_factor_hi_moment=wealth_to_output_model_1

                            else if ((discount_factor<discount_factor_hi) .AND. &
                                (wealth_to_output_model_1>discount_factor_hi_moment+10.d0**(-5))) then

                                write(*,*) "beta BRACKET DISCARDED: lowered to ", discount_factor, &
                                    " and wealth over output rose from ", discount_factor_hi_moment, &
                                    " to ", wealth_to_output_model_1
                                discount_factor_lo=-1
                                discount_factor_hi=-1
                                discount_factor_lo_moment=-1
                                discount_factor_hi_moment=-1

                            else if (discount_factor<discount_factor_hi) then

                                discount_factor_hi=discount_factor
                                discount_factor_hi_moment=wealth_to_output_model_1

                            end if

                        end if

                        distance_discount_factor=(1-freeze_beta_bisection)*abs(gap_discount_factor_1)

                        if ((discount_factor_lo>=0) .AND. &
                            (discount_factor_hi>discount_factor_lo)) then

                            if ((discount_factor_hi-discount_factor_lo)<bracket_discount_factor_floor) then

                                ! A WINDOW THIS NARROW IS THE ANSWER. The moment
                                ! jumps across it, so no beta reproduces the target
                                ! more closely and iterating further only burns
                                ! solves. Report the two sides and stop asking.
                                write(*,*) "beta BRACKET IS AT ITS FLOOR [", discount_factor_lo, &
                                    ",", discount_factor_hi, "] with the moment jumping from ", &
                                    discount_factor_lo_moment, " to ", discount_factor_hi_moment, &
                                    " across it, against a target of ", wealth_to_output_data
                                write(*,*) "   wealth over output is a step in beta here, so this is",&
                                    " as close as the moment can be brought."
                                distance_discount_factor=0

                            else

                                if (freeze_beta_bisection==0) &
                                    discount_factor=0.5d0*(discount_factor_lo+discount_factor_hi)

                                write(*,*) "beta bisecting in [", discount_factor_lo, &
                                    ",", discount_factor_hi, "]"

                            end if

                        else

                            ! No bracket yet, so traverse.
                            if (freeze_beta_bisection==0) &
                                discount_factor=min(max(discount_factor-discount_factor_adjuster*&
                                gap_discount_factor_1,0.5d0),1.05d0)

                        end if

                        write(*,*) "wealth_to_output_model=", wealth_to_output_model_1, &
                            " against ", wealth_to_output_data
                        write(*,*) "discount_factor_adjuster=", discount_factor_adjuster

                        ! A PINNED PARAMETER IS A RESULT, NOT A DETAIL. If beta
                        ! sits on a bound the target is not reachable by patience
                        ! alone and the number in the table would be a bound
                        ! rather than a calibration.
                        if ((discount_factor<=0.5d0+10.d0**(-8)) .OR. &
                            (discount_factor>=1.05d0-10.d0**(-8))) then

                            write(*,*) "beta IS PINNED AT A BOUND", discount_factor, &
                                " and wealth over output is ", wealth_to_output_model_1, &
                                " against ", wealth_to_output_data

                        end if

                    end if
                                         
                    write(*,*) "discount_factor=", discount_factor
                    write(*,*) "distance_discount_factor=", distance_discount_factor
                    write(*,*) "model_total_net_wealth(1)/model_GDP_incl_imput_rent(1)=", &
                        model_total_net_wealth(1)/model_GDP_incl_imput_rent(1)
                    write(*,*) "model_fraction_of_homeowners_with_mortgage(1)=", &
                        model_fraction_of_homeowners_with_mortgage(1)
                    write(*,*) "(model_mortgages(1)/model_gross_housing_wealth(1))=", &
                        (model_mortgages(1)/model_gross_housing_wealth(1))
                                            
                    write(*,*) "discount_factor_on_child=", discount_factor_on_child

                    ! A DISTANCE WHOSE PARAMETER CANNOT MOVE MUST NOT BE IN THE
                    ! CONVERGENCE TEST.
                    !
                    ! Both adjusters below are zero, so the parameter is frozen,
                    ! but the distance was still computed from a model moment and
                    ! still tested against 1e-3 in the loop condition. A frozen
                    ! parameter will not walk its moment onto its target, so the
                    ! sweep could not terminate however well everything else fit.
                    ! Guard on the adjuster, which is the same discipline the
                    ! homeownership blocks below already use.
                    if (discount_factor_on_child_adjuster==0) then

                        distance_discount_factor_on_child=0

                    else if (target_HO_of_old==1) then

                        discount_factor_on_child=min(max(discount_factor_on_child-&
                            discount_factor_on_child_adjuster*(model_homeownership_by_age_group(1,5)-&
                            homeownership_rate_of_old_data),0.005),10000.d0) 
                            
                        distance_discount_factor_on_child=&
                            abs(model_homeownership_by_age_group(1,5)-homeownership_rate_of_old_data)
                            
                        write(*,*) "model_homeownership_by_age_group=", model_homeownership_by_age_group(1,5)
                        
                    else
                    
                        ! THIS BRANCH CANNOT STEER, AND MUST NOT PRETEND TO. It
                        ! updated the parameter from model_median_assets_to_income(1)
                        ! over model_median_assets_to_income(3): the array has size
                        ! num_percentiles=1, so index 3 is out of bounds, and it is
                        ! assigned NOWHERE in this file, so index 1 is the zero it
                        ! was initialised to. A run that entered here would walk
                        ! discount_factor_on_child by 0/garbage and report a
                        ! distance made of the same. Dead today only because
                        ! discount_factor_on_child_adjuster=0; stop rather than
                        ! run, for the reason the smooth-hazard guard gives: a
                        ! model that still produces numbers is exactly how this
                        ! would go unnoticed.
                        write(*,*) "discount_factor_on_child is switched on with"
                        write(*,*) "target_HO_of_old=0, but its alternative moment"
                        write(*,*) "model_median_assets_to_income is never computed."
                        write(*,*) "Compute the moment or set target_HO_of_old=1."
                        stop
                    
                    end if
                            
                    write(*,*) "discount_factor_on_child=", discount_factor_on_child

                    write(*,*) "minimum_inheritance=", minimum_inheritance
                
                    minimum_inheritance=min(max(minimum_inheritance+minimum_inheritance_adjuster*&
                        (model_fraction_leaving_bequests(1)-fraction_leaving_bequests_data),0.d0),150.d0)

                    if (minimum_inheritance_adjuster==0) then

                        distance_minimum_inheritance=0

                    else

                        distance_minimum_inheritance=&
                            abs(model_fraction_leaving_bequests(1)-fraction_leaving_bequests_data)

                    end if

                    write(*,*) "minimum_inheritance=", minimum_inheritance
                    write(*,*) "model_fraction_leaving_bequests=", model_fraction_leaving_bequests(1)
                                                                 
                    if (advantage_to_owning_adjuster>0) then
                    
                        write(*,*) "advantage_to_owning=", advantage_to_owning
                    
                        advantage_to_owning=min(max(advantage_to_owning-advantage_to_owning_adjuster*&
                            (model_homeownership_rate(1)-SCF_homeownership_rate),0.d0),10000.d0) 
                                                                    
                        distance_advantage_to_owning=abs(model_homeownership_rate(1)-SCF_homeownership_rate)
                        
                        write(*,*) "advantage_to_owning=", advantage_to_owning
                        write(*,*) "distance_advantage_to_owning=", distance_advantage_to_owning
                        write(*,*) "model_homeownership_rate(1)=", model_homeownership_rate(1)
                        
                        distance_rent_to_price=0
                        
                    else
                        
                        distance_advantage_to_owning=0
                        distance_rent_to_price=0
                            
                    end if
                        
                    write(*,*) "relative_share_of_housing=", relative_share_of_housing 
                    
                    if (target_renters_rent_to_income==1) then
                                        
                        ! Raising gamma makes housing worth more against
                        ! consumption and the drug, so the household buys more of
                        ! it and the rent to income ratio RISES. A model above
                        ! target therefore calls for a smaller gamma.
                        !
                        ! THE DAMPING GOES ON THIS BRANCH, because this is the one
                        ! that runs: target_renters_rent_to_income is one. It was
                        ! first put on the else, where it compiled, printed
                        ! nothing and did nothing, and the only way to see that
                        ! was that its adjuster never appeared in the log beside
                        ! the other eight.
                        call damp_on_flip(relative_share_of_housing_adjuster,&
                            model_avg_housing_spending_renters(1)-avg_rent_to_income_data,&
                            previous_gap_relative_share_of_housing,have_gap_relative_share_of_housing,&
                            relative_share_of_housing_adjuster_start,damp_adjuster_floor)
                        write(*,*) "relative_share_of_housing_adjuster=", relative_share_of_housing_adjuster
                        if (tie_gamma_to_theta==0) relative_share_of_housing=&
                            min(max(relative_share_of_housing-relative_share_of_housing_adjuster*&
                            (model_avg_housing_spending_renters(1)-avg_rent_to_income_data),0.01),0.9) 
                                                                     
                        ! WHILE THE TIE IS ON, gamma is not being calibrated and its
                        ! moment is not a miss: it is whatever 0.28*(1-theta)
                        ! gives. A live distance would keep the joint loop running
                        ! on a bracket that is switched off.
                        if (tie_gamma_to_theta==1) distance_relative_share_of_housing=0
                        if (tie_gamma_to_theta==0) distance_relative_share_of_housing=&
                            abs(model_avg_housing_spending_renters(1)-avg_rent_to_income_data)
                                    
                        ! THE LABEL SAID "all" AND THE VARIABLE IS THE RENTERS
                        ! SERIES, and the other print of that label further down
                        ! the loop really is the all households one. Two different
                        ! quantities under one name, differing by more than a
                        ! factor of two, and a reading keyed on the label picked
                        ! whichever came first: it made gamma's moment look like
                        ! 0.45 against a target of 0.268 when it is 0.19, which
                        ! reverses which way gamma has to move.
                        write(*,*) "model_avg_housing_spending_renters=", &
                            model_avg_housing_spending_renters(1)
                            
                    else
                    
                        if (tie_gamma_to_theta==0) relative_share_of_housing=&
                            min(max(relative_share_of_housing-relative_share_of_housing_adjuster*&
                            (mass_of_renters_at_housing_spending(1,1)-SW_renters_spend_over_X_on_hous_2),0.01),0.9) 
                                                                     
                        distance_relative_share_of_housing=&
                            abs(mass_of_renters_at_housing_spending(1,1)-SW_renters_spend_over_X_on_hous_2)
                                    
                        write(*,*) "mass_of_renters_at_housing_spending(1,1)=", mass_of_renters_at_housing_spending(1,1)
                    
                    end if
                                                 
                    write(*,*) "relative_share_of_housing=", relative_share_of_housing 
                    write(*,*) "distance_relative_share_of_housing=", distance_relative_share_of_housing
                                        
                    write(*,*) "relative_share_of_housing=", relative_share_of_housing 
                                    
                    ! MULTIPLICATIVE, BECAUSE THE PARAMETER AND ITS MOMENT ARE NOT ON
                    ! THE SAME SCALE. The moment is a share of hours, bounded in
                    ! [0,1], so the gap can never exceed 0.4 in magnitude, while
                    ! the weight sits around 6.5. An additive step of
                    ! adjuster times gap is therefore at most 0.2 on a parameter
                    ! of 6.5, about three per cent a loop, and it does not care
                    ! how far away the moment is.
                    !
                    ! Measured: 6.786, 6.598, 6.411, falling 0.19 a loop while
                    ! labour supply sat at 0.025 against a target of 0.4. Not
                    ! stuck, and not a corner either — only two per cent of
                    ! households choose zero hours, so there is no grid to blame.
                    ! Just a rule that would need about thirty more loops, six
                    ! hours of wall clock, to cover ground a proportional step
                    ! covers in four.
                    !
                    ! Normalising the gap by the target makes the step
                    ! proportional to the parameter, which is what a scale-free
                    ! weight calls for, and the damping keeps it from ringing once
                    ! it arrives. Direction is unchanged: a model below target
                    ! still lowers the weight.
                    call damp_on_flip(relative_share_of_leisure_adjuster,&
                        model_labor_supply(1)/model_total_hours(1)-avg_labor_supply_data,&
                        previous_gap_relative_share_of_leisure,have_gap_relative_share_of_leisure,&
                        relative_share_of_leisure_adjuster_start,damp_adjuster_floor)
                    write(*,*) "relative_share_of_leisure_adjuster=", relative_share_of_leisure_adjuster
                    relative_share_of_leisure=&
                        min(max(relative_share_of_leisure*&
                        (1+relative_share_of_leisure_adjuster*&
                        (model_labor_supply(1)/model_total_hours(1)-avg_labor_supply_data)/&
                        max(avg_labor_supply_data,10.d0**(-12))),0.01),1000.d0) 
                                                                 
                    distance_relative_share_of_leisure=&
                        (1-freeze_relative_share_of_leisure)*&
                        abs(model_labor_supply(1)/model_total_hours(1)-avg_labor_supply_data)
                                
                    write(*,*) "model_labor_supply(1)/model_total_hours(1)=", &
                        model_labor_supply(1)/model_total_hours(1)

                    ! LABELLED WITH THE PARAMETER THEY ACTUALLY CARRY. These two
                    ! printed the LEISURE weight under the HOUSING label and then
                    ! repeated the housing distance, so the log showed
                    ! relative_share_of_housing taking two different values a line
                    ! apart, one of them 7.85 against a parameter bounded at 0.9.
                    ! It also corrupts export_moments.py, which takes the last
                    ! printed value for a label, so the housing weight in the
                    ! paper would have been the leisure weight.
                    write(*,*) "relative_share_of_leisure=", relative_share_of_leisure
                    write(*,*) "distance_relative_share_of_leisure=", distance_relative_share_of_leisure
                                             
                    write(*,*) "housing_status_grid_expander=", housing_status_grid_expander
                        
                    if (calibrate_size_of_smallest_house_hhld_can_buy==1) then

                        ! RETARGETED ONTO THE SIZE DISTRIBUTION. This used to be
                        ! bracketed on the homeownership rate against the SCF's
                        ! 0.659, which is a dead moment now: include_homeownership
                        ! is zero, so model_homeownership_rate is identically zero
                        ! and the update drove the expander with a constant gap of
                        ! -0.659 every iteration. The expander sets the curvature
                        ! of the grid between the smallest and largest sizes, so
                        ! the share in the LARGEST size is what it actually
                        ! identifies.
                        !
                        ! THE LARGEST SIZE CARRIES THIS MOMENT, not the expander.
                        ! Three shares have two free numbers in them, so two size
                        ! parameters identify them and a third would be chasing the
                        ! same target: h0 takes the smallest share, h2 the largest,
                        ! and the middle follows. The expander is SET at its
                        ! starting curvature. It was tried on this moment first and
                        ! it cannot reach it, because what empties the largest unit
                        ! is the LEVEL of h2 rather than the curvature between h0
                        ! and h2: raising the expander from 1.8 to 2.17 moved the
                        ! largest share from 6 per cent to zero rather than towards
                        ! 62.7.
                        ! ZEROED AT ONE RENTAL for the same reason: the single
                        ! unit's share is 1.0 by construction, so this gap would be
                        ! a constant 0.373 driving largest_house_size forever.
                        gap_house_size_1=merge(&
                            model_housing_size_dist(1,housing_status_grid_size-1)-&
                            housing_size_dist_data(2),0.d0,housing_status_grid_size>2)

                        if (have_gap_largest_house_size==1) then

                            if ((gap_house_size_1*previous_gap_largest_house_size)<0) then

                                largest_house_size_adjuster=&
                                    max(largest_house_size_adjuster*house_size_adjuster_damping,&
                                    house_size_adjuster_floor)

                            else

                                largest_house_size_adjuster=&
                                    min(largest_house_size_adjuster*house_size_adjuster_growth,&
                                    largest_house_size_adjuster_start)

                            end if

                        end if

                        previous_gap_largest_house_size=gap_house_size_1
                        have_gap_largest_house_size=1

                        write(*,*) "largest_house_size_adjuster=", largest_house_size_adjuster

                        largest_house_size=&
                            min(max(largest_house_size+largest_house_size_adjuster*&
                            gap_house_size_1,0.02d0),1.d0)

                        distance_largest_house_size=&
                            abs(model_housing_size_dist(1,housing_status_grid_size-1)-&
                            housing_size_dist_data(2))

                        write(*,*) "largest_house_size=", largest_house_size
                        write(*,*) "distance_largest_house_size=", distance_largest_house_size

                        ! THE CURVATURE, ON THE MIDDLE CATEGORY'S SHARE, which
                        ! is h_3's own moment and nobody else's.
                        !
                        ! Each rung of the ladder now answers to one moment. h_2
                        ! is the cheapest dwelling and is set by the employed
                        ! share of the homeless, because the price of that rung
                        ! is what decides whether a working household can be
                        ! housed at all. h_4 is set by the share at the top size.
                        ! That leaves h_3, and the share living in the middle
                        ! unit is the moment left over for it.
                        !
                        ! This used to run on the SMALLEST category's share. With
                        ! largest_house_size holding the top share the two are
                        ! the same fixed point, because the three shares add to
                        ! one, so nothing about the calibrated ladder moves. What
                        ! moves is the attribution: the smallest category's share
                        ! is not h_2's moment any more, and pointing the curvature
                        ! at it was aiming a rung at a share the rung below owns.
                        !
                        ! THE SIGN FLIPS WITH THE MOMENT. Raising the expander
                        ! pulls h_3 down toward h_2 (h_3 = h_2 + (h_4-h_2)/2**e),
                        ! so the middle unit gets cheaper and takes households off
                        ! the bottom rung: share(0) falls and share(1) rises. The
                        ! old update added the gap, which is right for a moment
                        ! that falls in e; this one subtracts it.
                        ! INDEX 1 IS OUT OF BOUNDS AT ONE RENTAL. This array is
                        ! dimensioned 0:housing_status_grid_size-1, which is 0:0
                        ! once h_3 and h_4 are gone, and this line read index 1.
                        ! The index is clamped so the access is legal and the gap
                        ! is forced to zero below two rungs, so the expander
                        ! cannot be driven by a rung that does not exist.
                        gap_housing_status_grid_expander=merge(&
                            model_housing_size_dist(1,min(1,housing_status_grid_size-1))-&
                            housing_size_dist_data(1),0.d0,housing_status_grid_size>2)

                        call damp_on_flip(housing_status_grid_expander_adjuster,&
                            gap_housing_status_grid_expander,&
                            previous_gap_housing_status_grid_expander,&
                            have_gap_housing_status_grid_expander,&
                            housing_status_grid_expander_adjuster_start,&
                            housing_status_grid_expander_floor)

                        housing_status_grid_expander=&
                            min(max(housing_status_grid_expander-&
                            housing_status_grid_expander_adjuster*&
                            gap_housing_status_grid_expander,1.d0),5.d0)

                        ! SAME CLAMP AS THE GAP ABOVE. This second index-1 read
                        ! was missed when the gap was fixed and the bounds build
                        ! caught it: the array is 0:housing_status_grid_size-1,
                        ! which is 0:0 at one rental. The distance is forced to
                        ! zero below two rungs so the convergence test cannot be
                        ! held open by a rung that does not exist.
                        distance_housing_status_grid_expander=merge(&
                            abs(model_housing_size_dist(1,min(1,housing_status_grid_size-1))-&
                            housing_size_dist_data(1)),0.d0,housing_status_grid_size>2)

                        write(*,*) "housing_status_grid_expander=", housing_status_grid_expander, &
                            " distance_housing_status_grid_expander=", &
                            distance_housing_status_grid_expander

                        distance_rent_to_price=0
                                                
                    else
                    
                        distance_housing_status_grid_expander=0
                        distance_rent_to_price=0
                        
                    end if
                    
                    if ((calibrate_size_of_smallest_house_hhld_can_buy==0) .AND. &
                        (advantage_to_owning_adjuster==0)) then
                        
                        write(*,*) "rent(1)/housing_price=", rent(1,:)/housing_price(1)
                        
                        distance_rent_to_price=(1-fix_rent)*abs(model_homeownership_rate(1)-SCF_homeownership_rate)
                            
                        if (fix_rent==0) then
                            rent(1,:)=rent(1,:)-rent_to_price_adjuster*&
                                (model_homeownership_rate(1)-SCF_homeownership_rate)
                        end if
                        
                        write(*,*) "rent(1)/housing_price=", rent(1,:)/housing_price(1)
                        write(*,*) "distance_rent_to_price=", distance_advantage_to_owning
                        write(*,*) "model_homeownership_rate(1)=", model_homeownership_rate(1)
                        
                    else
                    
                        write(*,*) "rent(1)=", rent(1,:)
                    
                        if (fix_rent==0) then
                            rent(1,:)=rent(1,:)-rent_to_price_adjuster*&
                                (rent(1,:)/housing_price(1)-rent_to_housing_price)
                        end if
                            
                        write(*,*) "rent(1)=", rent(1,:)
                            
                    end if
                    
                    write(*,*) "size_of_smallest_house_hhld_can_buy=", size_of_smallest_house_hhld_can_buy
                    write(*,*) "housing_status_grid_expander=", housing_status_grid_expander
                    write(*,*) "housing_size(index_of_smallest_house_hhld_can_buy)=", &
                        housing_size(max(min(index_of_smallest_house_hhld_can_buy,housing_status_grid_size-1),lowest_housing_grid_point))
                    write(*,*) "model_fraction_of_homeowners_with_mortgage(1)=", model_fraction_of_homeowners_with_mortgage(1)
                    
                    if ((mortgage_deductibility>0) .OR. (property_tax_deductibility>0)) then
                    
                        write(*,*) "govt_spending_on_mortgage_interest_deductions(1)/model_GDP_incl_imput_rent(1)=", &
                            100*(govt_spending_on_mortgage_interest_deductions(1)/model_GDP_incl_imput_rent(1))
                            
                    end if
                    
                    write(*,*) "smallest_rental_relative_to_lowest_income=", smallest_rental_relative_to_lowest_income                    
                    
                    if (calibrate_smallest_house_size==1) then

                        ! THE SMALLEST RENTAL TARGETS THE SHARE LIVING IN THE
                        ! SMALLEST UNIT. It used to target the employed share of
                        ! the homeless, and that target could not be had at the
                        ! same time as the homelessness RATE, because both were
                        ! being asked of this one parameter and they wanted
                        ! values six to eight times apart. The run measured it:
                        !
                        !   h_2      room as a share    homelessness   employed
                        !            of poorest income      rate       share
                        !   0.0158        45.9%           0.0075        0.934
                        !   0.0048        13.0%           0.00045       0.978
                        !   0.0015         5.3%           0.0000068     0.499
                        !
                        ! The 0.50 employed share needs 0.0015, where the
                        ! cheapest room costs five per cent of the poorest
                        ! household's income and essentially nobody is priced out
                        ! of housing, so homelessness collapses to six hundred
                        ! times below target and h_1 cannot recover it: making
                        ! the street relatively worse cannot put people on it
                        ! when a room is nearly free.
                        !
                        ! The size distribution's bottom rung is the moment this
                        ! parameter can actually carry, and it agrees with the
                        ! homelessness rate about where h_2 belongs. Measured
                        ! across the run, the share on the smallest rung rises
                        ! monotonically in h_2 -- 0.004 at 0.0015, 0.048 at
                        ! 0.0048, 0.236 at 0.0144, 0.398 at 0.0169 -- and crosses
                        ! its target of 0.132 near h_2 = 0.011, which is also
                        ! where the homelessness rate wants it.
                        !
                        ! THE SIGN IS UNCHANGED, and that is not luck: the share
                        ! rises in h_2 and the update subtracts the gap, so a
                        ! share below target raises h_2, which is the direction
                        ! the table above shows.
                        !
                        ! THE EMPTY SET GUARD IS GONE WITH THE OLD MOMENT. The
                        ! size distribution is taken over HOUSED households, who
                        ! are never absent, so there is no conditional mean over
                        ! a vanishing population to protect against here. Leaving
                        ! the guard in would have frozen h_2 at exactly the point
                        ! it is needed, since homelessness is near zero now.
                        write(*,*) "model_housing_size_dist=", model_housing_size_dist(1,:)
                        write(*,*) "housing_size_dist_data=", housing_size_dist_data
                        write(*,*) "smallest_rental_relative_to_lowest_income=", &
                            smallest_rental_relative_to_lowest_income

                        gap_house_size_1=&
                            model_housing_size_dist(1,0)-housing_size_dist_data(0)

                        if (have_gap_smallest_house_size==1) then

                            if ((gap_house_size_1*previous_gap_smallest_house_size)<0) then

                                smallest_house_size_adjuster=&
                                    max(smallest_house_size_adjuster*house_size_adjuster_damping,&
                                    house_size_adjuster_floor)

                            else

                                smallest_house_size_adjuster=&
                                    min(smallest_house_size_adjuster*house_size_adjuster_growth,&
                                    smallest_house_size_adjuster_start)

                            end if

                        end if

                        previous_gap_smallest_house_size=gap_house_size_1
                        have_gap_smallest_house_size=1

                        write(*,*) "smallest_house_size_adjuster=", smallest_house_size_adjuster

                        smallest_rental_relative_to_lowest_income=&
                            min(max(smallest_rental_relative_to_lowest_income-smallest_house_size_adjuster*&
                            gap_house_size_1,smallest_rental_floor),10.d0) 
                                                                     
                        distance_smallest_house_size=&
                            abs(model_housing_size_dist(1,0)-housing_size_dist_data(0))

8801                    continue
                                                         
                    else
                    
                        distance_smallest_house_size=0
                    
                    end if
                    
                    write(*,*) "smallest_rental_relative_to_lowest_income=", smallest_rental_relative_to_lowest_income
                    write(*,*) "mass_of_renters_at_housing_spending=", &
                        mass_of_renters_at_housing_spending(1,target_30_perc*1+(1-target_30_perc)*2)
                        
                    write(*,*) "labor_income_tax_rate=", labor_income_tax_rate

                    ! THE PLUS IS CORRECT AND THE NAME IS NOT. labor_income_tax_rate
                    ! is the RETENTION SCALE in the tax function
                    !
                    !     tax = y - labor_income_tax_rate * y**curvature
                    !
                    ! so it multiplies income KEPT, not income taken. Raising it
                    ! lowers the average effective tax rate, which is why an
                    ! average tax above target is met by raising this number. Its
                    ! declared value of 0.75 only makes sense read that way; as a
                    ! marginal rate it would be absurd. Anyone auditing signs from
                    ! the variable names will read this one as inverted and be
                    ! wrong, which is why the note is here rather than nowhere.
                    call damp_on_flip(labor_income_tax_rate_adjuster,&
                        model_average_labour_income_tax(1)-average_labor_income_tax_data,&
                        previous_gap_labor_income_tax_rate,have_gap_labor_income_tax_rate,&
                        labor_income_tax_rate_adjuster_start,damp_adjuster_floor)
                    write(*,*) "labor_income_tax_rate_adjuster=", labor_income_tax_rate_adjuster
                    labor_income_tax_rate=max(min(labor_income_tax_rate+labor_income_tax_rate_adjuster*&
                        (model_average_labour_income_tax(1)-average_labor_income_tax_data),2.d0),0.d0)

                    distance_labor_income_tax_rate=&
                        abs(model_average_labour_income_tax(1)-average_labor_income_tax_data)

                    write(*,*) "average labour income tax rate =", model_average_labour_income_tax(1),&
                        " against ", average_labor_income_tax_data,&
                        " distance_labor_income_tax_rate=", distance_labor_income_tax_rate

                    if ((labor_income_tax_rate<=10.d0**(-8)) .OR. (labor_income_tax_rate>=2.d0-10.d0**(-8))) then

                        write(*,*) "the retention scale IS PINNED AT A BOUND", labor_income_tax_rate,&
                            " and the average labour income tax rate is ", model_average_labour_income_tax(1),&
                            " against ", average_labor_income_tax_data

                    end if
                        
                    write(*,*) "labor_income_tax_rate=", labor_income_tax_rate
                                                            
                    if (mortgage_deductibility==1) then
                    
                        write(*,*) "fraction_using_MID(1)=", fraction_using_MID(1)
                        write(*,*) "standard_deduction_as_percent_of_average_labor_income=", &
                            standard_deduction_as_percent_of_average_labor_income
                    
                        standard_deduction_as_percent_of_average_labor_income=&
                            max(min(standard_deduction_as_percent_of_average_labor_income+&
                            standard_deduction_adjuster*&
                            (100*(govt_spending_on_mortgage_interest_deductions(1)/model_GDP_incl_imput_rent(1))-&
                            MID_to_GDP_data),1.d0),0.d0)
                            
                        distance_standard_deduction=&
                            abs(100*(govt_spending_on_mortgage_interest_deductions(1)/model_GDP_incl_imput_rent(1)))
                            
                        write(*,*) "standard_deduction_as_percent_of_average_labor_income=", &
                            standard_deduction_as_percent_of_average_labor_income
                        write(*,*) "distance_standard_deduction=", distance_standard_deduction
                    
                    else
                        
                        distance_standard_deduction=0
                        standard_deduction_as_percent_of_average_labor_income=0 !0.08
                    
                    end if
                                        
                    if (fixed_cost_to_moving_adjuster>0)  then
                    
                        write(*,*) "fixed_cost_to_moving=", fixed_cost_to_moving
                                
!                        fixed_cost_to_moving=max(min(fixed_cost_to_moving-fixed_cost_to_moving_adjuster*&
!                            (model_years_in_same_rental(1,2)-average_years_in_same_rental_data),1.d0),0.d0)
!                            
!                        distance_fixed_cost_to_moving=abs(model_years_in_same_rental(1,2)-average_years_in_same_rental_data)
                            
                        write(*,*) "fixed_cost_to_moving=", fixed_cost_to_moving
                        write(*,*) "distance_fixed_cost_to_moving=", distance_fixed_cost_to_moving
                    
                    else
                    
                        distance_fixed_cost_to_moving=0
                    
                    end if
                                        
                    ! LAMBDA on the substance use disorder rate.
                    write(*,*) "model_fraction_addicted(1)=", model_fraction_addicted(1)
                    write(*,*) "sud_rate_data=", sud_rate_data
                    write(*,*) "probability_of_becoming_addicted_if_experiment=", &
                        probability_of_becoming_addicted_if_experiment

                    if (smooth_addiction_hazard==1) then

                        ! LAMBDA IS BRACKETED THROUGH THE ONSET AT THE MEAN
                        ! QUANTITY, not directly, and that is what makes the
                        ! bracket transferable.
                        !
                        ! lambda is a hazard per unit of drug, so its scale is
                        ! whatever the model's consumption units happen to be and
                        ! an adjuster tuned at one calibration would be wrong at
                        ! the next. The onset a mean user faces,
                        ! 1-exp(-lambda vbar), is a probability whatever the
                        ! units, it is monotone in lambda, and it is the same
                        ! object the flat hazard was: so the update runs on it
                        ! with the step and the bracket the flat hazard already
                        ! used, and lambda is recovered by inverting at the
                        ! model's own mean. Nothing is left to depend on a guess
                        ! about scale except the very first backward pass.
                        !
                        ! Sign is unchanged: a higher hazard means more of the
                        ! people who use acquire the disorder, so prevalence
                        ! rises in it and the update subtracts the gap.
                        mean_drug_quantity_1=model_drugs_used_by_users_on_average(1)

                        if (mean_drug_quantity_1>0) then

                            ! THROUGH THE FUNCTION, not the bare exponential. This
                            ! drives the SECANT that calibrates lambda_addiction, so
                            ! with addiction_onset_base live the bare form would have
                            ! it solving for a hazard the model does not use.
                            onset_at_mean_1=addiction_onset_hazard(mean_drug_quantity_1)

                            ! SECANT ON THE ONSET, NOT A FIXED STEP, and the
                            ! first step comes from the flow balance rather than
                            ! from the adjuster.
                            !
                            ! An equilibrium is hours, so the number of loops IS
                            ! the calibration time and a fixed step that has to
                            ! creep is the wrong instrument. Two things fix it.
                            !
                            ! THE FIRST STEP IS ANALYTIC. In the stationary
                            ! distribution the disorder is a two state flow
                            ! balance: onset times the mass using equals recovery
                            ! times the mass carrying it, so prevalence is very
                            ! nearly proportional to the onset at a given share
                            ! who use. Scaling the onset by the ratio of target
                            ! to model prevalence therefore lands close on the
                            ! first try, where the fixed step would have taken
                            ! twenty loops to cover the same ground when the
                            ! model came in at nine times the data.
                            !
                            ! AFTER THAT IT IS A SECANT. Two (onset, prevalence)
                            ! pairs give the local slope, which is what the
                            ! proportionality above only approximates once the
                            ! share who use responds to the hazard as well. The
                            ! step is clipped to a factor of four either way so a
                            ! flat or noisy secant cannot throw lambda across the
                            ! bracket, and it falls back to the proportional rule
                            ! whenever the two prevalences are too close to
                            ! divide by.
                            ! AND THE SECANT IS ONLY READ WHEN ITS SLOPE HAS THE SIGN THE
                            ! MODEL GUARANTEES. Prevalence rises in the onset hazard with
                            ! everything else held fixed, so a measured slope that is
                            ! negative is not news about the model, it is a reading taken
                            ! through another instrument's move. This loop is Gauss-Seidel:
                            ! b moved in the same pass, and when it moves participation by
                            ! more than the hazard moves conversion the difference in
                            ! prevalence carries b's sign, not lambda's.
                            !
                            ! WHAT WAS ACTUALLY MEASURED ON THE RUN THIS GUARD WAS ADDED
                            ! FOR, since the first reading of it was wrong and the wrong
                            ! reading is the more tempting one. Prevalence fell from 5.79e-4
                            ! to 7.31e-6 while b cut participation thirteenfold in the same
                            ! loop, and it looked as though the secant had inverted. It had
                            ! not. onset_at_mean is recomputed each loop at the MODEL'S OWN
                            ! mean quantity, and that mean collapsed from 1.09e-2 to 1.19e-3
                            ! along with participation, so the onset fell from 1.19e-3 to
                            ! 1.30e-4 even though lambda QUADRUPLED, from 0.1095 to 0.4381,
                            ! which is its clamp. The slope came out at +1.86, the secant
                            ! was not rejected, and it asked for an onset of 0.0685 that the
                            ! clamp cut to four times the current one. Lambda was pushing as
                            ! hard as it is allowed to, in the right direction, the whole
                            ! time.
                            !
                            ! So the collapse was b's alone, and b's damping is what fixes
                            ! it. The lesson lambda carries is a different one: a hazard
                            ! clipped to a factor of four a loop cannot hold prevalence
                            ! while another instrument moves the population it acts on by a
                            ! factor of thirteen. Damping b is what makes lambda's clamp
                            ! sufficient.
                            !
                            ! The slope test stays, because a contaminated slope CAN come
                            ! out negative and there is nothing to be gained from stepping
                            ! on it. It is a safeguard against a case that can arise and not
                            ! a fix for one that did. A rejected secant falls back to the
                            ! proportional rule, which cannot point the wrong way: it scales
                            ! the hazard by target over model and both are positive.
                            !
                            ! WORTH KNOWING WHEN READING THE SECANT AT ALL: because the two
                            ! onsets are measured at two different mean quantities, the
                            ! slope is not a clean derivative of prevalence in the hazard.
                            ! It mixes in the change in how much users buy. That is a
                            ! consequence of calibrating the onset at the mean rather than
                            ! calibrating lambda directly, which is deliberate and is
                            ! explained above, but it means the secant is an approximation
                            ! and should be read as one.
                            lambda_secant_slope_1=0

                            if (abs(model_fraction_addicted(1)-previous_sud_rate)>10.d0**(-12)) then

                                lambda_secant_slope_1=(onset_at_mean_1-previous_onset_at_mean)/&
                                    (model_fraction_addicted(1)-previous_sud_rate)

                            end if

                            if ((have_lambda_secant==1) .AND. &
                                (abs(model_fraction_addicted(1)-previous_sud_rate)>10.d0**(-6)) .AND. &
                                (abs(onset_at_mean_1-previous_onset_at_mean)>10.d0**(-12)) .AND. &
                                (lambda_secant_slope_1>0)) then

                                onset_step_1=onset_at_mean_1-&
                                    (model_fraction_addicted(1)-sud_rate_data)*&
                                    lambda_secant_slope_1

                            elseif (model_fraction_addicted(1)>10.d0**(-8)) then

                                if ((have_lambda_secant==1) .AND. (lambda_secant_slope_1<=0) .AND. &
                                    (abs(model_fraction_addicted(1)-previous_sud_rate)>10.d0**(-6))) then

                                    write(*,*) "lambda secant REJECTED, slope=", lambda_secant_slope_1, &
                                        ": prevalence moved against the hazard, so another instrument",&
                                        " moved more than this one. Falling back to the proportional rule."

                                end if

                                onset_step_1=onset_at_mean_1*&
                                    (sud_rate_data/model_fraction_addicted(1))

                            else

                                onset_step_1=onset_at_mean_1-&
                                    lambda_addiction_adjuster*&
                                    (model_fraction_addicted(1)-sud_rate_data)

                            end if

                            gap_lambda_addiction_1=model_fraction_addicted(1)-sud_rate_data

                            if (have_gap_lambda_addiction==1) then

                                if ((gap_lambda_addiction_1*previous_gap_lambda_addiction)<0) then

                                    lambda_clamp=max(1+(lambda_clamp-1)*0.5d0,lambda_clamp_floor)

                                else

                                    lambda_clamp=min(1+(lambda_clamp-1)*1.2d0,lambda_clamp_start)

                                end if

                            end if

                            previous_gap_lambda_addiction=gap_lambda_addiction_1
                            have_gap_lambda_addiction=1

                            write(*,*) "lambda_clamp=", lambda_clamp

                            lambda_move_1=max(lambda_clamp,&
                                move_factor(model_fraction_addicted(1),&
                                sud_rate_data,escape_factor))
                            write(*,*) "MOVE MODE lambda_addiction=", lambda_move_1
                            onset_step_1=max(min(onset_step_1,lambda_move_1*onset_at_mean_1),&
                                onset_at_mean_1/lambda_move_1)

                            previous_onset_at_mean=onset_at_mean_1
                            previous_sud_rate=model_fraction_addicted(1)
                            have_lambda_secant=1

                            onset_at_mean_1=max(min(onset_step_1,0.2d0),1.d0*10.d0**(-5))

                            lambda_addiction=-log(1-onset_at_mean_1)/mean_drug_quantity_1

                            write(*,*) "model_drugs_used_by_users_on_average(1)=", mean_drug_quantity_1
                            write(*,*) "onset_at_the_mean_quantity=", onset_at_mean_1

                        else

                            write(*,*) "no drug use at all, lambda left where it is"

                        end if

                        distance_lambda_addiction=&
                            abs(model_fraction_addicted(1)-sud_rate_data)

                        ! The flat hazard is not calibrated alongside it. Two
                        ! parameters on one moment is not identification, it is a
                        ! race, and with the smooth form on the flat number is
                        ! read only where the household abstains, where it is
                        ! multiplied by zero.
                        distance_probability_of_becoming_addicted=0

                        write(*,*) "lambda_addiction=", lambda_addiction
                        write(*,*) "distance_lambda_addiction=", distance_lambda_addiction

                    else

                        probability_of_becoming_addicted_if_experiment=&
                            max(min(probability_of_becoming_addicted_if_experiment-&
                            probability_of_becoming_addicted_adjuster*&
                            (model_fraction_addicted(1)-sud_rate_data),0.2d0),1.d0*10.d0**(-5))

                        distance_probability_of_becoming_addicted=&
                            abs(model_fraction_addicted(1)-sud_rate_data)

                        distance_lambda_addiction=0

                        write(*,*) "probability_of_becoming_addicted_if_experiment=", &
                            probability_of_becoming_addicted_if_experiment
                        write(*,*) "distance_probability_of_becoming_addicted=", &
                            distance_probability_of_becoming_addicted

                    end if

                    ! THE UTILITY COST OF TREATMENT, on take up given a SUD.
                    !
                    ! Sign: a higher cost means fewer households take treatment,
                    ! so take up FALLS in it and the update adds the gap. Same
                    ! secant as lambda and rent, for the same reason: the number
                    ! of loops is the calibration time.
                    !
                    ! Take up is bounded in [0,1] and the cost is in utils, so
                    ! the fallback step is a fixed one on the gap rather than a
                    ! proportional rule, which would be meaningless at a take up
                    ! of zero.
                    if (include_treatment==1) then

                        write(*,*) "model_treatment_take_up(1)=", model_treatment_take_up(1)
                        write(*,*) "treatment_take_up_data=", treatment_take_up_data
                        write(*,*) "utility_cost_of_treatment=", utility_cost_of_treatment

                        ! THE SIGN. Take up FALLS in the cost: the cost is
                        ! subtracted from flow utility in the period treatment is
                        ! taken, so raising it makes treatment less attractive.
                        ! The step therefore has to move the cost AGAINST the
                        ! gap, not with it. Written with a plus, as it was, a
                        ! take up below target raised the cost, which lowered take
                        ! up further, which raised the cost again: measured over
                        ! thirteen iterations the cost ratcheted from 0.020 to
                        ! 0.151 in exact steps of adjuster*(0.24-0) = 0.012 while
                        ! take up sat at zero throughout. The secant below cannot
                        ! rescue it, because a take up that never moves fails the
                        ! guard on its own change and the fallback runs every
                        ! time. This is the same error as the kappa_uem update,
                        ! which was also copied from a moment that runs the other
                        ! way.
                        treatment_step_1=utility_cost_of_treatment-&
                            utility_cost_of_treatment_adjuster*&
                            (treatment_take_up_data-model_treatment_take_up(1))

                        if ((have_treatment_secant==1) .AND. &
                            (abs(model_treatment_take_up(1)-previous_treatment_take_up)>10.d0**(-6)) .AND. &
                            (abs(utility_cost_of_treatment-previous_utility_cost_of_treatment)>10.d0**(-10))) then

                            treatment_step_1=utility_cost_of_treatment-&
                                (model_treatment_take_up(1)-treatment_take_up_data)*&
                                (utility_cost_of_treatment-previous_utility_cost_of_treatment)/&
                                (model_treatment_take_up(1)-previous_treatment_take_up)

                        end if

                        previous_utility_cost_of_treatment=utility_cost_of_treatment
                        previous_treatment_take_up=model_treatment_take_up(1)
                        have_treatment_secant=1

                        call trust_step(treatment_step_1,utility_cost_of_treatment,&
                            move_factor(model_treatment_take_up(1),&
                            treatment_take_up_data,escape_factor),10.d0**(-2))
                        write(*,*) "MOVE MODE utility_cost_of_treatment=",&
                            move_factor(model_treatment_take_up(1),&
                            treatment_take_up_data,escape_factor)
                        utility_cost_of_treatment=max(min(treatment_step_1,10.d0),0.d0)

                        ! ZEROED WHEN THE ADJUSTER IS ZERO, OR THE LOOP CANNOT EXIT.
                        ! utility_cost_of_treatment_adjuster is 0, so the step below
                        ! cannot move the parameter, so this distance can never fall
                        ! below its stopping rule -- and it sits in the do while
                        ! condition, so the calibration loop ran to its iteration cap
                        ! on every point and stopped with the OTHER distances wherever
                        ! they happened to be, rather than converged.
                        !
                        ! tau_u is owned externally by next_batch.py through
                        ! utility_cost_of_treatment, so the moment is not abandoned;
                        ! it is calibrated across points instead of inside the loop.
                        ! This is the same shape as freeze_fitted_internals: an
                        ! adjuster at zero must take its distance out of the
                        ! convergence test with it.
                        distance_utility_cost_of_treatment=&
                            merge(0.d0,abs(model_treatment_take_up(1)-treatment_take_up_data),&
                            utility_cost_of_treatment_adjuster<=0.d0)

                        write(*,*) "utility_cost_of_treatment=", utility_cost_of_treatment
                        write(*,*) "distance_utility_cost_of_treatment=", &
                            distance_utility_cost_of_treatment

                        ! SAY SO WHEN THE COST CAN GO NO LOWER, the way the
                        ! lambda_m floor does. At a cost of zero treatment is free
                        ! in utils and still costs the household its drug
                        ! spending, since taking it forces abstention. So a take
                        ! up of zero here is not a failure of this update: it says
                        ! the benefit side is too small, which is g, mu_H, pi_r
                        ! and the abstention itself, and no value of bar_tau^u
                        ! reaches the target.
                        if ((utility_cost_of_treatment<=0.d0) .AND. &
                            (model_treatment_take_up(1)<treatment_take_up_data)) then

                            write(*,*) "utility_cost_of_treatment IS AT ITS FLOOR 0 and take up is ",&
                                model_treatment_take_up(1), " against a target of ", treatment_take_up_data
                            write(*,*) "   treatment is declined even when free, so the target is out of",&
                                " reach on the benefit side, not on the cost."

                        end if

                    ! MU_H, on the model's own increase in recovery from housing.
                    ! The ratio FALLS in mu_H, since mu_H is how good recovery on
                    ! the street is, so the step moves mu_H with the gap: a model
                    ! ratio above target means the street is too bad and mu_H rises.
                    if ((model_recovery_homeless(1)>0) .AND. (model_recovery_housed(1)>0)) then

                        write(*,*) "model recovery housed, homeless =",&
                            model_recovery_housed(1), model_recovery_homeless(1)
                        write(*,*) "model recovery ratio =",&
                            model_recovery_housed(1)/model_recovery_homeless(1),&
                            " target =", milby_recovery_ratio_data
                        write(*,*) "mu_homeless=", mu_homeless

                        mu_homeless=max(min(mu_homeless+mu_homeless_adjuster*&
                            (model_recovery_housed(1)/model_recovery_homeless(1)-&
                            milby_recovery_ratio_data),1.d0),10.d0**(-3))

                        distance_mu_homeless=&
                            abs(model_recovery_housed(1)/model_recovery_homeless(1)-&
                            milby_recovery_ratio_data)

                        write(*,*) "mu_homeless=", mu_homeless,&
                            " distance_mu_homeless=", distance_mu_homeless

                    else

                        ! No homeless household carries the disorder, so the
                        ! gradient has no denominator. Say so rather than dividing.
                        write(*,*) "mu_homeless HELD: no homeless household carries the disorder, so",&
                            " the recovery gradient cannot be measured this iteration"

                    end if

                    ! OMEGA, on how much drug use rises when the child term is off.
                    ! Use rises in the gap, and a LARGER omega means the parent
                    ! already internalises more, so switching the term off changes
                    ! more and the measured gap RISES in omega. A model gap above
                    ! target therefore calls for a smaller omega.
                    ! THE BASELINE HAS TO EXIST FOR THE GAP TO BE A GAP. With a
                    ! baseline using mass of 2.3e-4 the ratio came back as 325
                    ! against a target of 0.18 and omega went to zero in one step,
                    ! which is a statement about the denominator rather than about
                    ! how much a parent internalises. A tenth of the participation
                    ! rate the model is trying to reproduce is the floor.
                    if ((calibrate_weight_on_child==1) .AND. (drug_users_without_child>0)&
                        .AND. (model_total_drug_users(1)>&
                        10.d0**(-1)*participation_rate_data)) then

                        write(*,*) "drug users, baseline and child term off =",&
                            model_total_drug_users(1), drug_users_without_child

                        child_use_gap_1=drug_users_without_child/model_total_drug_users(1)-1

                        write(*,*) "model child use gap =",&
                            child_use_gap_1, " target =", child_use_gap_data
                        write(*,*) "weight_on_child=", weight_on_child

                        ! The step is taken on a clamped gap for the same reason
                        ! theta's is: the sign is informative long before the
                        ! magnitude is.
                        weight_on_child=max(min(weight_on_child-weight_on_child_adjuster*&
                            max(min(child_use_gap_1-child_use_gap_data,1.d0),-1.d0),&
                            1.d0),0.d0)

                        distance_weight_on_child=abs(child_use_gap_1-child_use_gap_data)

                        write(*,*) "weight_on_child=", weight_on_child,&
                            " distance_weight_on_child=", distance_weight_on_child

                    else if (calibrate_weight_on_child==1) then

                        write(*,*) "omega HELD: baseline users ", model_total_drug_users(1),&
                            " and users with the child term off ", drug_users_without_child,&
                            ": one of the two is too small for the gap to mean anything"
                        distance_weight_on_child=1

                    end if

                    ! DELTA_D, on the ratio of child disorder rates.
                    if (calibrate_penalty_child_addicted==1) then

                        child_sud_num_1=0
                        child_sud_den_1=0

                        do child_node_index_1=1,employment_grid_size

                            child_sud_num_1=child_sud_num_1+&
                                sum(newborn_parent_share(:,1,1)*newborn_employment_probability(child_node_index_1,:,1,1))/max(sum(newborn_parent_share(:,1,1)),10.d0**(-14))*&
                                percent_addicted_by_employment(1,child_node_index_1)

                            child_sud_den_1=child_sud_den_1+&
                                sum(newborn_parent_share(:,0,1)*newborn_employment_probability(child_node_index_1,:,0,1))/max(sum(newborn_parent_share(:,0,1)),10.d0**(-14))*&
                                percent_addicted_by_employment(1,child_node_index_1)

                        end do

                        if (child_sud_den_1>10.d0**(-10)) then

                            child_sud_ratio_model_1=child_sud_num_1/child_sud_den_1

                            gap_penalty_child_1=child_sud_ratio_model_1-child_sud_ratio_data

                            if (have_gap_penalty_child==1) then

                                ! AN ADJUSTER AT ZERO IS PINNED. Same rule as
                                ! damp_on_flip, written out inline, and the same
                                ! resurrection: max(0*damping, floor) is the
                                ! floor, so penalty_child_addicted -- declared
                                ! zero and commented "EXTERNALLY SET ... it
                                ! stopped being calibrated" -- would start
                                ! moving on the first sign flip.
                                if ((gap_penalty_child_1*previous_gap_penalty_child)<0 &
                                    .AND. (penalty_child_addicted_adjuster>0.d0)) then

                                    penalty_child_addicted_adjuster=&
                                        max(penalty_child_addicted_adjuster*penalty_child_adjuster_damping,&
                                        penalty_child_adjuster_floor)

                                else

                                    penalty_child_addicted_adjuster=&
                                        min(penalty_child_addicted_adjuster*penalty_child_adjuster_growth,&
                                        penalty_child_adjuster_start)

                                end if

                            end if

                            previous_gap_penalty_child=gap_penalty_child_1
                            have_gap_penalty_child=1

                            write(*,*) "child SUD ratio model =", child_sud_ratio_model_1,&
                                " target =", child_sud_ratio_data
                            write(*,*) "penalty_child_addicted=", penalty_child_addicted

                            ! A NINETY PER CENT CUT TO THE CHILD'S PRODUCTIVITY
                            ! IS NOT A PENALTY, IT IS A DIFFERENT MODEL. The cap
                            ! was 0.9 and the parameter sat on it, which
                            ! multiplies the child's productivity by a tenth and
                            ! lands every child of a parent with the disorder in
                            ! the bottom nodes of the grid. Two things follow and
                            ! both were visible in the output without the cause
                            ! being visible.
                            !
                            ! It manufactures a population of very low
                            ! productivity households who work and cannot afford
                            ! even the cheapest room, which is most of why the
                            ! employed share of the homeless would not come down
                            ! however far h_2 fell.
                            !
                            ! And it drives its OWN moment the wrong way. The
                            ! bottom of the grid has essentially no drug use, so
                            ! pushing the child further down lowers the child's
                            ! SUD rate; the ratio read 0.0027 against a target of
                            ! 3, the update read that as too low and raised the
                            ! penalty again, and it ran to the cap on the wrong
                            ! side of a relationship that is not monotone.
                            !
                            ! Forty per cent is the ceiling. penalty_child_homeless
                            ! is 0.31 and already inside it.
                            penalty_child_addicted=&
                                max(min(penalty_child_addicted-penalty_child_addicted_adjuster*&
                                gap_penalty_child_1,0.4d0),0.d0)

                            distance_penalty_child_addicted=abs(gap_penalty_child_1)

                            write(*,*) "penalty_child_addicted=", penalty_child_addicted,&
                                " distance_penalty_child_addicted=", distance_penalty_child_addicted

                            ! The newborn draw is built from this penalty, so it
                            ! has to be rebuilt now rather than at the next setup,
                            ! which never runs again.
                            call create_newborn_employment_probability()

                            if ((penalty_child_addicted<=10.d0**(-8)) .OR. &
                                (penalty_child_addicted>=0.9d0-10.d0**(-8))) then

                                write(*,*) "delta_d IS PINNED AT A BOUND", penalty_child_addicted,&
                                    " and the child SUD ratio is ", child_sud_ratio_model_1,&
                                    " against ", child_sud_ratio_data

                            end if

                        else

                            write(*,*) "child SUD ratio has an empty denominator: delta_d held at",&
                                penalty_child_addicted
                            distance_penalty_child_addicted=1

                        end if

                    else

                        distance_penalty_child_addicted=0

                    end if

                    ! DELTA_H, on the ratio of child homelessness rates. It
                    ! mirrors delta_d above: that one weights the newborn
                    ! productivity draw by the disorder rate at each node and
                    ! varies the parent's DISORDER at housed, this one weights by
                    ! the homelessness rate at each node and varies the parent's
                    ! HOMELESSNESS at clean. The third index is 1 for housed and
                    ! 2 for homeless, because the penalty's exponent is h_index-1.
                    if (calibrate_penalty_child_homeless==1) then

                        child_homeless_num_1=0
                        child_homeless_den_1=0

                        do child_node_index_1=1,employment_grid_size

                            child_homeless_num_1=child_homeless_num_1+&
                                sum(newborn_parent_share(:,0,2)*newborn_employment_probability(child_node_index_1,:,0,2))/max(sum(newborn_parent_share(:,0,2)),10.d0**(-14))*&
                                percent_homeless_by_employment(1,child_node_index_1)

                            child_homeless_den_1=child_homeless_den_1+&
                                sum(newborn_parent_share(:,0,1)*newborn_employment_probability(child_node_index_1,:,0,1))/max(sum(newborn_parent_share(:,0,1)),10.d0**(-14))*&
                                percent_homeless_by_employment(1,child_node_index_1)

                        end do

                        if (child_homeless_den_1>10.d0**(-10)) then

                            child_homeless_ratio_model_1=&
                                child_homeless_num_1/child_homeless_den_1

                            gap_penalty_child_homeless_1=&
                                child_homeless_ratio_model_1-child_homeless_ratio_data

                            call damp_on_flip(penalty_child_homeless_adjuster,&
                                gap_penalty_child_homeless_1,&
                                previous_gap_penalty_child_homeless,&
                                have_gap_penalty_child_homeless,&
                                penalty_child_homeless_adjuster_start,damp_adjuster_floor)

                            ! SIGN, STATED RATHER THAN INFERRED. The penalty
                            ! shifts the child DOWN the productivity grid, since
                            ! shifted_log adds log(penalty) and the penalty is
                            ! below one, and homelessness FALLS in productivity.
                            ! So the child's homelessness rate, and the ratio with
                            ! it, RISES in the penalty: a model ratio below target
                            ! calls for a larger penalty, which is what
                            ! subtracting the gap does.
                            penalty_child_homeless_step_1=penalty_child_homeless-&
                                penalty_child_homeless_adjuster*gap_penalty_child_homeless_1
                            call trust_step(penalty_child_homeless_step_1,&
                                penalty_child_homeless,&
                                move_factor(child_homeless_ratio_model_1,&
                                child_homeless_ratio_data,escape_factor),10.d0**(-3))
                            penalty_child_homeless=&
                                max(min(penalty_child_homeless_step_1,0.4d0),0.d0)

                            distance_penalty_child_homeless=&
                                abs(gap_penalty_child_homeless_1)

                            write(*,*) "child homelessness ratio model =",&
                                child_homeless_ratio_model_1,&
                                " target =", child_homeless_ratio_data
                            write(*,*) "penalty_child_homeless=", penalty_child_homeless,&
                                " distance_penalty_child_homeless=",&
                                distance_penalty_child_homeless

                            ! The newborn draw is built from this penalty too, so
                            ! it is rebuilt here for the same reason delta_d's is.
                            call create_newborn_employment_probability()

                        else

                            write(*,*) "child homelessness ratio has an empty denominator:",&
                                " delta_h held at", penalty_child_homeless
                            distance_penalty_child_homeless=1

                        end if

                    else

                        distance_penalty_child_homeless=0

                    end if


                    else

                        distance_utility_cost_of_treatment=0

                    end if

                    ! THE ELEVEN, FREED AND BRACKETED.
                    !
                    ! Each on the moment its row in the note's internal table
                    ! names. Signs are stated rather than left to be inferred,
                    ! because a wrong sign here shows up as a moment walking
                    ! away rather than as an error.
                    !
                    ! theta, the weight on drugs, on drug spending over income
                    ! averaged across users, light and heavy together, which is
                    ! the population the moment below is taken over. More weight,
                    ! more spending, so the update
                    ! adds the gap the other way round: subtract model minus
                    ! data.
                    ! THE MOMENT IS A WEIGHTED AVERAGE OVER BOTH KINDS OF USER.
                    !
                    ! It used to be the ratio for the experimenters alone, who are
                    ! the users WITHOUT a disorder, since the code keeps the two
                    ! groups disjoint. So a target meant for users as a whole was
                    ! being asked of the lighter half of them.
                    !
                    ! Now each group's own drug to income ratio is formed first and
                    ! the two are averaged with their shares of the using
                    ! population as weights, which is the object the data number is.
                    ! A GROUP WITH NO INCOME HAS NO RATIO.
                    !
                    ! Households carrying the disorder are largely out of work with
                    ! no assets, so their measured income can be numerically zero
                    ! while they still spend on the drug out of the consumption
                    ! floor. Dividing one by the other gave a group ratio of
                    ! 1,815,832 on the first iteration, which then swamped the
                    ! weighted average. The 1e-12 guard stopped a crash and
                    ! produced a meaningless number instead, which is worse.
                    !
                    ! So a group ratio is only formed when that group's income is a
                    ! real quantity, taken as a thousandth of average labour income
                    ! times its mass. When it is not, the pooled ratio over both
                    ! groups is used for that iteration, which is well behaved
                    ! because the denominator is dominated by the group that does
                    ! earn, and the log says so rather than passing it off as the
                    ! weighted average.
                    ! A TENTH OF AVERAGE INCOME PER HOUSEHOLD, not a thousandth.
                    ! At a thousandth the guard passed on a group whose income per
                    ! head was still near zero, and the ratio it then formed was
                    ! 1,815,823. A group whose average income is below a tenth of
                    ! the mean has no meaningful drug to income ratio, whatever the
                    ! numerator is.
                    income_floor_1=10.d0**(-1)*model_average_labour_income(1)

                    ! EACH ACCUMULATOR IS ALREADY A RATIO. It is divided by its
                    ! group's total income where the distribution is summed, and
                    ! dividing it again here is what produced 62 and 1,204,097 for
                    ! a share the budget constraint caps at one. A negative value
                    ! is the sentinel for a group with no income at all.
                    drug_share_experimenters_1=&
                        model_experimenters_total_drug_spending_to_total_income(1)
                    drug_share_addicted_1=&
                        model_addicted_total_addiction_spending_to_total_income(1)

                    ! A GROUP COUNTS ONLY IF ITS RATIO MEANS SOMETHING, and a group
                    ! that fails is dropped from the average rather than replaced
                    ! by a pooled ratio. Pooling put the failing group back in
                    ! through the numerator.
                    use_experimenters_1=(model_mass_experimenters(1)>0) .AND. &
                        (drug_share_experimenters_1>=0) .AND. &
                        (model_experimenters_total_income(1)>&
                        income_floor_1*model_mass_experimenters(1))
                    use_addicts_1=(model_mass_addicts(1)>0) .AND. &
                        (drug_share_addicted_1>=0) .AND. &
                        (model_addicted_total_income(1)>&
                        income_floor_1*model_mass_addicts(1))

                    ! ONE DEFINITION, in weighted_drug_share_now, so the value
                    ! the sweep records and the value the bracket moves on cannot
                    ! drift apart. The tests below survive only to say WHICH group
                    ! was dropped, which the function has no business printing.
                    drug_share_weighted_1=weighted_drug_share_now()

                    if (use_experimenters_1 .AND. (.NOT. use_addicts_1)) then

                        write(*,*) "drug share: the group with a disorder has no income to speak of,",&
                            " so the moment is the experimenters alone this iteration"

                    else if (use_addicts_1 .AND. (.NOT. use_experimenters_1)) then

                        write(*,*) "drug share: the experimenters have no income to speak of,",&
                            " so the moment is the group with a disorder alone this iteration"

                    end if

                    write(*,*) "drug share, experimenters and with a SUD =",&
                        drug_share_experimenters_1, drug_share_addicted_1
                    write(*,*) "drug share, weighted by their population shares =",&
                        drug_share_weighted_1, " target =", drug_spending_share_data

                    if (drug_share_weighted_1>=0) then

                        write(*,*) "relative_share_of_addiction_1=", relative_share_of_addiction_1

                        ! A TRUST REGION ON THE GAP AND ON THE STEP. The share
                        ! cannot exceed one, so a gap above one is a measurement
                        ! failure rather than a signal about theta, and the raw gap
                        ! of 109 moved theta from 0.44 to its floor in one step
                        ! while the next iteration undid it. Clamping the gap keeps
                        ! the sign and drops the magnitude; halving or doubling per
                        ! iteration is still fast and cannot land on a bound.
                        drug_share_gap_1=max(min(drug_share_weighted_1-&
                            drug_spending_share_data,1.d0),-1.d0)

                        ! ABSOLUTE BOUNDS, not only a trust region. The trust
                        ! region bounds each STEP and lets the level walk
                        ! anywhere, which is how theta reached 0.667: two thirds
                        ! of the utility bundle on the drug, against a quarter on
                        ! consumption and six per cent on housing. That is not a
                        ! preference anyone would defend, and it was reached while
                        ! the drug first order condition still had its sign
                        ! inverted. The stylized model uses 0.20 and the note says
                        ! the two share this parameter, so the band is set around
                        ! that.
                        ! THETA MAY NOT RISE WHILE THE GRADIENT IS INVERTED.
                        !
                        ! The drug spending share and the income gradient pull
                        ! theta opposite ways, and only one of them is the fact
                        ! the model exists to produce. Measured: as b rose and
                        ! participation fell from 76.6 per cent to 14.6, the
                        ! average user went from 0.85 of mean income to 1.54 and
                        ! the average household with the disorder to 1.87, while
                        ! the spending share FELL from 9.6 per cent to 5.9
                        ! against a target of 16.2. Those are the same fact:
                        ! the share is spending over INCOME, so users who are
                        ! rich carry a small share however much they buy, and
                        ! the update reads that as a reason to raise theta.
                        !
                        ! Raising it is the wrong direction. theta_hi is the
                        ! break point above which mortality stops reversing the
                        ! gradient, so a bracket pressing upward through it is
                        ! walking further into the region where the mechanism
                        ! does not work, chasing a share it cannot reach from
                        ! there. The guard lets theta FALL on the share as
                        ! before and refuses to let it RISE while the average
                        ! household with the disorder is richer than the mean.
                        if ((model_average_income_addicted(1)>&
                            model_average_labour_income(1)) .AND.&
                            (drug_share_gap_1<0)) then

                            write(*,*) "THETA HELD: the gradient is inverted, income of the",&
                                " disordered over the mean is",&
                                model_average_income_addicted(1)/&
                                max(model_average_labour_income(1),10.d0**(-12)),&
                                " and the share asks theta HIGHER. Refusing: the ceiling is",&
                                " the break point where mortality stops reversing the",&
                                " gradient, so raising theta chases a share that cannot be",&
                                " reached from above it."

                        else

                            relative_share_of_addiction_1=&
                                max(min(relative_share_of_addiction_1-&
                                relative_share_of_addiction_adj*drug_share_gap_1,&
                                min(theta_hi,2*relative_share_of_addiction_1)),&
                                max(theta_lo,relative_share_of_addiction_1/2))

                        end if

                        call apply_gamma_tie()

                        distance_relative_share_of_addiction_1=&
                            abs(drug_share_weighted_1-drug_spending_share_data)

                        write(*,*) "relative_share_of_addiction_1=", relative_share_of_addiction_1
                        write(*,*) "distance_relative_share_of_addiction_1=",&
                            distance_relative_share_of_addiction_1

                        ! THETA ON ITS CEILING IS A RESULT, NOT A STUCK SEARCH,
                        ! and it has to be said out loud or it reads as neither.
                        ! The ceiling is the break point above which mortality
                        ! stops reversing the income gradient, so a calibration
                        ! pressed against it is reporting that it cannot reach
                        ! the drug spending share while keeping the poor as the
                        ! users. That is the fact the paper exists to explain, so
                        ! losing it silently is the worst outcome available.
                        if ((relative_share_of_addiction_1>=theta_hi*(1-10.d0**(-9)))&
                            .AND. (drug_share_weighted_1<drug_spending_share_data)) then

                            write(*,*) "THETA PINNED AT ITS CEILING: theta=",&
                                relative_share_of_addiction_1, " and the drug share is",&
                                drug_share_weighted_1, " against a target of",&
                                drug_spending_share_data, &
                                ". The update wants theta HIGHER and the ceiling is the",&
                                " break point above which mortality stops reversing the",&
                                " income gradient. Check the gradient before trusting",&
                                " any other moment: income of users over average is",&
                                model_avg_income_drug_users(1)/&
                                max(model_average_labour_income(1),10.d0**(-12)),&
                                " and of the disordered",&
                                model_average_income_addicted(1)/&
                                max(model_average_labour_income(1),10.d0**(-12))

                        end if

                    else

                        write(*,*) "drug share HELD: neither using group has income worth dividing by,",&
                            " so theta is not moved on a moment that does not exist"
                        distance_relative_share_of_addiction_1=1

                    end if

                    ! b, the Stone-Geary endowment, on participation. A LARGER b
                    ! deters use, since the marginal value of the first unit is
                    ! theta/b, so participation FALLS in b and the update adds
                    ! the gap. Multiplicative, because b is of order 1e-8 and an
                    ! additive step in it is meaningless.
                    write(*,*) "addiction_scalar_1=", addiction_scalar_1
                    ! NO GUARD ON PARTICIPATION BEING POSITIVE. Zero participation
                    ! is exactly the state b has to move out of, and the gap is
                    ! normalised by the target so it cannot be worse than minus
                    ! one however empty the model is. Skipping the update there
                    ! left the model parked at the corner it needed to leave.
                    ! ALL USERS, NOT THE EXPERIMENTERS ALONE.
                    !
                    ! participation_rate_data is NSDUH's svyrdudany in (1,2,3),
                    ! which is ANY drug use disorder INCLUDING MILD: the data
                    ! appendix calls it "whether a household uses" and quotes
                    ! the conversion the model implies as 3.68/8.90 = 41.3 per
                    ! cent, which only reads that way if 8.90 is the whole user
                    ! population. model_exprimenters is the users WITHOUT the
                    ! disorder, so bracketing b on it asked the model for 8.90
                    ! per cent mild users PLUS 3.68 per cent disordered ones,
                    ! 12.58 per cent in total against a survey figure of 8.90,
                    ! and it put the disordered share of users at 29.3 per cent
                    ! where the survey says 41.3.
                    !
                    ! model_total_drug_users is exactly the sum: the log prints
                    ! model_fraction_addicted+model_exprimenters beside it and
                    ! the two agree to the last digit.
                    gap_addiction_scalar_1=model_total_drug_users(1)-participation_rate_data

                    if (have_gap_addiction_scalar==1) then

                        if ((gap_addiction_scalar_1*previous_gap_addiction_scalar)<0) then

                            addiction_scalar_adjuster=max(addiction_scalar_adjuster*&
                                addiction_scalar_damping,addiction_scalar_floor)

                        else

                            addiction_scalar_adjuster=min(addiction_scalar_adjuster*&
                                addiction_scalar_growth,addiction_scalar_adjuster_start)

                        end if

                    end if

                    previous_gap_addiction_scalar=gap_addiction_scalar_1
                    have_gap_addiction_scalar=1

                    ! ABSOLUTE BOUNDS ON b TOO, and they matter more than
                    ! theta's because b sets the ABSTENTION CORNER. The static
                    ! split buys nothing when x <= b*(w_c/w_v), so with b at 0.99
                    ! and theta at 0.667 the corner sat at 0.40 against a poorest
                    ! household's total consumption of 0.45: the bottom of the
                    ! distribution was one per cent of its consumption away from
                    ! being priced out of the drug entirely. At theta of 0.2 the
                    ! same b would put the corner at about 4b, which is above
                    ! every household in the model. The stylized model uses 0.009.
                    b_move_1=move_factor(model_exprimenters(1),&
                        participation_rate_data,escape_factor_b)
                    write(*,*) "MOVE MODE addiction_scalar_1=", b_move_1
                    addiction_scalar_1=max(min(addiction_scalar_1*&
                        (1+addiction_scalar_adjuster*&
                        gap_addiction_scalar_1/&
                        max(participation_rate_data,10.d0**(-12))),&
                        min(b_hi,b_move_1*addiction_scalar_1)),&
                        max(b_lo,addiction_scalar_1/b_move_1))
                    distance_addiction_scalar=abs(gap_addiction_scalar_1)
                    write(*,*) "addiction_scalar_adjuster=", addiction_scalar_adjuster
                    write(*,*) "addiction_scalar_1=", addiction_scalar_1
                    write(*,*) "distance_addiction_scalar=", distance_addiction_scalar

                    ! aleph, on the model implied value of a statistical life.
                    ! A larger aleph makes life worth more, so the VSL rises in
                    ! it and the update subtracts the gap.
                    ! THE MOMENT IS SCALE FREE, so the comparison is too. The
                    ! model's value of life is a sum of V/MU_c and carries the
                    ! numeraire with it; dividing by average labour income turns
                    ! it into the multiple the data number is quoted as, and
                    ! nothing in the block then depends on what a unit of the
                    ! model is worth.
                    if (model_average_labour_income(1)>0) then

                        model_vsl_ratio_1=model_value_of_life(1)/&
                            model_average_labour_income(1)

                        write(*,*) "model_value_of_life(1)=", model_value_of_life(1),&
                            " over average labour income =", model_vsl_ratio_1,&
                            " target =", vsl_data

                        ! A TRUST REGION. The adjuster is ten and the gap is measured
                        ! in the same units as the parameter, so an early gap of 88
                        ! moves it by 885 and any starting value below that lands on a
                        ! clamp. Halving or one and a half times per iteration is
                        ! still fast and cannot overshoot into a bound.
                        gap_value_of_life_1=model_vsl_ratio_1-vsl_data

                        if (have_gap_value_of_life==1) then

                            if ((gap_value_of_life_1*previous_gap_value_of_life)<0) then

                                value_of_life_trust=max(value_of_life_trust*&
                                    value_of_life_trust_damping,value_of_life_trust_floor)

                            else

                                value_of_life_trust=min(value_of_life_trust*&
                                    value_of_life_trust_growth,value_of_life_trust_start)

                            end if

                        end if

                        previous_gap_value_of_life=gap_value_of_life_1
                        have_gap_value_of_life=1

                        write(*,*) "value_of_life_trust=", value_of_life_trust

                        value_of_life_step_1=value_of_life-value_of_life_adjuster*&
                            gap_value_of_life_1
                        value_of_life_step_1=max(min(value_of_life_step_1,&
                            (1+value_of_life_trust)*value_of_life),&
                            value_of_life/(1+value_of_life_trust))
                        value_of_life=max(min(value_of_life_step_1,10.d0**(4)),10.d0**(-2))
                        distance_value_of_life=abs(model_vsl_ratio_1-vsl_data)

                    else

                        write(*,*) "aleph HELD: average labour income is zero, so the",&
                            " value of life has no multiple to be quoted as"
                        distance_value_of_life=1

                    end if
                    write(*,*) "value_of_life=", value_of_life
                    write(*,*) "distance_value_of_life=", distance_value_of_life

                    ! cbar, the food stamp floor, on food stamps over OUTPUT.
                    ! A higher floor pays more out, so the share rises in it and
                    ! the update subtracts the gap.
                    !
                    ! THE DENOMINATOR IS OUTPUT, AND IT MUST BE THE SAME ONE THE
                    ! MOMENT IS PRINTED WITH. food_stamps_share_data is 0.42 per
                    ! cent of GDP, so the moment above divides by model_output,
                    ! and this update divided by model_average_labour_income --
                    ! two different equations on one target. Whichever loop ran
                    ! last would move max_food_cost to satisfy the one the report
                    ! does not score. The denominator is named once here and once
                    ! at the moment; if one changes the other has to.
                    if (model_output(1)>0) then
                        write(*,*) "max_food_cost=", max_food_cost
                        max_food_cost=max(min(max_food_cost-max_food_cost_adjuster*&
                            (govt_spending_on_food_stamps(1)/model_output(1)-&
                            food_stamps_share_data),1.d0),10.d0**(-4))
                        ! PRINT THE RATIO THIS UPDATE COMPARES, which is now the
                        ! same ratio the moments block prints.
                        write(*,*) "govt_spending_on_food_stamps/model_output=", &
                            govt_spending_on_food_stamps(1)/model_output(1)

                        distance_max_food_cost=&
                            abs(govt_spending_on_food_stamps(1)/model_output(1)-food_stamps_share_data)
                        write(*,*) "max_food_cost=", max_food_cost
                        write(*,*) "distance_max_food_cost=", distance_max_food_cost
                    end if

                    ! pi_V, the voucher lottery, on recipients over the income
                    ! eligible. Coverage rises in it, so subtract the gap.
                    write(*,*) "probability_of_voucher_benchmark_used=", probability_of_voucher_benchmark_used
                    call damp_on_flip(voucher_probability_adjuster,&
                        model_eligibles_getting_voucher(1)-voucher_coverage_data,&
                        previous_gap_voucher_probability,have_gap_voucher_probability,&
                        voucher_probability_adjuster_start,damp_adjuster_floor)
                    write(*,*) "voucher_probability_adjuster=", voucher_probability_adjuster
                    probability_of_voucher_benchmark_used=&
                        max(min(probability_of_voucher_benchmark_used-voucher_probability_adjuster*&
                        (model_eligibles_getting_voucher(1)-voucher_coverage_data),1.d0),10.d0**(-5))
                    distance_voucher_probability=&
                        abs(model_eligibles_getting_voucher(1)-voucher_coverage_data)
                    write(*,*) "probability_of_voucher_benchmark_used=", probability_of_voucher_benchmark_used
                    write(*,*) "distance_voucher_probability=", distance_voucher_probability

                    ! bar pi^eu, the separation rate, on the unemployment rate.
                    ! Unemployment rises in it, so subtract the gap.
                    write(*,*) "probability_becoming_unemployed=", probability_becoming_unemployed
                    call damp_on_flip(separation_rate_adjuster,&
                        model_fraction_unemployed(1)-unemployment_rate_data,&
                        previous_gap_separation_rate,have_gap_separation_rate,&
                        separation_rate_adjuster_start,damp_adjuster_floor)
                    write(*,*) "separation_rate_adjuster=", separation_rate_adjuster
                    separation_step_1=probability_becoming_unemployed-&
                        separation_rate_adjuster*&
                        (model_fraction_unemployed(1)-unemployment_rate_data)
                    call trust_step(separation_step_1,probability_becoming_unemployed,&
                        move_factor(model_fraction_unemployed(1),&
                        unemployment_rate_data,escape_factor),10.d0**(-5))
                    write(*,*) "MOVE MODE separation_rate=",&
                        move_factor(model_fraction_unemployed(1),&
                        unemployment_rate_data,escape_factor)
                    probability_becoming_unemployed=&
                        max(min(separation_step_1,1.d0),10.d0**(-6))
                    distance_separation_rate=abs(model_fraction_unemployed(1)-unemployment_rate_data)
                    write(*,*) "probability_becoming_unemployed=", probability_becoming_unemployed
                    write(*,*) "distance_separation_rate=", distance_separation_rate

                    ! kappa_ued, the employment multiplier for the SUD, on the
                    ! unemployment rate GIVEN a SUD. It multiplies the
                    ! separation rate and divides the job finding rate, so
                    ! unemployment among those with the disorder rises in it.
                    write(*,*) "multiple_of_probabilities_of_employment_if_addicted=", &
                        multiple_of_probabilities_of_employment_if_addicted
                    call damp_on_flip(employment_multiplier_adjuster,&
                        model_fraction_addicted_and_unemployed(1)-unemployment_rate_sud_data,&
                        previous_gap_employment_multiplier,have_gap_employment_multiplier,&
                        employment_multiplier_adjuster_start,damp_adjuster_floor)
                    write(*,*) "employment_multiplier_adjuster=", employment_multiplier_adjuster
                    multiple_of_probabilities_of_employment_if_addicted=&
                        max(min(multiple_of_probabilities_of_employment_if_addicted-&
                        employment_multiplier_adjuster*&
                        (model_fraction_addicted_and_unemployed(1)-unemployment_rate_sud_data),&
                        20.d0),1.d0)
                    distance_employment_multiplier=&
                        abs(model_fraction_addicted_and_unemployed(1)-unemployment_rate_sud_data)
                    write(*,*) "multiple_of_probabilities_of_employment_if_addicted=", &
                        multiple_of_probabilities_of_employment_if_addicted
                    write(*,*) "distance_employment_multiplier=", distance_employment_multiplier

                    ! ================================================
                    ! THE SMI BLOCK AND THE TWO WAGE PENALTIES.
                    !
                    ! Each is guarded on its own adjuster, so a parameter that is
                    ! frozen contributes a zero distance rather than a moment the
                    ! sweep can never satisfy. That failure mode cost a whole
                    ! calibration once: a distance computed from a live moment
                    ! while its parameter could not move means the loop cannot
                    ! terminate however well everything else fits.
                    !
                    ! Signs, stated because a wrong one shows up as a moment
                    ! walking away rather than as an error:
                    !   lambda_m up   -> SMI less persistent -> SMI share of the
                    !                    homeless DOWN
                    !   kappa_uem up  -> employment margins worse -> employment
                    !                    rate given SMI DOWN, so the update ADDS,
                    !                    unlike kappa_ued above whose moment is an
                    !                    unemployment rate and whose update
                    !                    subtracts
                    !   rho_m up      -> smaller penalty -> homeless income UP
                    !   rho_d up      -> smaller penalty -> employed homeless can
                    !                    afford housing -> employed share of the
                    !                    homeless DOWN

                    ! ZETA_DI OWNS THE SMI SHARE OF THE HOMELESS. It was
                    ! lambda_m's moment until 25 August, and lambda_m's update
                    ! below is kept at a zero adjuster rather than deleted so
                    ! that what this loop used to do stays readable. A more
                    ! generous transfer keeps households with SMI housed, so the
                    ! share of the homeless carrying SMI FALLS as zeta_DI rises
                    ! and the update SUBTRACTS the gap.
                    if ((zeta_DI_adjuster>0) .AND. (number_of_smi_states>1) &
                        .AND. (model_mass_homeless_raw(1)>10.d0**(-12))) then

                        zeta_DI=min(max(zeta_DI-zeta_DI_adjuster*&
                            (model_smi_share_of_homeless(1)-smi_share_of_homeless_data),&
                            0.d0),1.d0)

                        ! OWNERSHIP IS READ OFF THE DISTANCE, not off the
                        ! update: calibration_report.pairs() builds the map from
                        ! distance_X = abs(model - target), which is what
                        ! check_alignment judges the table's Set column against.
                        distance_zeta_DI=&
                            abs(model_smi_share_of_homeless(1)-smi_share_of_homeless_data)

                        write(*,*) "zeta_DI ->", zeta_DI, " SMI share of the homeless", &
                            model_smi_share_of_homeless(1), " target", smi_share_of_homeless_data

                    else

                        distance_zeta_DI=0

                    end if

                    if ((lambda_m_adjuster>0) .AND. (number_of_smi_states>1)) then

                        ! THE SAME EMPTY SET PROBLEM AS h_2. With no homeless
                        ! households model_smi_share_of_homeless is set to zero
                        ! by the branch that guards its division, so the gap
                        ! against 0.25 is a fabricated -0.25 and lambda_m is
                        ! driven by a moment that does not exist. Hold it until
                        ! there is a homeless population to measure the share on.
                        if (model_mass_homeless_raw(1)<=10.d0**(-12)) then

                            write(*,*) "lambda_m HELD: no homeless mass, so the SMI share of the homeless"
                            write(*,*) "   is not measurable and lambda_m does not move"

                            distance_lambda_m=1

                            goto 8802

                        end if

                        ! THE FLOOR IS THE PROFILE'S, NOT 0.001. Below
                        ! lambda_m_floor the onset identity has no non negative
                        ! solution, the SMI state empties, and every SMI moment
                        ! reads zero, so the loop cannot recover: the moment stops
                        ! responding to the parameter and the update keeps pushing
                        ! the same way. Stopping at the floor keeps the model
                        ! interpretable and makes the tension visible instead.
                        lambda_m=min(max(lambda_m+lambda_m_adjuster*&
                            (model_smi_share_of_homeless(1)-smi_share_of_homeless_data),&
                            lambda_m_floor),0.5d0)

                        if (lambda_m<=lambda_m_floor+10.d0**(-9)) then

                            write(*,*) "lambda_m IS AT ITS FLOOR", lambda_m_floor, &
                                " and the SMI share of the homeless is", &
                                model_smi_share_of_homeless(1), " against a target of", &
                                smi_share_of_homeless_data
                            write(*,*) "   the profile cannot deliver this moment: the prevalence path, the onset"
                            write(*,*) "   identity and this target are not mutually consistent."

                        end if

                        distance_lambda_m=&
                            abs(model_smi_share_of_homeless(1)-smi_share_of_homeless_data)

                        write(*,*) "lambda_m=", lambda_m, " distance_lambda_m=", distance_lambda_m

8802                    continue

                    else

                        distance_lambda_m=0

                    end if

                    if ((kappa_uem_adjuster>0) .AND. (number_of_smi_states>1)) then

                        ! THE SIGN HERE IS THE OPPOSITE OF ITS NEIGHBOUR'S, and
                        ! that is not a slip. kappa_ued above is moved against an
                        ! UNEMPLOYMENT rate, which rises in the parameter, so its
                        ! update subtracts. kappa_uem is moved against an
                        ! EMPLOYMENT rate, which falls in the parameter, so its
                        ! update must ADD. The block was written by analogy with
                        ! the SUD block and inherited the minus, which drove
                        ! kappa_uem to its floor of one, removed the SMI
                        ! employment effect altogether, and left a distance that
                        ! could never fall below its stopping rule, so the loop
                        ! could not terminate however well anything else fitted.
                        ! THE CEILING WAS 20 AND kappa_uem WALKED INTO IT.
                        ! It reached 17.98 with the employment rate given SMI
                        ! still at 0.68 against a target of 0.30, so three more
                        ! loops would have parked it on the bound with the
                        ! moment untouched and the distance unable to fall.
                        ! A bound a parameter can reach while its moment is
                        ! still wide is indistinguishable, from the loop's
                        ! point of view, from a moment the model cannot hit.
                        ! 40 is not a belief about the penalty's size: it is far
                        ! enough away that reaching it would be evidence, not an
                        ! artefact of where the ceiling was put.
                        !
                        ! RAISED TO 100 on the author's instruction of 25 August,
                        ! for the same reason and with more room. The moment was
                        ! reported to them as close to unreachable on a log-LEVEL
                        ! elasticity of -0.133; in log ODDS the three measured
                        ! points at 1.0, 1.6 and 3.0 are a straight line of slope
                        ! -1.80 and put the answer near 8.5, so neither 40 nor 100
                        ! should ever bind. The point of the headroom is that if
                        ! one of them does bind, that is now a fact about the
                        ! model rather than about this constant.
                        !
                        ! Above kappa = 1/probability_becoming_unemployed, about
                        ! 34 at the current value, sep_1 is clamped at one and
                        ! only the job-finding side still responds. The employment
                        ! rate keeps falling to zero, so the ceiling remains a
                        ! ceiling and not a wall, but the log-odds line bends
                        ! there and a fit taken across it should not be believed.
                        kappa_uem=min(max(kappa_uem+kappa_uem_adjuster*&
                            (model_employment_rate_given_smi(1)-employment_rate_given_smi_data),&
                            1.0d0),100.d0)

                        distance_kappa_uem=&
                            abs(model_employment_rate_given_smi(1)-employment_rate_given_smi_data)

                        write(*,*) "kappa_uem=", kappa_uem, " distance_kappa_uem=", distance_kappa_uem

                    else

                        distance_kappa_uem=0

                    end if

                    if ((rho_m_adjuster>0) .AND. (number_of_smi_states>1) .AND. &
                        (include_rho_m==1)) then

                        rho_m=min(max(rho_m-rho_m_adjuster*&
                            (model_homeless_income_share(1)-homeless_income_share_data),&
                            0.05d0),1.d0)

                        distance_rho_m=&
                            abs(model_homeless_income_share(1)-homeless_income_share_data)

                        write(*,*) "rho_m=", rho_m, " distance_rho_m=", distance_rho_m

                    else

                        distance_rho_m=0

                    end if

                    if ((rho_d_adjuster>0) .AND. (include_rho_d==1)) then

                        rho_d=min(max(rho_d+rho_d_adjuster*&
                            (model_employed_share_of_homeless(1)-employed_share_of_homeless_data),&
                            0.05d0),1.d0)

                        distance_rho_d=&
                            abs(model_employed_share_of_homeless(1)-employed_share_of_homeless_data)

                        write(*,*) "rho_d=", rho_d, " distance_rho_d=", distance_rho_d

                    else

                        distance_rho_d=0

                    end if

                    write(*,*) "model_fraction_homeless(1)=", model_fraction_homeless(1)
                    write(*,*) "size_homelessness=", size_homelessness

                    ! A bracket whose endpoints were priced under different values
                    ! of life is not a bracket. Test for that before using it.
                    if ((size_homelessness_lo>=0) .OR. (size_homelessness_hi>=0)) then

                        if ((value_of_life_at_bracket>0) .AND. &
                            (abs(value_of_life-value_of_life_at_bracket)>&
                            bracket_value_of_life_tolerance*value_of_life_at_bracket)) then

                            write(*,*) "size_homelessness BRACKET DISCARDED: the value of life moved from ",&
                                value_of_life_at_bracket, " to ", value_of_life,&
                                " so its endpoints are not comparable"
                            size_homelessness_lo=-1
                            size_homelessness_hi=-1
                            size_homelessness_lo_moment=-1
                            size_homelessness_hi_moment=-1
                            value_of_life_at_bracket=-1

                        end if

                    end if

                    if ((size_homelessness_lo<0) .AND. (size_homelessness_hi<0)) then

                        value_of_life_at_bracket=value_of_life

                    end if

                    ! Tighten the bracket with what this evaluation just proved,
                    ! unless it proves the bracket itself is stale.
                    if (model_fraction_homeless(1)<fraction_homeless_data) then

                        if (size_homelessness_lo<0) then

                            size_homelessness_lo=size_homelessness
                            size_homelessness_lo_moment=model_fraction_homeless(1)

                        else if ((size_homelessness>size_homelessness_lo) .AND. &
                            (model_fraction_homeless(1)<size_homelessness_lo_moment-10.d0**(-5))) then

                            ! Raised the parameter and homelessness fell.
                            write(*,*) "size_homelessness BRACKET DISCARDED: raised to ",&
                                size_homelessness, " and homelessness fell from ",&
                                size_homelessness_lo_moment, " to ", model_fraction_homeless(1)
                            size_homelessness_lo=-1
                            size_homelessness_hi=-1
                            size_homelessness_lo_moment=-1
                            size_homelessness_hi_moment=-1

                        else if (size_homelessness>size_homelessness_lo) then

                            size_homelessness_lo=size_homelessness
                            size_homelessness_lo_moment=model_fraction_homeless(1)

                        end if

                    else

                        if (size_homelessness_hi<0) then

                            size_homelessness_hi=size_homelessness
                            size_homelessness_hi_moment=model_fraction_homeless(1)

                        else if ((size_homelessness<size_homelessness_hi) .AND. &
                            (model_fraction_homeless(1)>size_homelessness_hi_moment+10.d0**(-5))) then

                            ! Lowered the parameter and homelessness rose.
                            write(*,*) "size_homelessness BRACKET DISCARDED: lowered to ",&
                                size_homelessness, " and homelessness rose from ",&
                                size_homelessness_hi_moment, " to ", model_fraction_homeless(1)
                            size_homelessness_lo=-1
                            size_homelessness_hi=-1
                            size_homelessness_lo_moment=-1
                            size_homelessness_hi_moment=-1

                        else if (size_homelessness<size_homelessness_hi) then

                            size_homelessness_hi=size_homelessness
                            size_homelessness_hi_moment=model_fraction_homeless(1)

                        end if

                    end if

                    if ((size_homelessness_lo>=0) .AND. &
                        (size_homelessness_hi>size_homelessness_lo)) then

                        ! Bisect. This halves the window every equilibrium solve,
                        ! so a window of 0.08 is down to the stopping rule in about
                        ! seven of them however wide the initial bracket was.
                        size_homelessness=&
                            0.5d0*(size_homelessness_lo+size_homelessness_hi)

                        write(*,*) "size_homelessness bisecting in [",&
                            size_homelessness_lo, ",", size_homelessness_hi, "]"

                    else

                        ! No bracket yet, so traverse, which is what the adjuster
                        ! is good at.
                        gap_size_homelessness_1=model_fraction_homeless(1)-fraction_homeless_data

                        if (have_gap_size_homelessness==1) then

                            if ((gap_size_homelessness_1*previous_gap_size_homelessness)<0) then

                                size_homelessness_adjuster=max(size_homelessness_adjuster*&
                                    size_homelessness_damping,size_homelessness_adjuster_floor)

                            else if (abs(gap_size_homelessness_1)>&
                                0.5d0*fraction_homeless_data) then

                                ! DAMPING IS A MEMORY OF A DIFFERENT REGIME. The
                                ! adjuster is halved on every sign flip and grown
                                ! by a fifth on every same signed loop, which is
                                ! right beside a solution and wrong far from one:
                                ! after enough flips it stood at 0.067 against a
                                ! gap of 0.0034, a step of 0.0002 on a parameter
                                ! of 0.099, so an eighty five per cent miss moved
                                ! by two parts in a thousand a loop and would
                                ! have taken hundreds of solves.
                                !
                                ! A gap of half the target is not near a solution.
                                ! Re-arm rather than creep, and let the overshoot
                                ! do its job: the first sign flip after it
                                ! establishes the bracket, and the bisection below
                                ! closes the window in about seven solves however
                                ! wide it is. That is what the bracket is for, and
                                ! creeping never reaches it.
                                size_homelessness_adjuster=size_homelessness_adjuster_start

                                write(*,*) "size_homelessness adjuster RE-ARMED: the gap is ", &
                                    gap_size_homelessness_1, " against a target of ", &
                                    fraction_homeless_data

                            else

                                size_homelessness_adjuster=min(size_homelessness_adjuster*&
                                    size_homelessness_growth,size_homelessness_adjuster_start)

                            end if

                        end if

                        previous_gap_size_homelessness=gap_size_homelessness_1
                        have_gap_size_homelessness=1

                        write(*,*) "size_homelessness_adjuster=", size_homelessness_adjuster

                        ! THE LADDER MUST BE STRICTLY INCREASING, and this
                        ! bound is what guarantees it: h_1 is built as
                        ! housing_size(0)*size_homelessness, so a ceiling of 1
                        ! admits h_1 = h_2 exactly, a street worth as much as
                        ! the cheapest room and free, at which point the rung
                        ! above the street buys nothing and the housing
                        ! dimension collapses at the bottom. 0.9 keeps the
                        ! inequality strict and still leaves homelessness as
                        ! attractive as the traverse can need: the current
                        ! value is 0.10, so this binds on nothing today and
                        ! stops the degenerate case if the update ever runs.
                        size_homelessness_step_1=size_homelessness-&
                            size_homelessness_adjuster*gap_size_homelessness_1
                        call trust_step(size_homelessness_step_1,size_homelessness,&
                            move_factor(model_fraction_homeless(1),&
                            fraction_homeless_data,escape_factor),&
                            size_homelessness_max_step)
                        write(*,*) "MOVE MODE size_homelessness=",&
                            move_factor(model_fraction_homeless(1),&
                            fraction_homeless_data,escape_factor)
                        size_homelessness=max(min(size_homelessness_step_1,0.9d0),&
                            size_homelessness_floor)

                        ! Say so if the traverse has run out of room. At a street
                        ! worth as much as housing_size(0) and free, a model still
                        ! below target is not a failure of this update: nothing in
                        ! the housing ladder makes homelessness attractive, so the
                        ! rental grid or the food floor is what has to move.
                        if ((size_homelessness>=0.9d0) .AND. &
                            (model_fraction_homeless(1)<fraction_homeless_data)) then

                            write(*,*) "size_homelessness IS AT ITS CEILING 1 and homelessness is ",&
                                model_fraction_homeless(1), " against a target of ", fraction_homeless_data
                            write(*,*) "   no bracket exists below the ceiling: the street cannot be",&
                                " made attractive enough through this parameter."

                        end if

                    end if

                    distance_size_homelessness=&
                        abs(model_fraction_homeless(1)-fraction_homeless_data)

                    write(*,*) "size_homelessness=", size_homelessness
                                 
                end if
                                        
            end if
                                                                                     
            distance_rental_market(1)=maxval(abs(total_rental_demand(1,:)-total_rental_supply(1,:)))

            ! THE DRUG MARKET.
            !
            ! V is the quantity households actually bought, accumulated over the
            ! distribution in model_drugs_consumed_by_users. The supply price at
            ! that quantity is nu_1 V^(nu_2-1).
            !
            ! In the benchmark nu_1 is whatever puts that price at one, which is
            ! the note's normalisation, so the market clears every loop and the
            ! price never moves. In a counterfactual nu_1 is the benchmark's, so
            ! the price is whatever the supply curve says and the loop iterates
            ! until the price households faced and the price the quantity
            ! implies agree.
            call clear_drug_market(1)

            write(*,*) "rent(1)=", rent(1,:)
            write(*,*) "rental_supply(1)=", total_rental_supply(1,:)
            write(*,*) "rental_demand(1)=", total_rental_demand(1,:)
            write(*,*) "distance_rental_market(1)=", distance_rental_market(1)
                                                                   
            write(*,*) "one market"

            rental_market_adjuster=1
            
            if (re_do_simulation_with_fixed_parameters==5) then
        
                distance_rental_market(1)=maxval((abs(himmelberg_etal_rent_to_price-(rent(1,:)/housing_price(1)))))
                    
                if (fix_rent==0) then
                    rent(1,:)=rent(1,:)+rental_market_adjuster*(himmelberg_etal_rent_to_price-&
                        (rent(1,:)/housing_price(1)))
                end if
                    
            else
            
                rental_market_adjuster=10.d0**(-3)
                            
                distance_rental_market(1)=maxval(abs(total_rental_demand(1,:)-total_rental_supply(1,:)))
                                      
            end if
                                               
            write(*,*) "rent(1)=", rent(1,:)
            write(*,*) "rental_market_adjuster=", rental_market_adjuster
            write(*,*) "model_mortgages(1)/model_gross_housing_wealth(1)=", model_mortgages(1)/model_gross_housing_wealth(1)
            write(*,*) "model_average_rental_unit_size(1)=", model_average_rental_unit_size(1)
            write(*,*) "model_average_owner_occupied_unit_size(1)=", model_average_owner_occupied_unit_size(1)
            write(*,*) "model_average_rental_unit_size(1)/model_average_owner_occupied_unit_size(1)=", &
                model_average_rental_unit_size(1)/model_average_owner_occupied_unit_size(1)
!            write(*,*) "model_fraction_of_homeowners_with_mortgage(1)=", model_fraction_of_homeowners_with_mortgage(1)
                
            if (mortgage_deductibility>0) then
            
                write(*,*) "% govt spending on mortgage interest deductions(1)/model_GDP_incl_imput_rent(1)=", &
                    100*(govt_spending_on_mortgage_interest_deductions(1)/model_GDP_incl_imput_rent(1))
                
            end if
                
            write(*,*) "model_homeownership_rate(1)=", model_homeownership_rate(1)
                                                        
            call cpu_time(simulation_stop_time)
            
            write(*,*) "re_do_simulation_with_fixed_parameters=", re_do_simulation_with_fixed_parameters
            write(*,*) "relative_share_of_housing=", relative_share_of_housing
            write(*,*) "relative_share_of_leisure=", relative_share_of_leisure
            
            if (calibrate_size_of_smallest_house_hhld_can_buy==0) then
            
                write(*,*) "advantage_to_owning=", advantage_to_owning
                
            end if
            
            write(*,*) "discount_factor=", discount_factor
            write(*,*) "discount_factor_on_child=", discount_factor_on_child
                        
            write(*,*) "convexity_of_rental_company=", convexity_of_rental_company(:)
                                    
            write(*,*) "housing_status_grid_expander=", housing_status_grid_expander
                                    
            mass_at_top_financial=0
            
            do i=1,2
                                    
                mass_at_top_financial=mass_at_top_financial+&
                    sum(distribution_stationary(i)%vector_transition_real(1,:,financial_grid_size,:,:,:,:)) 
                    
            end do
                        
            write(*,*) "labor_income_tax_rate=", labor_income_tax_rate
            write(*,*) "utility_improvement,", utility_improvement
            write(*,*) "rental_management_costs=", rental_management_costs(:)
            write(*,*) "smallest_house_size=", smallest_house_size
            write(*,*) "index_of_smallest_house_hhld_can_buy=", index_of_smallest_house_hhld_can_buy
            write(*,*) "housing_size(index_of_smallest_house_hhld_can_buy)=", &
                housing_size(max(min(index_of_smallest_house_hhld_can_buy,housing_status_grid_size-1),lowest_housing_grid_point))
            write(*,*) "size_homelessness=", size_homelessness
            write(*,*) "largest_financial_chosen_in_equilibrium=", largest_financial_chosen_in_equilibrium
            write(*,*) "largest_housing_size_consumed_in_equilibrium=", largest_housing_size_consumed_in_equilibrium
            write(*,*) "smallest_financial_chosen_in_equilibrium=", smallest_financial_chosen_in_equilibrium
            write(*,*) "financial_grid(smallest_financial_chosen_in_equilibrium)=", &
                financial_grid(smallest_financial_chosen_in_equilibrium)
            write(*,*) "fraction of hhlds who make it to the highest net wealth=", mass_at_top_financial/sum_of_distribution
            write(*,*) "fraction_with_largest_housing_size_consumed_in_eqilibrium=", &
                fraction_with_largest_housing_size_consumed_in_eqilibrium
            write(*,*) "fraction_with_smallest_financial_in_eqilibrium=", &
                fraction_with_smallest_financial_in_eqilibrium
            write(*,*) "smallest_rental_relative_to_lowest_income=", smallest_rental_relative_to_lowest_income
                                      
            call initialize_variables_and_grids()                
            call GKKOC_intergenerational_employment_process(1)
            call initialize_financial_grid(1)

            if (re_do_simulation_with_fixed_parameters==0) then

                call set_smallest_house_size()

            end if
            
            distance_average_labor_income=&
                abs(previous_average_labor_income-model_average_labour_income(1))
                
            if (include_vouchers==1) then
                
                distance_median_income=&
                    abs(previous_median_income-median_income(1))
                    
            else
            
                distance_median_income=0
            
            end if
                
            if (threshold_for_food_stamps_as_perc_of_average_net_wealth>100) then
            
                distance_average_net_wealth=0
                
            else
                
                distance_average_net_wealth=&
                    abs(previous_average_net_wealth-model_average_net_wealth(1))
                    
            end if
                        
            model_average_labour_income(1)=&
                weight_on_labor_income*model_average_labour_income(1)+&
                (1-weight_on_labor_income)*previous_average_labor_income
                                
            median_income(1)=weight_on_median_income*median_income(1)+(1-weight_on_median_income)*previous_median_income
                                
            model_average_net_wealth(1)=&
                weight_on_labor_income*model_average_net_wealth(1)+&
                (1-weight_on_labor_income)*previous_average_net_wealth
                                                    
            call function_of_utility_advantage_from_homeowning(1)

            ! THE REFRESH CALL TO govt_revenues_calc WAS HERE AND IS REMOVED.
            !
            ! It ran AFTER the two-pass loop, where accumulating_beta_types is
            ! back to zero, so every guarded reset inside it fired: it wiped the
            ! pooled revenue totals and refilled them from
            ! distribution_stationary, which by then holds only the LAST TYPE
            ! SOLVED. Its denominators -- model_total_efficiency_units and
            ! model_financial -- are accumulated elsewhere and stayed pooled, so
            !
            !     tau_l = one type's revenue / two types' income = HALF
            !
            ! and tau_l is an INTERNAL ADJUSTER TARGET, so the model drove
            ! labor_income_tax_rate up until the halved number reached 0.224 --
            ! toward twice the tax rate the data asks for, faced by every
            ! household. Measured at 0.497 of its one-type value.
            !
            ! WHY REMOVING IT IS THE FIX RATHER THAN REPAIRING IT. The call
            ! cannot be made to accumulate instead of reset: type 1's
            ! distribution no longer exists here, so there is nothing to
            ! accumulate onto and no way to rebuild the pooled object. What it
            ! was for was refreshing revenues against the averages updated a few
            ! lines above. Dropping it leaves every revenue quantity holding the
            ! value the LOOP computed, which is pooled and correct, one outer
            ! iteration stale -- and the next outer iteration re-runs the whole
            ! chain against those same averages anyway. Stale and right beats
            ! fresh and halved.
            !
            ! set_SS_benefits reads nothing govt_revenues_calc produces, checked.
            call set_SS_benefits(1)
            
            if ((zero_elasticity==0) .AND. (infinite_elasticity_of_rental_supply==0)) then
                
                do j=0,have_two_rental_markets
!                        
                    call solve_elasticity_of_rental_housing(1,convexity_of_rental_company(j),j)
                    write(*,*) "convexity_of_rental_company=", convexity_of_rental_company(j)
                    write(*,*) "rental_management_costs=", rental_management_costs(j)
                    
                end do
                
            end if
                                                                                                         
            write(*,*) "loop_count=", loop_count
            
            write(*,*) "model average labour income=", model_average_labour_income(1)
            write(*,*) "model_average_labour_income_tax=", model_average_labour_income_tax(1)
            write(*,*) "model_average_net_wealth=", model_average_net_wealth(1)
            write(*,*) "do_internal_computations=", do_internal_computations
            
            write(*,*) "model_labor_supply/model_total_hours=", model_labor_supply(1)/model_total_hours(1)
            write(*,*) "distance_average_labor_income=", distance_average_labor_income    
            write(*,*) "distance_average_net_wealth=", distance_average_net_wealth  
                        
            write(*,*) "model_homeownership_by_age_group(1,5)=", model_homeownership_by_age_group(1,5)
            write(*,*) "value_of_initial_assets=", value_of_initial_assets
                                    
!            write(*,*) "model_avg_mortgage_spending=", model_avg_mortgage_spending(1)
            write(*,*) "model_avg_housing_spending_owners=", model_avg_housing_spending_owners(1)
            write(*,*) "model_avg_housing_spending_all=", model_avg_housing_spending_all(1)
            write(*,*) "model_avg_housing_spending_renters=", model_avg_housing_spending_renters(1)
            write(*,*) "total_rent_paid/total_renters_income=", 100*(total_rent_paid(1)/total_renters_income(1))
!            write(*,*) "inheritance_amount=", inheritance_amount
            write(*,*) "distance_inheritance_amount=", distance_inheritance_amount
            write(*,*) "average_welfare_of_youngest_cohort=", average_welfare_of_youngest_cohort(1)
            write(*,*) "mass_of_renters_at_housing_spending(1,1)=", mass_of_renters_at_housing_spending(1,1)
            write(*,*) "mass_of_renters_at_housing_spending(1,2)=", mass_of_renters_at_housing_spending(1,2)
            write(*,*) "model_fraction_homeless=", model_fraction_homeless(1)
!            write(*,*) "model_fraction_homeless_owners,", model_fraction_homeless_owners(1)
            write(*,*) "model_fraction_addicted=", model_fraction_addicted(1)
            write(*,*) "model_exprimenters=", model_exprimenters(1)
            ! ONE POINT PER PROCESS, AND IT ENDS HERE.
            !
            ! The foot of the calibration sweep is where b was being stepped, and
            ! that foot is never reached: seven passes ran in an hour, each with
            ! its own solve and its own converged distribution, and not one
            ! printed the announcement sitting three lines under the loop
            ! counter's increment. The tail of that body does not execute, so a
            ! grid indexed there never moves off its first point.
            !
            ! It could not have been clean if it had. re_do_simulation_with_fixed_
            ! parameters does not freeze everything: sd_permanent_productivity was
            ! still being updated pass by pass, and participation at a FIXED b
            ! drifted 0.3326, 0.3244, 0.3327 across three of them, which is the
            ! contamination the sweep exists to avoid.
            !
            ! So a sweep runs ONE point and stops. The distribution has converged
            ! by here (DIST_DONE prints above the loop counter and the moments
            ! below it), addiction_scalar_1 is the b this process was launched at,
            ! and nothing has updated yet. The driver relaunches for the next
            ! point, which costs a solve and buys a curve that is a function of b
            ! and of nothing else.
            ! THE AGE PROFILE PRINTS ABOVE THE SWEEP'S STOP, and that is the whole
            ! reason it sits here rather than with the other moments. A sweep
            ! point writes its row and STOPS, so anything printed below that
            ! branch is never printed by a sweep at all: the curve came back as
            ! six numbers a point with no age distribution behind any of them,
            ! and the one question the curve is being measured to answer -- who
            ! uses at the b that hits the target -- could not be read off it.
            do i=1,9
                write(*,*) "model_drug_use_by_age_group=", model_drug_use_by_age_group(1,i)
            end do
            ! The RATE, not the count, and by single age: the share of the
            ! households alive at each age who use. Printed from the last age
            ! backwards is the wrong way round for reading, so it goes forwards,
            ! and the data age is model age plus twenty five.
            write(*,*) "use rate by single age, model age 1 = data age 26:"
            do i=1,life_span
                if (model_alive_by_age(i)>10.d0**(-14)) then
                    write(*,*) "USE_BY_AGE", i, i+25, model_users_by_age(i)/model_alive_by_age(i)
                else
                    write(*,*) "USE_BY_AGE", i, i+25, 0.d0
                end if
            end do

            if (sweep_addiction_scalar==1) then

                call print_all_moments()

                write(*,*) "drug share, weighted by their population shares =",&
                    weighted_drug_share_now(), " target =", drug_spending_share_data

                ! THE VALUE OF LIFE AND WEALTH OVER OUTPUT, WHERE A SWEEP CAN SEE
                ! THEM. Both were computed only inside the parameter update block,
                ! which a sweep skips, so neither had appeared in a single sweep
                ! point: the log carried zero occurrences of either across twelve
                ! of them. They are aleph's moment and beta's, the two the author
                ! asked to be kept near their targets, and a sweep that cannot see
                ! them cannot say whether the pins are right. Both are ratios of
                ! aggregates the distribution pass has already built.
                write(*,*) "model_value_of_life(1)=", model_value_of_life(1),&
                    " over average labour income =",&
                    model_value_of_life(1)/max(model_average_labour_income(1),10.d0**(-12)),&
                    " target =", vsl_data
                write(*,*) "wealth_to_output_model =",&
                    model_total_net_wealth(1)/max(model_GDP_incl_imput_rent(1),10.d0**(-12)),&
                    " target =", wealth_to_output_data
                write(*,*) "labour supply over total hours =",&
                    model_labor_supply(1)/max(model_total_hours(1),10.d0**(-12)),&
                    " target =", avg_labor_supply_data

                open(unit=78,file="B_SWEEP_RAW.tsv",action='write',position='append')
                write(78,'(7(E24.15,A1))') addiction_scalar_1, char(9),&
                    model_exprimenters(1), char(9),&
                    model_total_drug_users(1), char(9),&
                    model_fraction_addicted(1), char(9),&
                    model_avg_income_drug_users(1)/&
                        max(model_average_labour_income(1),10.d0**(-12)), char(9),&
                    model_average_income_addicted(1)/&
                        max(model_average_labour_income(1),10.d0**(-12)), char(9),&
                    weighted_drug_share_now(), char(9)
                close(78)

                write(*,*) "B SWEEP POINT DONE at b=", addiction_scalar_1,&
                    " participation=", model_exprimenters(1)
                stop

            end if

            write(*,*) "model_fraction_addicted+model_exprimenters=", model_fraction_addicted(1)+model_exprimenters(1)
