            write(*,*) "model_fraction_of_homeowners_with_mortgage=", model_fraction_of_homeowners_with_mortgage(1)
            ! THE DELTA_D DIAGNOSTIC, and it is on because delta_d is pinned.
            !
            ! The child SUD ratio is a weighted average of
            ! percent_addicted_by_employment under two newborn distributions,
            ! one shifted down by the penalty and one not. It can therefore only
            ! move as far as THAT PROFILE IS STEEP: if the disorder rate is flat
            ! across productivity, no shift of the distribution changes the
            ! average and delta_d runs to its bound producing a ratio near one,
            ! which is what it does. Printing the profile beside the two
            ! distributions and the ratio they imply says which it is.
            write(*,*) "=== delta_d diagnostic ==="
            write(*,*) "percent_addicted_by_employment=", percent_addicted_by_employment(1,:)
            write(*,*) "mass with the disorder by node=", mass_by_employment(1,:)
            write(*,*) "population by node            =", total_mass_by_employment(1,:)
            ! THE FLOW, beside the stock. The stock above can rise with
            ! productivity because onset does, or because the disorder lasts
            ! longer up there, or because productivity drifts down after onset.
            ! Only the flow says which, and only the budget share says whether
            ! any force in the model tilts use against income.
            write(*,*) "onset hazard by node (flow)  =", onset_hazard_by_employment(1,:)
            write(*,*) "drug quantity by node        =", drug_quantity_by_employment(1,:)
            write(*,*) "consumption by node          =", clean_consumption_by_employment(1,:)
            write(*,*) "DRUG BUDGET SHARE by node    =", drug_quantity_by_employment(1,:)*&
                price_of_addictive_good/max(clean_consumption_by_employment(1,:),10.d0**(-12))
            write(*,*) "newborn prob, clean parent, median node =", newborn_employment_probability(:,(employment_grid_size+1)/2,0,1)
            write(*,*) "newborn prob, disordered, median node   =", newborn_employment_probability(:,(employment_grid_size+1)/2,1,1)
            write(*,*) "employment_grid               =", employment_grid(1,:)
            write(*,*) "penalty_child_addicted=", penalty_child_addicted
            child_sud_num_1=0
            child_sud_den_1=0
            do child_node_index_1=1,employment_grid_size
                child_sud_num_1=child_sud_num_1+&
                    sum(newborn_parent_share(:,1,1)*newborn_employment_probability(child_node_index_1,:,1,1))/max(sum(newborn_parent_share(:,1,1)),10.d0**(-14))*&
                    percent_addicted_by_employment(1,child_node_index_1)
                child_sud_den_1=child_sud_den_1+&
                    sum(newborn_parent_share(:,0,1)*newborn_employment_probability(child_node_index_1,:,0,1))/max(sum(newborn_parent_share(:,0,1)),10.d0**(-14))*&
                    percent_addicted_by_employment(1,child_node_index_1)
            end do
            write(*,*) "child SUD ratio implied=", child_sud_num_1/max(child_sud_den_1,10.d0**(-12)),&
                " against target", child_sud_ratio_data
            write(*,*) "=== end delta_d diagnostic ==="
